    @property
    def rdp_session_manager(self) -> RdpReconnectStateManager:
        """Return the engine-owned reconnectable RDP session manager."""

        return self._rdp_session_manager

    def execution_effect_audit_snapshot(self) -> ExecutionEffectAuditSnapshot:
        """Return bounded count-only command-effect audit totals."""

        return self._execution_effect_audit.snapshot()

    def advance_application_channel_watermark(self, cutoff: datetime) -> None:
        """Advance bounded application and network retention at the canonical frontier."""

        self._advance_application_channel_watermark(
            cutoff,
            advance_rdp_lifecycle=True,
            reject_terminal_closures=False,
        )

    def _advance_application_channel_watermark(
        self,
        cutoff: datetime,
        *,
        advance_rdp_lifecycle: bool,
        reject_terminal_closures: bool,
    ) -> None:
        """Advance protocol sidecars before their shared registry and network runtime."""

        canonical_cutoff = max(ensure_utc(cutoff), self._proxy_channel_window_start)
        if canonical_cutoff < self._proxy_channel_watermark:
            raise StateError(
                "Application-channel watermark cannot move backward: "
                f"{canonical_cutoff.isoformat()} < {self._proxy_channel_watermark.isoformat()}"
            )
        if advance_rdp_lifecycle:
            self.advance_rdp_session_retention_watermark(canonical_cutoff)
        self._advance_rdp_manager_watermark(canonical_cutoff)
        self._proxy_channel_manager.watermark(canonical_cutoff)
        self._http_channel_manager.watermark(canonical_cutoff)
        while True:
            ssh_page = self._ssh_channel_manager.watermark(canonical_cutoff)
            if reject_terminal_closures and ssh_page.closures:
                raise StateError(
                    "SSH manager produced unprojected closures at the terminal watermark"
                )
            if not ssh_page.has_more:
                break
        while True:
            smb_page = self._smb_channel_manager.watermark(canonical_cutoff)
            if reject_terminal_closures and smb_page.closures:
                raise StateError(
                    "SMB manager produced unprojected closures at the terminal watermark"
                )
            if not smb_page.has_more:
                break
        self._application_channel_registry.watermark(canonical_cutoff)
        while True:
            network_page = self._network_transaction_runtime.advance_watermark_page(
                canonical_cutoff,
                limit=_NETWORK_RUNTIME_WATERMARK_PAGE,
            )
            if not network_page.has_more:
                break
        self._proxy_channel_watermark = canonical_cutoff

    def advance_terminal_application_channel_watermark(self, cutoff: datetime) -> None:
        """Advance the shared terminal watermark after action journals are empty."""

        canonical_cutoff = max(ensure_utc(cutoff), self._proxy_channel_window_start)
        ssh = self._ssh_channel_manager.census()
        smb = self._smb_channel_manager.census()
        rdp = self._rdp_session_manager.census()
        terminal_protocol_owners = (
            ssh.open_sessions,
            ssh.active_operations,
            smb.open_sessions,
            smb.open_trees,
            smb.open_handles,
            rdp.connected_sessions,
            rdp.disconnected_sessions,
            rdp.active_operations,
            rdp.active_leases,
        )
        if any(terminal_protocol_owners):
            raise StateError(
                "Application protocol sidecars retain terminal owners before shared watermark: "
                f"ssh_sessions={ssh.open_sessions}, ssh_operations={ssh.active_operations}, "
                f"smb_sessions={smb.open_sessions}, smb_trees={smb.open_trees}, "
                f"smb_handles={smb.open_handles}, rdp_connected={rdp.connected_sessions}, "
                f"rdp_disconnected={rdp.disconnected_sessions}, "
                f"rdp_operations={rdp.active_operations}, rdp_leases={rdp.active_leases}"
            )
        self._advance_application_channel_watermark(
            canonical_cutoff,
            advance_rdp_lifecycle=False,
            reject_terminal_closures=True,
        )
        self._assert_terminal_application_channel_watermark(canonical_cutoff)

    def _assert_terminal_application_channel_watermark(self, cutoff: datetime) -> None:
        """Require exact shared-watermark postconditions after all sidecars advance."""

        proxy = self._proxy_channel_manager.census()
        http = self._http_channel_manager.census()
        ssh = self._ssh_channel_manager.census()
        rdp = self._rdp_session_manager.census()
        smb = self._smb_channel_manager.census()
        application = self._application_channel_registry.census()
        network = self._network_transaction_runtime.census()
        counts = (
            proxy.open_tunnel_views,
            proxy.prepared_admissions,
            proxy.claimed_admissions,
            proxy.reserved_channel_ids,
            proxy.reserved_affinities,
            proxy.reserved_origin_transport_ids,
            http.open_transport_views,
            ssh.open_sessions,
            ssh.active_operations,
            rdp.connected_sessions,
            rdp.disconnected_sessions,
            rdp.active_operations,
            rdp.active_leases,
            smb.open_sessions,
            smb.open_trees,
            smb.open_handles,
            application.open_channels,
            application.active_operations,
            application.prepared_admissions,
            application.claimed_admissions,
            application.reserved_channel_ids,
            application.reserved_transport_ids,
            application.reserved_operation_ids,
            network.open_preparations,
            network.prepared_transactions,
            network.claimed_transactions,
            network.reserved_points,
            network.preparation_fences,
            network.reserved_deadlines,
        )
        watermarks = (
            proxy.application.watermark,
            http.application.watermark,
            ssh.watermark,
            rdp.watermark,
            smb.application.watermark,
            application.watermark,
            network.watermark,
        )
        if any(counts) or any(watermark < cutoff for watermark in watermarks):
            raise StateError(
                "Shared application-channel terminal watermark did not reach its public "
                "postcondition"
            )

    def _process_termination_recorded(
        self,
        hostname: str,
        pid: int,
        start_time: datetime | None,
    ) -> bool:
        """Return whether a process instance termination was already generated."""
        if start_time is None:
            return any(
                terminated_host == hostname and terminated_pid == pid
                for terminated_host, terminated_pid, _ in self._terminated_process_keys
            )
        return (hostname, pid, start_time) in self._terminated_process_keys

    def _process_instance_key(
        self,
        hostname: str,
        pid: int,
        start_time: datetime | None = None,
    ) -> tuple[str, int, datetime | None]:
        """Return a PID-reuse-safe key for the current process instance."""
        if start_time is None:
            state_manager = getattr(self, "state_manager", None)
            process = (
                state_manager.get_process(hostname, pid) if state_manager is not None else None
            )
            if process is not None:
                start_time = process.start_time
        return hostname, pid, start_time

    def _process_cached_time(
        self,
        cache: dict[Any, datetime],
        latest: dict[tuple[str, int], tuple[datetime | None, datetime]],
        hostname: str,
        pid: int,
    ) -> datetime | None:
        """Read an instance timestamp with compatibility for direct unit fixtures."""
        instance_key = self._process_instance_key(hostname, pid)
        value = cache.get(instance_key)
        if value is not None:
            return value
        value = cache.get((hostname, pid))
        if value is not None:
            return value
        if instance_key[2] is not None:
            return None
        latest_value = latest.get((hostname, pid))
        return latest_value[1] if latest_value is not None else None

    def advance_process_state_watermark(self, cutoff: datetime) -> None:
        """Discard process-instance helper state sealed by the engine watermark."""
        normalized_cutoff = ensure_utc(cutoff)
        with self._failed_logon_attempt_lock:
            if self._failed_logon_attempt_pending:
                raise StateError(
                    "Failed-logon cadence watermark is fenced by an active primary publication"
                )
            self._advance_process_state_watermark_unfenced(normalized_cutoff)

    def _advance_process_state_watermark_unfenced(self, normalized_cutoff: datetime) -> None:
        """Advance process state while holding the failed-logon reservation fence."""

        active = {
            (process.system, process.pid, process.start_time)
            for process in self.state_manager.state.running_processes.values()
        }
        active_pids = {(hostname, pid) for hostname, pid, _start_time in active}
        self._terminated_process_times = {
            key: ended_at
            for key, ended_at in self._terminated_process_times.items()
            if ended_at >= normalized_cutoff
        }
        self._terminated_process_keys = set(self._terminated_process_times)
        self._process_source_create_times = {
            key: source_time
            for key, source_time in self._process_source_create_times.items()
            if key in active or source_time >= normalized_cutoff
        }
        self._process_source_terminate_times = {
            key: source_time
            for key, source_time in self._process_source_terminate_times.items()
            if source_time >= normalized_cutoff
        }
        self._process_source_create_latest = {
            key: value
            for key, value in self._process_source_create_latest.items()
            if (key[0], key[1], value[0]) in active or value[1] >= normalized_cutoff
        }
        self._process_source_terminate_latest = {
            key: value
            for key, value in self._process_source_terminate_latest.items()
            if value[1] >= normalized_cutoff
        }
        self._process_connection_hold_until = {
            key: hold_until
            for key, hold_until in self._process_connection_hold_until.items()
            if key in active or hold_until >= normalized_cutoff
        }
        self._session_process_source_terminate_times = {
            key: source_time
            for key, source_time in self._session_process_source_terminate_times.items()
            if source_time >= normalized_cutoff
        }
        active_module_prefixes = {
            (hostname, pid, start_time.isoformat()) for hostname, pid, start_time in active
        }
        self._loaded_modules_by_process = {
            module
            for module in self._loaded_modules_by_process
            if module[:3] in active_module_prefixes
        }
        self._foreground_process_finalizers.expire_before(
            normalized_cutoff.timestamp(),
            inclusive=True,
        )
        self._foreground_shell_next_time = {
            key: next_time
            for key, next_time in self._foreground_shell_next_time.items()
            if self.state_manager.get_process(key[0], key[3]) is not None
            or next_time >= normalized_cutoff
        }
        self._foreground_shell_release_groups = {
            key: group_id
            for key, group_id in self._foreground_shell_release_groups.items()
            if key in self._foreground_shell_next_time
        }
        systems_by_ip = getattr(self, "_ip_to_system", {})
        for responder_attribute in ("_ssh_responder_pids", "_smb_responder_pids"):
            responder_pids = getattr(self, responder_attribute, None)
            if responder_pids is None:
                continue
            retained_responders: dict[str, int] = {}
            for key, pid in responder_pids.items():
                target_ip = key.partition("->")[2].partition(":")[0]
                target_system = systems_by_ip.get(target_ip)
                if target_system is not None and (target_system.hostname, pid) in active_pids:
                    retained_responders[key] = pid
            setattr(self, responder_attribute, retained_responders)
        pid_aliases = getattr(self, "_ssh_pid_aliases", None)
        if pid_aliases is not None:
            self._ssh_pid_aliases = {
                key: mapped_pid
                for key, mapped_pid in pid_aliases.items()
                if (key[0], mapped_pid) in self.state_manager.state.running_processes
            }
        expired_failed_logons = self._failed_logon_attempt_times.advance_watermark(
            normalized_cutoff,
            limit=_NETWORK_RUNTIME_WATERMARK_PAGE,
        )
        if len(expired_failed_logons) == _NETWORK_RUNTIME_WATERMARK_PAGE:
            raise StateError(
                "Failed-logon cadence expiry reached its bounded 4,096-row watermark page; "
                "the modeled authentication rate exceeds the duration-stability gate"
            )
        expired_ssh_source_ports = self._ssh_source_ports.advance_watermark(
            normalized_cutoff,
            limit=_NETWORK_RUNTIME_WATERMARK_PAGE,
        )
        if len(expired_ssh_source_ports) == _NETWORK_RUNTIME_WATERMARK_PAGE:
            raise StateError(
                "SSH source-port expiry reached its bounded 4,096-row watermark page; "
                "the modeled SSH connection rate exceeds the duration-stability gate"
            )

    def finalize_terminal_runtime_state(self, cutoff: datetime) -> None:
        """Advance bounded process, lifecycle, and timing owners to one frontier."""

        canonical_cutoff = ensure_utc(cutoff)
        self.advance_process_state_watermark(canonical_cutoff)
        self._lifecycle_authority.advance_watermark(canonical_cutoff)
        self._lifecycle_authority.registry.advance_watermark(canonical_cutoff)
        self._source_timing_planner.advance_watermark(canonical_cutoff)

        authority = self._lifecycle_authority.census()
        registry = self._lifecycle_authority.registry.census()
        timing = self._source_timing_planner.census()
        if (
            authority.watermark is None
            or authority.watermark < canonical_cutoff
            or registry.watermark is None
            or registry.watermark < canonical_cutoff
            or timing.watermark is None
            or timing.watermark < canonical_cutoff
        ):
            raise StateError("Terminal lifecycle/runtime/timing cleanup missed its frontier")

    def _remember_process_connection_hold(
        self,
        *,
        system: System,
        pid: int,
        close_time: datetime | None,
    ) -> None:
        """Keep process lifecycle compatible with a process-owned transport interval."""
        self._remember_process_dependent_hold(
            system=system,
            pid=pid,
            required_until=close_time,
        )

    def _remember_process_dependent_hold(
        self,
        *,
        system: System,
        pid: int,
        required_until: datetime | None,
    ) -> None:
        """Keep a process alive through a canonical dependent event interval."""
        if pid <= 0 or required_until is None:
            return
        close_time = ensure_utc(required_until)
        end_plan = self.state_manager.process_session_end_plan(system.hostname, pid)
        if end_plan is not None and end_plan.is_authoritative:
            deadline = ensure_utc(end_plan.canonical_end)
            close_gap_ms = 100 + (
                _stable_seed(
                    "process_hold_before_authoritative_session_end:"
                    f"{system.hostname}:{pid}:{deadline.isoformat()}"
                )
                % 1401
            )
            latest_hold = deadline - timedelta(milliseconds=close_gap_ms)
            process = self.state_manager.get_process(system.hostname, pid)
            if (
                process is not None
                and process.last_activity_time is not None
                and latest_hold <= ensure_utc(process.last_activity_time)
            ):
                latest_hold = deadline - timedelta(milliseconds=1)
            close_time = min(close_time, latest_hold)
        key = self._process_instance_key(system.hostname, pid)
        previous = self._process_connection_hold_until.get(key)
        if previous is None or close_time > previous:
            self._process_connection_hold_until[key] = close_time
        self.state_manager.update_process_activity_time(system.hostname, pid, close_time)
        running = self.state_manager.get_process(system.hostname, pid)
        if running is not None and running.logon_id:
            self.state_manager.update_session_activity_time(running.logon_id, close_time)
        if (
            running is not None
            and _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(
                running.image,
                running.command_line,
            )
            and self._foreground_shell_key(
                system=system,
                username=running.username,
                logon_id=running.logon_id,
                parent_pid=running.parent_pid,
            )
            is not None
        ):
            self._remember_foreground_shell_available(
                system=system,
                username=running.username,
                logon_id=running.logon_id,
                parent_pid=running.parent_pid,
                termination_time=close_time,
                seed_text=running.command_line,
                concurrency_group_id=running.concurrency_group_id,
            )
        finalizer = self._foreground_process_finalizers.get(key)
        if finalizer is not None and ensure_utc(finalizer[4]) <= close_time:
            held_termination = self._held_process_termination_time(
                system=system,
                pid=pid,
                requested_time=finalizer[4],
            )
            self._remember_foreground_process_finalizer(
                system=system,
                user=self._user_model_for_username(finalizer[1]),
                pid=pid,
                process_name=finalizer[2],
                logon_id=finalizer[3],
                termination_time=held_termination,
            )

    def _held_process_termination_time(
        self,
        *,
        system: System,
        pid: int,
        requested_time: datetime,
    ) -> datetime:
        """Move process termination after any active process-owned transport hold."""
        hold_until = self._process_connection_hold_until.get(
            self._process_instance_key(system.hostname, pid)
        )
        if hold_until is None:
            return requested_time
        hold_until = ensure_utc(hold_until)
        requested_time = ensure_utc(requested_time)
        if requested_time > hold_until:
            return requested_time
        delay_rng = random.Random(
            _stable_seed(
                "process_terminate_after_connection_hold:"
                f"{system.hostname}:{pid}:{hold_until.isoformat()}"
            )
        )
        return hold_until + timedelta(seconds=delay_rng.uniform(1.0, 12.0))

    def _remember_foreground_process_finalizer(
        self,
        *,
        system: System,
        user: User,
        pid: int,
        process_name: str,
        logon_id: str,
        termination_time: datetime,
    ) -> None:
        """Track a bounded foreground process until its terminate event is observed."""
        key = self._process_instance_key(system.hostname, pid)
        termination_time = self._held_process_termination_time(
            system=system,
            pid=pid,
            requested_time=ensure_utc(termination_time),
        )
        self._foreground_process_finalizers[key] = (
            system,
            user.username,
            process_name,
            logon_id,
            termination_time,
        )
        running = self.state_manager.get_process(system.hostname, pid)
        if (
            running is not None
            and _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(
                running.image,
                running.command_line,
            )
            and self._foreground_shell_key(
                system=system,
                username=running.username,
                logon_id=running.logon_id,
                parent_pid=running.parent_pid,
            )
            is not None
        ):
            self._remember_foreground_shell_available(
                system=system,
                username=running.username,
                logon_id=running.logon_id,
                parent_pid=running.parent_pid,
                termination_time=termination_time,
                seed_text=running.command_line,
                concurrency_group_id=running.concurrency_group_id,
            )

    def foreground_process_termination_time(self, hostname: str, pid: int) -> datetime | None:
        """Return the canonical bounded-process deadline, when one is registered."""
        finalizer = self._foreground_process_finalizers.get(
            self._process_instance_key(hostname, pid)
        )
        return finalizer[4] if finalizer is not None else None

    def resolve_process_lifecycle_close_candidate(
        self,
        hostname: str,
        pid: int,
        close_at: datetime,
    ) -> datetime | None:
        """Resolve one advisory process close against its exact child frontier."""

        running = self.state_manager.get_process(hostname, pid)
        if running is None:
            raise StateError(
                f"Process close admission lost its live State identity: {hostname} pid={pid}"
            )
        lifecycle_process = self._lifecycle_authority.registry.get_process(running.ecar_object_id)
        if lifecycle_process is None and self._lifecycle_compatibility_fixture_mode:
            self._lifecycle_authority.ensure_process(hostname, pid)
            lifecycle_process = self._lifecycle_authority.registry.get_process(
                running.ecar_object_id
            )
        if (
            lifecycle_process is None
            or lifecycle_process.closed_at is not None
            or lifecycle_process.close_barrier is not None
            or lifecycle_process.closure_ticket is not None
            or lifecycle_process.identity.hostname != running.system
            or lifecycle_process.identity.pid != running.pid
            or lifecycle_process.identity.started_at != running.start_time
            or lifecycle_process.identity.image != running.image
        ):
            raise StateError(
                "Process close admission has no matching live lifecycle identity: "
                f"{hostname} pid={pid} object={running.ecar_object_id}"
            )
        if self._lifecycle_compatibility_fixture_mode:
            direct_children = tuple(
                child
                for child in self.state_manager.get_processes_on_system(hostname)
                if child.parent_pid == pid
            )
            for child in direct_children:
                self._lifecycle_authority.ensure_process(hostname, child.pid)
                child_lifecycle = self._lifecycle_authority.registry.get_process(
                    child.ecar_object_id
                )
                if (
                    child_lifecycle is None
                    or child_lifecycle.closed_at is not None
                    or child_lifecycle.identity.object_id != child.ecar_object_id
                    or child_lifecycle.identity.hostname != child.system
                    or child_lifecycle.identity.pid != child.pid
                    or child_lifecycle.identity.started_at != child.start_time
                    or child_lifecycle.identity.image != child.image
                    or child_lifecycle.identity.parent_object_id != running.ecar_object_id
                ):
                    raise StateError(
                        "Compatibility process close admission has no matching live child "
                        f"lifecycle identity: {hostname} pid={child.pid} "
                        f"object={child.ecar_object_id}"
                    )
        try:
            latest_closed_child = self._lifecycle_authority.process_child_close_deadline(
                hostname,
                pid,
            )
        except StateError as error:
            if self._lifecycle_authority.live_child_process_page_for_object(running.ecar_object_id):
                return None
            raise StateError(
                "Process close admission child frontier changed during resolution: "
                f"{hostname} pid={pid} object={running.ecar_object_id}"
            ) from error
        candidate = ensure_utc(close_at)
        if latest_closed_child is not None:
            candidate = max(
                candidate,
                ensure_utc(latest_closed_child) + timedelta(microseconds=1),
            )
        return candidate

    def finalize_foreground_process_lifetimes(self, end_time: datetime) -> None:
        """Close any tracked one-shot foreground shell processes still running.

        Most shell telemetry emits its terminate row immediately after the create row. This
        finalization pass is a safety net for slice-end and session-interleaving edge cases
        where a bounded foreground command stayed active in state despite its expected
        lifetime being inside the visible window.
        """
        known_users = getattr(self, "_users_by_username", {})
        window_end = ensure_utc(end_time)
        due_finalizers = self._foreground_process_finalizers.expire_before(
            window_end.timestamp(),
            inclusive=True,
        )

        def process_depth(
            finalizer: tuple[
                tuple[str, int, datetime | None],
                tuple[System, str, str, str, datetime],
            ],
        ) -> int:
            key, _value = finalizer
            running = self.state_manager.get_process(key[0], key[1])
            depth = 0
            seen: set[tuple[str, int]] = set()
            while running is not None and (running.system, running.pid) not in seen:
                seen.add((running.system, running.pid))
                if running.parent_pid <= 0:
                    break
                parent = self.state_manager.get_process(running.system, running.parent_pid)
                if parent is None:
                    break
                depth += 1
                running = parent
            return depth

        due_finalizers.sort(key=process_depth, reverse=True)
        for key, (
            system,
            username,
            process_name,
            logon_id,
            termination_time,
        ) in due_finalizers:
            running = self.state_manager.get_process(system.hostname, key[1])
            if running is None:
                continue
            if running.start_time != key[2]:
                continue
            if self._process_termination_recorded(system.hostname, key[1], running.start_time):
                continue
            process_user = known_users.get(username) or User(
                username=username,
                full_name=username,
                email=f"{username}@example.local",
            )
            resolved_termination_time = self.resolve_process_lifecycle_close_candidate(
                system.hostname,
                key[1],
                termination_time,
            )
            if resolved_termination_time is None:
                if self.state_manager.get_session(running.logon_id or logon_id) is None:
                    self._remember_foreground_process_finalizer(
                        system=system,
                        user=process_user,
                        pid=key[1],
                        process_name=running.image or process_name,
                        logon_id=running.logon_id or logon_id,
                        termination_time=window_end + timedelta(microseconds=1),
                    )
                continue
            session = self.state_manager.get_session(running.logon_id or logon_id)
            session_deadlines = [
                ensure_utc(deadline)
                for deadline in (
                    (
                        session.end_plan.canonical_end
                        if session is not None
                        and session.end_plan is not None
                        and session.end_plan.is_authoritative
                        else None
                    ),
                    session.network_close_time if session is not None else None,
                )
                if deadline is not None
            ]
            if session_deadlines and resolved_termination_time >= min(session_deadlines):
                continue
            if resolved_termination_time > window_end:
                self._remember_foreground_process_finalizer(
                    system=system,
                    user=process_user,
                    pid=key[1],
                    process_name=running.image or process_name,
                    logon_id=running.logon_id or logon_id,
                    termination_time=resolved_termination_time,
                )
                continue
            self.generate_process_termination(
                user=process_user,
                system=system,
                time=resolved_termination_time,
                pid=key[1],
                process_name=running.image or process_name,
                logon_id=running.logon_id or logon_id,
            )

    def _defer_ssh_session_close(
        self,
        bundle_or_continuation: Any,
        state: Any = None,
        event: OccurrenceBuilder | None = None,
        auth_state: Any = None,
    ) -> None:
        """Queue an SSH bundle closure until all dependent activity is generated."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        if type(bundle_or_continuation) is _SshCloseContinuation:
            if state is not None or event is not None or auth_state is not None:
                raise TypeError("Exact SSH close continuation cannot mix legacy close fields")
            self._recover_exact_ssh_close_continuation_no_fail(bundle_or_continuation)
            return
        if state is None or event is None or auth_state is None:
            raise TypeError("Legacy SSH close requires bundle, state, event, and auth state")
        with self._ssh_close_journal_lock:
            self._pending_ssh_session_closures.append(
                (
                    ensure_utc(state.close_time),
                    bundle_or_continuation,
                    state,
                    event,
                    auth_state,
                )
            )

    def _reserve_exact_rdp_lifecycle_continuation(self, prepared: Any) -> None:
        """Reserve bounded RDP terminal capacity before canonical publication."""

        from evidenceforge.generation.actions.rdp_session import (
            _PreparedRdpLifecycleContinuation,
        )

        if type(prepared) is not _PreparedRdpLifecycleContinuation:
            raise TypeError("Exact RDP lifecycle reservation requires its built-in payload")
        with self._rdp_lifecycle_journal_lock:
            retained = self._prepared_rdp_lifecycle_continuations.get(prepared.continuation_id)
            if retained is not None:
                if retained is not prepared:
                    raise StateError("Exact RDP lifecycle reservation identity was reused")
                return
            if prepared.continuation_id in self._pending_rdp_lifecycle_continuations:
                raise StateError("Exact RDP lifecycle continuation is already installed")
            if (
                len(self._prepared_rdp_lifecycle_continuations)
                + len(self._pending_rdp_lifecycle_continuations)
                >= self._rdp_lifecycle_journal_capacity
            ):
                raise StateError(
                    "Exact RDP lifecycle journal capacity is exhausted before publication"
                )
            self._prepared_rdp_lifecycle_continuations[prepared.continuation_id] = prepared

    def _cancel_exact_rdp_lifecycle_continuation_reservation(self, prepared: Any) -> None:
        """Idempotently release one uncommitted RDP terminal reservation."""

        from evidenceforge.generation.actions.rdp_session import (
            _PreparedRdpLifecycleContinuation,
        )

        if type(prepared) is not _PreparedRdpLifecycleContinuation:
            raise TypeError("Exact RDP lifecycle cancellation requires its built-in payload")
        with self._rdp_lifecycle_journal_lock:
            retained = self._prepared_rdp_lifecycle_continuations.get(prepared.continuation_id)
            if retained is None:
                return
            if retained is not prepared:
                raise StateError("Exact RDP lifecycle cancellation crossed its reservation")
            self._prepared_rdp_lifecycle_continuations.pop(prepared.continuation_id)

    def _recover_exact_rdp_lifecycle_continuation_no_fail(self, continuation: Any) -> None:
        """Idempotently install one committed RDP generation in the bounded journal."""

        from evidenceforge.generation.actions.rdp_session import (
            _RdpLifecycleContinuation,
        )

        if type(continuation) is not _RdpLifecycleContinuation:
            raise TypeError("Exact RDP lifecycle journal requires its built-in continuation")
        canonical = continuation.prepared.bind()
        if (
            canonical.prepared is not continuation.prepared
            or canonical.transaction is not continuation.transaction
            or canonical.session != continuation.session
        ):
            raise StateError("Exact RDP lifecycle continuation is copied or unauthenticated")
        with self._rdp_lifecycle_journal_lock:
            existing = self._pending_rdp_lifecycle_continuations.get(continuation.continuation_id)
            if existing is not None:
                if (
                    existing.continuation.prepared is not continuation.prepared
                    or existing.continuation.transaction is not continuation.transaction
                ):
                    raise StateError("Exact RDP lifecycle continuation identity was reused")
                return
            prepared = self._prepared_rdp_lifecycle_continuations.get(continuation.continuation_id)
            if prepared is not continuation.prepared:
                raise StateError("Exact RDP lifecycle continuation has no reserved owner")
            logical_id = continuation.session.identity.logical_session_id
            prior_entries = tuple(self._pending_rdp_lifecycle_continuations.items())
            for prior_id, prior_entry in prior_entries:
                prior = prior_entry.continuation
                if (
                    prior.session.identity.logical_session_id != logical_id
                    or prior.session.generation.ordinal >= continuation.session.generation.ordinal
                ):
                    continue
                if not (prior_entry.disconnect_published and prior_entry.source_terminated):
                    raise StateError(
                        "Exact RDP reconnect cannot supersede unfinished disconnect work"
                    )
                self._pending_rdp_lifecycle_continuations.pop(prior_id)
            self._pending_rdp_lifecycle_continuations[continuation.continuation_id] = (
                _RdpLifecycleJournalEntry(continuation)
            )
            self._prepared_rdp_lifecycle_continuations.pop(continuation.continuation_id)

    def _rdp_bundle_for_continuation(self, continuation: Any) -> RdpSessionActionBundle:
        """Materialize the exact RDP terminal publisher from frozen journal facts."""

        prepared = continuation.prepared
        return RdpSessionActionBundle(
            self,
            RdpSessionRequest(
                user=prepared.user,
                target_system=prepared.target_system,
                time=continuation.transaction.started_at,
                source_ip=continuation.transaction.src_ip,
                source_system=prepared.source_system,
                source_pid=(prepared.source_identity.pid if prepared.source_identity else -1),
                source_port=continuation.transaction.src_port,
                logon_id=prepared.session_identity.logon_id,
                preserve_explicit_source=True,
                source=prepared.source_tag,
            ),
        )

    def _publish_exact_rdp_disconnect(
        self,
        continuation: Any,
        source_termination_at: datetime,
    ) -> None:
        """Publish one exact state-neutral Security 4779/eCAR transition."""

        from evidenceforge.events.contracts import EventKind

        phase = "disconnect"
        prepared = continuation.prepared
        if prepared.recover_terminal_projection(phase, self.dispatcher):
            return
        identity = prepared.session_identity
        transaction = continuation.transaction
        canonical_source_termination = ensure_utc(source_termination_at)
        if canonical_source_termination != continuation.disconnect_at:
            raise StateError("Exact RDP source termination changed its transport-close anchor")
        disconnect_event_at = canonical_source_termination + timedelta(microseconds=1)
        event = OccurrenceBuilder(
            timestamp=disconnect_event_at,
            event_type=EventKind.RDP_DISCONNECT,
            dst_host=self._build_host_context(prepared.target_system),
            auth=AuthContext(
                username=identity.principal,
                user_sid=self._get_sid(identity.principal),
                logon_id=identity.logon_id,
                session_id=identity.session_id,
                logon_type=10,
                source_ip=transaction.src_ip,
                source_port=transaction.src_port,
                session_kind="rdp",
                auth_protocol="rdp",
            ),
            identity_plan=EventIdentityPlan(subject=identity, session=identity),
            lifecycle=ActionLifecycleContext(
                group_id=identity.lifecycle_group_id,
                canonical_start=identity.started_at,
                phase="dependent",
                parent_group_id=identity.parent_lifecycle_group_id or None,
            ),
        )
        carrier = None
        timing_preparation = None
        try:
            with self.dispatcher.source_timing_planner.prepared_planning() as timing_preparation:
                carrier = self.dispatcher.prepare_action_cohort_projection(
                    event,
                    source_timing_preparation=timing_preparation,
                )
            occurrence_id = self.dispatcher.action_cohort_projection_occurrence(
                carrier
            ).occurrence_id
        except BaseException as primary:
            if carrier is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "RDP disconnect projection",
                    lambda: self.dispatcher.cancel_prepared_action_cohort_projection(carrier),
                )
            self._reconcile_generator_cleanup(
                primary,
                "RDP disconnect orphan projection",
                self.dispatcher.prune_prepared_action_cohort_projections,
            )
            if timing_preparation is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "RDP disconnect source timing",
                    timing_preparation.cancel,
                )
            raise

        try:
            result = self.dispatcher.publish_state_neutral_exact_projection(carrier)
        except BaseException as error:
            attributes = object.__getattribute__(error, "__dict__")
            receipt = (
                attributes.get("state_neutral_projection_receipt")
                if type(attributes) is dict
                else None
            )
            attached_result = (
                attributes.get("state_neutral_projection_result")
                if type(attributes) is dict
                else None
            )
            result_type = getattr(
                dispatcher_types,
                "StateNeutralProjectionPublicationResult",
                None,
            )
            authentic = bool(
                receipt is not None
                and result_type is not None
                and type(attached_result) is result_type
                and attached_result.receipt is receipt
                and self.dispatcher.authenticates_state_neutral_projection_publication_receipt(
                    receipt
                )
                and receipt.occurrence_ids == (occurrence_id,)
            )
            if not authentic:
                self._reconcile_generator_cleanup(
                    error,
                    "RDP disconnect projection",
                    lambda: self.dispatcher.cancel_prepared_action_cohort_projection(carrier),
                )
                self._reconcile_generator_cleanup(
                    error,
                    "RDP disconnect orphan projection",
                    self.dispatcher.prune_prepared_action_cohort_projections,
                )
                raise
            prepared.projection_ledger.retain_state_neutral(
                phase,
                receipt=receipt,
                result=attached_result,
                occurrence_id=occurrence_id,
            )
            raise

        projection = result.projection
        if (
            not self.dispatcher.authenticates_state_neutral_projection_publication_receipt(
                result.receipt
            )
            or result.receipt.occurrence_ids != (occurrence_id,)
            or type(projection) is not ActionCohortProjectionOutcome
            or projection.occurrence_id != occurrence_id
            or projection.status != "succeeded"
            or projection.error is not None
        ):
            raise StateError("Exact RDP disconnect returned invalid terminal proof")
        prepared.mark_terminal_projection_complete(phase)

    @staticmethod
    def _rdp_snapshot_matches_generation(continuation: Any, snapshot: Any) -> bool:
        """Return whether a public manager snapshot is the journal's exact generation."""

        expected = continuation.session
        return bool(
            snapshot is not None
            and snapshot.identity == expected.identity
            and snapshot.generation.ordinal == expected.generation.ordinal
            and snapshot.generation.channel_id == expected.generation.channel_id
            and snapshot.generation.binding.transport_id == expected.generation.binding.transport_id
        )

    @staticmethod
    def _rdp_source_projection_proof_complete(
        entry: _RdpLifecycleJournalEntry,
        source_identity: ProcessIdentity | None,
    ) -> bool:
        """Require the exact no-source, visible-source, or suppressed-source journal shape."""

        disposition = entry.source_projection_disposition
        frontiers = entry.source_projection_frontiers
        if source_identity is None:
            return disposition is None and frontiers == ()
        if disposition is ActionCohortProjectionDisposition.EXACT_WARMUP_SUPPRESSED:
            return frontiers == ()
        return bool(
            disposition is ActionCohortProjectionDisposition.SOURCE_FRONTIERS_REQUIRED and frontiers
        )

    def _disconnect_exact_rdp_entry(self, entry: _RdpLifecycleJournalEntry) -> None:
        """Disconnect one exact generation, project 4779, and close its mstsc owner."""

        from evidenceforge.events.rdp import RdpSessionState

        continuation = entry.continuation
        logical_id = continuation.session.identity.logical_session_id
        snapshot = self._rdp_session_manager.get(logical_id)
        if not self._rdp_snapshot_matches_generation(continuation, snapshot):
            raise StateError("Exact RDP disconnect journal lost its current generation")
        if snapshot.state is RdpSessionState.CONNECTED:
            try:
                snapshot = self._rdp_session_manager.disconnect(
                    logical_id,
                    channel_id=continuation.session.generation.channel_id,
                    disconnected_at=continuation.disconnect_at,
                )
            except BaseException:
                recovered = self._rdp_session_manager.get(logical_id)
                if (
                    not self._rdp_snapshot_matches_generation(continuation, recovered)
                    or recovered.state is not RdpSessionState.DISCONNECTED
                    or recovered.generation.disconnected_at != continuation.disconnect_at
                ):
                    raise
                snapshot = recovered
        if snapshot.state is RdpSessionState.LOGGED_OUT:
            if (
                not entry.manager_logged_out
                or not entry.disconnect_published
                or not entry.source_terminated
                or entry.source_termination_at is None
                or not self._rdp_source_projection_proof_complete(
                    entry,
                    continuation.prepared.source_identity,
                )
                or snapshot.generation.disconnected_at != continuation.disconnect_at
            ):
                raise StateError("Exact RDP disconnect retry crossed its terminal journal state")
            return
        if (
            snapshot.state is not RdpSessionState.DISCONNECTED
            or snapshot.generation.disconnected_at != continuation.disconnect_at
        ):
            raise StateError("Exact RDP manager returned a different disconnect transition")
        if not entry.source_terminated:
            source_identity = continuation.prepared.source_identity
            source_termination_at = continuation.disconnect_at
            source_projection_frontiers: tuple[tuple[str, int, datetime], ...] = ()
            source_projection_disposition: ActionCohortProjectionDisposition | None = None
            if source_identity is not None:
                timing_proof = self._rdp_bundle_for_continuation(
                    continuation
                ).terminate_exact_rdp_process(
                    continuation,
                    source_identity,
                    continuation.disconnect_at,
                )
                source_termination_at = timing_proof.canonical_time
                source_projection_frontiers = timing_proof.source_frontiers
                source_projection_disposition = timing_proof.disposition
            if ensure_utc(source_termination_at) != continuation.disconnect_at:
                raise StateError("Exact RDP source termination does not match transport close")
            entry.source_termination_at = ensure_utc(source_termination_at)
            entry.source_projection_frontiers = source_projection_frontiers
            entry.source_projection_disposition = source_projection_disposition
            if not self._rdp_source_projection_proof_complete(entry, source_identity):
                raise StateError("Exact RDP source termination lost its projection proof")
            entry.source_terminated = True
        if entry.source_termination_at is None:
            raise StateError("Exact RDP disconnect lost its canonical source termination")
        if entry.source_termination_at != continuation.disconnect_at:
            raise StateError("Exact RDP disconnect changed its canonical source termination")
        if not self._rdp_source_projection_proof_complete(
            entry,
            continuation.prepared.source_identity,
        ):
            raise StateError("Exact RDP disconnect lost its source projection proof")
        if not entry.disconnect_published:
            self._publish_exact_rdp_disconnect(
                continuation,
                entry.source_termination_at,
            )
            entry.disconnect_published = True

    def _plan_exact_rdp_target_terminations(
        self,
        entry: _RdpLifecycleJournalEntry,
        logout_time: datetime,
    ) -> tuple[tuple[ProcessIdentity, datetime], ...]:
        """Freeze children-first target process closes inside the logout window."""

        continuation = entry.continuation
        identity = continuation.prepared.session_identity
        active_session = self.state_manager.get_session(identity.logon_id)
        if active_session is None:
            raise StateError("Exact RDP logout lost its live State session")
        processes = self.state_manager.get_processes_for_session(
            identity.logon_id,
            identity.hostname,
        )
        if active_session.session_winlogon_pid is not None:
            winlogon = self.state_manager.get_process(
                identity.hostname,
                active_session.session_winlogon_pid,
            )
            if winlogon is not None and all(item.pid != winlogon.pid for item in processes):
                processes.append(winlogon)
        by_pid = {process.pid: process for process in processes}

        def process_depth(pid: int) -> int:
            depth = 0
            seen: set[int] = set()
            current = by_pid.get(pid)
            while current is not None and current.pid not in seen:
                seen.add(current.pid)
                parent = by_pid.get(current.parent_pid)
                if parent is None:
                    break
                depth += 1
                current = parent
            return depth

        processes.sort(
            key=lambda process: (process_depth(process.pid), process.start_time, process.pid),
            reverse=True,
        )
        disconnect_at = continuation.disconnect_at
        available = logout_time - disconnect_at
        if available <= timedelta(0):
            raise StateError("Exact RDP logout has no terminal process interval")
        step = available / max(2, len(processes) + 1)
        planned: list[tuple[ProcessIdentity, datetime]] = []
        prior = disconnect_at
        for ordinal, process in enumerate(processes, start=1):
            process_identity = self.state_manager.get_process_identity(
                identity.hostname,
                process.pid,
            )
            if process_identity is None or process_identity.object_id != process.ecar_object_id:
                raise StateError("Exact RDP logout lost a target process identity")
            minimum = max(
                disconnect_at,
                ensure_utc(process.start_time),
                ensure_utc(process.last_activity_time or process.start_time),
                prior,
            )
            terminate_at = max(disconnect_at + step * ordinal, minimum)
            if terminate_at >= logout_time:
                raise StateError("Exact RDP target process cannot terminate before logout")
            planned.append((process_identity, terminate_at))
            prior = terminate_at + timedelta(microseconds=1)
        return tuple(planned)

    def _logout_exact_rdp_entry(
        self,
        entry: _RdpLifecycleJournalEntry,
        logout_time: datetime,
    ) -> None:
        """Terminalize one disconnected RDP logical session and acknowledge its journal."""

        from evidenceforge.events.rdp import RdpSessionState

        continuation = entry.continuation
        logical_id = continuation.session.identity.logical_session_id
        snapshot = self._rdp_session_manager.get(logical_id)
        if not self._rdp_snapshot_matches_generation(continuation, snapshot):
            raise StateError("Exact RDP logout journal lost its disconnected generation")
        if entry.target_terminations is None:
            entry.target_terminations = self._plan_exact_rdp_target_terminations(
                entry,
                logout_time,
            )
        if not entry.manager_logged_out:
            try:
                snapshot = self._rdp_session_manager.logout(
                    logical_id,
                    logged_out_at=logout_time,
                )
            except BaseException:
                recovered = self._rdp_session_manager.get(logical_id)
                if (
                    not self._rdp_snapshot_matches_generation(continuation, recovered)
                    or recovered.state is not RdpSessionState.LOGGED_OUT
                    or recovered.logged_out_at != logout_time
                ):
                    raise
                snapshot = recovered
            if (
                snapshot.state is not RdpSessionState.LOGGED_OUT
                or snapshot.logged_out_at != logout_time
            ):
                raise StateError("Exact RDP manager returned a different logout transition")
            entry.manager_logged_out = True
        bundle = self._rdp_bundle_for_continuation(continuation)
        for process_identity, terminate_at in entry.target_terminations:
            bundle.terminate_exact_rdp_process(
                continuation,
                process_identity,
                terminate_at,
            )
        if not entry.logout_published:
            bundle.logout_exact_rdp_session(continuation, logout_time)
            entry.logout_published = True
        if (
            self.state_manager.get_session(continuation.prepared.session_identity.logon_id)
            is not None
        ):
            raise StateError("Exact RDP logout returned before State terminalization")

    def advance_rdp_session_lifecycle_watermark(self, cutoff: datetime) -> None:
        """Drain due RDP disconnect/logout work before advancing shared application state."""

        canonical_cutoff = ensure_utc(cutoff)
        if canonical_cutoff < self._rdp_lifecycle_watermark:
            raise StateError("RDP lifecycle watermark cannot move backward")
        with self._rdp_lifecycle_journal_lock:
            pending = sorted(
                tuple(self._pending_rdp_lifecycle_continuations.values()),
                key=lambda entry: (
                    entry.continuation.disconnect_at,
                    entry.continuation.continuation_id,
                ),
            )
        for entry in pending:
            continuation = entry.continuation
            if continuation.disconnect_at > canonical_cutoff:
                continue
            self._disconnect_exact_rdp_entry(entry)
            snapshot = self._rdp_session_manager.get(
                continuation.session.identity.logical_session_id
            )
            reconnect_deadline = snapshot.reconnect_deadline if snapshot is not None else None
            logout_time = min(
                reconnect_deadline or continuation.prepared.hard_deadline,
                continuation.prepared.hard_deadline,
            )
            if logout_time > canonical_cutoff:
                continue
            self._logout_exact_rdp_entry(entry, logout_time)
            with self._rdp_lifecycle_journal_lock:
                installed = self._pending_rdp_lifecycle_continuations.get(
                    continuation.continuation_id
                )
                if installed is not entry:
                    raise StateError("Exact RDP lifecycle entry changed before acknowledgement")
                self._pending_rdp_lifecycle_continuations.pop(continuation.continuation_id)
        self._rdp_lifecycle_watermark = canonical_cutoff

    def advance_rdp_session_retention_watermark(self, cutoff: datetime) -> None:
        """Advance shared retention without reversing the RDP action frontier."""

        canonical_cutoff = ensure_utc(cutoff)
        lifecycle_frontier = self._rdp_session_lifecycle_frontier()
        if canonical_cutoff < lifecycle_frontier:
            return
        self.advance_rdp_session_lifecycle_watermark(canonical_cutoff)

    def _rdp_session_lifecycle_frontier(self) -> datetime:
        """Return the exact committed RDP lifecycle scheduling frontier."""

        with self._rdp_lifecycle_journal_lock:
            return self._rdp_lifecycle_watermark

    def rdp_lifecycle_journal_census(self) -> RdpLifecycleJournalCensus:
        """Return bounded counts for prepared and installed RDP lifecycle work."""

        with self._rdp_lifecycle_journal_lock:
            pending = tuple(self._pending_rdp_lifecycle_continuations.values())
            return RdpLifecycleJournalCensus(
                prepared_reservations=len(self._prepared_rdp_lifecycle_continuations),
                pending_generations=len(pending),
                disconnected_generations=sum(
                    entry.disconnect_published and entry.source_terminated for entry in pending
                ),
                capacity=self._rdp_lifecycle_journal_capacity,
            )

    def _rdp_reconnect_source_frontier(self, logon_id: str) -> datetime | None:
        """Return the prior committed mstsc source-close observation for reconnect timing."""

        session_identity = self.state_manager.get_session_identity(logon_id)
        if session_identity is None:
            return None
        with self._rdp_lifecycle_journal_lock:
            entries = tuple(self._pending_rdp_lifecycle_continuations.values())
        frontiers = [
            frontier
            for entry in entries
            if entry.continuation.session.identity.logical_session_id == session_identity.object_id
            and entry.continuation.prepared.source_identity is not None
            for frontier in (
                self.process_source_terminate_time(
                    entry.continuation.prepared.source_identity.hostname,
                    entry.continuation.prepared.source_identity.pid,
                ),
            )
            if frontier is not None
        ]
        return max(frontiers) if frontiers else None

    def assert_rdp_session_lifecycles_drained(self) -> None:
        """Reject sink shutdown while exact RDP terminal work remains."""

        census = self.rdp_lifecycle_journal_census()
        if census.prepared_reservations or census.pending_generations:
            raise StateError(
                "RDP lifecycle journal is not drained: "
                f"prepared={census.prepared_reservations}, "
                f"pending={census.pending_generations}, "
                f"disconnected={census.disconnected_generations}"
            )

    def _advance_rdp_manager_watermark(self, cutoff: datetime) -> None:
        """Advance the RDP sidecar only after its exact projection journal."""

        while True:
            page = self._rdp_session_manager.watermark(cutoff)
            if page.closures:
                raise StateError(
                    "RDP manager produced unprojected lifecycle closures after journal drain"
                )
            if not page.has_more:
                return

    def finalize_rdp_session_lifecycles(self, end_time: datetime) -> None:
        """Drain every due exact RDP generation while source sinks remain open."""

        window_end = ensure_utc(end_time)
        self.advance_rdp_session_lifecycle_watermark(window_end)
        self._advance_rdp_manager_watermark(window_end)
        self.assert_rdp_session_lifecycles_drained()

    def _reserve_exact_ssh_close_continuation(self, prepared: Any) -> None:
        """Reserve bounded terminal-journal capacity before canonical mutation."""

        from evidenceforge.generation.actions.ssh_session import (
            _PreparedSshCloseContinuation,
            _SshCloseContinuation,
        )

        if type(prepared) is not _PreparedSshCloseContinuation:
            raise TypeError("Exact SSH close reservation requires its built-in payload")
        continuation_id = prepared.plan.continuation_id
        with self._ssh_close_journal_lock:
            retained = self._prepared_ssh_close_continuations.get(continuation_id)
            if retained is not None:
                if retained is not prepared:
                    raise StateError("Exact SSH close reservation identity was reused")
                return
            for existing in self._pending_ssh_session_closures:
                if (
                    type(existing) is _SshCloseContinuation
                    and existing.continuation_id == continuation_id
                ):
                    raise StateError("Exact SSH close reservation is already installed")
            exact_pending = sum(
                type(existing) is _SshCloseContinuation
                for existing in self._pending_ssh_session_closures
            )
            if (
                len(self._prepared_ssh_close_continuations) + exact_pending
                >= self._ssh_close_journal_capacity
            ):
                raise StateError(
                    "Exact SSH close journal capacity is exhausted before session publication"
                )
            self._prepared_ssh_close_continuations[continuation_id] = prepared

    def _cancel_exact_ssh_close_continuation_reservation(self, prepared: Any) -> None:
        """Idempotently release one exact reservation after precommit rejection."""

        from evidenceforge.generation.actions.ssh_session import _PreparedSshCloseContinuation

        if type(prepared) is not _PreparedSshCloseContinuation:
            raise TypeError("Exact SSH close cancellation requires its built-in payload")
        continuation_id = prepared.plan.continuation_id
        with self._ssh_close_journal_lock:
            retained = self._prepared_ssh_close_continuations.get(continuation_id)
            if retained is None:
                return
            if retained is not prepared:
                raise StateError("Exact SSH close cancellation crossed its reservation owner")
            self._prepared_ssh_close_continuations.pop(continuation_id)

    def _recover_exact_ssh_close_continuation_no_fail(self, continuation: Any) -> None:
        """Idempotently install one already-validated exact SSH close continuation."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        if type(continuation) is not _SshCloseContinuation:
            raise TypeError("Exact SSH close journal requires its built-in continuation")
        if not continuation.prepared.authenticates_bound(continuation):
            raise StateError("Exact SSH close continuation is a copied or foreign carrier")
        with self._ssh_close_journal_lock:
            for existing in self._pending_ssh_session_closures:
                if type(existing) is not _SshCloseContinuation:
                    continue
                if existing.continuation_id != continuation.continuation_id:
                    continue
                if not existing.authenticates(continuation):
                    raise StateError("Exact SSH close continuation identity was reused")
                return
            prepared = self._prepared_ssh_close_continuations.get(continuation.continuation_id)
            if prepared is None:
                raise StateError("Exact SSH close continuation has no reserved journal owner")
            if prepared is not continuation.prepared:
                raise StateError("Exact SSH close continuation crossed its reservation owner")
            # Append before consuming the reservation. If allocation itself
            # fails, the same exact payload remains retryable.
            self._pending_ssh_session_closures.append(continuation)
            self._prepared_ssh_close_continuations.pop(continuation.continuation_id)

    def _installed_exact_ssh_close_continuation(self, continuation: Any) -> Any:
        """Return the canonical installed entry authenticated by exact identities."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        if type(continuation) is not _SshCloseContinuation:
            raise TypeError("Exact SSH close execution requires its built-in continuation")
        if not continuation.prepared.authenticates_bound(continuation):
            raise StateError("Exact SSH close execution received a copied carrier")
        with self._ssh_close_journal_lock:
            for existing in self._pending_ssh_session_closures:
                if type(existing) is not _SshCloseContinuation:
                    continue
                if existing.continuation_id != continuation.continuation_id:
                    continue
                if not existing.authenticates(continuation):
                    raise StateError("Exact SSH close continuation changed after installation")
                return existing
        raise StateError("Exact SSH close continuation was not durably installed")

    def _execute_exact_ssh_close_continuation(self, continuation: Any) -> None:
        """Execute one authenticated terminal continuation outside owner locks."""

        continuation = self._installed_exact_ssh_close_continuation(continuation)
        state = continuation.materialize_state()
        bundle = continuation.materialize_bundle(self)
        bundle._terminate_source_ssh_client_process(
            state,
            continuation=continuation,
        )
        bundle._dispatch_linux_session_close_lifecycle(
            state,
            continuation.materialize_event(state),
            continuation.plan.auth_state,
            continuation=continuation,
        )
        continuation.prepared.require_projection_owner(self)
        continuation.prepared.require_application_session_retired()
        self._release_session_retention_state(
            hostname=continuation.plan.target_system.hostname,
            username=continuation.plan.username,
            logon_id=continuation.plan.logon_id,
        )

    def _finalize_exact_ssh_close_continuation(self, continuation: Any) -> None:
        """Execute and acknowledge one installed immediate SSH close continuation."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        if type(continuation) is not _SshCloseContinuation:
            raise TypeError("Exact SSH close finalization requires its built-in continuation")
        installed = self._installed_exact_ssh_close_continuation(continuation)
        self._execute_exact_ssh_close_continuation(installed)
        with self._ssh_close_journal_lock:
            for index, existing in enumerate(self._pending_ssh_session_closures):
                if existing is installed:
                    del self._pending_ssh_session_closures[index]
                    return
        raise StateError("Exact SSH close continuation disappeared before acknowledgement")

    def finalize_ssh_session_lifecycles(self, end_time: datetime) -> None:
        """Dispatch due action-owned SSH closures after dependent generation completes."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        window_end = ensure_utc(end_time)
        with self._ssh_close_journal_lock:
            pending = sorted(
                tuple(self._pending_ssh_session_closures),
                key=lambda item: (
                    item.close_time if type(item) is _SshCloseContinuation else item[0]
                ),
            )
        for item in pending:
            if type(item) is _SshCloseContinuation:
                if item.close_time > window_end:
                    continue
                self._execute_exact_ssh_close_continuation(item)
            else:
                close_time, bundle, state, event, auth_state = item
                if close_time > window_end:
                    continue
                if state.logon_id and self.state_manager.get_session(state.logon_id) is not None:
                    bundle._terminate_source_ssh_client_process(state)
                    bundle._dispatch_linux_session_close_lifecycle(state, event, auth_state)
            with self._ssh_close_journal_lock:
                for index, existing in enumerate(self._pending_ssh_session_closures):
                    if existing is item:
                        del self._pending_ssh_session_closures[index]
                        break

    def ssh_close_journal_census(self) -> SshCloseJournalCensus:
        """Return bounded counts for prepared and installed SSH close work."""

        from evidenceforge.generation.actions.ssh_session import _SshCloseContinuation

        with self._ssh_close_journal_lock:
            exact_pending = sum(
                type(existing) is _SshCloseContinuation
                for existing in self._pending_ssh_session_closures
            )
            return SshCloseJournalCensus(
                prepared_reservations=len(self._prepared_ssh_close_continuations),
                exact_pending=exact_pending,
                legacy_pending=len(self._pending_ssh_session_closures) - exact_pending,
                capacity=self._ssh_close_journal_capacity,
            )

    def assert_ssh_session_lifecycles_drained(self) -> None:
        """Reject sink shutdown while any prepared or installed SSH close remains."""

        census = self.ssh_close_journal_census()
        if census.prepared_reservations or census.total_pending:
            raise StateError(
                "SSH close journal is not drained: "
                f"prepared={census.prepared_reservations}, "
                f"exact={census.exact_pending}, legacy={census.legacy_pending}"
            )

    def _generate_bounded_foreground_process_termination(
        self,
        *,
        user: User,
        system: System,
        start_time: datetime,
        pid: int,
        process_name: str,
        logon_id: str,
        lifetime: tuple[float, float],
        rng: random.Random,
    ) -> datetime:
        """Emit and track termination for a bounded foreground command process."""
        termination_time = start_time + timedelta(seconds=rng.uniform(*lifetime))
        session_end_plan = self.state_manager.get_session_end_plan(logon_id)
        session = self.state_manager.get_session(logon_id)
        lifecycle_deadlines = [
            ensure_utc(deadline)
            for deadline in (
                session_end_plan.canonical_end
                if session_end_plan is not None and session_end_plan.is_authoritative
                else None,
                session.network_close_time if session is not None else None,
            )
            if deadline is not None
        ]
        if lifecycle_deadlines:
            deadline = min(lifecycle_deadlines)
            # A foreground command belongs to its interactive session.  Its
            # sampled lifetime cannot outlive the transport/session deadline;
            # leave a small canonical margin for source-native termination
            # latency before the session's close observation.
            latest_termination = deadline - timedelta(seconds=2)
            if latest_termination <= ensure_utc(start_time):
                latest_termination = min(
                    deadline - timedelta(milliseconds=25),
                    ensure_utc(start_time) + timedelta(milliseconds=100),
                )
            termination_time = min(termination_time, latest_termination)
        resolved_termination_time = self.resolve_process_lifecycle_close_candidate(
            system.hostname,
            pid,
            termination_time,
        )
        lifecycle_deadline = min(lifecycle_deadlines) if lifecycle_deadlines else None
        resolved_precedes_deadline = (
            resolved_termination_time is None
            or lifecycle_deadline is None
            or resolved_termination_time < lifecycle_deadline
        )
        if resolved_precedes_deadline:
            tracked_termination_time = resolved_termination_time or termination_time
            self._remember_foreground_process_finalizer(
                system=system,
                user=user,
                pid=pid,
                process_name=process_name,
                logon_id=logon_id,
                termination_time=tracked_termination_time,
            )
        else:
            # The owning session teardown already has the only valid close
            # window. Do not publish a post-deadline advisory release or leave
            # stale finalizer ownership behind it.
            tracked_termination_time = lifecycle_deadline
            assert tracked_termination_time is not None
        if (
            resolved_termination_time is not None
            and resolved_precedes_deadline
            and self._is_within_scenario_window(resolved_termination_time)
        ):
            self.generate_process_termination(
                user=user,
                system=system,
                time=resolved_termination_time,
                pid=pid,
                process_name=process_name,
                logon_id=logon_id,
                session_end_plan=session_end_plan,
            )
            source_termination_time = self.process_source_terminate_time(system.hostname, pid)
            if source_termination_time is not None:
                return max(resolved_termination_time, source_termination_time)
        return tracked_termination_time

    def _is_within_scenario_window(self, event_time: datetime) -> bool:
        """Return whether source-visible generated telemetry belongs inside the scenario."""
        scenario_end = getattr(self, "_scenario_end_time", None)
        if scenario_end is None:
            return True
        return ensure_utc(event_time) < ensure_utc(scenario_end)

    def _foreground_shell_key(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        parent_pid: int,
    ) -> tuple[str, str, str, int] | None:
        """Return the interactive shell key that serializes foreground Linux children."""
        proc = self.state_manager.get_process(system.hostname, parent_pid)
        if proc is None:
            return None
        image = (proc.image or "").rsplit("/", 1)[-1].lower()
        if image not in {"bash", "sh", "zsh"}:
            return None
        shell_logon_id = proc.logon_id or logon_id
        return (system.hostname, username, shell_logon_id, parent_pid)

    def _reserve_foreground_shell_time(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        parent_pid: int,
        requested_time: datetime,
        seed_text: str,
        concurrency_group_id: str = "",
    ) -> datetime:
        """Delay a new foreground command until the same interactive shell is free."""
        key = self._foreground_shell_key(
            system=system,
            username=username,
            logon_id=logon_id,
            parent_pid=parent_pid,
        )
        if key is None:
            return requested_time
        shell_proc = self.state_manager.get_process(system.hostname, parent_pid)
        if shell_proc is not None:
            shell_start = ensure_utc(shell_proc.start_time)
            readiness_seed = _stable_seed(
                "foreground_shell_initial_ready:"
                f"{system.hostname}:{username}:{logon_id}:{parent_pid}:"
                f"{shell_start.isoformat()}"
            )
            requested_time = max(
                requested_time,
                shell_start
                + timedelta(
                    milliseconds=(
                        _FOREGROUND_SHELL_INITIAL_READY_MIN_MS
                        + (readiness_seed % _FOREGROUND_SHELL_INITIAL_READY_SPAN_MS)
                    )
                ),
            )
        next_time = self._foreground_shell_next_time.get(key)
        if next_time is None or requested_time >= next_time:
            return requested_time
        if (
            concurrency_group_id
            and self._foreground_shell_release_groups.get(key) == concurrency_group_id
        ):
            return requested_time
        rng = random.Random(
            _stable_seed(
                f"foreground_shell_gap:{system.hostname}:{username}:{logon_id}:"
                f"{parent_pid}:{seed_text}:{next_time.timestamp()}"
            )
        )
        return next_time + timedelta(milliseconds=rng.randint(120, 900))

    def _remember_foreground_shell_available(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        parent_pid: int,
        termination_time: datetime,
        seed_text: str,
        concurrency_group_id: str = "",
    ) -> None:
        """Remember when an interactive Linux shell can plausibly accept more input."""
        rng = random.Random(
            _stable_seed(
                f"foreground_shell_release:{system.hostname}:{username}:{logon_id}:"
                f"{parent_pid}:{seed_text}:{termination_time.timestamp()}"
            )
        )
        release_time = termination_time + timedelta(milliseconds=rng.randint(180, 1400))
        bash_key = (system.hostname, username, logon_id)
        self._bash_history_next_time[bash_key] = max(
            self._bash_history_next_time.get(bash_key, release_time),
            release_time,
        )
        generic_bash_key = (system.hostname, username, "")
        self._bash_history_next_time[generic_bash_key] = max(
            self._bash_history_next_time.get(generic_bash_key, release_time),
            release_time,
        )
        key = self._foreground_shell_key(
            system=system,
            username=username,
            logon_id=logon_id,
            parent_pid=parent_pid,
        )
        if key is None:
            return
        self._foreground_shell_next_time[key] = max(
            release_time,
            self._foreground_shell_next_time.get(key, release_time),
        )
        if self._foreground_shell_next_time[key] == release_time:
            self._foreground_shell_release_groups[key] = concurrency_group_id

    def reserve_linux_foreground_process_start(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        parent_pid: int,
        requested_time: datetime,
        process_name: str,
        command_line: str,
    ) -> datetime:
        """Return a shell-serialized start time for a Linux foreground process."""
        if _get_os_category(system.os) != "linux":
            return requested_time
        if _linux_foreground_lifetime(process_name, command_line) is None:
            return requested_time
        reserved_time = max(
            requested_time,
            self._bash_history_next_time.get(
                (system.hostname, username, logon_id),
                requested_time,
            ),
        )
        return self._reserve_foreground_shell_time(
            system=system,
            username=username,
            logon_id=logon_id,
            parent_pid=parent_pid,
            requested_time=reserved_time,
            seed_text=command_line,
        )

    def _reusable_linux_sudo_shell_pid(
        self,
        *,
        system: System,
        session: ActiveSession,
        requested_time: datetime,
    ) -> int | None:
        """Return the shell PID that sudo bootstrap would reuse without mutation."""

        shell_pid = session.session_shell_pid
        if shell_pid is None:
            return None
        shell = self.state_manager.get_process(system.hostname, shell_pid)
        if shell is None or not self._is_pid_active_at(system, shell_pid, requested_time):
            return None
        scenario_start = getattr(self, "_scenario_start_time", None)
        shell_start = ensure_utc(shell.start_time)
        if (
            scenario_start is not None
            and ensure_utc(requested_time) >= ensure_utc(scenario_start)
            and shell_start < ensure_utc(scenario_start)
        ):
            return None
        if session.session_kind == "ssh":
            source_ready_time = _session_source_ready_time(session)
            if shell.logon_id != session.logon_id or (
                source_ready_time is not None and shell_start < source_ready_time
            ):
                return None
        return shell_pid

    def _linux_sudo_foreground_admission_ceiling(
        self,
        *,
        system: System,
        username: str,
        requested_time: datetime,
        command: str,
        session: ActiveSession | None,
    ) -> datetime:
        """Return an exact-or-conservative pre-mutation sudo serialization ceiling."""

        requested_time = ensure_utc(requested_time)
        activity_anchor = requested_time
        if session is not None:
            shell_pid = self._reusable_linux_sudo_shell_pid(
                system=system,
                session=session,
                requested_time=requested_time,
            )
            if shell_pid is not None:
                return self.reserve_linux_foreground_process_start(
                    system=system,
                    username=username,
                    logon_id=session.logon_id,
                    parent_pid=shell_pid,
                    requested_time=requested_time,
                    process_name="/usr/bin/sudo",
                    command_line=f"sudo {command}",
                )
            history_ceiling = self._bash_history_next_time.get(
                (system.hostname, username, session.logon_id),
                requested_time,
            )
            if session.session_kind == "ssh":
                shell_ceiling = ensure_utc(session.start_time) + timedelta(
                    milliseconds=(
                        _SSH_SESSION_SSHD_MAX_AFTER_LOGON_MS + _SSH_SESSION_BASH_MAX_AFTER_SSHD_MS
                    ),
                )
                source_ready_time = _session_source_ready_time(session)
                if source_ready_time is not None:
                    shell_ceiling = max(
                        shell_ceiling,
                        source_ready_time
                        + timedelta(milliseconds=_SSH_SESSION_SHELL_MAX_AFTER_SOURCE_READY_MS),
                    )
                scenario_start = getattr(self, "_scenario_start_time", None)
                if scenario_start is not None and activity_anchor >= ensure_utc(scenario_start):
                    shell_ceiling = max(
                        shell_ceiling,
                        ensure_utc(scenario_start)
                        + timedelta(
                            milliseconds=(
                                _SSH_SESSION_SSHD_MAX_AFTER_SCENARIO_START_MS
                                + _SSH_SESSION_BASH_MAX_AFTER_SSHD_MS
                            ),
                        ),
                    )
            else:
                shell_ceiling = max(
                    activity_anchor
                    + timedelta(milliseconds=_LINUX_LOCAL_SESSION_SHELL_MAX_AFTER_REQUEST_MS),
                    ensure_utc(session.start_time)
                    + timedelta(milliseconds=_LINUX_LOCAL_SESSION_SHELL_MAX_AFTER_LOGON_MS),
                )
                scenario_start = getattr(self, "_scenario_start_time", None)
                if scenario_start is not None and activity_anchor >= ensure_utc(scenario_start):
                    shell_ceiling = max(
                        shell_ceiling,
                        ensure_utc(scenario_start)
                        + timedelta(
                            milliseconds=_LINUX_LOCAL_SESSION_SHELL_MAX_AFTER_SCENARIO_START_MS,
                        ),
                    )
        else:
            history_ceiling = requested_time
            shell_ceiling = activity_anchor + timedelta(
                milliseconds=_LINUX_LOCAL_SESSION_SHELL_MAX_AFTER_REQUEST_MS,
            )
            scenario_start = getattr(self, "_scenario_start_time", None)
            if scenario_start is not None and activity_anchor >= ensure_utc(scenario_start):
                shell_ceiling = max(
                    shell_ceiling,
                    ensure_utc(scenario_start)
                    + timedelta(
                        milliseconds=_LINUX_LOCAL_SESSION_SHELL_MAX_AFTER_SCENARIO_START_MS,
                    ),
                )
        return max(
            requested_time,
            history_ceiling,
            shell_ceiling + timedelta(milliseconds=_FOREGROUND_SHELL_INITIAL_READY_MAX_MS),
        )

    def remember_linux_foreground_process_completion(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        parent_pid: int,
        termination_time: datetime,
        process_name: str,
        command_line: str,
    ) -> None:
        """Update shared shell availability after a Linux foreground process finishes."""
        if _get_os_category(system.os) != "linux":
            return
        if _linux_foreground_lifetime(process_name, command_line) is None:
            return
        self._remember_foreground_shell_available(
            system=system,
            username=username,
            logon_id=logon_id,
            parent_pid=parent_pid,
            termination_time=termination_time,
            seed_text=command_line,
        )

    def _ntp_association_profile(
        self,
        src_ip: str,
        dst_ip: str,
        *,
        network_preparation: Any | None = None,
        expires_at: datetime | None = None,
    ) -> dict[str, float | int]:
        """Return stable NTP client/server association fields."""
        key = (src_ip, dst_ip)
        profile = (
            self._ntp_association_profiles.get(key)
            if network_preparation is None
            else network_preparation.read_point(
                NetworkRuntimePointFamily.NTP_ASSOCIATION,
                key,
                None,
            )
        )
        if profile is not None:
            return dict(profile)

        profile_rng = random.Random(_stable_seed(f"ntp_association:{src_ip}:{dst_ip}"))
        version = 3 if profile_rng.random() < 0.08 else 4
        poll = float(_ntp_association_poll_seconds(src_ip, dst_ip))
        profile = {
            "version": version,
            "poll": poll,
        }
        if network_preparation is None:
            self._ntp_association_profiles[key] = profile
        else:
            network_preparation.stage_point(
                NetworkRuntimePointFamily.NTP_ASSOCIATION,
                key,
                profile,
                expires_at=expires_at,
            )
        return profile

    def _ntp_server_response_profile(
        self,
        dst_ip: str,
        *,
        network_preparation: Any | None = None,
        timing_runtime: Any | None = None,
        network_point_expires_at: datetime | None = None,
        expires_at: datetime | None = None,
    ) -> dict[str, float]:
        """Return NTP response fields owned by the server, not by clients."""
        profile = (
            self._ntp_server_response_profiles.get(dst_ip)
            if network_preparation is None
            else network_preparation.read_point(
                NetworkRuntimePointFamily.NTP_SERVER_PROFILE,
                dst_ip,
                None,
            )
        )
        if profile is not None:
            return dict(profile)

        if _is_private_ip(dst_ip):
            delay_bounds = (0.006, 0.016, 0.055)
            dispersion_bounds = (0.004, 0.011, 0.028)
        else:
            delay_bounds = (0.001, 0.019, 0.08)
            dispersion_bounds = (0.001, 0.009, 0.04)
        planner = (
            self._activity_timing_planner
            if timing_runtime is None
            else BaselineTimingPlanner(timing_runtime, source="activity")
        )
        root_delay = planner.right_skew_seconds(
            relationship_key="activity.ntp.server_root_delay",
            stable_id=f"ntp-server:{dst_ip}",
            minimum=delay_bounds[0],
            median=delay_bounds[1],
            maximum=delay_bounds[2],
            host=dst_ip,
            sample_key="root_delay",
        )
        root_disp = planner.right_skew_seconds(
            relationship_key="activity.ntp.server_root_dispersion",
            stable_id=f"ntp-server:{dst_ip}",
            minimum=dispersion_bounds[0],
            median=dispersion_bounds[1],
            maximum=dispersion_bounds[2],
            host=dst_ip,
            sample_key="root_dispersion",
        )
        precision_rng = random.Random(_stable_seed(f"ntp_server_precision:{dst_ip}"))
        precision_exponent = precision_rng.randint(-24, -19)
        profile = {
            "precision": _ntp_precision_interval_seconds(precision_exponent),
            "root_delay": root_delay,
            "root_disp": root_disp,
        }
        if network_preparation is None:
            self._ntp_server_response_profiles[dst_ip] = profile
        else:
            network_preparation.stage_point(
                NetworkRuntimePointFamily.NTP_SERVER_PROFILE,
                dst_ip,
                profile,
                expires_at=expires_at,
            )
        return profile

    def _build_host_context(self, system: System) -> HostContext:
        """Build a HostContext from a System model object.

        Precomputes FQDN and NetBIOS domain so render methods don't have to.
        """
        ad_domain = getattr(self, "_ad_domain", "")
        hostname = system.hostname
        return HostContext(
            hostname=hostname,
            ip=system.ip,
            os=system.os,
            os_category=_get_os_category(system.os),
            system_type=system.type,
            domain=ad_domain,
            # Guard against an already-FQDN hostname so we never double the domain
            # (e.g. "cdn.example.com" -> "cdn.example.com.example.com"), mirroring
            # the guard in _system_for_hostname.
            fqdn=(hostname if "." in hostname else f"{hostname}.{ad_domain}")
            if ad_domain
            else hostname,
            netbios_domain=ad_domain.split(".")[0].upper() if ad_domain else "CORP",
            roles=list(system.roles),
        )

    def _system_for_hostname(self, hostname: str) -> Any | None:
        """Resolve a scenario system by short hostname or FQDN."""
        wanted = hostname.lower().rstrip(".")
        if not wanted:
            return None

        systems_by_ip = getattr(self, "_ip_to_system", {})
        ad_domain = str(getattr(self, "_ad_domain", "") or "").lower().rstrip(".")
        signature = (id(systems_by_ip), len(systems_by_ip), ad_domain)
        if signature != self._systems_by_hostname_signature:
            systems_by_hostname: dict[str, Any] = {}
            for system in systems_by_ip.values():
                system_host = str(getattr(system, "hostname", "") or "").lower().rstrip(".")
                if not system_host:
                    continue
                systems_by_hostname.setdefault(system_host, system)
                if ad_domain and "." not in system_host:
                    systems_by_hostname.setdefault(f"{system_host}.{ad_domain}", system)
            self._systems_by_hostname = systems_by_hostname
            self._systems_by_hostname_signature = signature

        return self._systems_by_hostname.get(wanted)

    def _dns_canonical_internal_hostname(self, hostname: str | None) -> str | None:
        """Return the scenario FQDN for known internal hostnames."""
        if not hostname:
            return hostname
        system = self._system_for_hostname(hostname)
        if system is None:
            return hostname
        ad_domain = str(getattr(self, "_ad_domain", "") or "").strip().rstrip(".")
        system_host = str(getattr(system, "hostname", "") or "").strip().rstrip(".")
        if not system_host or not ad_domain:
            return system_host or hostname
        if "." in system_host:
            return system_host
        return f"{system_host}.{ad_domain}"

    def _scenario_fqdn_for_ip(self, ip: str) -> str | None:
        """Return the current scenario's canonical hostname for an owned IP."""
        system = getattr(self, "_ip_to_system", {}).get(ip)
        if system is None:
            return None
        return self._dns_canonical_internal_hostname(str(getattr(system, "hostname", "") or ""))

    def _unique_environment_systems(self) -> list[Any]:
        """Return scenario systems once, preserving environment order where possible."""
        systems: list[Any] = []
        seen_hosts: set[str] = set()
        for system in getattr(self, "_ip_to_system", {}).values():
            hostname = str(getattr(system, "hostname", "") or "")
            if hostname in seen_hosts:
                continue
            seen_hosts.add(hostname)
            systems.append(system)
        return systems

    def _system_for_command_alias(self, hostname: str, service: str) -> Any | None:
        """Resolve common generic command aliases to environment systems."""
        wanted = hostname.lower().rstrip(".")
        if not wanted:
            return None
        systems = self._unique_environment_systems()
        if not systems:
            return None

        def system_matches(system: Any, markers: tuple[str, ...]) -> bool:
            haystack = " ".join(
                [
                    str(getattr(system, "hostname", "") or ""),
                    str(getattr(system, "type", "") or ""),
                    " ".join(getattr(system, "roles", []) or []),
                    " ".join(getattr(system, "services", []) or []),
                ]
            ).lower()
            return any(marker in haystack for marker in markers)

        if service == "ssh":
            if wanted.startswith("web") or "web" in wanted:
                markers = ("web", "apache", "nginx", "http")
            elif wanted.startswith("db") or "db" in wanted:
                markers = ("db", "database", "mysql", "postgres", "mssql")
            elif wanted.startswith("app") or "app" in wanted:
                markers = ("app", "api")
            elif "bastion" in wanted or "jump" in wanted:
                markers = ("bastion", "proxy", "jump")
            else:
                markers = ()
            if markers:
                candidates = [
                    system
                    for system in systems
                    if _get_os_category(getattr(system, "os", "")) == "linux"
                    and system_matches(system, markers)
                ]
                if candidates:
                    return candidates[0]
        return None

    def _resolve_command_network_target(
        self,
        target: str,
        service: str,
    ) -> tuple[str, str | None] | None:
        """Resolve a command-line network target to a destination IP and hostname hint."""
        normalized = _normalize_command_host_token(target)
        if not normalized:
            return None
        if _is_ip_literal(normalized):
            return normalized, None
        target_system = self._system_for_hostname(normalized) or self._system_for_command_alias(
            normalized, service
        )
        if target_system is None:
            return None
        return target_system.ip, normalized

    def _process_network_target_supports_service(
        self,
        target_system: Any | None,
        service: str,
        dst_port: int,
    ) -> bool:
        """Return whether a process-network side effect can succeed on a target."""
        if target_system is None:
            return False

        services = {
            str(value).lower().replace(" ", "-").replace("_", "-")
            for value in (getattr(target_system, "services", []) or [])
        }
        roles = {
            str(value).lower().replace(" ", "-").replace("_", "-")
            for value in (getattr(target_system, "roles", []) or [])
        }
        os_category = _get_os_category(str(getattr(target_system, "os", "") or ""))
        system_type = str(getattr(target_system, "type", "") or "").lower()

        if service == "smb" or dst_port == 445:
            if services & {"smb", "samba", "smbd", "lanmanserver", "ad-ds"}:
                return True
            return os_category == "windows"
        if service == "rdp" or dst_port == 3389:
            if services & {"rdp", "termservice", "terminal-services", "xrdp"}:
                return True
            return os_category == "windows" and system_type in {"server", "domain_controller"}
        if service == "ssh" or dst_port == 22:
            return os_category == "linux" or bool(services & {"ssh", "sshd", "openssh"})
        if service in {"http", "ssl"} or dst_port in {80, 443, 8080, 8443}:
            if services & {
                "http",
                "https",
                "apache",
                "apache2",
                "nginx",
                "httpd",
                "iis",
                "gunicorn",
                "tomcat",
                "squid",
            }:
                return True
            return bool(roles & {"web-server", "app-server", "forward-proxy"})
        return True

    def _process_network_target_ips(
        self,
        source_system: System,
        service: str,
        dst_port: int,
    ) -> list[str]:
        """Return internal target IPs compatible with a process-network service."""
        ips: list[str] = []
        for target in self._unique_environment_systems():
            target_ip = str(getattr(target, "ip", "") or "")
            if not target_ip or target_ip == source_system.ip:
                continue
            if self._process_network_target_supports_service(target, service, dst_port):
                ips.append(target_ip)
        return ips

    def _fallback_database_network_target(
        self,
        target: str,
        source_system: System,
    ) -> tuple[str, str | None, bool] | None:
        """Map an unresolved nonlocal DB target to a plausible failed TCP attempt."""
        normalized = _normalize_database_command_target(target)
        if not normalized or _is_local_database_instance_target(normalized):
            return None
        if _is_ip_literal(normalized):
            return normalized, None, False

        systems_by_ip = getattr(self, "_ip_to_system", {})
        anchor_ip = ""
        for db_entry in getattr(self, "_db_servers", []) or []:
            if isinstance(db_entry, dict):
                anchor_ip = str(db_entry.get("ip") or "")
            else:
                anchor_ip = str(db_entry)
            if anchor_ip:
                break
        if not anchor_ip:
            server_systems = [
                system
                for system in self._unique_environment_systems()
                if getattr(system, "ip", "") != source_system.ip
                and (
                    getattr(system, "type", "") in {"server", "domain_controller"}
                    or getattr(system, "roles", [])
                )
            ]
            if server_systems:
                anchor_ip = str(server_systems[0].ip)
        if not anchor_ip:
            anchor_ip = source_system.ip

        try:
            network = ipaddress.ip_network(f"{anchor_ip}/24", strict=False)
            host_offset = 20 + (_stable_seed(f"db_unresolved:{normalized}") % 210)
            candidate_ip = str(network.network_address + host_offset)
            if candidate_ip == source_system.ip or candidate_ip in systems_by_ip:
                candidate_ip = str(network.network_address + ((host_offset + 37) % 210 + 20))
        except ValueError:
            candidate_ip = f"10.10.2.{50 + (_stable_seed(f'db_unresolved:{normalized}') % 150)}"

        ad_domain = str(getattr(self, "_ad_domain", "") or "").strip(".")
        hostname = normalized if "." in normalized or not ad_domain else f"{normalized}.{ad_domain}"
        return candidate_ip, hostname, True

    def _pick_database_target_placeholder(
        self,
        rng: random.Random,
        command_line: str,
        source_system: System,
    ) -> str | None:
        """Choose a scenario-aware value for database command target placeholders."""
        command_lower = command_line.lower()
        service = "mssql"
        if "mysql" in command_lower:
            service = "mysql"
        elif "psql" in command_lower or "postgres" in command_lower:
            service = "postgresql"

        compatible: list[str] = []
        for db_entry in getattr(self, "_db_servers", []) or []:
            if isinstance(db_entry, dict):
                entry_service = str(db_entry.get("service") or "")
                if entry_service and entry_service != service:
                    continue
                ip = str(db_entry.get("ip") or "")
            else:
                ip = str(db_entry)
            if ip and ip != source_system.ip:
                compatible.append(ip)
        if not compatible:
            return None

        target_ip = rng.choice(compatible)
        target_system = getattr(self, "_ip_to_system", {}).get(target_ip)
        if target_system is None:
            return target_ip

        ad_domain = str(getattr(self, "_ad_domain", "") or "").strip(".")
        style = rng.random()
        if style < 0.20:
            return target_ip
        if style < 0.45 and ad_domain:
            return f"{target_system.hostname}.{ad_domain}"
        return str(target_system.hostname)

    def _pick_command_target_placeholder(
        self,
        rng: random.Random,
        command_line: str,
        source_system: System,
    ) -> str | None:
        """Choose an environment-valid replacement for command `{ssh_target}` placeholders."""
        systems = [
            system for system in self._unique_environment_systems() if system.ip != source_system.ip
        ]
        if not systems:
            return None
        command_lower = command_line.lower()
        if "ldap://" in command_lower:
            candidates = [
                system
                for system in systems
                if getattr(system, "type", "") == "domain_controller"
                or "domain_controller" in (getattr(system, "roles", []) or [])
            ]
        elif "mstsc" in command_lower:
            candidates = [
                system
                for system in systems
                if _get_os_category(getattr(system, "os", "")) == "windows"
                and getattr(system, "type", "") in {"server", "domain_controller"}
            ]
        else:
            candidates = [
                system
                for system in systems
                if _get_os_category(getattr(system, "os", "")) == "linux"
            ]
        if not candidates:
            candidates = systems
        target = rng.choice(candidates)
        ad_domain = str(getattr(self, "_ad_domain", "") or "").strip(".")
        style = rng.random()
        if style < 0.18:
            return target.ip
        if style < 0.32 and ad_domain:
            return f"{target.hostname}.{ad_domain}"
        return str(target.hostname)

    def _parameterize_command_for_system(
        self,
        rng: random.Random,
        command_line: str,
        *,
        username: str,
        system: System,
    ) -> str:
        """Parameterize command templates with environment-aware network targets."""
        if "{ssh_target}" in command_line:
            target = self._pick_command_target_placeholder(rng, command_line, system)
            if target:
                command_line = command_line.replace("{ssh_target}", target)
        if "{internal_url}" in command_line:
            internal_url_count = command_line.count("{internal_url}")
            for _ in range(internal_url_count):
                command_line = command_line.replace(
                    "{internal_url}",
                    self._pick_internal_url_placeholder(rng),
                    1,
                )
        if "{ldap_base_dn}" in command_line:
            command_line = command_line.replace(
                "{ldap_base_dn}",
                _ldap_base_dn(str(getattr(self, "_ad_domain", "") or "corp.local")),
            )
        if "{db_server}" in command_line:
            target = self._pick_database_target_placeholder(rng, command_line, system)
            if target:
                command_line = command_line.replace("{db_server}", target)
        return _parameterize_command(rng, command_line, username=username)

    def _pick_internal_url_placeholder(self, rng: random.Random) -> str:
        """Return an internal URL in the current scenario namespace."""
        domain = str(getattr(self, "_ad_domain", "") or "corp.local").strip(".").lower()
        if not domain or "{" in domain or "}" in domain:
            domain = "corp.local"
        options = [
            f"https://jira.{domain}/browse/PROJ-{rng.randint(1000, 9999)}",
            f"https://wiki.{domain}/display/ENG/Architecture",
            f"https://gitlab.{domain}/team/project/-/pipelines/{rng.randint(100, 9999)}",
            f"https://grafana.{domain}/d/system-overview",
        ]
        return rng.choice(options)

    def _active_interactive_windows_session(
        self,
        system: System,
        time: datetime,
    ) -> ActiveSession | None:
        """Return the newest user-owned interactive Windows session on a host."""
        if _get_os_category(system.os) != "windows":
            return None

        candidates = [
            session
            for session in self.state_manager.get_active_sessions_on_system_at(
                system.hostname,
                time,
            )
            if (
                session.username not in _SYSTEM_ACCOUNTS
                and not session.username.endswith("$")
                and session.logon_type in _WINDOWS_INTERACTIVE_SESSION_LOGON_TYPES
                and session.session_kind not in {"network", "service"}
                and _session_started_by(session, time)
                and not self._workstation_logon_locked_at(
                    system,
                    session.username,
                    session.logon_id,
                    time,
                )
            )
        ]
        if not candidates:
            return None

        assigned_user = getattr(system, "assigned_user", None)
        if assigned_user:
            assigned_candidates = [
                session for session in candidates if session.username == assigned_user
            ]
            if assigned_candidates:
                candidates = assigned_candidates
        return max(candidates, key=lambda session: session.start_time)

    def _active_user_interactive_windows_session(
        self,
        user: User,
        system: System,
        time: datetime,
    ) -> ActiveSession | None:
        """Return the newest active Windows interactive session for this user/host."""
        if _get_os_category(system.os) != "windows":
            return None

        candidates = [
            session
            for session in self.state_manager.get_sessions_for_user_at(user.username, time)
            if (
                session.system == system.hostname
                and session.logon_type in _WINDOWS_INTERACTIVE_SESSION_LOGON_TYPES
                and session.session_kind not in {"network", "service"}
                and _session_started_by(session, time)
                and not self._workstation_session_locked_at(session, user, system, time)
            )
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda session: session.start_time)

    def _active_user_workstation_windows_session(
        self,
        user: User,
        system: System,
        time: datetime,
    ) -> ActiveSession | None:
        """Return the newest local workstation session for this user/host."""
        if _get_os_category(system.os) != "windows":
            return None

        candidates = [
            session
            for session in self.state_manager.get_sessions_for_user_at(user.username, time)
            if (
                session.system == system.hostname
                and _is_windows_workstation_session(session)
                and _session_started_by(session, time)
            )
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda session: session.start_time)

    def _active_user_local_linux_session(
        self,
        user: User,
        system: System,
        time: datetime,
    ) -> ActiveSession | None:
        """Return the newest active local Linux session for this user/host."""
        if _get_os_category(system.os) != "linux":
            return None

        candidates = [
            session
            for session in self.state_manager.get_active_sessions_for_user_at(user.username, time)
            if (
                session.system == system.hostname
                and session.logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES
                and session.session_kind not in _LINUX_REMOTE_SESSION_KINDS
                and _session_active_for_activity(session, time)
            )
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda session: ensure_utc(session.start_time))

    def _session_id_for_logon(self, logon_id: str) -> int:
        """Return the canonical source-native session ID for a LogonID."""
        if not logon_id:
            return 0
        return self.state_manager.get_session_id(logon_id)

    def _locked_user_interactive_windows_session(
        self,
        user: User,
        system: System,
        time: datetime,
    ) -> tuple[ActiveSession, datetime] | None:
        """Return the newest locked interactive Windows session for this user/host."""
        if _get_os_category(system.os) != "windows":
            return None

        lock_times = getattr(self, "_last_workstation_lock_time", {})
        candidates: list[tuple[datetime, ActiveSession]] = []
        for (hostname, username, locked_logon_id), lock_time in lock_times.items():
            if hostname != system.hostname or username != user.username:
                continue
            lock_timestamp = ensure_utc(lock_time)
            if lock_timestamp > time:
                continue
            session = self.state_manager.get_session(locked_logon_id)
            if (
                session is not None
                and session.system == system.hostname
                and session.start_time <= time
                and _is_windows_workstation_session(session)
            ):
                candidates.append((lock_timestamp, session))

        if not candidates:
            return None
        return max(candidates, key=lambda candidate: candidate[0])

    def _workstation_session_locked_at(
        self,
        session: ActiveSession,
        user: User,
        system: System,
        time: datetime,
    ) -> bool:
        """Return whether a local workstation session is visibly locked at ``time``."""
        if not _is_windows_workstation_session(session):
            return False
        return self._workstation_logon_locked_at(system, user.username, session.logon_id, time)

    def _workstation_logon_locked_at(
        self,
        system: System,
        username: str,
        logon_id: str,
        time: datetime,
    ) -> bool:
        """Return whether a workstation logon ID is visibly locked at ``time``."""
        lock_time = getattr(self, "_last_workstation_lock_time", {}).get(
            (system.hostname, username, logon_id)
        )
        return lock_time is not None and ensure_utc(lock_time) <= ensure_utc(time)

    def _near_future_user_interactive_windows_session(
        self,
        user: User,
        system: System,
        time: datetime,
        *,
        max_gap: timedelta = timedelta(minutes=10),
    ) -> ActiveSession | None:
        """Return a near-future Windows session that should own shifted baseline work."""
        if _get_os_category(system.os) != "windows":
            return None

        activity_time = ensure_utc(time)
        candidates = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if (
                session.system == system.hostname
                and session.logon_type in _WINDOWS_INTERACTIVE_SESSION_LOGON_TYPES
                and session.session_kind not in {"network", "service"}
                and activity_time < ensure_utc(session.start_time) <= activity_time + max_gap
            )
        ]
        if not candidates:
            return None
        return min(candidates, key=lambda session: ensure_utc(session.start_time))

    def _user_model_for_username(self, username: str) -> User:
        """Resolve a known scenario user, or build a safe fallback user object."""
        known_users = getattr(self, "_users_by_username", {})
        known_user = known_users.get(username)
        if known_user is not None:
            return known_user
        return User(
            username=username,
            full_name=username,
            email=f"{username}@{self._valid_fallback_email_domain()}",
        )

    def _resolve_process_identity(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        time: datetime,
    ) -> tuple[str, str]:
        """Resolve process owner/logon before emitters render cross-source evidence."""
        if _get_os_category(system.os) != "windows":
            return username, logon_id

        exe_name = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        normalized_username = username.upper().split("\\")[-1]
        if (
            normalized_username in _SYSTEM_ACCOUNT_LOGON_IDS
            and exe_name not in _WINDOWS_USER_SESSION_PROCESSES
        ):
            return normalized_username, _SYSTEM_ACCOUNT_LOGON_IDS[normalized_username]
        if (
            exe_name not in _WINDOWS_USER_SESSION_PROCESSES
            or normalized_username not in _SYSTEM_ACCOUNTS
        ):
            return username, logon_id

        session = self._active_interactive_windows_session(system, time)
        if session is None:
            return username, logon_id
        return session.username, session.logon_id

    def _remember_connection_tuple(
        self,
        src_ip: str,
        src_port: int,
        dst_ip: str,
        dst_port: int,
        proto: str,
        time: datetime,
        duration: float | None = None,
    ) -> None:
        """Track recently allocated 5-tuples to avoid synthetic exact repeats."""
        if proto == "icmp":
            return
        ts_epoch = time.timestamp()
        self._prune_recent_connection_tuples(ts_epoch)
        active_until = ts_epoch + max(0.0, duration or 0.0)
        for key in self._connection_tuple_key_variants(src_ip, src_port, dst_ip, dst_port, proto):
            previous_seen_at = self._recent_connection_tuples.get(key)
            seen_at = max(
                active_until, previous_seen_at if previous_seen_at is not None else ts_epoch
            )
            if previous_seen_at == seen_at:
                continue
            self._recent_connection_tuples[key] = seen_at

    def _prune_recent_connection_tuples(
        self,
        ts_epoch: float,
        *,
        reuse_window: float = _RECENT_CONNECTION_REUSE_WINDOW_SECONDS,
    ) -> None:
        """Remove tuple reservations older than the event-time reuse window."""
        cutoff = ts_epoch - reuse_window
        self._recent_connection_tuples.expire_before(cutoff)

    @staticmethod
    def _connection_tuple_key_variants(
        src_ip: str,
        src_port: int,
        dst_ip: str,
        dst_port: int,
        proto: str,
    ) -> tuple[tuple[str, int, str, int, str], ...]:
        """Return raw and IPv4-mapped-normalized tuple keys for reuse checks."""
        src_values = (src_ip, src_ip.removeprefix("::ffff:"))
        dst_values = (dst_ip, dst_ip.removeprefix("::ffff:"))
        variants: list[tuple[str, int, str, int, str]] = []
        seen: set[tuple[str, int, str, int, str]] = set()
        for candidate_src in src_values:
            for candidate_dst in dst_values:
                key = (candidate_src, src_port, candidate_dst, dst_port, proto)
                if key in seen:
                    continue
                variants.append(key)
                seen.add(key)
        return tuple(variants)

    def _connection_tuple_recently_used(
        self,
        src_ip: str,
        src_port: int,
        dst_ip: str,
        dst_port: int,
        proto: str,
        time: datetime,
        *,
        reuse_window: float = _RECENT_CONNECTION_REUSE_WINDOW_SECONDS,
    ) -> bool:
        """Return whether a source port would visibly repeat a recent endpoint tuple."""
        ts_epoch = time.timestamp()
        self._prune_recent_connection_tuples(ts_epoch, reuse_window=reuse_window)
        for key in self._connection_tuple_key_variants(src_ip, src_port, dst_ip, dst_port, proto):
            seen_at = self._recent_connection_tuples.get(key)
            if seen_at is not None and abs(ts_epoch - seen_at) <= reuse_window:
                return True

        return self.state_manager.connection_tuple_recently_used(
            src_ip,
            src_port,
            dst_ip,
            dst_port,
            proto,
            time,
            reuse_window=reuse_window,
        )

    def _allocate_ephemeral_port(
        self,
        src_ip: str,
        dst_ip: str,
        dst_port: int,
        proto: str,
        time: datetime,
        os_category: str,
    ) -> int:
        """Allocate an ephemeral port while avoiding exact 5-tuple reuse."""
        rng = _get_rng()
        reuse_window = _RECENT_CONNECTION_REUSE_WINDOW_SECONDS
        for _ in range(128):
            src_port = _ephemeral_port(rng, os_category)
            if not self._connection_tuple_recently_used(
                src_ip,
                src_port,
                dst_ip,
                dst_port,
                proto,
                time,
                reuse_window=reuse_window,
            ):
                self._remember_connection_tuple(src_ip, src_port, dst_ip, dst_port, proto, time)
                return src_port
        src_port = _ephemeral_port(rng, os_category)
        self._remember_connection_tuple(src_ip, src_port, dst_ip, dst_port, proto, time)
        return src_port

    def _last_effective_connection_source_port(
        self,
        *,
        src_ip: str,
        dst_ip: str,
        dst_port: int,
        proto: str = "tcp",
    ) -> int | None:
        """Return the source port from the most recently emitted matching connection."""
        last_tuple = self._last_connection_effective_tuple
        if last_tuple is None:
            return None
        last_src_ip, last_src_port, last_dst_ip, last_dst_port, last_proto = last_tuple
        if (
            last_src_ip == src_ip
            and last_dst_ip == dst_ip
            and last_dst_port == dst_port
            and last_proto == proto
        ):
            return last_src_port
        return None

    def _last_effective_connection_transaction_id(
        self,
        *,
        src_ip: str,
        src_port: int,
        dst_ip: str,
        dst_port: int,
        proto: str = "tcp",
    ) -> str:
        """Return the transaction identity for the exact last emitted transport."""

        if self._last_connection_effective_tuple != (
            src_ip,
            src_port,
            dst_ip,
            dst_port,
            proto,
        ):
            return ""
        return self._last_connection_effective_transaction_id

    @staticmethod
    def _kerberos_port_key(source_ip: str, dc_hostname: str) -> tuple[str, str]:
        """Return the source/DC key used for short Kerberos TCP exchanges."""
        return (source_ip.removeprefix("::ffff:"), dc_hostname.lower().rstrip("."))

    @staticmethod
    def _kerberos_principal_key(username: str) -> str:
        """Return the stable account principal key used for Kerberos/account lifecycle state."""
        principal = username.strip().rsplit("\\", 1)[-1].split("@", 1)[0]
        return principal.upper()

    def _kerberos_account_allows_no_preauth(self, username: str) -> bool:
        """Return whether canonical identity state explicitly disables Kerberos pre-auth."""
        directory = self.identity_directory
        return directory is not None and directory.windows_account_has_control(
            username,
            "DONT_REQUIRE_PREAUTH",
        )

    @staticmethod
    def _kerberos_tgt_cache_key(
        username: str,
        source_ip: str,
        dc_hostname: str,
    ) -> tuple[str, str, str]:
        """Return the source-native TGT cache identity for one client/DC account."""
        principal = ActivityGenerator._kerberos_principal_key(username)
        return (principal, source_ip.removeprefix("::ffff:"), dc_hostname.lower().rstrip("."))

    def _remember_visible_account_created(self, username: str, time: datetime) -> None:
        """Remember a visible account creation and invalidate impossible pre-create TGT cache."""
        principal = self._kerberos_principal_key(username)
        if not principal:
            return
        created_at = ensure_utc(time)
        existing = self._visible_account_created_at.get(principal)
        if existing is None or created_at < existing:
            self._visible_account_created_at[principal] = created_at
        for key in list(self._kerberos_tgt_cache_until):
            if key[0] == principal:
                self._kerberos_tgt_cache_until.pop(key, None)
        self._visible_account_kerberos_transport_emitted = {
            key for key in self._visible_account_kerberos_transport_emitted if key[0] != principal
        }

    def _visible_account_created_before(self, username: str, time: datetime) -> bool:
        """Return whether an account principal was created during the visible window."""
        principal = self._kerberos_principal_key(username)
        created_at = self._visible_account_created_at.get(principal)
        return created_at is not None and created_at <= ensure_utc(time)

    @staticmethod
    def _kerberos_source_time(
        time: datetime,
        *,
        event_type: str,
        username: str,
        source_ip: str,
        dc_hostname: str,
        source_port: int,
        service_name: str = "",
    ) -> datetime:
        """Return a source-native Kerberos audit timestamp with sub-ms texture."""
        seed = _stable_seed(
            "kerberos_source_time:"
            f"{event_type}:{username}:{source_ip}:{dc_hostname}:{source_port}:"
            f"{service_name}:{time.isoformat()}"
        )
        # Windows event timestamps are not obtained by adding whole milliseconds
        # to a shared base event. Add deterministic sub-ms texture so related
        # Kerberos rows do not preserve identical fractional suffixes.
        return time + timedelta(microseconds=37 + (seed % 937))

    @staticmethod
    def _kerberos_ticket_times(
        anchor_time: datetime,
        rng: random.Random,
        *,
        tgs_before_ms: tuple[int, int] = (12, 90),
        tgt_before_tgs_ms: tuple[int, int] = (35, 240),
    ) -> tuple[datetime, datetime]:
        """Return source-native-ish TGT and TGS times before an anchor event."""
        tgs_time = anchor_time - timedelta(
            milliseconds=rng.randint(*tgs_before_ms),
            microseconds=rng.randint(83, 941),
        )
        tgt_time = tgs_time - timedelta(
            milliseconds=rng.randint(*tgt_before_tgs_ms),
            microseconds=rng.randint(97, 953),
        )
        return tgt_time, tgs_time

    def _remember_kerberos_tgt_cache(
        self,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        rng: random.Random,
    ) -> None:
        """Remember that a client has a reusable TGT beyond this visible moment."""
        key = self._kerberos_tgt_cache_key(username, source_ip, dc_hostname)
        base_ttl = rng.randint(45 * 60, 8 * 60 * 60)
        if username.endswith("$"):
            base_ttl = rng.randint(60 * 60, 10 * 60 * 60)
        expires_at = ensure_utc(time) + timedelta(seconds=base_ttl)
        current = self._kerberos_tgt_cache_until.get(key)
        self._kerberos_tgt_cache_until[key] = (
            max(current, expires_at) if current is not None else expires_at
        )

    def _should_emit_visible_kerberos_tgt(
        self,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        rng: random.Random,
    ) -> bool:
        """Return whether a TGS should be preceded by a visible fresh TGT."""
        key = self._kerberos_tgt_cache_key(username, source_ip, dc_hostname)
        current_time = ensure_utc(time)
        cached_until = self._kerberos_tgt_cache_until.get(key)
        if cached_until is not None and cached_until > current_time:
            return rng.random() < 0.08

        if self._visible_account_created_before(username, current_time):
            return True

        pre_window_cache_probability = 0.55 if username.endswith("$") else 0.35
        if rng.random() < pre_window_cache_probability:
            self._remember_kerberos_tgt_cache(username, source_ip, dc_hostname, time, rng)
            return False
        return True

    def _maybe_generate_kerberos_tgt(
        self,
        *,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        rng: random.Random,
        source_port: int | None = None,
        domain: str = "",
    ) -> bool:
        """Emit a TGT only when the client should not be using a cached ticket."""
        if not self._should_emit_visible_kerberos_tgt(username, source_ip, dc_hostname, time, rng):
            return False
        self.generate_kerberos_tgt(
            username=username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=time,
            domain=domain,
            source_port=source_port,
        )
        return True

    def _ensure_visible_created_account_kerberos_exchange(
        self,
        *,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        source_port: int,
        domain: str,
    ) -> None:
        """Ensure first visible TGS for a newly-created account has TGT and KDC flow."""
        service_time = ensure_utc(time)
        if not self._visible_account_created_before(username, service_time):
            return

        principal = self._kerberos_principal_key(username)
        source_ip_key = source_ip.removeprefix("::ffff:")
        dc_key = dc_hostname.lower().rstrip(".")
        cache_key = self._kerberos_tgt_cache_key(username, source_ip, dc_hostname)
        transport_key = (principal, source_ip_key, dc_key)
        rng = random.Random(
            _stable_seed(
                "visible_created_account_kerberos_exchange:"
                f"{principal}:{source_ip_key}:{dc_key}:{service_time.isoformat()}"
            )
        )

        cached_until = self._kerberos_tgt_cache_until.get(cache_key)
        if cached_until is None or cached_until <= service_time:
            tgt_time = service_time - timedelta(
                milliseconds=rng.randint(45, 260),
                microseconds=rng.randint(103, 941),
            )
            self._maybe_generate_kerberos_tgt(
                username=username,
                source_ip=source_ip,
                dc_hostname=dc_hostname,
                time=tgt_time,
                rng=rng,
                source_port=source_port,
                domain=domain,
            )

        if transport_key in self._visible_account_kerberos_transport_emitted:
            return

        dc_system = self._dc_system_for_hostname(dc_hostname)
        source_system = self._ip_to_system.get(source_ip_key) or self._ip_to_system.get(source_ip)
        if dc_system is None or source_system is None:
            return
        dc_ip = str(getattr(dc_system, "ip", "") or "")
        if not dc_ip:
            return

        conn_time = service_time - timedelta(
            milliseconds=rng.randint(1200, 1850),
            microseconds=rng.randint(43, 937),
        )
        if conn_time >= service_time:
            conn_time = service_time - timedelta(microseconds=733)
        self.generate_connection(
            src_ip=source_ip_key,
            dst_ip=dc_ip,
            time=conn_time,
            dst_port=88,
            proto="tcp",
            service="kerberos",
            duration=rng.uniform(1.25, 2.1),
            orig_bytes=rng.randint(520, 1600),
            resp_bytes=rng.randint(1800, 5200),
            src_port=source_port,
            source_system=source_system,
            conn_state="SF",
            suppress_prereq_dns=True,
        )
        self._visible_account_kerberos_transport_emitted.add(transport_key)

    @staticmethod
    def _is_domain_controller_system(system: Any | None) -> bool:
        """Return whether a system is a domain controller."""
        if system is None:
            return False
        roles = set(getattr(system, "roles", []) or [])
        services = set(getattr(system, "services", []) or [])
        return (
            "domain_controller" in roles
            or getattr(system, "type", "") == "domain_controller"
            or "ad-ds" in services
        )

    def _dc_system_for_ip(self, ip: str) -> Any | None:
        """Resolve a domain controller system by IP address."""
        ip_to_system = getattr(self, "_ip_to_system", {})
        system = ip_to_system.get(ip)
        if self._is_domain_controller_system(system):
            return system
        dc_systems = getattr(self, "_dc_systems", [])
        if isinstance(dc_systems, dict):
            dc_systems = dc_systems.values()
        for candidate in dc_systems:
            if getattr(candidate, "ip", "") == ip and self._is_domain_controller_system(candidate):
                return candidate
        return None

    def _dc_system_for_hostname(self, dc_hostname: str) -> Any | None:
        """Resolve a domain controller system by hostname or FQDN."""
        system = self._system_for_hostname(dc_hostname)
        if self._is_domain_controller_system(system):
            return system
        wanted = dc_hostname.lower().rstrip(".")
        dc_systems = getattr(self, "_dc_systems", [])
        if isinstance(dc_systems, dict):
            dc_systems = dc_systems.values()
        for candidate in dc_systems:
            candidate_host = str(getattr(candidate, "hostname", "") or "").lower().rstrip(".")
            ad_domain = str(getattr(self, "_ad_domain", "") or "").lower().rstrip(".")
            candidate_fqdn = (
                f"{candidate_host}.{ad_domain}"
                if candidate_host and ad_domain and "." not in candidate_host
                else candidate_host
            )
            if wanted in {candidate_host, candidate_fqdn} and self._is_domain_controller_system(
                candidate
            ):
                return candidate
        return None

    def _find_reserved_kerberos_source_port(
        self,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        *,
        dst_ip: str | None = None,
        dst_port: int = 88,
        proto: str = "tcp",
        exclude_active_tuple: bool = True,
        window_seconds: float = 2.0,
    ) -> int | None:
        """Return a nearby reserved Kerberos source port for this source/DC pair."""
        if not source_ip or source_ip == "-" or not dc_hostname:
            return None
        key = self._kerberos_port_key(source_ip, dc_hostname)
        current_time = ensure_utc(time)
        current = current_time.timestamp()
        reservations = [
            (seen_at, port)
            for seen_at, port in self._kerberos_source_port_reservations.get(key, [])
            if abs(current - seen_at) <= window_seconds
        ]
        if dst_ip and exclude_active_tuple:
            runtime = getattr(self, "_network_transaction_runtime", None)
            filtered_reservations = []
            for seen_at, port in reservations:
                recent_connection_times: list[float] = []
                for candidate_proto in {proto, "tcp", "udp"}:
                    for tuple_key in self._connection_tuple_key_variants(
                        source_ip,
                        port,
                        dst_ip,
                        dst_port,
                        candidate_proto,
                    ):
                        legacy_seen_at = self._recent_connection_tuples.get(tuple_key)
                        if legacy_seen_at is not None:
                            recent_connection_times.append(legacy_seen_at)
                        if runtime is None:
                            continue
                        runtime_seen_at = runtime.get_point(
                            NetworkRuntimePointFamily.RECENT_TUPLE,
                            tuple_key,
                            None,
                            at=current_time,
                        )
                        if runtime_seen_at is None:
                            continue
                        if type(runtime_seen_at) is not float:
                            raise StateError(
                                "Network runtime recent-tuple point contains a malformed timestamp"
                            )
                        recent_connection_times.append(runtime_seen_at)
                recent_connection_at = max(recent_connection_times, default=0.0)
                reuse_cooldown = min(window_seconds, 2.0)
                if not recent_connection_at or current - recent_connection_at > reuse_cooldown:
                    filtered_reservations.append((seen_at, port))
            reservations = filtered_reservations
        if not reservations:
            return None
        return min(reservations, key=lambda item: abs(current - item[0]))[1]

    def _reserve_kerberos_source_port(
        self,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        source_port: int | None = None,
    ) -> int:
        """Reserve one TCP source port across nearby Kerberos audit and flow events."""
        if not source_ip or source_ip == "-" or not dc_hostname:
            return 0

        dc_system = self._dc_system_for_hostname(dc_hostname)
        dc_ip = str(getattr(dc_system, "ip", "") or "")
        reserved = self._find_reserved_kerberos_source_port(
            source_ip,
            dc_hostname,
            time,
            dst_ip=dc_ip or None,
        )
        if reserved is not None and source_port is None:
            source_port = reserved
        if source_port is None:
            if dc_ip:
                source_port = self._allocate_ephemeral_port(
                    source_ip,
                    dc_ip,
                    88,
                    "tcp",
                    time,
                    self._os_for_ip(source_ip),
                )
                for candidate_proto in ("tcp", "udp"):
                    self._recent_connection_tuples.pop(
                        (source_ip, source_port, dc_ip, 88, candidate_proto),
                        None,
                    )
                    self._recent_connection_tuples.pop(
                        (
                            source_ip.removeprefix("::ffff:"),
                            source_port,
                            dc_ip,
                            88,
                            candidate_proto,
                        ),
                        None,
                    )
            else:
                source_port = _ephemeral_port(_get_rng(), self._os_for_ip(source_ip))

        key = self._kerberos_port_key(source_ip, dc_hostname)
        current = time.timestamp()
        recent = [
            (seen_at, port)
            for seen_at, port in self._kerberos_source_port_reservations.get(key, [])
            if abs(current - seen_at) <= 30.0
        ]
        recent.append((current, source_port))
        self._kerberos_source_port_reservations[key] = recent[-16:]
        return source_port

    def _disambiguate_icmp_observation_time(
        self,
        src_ip: str,
        src_port: int,
        dst_ip: str,
        dst_port: int,
        time: datetime,
    ) -> datetime:
        """Avoid exact duplicate Zeek ICMP summaries for the same tuple and timestamp.

        ICMP scans can intentionally repeat the same source/destination pair at very high
        rates, and Zeek collapses the source/destination ports to type/code values. Track the
        next usable microsecond timestamp per rendered ICMP tuple so duplicates are assigned
        in constant time instead of linearly probing through previously emitted timestamps.
        """
        if len(self._next_icmp_observation_ts_us) > 100_000:
            self._next_icmp_observation_ts_us.clear()
        zeek_type = src_port if src_port else 8
        zeek_code = dst_port if dst_port else 0
        tuple_key = (src_ip, zeek_type, dst_ip, zeek_code)
        requested_ts_us = int(round(time.timestamp() * 1_000_000))
        adjusted_ts_us = max(
            requested_ts_us,
            self._next_icmp_observation_ts_us.get(tuple_key, requested_ts_us),
        )
        gap_seed = _stable_seed(
            f"icmp_observation_gap:{src_ip}:{zeek_type}:{dst_ip}:{zeek_code}:{adjusted_ts_us}"
        )
        # High-rate ICMP sweeps can create many Zeek rows for the same type/code tuple.
        # Keep duplicate observations monotonic without leaving a fixed inter-row cadence.
        next_gap_us = 7_000 + (gap_seed % 77_000)
        self._next_icmp_observation_ts_us[tuple_key] = adjusted_ts_us + next_gap_us
        if adjusted_ts_us == requested_ts_us:
            return time
        return time + timedelta(microseconds=adjusted_ts_us - requested_ts_us)

    def _infer_connection_pid(
        self,
        source_system: System | None,
        service: str | None,
        dst_port: int,
        proto: str,
    ) -> int:
        """Infer a durable system-service PID for infrastructure connections."""
        if source_system is None:
            return -1
        pids = getattr(self, "_system_pids", {}).get(source_system.hostname, {})
        if not pids:
            return -1

        service_name = (service or "").lower()
        roles = set(getattr(source_system, "roles", []) or [])
        os_category = _get_os_category(source_system.os)

        candidates: list[str] = []
        if proto == "udp" and dst_port == 53 or service_name == "dns":
            candidates = [
                "systemd_resolved",
                "svchost_local_svc",
                "svchost_netsvcs",
                "svchost_net_svc",
            ]
        elif proto == "udp" and dst_port == 123 or service_name == "ntp":
            candidates = ["timesyncd", "chronyd", "svchost_netsvcs"]
        elif service_name in ("kerberos", "ldap") or dst_port in (88, 389):
            candidates = ["lsass", "svchost_netsvcs"]
        elif service_name == "smb" or dst_port == 445:
            # smbd is a destination-side Samba responder, never an outbound
            # Linux client owner.  Let client/profile resolution distinguish
            # GVFS, smbclient, and kernel CIFS transports below.
            return 4 if os_category == "windows" else -1
        elif service_name == "ssh" or dst_port == 22:
            if os_category == "linux":
                return -1
            candidates = ["sshd"]
        elif "forward_proxy" in roles and service_name in ("http", "ssl"):
            candidates = ["squid", "nginx", "apache2", "httpd"]
        elif os_category == "linux" and (
            service_name in ("http", "ssl", "https") or dst_port in (80, 443, 8080, 8443)
        ):
            candidates = ["curl", "wget", "firefox", "apache2", "httpd", "nginx", "python3"]
        elif os_category == "windows" and (
            service_name in ("http", "ssl", "https") or dst_port in (80, 443, 8080, 8443)
        ):
            candidates = ["chrome", "msedge", "firefox", "powershell", "svchost_netsvcs"]

        for name in candidates:
            pid = pids.get(name)
            if pid and pid > 0:
                return pid
        return -1

    def _ensure_high_confidence_connection_owner(
        self,
        *,
        source_system: System | None,
        time: datetime,
        service: str | None,
        dst_port: int,
        proto: str,
        hostname: str | None,
        http: HttpContext | None,
        ssh_attempted_username: str | None = None,
    ) -> tuple[int, str | None]:
        """Create or reuse canonical process ownership for high-signal outbound flows."""
        if source_system is None or proto != "tcp":
            return -1, None

        if self._high_confidence_connection_should_remain_unattributed(
            service=service,
            dst_port=dst_port,
            http=http,
        ):
            return -1, None

        os_category = _get_os_category(source_system.os)
        if self._source_should_use_service_connection_owner(source_system, dst_port):
            return self._ensure_service_connection_owner_process(
                source_system=source_system,
                time=time,
                service=service,
                dst_port=dst_port,
                os_category=os_category,
                hostname=hostname,
                http=http,
            )

        return self._ensure_user_connection_owner_process(
            source_system=source_system,
            time=time,
            service=service,
            dst_port=dst_port,
            os_category=os_category,
            hostname=hostname,
            ssh_attempted_username=ssh_attempted_username,
            source_visible_by=time,
        )

    @staticmethod
    def _high_confidence_connection_should_remain_unattributed(
        *,
        service: str | None,
        dst_port: int,
        http: HttpContext | None,
    ) -> bool:
        """Return whether a flow is too low-confidence to synthesize process ownership."""
        service_name = (service or "").lower()
        high_signal_services = {"http", "https", "ssl", "ssh", "smb", "ldap", "kerberos", "mysql"}
        high_signal_ports = {22, 80, 88, 389, 443, 445, 8080, 8443, 3306, 5432}
        if service_name in high_signal_services or dst_port in high_signal_ports:
            return False
        return http is None

    @staticmethod
    def _source_should_use_service_connection_owner(
        source_system: System,
        dst_port: int,
    ) -> bool:
        """Return whether a source host should model daemon/service ownership."""
        roles = {str(role).lower() for role in (getattr(source_system, "roles", []) or [])}
        server_roles = {
            "app_server",
            "database",
            "dns_server",
            "domain_controller",
            "file_server",
            "forward_proxy",
            "log_server",
            "mail_server",
            "monitoring",
            "web_server",
        }
        if roles & server_roles:
            return True
        system_type = (getattr(source_system, "type", "") or "").lower()
        if system_type in {"server", "domain_controller"}:
            return True
        return dst_port in {88, 389}

    def _ensure_service_connection_owner_process(
        self,
        *,
        source_system: System,
        time: datetime,
        service: str | None,
        dst_port: int,
        os_category: str,
        hostname: str | None,
        http: HttpContext | None,
    ) -> tuple[int, str | None]:
        """Create or reuse a daemon/client process for server-originated flows."""
        spec = self._service_connection_owner_spec(
            source_system=source_system,
            service=service,
            dst_port=dst_port,
            os_category=os_category,
            hostname=hostname,
            http=http,
        )
        if spec is None:
            return -1, None
        key, image, command_line, username = spec
        return self._ensure_system_connection_owner_process(
            source_system=source_system,
            time=time,
            key=key,
            image=image,
            command_line=command_line,
            username=username,
        )

    def _service_connection_owner_spec(
        self,
        *,
        source_system: System,
        service: str | None,
        dst_port: int,
        os_category: str,
        hostname: str | None,
        http: HttpContext | None,
    ) -> tuple[str, str, str, str] | None:
        """Return source-native process metadata for a service-owned connection."""
        service_name = (service or "").lower()
        roles = {str(role).lower() for role in (getattr(source_system, "roles", []) or [])}
        target = hostname or (http.host if http is not None else "") or "internal-service"

        if os_category == "windows":
            if service_name in {"kerberos", "ldap"} or dst_port in {88, 389}:
                return (
                    "lsass",
                    r"C:\Windows\System32\lsass.exe",
                    "lsass.exe",
                    "SYSTEM",
                )
            if dst_port in {80, 443, 8080, 8443} or service_name in {"http", "ssl", "https"}:
                user_agent = ((http.user_agent if http is not None else "") or "").lower()
                if "microsoft-cryptoapi" in user_agent:
                    return (
                        "cryptsvc",
                        r"C:\Windows\System32\svchost.exe",
                        "svchost.exe -k NetworkService -p -s CryptSvc",
                        "NETWORK SERVICE",
                    )
                if any(token in user_agent for token in ("windows-update-agent", "bits/")):
                    return (
                        "windows_update_client",
                        r"C:\Windows\System32\svchost.exe",
                        "svchost.exe -k netsvcs -p -s UsoSvc",
                        "SYSTEM",
                    )
                if not any(
                    token in user_agent for token in ("go-http-client/", "meridian-servicehealth/")
                ):
                    return None
                image = r"C:\Program Files\Meridian\ServiceHealth\service-healthcheck.exe"
                return (
                    "service_healthcheck_agent",
                    image,
                    f'"{image}" --service',
                    "SYSTEM",
                )
            if dst_port == 445 or service_name == "smb":
                return (
                    "lanmanworkstation",
                    r"C:\Windows\System32\svchost.exe",
                    "svchost.exe -k NetworkService -p -s LanmanWorkstation",
                    "NETWORK SERVICE",
                )
            return None

        if os_category != "linux":
            return None

        if dst_port in {3306, 5432} or service_name in {"mysql", "postgres", "postgresql"}:
            if "app_server" in roles:
                return (
                    "gunicorn",
                    "/opt/meridian/venv/bin/gunicorn",
                    "gunicorn meridian.wsgi:application --bind 0.0.0.0:8080",
                    "www-data",
                )
            if "web_server" in roles:
                return (
                    "apache2",
                    "/usr/sbin/apache2",
                    "/usr/sbin/apache2 -DFOREGROUND",
                    "www-data",
                )
            return (
                f"db_client_service:{target}:{dst_port}",
                "/usr/bin/mysqladmin",
                f"mysqladmin --host={target} --port={dst_port} ping",
                "root",
            )

        if service_name == "ldap" or dst_port == 389:
            if "mail_server" in roles:
                return (
                    "postfix",
                    "/usr/lib/postfix/sbin/smtpd",
                    "smtpd -n smtp -t inet -u",
                    "postfix",
                )
            if "app_server" in roles or "web_server" in roles:
                return (
                    "gunicorn",
                    "/opt/meridian/venv/bin/gunicorn",
                    "gunicorn meridian.wsgi:application --bind 0.0.0.0:8080",
                    "www-data",
                )
            return (
                "sssd",
                "/usr/sbin/sssd",
                "/usr/sbin/sssd -i --logger=files",
                "root",
            )

        if service_name == "smb" or dst_port == 445:
            return linux_smb_connection_owner(roles, target)

        if dst_port in {80, 443, 8080, 8443} or service_name in {"http", "ssl", "https"}:
            user_agent = (http.user_agent if http is not None else "") or ""
            user_agent_lower = user_agent.lower()
            if "forward_proxy" in roles:
                return (
                    "squid",
                    "/usr/sbin/squid",
                    "/usr/sbin/squid -N -f /etc/squid/squid.conf",
                    "proxy",
                )
            if "curl/" in user_agent_lower:
                return (
                    f"curl_proxy_client:{target}",
                    "/usr/bin/curl",
                    f"curl -fsS --proxy http://proxy:8080 https://{target}/",
                    "root",
                )
            if "wget/" in user_agent_lower:
                return (
                    f"wget_proxy_client:{target}",
                    "/usr/bin/wget",
                    f"wget -q -e use_proxy=yes -O - https://{target}/",
                    "root",
                )
            if "python-requests/" in user_agent_lower:
                return (
                    f"python_requests_proxy_client:{target}",
                    "/usr/bin/python3",
                    f"/usr/bin/python3 /opt/meridian/bin/proxy_healthcheck.py --target {target}",
                    "root",
                )
            if "apache-httpclient" in user_agent_lower:
                return (
                    f"integration_worker:{target}",
                    "/usr/bin/java",
                    f"/usr/bin/java -jar /opt/meridian/integration-worker.jar --check-url https://{target}/",
                    "www-data",
                )
            return (
                f"service_healthcheck:{target}",
                "/usr/bin/java",
                f"/usr/bin/java -jar /opt/meridian/service-healthcheck.jar --target {target}",
                "root",
            )

        return None

    def _ensure_system_connection_owner_process(
        self,
        *,
        source_system: System,
        time: datetime,
        key: str,
        image: str,
        command_line: str,
        username: str,
    ) -> tuple[int, str | None]:
        """Reuse or create a source-native system process for connection attribution."""
        sys_pids = getattr(self, "_system_pids", {}).setdefault(source_system.hostname, {})
        process_rng = random.Random(
            _stable_seed(
                "high_confidence_connection_owner:"
                f"{source_system.hostname}:{key}:{image}:{username}:{time.isoformat()}"
            )
        )
        profiled_worker = matching_service_worker(
            os_category=_get_os_category(source_system.os),
            image=image,
            command_line=command_line,
            username=username,
        )
        if profiled_worker is None:
            pid = self._active_matching_process_pid(
                source_system=source_system,
                time=time,
                key=key,
                image=image,
                username=username,
                command_line=command_line,
            )
            if pid > 0:
                self.state_manager.update_process_activity_time(source_system.hostname, pid, time)
                self._remember_system_connection_owner_finalizer(
                    source_system=source_system,
                    time=time,
                    pid=pid,
                    image=image,
                    command_line=command_line,
                    username=username,
                    rng=process_rng,
                )
                return pid, image

        if self._connection_owner_is_one_shot_network_client(image, command_line):
            lead_seconds = process_rng.uniform(0.12, 3.5)
        else:
            lead_seconds = process_rng.uniform(45.0, 420.0)
        process_time = time - timedelta(seconds=lead_seconds)
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            visible_start = ensure_utc(scenario_start) + timedelta(
                seconds=15 + (process_rng.randint(0, 75))
            )
            if process_time < visible_start < time:
                process_time = visible_start
        if process_time >= time:
            process_time = time - timedelta(milliseconds=120)

        if profiled_worker is not None:
            family_name, worker_name, _family = profiled_worker
            pid = self._ensure_profiled_service_worker(
                system=source_system,
                worker_time=process_time,
                activity_time=time,
                family_name=family_name,
                worker_name=worker_name,
            )
            if pid > 0:
                self.state_manager.update_process_activity_time(
                    source_system.hostname,
                    pid,
                    time,
                )
                self.state_manager.set_current_time(time)
                return pid, image

        if _get_os_category(source_system.os) == "windows":
            parent_pid = self._windows_system_parent_fallback(source_system, process_time)
        else:
            parent_pid = self._linux_system_parent_fallback(source_system, process_time)
            if image.lower().startswith("/usr/lib/apt/methods/"):
                parent_pid = self._ensure_linux_apt_frontend_process(
                    source_system=source_system,
                    helper_time=process_time,
                    rng=process_rng,
                )
        pid = self.generate_system_process(
            source_system,
            process_time,
            image,
            command_line,
            parent_pid=parent_pid,
            username=username,
            emit_linux_syslog=False,
        )
        if pid > 0:
            sys_pids[key] = pid
            self.state_manager.update_process_activity_time(source_system.hostname, pid, time)
            self._remember_system_connection_owner_finalizer(
                source_system=source_system,
                time=time,
                pid=pid,
                image=image,
                command_line=command_line,
                username=username,
                rng=process_rng,
            )
            self.state_manager.set_current_time(time)
            running = self.state_manager.get_process(source_system.hostname, pid)
            return pid, running.image if running is not None else image
        self.state_manager.set_current_time(time)
        return -1, None

    def _active_profiled_service_process(
        self,
        *,
        system: System,
        time: datetime,
        spec: ServiceProcessSpec,
        parent_pid: int,
    ) -> int | None:
        """Return one exact active service manager or worker process."""

        candidates = [
            process
            for process in self.state_manager.get_processes_on_system(system.hostname)
            if process.image.replace("/", "\\").casefold()
            == spec.image.replace("/", "\\").casefold()
            and process.command_line == spec.command_line
            and process.username.casefold() == spec.username.casefold()
            and process.parent_pid == parent_pid
            and process.start_time <= time
            and self._is_pid_active_at(system, process.pid, time)
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda process: process.start_time).pid

    def _process_source_visible_by(
        self,
        *,
        hostname: str,
        pid: int,
        deadline: datetime | None,
    ) -> bool:
        """Return whether an existing process has finalized source visibility in time."""

        if deadline is None:
            return True
        source_time = self.process_source_create_time(hostname, pid)
        return source_time is not None and source_time <= ensure_utc(deadline)

    def _process_source_bound_visible_by(
        self,
        *,
        system: System,
        pid: int,
        deadline: datetime | None,
    ) -> bool:
        """Accept exact visibility or a conservative bound for legacy process state."""

        if deadline is None:
            return True
        source_time = self._process_source_frontier_or_bound(system=system, pid=pid)
        return source_time is not None and source_time <= ensure_utc(deadline)

    def _process_create_source_bound(
        self,
        *,
        system: System,
        canonical_time: datetime,
        parent_source_time: datetime | None = None,
        session_source_time: datetime | None = None,
    ) -> datetime:
        """Return the conservative finalized source frontier for one process create."""

        canonical_time = ensure_utc(canonical_time)
        return canonical_time + self._source_timing_planner.process_create_positive_headroom(
            canonical_time,
            _get_os_category(system.os),
            parent_source_time=parent_source_time,
            session_source_time=session_source_time,
        )

    def _process_source_frontier_or_bound(
        self,
        *,
        system: System,
        pid: int,
        seen_pids: frozenset[int] = frozenset(),
    ) -> datetime | None:
        """Return finalized process visibility or a read-only conservative projection."""

        finalized = self.process_source_create_time(system.hostname, pid)
        if finalized is not None:
            return finalized
        process = self.state_manager.get_process(system.hostname, pid)
        if process is None or pid in seen_pids:
            return None
        next_seen = seen_pids | {pid}
        parent_source_time = (
            self._process_source_frontier_or_bound(
                system=system,
                pid=process.parent_pid,
                seen_pids=next_seen,
            )
            if process.parent_pid > 0 and process.parent_pid != pid
            else None
        )
        session = self.state_manager.get_session(process.logon_id) if process.logon_id else None
        return self._process_create_source_bound(
            system=system,
            canonical_time=process.start_time,
            parent_source_time=parent_source_time,
            session_source_time=(
                _session_source_ready_time(session) if session is not None else None
            ),
        )

    def _profiled_service_manager_parent_pid(
        self,
        *,
        system: System,
        time: datetime,
        family: ServiceProcessFamily,
        existing_only: bool = False,
    ) -> int:
        """Resolve the configured service-control parent for one resident manager."""

        sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        configured = sys_pids.get(family.manager.parent_key)
        if configured and self._is_pid_active_at(system, configured, time):
            return configured
        if existing_only:
            return self._resolve_existing_prepared_process_parent(
                system=system,
                user=self._user_model_for_username(family.manager.username),
                time=time,
                logon_id="0x3e7",
                parent_pid=0,
                process_username=family.manager.username,
            )
        if family.os_category == "windows":
            return self._windows_system_parent_fallback(system, time)
        return self._linux_system_parent_fallback(system, time)

    def _ensure_profiled_service_worker(
        self,
        *,
        system: System,
        worker_time: datetime,
        activity_time: datetime,
        family_name: str,
        worker_name: str,
        source_visible_by: datetime | None = None,
    ) -> int:
        """Create or reuse one worker beneath its exact resident service manager."""

        worker_time = ensure_utc(worker_time)
        activity_time = ensure_utc(activity_time)
        source_deadline = ensure_utc(source_visible_by) if source_visible_by is not None else None
        if source_deadline is not None and worker_time > source_deadline:
            return 0

        family = service_process_family(family_name)
        if family.os_category != _get_os_category(system.os):
            raise ValueError(f"service family {family_name!r} does not support {system.os!r}")
        try:
            worker = family.workers[worker_name]
        except KeyError as exc:
            raise KeyError(
                f"unknown worker {worker_name!r} for service family {family_name!r}"
            ) from exc

        singleton_worker_pid = None
        if source_deadline is not None:
            singleton_worker_pid = self._existing_windows_singleton_service_pid(
                system=system,
                process_name=worker.image,
                time=activity_time,
                username=worker.username,
                command_line=worker.command_line,
            )
            if singleton_worker_pid is not None and not self._process_source_visible_by(
                hostname=system.hostname,
                pid=singleton_worker_pid,
                deadline=source_deadline,
            ):
                # The recursive worker path must not discover this conflict only
                # after publishing a newly materialized service manager.
                return 0

        manager_parent = self._profiled_service_manager_parent_pid(
            system=system,
            time=activity_time,
            family=family,
            existing_only=source_deadline is not None,
        )
        if source_deadline is not None and manager_parent <= 0:
            return 0
        manager_pid = self._active_profiled_service_process(
            system=system,
            time=activity_time,
            spec=family.manager,
            parent_pid=manager_parent,
        )
        manager_source_deadline = (
            source_deadline - timedelta(milliseconds=1) if source_deadline is not None else None
        )
        manager_time = None
        manager_source_time = None
        if manager_pid is not None:
            manager_source_time = self._process_source_frontier_or_bound(
                system=system,
                pid=manager_pid,
            )
            if manager_source_deadline is not None and (
                manager_source_time is None or manager_source_time > manager_source_deadline
            ):
                return 0
        else:
            manager_seed = _stable_seed(
                f"service_process_manager:{system.hostname}:{family_name}:{worker_time.isoformat()}"
            )
            manager_time = worker_time - timedelta(seconds=30 + (manager_seed % 271))
            if manager_source_deadline is not None:
                manager_source_time = self._process_create_source_bound(
                    system=system,
                    canonical_time=manager_time,
                    parent_source_time=self._process_source_frontier_or_bound(
                        system=system,
                        pid=manager_parent,
                    ),
                )
                if manager_source_time > manager_source_deadline:
                    return 0

        worker_pid = (
            self._active_profiled_service_process(
                system=system,
                time=activity_time,
                spec=worker,
                parent_pid=manager_pid,
            )
            if manager_pid is not None
            else None
        )
        if worker_pid is not None and source_deadline is not None:
            if not self._process_source_visible_by(
                hostname=system.hostname,
                pid=worker_pid,
                deadline=source_deadline,
            ):
                return 0
        if (
            source_deadline is not None
            and singleton_worker_pid is None
            and manager_source_time is not None
            and worker_pid is None
        ):
            prospective_worker_time = worker_time
            manager_process = (
                self.state_manager.get_process(system.hostname, manager_pid)
                if manager_pid is not None
                else None
            )
            manager_start_time = (
                manager_process.start_time if manager_process is not None else manager_time
            )
            if manager_start_time is not None:
                earliest_worker_time = manager_start_time + timedelta(milliseconds=1)
                if earliest_worker_time < activity_time:
                    prospective_worker_time = max(
                        prospective_worker_time,
                        earliest_worker_time,
                    )
                else:
                    prospective_worker_time = activity_time
            worker_source_bound = self._process_create_source_bound(
                system=system,
                canonical_time=prospective_worker_time,
                parent_source_time=manager_source_time,
            )
            if worker_source_bound > source_deadline:
                return 0

        if manager_pid is None:
            if manager_time is None:
                raise StateError("Profiled service manager preflight lost its canonical start")
            manager_pid = self.generate_system_process(
                system=system,
                time=manager_time,
                process_name=family.manager.image,
                command_line=family.manager.command_line,
                parent_pid=manager_parent,
                username=family.manager.username,
                emit_linux_syslog=False,
                _profiled_service_bypass=True,
                _skip_singleton_reuse=True,
                source_visible_by=manager_source_deadline,
            )
            if manager_pid <= 0:
                return 0

        if worker_pid is None:
            worker_pid = self._active_profiled_service_process(
                system=system,
                time=activity_time,
                spec=worker,
                parent_pid=manager_pid,
            )
        if worker_pid is None:
            manager_process = self.state_manager.get_process(system.hostname, manager_pid)
            if manager_process is not None:
                earliest_worker_time = manager_process.start_time + timedelta(milliseconds=1)
                if earliest_worker_time < activity_time:
                    worker_time = max(worker_time, earliest_worker_time)
                else:
                    worker_time = activity_time
            worker_pid = self.generate_system_process(
                system=system,
                time=worker_time,
                process_name=worker.image,
                command_line=worker.command_line,
                parent_pid=manager_pid,
                username=worker.username,
                emit_linux_syslog=False,
                _profiled_service_bypass=True,
                source_visible_by=source_visible_by,
            )
            if worker_pid <= 0:
                return 0
        retained_pids = getattr(self, "_system_pids", {}).setdefault(system.hostname, {})
        retained_pids[family.manager.key] = manager_pid
        retained_pids[worker.key] = worker_pid
        return worker_pid

    def _remember_system_connection_owner_finalizer(
        self,
        *,
        source_system: System,
        time: datetime,
        pid: int,
        image: str,
        command_line: str,
        username: str,
        rng: random.Random,
    ) -> None:
        """Bound a one-shot system connection owner and its package frontend."""
        if not self._connection_owner_is_one_shot_network_client(image, command_line):
            return
        os_category = _get_os_category(source_system.os)
        lifetime = (
            _windows_foreground_lifetime(image, command_line)
            if os_category == "windows"
            else _linux_foreground_lifetime(image, command_line)
        )
        if lifetime is None:
            return
        running = self.state_manager.get_process(source_system.hostname, pid)
        process_anchor = max(
            ensure_utc(time),
            ensure_utc(running.start_time) if running is not None else ensure_utc(time),
        )
        termination_time = process_anchor + timedelta(seconds=rng.uniform(*lifetime))
        self._remember_foreground_process_finalizer(
            system=source_system,
            user=User(username=username, full_name=username, email=f"{username}@example.local"),
            pid=pid,
            process_name=image,
            logon_id="0x3e7",
            termination_time=termination_time,
        )

        if not image.lower().startswith("/usr/lib/apt/methods/"):
            return
        helper = running
        active = self._linux_apt_frontends.get(source_system.hostname)
        if helper is None or active is None or helper.parent_pid != active[0]:
            return
        frontend = self.state_manager.get_process(source_system.hostname, active[0])
        if frontend is None:
            return
        frontend_termination = max(
            active[1],
            termination_time + timedelta(milliseconds=rng.randint(120, 1800)),
        )
        self._linux_apt_frontends[source_system.hostname] = (
            frontend.pid,
            frontend_termination,
        )
        self._remember_foreground_process_finalizer(
            system=source_system,
            user=User(username="root", full_name="root", email="root@example.local"),
            pid=frontend.pid,
            process_name=frontend.image,
            logon_id=frontend.logon_id or "0x3e7",
            termination_time=frontend_termination,
        )

    def _ensure_linux_apt_frontend_process(
        self,
        *,
        source_system: System,
        helper_time: datetime,
        rng: random.Random,
    ) -> int:
        """Create or reuse the APT frontend that owns a transport method helper."""
        image = "/usr/bin/apt-get"
        command_line = "apt-get update"
        active = self._linux_apt_frontends.get(source_system.hostname)
        if active is not None and ensure_utc(helper_time) < ensure_utc(active[1]):
            existing_pid = active[0]
            running = self.state_manager.get_process(source_system.hostname, existing_pid)
        else:
            existing_pid = -1
            running = None
        if running is not None:
            process_anchor = max(ensure_utc(helper_time), ensure_utc(running.start_time))
            termination_time = max(
                active[1],
                process_anchor + timedelta(seconds=rng.uniform(35.0, 90.0)),
            )
            self._linux_apt_frontends[source_system.hostname] = (
                existing_pid,
                termination_time,
            )
            self._remember_foreground_process_finalizer(
                system=source_system,
                user=User(username="root", full_name="root", email="root@example.local"),
                pid=existing_pid,
                process_name=image,
                logon_id="0x3e7",
                termination_time=termination_time,
            )
            self.state_manager.update_process_activity_time(
                source_system.hostname,
                existing_pid,
                helper_time,
            )
            return existing_pid

        frontend_time = helper_time - timedelta(milliseconds=rng.randint(80, 650))
        systemd_pid = self._linux_system_parent_fallback(source_system, frontend_time)
        frontend_pid = self.generate_system_process(
            source_system,
            frontend_time,
            image,
            command_line,
            parent_pid=systemd_pid,
            username="root",
            emit_linux_syslog=False,
        )
        if frontend_pid <= 0:
            return systemd_pid
        frontend = self.state_manager.get_process(source_system.hostname, frontend_pid)
        process_anchor = max(
            ensure_utc(helper_time),
            ensure_utc(frontend.start_time) if frontend is not None else ensure_utc(helper_time),
        )
        termination_time = process_anchor + timedelta(seconds=rng.uniform(35.0, 90.0))
        self._linux_apt_frontends[source_system.hostname] = (
            frontend_pid,
            termination_time,
        )
        self._remember_foreground_process_finalizer(
            system=source_system,
            user=User(username="root", full_name="root", email="root@example.local"),
            pid=frontend_pid,
            process_name=image,
            logon_id="0x3e7",
            termination_time=termination_time,
        )
        self.state_manager.update_process_activity_time(
            source_system.hostname,
            frontend_pid,
            helper_time,
        )
        return frontend_pid

    def _active_matching_process_pid(
        self,
        *,
        source_system: System,
        time: datetime,
        key: str,
        image: str,
        username: str,
        command_line: str,
    ) -> int:
        """Return an active process matching a role key or exact image/user owner."""
        sys_pids = getattr(self, "_system_pids", {}).get(source_system.hostname, {})
        candidate_pids = [pid for pid in (sys_pids.get(key),) if pid]
        image_lower = image.lower()
        require_exact_command = self._connection_owner_requires_exact_command_line(
            image,
            command_line,
        )
        require_unique_process = self._connection_owner_requires_unique_transport_process(image)
        for proc in self.state_manager.get_processes_on_system(source_system.hostname):
            if proc.image.lower() == image_lower and proc.username == username:
                if require_exact_command and proc.command_line != command_line:
                    continue
                candidate_pids.append(proc.pid)

        for candidate_pid in candidate_pids:
            if require_unique_process:
                continue
            proc = self.state_manager.get_process(source_system.hostname, candidate_pid)
            if proc is None:
                continue
            if require_exact_command and proc.command_line != command_line:
                continue
            if proc.start_time is not None and ensure_utc(proc.start_time) > ensure_utc(time):
                continue
            if self._process_termination_recorded(
                source_system.hostname,
                candidate_pid,
                proc.start_time,
            ):
                continue
            if self._foreground_process_expired_for_attribution(source_system, proc, time):
                continue
            return candidate_pid
        return -1

    @staticmethod
    def _connection_owner_requires_exact_command_line(
        image: str,
        command_line: str,
    ) -> bool:
        """Return whether a process command line carries per-target network semantics."""
        image_lower = image.lower()
        command_lower = command_line.lower()
        # A literal SMB URI binds any executable—not only generic clients—to
        # one repository peer. Reusing that process for another destination
        # would make its endpoint FLOW contradict its own command line.
        if "smb://" in command_lower:
            return True
        target_bearing_images = {
            "curl",
            "curl.exe",
            "wget",
            "wget.exe",
            "python",
            "python.exe",
            "python3",
            "python3.exe",
            "service-healthcheck",
            "service-healthcheck.exe",
            "ssh",
            "ssh.exe",
            "scp",
            "scp.exe",
            "sftp",
            "sftp.exe",
            "smbclient",
            "gvfsd-smb-browse",
            "java",
            "java.exe",
            "mysqladmin",
        }
        exe = image_lower.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]
        if exe in target_bearing_images:
            return any(
                token in command_lower
                for token in (
                    "--target",
                    "--url",
                    "--check-url",
                    "http://",
                    "https://",
                    "requests.get",
                    "mysqladmin",
                    "ssh ",
                    "ssh.exe ",
                    "scp ",
                    "scp.exe ",
                    "sftp ",
                    "sftp.exe ",
                    "smbclient ",
                )
            )
        return False

    @classmethod
    def _connection_owner_is_one_shot_network_client(
        cls,
        image: str,
        command_line: str,
    ) -> bool:
        """Return whether a connection owner should start near its first network action."""
        normalized_image = image.lower().replace("\\", "/")
        if "/apt/methods/" in normalized_image:
            return True
        return cls._connection_owner_requires_exact_command_line(image, command_line)

    @staticmethod
    def _connection_owner_requires_unique_transport_process(image: str) -> bool:
        """Return whether each transport needs a distinct short-lived client process."""

        executable = image.lower().replace("\\", "/").rsplit("/", 1)[-1]
        return executable in {
            "ssh",
            "ssh.exe",
            "scp",
            "scp.exe",
            "sftp",
            "sftp.exe",
            "smbclient",
        }

    def ensure_smb_client_process(
        self,
        *,
        client_system: System,
        actor: User,
        server: str,
        share: str,
        path: str,
        client_path: str,
        local_path: str = "",
        source_path: str = "",
        destination_path: str = "",
        operation: str,
        time: datetime,
        client_access: str = "auto",
        smb_principal: str | None = None,
        auth_protocol: str = "",
        transfer_direction: Literal["download", "upload", "remote"] | None = None,
        preferred_pid: int = -1,
        source_visible_by: datetime | None = None,
    ) -> SmbClientProcessPlan:
        """Resolve source-native SMB actor and transport ownership.

        A direct ``smbclient`` or desktop GVFS process owns both the operation
        and socket.  A mounted CIFS operation has a normal user-space actor for
        endpoint FILE telemetry, while the TCP/445 transport remains kernel
        attributed (PID ``-1``).  This prevents ``mount.cifs`` from being
        fabricated as the owner of every later file operation.
        """

        os_category = _get_os_category(client_system.os)
        access_mode = {
            "windows_native": "explorer",
            "cifs_mount": "mounted",
            "smbclient": "direct",
        }.get(client_access)
        if os_category == "linux" and access_mode is None:
            service_tokens = {
                service.casefold().replace("_", "-") for service in (client_system.services or ())
            }
            access_mode = (
                "mounted"
                if service_tokens.intersection({"cifs-client", "cifs-utils"})
                else "direct"
            )
        profile = select_client_profile(
            os_category,
            client_system.services or (),
            system_type=client_system.type,
            access_mode=access_mode,
            scope_key=(
                f"{client_system.hostname}:{actor.username}:{server}:{share}:"
                f"{operation}:{time.isoformat()}"
            ),
        )
        process_profile = client_process_for_operation(
            profile,
            operation,
            transfer_direction=transfer_direction,
        )
        if process_profile is None:
            return SmbClientProcessPlan(
                actor_pid=-1,
                actor_image="",
                actor_command_line="",
                transport_pid=-1,
                transport_image="",
                access_mode=profile.access_mode,
                path_style=profile.path_style,
            )
        local_operand = local_path
        if process_profile.operand_mode in {"download", "upload"}:
            local_operand = local_smbclient_operand(
                path,
                local_path or client_path,
            )
        rendered = render_smb_process(
            process_profile,
            server=server,
            share=share,
            path=path,
            client_path=client_path,
            local_path=local_operand,
            source_path=source_path,
            destination_path=destination_path,
            username=actor.username,
            smb_principal=smb_principal or actor.username,
            auth_options=client_auth_options(profile, auth_protocol),
            operation=operation,
            client_ip=client_system.ip,
        )

        actor_pid = preferred_pid if preferred_pid > 0 else -1
        running = (
            self.state_manager.get_process(client_system.hostname, actor_pid)
            if actor_pid > 0
            else None
        )
        if running is not None and not self._process_source_visible_by(
            hostname=client_system.hostname,
            pid=actor_pid,
            deadline=source_visible_by,
        ):
            return SmbClientProcessPlan(
                actor_pid=-1,
                actor_image="",
                actor_command_line="",
                transport_pid=-1,
                transport_image="",
                access_mode=profile.access_mode,
                path_style=profile.path_style,
            )
        if running is None:
            session = self._smb_actor_session(client_system, actor, time)
            if session is not None:
                actor_pid, _actor_image = self._ensure_user_connection_owner_process(
                    source_system=client_system,
                    time=time,
                    service="smb",
                    dst_port=445,
                    os_category=os_category,
                    hostname=server,
                    ssh_attempted_username=None,
                    source_visible_by=source_visible_by,
                    owner_spec=(rendered.image, rendered.command_line),
                    session_info=(actor, session),
                )
                running = self.state_manager.get_process(client_system.hostname, actor_pid)

        actor_image = running.image if running is not None else rendered.image
        actor_command_line = running.command_line if running is not None else rendered.command_line
        if actor_pid > 0 and rendered.lifecycle == "operation":
            lifetime = (
                _windows_foreground_lifetime(actor_image, actor_command_line)
                if os_category == "windows"
                else _linux_foreground_lifetime(actor_image, actor_command_line)
            )
            if lifetime is not None:
                lifetime_rng = random.Random(
                    _stable_seed(
                        "smb-operation-process-lifetime:"
                        f"{client_system.hostname}:{actor_pid}:{time.isoformat()}"
                    )
                )
                self._remember_foreground_process_finalizer(
                    system=client_system,
                    user=actor,
                    pid=actor_pid,
                    process_name=actor_image,
                    logon_id=(running.logon_id if running is not None else ""),
                    termination_time=time + timedelta(seconds=lifetime_rng.uniform(*lifetime)),
                )

        transport_pid = actor_pid if profile.transport_attribution == "process" else -1
        transport_image = actor_image if transport_pid > 0 else ""
        return SmbClientProcessPlan(
            actor_pid=actor_pid,
            actor_image=actor_image,
            actor_command_line=actor_command_line,
            transport_pid=transport_pid,
            transport_image=transport_image,
            access_mode=profile.access_mode,
            path_style=profile.path_style,
        )

    def _smb_actor_session(
        self,
        system: System,
        actor: User,
        time: datetime,
    ) -> ActiveSession | None:
        """Return the newest local/interactive session that can own SMB work."""

        candidates = [
            session
            for session in self.state_manager.get_sessions_for_user_at(actor.username, time)
            if session.system == system.hostname
            and session.logon_type in {2, 7, 10, 11}
            and _session_started_by(session, time)
            and not self._workstation_logon_locked_at(
                system,
                actor.username,
                session.logon_id,
                time,
            )
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda session: ensure_utc(session.start_time))

    def _ensure_user_connection_owner_process(
        self,
        *,
        source_system: System,
        time: datetime,
        service: str | None,
        dst_port: int,
        os_category: str,
        hostname: str | None,
        ssh_attempted_username: str | None,
        source_visible_by: datetime | None = None,
        owner_spec: tuple[str, str] | None = None,
        session_info: tuple[User, Any] | None = None,
    ) -> tuple[int, str | None]:
        """Create or reuse a user process for high-confidence workstation flows."""
        session_info = session_info or self._select_explicit_proxy_client_session(
            source_system,
            time,
        )
        if session_info is None:
            return -1, None
        user, session = session_info
        spec = owner_spec
        if spec is None and ((service or "").casefold() == "smb" or dst_port == 445):
            profile = select_client_profile(
                os_category,
                source_system.services or (),
                system_type=source_system.type,
                scope_key=(
                    f"generic:{source_system.hostname}:{user.username}:"
                    f"{hostname or 'internal-host'}:{time.isoformat()}"
                ),
            )
            if profile.transport_attribution != "process":
                return -1, None
            process_profile = client_process_for_operation(profile, "browse")
            if process_profile is not None:
                rendered = render_smb_process(
                    process_profile,
                    server=hostname or "internal-host",
                    share="shared",
                    path="",
                    client_path="/mnt/shared",
                    username=user.username,
                    smb_principal=user.username,
                    auth_options=client_auth_options(profile, "auto"),
                    operation="browse",
                    client_ip=source_system.ip,
                )
                spec = (rendered.image, rendered.command_line)
        spec = spec or self._user_connection_owner_spec(
            service=service,
            dst_port=dst_port,
            os_category=os_category,
            hostname=hostname,
            ssh_attempted_username=ssh_attempted_username,
        )
        if spec is None:
            return -1, None
        image, command_line = spec

        image_lower = image.lower()
        image_exe = image_lower.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]
        resident_resource_owner = image_exe == "gvfsd-smb-browse"
        require_exact_command = self._connection_owner_requires_exact_command_line(
            image,
            command_line,
        )
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(source_system.hostname)
            if proc.username == user.username
            and proc.logon_id == session.logon_id
            and proc.image.lower() == image_lower
            and (not require_exact_command or proc.command_line == command_line)
            and proc.start_time is not None
            and ensure_utc(proc.start_time) <= ensure_utc(time)
            and not self._foreground_process_expired_for_attribution(source_system, proc, time)
            and not self._connection_owner_requires_unique_transport_process(proc.image)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            if not self._process_source_visible_by(
                hostname=source_system.hostname,
                pid=proc.pid,
                deadline=source_visible_by,
            ):
                return -1, None
            self.state_manager.update_process_activity_time(
                source_system.hostname,
                proc.pid,
                time,
            )
            return proc.pid, proc.image

        singleton_claim: (
            tuple[
                tuple[str, str, str, str],
                datetime,
                datetime,
            ]
            | None
        ) = None
        if resident_resource_owner:
            resource_key = self._singleton_application_key(
                source_system,
                user.username,
                session.logon_id,
                f"{image}|{command_line}",
            )
            provisional_end = (
                self.state_manager.get_session_end_time(session.logon_id) or self._scenario_end_time
            )
            if not self.claim_singleton_application_interval(
                resource_key,
                ensure_utc(session.start_time),
                provisional_end,
            ):
                return -1, None
            singleton_claim = (
                resource_key,
                ensure_utc(session.start_time),
                provisional_end,
            )

        process_rng = random.Random(
            _stable_seed(
                "high_confidence_user_connection_owner:"
                f"{source_system.hostname}:{user.username}:{image}:{time.isoformat()}"
            )
        )
        if resident_resource_owner:
            process_time = ensure_utc(session.start_time) + timedelta(
                milliseconds=500
                + _stable_seed(
                    f"resident_resource_bootstrap:{source_system.hostname}:"
                    f"{user.username}:{session.logon_id}:{command_line}"
                )
                % 2500
            )
        else:
            process_lifetime = (
                _windows_foreground_lifetime(image, command_line)
                if os_category == "windows"
                else _linux_foreground_lifetime(image, command_line)
            )
            if process_lifetime is None:
                lead_seconds = process_rng.uniform(3.0, 30.0)
            else:
                lead_seconds = process_rng.uniform(0.4, min(8.0, process_lifetime[1]))
            process_time = time - timedelta(seconds=lead_seconds)
        min_process_time = ensure_utc(session.start_time) + timedelta(milliseconds=500)
        if process_time < min_process_time:
            process_time = min_process_time
        if process_time >= time:
            process_time = time - timedelta(milliseconds=100)

        windows_cli_owner = os_category == "windows" and image_exe in {
            "ssh.exe",
            "scp.exe",
            "sftp.exe",
        }
        parent_pid = (
            0
            if windows_cli_owner
            else self._select_parent_pid(
                source_system,
                user,
                image,
                time=process_time,
                logon_id=session.logon_id,
            )
        )
        if windows_cli_owner:
            parent_pid = self._ensure_windows_user_cli_parent(
                system=source_system,
                user=user,
                session=session,
                child_time=process_time,
                candidate_pid=parent_pid,
                child_process_name=image,
                child_command_line=command_line,
                source_visible_by=source_visible_by,
            )
            if parent_pid <= 0:
                return -1, None
        elif os_category == "linux" and not resident_resource_owner:
            prepared_owner = self._prepare_linux_foreground_connection_owner(
                system=source_system,
                user=user,
                session=session,
                process_time=process_time,
                activity_time=time,
                process_name=image,
                command_line=command_line,
                source_visible_by=source_visible_by,
            )
            if prepared_owner is None:
                return -1, None
            parent_pid, process_time = prepared_owner
        elif os_category == "linux":
            parent_pid = (
                self._linux_non_shell_session_parent_pid(
                    system=source_system,
                    time=process_time,
                    logon_id=session.logon_id,
                )
                or parent_pid
            )
        pid = self.generate_process(
            user=user,
            system=source_system,
            time=process_time,
            logon_id=session.logon_id,
            process_name=image,
            command_line=command_line,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            allow_existing_browser_reuse=False,
            allow_browser_launch_spacing=False,
            source_visible_by=source_visible_by,
        )
        if pid <= 0:
            if singleton_claim is not None:
                self._cancel_singleton_application_interval(*singleton_claim)
            return -1, None
        self._record_user_process(source_system, user, pid, image)
        self.state_manager.update_process_activity_time(source_system.hostname, pid, time)
        self.state_manager.set_current_time(time)
        running = self.state_manager.get_process(source_system.hostname, pid)
        if running is not None:
            return pid, running.image
        return pid, image

    def _ensure_windows_user_cli_parent(
        self,
        *,
        system: System,
        user: User,
        session: Any,
        child_time: datetime,
        candidate_pid: int,
        child_command_line: str,
        child_process_name: str = "",
        source_visible_by: datetime | None = None,
    ) -> int:
        """Return a visible interactive shell for a user-owned Windows CLI process."""

        command_exe = child_command_line.strip().split(maxsplit=1)[0].strip('"').lower()
        requires_dedicated_shell = command_exe in {
            "ssh",
            "ssh.exe",
            "scp",
            "scp.exe",
            "sftp",
            "sftp.exe",
        }
        candidate = self.state_manager.get_process(system.hostname, candidate_pid)
        if candidate is not None and not requires_dedicated_shell:
            candidate_exe = ntpath.basename(candidate.image).lower()
            if (
                candidate_exe in self._WINDOWS_SHELL_NAMES
                and candidate.logon_id == session.logon_id
                and self._is_pid_active_at(system, candidate.pid, child_time)
                and not self._is_one_shot_shell_parent(system, candidate.pid)
                and not self._shell_has_active_foreground_child(
                    system,
                    candidate.pid,
                    child_time,
                )
            ):
                if not self._process_source_visible_by(
                    hostname=system.hostname,
                    pid=candidate.pid,
                    deadline=source_visible_by,
                ):
                    return 0
                return candidate.pid

        shell_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(system.hostname)
            if ntpath.basename(proc.image).lower() in self._WINDOWS_SHELL_NAMES
            and proc.username == user.username
            and proc.logon_id == session.logon_id
            and self._is_pid_active_at(system, proc.pid, child_time)
            and not self._is_one_shot_shell_parent(system, proc.pid)
            and not self._shell_has_active_foreground_child(system, proc.pid, child_time)
        ]
        if shell_candidates and not requires_dedicated_shell:
            shell = max(shell_candidates, key=lambda proc: proc.start_time)
            if not self._process_source_bound_visible_by(
                system=system,
                pid=shell.pid,
                deadline=source_visible_by,
            ):
                return 0
            return shell.pid

        shell_seed = _stable_seed(
            f"windows-user-cli-parent:{system.hostname}:{user.username}:"
            f"{session.logon_id}:{child_command_line}"
        )
        shell_image = (
            r"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe"
            if shell_seed % 3
            else r"C:\Windows\System32\cmd.exe"
        )
        shell_command = ntpath.basename(shell_image)
        session_floor = ensure_utc(session.start_time) + timedelta(milliseconds=100)
        lead_ms = 1200 + shell_seed % 4801
        shell_time = max(session_floor, ensure_utc(child_time) - timedelta(milliseconds=lead_ms))
        if shell_time >= ensure_utc(child_time):
            shell_time = ensure_utc(child_time) - timedelta(milliseconds=100)
        shell_deadline = (
            min(ensure_utc(source_visible_by), ensure_utc(child_time) - timedelta(milliseconds=1))
            if source_visible_by is not None
            else None
        )
        if shell_deadline is not None:
            source_bound = self._windows_user_cli_parent_source_bound(
                system=system,
                user=user,
                session=session,
                shell_time=shell_time,
                shell_image=shell_image,
                shell_command=shell_command,
            )
            if source_bound is None or source_bound > shell_deadline:
                return 0
            if child_process_name:
                child_request = ProcessExecutionRequest(
                    user=user,
                    system=system,
                    time=child_time,
                    logon_id=session.logon_id,
                    process_name=child_process_name,
                    command_line=child_command_line,
                    parent_pid=0,
                    suppress_command_file_effect=True,
                    allow_existing_browser_reuse=False,
                    allow_browser_launch_spacing=False,
                    source_visible_by=source_visible_by,
                )
                child_actor = self._prepare_process_effect_actor(child_request)
                child_source_bound = self._process_create_source_bound(
                    system=system,
                    canonical_time=child_actor.started_at,
                    parent_source_time=source_bound,
                    session_source_time=_session_source_ready_time(session),
                )
                if child_source_bound > ensure_utc(source_visible_by):
                    return 0
        explorer_pid = self._ensure_session_explorer_pid(
            system,
            user,
            time=shell_time,
            logon_id=session.logon_id,
        )
        parent_pid = explorer_pid or self._windows_explorer_parent_pid(
            system,
            user,
            shell_time,
            session.logon_id,
        )
        shell_pid = self.generate_process(
            user=user,
            system=system,
            time=shell_time,
            logon_id=session.logon_id,
            process_name=shell_image,
            command_line=shell_command,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            allow_existing_browser_reuse=False,
            allow_browser_launch_spacing=False,
            source_visible_by=shell_deadline,
        )
        if shell_pid <= 0:
            return 0
        self._record_user_process(system, user, shell_pid, shell_image)
        return shell_pid

    def _windows_user_cli_parent_source_bound(
        self,
        *,
        system: System,
        user: User,
        session: ActiveSession,
        shell_time: datetime,
        shell_image: str,
        shell_command: str,
    ) -> datetime | None:
        """Return the allocation-free source frontier for Explorer plus one CLI shell."""

        session_source_time = _session_source_ready_time(session)
        explorer_pid = self._get_session_explorer_pid(
            system,
            user,
            time=shell_time,
            logon_id=session.logon_id,
        )
        if explorer_pid is not None:
            explorer = self.state_manager.get_process(system.hostname, explorer_pid)
            explorer_source = self._process_source_frontier_or_bound(
                system=system,
                pid=explorer_pid,
            )
            if explorer is None or explorer_source is None:
                return None
            request = ProcessExecutionRequest(
                user=user,
                system=system,
                time=shell_time,
                logon_id=session.logon_id,
                process_name=shell_image,
                command_line=shell_command,
                parent_pid=explorer_pid,
                suppress_command_file_effect=True,
                allow_existing_browser_reuse=False,
                allow_browser_launch_spacing=False,
                source_visible_by=shell_time,
            )
            actor = self._prepare_process_effect_actor(request)
            return self._process_create_source_bound(
                system=system,
                canonical_time=actor.started_at,
                parent_source_time=explorer_source,
                session_source_time=session_source_time,
            )

        sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        root_pid = next(
            (
                pid
                for role in ("smss", "wininit", "winlogon", "services")
                if (pid := sys_pids.get(role)) and self._is_pid_active_at(system, pid, shell_time)
            ),
            None,
        )
        if root_pid is None:
            return None
        chain_time = max(ensure_utc(session.start_time), shell_time - timedelta(seconds=1))
        winlogon_pid = session.session_winlogon_pid
        if winlogon_pid is not None and self._is_pid_active_at(system, winlogon_pid, shell_time):
            winlogon_source = self._process_source_frontier_or_bound(
                system=system,
                pid=winlogon_pid,
            )
        else:
            winlogon_source = self._process_create_source_bound(
                system=system,
                canonical_time=chain_time,
                parent_source_time=self._process_source_frontier_or_bound(
                    system=system,
                    pid=root_pid,
                ),
            )
        if winlogon_source is None:
            return None
        userinit_time = chain_time + timedelta(
            milliseconds=80
            + (
                _stable_seed(
                    "windows_session_userinit_start:"
                    f"{system.hostname}:{session.logon_id}:{chain_time.isoformat()}"
                )
                % 171
            )
        )
        userinit_source = self._process_create_source_bound(
            system=system,
            canonical_time=userinit_time,
            parent_source_time=winlogon_source,
            session_source_time=session_source_time,
        )
        explorer_time = userinit_time + timedelta(
            milliseconds=150
            + (
                _stable_seed(
                    "windows_session_explorer_start:"
                    f"{system.hostname}:{session.logon_id}:{chain_time.isoformat()}"
                )
                % 251
            )
        )
        explorer_source = self._process_create_source_bound(
            system=system,
            canonical_time=explorer_time,
            parent_source_time=userinit_source,
            session_source_time=session_source_time,
        )
        latest_shell_time = max(shell_time, explorer_time + timedelta(milliseconds=499))
        return self._process_create_source_bound(
            system=system,
            canonical_time=latest_shell_time,
            parent_source_time=explorer_source,
            session_source_time=session_source_time,
        )

    def _shell_has_active_foreground_child(
        self,
        system: System,
        shell_pid: int,
        activity_time: datetime,
    ) -> bool:
        """Return whether a shell is blocked by an ordinary foreground child."""
        os_category = _get_os_category(system.os)
        for process in self.state_manager.get_processes_on_system(system.hostname):
            if process.parent_pid != shell_pid or process.start_time > activity_time:
                continue
            lifetime = (
                _windows_foreground_lifetime(process.image, process.command_line)
                if os_category == "windows"
                else _linux_foreground_lifetime(process.image, process.command_line)
            )
            if lifetime is not None:
                return True
        return False

    @staticmethod
    def _user_connection_owner_spec(
        *,
        service: str | None,
        dst_port: int,
        os_category: str,
        hostname: str | None,
        ssh_attempted_username: str | None = None,
    ) -> tuple[str, str] | None:
        """Return user-process metadata for source-owned workstation connections."""
        service_name = (service or "").lower()
        target = hostname or "internal-host"
        if os_category == "windows":
            if service_name == "ssh" or dst_port == 22:
                image = r"C:\Windows\System32\OpenSSH\ssh.exe"
                return image, f"ssh.exe {_ssh_command_target(target, ssh_attempted_username)}"
            if service_name == "smb" or dst_port == 445:
                image = r"C:\Windows\explorer.exe"
                return image, rf"explorer.exe \\{target}\shared"
            return None
        if os_category == "linux":
            if service_name == "ssh" or dst_port == 22:
                image = "/usr/bin/ssh"
                return image, f"ssh {_ssh_command_target(target, ssh_attempted_username)}"
            if service_name == "smb" or dst_port == 445:
                image = "/usr/bin/gvfsd-smb-browse"
                return image, f"gvfsd-smb-browse smb://{target}/shared"
            return None
        return None

    def _build_dc_host_context(self, dc_hostname: str) -> HostContext:
        """Build a HostContext for a domain controller from raw hostname string.

        DC methods receive raw strings (not System objects). Constructs a
        HostContext suitable for Windows event rendering (Computer field).
        """
        ad_domain = getattr(self, "_ad_domain", "corp.local")
        return HostContext(
            hostname=dc_hostname,
            ip="",
            os="Windows Server 2019",
            os_category="windows",
            system_type="domain_controller",
            domain=ad_domain,
            fqdn=f"{dc_hostname}.{ad_domain}" if ad_domain else dc_hostname,
            netbios_domain=ad_domain.split(".")[0].upper() if ad_domain else "CORP",
        )

    def _proxy_fqdn(self, proxy_sys: "System") -> str:
        """Return the FQDN used to route proxy access logs."""
        proxy_fqdn = getattr(proxy_sys, "hostname", "")
        ad_domain = getattr(self, "_ad_domain", "")
        if ad_domain and "." not in proxy_fqdn:
            proxy_fqdn = f"{proxy_fqdn}.{ad_domain}"
        return proxy_fqdn

    def set_proxy_auth_session_deadlines(
        self,
        deadlines: dict[tuple[str, str], datetime],
    ) -> None:
        """Publish planned visible session-end times for proxy username attribution."""

        self._proxy_auth_session_deadlines = {
            key: ensure_utc(value) for key, value in deadlines.items()
        }

    def _proxy_username_for_source(
        self,
        *,
        source_system: Optional["System"],
        user_agent: str,
        cache_result: str,
        hostname: str | None = None,
        time: datetime | None = None,
    ) -> str:
        """Return the source-native authenticated proxy username for a client request."""
        if source_system is None or cache_result.upper() == "AUTH_REQUIRED":
            return ""

        auth_policy = getattr(self, "_proxy_auth_policy", ProxyAuthPolicyConfig())
        netbios_domain = getattr(self, "_netbios_domain", "") or "CORP"
        os_category = _get_os_category(getattr(source_system, "os", ""))
        short_hostname = str(getattr(source_system, "hostname", "") or "").split(".", 1)[0]

        def _service_principal(seed: int) -> str:
            service_accounts = list(getattr(self, "_proxy_service_accounts", []) or [])
            if not service_accounts:
                return ""
            service_account = service_accounts[seed % len(service_accounts)]
            if os_category == "windows":
                return f"{netbios_domain}\\{service_account}"
            ad_domain = getattr(self, "_ad_domain", "")
            return f"{service_account}@{ad_domain}" if ad_domain else service_account

        domain_class = get_proxy_domain_class(hostname or "") if hostname else None
        if (
            auth_policy.mode == "realistic"
            and domain_class
            and domain_class.lower() in set(auth_policy.allowlisted_domain_classes)
        ):
            if not auth_policy.non_human_principals:
                return ""
            roll_seed = _stable_seed(
                "proxy_auth_non_human:"
                f"{getattr(source_system, 'hostname', '')}:"
                f"{hostname or ''}:"
                f"{user_agent}:"
                f"{cache_result}"
            )
            roll = (roll_seed % 1_000_000) / 1_000_000.0
            machine_cutoff = auth_policy.machine_account_probability
            service_cutoff = machine_cutoff + auth_policy.service_account_probability
            if roll < machine_cutoff and os_category == "windows" and short_hostname:
                return f"{netbios_domain}\\{short_hostname}$"
            if roll < service_cutoff:
                return _service_principal(roll_seed)
            return ""

        assigned_user = getattr(source_system, "assigned_user", None)
        if not assigned_user or assigned_user in _SYSTEM_ACCOUNTS or assigned_user.endswith("$"):
            return ""

        system_type = (getattr(source_system, "type", "") or "").lower()
        if system_type != "workstation":
            return ""

        if time is not None:
            current_time = ensure_utc(time)
            source_hostname = getattr(source_system, "hostname", "")
            sessions_at_time = self.state_manager.get_sessions_for_user_at(
                assigned_user,
                current_time,
            )
            has_active_user_session = any(
                session.system == source_hostname
                and session.logon_type in {2, 7, 10, 11}
                and ensure_utc(session.start_time) <= current_time
                for session in sessions_at_time
            )
            if not has_active_user_session:
                return ""

            deadline = self._proxy_auth_session_deadlines.get((source_hostname, assigned_user))
            if deadline is not None and ensure_utc(time) >= deadline:
                newer_session_started = any(
                    session.system == source_hostname
                    and ensure_utc(session.start_time) > deadline
                    and ensure_utc(session.start_time) <= current_time
                    for session in sessions_at_time
                )
                if not newer_session_started:
                    return ""

        if os_category == "windows":
            if _is_machine_context_proxy_user_agent(user_agent):
                if auth_policy.mode == "realistic" and not auth_policy.non_human_principals:
                    return ""
                if auth_policy.mode == "realistic":
                    machine_roll_seed = _stable_seed(
                        "proxy_auth_machine:"
                        f"{getattr(source_system, 'hostname', '')}:"
                        f"{hostname or ''}:"
                        f"{user_agent}:"
                        f"{cache_result}"
                    )
                    machine_roll = (machine_roll_seed % 1_000_000) / 1_000_000.0
                    machine_cutoff = auth_policy.machine_account_probability
                    service_cutoff = machine_cutoff + auth_policy.service_account_probability
                    if machine_roll >= service_cutoff:
                        return ""
                    if machine_roll >= machine_cutoff:
                        return _service_principal(machine_roll_seed)
                if short_hostname:
                    return f"{netbios_domain}\\{short_hostname}$"
            return f"{netbios_domain}\\{assigned_user}"

        ad_domain = getattr(self, "_ad_domain", "")
        if ad_domain:
            return f"{assigned_user}@{ad_domain}"
        return assigned_user

    def _proxy_user_agent_for_context(
        self,
        rng: random.Random,
        source_system: Optional["System"],
        *,
        hostname: str | None,
        domain_tags: list[str] | None,
        existing_user_agent: str = "",
        override_user_agent: str | None = None,
        apply_domain_override: bool = True,
        source_identity: str | None = None,
    ) -> str:
        """Return a source-sticky proxy User-Agent for one logical client context."""

        def normalize_selected_user_agent(
            selected_user_agent: str,
            normalizer_rng: random.Random = rng,
        ) -> str:
            normalized = normalize_proxy_user_agent_for_os(
                normalizer_rng,
                source_system,
                selected_user_agent,
                hostname=hostname,
                domain_tags=domain_tags,
            )
            if self._is_proxy_server_like_source(
                source_system
            ) and _is_browser_family_http_user_agent(normalized):
                return normalize_proxy_user_agent_for_os(
                    normalizer_rng,
                    source_system,
                    "Go-http-client/1.1",
                    hostname=hostname,
                    domain_tags=domain_tags,
                )
            return normalized

        host = hostname or ""
        host_is_browser_like = is_browser_like_proxy_domain(host, domain_tags=domain_tags)
        existing_is_browser_family = _is_browser_family_http_user_agent(existing_user_agent)
        browser_identity_scope = host_is_browser_like or existing_is_browser_family
        if apply_domain_override:
            domain_user_agent = pick_proxy_domain_user_agent(
                rng,
                source_system,
                hostname=hostname,
            )
            if domain_user_agent:
                return normalize_selected_user_agent(domain_user_agent)

        if override_user_agent:
            return normalize_selected_user_agent(override_user_agent)

        if existing_user_agent and existing_is_browser_family and source_system is None:
            return normalize_selected_user_agent(existing_user_agent)

        if existing_user_agent and not existing_is_browser_family:
            return normalize_selected_user_agent(existing_user_agent)

        domain_class = get_proxy_domain_class(host) or ""
        source_key = source_identity or "unknown"
        os_category = ""
        if source_system is not None:
            os_category = _get_os_category(getattr(source_system, "os", ""))
            roles = ",".join(sorted(str(role) for role in (source_system.roles or [])))
            source_key = (
                f"{getattr(source_system, 'hostname', '')}:"
                f"{getattr(source_system, 'ip', '')}:"
                f"{getattr(source_system, 'os', '')}:"
                f"{getattr(source_system, 'type', '')}:{roles}"
            )

        if self._is_proxy_server_like_source(source_system):
            scope = "server:generic"
        elif browser_identity_scope:
            scope = f"{os_category or 'unknown'}:browser"
        elif domain_class:
            scope = f"class:{domain_class}"
        else:
            scope = f"{os_category or 'unknown'}:tooling"

        stable_rng = random.Random(_stable_seed(f"proxy_ua_context:{source_key}:{scope}"))
        user_agent = pick_proxy_user_agent(
            stable_rng,
            source_system,
            hostname=host,
            domain_tags=domain_tags,
        )
        if (
            source_system is not None
            and str(getattr(source_system, "type", "") or "").lower() == "workstation"
            and browser_identity_scope
        ):
            for _ in range(12):
                if not _is_tool_http_user_agent(user_agent):
                    break
                user_agent = pick_proxy_user_agent(
                    stable_rng,
                    source_system,
                    hostname=host,
                    domain_tags=domain_tags,
                )
        return normalize_selected_user_agent(user_agent, stable_rng)

    def _build_proxy_context(
        self,
        *,
        src_ip: str,
        dst_ip: str,
        dst_port: int,
        service: str | None,
        duration: float | None,
        orig_bytes: int | None,
        resp_bytes: int | None,
        hostname: str | None,
        source_system: Optional["System"],
        proxy_sys: "System",
        http: Optional["HttpContext"] = None,
        explicit_mode: bool = False,
        time: datetime | None = None,
    ) -> ProxyContext:
        """Build a proxy access context from the logical origin request."""
        rng = _get_rng()
        proxy_hostname = hostname
        if proxy_hostname is None:
            proxy_hostname = self._scenario_fqdn_for_ip(dst_ip) or REVERSE_DNS.get(dst_ip)
        if proxy_hostname is None:
            proxy_hostname = _generate_random_hostname(rng, dst_ip)
        if proxy_hostname == "":
            proxy_hostname = dst_ip

        from evidenceforge.generation.activity.dns_registry import get_domain_tags
        from evidenceforge.generation.activity.proxy_uri import (
            is_browser_like_proxy_domain,
            pick_proxy_uri,
            plaintext_http_redirect_status,
        )
        from evidenceforge.generation.activity.referrer import pick_referrer

        domain_tags = get_domain_tags(proxy_hostname)
        proxy_ua_override = None
        if http is not None:
            from evidenceforge.generation.activity.http_content import normalize_mime_type_for_path

            scheme = "https" if dst_port == 443 or service == "ssl" else "http"
            proxy_method = http.method
            url = f"{scheme}://{proxy_hostname}{http.uri}"
            if http.resp_mime_types or http.status_code == 304:
                proxy_content_type = normalize_mime_type_for_path(
                    http.uri,
                    http.resp_mime_types[0] if http.resp_mime_types else "text/html",
                )
            else:
                proxy_content_type = "text/html"
            user_agent = http.user_agent
            proxy_referrer = http.referrer
            if _is_browser_family_http_user_agent(user_agent):
                proxy_ua_override = user_agent
        elif explicit_mode and dst_port == 443:
            proxy_method = "CONNECT"
            url = f"{proxy_hostname}:443"
            proxy_content_type = ""
            proxy_referrer = ""
            user_agent = ""
        else:
            source_os = _get_os_category(source_system.os) if source_system else None
            (
                path,
                proxy_content_type,
                proxy_method,
                proxy_ua_override,
                referrer_policy,
            ) = pick_proxy_uri(
                rng,
                proxy_hostname,
                domain_tags,
                source_os=source_os,
                source_system_type=getattr(source_system, "type", None),
                allow_canonical_protocol_templates=False,
            )
            scheme = "https" if dst_port == 443 or service == "ssl" else "http"
            url = f"{scheme}://{proxy_hostname}{path}"
            proxy_referrer = (
                ""
                if referrer_policy == "none"
                else pick_referrer(rng, proxy_hostname, context="general", port=dst_port)
            )
            user_agent = ""

        redirect_status = plaintext_http_redirect_status(
            proxy_hostname,
            port=dst_port,
            path=http.uri if http is not None else _origin_form_uri_from_proxy_url(url),
            dst_ip=dst_ip,
        )
        if redirect_status is not None and http is None:
            proxy_content_type = "text/html"

        apply_domain_user_agent = http is None or (
            not getattr(http, "user_agent_known_absent", False)
            and not _is_tool_http_user_agent(http.user_agent)
            and not is_browser_like_proxy_domain(proxy_hostname, domain_tags=domain_tags)
        )
        if http is not None and getattr(http, "user_agent_known_absent", False):
            user_agent = ""
        else:
            user_agent = self._proxy_user_agent_for_context(
                rng,
                source_system,
                hostname=proxy_hostname,
                domain_tags=domain_tags,
                existing_user_agent=user_agent,
                override_user_agent=proxy_ua_override,
                apply_domain_override=apply_domain_user_agent,
            )
        proxy_referrer = _source_native_http_referrer(
            user_agent,
            proxy_referrer,
            request_scheme="https" if dst_port == 443 or service == "ssl" else "http",
            request_port=dst_port,
        )

        proxy_cacheable = _proxy_request_allows_cache_hit(
            method=proxy_method,
            url=url,
            content_type=proxy_content_type,
            domain_tags=domain_tags,
        )
        if http is not None:
            from evidenceforge.generation.activity.http_content import infer_mime_type_from_path

            response_mime = proxy_content_type or infer_mime_type_from_path(url)
            proxy_cacheable = _proxy_request_allows_cache_hit(
                method=proxy_method,
                url=url,
                content_type=response_mime,
                domain_tags=domain_tags,
            )
        if explicit_mode and dst_port == 443:
            proxy_cacheable = False

        cache_roll = rng.random()
        if http is not None:
            # When the request already carries canonical HTTP outcome data,
            # proxy rendering should not independently invent a policy denial.
            if http.status_code == 304:
                cache_result = "REVALIDATED"
            elif proxy_cacheable and cache_roll < 0.30 and http.status_code < 400:
                cache_result = "HIT"
            else:
                cache_result = "MISS"
        elif explicit_mode and proxy_method == "CONNECT":
            if cache_roll < 0.88:
                cache_result = "NONE"
            elif cache_roll < 0.925:
                cache_result = "DENIED"
            elif cache_roll < 0.965:
                cache_result = "AUTH_REQUIRED"
            else:
                cache_result = "GATEWAY_ERROR"
        elif proxy_cacheable and cache_roll < 0.30:
            cache_result = "HIT"
        elif cache_roll < 0.95:
            cache_result = "MISS"
        else:
            cache_result = "DENIED"

        policy_status_code = (
            redirect_status
            if redirect_status is not None
            and cache_result not in {"DENIED", "AUTH_REQUIRED", "GATEWAY_ERROR"}
            else None
        )
        if policy_status_code is not None and http is None:
            from evidenceforge.generation.activity.http_content import response_size_for_status

            response_bytes = response_size_for_status(
                policy_status_code,
                proxy_hostname,
                _origin_form_uri_from_proxy_url(url),
            )
        else:
            response_bytes = http.response_body_len if http is not None else (resp_bytes or 0)
        cs_bytes = (orig_bytes or 0) + rng.randint(*_PROXY_CS_OVERHEAD)
        if cache_result == "DENIED":
            sc_bytes = rng.randint(500, 2000)
        elif cache_result == "AUTH_REQUIRED":
            sc_bytes = rng.randint(300, 1200)
        elif cache_result == "GATEWAY_ERROR":
            sc_bytes = rng.randint(250, 1800)
        elif cache_result == "HIT":
            sc_bytes = response_bytes + rng.randint(*_PROXY_SC_OVERHEAD)
        elif proxy_method == "CONNECT":
            host_len = len(proxy_hostname)
            cs_bytes = rng.randint(180 + host_len, 520 + host_len)
            sc_bytes = rng.randint(90, 260)
        else:
            sc_bytes = response_bytes + rng.randint(*_PROXY_SC_OVERHEAD)

        if (
            explicit_mode
            and proxy_method == "CONNECT"
            and cache_result
            in {
                "DENIED",
                "AUTH_REQUIRED",
                "GATEWAY_ERROR",
            }
        ):
            host_len = len(proxy_hostname)
            cs_bytes = rng.randint(180 + host_len, 520 + host_len)

        status_code = (
            http.status_code
            if http is not None
            else policy_status_code
            if policy_status_code is not None
            else {
                "DENIED": 403,
                "AUTH_REQUIRED": 407,
                "GATEWAY_ERROR": rng.choice([502, 503, 504]),
            }.get(cache_result, 200)
        )
        time_taken = _proxy_time_taken_ms(
            duration,
            rng,
            method=proxy_method,
            status_code=status_code,
            cache_result=cache_result,
            timing_runtime=self.timing_runtime,
            stable_id=(
                f"{source_system.hostname if source_system is not None else src_ip}:"
                f"{proxy_hostname}:{proxy_method}:{status_code}:{url}"
            ),
        )
        request_body_bytes = 0
        if proxy_method not in {"GET", "HEAD", "CONNECT", "OPTIONS"}:
            request_body_bytes = (
                max(0, http.request_body_len) if http is not None else max(0, orig_bytes or 0)
            )
        if proxy_method == "HEAD" or status_code in {204, 304}:
            response_body_bytes = 0
        elif proxy_method == "CONNECT" and status_code < 400:
            response_body_bytes = 0
        elif http is not None and http.status_code == status_code:
            response_body_bytes = max(0, http.response_body_len)
        elif status_code >= 400:
            response_body_bytes = max(0, sc_bytes - rng.randint(120, min(320, sc_bytes)))
        else:
            response_body_bytes = max(0, response_bytes)

        return ProxyContext(
            client_ip=src_ip,
            username=self._proxy_username_for_source(
                source_system=source_system,
                user_agent=user_agent,
                cache_result=cache_result,
                hostname=proxy_hostname,
                time=time,
            ),
            method=proxy_method,
            url=url,
            host=proxy_hostname,
            status_code=status_code,
            tunnel_status_code=200
            if explicit_mode and dst_port == 443 and proxy_method != "CONNECT"
            else status_code,
            sc_bytes=sc_bytes,
            cs_bytes=cs_bytes,
            time_taken=time_taken,
            request_body_bytes=request_body_bytes,
            response_body_bytes=response_body_bytes,
            user_agent=user_agent,
            content_type=proxy_content_type,
            cache_result=cache_result,
            referrer=proxy_referrer,
            proxy_fqdn=self._proxy_fqdn(proxy_sys),
            proxy_action=_proxy_action_for_context(
                method=proxy_method,
                url=url,
                status_code=status_code,
                cache_result=cache_result,
                dst_port=dst_port,
                explicit_mode=explicit_mode,
            ),
        )

    def _explicit_proxy_client_process_hint(
        self,
        *,
        user_agent: str,
        hostname: str,
        dst_port: int,
        proxy_sys: System,
        source_system: System | None = None,
    ) -> tuple[str, str] | None:
        """Map user-owned proxy User-Agents to the process that owns the socket."""
        os_category = _get_os_category(source_system.os) if source_system is not None else "windows"
        server_like_source = self._is_proxy_server_like_source(source_system)
        if os_category == "windows" and not server_like_source:
            browser_hint = self._browser_http_client_process_hint(
                user_agent=user_agent,
                hostname=hostname,
                dst_port=dst_port,
            )
            if browser_hint is not None:
                return browser_hint

        ua = (user_agent or "").lower()
        if not ua:
            return None

        target_url = self._http_target_url(hostname=hostname, uri="/", dst_port=dst_port)
        proxy_url = (
            f"http://{self._proxy_fqdn(proxy_sys)}:{getattr(self, '_proxy_listener_port', 8080)}"
        )

        if os_category == "linux":
            package_hint = self._linux_package_manager_proxy_client_hint(
                user_agent=user_agent,
                source_system=source_system,
                dst_port=dst_port,
            )
            if package_hint is not None:
                return package_hint
            if server_like_source:
                if ua.startswith("curl/") or " curl/" in ua:
                    return "/usr/bin/curl", f"curl --proxy {proxy_url} {target_url}"
                if ua.startswith("wget/") or " wget/" in ua:
                    return (
                        "/usr/bin/wget",
                        f"wget -e use_proxy=yes -e http_proxy={proxy_url} {target_url}",
                    )
                if ua.startswith("python-requests/"):
                    return (
                        "/usr/bin/python3",
                        f"/usr/bin/python3 /opt/meridian/bin/proxy_healthcheck.py "
                        f"--target {hostname}",
                    )
                if ua.startswith("go-http-client/"):
                    return "/usr/local/bin/service-healthcheck", (
                        f"service-healthcheck --url {target_url}"
                    )
                if ua.startswith("apache-httpclient/"):
                    return "/usr/bin/java", (
                        f"java -jar /opt/meridian/integration-worker.jar --check-url {target_url}"
                    )
                return None
            if "firefox/" in ua:
                return "/usr/bin/firefox", f"firefox --new-window {target_url}"
            if "edg/" in ua or "edge/" in ua:
                return "/usr/bin/microsoft-edge", f"microsoft-edge {target_url}"
            if "opr/" in ua or "opera/" in ua:
                return "/usr/bin/opera", f"opera {target_url}"
            if "chrome/" in ua and "google update" not in ua:
                return "/usr/bin/google-chrome", f"google-chrome {target_url}"
            if ua.startswith("curl/") or " curl/" in ua:
                return "/usr/bin/curl", f"curl --proxy {proxy_url} {target_url}"
            if ua.startswith("wget/") or " wget/" in ua:
                return (
                    "/usr/bin/wget",
                    f"wget -e use_proxy=yes -e http_proxy={proxy_url} {target_url}",
                )
            if ua.startswith("python-requests/"):
                return None
            if ua.startswith("go-http-client/"):
                return "/usr/local/bin/service-healthcheck", (
                    f"service-healthcheck --url {target_url}"
                )
            if ua.startswith("apache-httpclient/"):
                return "/usr/bin/java", (
                    f"java -jar /opt/meridian/integration-worker.jar --check-url {target_url}"
                )
            if "powershell" in ua or "invoke-webrequest" in ua:
                return "/usr/bin/pwsh", f"pwsh -NoProfile -Command Invoke-WebRequest {target_url}"
            return None

        if server_like_source:
            if ua.startswith("go-http-client/"):
                image = r"C:\Program Files\Meridian\ServiceHealth\service-healthcheck.exe"
                return image, f'"{image}" --service'
            if ua.startswith("apache-httpclient/"):
                image = r"C:\Program Files\Eclipse Adoptium\jdk-17\bin\java.exe"
                return image, f'"{image}" -jar C:\\ProgramData\\Meridian\\integration-worker.jar'
            return None

        if ua.startswith("curl/") or " curl/" in ua:
            image = r"C:\Windows\System32\curl.exe"
            return image, f'curl.exe --proxy {proxy_url} "{target_url}"'
        if ua.startswith("wget/") or " wget/" in ua:
            image = r"C:\Program Files\GnuWin32\bin\wget.exe"
            return image, f'wget.exe -e use_proxy=yes -e http_proxy={proxy_url} "{target_url}"'
        if ua.startswith("python-requests/"):
            image = r"C:\Python311\python.exe"
            return image, f"python.exe -c \"import requests; requests.get('{target_url}')\""
        if ua.startswith("go-http-client/"):
            image = r"C:\Program Files\Meridian\ServiceHealth\service-healthcheck.exe"
            return image, f'"{image}" --url "{target_url}"'
        if ua.startswith("apache-httpclient/"):
            image = r"C:\Program Files\Eclipse Adoptium\jdk-17\bin\java.exe"
            return image, f'"{image}" -jar C:\\ProgramData\\Meridian\\integration-worker.jar'
        if "powershell" in ua or "invoke-webrequest" in ua:
            image = r"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe"
            return image, (
                f'powershell.exe -NoProfile -Command "Invoke-WebRequest '
                f"-Proxy '{proxy_url}' -Uri '{target_url}' -UseBasicParsing\""
            )
        return None

    @staticmethod
    def _is_proxy_server_like_source(source_system: System | None) -> bool:
        """Return whether proxy client PID synthesis should avoid workstation tooling."""
        if source_system is None:
            return False
        roles = {str(role).lower() for role in (getattr(source_system, "roles", None) or [])}
        server_roles = {
            "app_server",
            "database",
            "dns_server",
            "domain_controller",
            "file_server",
            "forward_proxy",
            "log_server",
            "mail_server",
            "monitoring",
            "web_server",
        }
        if roles & server_roles:
            return True
        system_type = (getattr(source_system, "type", "") or "").lower()
        if (
            system_type == "server"
            and _get_os_category(source_system.os) == "linux"
            and getattr(source_system, "assigned_user", None)
        ):
            return False
        return system_type in {"server", "domain_controller"}

    @staticmethod
    def _linux_package_manager_proxy_client_hint(
        *,
        user_agent: str,
        source_system: System | None,
        dst_port: int,
    ) -> tuple[str, str] | None:
        """Return source-native Linux package-manager socket owner process details."""
        if source_system is None:
            return None
        ua = (user_agent or "").lower()
        if not ua:
            return None

        from evidenceforge.generation.activity.bash_commands import (
            package_manager_family_for_os,
        )

        package_family = package_manager_family_for_os(source_system.os)
        if "apt-http" in ua:
            if package_family != "debian":
                return None
            method = "https" if dst_port == 443 else "http"
            image = f"/usr/lib/apt/methods/{method}"
            return image, image
        if "libdnf" in ua:
            if package_family != "rpm":
                return None
            return "/usr/bin/dnf", "dnf makecache --timer"
        return None

    def _linux_proxy_helper_system_owner_spec(
        self,
        *,
        source_system: System,
        image: str,
        command_line: str,
    ) -> tuple[str, str, str, str] | None:
        """Return system-owned process metadata for Linux proxy helper traffic."""
        if _get_os_category(source_system.os) != "linux":
            return None

        image_lower = image.lower()
        command_lower = command_line.lower()
        exe_name = image_lower.rsplit("/", 1)[-1]

        if image_lower.startswith("/usr/lib/apt/methods/"):
            method = exe_name or "http"
            return (
                f"apt_proxy_method:{method}:{command_line}",
                image,
                command_line,
                "root",
            )
        if exe_name in {"dnf", "yum"} and any(
            token in command_lower for token in ("makecache", "check-update", "update")
        ):
            return (
                f"{exe_name}_proxy_refresh:{command_line}",
                image,
                command_line,
                "root",
            )

        if not self._is_proxy_server_like_source(source_system):
            return None
        if exe_name in {"curl", "wget", "python", "python3"} and (
            self._connection_owner_requires_exact_command_line(image, command_line)
        ):
            return (
                f"{exe_name}_proxy_client:{command_line}",
                image,
                command_line,
                "root",
            )
        if exe_name == "service-healthcheck":
            return (
                f"service_healthcheck_proxy:{command_line}",
                image,
                command_line,
                "root",
            )
        if exe_name == "java" and "integration-worker" in command_lower:
            return (
                f"integration_worker_proxy:{command_line}",
                image,
                command_line,
                "www-data",
            )
        return None

    def _windows_proxy_helper_system_owner_spec(
        self,
        *,
        source_system: System,
        image: str,
        command_line: str,
    ) -> tuple[str, str, str, str] | None:
        """Return system-owned process metadata for Windows server proxy helpers."""
        if _get_os_category(source_system.os) != "windows":
            return None
        if not self._is_proxy_server_like_source(source_system):
            return None

        image_lower = image.lower()
        command_lower = command_line.lower()
        exe_name = image_lower.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]

        if exe_name == "service-healthcheck.exe":
            return (
                f"service_healthcheck_proxy:{command_line}",
                image,
                command_line,
                "SYSTEM",
            )
        if exe_name == "java.exe" and "integration-worker" in command_lower:
            return (
                f"integration_worker_proxy:{command_line}",
                image,
                command_line,
                "SYSTEM",
            )
        return None

    @staticmethod
    def _http_target_url(*, hostname: str, uri: str, dst_port: int) -> str:
        """Build the URL used in source-native client process command lines."""
        return ActivityGenerator._http_target_url_with_scheme(
            hostname=hostname,
            uri=uri,
            dst_port=dst_port,
            scheme=None,
        )

    @staticmethod
    def _http_target_url_with_scheme(
        *,
        hostname: str,
        uri: str,
        dst_port: int,
        scheme: str | None,
    ) -> str:
        """Build a URL while allowing CONNECT callers to preserve HTTPS semantics."""
        path = uri or "/"
        if path.startswith(("http://", "https://")):
            return path
        if not path.startswith("/"):
            path = f"/{path}"
        resolved_scheme = scheme or ("https" if dst_port == 443 else "http")
        if not hostname:
            return f"{resolved_scheme}://"
        host = hostname
        default_port = 443 if resolved_scheme == "https" else 80
        if dst_port != default_port and ":" not in host:
            host = f"{host}:{dst_port}"
        return f"{resolved_scheme}://{host}{path}"

    @staticmethod
    def _browser_launch_uri(uri: str) -> str:
        """Return the navigation URI a browser process would show at launch."""
        path = uri or "/"
        if path.startswith(("http://", "https://")):
            try:
                parsed = urlsplit(path)
            except ValueError:
                return uri or "/"
            path = parsed.path or "/"
        if not path.startswith("/"):
            path = f"/{path}"

        clean_path = path.split("?", 1)[0].split("#", 1)[0].lower()
        basename = clean_path.rsplit("/", 1)[-1]
        suffix = f".{basename.rsplit('.', 1)[-1]}" if "." in basename else ""
        static_prefixes = (
            "/assets/",
            "/asset/",
            "/static/",
            "/media/",
            "/images/",
            "/img/",
            "/css/",
            "/js/",
            "/fonts/",
        )
        static_names = {"/favicon.ico", "/robots.txt", "/sitemap.xml", "/index.html", "/index.htm"}
        static_suffixes = {
            ".avif",
            ".css",
            ".gif",
            ".ico",
            ".jpeg",
            ".jpg",
            ".js",
            ".map",
            ".png",
            ".svg",
            ".webp",
            ".woff",
            ".woff2",
        }
        if (
            clean_path in static_names
            or clean_path.startswith(static_prefixes)
            or suffix in static_suffixes
        ):
            return "/"
        return uri or "/"

    @staticmethod
    def _browser_navigation_target(
        *,
        hostname: str,
        uri: str,
        dst_port: int,
    ) -> tuple[str, int, bool]:
        """Normalize proxy CONNECT targets into a browser-visible navigation target."""
        max_port_digits = 5
        raw_uri = (uri or "").strip()
        host = (hostname or "").strip().lower().rstrip(".")
        if raw_uri and not raw_uri.startswith(("/", "http://", "https://")):
            target, separator, port = raw_uri.rpartition(":")
            if separator and port.isdigit() and target.strip().lower().rstrip(".") == host:
                if len(port) > max_port_digits:
                    return "/", dst_port, True
                parsed_port = int(port)
                if 1 <= parsed_port <= 65535:
                    return "/", parsed_port, True
                return "/", dst_port, True
        return uri, dst_port, False

    @staticmethod
    def _browser_target_allows_top_level_launch(hostname: str, uri: str = "/") -> bool:
        """Return whether a URL is plausible as a new user-visible browser launch."""
        host = (hostname or "").strip().lower().rstrip(".")
        if not host:
            return True
        if not is_browser_like_proxy_domain(host):
            return False

        label = host.split(".", 1)[0]
        resource_labels = {
            "asset",
            "assets",
            "avatars",
            "cdn",
            "crl",
            "github-releases",
            "img",
            "images",
            "media",
            "objects",
            "ocsp",
            "static",
        }
        if label in resource_labels:
            return False
        if host.endswith(".githubusercontent.com") and label in {"avatars", "objects"}:
            return False
        return True

    def _browser_http_client_process_hint(
        self,
        *,
        user_agent: str,
        hostname: str,
        dst_port: int,
        uri: str = "/",
    ) -> tuple[str, str] | None:
        """Map browser-like Windows HTTP User-Agents to their owning process."""
        ua = (user_agent or "").lower()
        if not ua:
            return None

        target_uri, target_port, is_connect_target = self._browser_navigation_target(
            hostname=hostname,
            uri=uri,
            dst_port=dst_port,
        )
        launch_uri = self._browser_launch_uri(target_uri)
        target_url = self._http_target_url_with_scheme(
            hostname=hostname,
            uri=launch_uri,
            dst_port=target_port,
            scheme="https" if is_connect_target and target_port != 80 else None,
        )
        if "firefox/" in ua:
            image = r"C:\Program Files\Mozilla Firefox\firefox.exe"
            return image, f'"{image}" -osint -url {target_url}'
        if "edg/" in ua or "edge/" in ua:
            image = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
            return image, f'"{image}" --single-argument {target_url}'
        if "opr/" in ua or "opera/" in ua:
            image = r"C:\Program Files\Opera\opera.exe"
            return image, f'"{image}" {target_url}'
        if "chrome/" in ua and "google update" not in ua:
            image = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
            return image, f'"{image}" --single-argument {target_url}'
        if "trident/" in ua or "msie " in ua:
            image = r"C:\Program Files\Internet Explorer\iexplore.exe"
            return image, f'"{image}" {target_url}'
        return None

    def _claim_top_level_browser_launch_target(
        self,
        *,
        system: System,
        username: str,
        image: str,
        hostname: str,
        uri: str,
    ) -> bool:
        """Return whether an exact browser launch target should create a process."""
        if not hasattr(self, "_top_level_browser_launch_targets"):
            self._top_level_browser_launch_targets: dict[tuple[str, str, str, str, str], int] = {}
        key = (
            system.hostname,
            username,
            image.lower(),
            (hostname or "").strip().lower().rstrip("."),
            self._browser_launch_uri(uri).lower(),
        )
        previous = self._top_level_browser_launch_targets.get(key, 0)
        self._top_level_browser_launch_targets[key] = previous + 1
        return previous == 0

    def _select_explicit_proxy_client_session(
        self,
        source_system: System,
        time: datetime,
    ) -> tuple[User, Any] | None:
        """Pick the user session most likely to own a user-mode proxy request."""
        known_users = getattr(self, "_users_by_username", {})

        def _accepts_activity(session: Any) -> bool:
            end_plan = self.state_manager.get_session_end_plan(session.logon_id)
            return not (
                end_plan is not None
                and end_plan.is_authoritative
                and ensure_utc(time) >= ensure_utc(end_plan.canonical_end)
            )

        sessions = [
            session
            for session in self.state_manager.get_sessions_on_system_at(
                source_system.hostname,
                time,
            )
            if session.username in known_users
            and session.username not in _SYSTEM_ACCOUNTS
            and not session.username.endswith("$")
            and session.logon_type in {2, 7, 10, 11}
            and _session_started_by(session, time)
            and _accepts_activity(session)
            and not self._workstation_logon_locked_at(
                source_system,
                session.username,
                session.logon_id,
                time,
            )
        ]
        if not sessions:
            return None

        assigned_user = getattr(source_system, "assigned_user", None)
        if assigned_user:
            assigned_sessions = [
                session for session in sessions if session.username == assigned_user
            ]
            if assigned_sessions:
                sessions = assigned_sessions

        session = max(sessions, key=lambda candidate: candidate.start_time)
        return known_users[session.username], session

    def _ensure_explicit_proxy_client_process(
        self,
        *,
        source_system: System | None,
        time: datetime,
        proxy_context: ProxyContext,
        proxy_sys: System,
        dst_port: int,
    ) -> tuple[int, str | None]:
        """Create or reuse the process that source-natively owns a proxy client socket."""
        if source_system is None or _get_os_category(source_system.os) != "windows":
            if source_system is None or _get_os_category(source_system.os) != "linux":
                return -1, None

        hint = self._explicit_proxy_client_process_hint(
            user_agent=proxy_context.user_agent,
            hostname=proxy_context.host,
            dst_port=dst_port,
            proxy_sys=proxy_sys,
            source_system=source_system,
        )
        if hint is None:
            return -1, None

        image, command_line = hint
        os_category = _get_os_category(source_system.os)
        system_owner_spec = self._windows_proxy_helper_system_owner_spec(
            source_system=source_system,
            image=image,
            command_line=command_line,
        )
        if system_owner_spec is not None:
            key, owner_image, owner_command_line, owner_username = system_owner_spec
            return self._ensure_system_connection_owner_process(
                source_system=source_system,
                time=time,
                key=key,
                image=owner_image,
                command_line=owner_command_line,
                username=owner_username,
            )

        system_owner_spec = self._linux_proxy_helper_system_owner_spec(
            source_system=source_system,
            image=image,
            command_line=command_line,
        )
        if system_owner_spec is not None:
            key, owner_image, owner_command_line, owner_username = system_owner_spec
            return self._ensure_system_connection_owner_process(
                source_system=source_system,
                time=time,
                key=key,
                image=owner_image,
                command_line=owner_command_line,
                username=owner_username,
            )

        require_exact_command = self._connection_owner_requires_exact_command_line(
            image,
            command_line,
        )
        session_info = self._select_explicit_proxy_client_session(source_system, time)
        if session_info is None:
            return -1, None
        user, session = session_info

        image_lower = image.lower()
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(source_system.hostname)
            if proc.username == user.username
            and proc.logon_id == session.logon_id
            and proc.image.lower() == image_lower
            and (not require_exact_command or proc.command_line == command_line)
            and proc.start_time is not None
            and proc.start_time <= time
            and not self._foreground_process_expired_for_attribution(source_system, proc, time)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            self.state_manager.update_process_activity_time(
                source_system.hostname,
                proc.pid,
                time,
            )
            return proc.pid, proc.image

        if os_category == "windows" and image_lower.endswith(tuple(_WINDOWS_BROWSER_EXES)):
            parsed_url = urlsplit(proxy_context.url or "")
            proxy_uri = parsed_url.path or "/"
            if not self._browser_target_allows_top_level_launch(proxy_context.host, proxy_uri):
                return -1, None
            if not self._claim_top_level_browser_launch_target(
                system=source_system,
                username=user.username,
                image=image,
                hostname=proxy_context.host,
                uri=proxy_uri,
            ):
                return -1, None

        process_rng = random.Random(
            _stable_seed(
                "explicit_proxy_client_process:"
                f"{source_system.hostname}:{user.username}:{image}:{proxy_context.host}"
            )
        )
        process_lifetime = (
            _windows_foreground_lifetime(image, command_line)
            if os_category == "windows"
            else _linux_foreground_lifetime(image, command_line)
        )
        if process_lifetime is not None:
            lead_seconds = process_rng.uniform(0.4, min(8.0, process_lifetime[1]))
        else:
            lead_seconds = process_rng.uniform(12.0, 240.0)
        process_time = time - timedelta(seconds=lead_seconds)
        min_process_time = session.start_time + timedelta(milliseconds=500)
        if process_time < min_process_time:
            process_time = min_process_time
        if process_time >= time:
            process_time = time - timedelta(milliseconds=100)

        parent_pid = self._select_parent_pid(
            source_system,
            user,
            image,
            time=process_time,
            logon_id=session.logon_id,
        )
        if os_category == "linux":
            parent_pid = (
                self._linux_non_shell_session_parent_pid(
                    system=source_system,
                    time=process_time,
                    logon_id=session.logon_id,
                )
                or parent_pid
            )
        pid = self.generate_process(
            user=user,
            system=source_system,
            time=process_time,
            logon_id=session.logon_id,
            process_name=image,
            command_line=command_line,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            allow_browser_launch_spacing=False,
        )
        self._record_user_process(source_system, user, pid, image)
        self.state_manager.update_process_activity_time(source_system.hostname, pid, time)
        self.state_manager.set_current_time(time)
        return pid, image

    def _linux_non_shell_session_parent_pid(
        self,
        *,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> int | None:
        """Return a live non-shell parent for Linux session-bound helper processes."""
        if _get_os_category(system.os) != "linux" or not logon_id:
            return None

        def live_non_shell(candidate: int | None) -> int | None:
            if not candidate:
                return None
            proc = self.state_manager.get_process(system.hostname, candidate)
            if proc is None or not self._linux_parent_usable_for_child_at(
                system=system,
                parent_pid=candidate,
                time=time,
                logon_id=logon_id,
            ):
                return None
            exe = proc.image.rsplit("/", 1)[-1].lower()
            if exe in {"bash", "sh", "zsh"}:
                return None
            return candidate

        session = self.state_manager.get_session(logon_id)
        if session is not None:
            for candidate in (session.process_tree_root, session.transport_pid):
                parent_pid = live_non_shell(candidate)
                if parent_pid is not None:
                    return parent_pid

        session_user = session.username if session is not None else ""
        preferred_images = {
            "systemd",
            "gnome-terminal-server",
            "login",
            "sshd",
        }
        candidates = []
        for proc in self.state_manager.get_processes_on_system(system.hostname):
            if session_user and proc.username not in {session_user, "root"}:
                continue
            if proc.logon_id and proc.logon_id != logon_id:
                continue
            exe = proc.image.rsplit("/", 1)[-1].lower()
            if exe not in preferred_images:
                continue
            parent_pid = live_non_shell(proc.pid)
            if parent_pid is not None:
                candidates.append(proc)
        if candidates:
            return max(candidates, key=lambda candidate: candidate.start_time or time).pid

        sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        for role in ("systemd", "init", "sshd"):
            parent_pid = live_non_shell(sys_pids.get(role))
            if parent_pid is not None:
                return parent_pid
        return None

    def _prepare_linux_foreground_connection_owner(
        self,
        *,
        system: System,
        user: User,
        session: ActiveSession,
        process_time: datetime,
        activity_time: datetime,
        process_name: str,
        command_line: str,
        source_visible_by: datetime | None = None,
    ) -> tuple[int, datetime] | None:
        """Choose an available shell for an anchored Linux foreground client.

        Connection owners must already be visible when their transport opens, so a
        busy shell cannot simply move the command past that anchor.  Interactive
        terminals and SSH connections can own more than one shell/channel; create a
        sibling shell when every existing shell is reserved by foreground work.
        """
        process_time = ensure_utc(process_time)
        deadline = ensure_utc(source_visible_by or activity_time)
        if not _linux_shell_process_reserves_foreground(process_name, command_line):
            parent_pid = self._linux_non_shell_session_parent_pid(
                system=system,
                time=process_time,
                logon_id=session.logon_id,
            )
            return (parent_pid, process_time) if parent_pid is not None else None

        shell_candidates = [
            process
            for process in self.state_manager.get_processes_on_system(system.hostname)
            if process.username == user.username
            and process.logon_id == session.logon_id
            and process.image.rsplit("/", 1)[-1].lower() in {"bash", "sh", "zsh"}
            and self._is_pid_active_at(system, process.pid, process_time)
        ]
        shell_candidates.sort(key=lambda process: process.start_time, reverse=True)
        for shell in shell_candidates:
            if not self._process_source_bound_visible_by(
                system=system,
                pid=shell.pid,
                deadline=source_visible_by,
            ):
                continue
            reserved_time = self._reserve_foreground_shell_time(
                system=system,
                username=user.username,
                logon_id=session.logon_id,
                parent_pid=shell.pid,
                requested_time=process_time,
                seed_text=command_line,
            )
            if reserved_time < deadline:
                return shell.pid, reserved_time

        non_shell_parent = self._linux_non_shell_session_parent_pid(
            system=system,
            time=process_time,
            logon_id=session.logon_id,
        )
        if non_shell_parent is None:
            return None
        shell_seed = _stable_seed(
            "linux-anchored-foreground-shell:"
            f"{system.hostname}:{user.username}:{session.logon_id}:"
            f"{command_line}:{process_time.isoformat()}"
        )
        session_floor = ensure_utc(session.start_time) + timedelta(milliseconds=100)
        # A newly materialized terminal needs up to 6.999 seconds before its
        # first child can launch.  Start the sibling far enough ahead that the
        # readiness floor cannot consume the anchored transport deadline.
        shell_time = max(
            session_floor,
            process_time - timedelta(milliseconds=7200 + (shell_seed % 4801)),
        )
        if shell_time >= process_time:
            shell_time = process_time - timedelta(milliseconds=100)
        if shell_time <= ensure_utc(session.start_time):
            return None
        shell_deadline = min(deadline, process_time - timedelta(milliseconds=1))
        parent_source_time = self._process_source_frontier_or_bound(
            system=system,
            pid=non_shell_parent,
        )
        if parent_source_time is None:
            return None
        session_source_time = _session_source_ready_time(session)
        shell_source_bound = self._process_create_source_bound(
            system=system,
            canonical_time=shell_time,
            parent_source_time=parent_source_time,
            session_source_time=session_source_time,
        )
        prospective_process_time = max(
            process_time,
            shell_time + timedelta(milliseconds=_FOREGROUND_SHELL_INITIAL_READY_MAX_MS),
        )
        prospective_process_source_bound = self._process_create_source_bound(
            system=system,
            canonical_time=prospective_process_time,
            parent_source_time=shell_source_bound,
            session_source_time=session_source_time,
        )
        if (
            shell_source_bound > shell_deadline
            or prospective_process_time >= deadline
            or prospective_process_source_bound > deadline
        ):
            return None
        shell_pid = self.generate_process(
            user=user,
            system=system,
            time=shell_time,
            logon_id=session.logon_id,
            process_name="/bin/bash",
            command_line="-bash",
            parent_pid=non_shell_parent,
            suppress_command_file_effect=True,
            allow_existing_browser_reuse=False,
            allow_browser_launch_spacing=False,
            lifecycle_group_id=session.lifecycle_group_id,
            source_visible_by=shell_deadline,
        )
        if shell_pid <= 0:
            return None
        reserved_time = self._reserve_foreground_shell_time(
            system=system,
            username=user.username,
            logon_id=session.logon_id,
            parent_pid=shell_pid,
            requested_time=process_time,
            seed_text=command_line,
        )
        if reserved_time >= deadline:
            return None
        return shell_pid, reserved_time

    def _ensure_browser_http_client_process(
        self,
        *,
        source_system: System | None,
        time: datetime,
        http: HttpContext,
        dst_port: int,
    ) -> tuple[int, str | None]:
        """Create or reuse the browser process that owns a Windows HTTP socket."""
        if source_system is None or _get_os_category(source_system.os) != "windows":
            return -1, None

        hint = self._browser_http_client_process_hint(
            user_agent=http.user_agent,
            hostname=http.host,
            dst_port=dst_port,
            uri=http.uri,
        )
        if hint is None:
            return -1, None

        image, command_line = hint
        session = self._active_interactive_windows_session(source_system, time)
        if session is None:
            return -1, None
        user = self._user_model_for_username(session.username)

        image_lower = image.lower()
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(source_system.hostname)
            if proc.username == user.username
            and proc.logon_id == session.logon_id
            and proc.image.lower() == image_lower
            and proc.start_time is not None
            and proc.start_time <= time
            and not self._foreground_process_expired_for_attribution(source_system, proc, time)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            self.state_manager.update_process_activity_time(
                source_system.hostname,
                proc.pid,
                time,
            )
            return proc.pid, proc.image

        if not self._browser_target_allows_top_level_launch(http.host, http.uri):
            return -1, None
        if not self._claim_top_level_browser_launch_target(
            system=source_system,
            username=user.username,
            image=image,
            hostname=http.host,
            uri=http.uri,
        ):
            return -1, None

        process_rng = random.Random(
            _stable_seed(
                "browser_http_client_process:"
                f"{source_system.hostname}:{user.username}:{image}:"
                f"{http.host}:{self._browser_launch_uri(http.uri)}"
            )
        )
        lead_seconds = process_rng.uniform(0.4, 8.0)
        process_time = time - timedelta(seconds=lead_seconds)
        min_process_time = session.start_time + timedelta(milliseconds=500)
        if process_time < min_process_time:
            process_time = min_process_time
        if process_time >= time:
            process_time = time - timedelta(milliseconds=100)

        parent_pid = self._select_parent_pid(
            source_system,
            user,
            image,
            time=process_time,
            logon_id=session.logon_id,
        )
        pid = self.generate_process(
            user=user,
            system=source_system,
            time=process_time,
            logon_id=session.logon_id,
            process_name=image,
            command_line=command_line,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            allow_existing_browser_reuse=False,
            allow_browser_launch_spacing=False,
        )
        self._record_user_process(source_system, user, pid, image)
        self.state_manager.update_process_activity_time(source_system.hostname, pid, time)
        self.state_manager.set_current_time(time)
        running = self.state_manager.get_process(source_system.hostname, pid)
        if running is not None:
            return pid, running.image
        return pid, image

    def _set_connection_process_context(
        self,
        event: OccurrenceBuilder,
        *,
        source_system: System,
        pid: int,
        image: str | None = None,
    ) -> None:
        """Update canonical connection process ownership from StateManager."""
        running = self.state_manager.get_process(source_system.hostname, pid)
        if running is not None:
            event.process = ProcessContext(
                pid=pid,
                parent_pid=running.parent_pid,
                image=running.image,
                command_line=running.command_line,
                username=running.username,
                logon_id=running.logon_id,
                start_time=running.start_time,
                parent_start_time=self._lookup_parent_start_time(
                    source_system.hostname,
                    running.parent_pid,
                ),
            )
        elif image:
            event.process = ProcessContext(
                pid=pid,
                parent_pid=0,
                image=image,
                command_line="",
                username="",
            )
        else:
            event.process = None
        if isinstance(event.network, NetworkTransactionPlan):
            event.network = replace(event.network, initiating_pid=pid)
        else:
            event.network.initiating_pid = pid

    def _repair_browser_http_process_attribution(
        self,
        event: OccurrenceBuilder,
        *,
        source_system: System | None,
        time: datetime,
    ) -> None:
        """Prevent browser-like HTTP rows from inheriting service-process ownership."""
        if (
            source_system is None
            or event.http is None
            or event.network is None
            or _get_os_category(source_system.os) != "windows"
        ):
            return

        hint = self._browser_http_client_process_hint(
            user_agent=event.http.user_agent,
            hostname=event.http.host,
            dst_port=event.network.dst_port,
            uri=event.http.uri,
        )
        if hint is None:
            return

        expected_image = hint[0].lower()
        current_pid = event.network.initiating_pid
        if current_pid > 0:
            current = self.state_manager.get_process(source_system.hostname, current_pid)
            if current is not None and not self._foreground_process_expired_for_attribution(
                source_system,
                current,
                time,
            ):
                if current.image.lower() == expected_image:
                    self._set_connection_process_context(
                        event,
                        source_system=source_system,
                        pid=current_pid,
                    )
                    self.state_manager.update_process_activity_time(
                        source_system.hostname,
                        current_pid,
                        time,
                    )
                    return
                expected_exe = ntpath.basename(expected_image).lower()
                current_exe = ntpath.basename(current.image or "").lower()
                mismatched_browser = (
                    expected_exe in _WINDOWS_BROWSER_EXES and current_exe in _WINDOWS_BROWSER_EXES
                )
                if not mismatched_browser and not self._windows_proxy_pid_should_be_replaced(
                    current
                ):
                    return

        client_pid, client_image = self._ensure_browser_http_client_process(
            source_system=source_system,
            time=time,
            http=event.http,
            dst_port=event.network.dst_port,
        )
        if client_pid > 0:
            self._set_connection_process_context(
                event,
                source_system=source_system,
                pid=client_pid,
                image=client_image,
            )
            return

        self._set_connection_process_context(
            event,
            source_system=source_system,
            pid=-1,
        )

    @staticmethod
    def _proxy_origin_port_from_http(http: HttpContext) -> int:
        """Return the origin port represented by a client-to-proxy HTTP request."""
        if (http.method or "").upper() == "CONNECT":
            target = http.uri or http.host or ""
            _host, separator, port_text = target.rpartition(":")
            if separator and port_text.isdigit() and len(port_text) <= 5:
                port = int(port_text)
                if 1 <= port <= 65535:
                    return port
            return 443
        url = http.uri or ""
        if url.startswith(("http://", "https://")):
            try:
                parsed = urlsplit(url)
                parsed_port = parsed.port
            except ValueError:
                return 443 if url.startswith("https://") else 80
            if parsed_port is not None:
                return parsed_port
            return 443 if parsed.scheme == "https" else 80
        return 80

    def _repair_explicit_proxy_listener_process_attribution(
        self,
        event: OccurrenceBuilder,
        *,
        source_system: System | None,
        time: datetime,
    ) -> None:
        """Apply proxy client process ownership to direct client-to-proxy HTTP flows."""
        if source_system is None or event.http is None or event.network is None:
            return
        if event.network.dst_port != getattr(self, "_proxy_listener_port", 8080):
            return
        proxy_sys = getattr(self, "_ip_to_system", {}).get(event.network.dst_ip)
        if proxy_sys is None or "forward_proxy" not in (proxy_sys.roles or []):
            return

        proxy_context = ProxyContext(
            client_ip=event.network.src_ip,
            method=event.http.method,
            url=event.http.uri,
            host=event.http.host,
            status_code=event.http.status_code,
            user_agent=event.http.user_agent,
            proxy_fqdn=self._proxy_fqdn(proxy_sys),
        )
        origin_port = self._proxy_origin_port_from_http(event.http)
        current_pid = event.network.initiating_pid
        current_image = event.process.image if event.process is not None else None
        if current_pid > 0:
            caller_process_image = self._caller_explicit_proxy_process_image(
                source_system=source_system,
                pid=current_pid,
                process_image=current_image,
                time=time,
                proxy_context=proxy_context,
                proxy_sys=proxy_sys,
                dst_port=origin_port,
                http=event.http,
            )
            if caller_process_image is not None:
                running = self.state_manager.get_process(source_system.hostname, current_pid)
                if running is not None and self._process_owns_multipart_proxy_request(
                    process=running,
                    candidate_image=caller_process_image,
                    http=event.http,
                ):
                    process_user_agent = _http_user_agent_for_process(
                        caller_process_image,
                        running.command_line,
                    )
                    event.http = replace(
                        event.http,
                        user_agent=process_user_agent,
                        referrer=_source_native_http_referrer(
                            process_user_agent,
                            event.http.referrer,
                        ),
                    )
                self._set_connection_process_context(
                    event,
                    source_system=source_system,
                    pid=current_pid,
                    image=caller_process_image,
                )
                self.state_manager.update_process_activity_time(
                    source_system.hostname,
                    current_pid,
                    time,
                )
                return

        client_pid, client_image = self._ensure_explicit_proxy_client_process(
            source_system=source_system,
            time=time,
            proxy_context=proxy_context,
            proxy_sys=proxy_sys,
            dst_port=origin_port,
        )
        if client_pid > 0:
            self._set_connection_process_context(
                event,
                source_system=source_system,
                pid=client_pid,
                image=client_image,
            )
            return

        fallback_pid, fallback_image = self._ensure_high_confidence_connection_owner(
            source_system=source_system,
            time=time,
            service=event.network.service,
            dst_port=event.network.dst_port,
            proto=event.network.protocol,
            hostname=proxy_context.host,
            http=event.http,
        )
        if fallback_pid > 0:
            self._set_connection_process_context(
                event,
                source_system=source_system,
                pid=fallback_pid,
                image=fallback_image,
            )
            return

        self._set_connection_process_context(
            event,
            source_system=source_system,
            pid=-1,
        )

    def _caller_explicit_proxy_process_image(
        self,
        *,
        source_system: System | None,
        pid: int,
        process_image: str | None,
        time: datetime,
        proxy_context: ProxyContext,
        proxy_sys: System,
        dst_port: int,
        http: HttpContext | None = None,
    ) -> str | None:
        """Return the caller process image when valid proxy client telemetry owns it."""
        if pid <= 0 or source_system is None:
            return None

        running = self.state_manager.get_process(source_system.hostname, pid)
        if running is None:
            return None
        session_end_plan = self.state_manager.process_session_end_plan(
            source_system.hostname,
            pid,
        )
        if (
            session_end_plan is not None
            and session_end_plan.is_authoritative
            and ensure_utc(time) >= ensure_utc(session_end_plan.canonical_end)
        ):
            return None
        candidate_image = running.image or process_image
        if not candidate_image:
            return None
        owns_multipart_request = self._process_owns_multipart_proxy_request(
            process=running,
            candidate_image=candidate_image,
            http=http,
        )
        if not owns_multipart_request and self._foreground_process_expired_for_attribution(
            source_system,
            running,
            time=time,
        ):
            return None
        if owns_multipart_request:
            return candidate_image

        hint = self._explicit_proxy_client_process_hint(
            user_agent=proxy_context.user_agent,
            hostname=proxy_context.host,
            dst_port=dst_port,
            proxy_sys=proxy_sys,
            source_system=source_system,
        )
        if hint is None:
            os_category = _get_os_category(source_system.os)
            if os_category == "windows" and self._windows_proxy_pid_should_be_replaced(running):
                return None
            if os_category == "linux" and self._linux_proxy_pid_should_be_replaced(
                running,
                expected_exe="",
            ):
                return None
            return candidate_image

        expected_image = hint[0]
        expected_command_line = hint[1]
        require_exact_command = self._connection_owner_requires_exact_command_line(
            expected_image,
            expected_command_line,
        )
        if candidate_image.lower() == expected_image.lower():
            if require_exact_command and running.command_line != expected_command_line:
                return None
            return candidate_image
        expected_exe = ntpath.basename(expected_image).lower()
        candidate_exe = ntpath.basename(candidate_image).lower()
        proxy_browser_exes = _WINDOWS_BROWSER_EXES | {
            "chromium",
            "chromium-browser",
            "firefox",
            "google-chrome",
            "microsoft-edge",
            "opera",
        }
        if expected_exe in proxy_browser_exes and candidate_exe in proxy_browser_exes:
            return None
        os_category = _get_os_category(source_system.os)
        if os_category == "windows" and self._windows_proxy_pid_should_be_replaced(running):
            return None
        if os_category == "linux" and self._linux_proxy_pid_should_be_replaced(
            running,
            expected_exe=expected_exe,
        ):
            return None
        return candidate_image

    @staticmethod
    def _process_owns_multipart_proxy_request(
        *,
        process: Any,
        candidate_image: str,
        http: HttpContext | None,
    ) -> bool:
        """Recognize an explicit curl form command as the multipart socket owner."""
        if http is None or http.request_multipart is None:
            return False
        if ntpath.basename(candidate_image).lower() not in {"curl", "curl.exe"}:
            return False
        command = str(getattr(process, "command_line", "") or "")
        command_lower = command.lower()
        if not any(marker in command_lower for marker in (" --form ", " -f ")):
            return False
        target = f"{http.host}{http.uri}".lower()
        if target not in command_lower:
            return False
        local_parts = [
            part for part in http.request_multipart.leaf_parts() if part.local_source_path
        ]
        return bool(local_parts) and all(
            part.local_source_path.lower() in command_lower for part in local_parts
        )

    @staticmethod
    def _windows_proxy_pid_should_be_replaced(process: Any) -> bool:
        """Return whether a Windows PID is known service-owned proxy attribution noise."""
        image = str(getattr(process, "image", "") or "")
        command_line = str(getattr(process, "command_line", "") or "")
        exe_name = ntpath.basename(image).lower()
        unrelated_user_app_exes = {
            "acrobat.exe",
            "devicesyncsvc.exe",
            "dropbox.exe",
            "dropboxupdate.exe",
            "excel.exe",
            "googledrivefs.exe",
            "outlook.exe",
            "onedrive.exe",
            "pangpa.exe",
            "postman.exe",
            "python.exe",
            "python3.exe",
            "selfservice.exe",
            "slack.exe",
            "teams.exe",
            "vpnui.exe",
            "webex.exe",
            "winword.exe",
            "zoom.exe",
            "zsatray.exe",
        }
        return (
            _windows_service_process_account(image, command_line) is not None
            or exe_name in _WINDOWS_SINGLETON_SERVICE_EXES
            or exe_name in unrelated_user_app_exes
        )

    @staticmethod
    def _linux_proxy_pid_should_be_replaced(process: Any, *, expected_exe: str) -> bool:
        """Return whether a Linux PID is source-native noise for a proxy client socket."""
        image = str(getattr(process, "image", "") or "")
        exe_name = image.rsplit("/", 1)[-1].lower()
        if exe_name == expected_exe:
            return False
        return exe_name in {
            "apache2",
            "bash",
            "cat",
            "cargo",
            "curl",
            "docker",
            "git",
            "grep",
            "head",
            "httpd",
            "java",
            "journalctl",
            "kubectl",
            "less",
            "ls",
            "nano",
            "nginx",
            "npm",
            "php-fpm",
            "postfix",
            "ps",
            "python",
            "python3",
            "sed",
            "service-healthcheck",
            "sh",
            "smtp",
            "smtpd",
            "systemctl",
            "tail",
            "vim",
            "zsh",
        }

    def _attach_ssl_context(
        self,
        event: OccurrenceBuilder,
        *,
        hostname: str | None,
        dns: Optional["DnsContext"],
        dst_ip: str,
        rng: random.Random,
        allow_failure: bool = True,
        timing_stable_id: str = "",
        network_preparation: Any | None = None,
        timing_runtime: Any | None = None,
        network_point_expires_at: datetime | None = None,
    ) -> None:
        """Attach Zeek SSL and x509 contexts to an established TLS connection."""
        from evidenceforge.events.contexts import SslContext

        net = event.network
        if net is None or event.ssl is not None:
            return

        # Hostname is the SNI source of truth.  Do not invent SNI from a bare
        # destination IP or PTR; raw-IP TLS should either have no SNI or an
        # explicit/DNS-backed hostname.
        server_name = hostname
        if server_name is None and dns is not None and dns.query:
            server_name = dns.query
        # Suppressed hostname -> no SNI (raw-IP C2, etc.)
        if server_name == "":
            server_name = None
        if event.http is not None:
            # A visible HTTP transaction over TLS means the handshake completed.
            # Failed-handshake SSL rows cannot coexist with successful http.log,
            # web/proxy response bytes, or SF conn.log accounting for the same UID.
            allow_failure = False

        # For suppressed external hostnames (raw-IP C2), use the IP as the cert subject.
        # For internal/private endpoints without explicit SNI, use the known
        # internal hostname so x509.log does not show public-CA certificates
        # issued to private IPs. If explicit internal SNI exists, it remains
        # the certificate identity and SAN source of truth.
        internal_cert_name = ""
        ad_domain = getattr(self, "_ad_domain", "")
        server_name_is_internal = bool(server_name) and _dns_is_internal_name(
            server_name,
            ad_domain,
        )
        if _is_private_ip(dst_ip):
            if server_name_is_internal:
                internal_cert_name = server_name
            elif not server_name:
                dst_host = event.dst_host
                if dst_host is None and hasattr(self, "_ip_to_system"):
                    dst_system = self._ip_to_system.get(dst_ip)
                    if dst_system is not None:
                        dst_host = self._build_host_context(dst_system)
                if dst_host is not None:
                    internal_cert_name = dst_host.fqdn or dst_host.hostname
        cert_name = server_name or internal_cert_name or dst_ip

        # Issuer-aware certificate generation from YAML config.
        from evidenceforge.generation.activity.tls_issuers import pick_issuer, pick_key_type

        cert_rng = random.Random(_stable_seed(f"tls_cert_profile:{cert_name}"))
        if internal_cert_name:
            issuer_cfg = _enterprise_tls_issuer(getattr(self, "_ad_domain", ""))
        elif _is_ip_literal(cert_name):
            issuer_cfg = _raw_ip_tls_issuer(cert_name)
        else:
            issuer_cfg = pick_issuer(cert_rng, server_name=cert_name, event_time=event.timestamp)
        key_type, key_length = pick_key_type(cert_rng, issuer_cfg)
        key_type, key_length = _tls_key_for_certificate_name(cert_name, key_type, key_length)
        is_ecdsa = key_type == "ecdsa"

        modern_tls_domain = bool(server_name) and server_name.endswith(
            (
                ".google.com",
                ".gstatic.com",
                ".googleapis.com",
                ".microsoft.com",
                ".office.com",
                ".office365.com",
                ".microsoftonline.com",
                ".windowsupdate.com",
                ".cloudfront.net",
                ".github.com",
                ".slack.com",
                ".zoom.us",
            )
        )
        _tls_rng = random.Random(_stable_seed(f"tls:{server_name or dst_ip}:{net.src_ip}"))
        if modern_tls_domain:
            tls_version = _tls_rng.choices(("TLSv12", "TLSv13"), weights=(15, 85), k=1)[0]
        else:
            tls_version = _tls_rng.choices(_TLS_VERSION_VALUES, weights=_TLS_VERSION_WEIGHTS, k=1)[
                0
            ]
        if tls_version == "TLSv13":
            cipher = _tls_rng.choices(_TLS13_CIPHER_VALUES, weights=_TLS13_CIPHER_WEIGHTS, k=1)[0]
        elif is_ecdsa:
            cipher = "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256"
        elif modern_tls_domain:
            cipher = _tls_rng.choices(
                (
                    "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
                    "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
                ),
                weights=(75, 25),
                k=1,
            )[0]
        else:
            cipher = _tls_rng.choices(
                (
                    "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
                    "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
                    "TLS_ECDHE_RSA_WITH_AES_128_CBC_SHA256",
                ),
                weights=(65, 28, 7),
                k=1,
            )[0]

        ssl_established = (rng.random() > _SSL_FAILURE_RATE) if allow_failure else True
        ssl_history_roll = rng.random()
        tls_name_key = server_name or dst_ip
        pair_key = (net.src_ip, net.dst_ip, net.dst_port, tls_name_key)
        if not ssl_established:
            resumed = False
        elif network_preparation is None:
            # Direct context construction has no authenticated runtime owner.
            # Treat it as one fresh handshake rather than retaining a second,
            # unbounded resumption cache beside NetworkTransactionRuntime.
            _ = rng.random()
            resumed = False
        else:
            first_observed_name = not bool(
                network_preparation.read_point(
                    NetworkRuntimePointFamily.TLS_SERVER_NAME,
                    tls_name_key,
                    False,
                    at=ensure_utc(event.timestamp),
                )
            )
            first_observed_pair = not bool(
                network_preparation.read_point(
                    NetworkRuntimePointFamily.TLS_CLIENT_SERVER_PAIR,
                    pair_key,
                    False,
                    at=ensure_utc(event.timestamp),
                )
            )
            resumed = rng.random() < 0.45 and not first_observed_name and not first_observed_pair
            if network_point_expires_at is None:
                raise StateError("Prepared TLS resumption state requires an explicit finite expiry")
            point_expiry = min(
                ensure_utc(network_point_expires_at),
                ensure_utc(event.timestamp) + _TLS_RESUMPTION_STATE_HORIZON,
            )
            network_preparation.stage_point(
                NetworkRuntimePointFamily.TLS_SERVER_NAME,
                tls_name_key,
                True,
                expires_at=point_expiry,
            )
            network_preparation.stage_point(
                NetworkRuntimePointFamily.TLS_CLIENT_SERVER_PAIR,
                pair_key,
                True,
                expires_at=point_expiry,
            )
        ssl_hist = _choose_ssl_history_from_roll(
            ssl_history_roll,
            tls_version=tls_version,
            established=ssl_established,
            resumed=resumed,
        )

        event.ssl = SslContext(
            version=tls_version,
            cipher=cipher if ssl_established else "",
            server_name=server_name,
            resumed=resumed,
            established=ssl_established,
            ssl_history=ssl_hist,
        )
        if not ssl_established:
            orig_bytes = rng.randint(90, 260)
            resp_bytes = rng.randint(40, 180) if rng.random() < 0.55 else 0
            history = "ShADd" if resp_bytes else "ShAD"
            orig_pkts, resp_pkts = _tcp_packet_counts_from_payload_and_history(
                orig_bytes,
                resp_bytes,
                history,
                rng,
            )
            orig_ip_bytes = _tcp_ip_byte_count(orig_bytes, orig_pkts, rng)
            resp_ip_bytes = _tcp_ip_byte_count(resp_bytes, resp_pkts, rng)
            duration = (
                (timing_runtime or self.timing_runtime)
                .sampler.sample_timedelta(
                    TruncatedLognormalDistribution(
                        median=28_000.0,
                        sigma=0.88,
                        minimum=37.0,
                        maximum=500_001.0,
                    ),
                    relationship_key="network.failed_transport.tls_handshake_duration",
                    scope=TimingScope(
                        stable_id=(
                            timing_stable_id
                            or (
                                net.transaction.stable_id
                                if isinstance(net, NetworkTransactionDraft)
                                and net.transaction is not None
                                else net.stable_id
                                if isinstance(net, NetworkTransactionPlan)
                                else ""
                            )
                            or net.conn_id
                            or net.zeek_uid
                        ),
                        host=event.src_host.hostname if event.src_host is not None else "",
                        source="network",
                        lifecycle_id=net.conn_id,
                    ),
                    sample_key="tls_handshake",
                )
                .total_seconds()
                if net.duration is not None
                else None
            )
            if isinstance(net, NetworkTransactionPlan):
                closed_at = (
                    net.started_at + timedelta(seconds=duration) if duration is not None else None
                )
                phase_times: tuple[tuple[str, datetime], ...] = (
                    ("transport_start", net.started_at),
                )
                if closed_at is not None:
                    phase_times += (("transport_close", closed_at),)
                event.network = replace(
                    net,
                    closed_at=closed_at,
                    duration=duration,
                    conn_state="S1",
                    history=history,
                    phase_times=phase_times,
                    traffic=NetworkTrafficLedger(
                        orig=DirectionalTrafficLedger(orig_bytes, orig_pkts, orig_ip_bytes),
                        resp=DirectionalTrafficLedger(resp_bytes, resp_pkts, resp_ip_bytes),
                        missed_orig_bytes=net.traffic.missed_orig_bytes,
                        missed_resp_bytes=net.traffic.missed_resp_bytes,
                    ),
                )
                return
            net.conn_state = "S1"
            net.orig_bytes = orig_bytes
            net.resp_bytes = resp_bytes
            net.history = history
            net.orig_pkts = orig_pkts
            net.resp_pkts = resp_pkts
            net.orig_ip_bytes = orig_ip_bytes
            net.resp_ip_bytes = resp_ip_bytes
            if net.duration is not None:
                net.duration = duration
            return

        # Passive Zeek cannot extract the encrypted Certificate message from
        # ordinary TLS 1.3 handshakes. Keep ssl.log evidence but suppress
        # cert_chain_fuids plus files.log/x509.log side effects unless the
        # model grows an explicit TLS decryption context.
        if tls_version == "TLSv13":
            return

        if resumed:
            return
        if internal_cert_name:
            short_name = internal_cert_name.split(".", 1)[0]
            san_dns_list = list(dict.fromkeys([internal_cert_name, short_name]))
        else:
            san_dns_list = _tls_san_dns_names(cert_name)
        tls_certificate_planner = (
            self._tls_certificate_planner
            if network_preparation is None
            else TlsCertificatePlanner(
                network_preparation.cryptographic_material,
                timing_runtime=(
                    timing_runtime if timing_runtime is not None else self.timing_runtime
                ),
            )
        )
        event.tls_presentation = tls_certificate_planner.plan(
            backend_identity=cert_name.rstrip(".").lower(),
            cert_name=cert_name,
            issuer_config=issuer_cfg,
            event_time=event.timestamp,
            connection_identity=net.zeek_uid,
            key_type=key_type,
            key_size=key_length,
            san_dns=tuple(san_dns_list),
        )
        event.x509_chain = tls_certificate_planner.x509_contexts(event.tls_presentation)
        tls_certificate_planner.validate_projection(
            event.tls_presentation,
            event.x509_chain,
        )
        event.x509 = event.x509_chain[0]
        event.ssl = replace(
            event.ssl,
            cert_chain_fuids=tuple(cert.fuid for cert in event.x509_chain),
        )
        self._ensure_tls_conn_covers_certificate_bytes(event, timing_runtime=timing_runtime)

    def _maybe_emit_ocsp_transaction(self, event: OccurrenceBuilder) -> OcspTransactionPlan | None:
        """Emit one action-owned OCSP child only after its TLS parent is finalized."""

        from evidenceforge.generation.activity.tls_realism import ocsp_config

        if event.tls_presentation is None or event.network is None:
            return None
        settings = ocsp_config()
        probability = max(0.0, min(float(settings.get("query_probability", 0.18)), 1.0))
        roll = random.Random(
            _stable_seed(
                "ocsp_query_decision:"
                f"{event.network.zeek_uid}:{event.tls_presentation.leaf.fingerprint}:"
                f"{event.timestamp.isoformat()}"
            )
        ).random()
        if roll >= probability or self.state_manager.state.current_time is None:
            return None
        certificate = event.tls_presentation.leaf
        issuer = self._tls_certificate_planner.authority_material(certificate.issuer_name)
        return OcspTransactionActionBundle(
            executor=self,
            planner=self._ocsp_transaction_planner,
            request=OcspTransactionRequest(
                tls_event=event,
                certificate=certificate,
                issuer=issuer,
                cert_name=certificate.subject_name.removeprefix("CN="),
            ),
        ).execute()

    def _ensure_tls_conn_covers_certificate_bytes(
        self,
        event: OccurrenceBuilder,
        *,
        timing_runtime: Any | None = None,
    ) -> bool:
        """Keep Zeek SSL certificate file evidence within the same conn budget."""
        net = event.network
        if net is None or not event.x509_chain:
            return False

        from evidenceforge.generation.activity.tls_realism import (
            certificate_analyzer_delay_ms,
            certificate_file_size,
        )

        changed = False
        cert_bytes = sum(certificate_file_size(cert) for cert in event.x509_chain)
        min_resp_bytes = cert_bytes + 280
        resp_bytes = net.resp_bytes or 0
        resp_pkts = net.resp_pkts
        resp_ip_bytes = net.resp_ip_bytes or 0
        if resp_bytes < min_resp_bytes:
            resp_bytes = min_resp_bytes
            resp_pkts = max(resp_pkts, max(1, (resp_bytes // 1460) + 1))
            resp_ip_bytes = max(resp_ip_bytes, resp_bytes + (resp_pkts * 40))
            changed = True

        max_cert_delay = max(
            certificate_analyzer_delay_ms(
                zeek_uid=net.zeek_uid,
                event_timestamp=event.timestamp,
                fuid=cert.fuid,
                position=idx,
                timing_runtime=timing_runtime or self.timing_runtime,
            )
            for idx, cert in enumerate(event.x509_chain)
        )
        min_duration = (max_cert_delay / 1000.0) + 0.005
        # Reserve room for files.log and x509.log chain rows before the conn
        # emitter applies its own source-native TLS duration floor.
        min_duration = max(min_duration, 1.05 + (0.075 * len(event.x509_chain)))
        duration = net.duration
        if duration is None or duration < min_duration:
            duration = min_duration
            changed = True
        if not changed:
            return False
        if isinstance(net, NetworkTransactionPlan):
            closed_at = net.started_at + timedelta(seconds=duration)
            phase_times = tuple(
                (name, closed_at if name == "transport_close" else timestamp)
                for name, timestamp in net.phase_times
                if name != "transport_close" or closed_at is not None
            )
            if not any(name == "transport_close" for name, _timestamp in phase_times):
                phase_times += (("transport_close", closed_at),)
            event.network = replace(
                net,
                duration=duration,
                closed_at=closed_at,
                phase_times=phase_times,
                traffic=NetworkTrafficLedger(
                    orig=net.traffic.orig,
                    resp=DirectionalTrafficLedger(resp_bytes, resp_pkts, resp_ip_bytes),
                    missed_orig_bytes=net.traffic.missed_orig_bytes,
                    missed_resp_bytes=net.traffic.missed_resp_bytes,
                ),
            )
        else:
            net.resp_bytes = resp_bytes
            net.resp_pkts = resp_pkts
            net.resp_ip_bytes = resp_ip_bytes
            net.duration = duration
        return changed

    def _pick_profiled_tls_destination(
        self,
        rng: random.Random,
        *,
        src_ip: str,
        source_system: Optional["System"] = None,
        purpose_tags: tuple[str, ...] = (),
    ) -> tuple[str, str]:
        """Pick a profile-aware TLS hostname/IP for baseline external TLS."""
        from evidenceforge.generation.activity.tls_realism import pick_tls_destination

        resolved_source = source_system
        if (
            resolved_source is None
            and hasattr(self, "_ip_to_system")
            and src_ip in self._ip_to_system
        ):
            resolved_source = self._ip_to_system[src_ip]

        source_os = _get_os_category(resolved_source.os) if resolved_source else None
        persona = None
        if resolved_source is not None and getattr(resolved_source, "assigned_user", None):
            user = getattr(self, "_users_by_username", {}).get(resolved_source.assigned_user)
            persona = getattr(user, "persona", None) if user is not None else None

        return pick_tls_destination(
            rng,
            src_host=resolved_source.hostname if resolved_source else src_ip,
            source_os=source_os,
            persona=persona,
            system_type=getattr(resolved_source, "type", None) if resolved_source else None,
            purpose_tags=purpose_tags,
        )

    def _build_expansion_context(
        self,
        event_type: str,
        timestamp: datetime,
        **kwargs: Any,
    ) -> ExpansionContext:
        """Build an ExpansionContext from event parameters and engine state."""
        source_system = kwargs.get("source_system")
        src_ip = kwargs.get("src_ip") or getattr(source_system, "ip", "")
        dns_server_ips = self._dns_resolver_ips_for_source(str(src_ip))
        dc_hostnames = getattr(self, "_dc_hostnames", [])
        ad_domain = getattr(self, "_ad_domain", "corp.local")
        if not hasattr(self, "_dns_cache"):
            self._dns_cache = ExpiringIndex(deadline=lambda window: _dns_cache_window(window)[1])
        if not hasattr(self, "_kerberos_cache"):
            self._kerberos_cache: dict[str, float] = {}

        dc_systems = getattr(self, "_dc_systems", [])
        if not hasattr(self, "_created_account_sids"):
            self._created_account_sids: dict[str, str] = {}

        return ExpansionContext(
            event_type=event_type,
            timestamp=timestamp,
            src_ip=kwargs.get("src_ip"),
            dst_ip=kwargs.get("dst_ip"),
            dst_port=kwargs.get("dst_port"),
            protocol=kwargs.get("protocol") or kwargs.get("proto"),
            service=kwargs.get("service"),
            logon_type=kwargs.get("logon_type"),
            auth_package=kwargs.get("auth_package"),
            command_line=kwargs.get("command_line"),
            process_name=kwargs.get("process_name"),
            os_category=kwargs.get("os_category"),
            hostname=kwargs.get("hostname"),
            source_system=kwargs.get("source_system"),
            target_system=kwargs.get("target_system"),
            actor=kwargs.get("actor"),
            source_pid=kwargs.get("source_pid"),
            source_image=kwargs.get("source_image"),
            target_pid=kwargs.get("target_pid"),
            target_image=kwargs.get("target_image"),
            logon_id=kwargs.get("logon_id"),
            skip_types=kwargs.get("skip_types", set()),
            dns_cache=self._dns_cache,
            kerberos_cache=self._kerberos_cache,
            dns_server_ips=dns_server_ips,
            dc_hostnames=dc_hostnames,
            dc_systems=dc_systems,
            ad_domain=ad_domain,
            sid_registry=self.sid_registry,
            created_account_sids=self._created_account_sids,
        )

    def _dns_resolver_ips_for_source(self, source_ip: str) -> list[str]:
        """Return modeled resolvers or one stable public-operator pool for a source."""

        configured = list(getattr(self, "_dns_server_ips", None) or [])
        if configured and not getattr(self, "_dns_server_ips_are_public_fallback", False):
            return configured
        return public_dns_resolver_ips(source_ip) or configured

    def _expand_and_emit(
        self,
        event_type: str,
        timestamp: datetime,
        **kwargs: Any,
    ) -> None:
        """Run causal expansion and emit all expanded prerequisite/consequent events.

        This is a no-op if:
        - No causal engine is configured.
        - We are already expanding the same event type (prevents same-type recursion).

        Cross-type expansion is allowed: a process_create expansion can trigger
        a connection expansion (which triggers DNS), but connection cannot
        recursively trigger another connection expansion.
        """
        if event_type in self._expanding_types:
            logger.debug("Skipping nested %s expansion (already expanding)", event_type)
            return

        ctx = self._build_expansion_context(event_type, timestamp, **kwargs)
        expanded = self._causal_engine.expand(event_type, ctx)
        if not expanded:
            return

        rng = _get_rng()
        self._expanding_types.add(event_type)
        try:
            previous_after_time: datetime | None = None
            for ev in expanded:
                offset_ms = rng.randint(ev.timing.min_ms, ev.timing.max_ms)
                offset = timedelta(milliseconds=offset_ms)
                if ev.timing.position == "before":
                    ev.kwargs["time"] = timestamp - offset
                else:
                    ev.kwargs["time"] = timestamp + offset
                    if event_type == "process_create":
                        process_system = kwargs.get("target_system") or kwargs.get("source_system")
                        source_pid = kwargs.get("source_pid")
                        if process_system is not None and isinstance(source_pid, int):
                            ev.kwargs["time"] = self._clamp_after_visible_process_create(
                                process_system,
                                source_pid,
                                ev.kwargs["time"],
                                "windows.audit_after_visible_admin_command",
                            )
                    if previous_after_time is not None and ev.kwargs["time"] <= previous_after_time:
                        ev.kwargs["time"] = previous_after_time + timedelta(milliseconds=1)
                    previous_after_time = ev.kwargs["time"]

                method = getattr(self, ev.method)
                method(**ev.kwargs)
        finally:
            self._expanding_types.discard(event_type)

    def generate_logon(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_type: int = 2,
        source_ip: str | None = None,
        source_system: System | None = None,
        source_port: int | None = None,
        emit_transport_syslog: bool = True,
        emit_network_evidence: bool = True,
        logon_id: str | None = None,
        reuse_required_at: datetime | None = None,
        lifecycle_group_id: str = "",
        session_end_plan: SessionEndPlan | None = None,
        remote_authentication_plan: RemoteAuthenticationPlan | None = None,
        remote_authentication_transport_id: str = "",
        remote_auth_destination_port: int | None = None,
        session_kind: str | None = None,
        auth_protocol: str = "",
        smb_principal: str = "",
        account_scope: str = "",
        auth_session_ref: str = "",
        effective_uid: int | None = None,
        effective_gid: int | None = None,
        source: str = "activity_generator",
    ) -> str:
        """Generate logon event across all applicable log formats.

        Creates or reuses a session in StateManager, builds a OccurrenceBuilder,
        and dispatches to matching emitters (Windows 4624 + optional 4672,
        syslog auth, eCAR).

        Args:
            user: User logging on
            system: System being logged into
            time: Logon timestamp
            logon_type: Windows logon type (2=interactive, 3=network, 10=remote interactive)
            source_ip: Source IP address for remote logons. Local logons render with no
                source address in Windows Security, but still use the host IP for DC-side
                authentication evidence when applicable.

        Returns:
            LogonID (hex string format, e.g., "0x3e7")
        """
        request = LogonRequest(
            user=user,
            system=system,
            time=time,
            logon_type=logon_type,
            source_ip=source_ip,
            source_system=source_system,
            source_port=source_port,
            emit_transport_syslog=emit_transport_syslog,
            emit_network_evidence=emit_network_evidence,
            logon_id=logon_id,
            reuse_required_at=reuse_required_at,
            lifecycle_group_id=lifecycle_group_id,
            session_end_plan=session_end_plan,
            remote_authentication_plan=remote_authentication_plan,
            remote_authentication_transport_id=remote_authentication_transport_id,
            remote_auth_destination_port=remote_auth_destination_port,
            session_kind=session_kind,
            auth_protocol=auth_protocol,
            smb_principal=smb_principal,
            account_scope=account_scope,
            auth_session_ref=auth_session_ref,
            effective_uid=effective_uid,
            effective_gid=effective_gid,
            source=source,
        )
        return LogonActionBundle(self, request).execute()

    def _execute_logon_bundle(self, request: LogonRequest) -> str:
        """Expand a successful logon bundle through the compatibility adapter."""
        user = request.user
        system = request.system
        time = request.time
        logon_type = request.logon_type
        source_ip = request.source_ip
        source_system = request.source_system
        source_port = request.source_port
        emit_transport_syslog = request.emit_transport_syslog
        emit_network_evidence = request.emit_network_evidence
        logon_id = request.logon_id
        lifecycle_group_id = request.lifecycle_group_id or request.stable_id
        remote_authentication_plan = request.remote_authentication_plan
        remote_authentication_transport_id = request.remote_authentication_transport_id

        if logon_type == 9:
            raise StateError(
                "Generic logon_type 9 cannot supply NewCredentials caller and outbound "
                "identity; author an explicit_credentials event using runas.exe /netonly"
            )

        os_cat = _get_os_category(system.os)
        remote_source_ready_delta = (
            self._freeze_profile_activity_gap(
                "windows.remote_logon_source_ready",
                stable_id=request.stable_id,
                host=system.hostname,
                source="authentication",
                lifecycle_id=request.logon_id or request.stable_id,
                sample_key="remote_source_ready",
            )
            if os_cat == "windows" and logon_type == 3
            else None
        )
        remote_source_ready_used = False
        self.state_manager.set_current_time(time)
        if logon_type == 10 and os_cat == "linux" and source_ip in (None, "", "-", system.ip):
            logon_type = 2
            source_ip = None
        if logon_type == 10 and os_cat == "windows" and source_ip in (None, "", "-", system.ip):
            logon_type = 2
            source_ip = None
        if logon_type == 3 and os_cat == "linux" and source_ip in (None, "", "-", system.ip):
            logon_type = 2
            source_ip = None
        if (
            logon_type == 3
            and os_cat == "windows"
            and source_ip in (None, "", "-")
            and getattr(self, "_all_system_ips", [])
        ):
            is_service_account = user.username.endswith("$") or user.username.lower().startswith(
                "svc"
            )
            source_ip = self._baseline_type3_source_ip(
                user,
                system,
                _get_rng(),
                is_service_account=is_service_account,
            )
            if source_ip is None:
                logon_type = 2
        if (
            logon_type == 10
            and os_cat == "windows"
            and source_ip not in (None, "", "-", system.ip)
            and emit_network_evidence
        ):
            explicit_source_system = source_system
            if explicit_source_system is None and source_ip is not None:
                explicit_source_system = self._ip_to_system.get(source_ip)
            _, rendered_logon_id = self._execute_rdp_session_bundle(
                user=user,
                target_system=system,
                time=time,
                source_ip=source_ip,
                source_system=explicit_source_system,
                source_port=source_port,
                logon_id=logon_id,
                preserve_explicit_source=True,
                session_end_plan=request.session_end_plan,
            )
            return rendered_logon_id
        if logon_id is None and os_cat == "windows" and logon_type in (2, 11):
            existing_interactive = self._active_user_workstation_windows_session(
                user,
                system,
                time,
            )
            if existing_interactive is not None:
                reusable = (
                    request.reuse_required_at is None
                    or self.state_manager.get_session_at(
                        existing_interactive.logon_id,
                        request.reuse_required_at,
                    )
                    is not None
                )
                if reusable:
                    existing_interactive.last_activity_time = time
                    return existing_interactive.logon_id

        windows_remote_auth_port: int | None = None
        if os_cat == "windows" and logon_type == 10:
            windows_remote_auth_port = 3389
        elif os_cat == "windows" and logon_type == 3:
            if request.remote_auth_destination_port is not None:
                windows_remote_auth_port = request.remote_auth_destination_port
            elif request.session_kind == "smb" or remote_authentication_transport_id:
                windows_remote_auth_port = 445
        if windows_remote_auth_port is not None and not 1 <= windows_remote_auth_port <= 65535:
            raise ValueError("remote_auth_destination_port must be between 1 and 65535")
        if (
            logon_id is None
            and os_cat == "linux"
            and logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES
            and source_ip in (None, "", "-", system.ip)
        ):
            existing_interactive = self._active_user_local_linux_session(
                user,
                system,
                time,
            )
            if existing_interactive is not None:
                reusable = (
                    request.reuse_required_at is None
                    or self.state_manager.get_session_at(
                        existing_interactive.logon_id,
                        request.reuse_required_at,
                    )
                    is not None
                )
                if reusable:
                    existing_interactive.last_activity_time = time
                    return existing_interactive.logon_id
        local_logon = (
            windows_logon_has_local_source(logon_type)
            if os_cat == "windows"
            else logon_type in (2, 5, 7, 11)
        )
        dc_source_ip = source_ip or system.ip
        if source_ip is None:
            source_ip = "-" if local_logon else system.ip
        auth_source_ip = "-" if local_logon else source_ip
        if not local_logon and source_port is None and source_ip and source_ip != "-":
            if logon_type == 3 and source_ip == system.ip:
                source_port = 0
            elif os_cat == "windows" and logon_type in (3, 10):
                if windows_remote_auth_port is not None:
                    source_port = self._allocate_ephemeral_port(
                        source_ip,
                        system.ip,
                        windows_remote_auth_port,
                        "tcp",
                        time,
                        self._os_for_ip(source_ip),
                    )
                else:
                    source_port = _ephemeral_port(_get_rng(), self._os_for_ip(source_ip))
            else:
                source_port = _ephemeral_port(_get_rng(), self._os_for_ip(source_ip))

        # Linux type-10 remote logons are SSH, not RDP
        if request.session_kind:
            session_kind = request.session_kind
        elif logon_type == 10 and os_cat == "linux":
            session_kind = "ssh"
        else:
            session_kind = {
                3: "network",
                4: "batch",
                5: "service",
                8: "network_cleartext",
                9: "new_credentials",
                10: "rdp",
            }.get(logon_type, "interactive")

        if (
            os_cat == "linux"
            and logon_type == 10
            and source_ip
            and source_ip not in {"-", system.ip}
        ):
            if logon_id is None:
                logon_id = self.state_manager.create_session(
                    username=user.username,
                    system=system.hostname,
                    logon_type=logon_type,
                    source_ip=auth_source_ip,
                    source_port=source_port or 0,
                    session_kind="ssh",
                    lifecycle_group_id=lifecycle_group_id,
                )
            else:
                existing_session = self.state_manager.get_session(logon_id)
                if existing_session is None:
                    self.state_manager.register_session(
                        logon_id=logon_id,
                        username=user.username,
                        system=system.hostname,
                        logon_type=logon_type,
                        source_ip=auth_source_ip,
                        start_time=time,
                        source_port=source_port or 0,
                        session_kind="ssh",
                        lifecycle_group_id=lifecycle_group_id,
                    )
                else:
                    self.state_manager.update_session_metadata(
                        logon_id,
                        source_ip=auth_source_ip,
                        source_port=source_port or 0,
                        session_kind="ssh",
                    )

            session_obj_id = self.state_manager.get_session_object_id(logon_id)
            source_system = (
                self._ip_to_system.get(source_ip) if hasattr(self, "_ip_to_system") else None
            )
            self.generate_ssh_session(
                user=user,
                target_system=system,
                time=time,
                source_ip=source_ip,
                source_system=source_system,
                source_port=source_port,
                logon_id=logon_id,
                session_obj_id=session_obj_id,
                session_end_plan=request.session_end_plan,
                source="linux_logon_compat",
            )
            session = self.state_manager.get_session(logon_id)
            if session is not None:
                session.last_activity_time = time
            logger.debug(
                "Generated Linux SSH logon via SSH bundle: %s on %s (LogonID: %s)",
                user.username,
                system.hostname,
                logon_id,
            )
            return logon_id

        # Select auth package (semantic data, not format-specific)
        auth_pkg = self._select_auth_package(logon_type)
        if request.auth_protocol == "kerberos":
            auth_pkg = {
                **auth_pkg,
                "AuthenticationPackageName": "Kerberos",
                "LogonProcessName": "Kerberos",
                "LmPackageName": "-",
            }
        elif request.auth_protocol == "ntlmssp":
            auth_pkg = {
                **auth_pkg,
                "AuthenticationPackageName": "NTLM",
                "LogonProcessName": "NtLmSsp",
                "LmPackageName": "NTLM V2",
            }
        resolved_auth_protocol = request.auth_protocol
        if request.session_kind == "smb" and not resolved_auth_protocol:
            resolved_auth_protocol = (
                "ntlmssp"
                if auth_pkg.get("AuthenticationPackageName", "").casefold() == "ntlm"
                else "kerberos"
            )
        requires_logon_guid = auth_pkg.get("LogonGuid") != "{00000000-0000-0000-0000-000000000000}"

        # Phase 1: Allocate or resolve IDs from StateManager
        local_linux_session = (
            os_cat == "linux"
            and logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES
            and session_kind not in _LINUX_REMOTE_SESSION_KINDS
        )
        if logon_id is None:
            logon_id = self.state_manager.create_session(
                username=user.username,
                system=system.hostname,
                logon_type=logon_type,
                source_ip=auth_source_ip,
                source_port=source_port or 0,
                session_kind=session_kind,
                logon_guid_required=requires_logon_guid,
                lifecycle_group_id=lifecycle_group_id,
                auth_protocol=resolved_auth_protocol,
                smb_principal=request.smb_principal,
                account_scope=request.account_scope,
                auth_session_ref=request.auth_session_ref,
                effective_uid=request.effective_uid,
                effective_gid=request.effective_gid,
                session_id=0 if local_linux_session else None,
            )
        else:
            existing_session = self.state_manager.get_session(logon_id)
            if existing_session is None:
                self.state_manager.register_session(
                    logon_id=logon_id,
                    username=user.username,
                    system=system.hostname,
                    logon_type=logon_type,
                    source_ip=auth_source_ip,
                    start_time=time,
                    source_port=source_port or 0,
                    session_kind=session_kind,
                    logon_guid_required=requires_logon_guid,
                    lifecycle_group_id=lifecycle_group_id,
                    auth_protocol=resolved_auth_protocol,
                    smb_principal=request.smb_principal,
                    account_scope=request.account_scope,
                    auth_session_ref=request.auth_session_ref,
                    effective_uid=request.effective_uid,
                    effective_gid=request.effective_gid,
                    session_id=0 if local_linux_session else None,
                )
            else:
                self.state_manager.update_session_metadata(
                    logon_id,
                    source_ip=auth_source_ip,
                    source_port=source_port or 0,
                    session_kind=session_kind,
                    auth_protocol=resolved_auth_protocol,
                    smb_principal=request.smb_principal,
                    account_scope=request.account_scope,
                    auth_session_ref=request.auth_session_ref,
                    effective_uid=request.effective_uid,
                    effective_gid=request.effective_gid,
                )
            if (
                existing_session is not None
                and logon_type != 7
                and existing_session.start_time < time
            ):
                time = existing_session.start_time
                self.state_manager.set_current_time(time)

        if local_linux_session:
            self._ensure_linux_local_session_id(user, system, time, logon_id)

        if request.session_end_plan is not None:
            self.state_manager.plan_session_end(logon_id, request.session_end_plan)

        session_for_login = self.state_manager.get_session(logon_id)
        if (
            os_cat == "linux"
            and logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES
            and session_for_login is not None
            and session_for_login.login_occurrence_emitted
        ):
            session_for_login.last_activity_time = time
            return logon_id

        auth_logon_guid = self.state_manager.get_or_create_session_logon_guid(
            logon_id,
            system.hostname,
            require_nonzero=requires_logon_guid,
        )
        session_for_guid = self.state_manager.get_session(logon_id)
        session_id = session_for_guid.session_id if session_for_guid is not None else 0
        elevated = self._should_elevate(user, logon_type=logon_type, hostname=system.hostname)
        emit_special_privileges = elevated and self._claim_privileged_auth_occurrence(
            request.stable_id
        )
        privilege_list = (
            self._select_special_privileges(user, logon_type, system.hostname) if elevated else ""
        )

        if os_cat == "linux" and logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES:
            self._emit_linux_local_logon_syslog(user, system, time, logon_id)
            session_for_guid = self.state_manager.get_session(logon_id)
            session_id = session_for_guid.session_id if session_for_guid is not None else 0

        logon_caller_pid = 0
        logon_caller_process = ""
        if os_cat == "windows" and logon_type in {2, 7, 10, 11}:
            session_for_caller = self.state_manager.get_session(logon_id)
            if session_for_caller is not None:
                logon_caller_pid = session_for_caller.session_winlogon_pid or 0
                if logon_caller_pid <= 0 and logon_type != 7:
                    self.state_manager.set_current_time(time)
                    sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
                    parent_for_chain = next(
                        (
                            pid
                            for candidate in ("smss", "wininit", "winlogon", "services")
                            if (pid := sys_pids.get(candidate))
                            and self.state_manager.get_process(system.hostname, pid) is not None
                        ),
                        None,
                    )
                    if parent_for_chain is not None:
                        caller_start = time - timedelta(
                            milliseconds=700
                            + (
                                _stable_seed(
                                    "windows_session_winlogon_start:"
                                    f"{system.hostname}:{logon_id}:{time.isoformat()}"
                                )
                                % 1801
                            )
                        )
                        self.state_manager.set_current_time(caller_start)
                        logon_caller_pid = self.state_manager.create_process(
                            system.hostname,
                            parent_for_chain,
                            r"C:\Windows\System32\winlogon.exe",
                            "winlogon.exe",
                            "SYSTEM",
                            "System",
                            logon_id="0x3e7",
                        )
                        self.state_manager.set_current_time(time)
                        session_for_caller.session_winlogon_pid = logon_caller_pid
                        session_for_caller.process_tree_root = logon_caller_pid
                if logon_caller_pid > 0:
                    logon_caller_process = r"C:\Windows\System32\winlogon.exe"

        # Phase 2: Build OccurrenceBuilder with all contexts
        # For network logons (type 3, 10), resolve source host from source_ip
        src_host_ctx = None
        if logon_type in (3, 10) and source_ip and source_ip != "-":
            if source_system is not None:
                src_host_ctx = self._build_host_context(source_system)
            elif hasattr(self, "_ip_to_system") and source_ip in self._ip_to_system:
                src_host_ctx = self._build_host_context(self._ip_to_system[source_ip])

        session_obj_id = self.state_manager.get_session_object_id(logon_id)
        if logon_type == 7:
            # Type 7 is a workstation unlock re-auth against an existing LUID.
            # eCAR object lifecycles should still be single-login, so model the
            # re-auth as a child observation linked to the durable session.
            session_obj_id = stable_uuid(
                "ecar-unlock-reauth",
                system.hostname,
                logon_id,
                time.isoformat(),
            )
        subject = self._successful_logon_subject_fields(
            user=user,
            system=system,
            logon_type=logon_type,
            time=time,
            source_ip=auth_source_ip,
            source_system=source_system,
            logon_id=logon_id,
        )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="logon",
            src_host=src_host_ctx,
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=user.username,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session_id,
                logon_type=logon_type,
                auth_package=auth_pkg.get("AuthenticationPackageName", "Negotiate"),
                source_ip=auth_source_ip,
                source_port=source_port or 0,
                elevated=elevated,
                emit_special_privileges=emit_special_privileges,
                logon_process=auth_pkg.get("LogonProcessName", ""),
                lm_package=auth_pkg.get("LmPackageName", "-"),
                logon_guid=auth_logon_guid,
                subject_sid=subject["sid"],
                subject_username=subject["username"],
                subject_domain=subject["domain"],
                subject_logon_id=subject["logon_id"],
                privilege_list=privilege_list,
                reporting_pid=self._get_system_pid(system.hostname, "lsass", 0x2E0),
                process_pid=logon_caller_pid,
                process_name=logon_caller_process,
                session_kind=session_kind,
                auth_protocol=resolved_auth_protocol,
                smb_principal=request.smb_principal,
                account_scope=request.account_scope,
                auth_session_ref=request.auth_session_ref,
                effective_uid=request.effective_uid,
                effective_gid=request.effective_gid,
            ),
            remote_auth=remote_authentication_plan,
        )

        is_windows_remote_auth = (
            os_cat == "windows"
            and logon_type in {3, 10}
            and auth_source_ip not in {"", "-", system.ip}
        )
        if (
            is_windows_remote_auth
            and remote_authentication_plan is None
            and windows_remote_auth_port is not None
        ):
            remote_request = WindowsRemoteAuthenticationRequest(
                target_system=system,
                time=time,
                source_ip=auth_source_ip,
                source_port=source_port or 0,
                logon_type=logon_type,
                auth_protocol=auth_pkg.get("AuthenticationPackageName", "Negotiate"),
                outcome="success",
                destination_port=windows_remote_auth_port,
                source_system=source_system or self._ip_to_system.get(auth_source_ip),
                session_object_id=session_obj_id,
                logon_id=logon_id,
                emit_transport=emit_network_evidence,
                source=request.source,
            )
            planner = WindowsRemoteAuthenticationPlanner(self)
            if emit_network_evidence:
                remote_authentication_plan = WindowsRemoteAuthenticationActionBundle(
                    self,
                    remote_request,
                ).execute()
            else:
                remote_authentication_plan = (
                    planner.from_existing_transaction(
                        remote_request,
                        remote_authentication_transport_id,
                    )
                    if remote_authentication_transport_id
                    else None
                ) or planner.without_transport(remote_request)
            event.remote_auth = remote_authentication_plan
        if remote_authentication_plan is not None:
            self.state_manager.update_session_metadata(
                logon_id,
                parent_lifecycle_group_id=remote_authentication_plan.stable_id,
            )
        event.lifecycle = ActionLifecycleContext(
            group_id=lifecycle_group_id,
            canonical_start=time,
            phase="start",
            parent_group_id=(
                remote_authentication_plan.stable_id
                if remote_authentication_plan is not None
                else None
            ),
        )

        # Attach SyslogContext for Linux SSH sessions only (not network/interactive)
        session_for_syslog = self.state_manager.get_session(logon_id) if logon_id else None
        is_ssh_session = (
            session_for_syslog and getattr(session_for_syslog, "session_kind", None) == "ssh"
        ) or logon_type == 10  # logon_type 10 = remote (SSH on Linux)
        if (
            event.dst_host
            and event.dst_host.os_category == "linux"
            and emit_transport_syslog
            and is_ssh_session
            and auth_source_ip not in {"", "-", system.ip}
        ):
            from evidenceforge.events.contexts import SyslogContext

            session = self.state_manager.get_session(logon_id)
            effective_source_port = source_port or (session.source_port if session else 0)
            sshd_release_time = (
                ensure_utc(session.end_plan.canonical_end)
                if session is not None and session.end_plan is not None
                else (
                    ensure_utc(session.network_close_time)
                    if session is not None and session.network_close_time is not None
                    else min(self._scenario_end_time, ensure_utc(time) + timedelta(hours=12))
                )
            )
            sshd_pid = (
                session.transport_pid
                if session and session.transport_pid is not None
                else self.state_manager.allocate_transient_linux_pid(
                    system.hostname,
                    time,
                    os_category=_get_os_category(system.os),
                    release_time=sshd_release_time,
                )
            )
            self.state_manager.update_session_metadata(
                logon_id,
                source_port=effective_source_port,
                transport_pid=sshd_pid,
            )
            event.syslog = SyslogContext(
                app_name="sshd",
                pid=sshd_pid,
                facility=10,
                severity=6,
                message=(
                    f"Accepted password for {user.username} from {auth_source_ip} "
                    f"port {effective_source_port or _ephemeral_port(_get_rng(), 'linux')} ssh2"
                ),
            )

        # Emit DC-side Kerberos events for domain logons via causal expansion.
        # The target-host 4624 renderer owns 4672 for elevated sessions because
        # that privilege assignment belongs to the host where the logon session
        # is created, not to the DC ticket request itself.
        auth_package_name = auth_pkg.get("AuthenticationPackageName", "Negotiate")
        self._expand_and_emit(
            "logon",
            time,
            actor=user,
            target_system=system,
            auth_package=auth_package_name,
            src_ip=dc_source_ip,
            os_category=_get_os_category(system.os),
        )
        if (
            auth_package_name == "NTLM"
            and logon_type in (3, 10)
            and _get_os_category(system.os) == "windows"
            and source_ip
            and source_ip != "-"
        ):
            self._emit_dc_ntlm_for_logon(user, system, time, source_ip)

        if os_cat == "windows" and logon_type == 3 and auth_source_ip not in {"", "-", system.ip}:
            if remote_source_ready_delta is None:
                raise StateError("Remote source readiness lost its frozen timing delta")
            ready_time = ensure_utc(time) + remote_source_ready_delta.value
            remote_source_ready_used = True
            session = self.state_manager.get_session(logon_id)
            existing_ready_time = _session_source_ready_time(session) if session else None
            if existing_ready_time is None or existing_ready_time < ready_time:
                self.state_manager.update_session_metadata(
                    logon_id,
                    source_ready_time=ready_time,
                )

        # Phase 3: Dispatch to matching emitters
        self.dispatcher.dispatch_builder(event)
        if os_cat == "linux" and logon_type in _LINUX_LOCAL_SESSION_LOGON_TYPES:
            session_for_login = self.state_manager.get_session(logon_id)
            if session_for_login is not None:
                session_for_login.login_occurrence_emitted = True

        # Interactive child processes cannot be visible to eCAR before the
        # source-native session login that owns their LogonID.  The session
        # renderer finalizes that timestamp during dispatch, so publish it as
        # the readiness floor before materializing the shell lifecycle.
        if (
            os_cat == "windows"
            and windows_logon_can_own_desktop(logon_type)
            and event.lifecycle is not None
        ):
            ecar_login_time = self.dispatcher.source_timing_planner.session_start_source_time(
                "ecar",
                event.lifecycle.group_id,
            )
            session = self.state_manager.get_session(logon_id)
            existing_ready_time = _session_source_ready_time(session) if session else None
            if ecar_login_time is not None and (
                existing_ready_time is None or existing_ready_time < ecar_login_time
            ):
                self.state_manager.update_session_metadata(
                    logon_id,
                    source_ready_time=ecar_login_time,
                )

        # Phase 4: Create per-session explorer.exe for interactive logons
        if windows_logon_can_own_desktop(logon_type):
            session = self.state_manager.get_session(logon_id)
            if session is not None:
                os_cat = _get_os_category(system.os)
                if os_cat == "windows":
                    sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
                    parent_for_chain = None
                    for candidate in ("smss", "wininit", "winlogon", "services"):
                        pid = sys_pids.get(candidate)
                        if pid and self.state_manager.get_process(system.hostname, pid):
                            parent_for_chain = pid
                            break
                    if parent_for_chain is not None and not session.windows_shell_bootstrapped:
                        winlogon_pid = session.session_winlogon_pid
                        if winlogon_pid is None:
                            winlogon_pid = self.state_manager.create_process(
                                system.hostname,
                                parent_for_chain,
                                r"C:\Windows\System32\winlogon.exe",
                                "winlogon.exe",
                                "SYSTEM",
                                "System",
                                logon_id="0x3e7",
                            )
                            session.session_winlogon_pid = winlogon_pid
                        explorer_pid = self._create_windows_session_shell_lifecycle(
                            user=user,
                            system=system,
                            session=session,
                            winlogon_pid=winlogon_pid,
                            logon_time=time,
                        )
                        session.explorer_pid = explorer_pid
                        session.initial_explorer_pid = explorer_pid
                        session.process_tree_root = winlogon_pid
                        session.windows_shell_bootstrapped = True
                session.last_activity_time = time

        if remote_source_ready_used:
            remote_source_ready_delta.publish()
        logger.debug(f"Generated logon: {user.username} on {system.hostname} (LogonID: {logon_id})")
        return logon_id

    def _emit_linux_local_logon_syslog(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> None:
        """Emit logind open evidence for a durable local Linux session."""
        if self.dispatcher is None or logon_id in self._linux_local_logon_syslog_sessions:
            return
        if _get_os_category(system.os) != "linux":
            return
        session = self.state_manager.get_session(logon_id)
        if (
            session is None
            or session.logon_type not in _LINUX_LOCAL_SESSION_LOGON_TYPES
            or session.session_kind in {"network", "service"}
            or (session.session_kind == "ssh" and session.source_ip not in {"", "-", system.ip})
        ):
            return

        rng = random.Random(
            _stable_seed(f"linux_local_logon_syslog:{system.hostname}:{user.username}:{logon_id}")
        )
        logind_time = time - timedelta(milliseconds=rng.randint(20, 80))
        session_id = self._ensure_linux_local_session_id(user, system, time, logon_id)
        self._linux_local_logind_session_ids[logon_id] = session_id
        system_type = (system.type or "workstation").lower()
        pam_service = (
            "login"
            if system_type in {"server", "domain_controller"} or user.username == "root"
            else "gdm-password"
        )
        pam_actor = "LOGIN(uid=0)" if pam_service == "login" else "gdm(uid=0)"
        pam_time = logind_time - timedelta(milliseconds=rng.randint(3000, 8000))
        if pam_service == "login":
            login_start_time = pam_time - timedelta(milliseconds=rng.randint(2500, 4500))
            root_parent_pid = self._linux_local_login_parent_pid(
                system,
                login_start_time,
                seed=_stable_seed(
                    f"linux_local_login_parent:{system.hostname}:{user.username}:{logon_id}"
                ),
            )
            pam_pid = self.generate_process(
                user=self._user_model_for_username("root"),
                system=system,
                time=login_start_time,
                logon_id="0x3e7",
                process_name="/bin/login",
                command_line=f"login -- {user.username}",
                parent_pid=root_parent_pid,
                suppress_command_file_effect=True,
                lifecycle_group_id=session.lifecycle_group_id,
                source_visible_by=pam_time,
            )
            if pam_pid > 0:
                session.process_tree_root = pam_pid
                pam_time = self._clamp_after_visible_linux_process_create(
                    system,
                    pam_pid,
                    pam_time,
                    relationship_key="source.ecar_dependent_after_process_create",
                    later_source="syslog",
                )
            else:
                pam_pid = self.state_manager.allocate_transient_linux_pid(
                    system.hostname,
                    pam_time,
                    os_category="linux",
                )
            logind_time = max(
                logind_time,
                pam_time + timedelta(milliseconds=rng.randint(350, 1100)),
            )
        else:
            pam_pid = self.state_manager.allocate_transient_linux_pid(
                system.hostname,
                pam_time,
                os_category="linux",
            )
        self.generate_syslog_event(
            system=system,
            time=pam_time,
            app_name=pam_service,
            message=(
                f"pam_unix({pam_service}:session): session opened for user "
                f"{user.username}(uid={_linux_uid_for_user(user.username)}) by {pam_actor}"
            ),
            pid=pam_pid,
            facility=10,
            auth=AuthContext(
                username=user.username,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session_id,
                logon_type=session.logon_type,
                source_ip="-",
            ),
        )
        self.generate_syslog_event(
            system=system,
            time=logind_time,
            app_name="systemd-logind",
            message=f"New session {session_id} of user {user.username}.",
            pid=self._get_system_pid(system.hostname, "logind", 456),
            facility=10,
            auth=AuthContext(
                username=user.username,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session_id,
                logon_type=session.logon_type,
                source_ip="-",
            ),
        )

        self._linux_local_logon_syslog_sessions.add(logon_id)

    def _ensure_linux_local_session_id(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> int:
        """Allocate a local Linux logind identity before publishing session members."""
        session = self.state_manager.get_session(logon_id)
        if session is None:
            raise StateError(f"Cannot allocate Linux session ID for unknown LogonID {logon_id}")
        if session.session_id > 0:
            return session.session_id

        rng = random.Random(
            _stable_seed(f"linux_local_logon_syslog:{system.hostname}:{user.username}:{logon_id}")
        )
        logind_time = ensure_utc(time) - timedelta(milliseconds=rng.randint(20, 80))
        session_id = self.state_manager.next_linux_logind_session_id(
            system.hostname,
            rng,
            logind_time,
        )
        self.state_manager.update_session_metadata(logon_id, session_id=session_id)
        return session_id

    def _emit_dc_ntlm_for_logon(
        self,
        user: User,
        system: System,
        time: datetime,
        source_ip: str,
    ) -> None:
        """Emit DC-side 4776 validation for successful domain NTLM logons."""
        if _get_os_category(system.os) != "windows":
            return

        dc_hostnames = getattr(self, "_dc_hostnames", [])
        dc_ips = getattr(self, "_dc_ips", [])
        if not dc_hostnames:
            return
        if system.hostname in dc_hostnames or system.ip in dc_ips:
            return

        rng = _get_rng()
        dc_hostname = dc_hostnames[rng.randint(0, len(dc_hostnames) - 1)]
        workstation = self._workstation_name_for_source(source_ip)
        self.generate_ntlm_validation(
            username=user.username,
            workstation=workstation,
            dc_hostname=dc_hostname,
            time=time - timedelta(milliseconds=rng.randint(8, 120)),
            status="0x0",
        )

    def _emit_dc_kerberos_for_logon(
        self,
        user: User,
        system: System,
        time: datetime,
        auth_package: str,
        source_ip: str,
    ) -> None:
        """Emit DC-side Kerberos evidence for a domain logon via an action bundle."""
        request = KerberosLogonTicketsRequest(
            user=user,
            system=system,
            time=time,
            auth_package=auth_package,
            source_ip=source_ip,
        )
        KerberosLogonTicketsActionBundle(self, request).execute()

    def _execute_kerberos_logon_tickets_bundle(
        self,
        request: KerberosLogonTicketsRequest,
    ) -> None:
        """Emit DC-side Kerberos TGT (4768) and service ticket (4769) for domain logons.

        In a real AD environment, when a user authenticates via Kerberos:
        1. Client requests TGT from DC (4768) ~50-200ms before logon
        2. Client requests service ticket for target host (4769) ~20-100ms after TGT
        3. Target host logs the 4624

        Only emits when:
        - Auth package is Kerberos (not NTLM)
        - Target system is Windows
        - System is not the DC itself
        - A DC is known in the scenario
        """
        user = request.user
        system = request.system
        time = request.time
        auth_package = request.auth_package
        source_ip = request.source_ip

        # Only emit for explicit Kerberos auth on Windows systems.
        # "Negotiate" can fall back to NTLM, and CredSSP (RDP) uses its own
        # auth flow — only pure "Kerberos" auth triggers DC-side TGT/TGS.
        if auth_package != "Kerberos":
            return

        os_cat = _get_os_category(system.os)
        if os_cat != "windows":
            return

        dc_hostnames = getattr(self, "_dc_hostnames", [])
        dc_ips = getattr(self, "_dc_ips", [])
        if not dc_hostnames:
            return

        # Don't emit Kerberos events when logging onto the DC itself
        if system.hostname in dc_hostnames or system.ip in dc_ips:
            return

        rng = _get_rng()
        dc_idx = rng.randint(0, len(dc_hostnames) - 1)
        dc_hostname = dc_hostnames[dc_idx]

        # TGT and service ticket requests both precede the target-host 4624.
        # Keep TGT before TGS, and TGS before member-host logon.
        tgt_time, tgs_time = self._kerberos_ticket_times(
            time,
            rng,
            tgs_before_ms=(20, 100),
            tgt_before_tgs_ms=(35, 240),
        )
        self._maybe_generate_kerberos_tgt(
            username=user.username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=tgt_time,
            rng=rng,
        )

        role_names = {str(role).lower() for role in (getattr(system, "roles", []) or [])}
        service_names = {
            str(service).lower() for service in (getattr(system, "services", []) or [])
        }
        hostname_lower = system.hostname.lower()
        if "file_server" in role_names or "file" in hostname_lower or "smb" in service_names:
            service_dist = (
                ("cifs/{hostname}", 70),
                ("host/{hostname}", 25),
                ("ldap/{hostname}", 5),
            )
        elif "web_server" in role_names or any("http" in service for service in service_names):
            service_dist = (
                ("http/{hostname}", 65),
                ("host/{hostname}", 30),
                ("cifs/{hostname}", 5),
            )
        elif "dns_server" in role_names or "dns" in service_names:
            service_dist = (
                ("DNS/{hostname}", 55),
                ("host/{hostname}", 35),
                ("cifs/{hostname}", 10),
            )
        else:
            service_dist = (
                ("cifs/{hostname}", 45),
                ("host/{hostname}", 35),
                ("ldap/{hostname}", 10),
                ("http/{hostname}", 5),
                ("DNS/{hostname}", 5),
            )
        _svc_template = rng.choices(
            [entry[0] for entry in service_dist],
            weights=[entry[1] for entry in service_dist],
            k=1,
        )[0]
        service_name = _svc_template.format(
            hostname=system.hostname, domain=getattr(self, "_ad_domain", "CORP.LOCAL")
        )
        self.generate_kerberos_service_ticket(
            username=user.username,
            service_name=service_name,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=tgs_time,
        )

    def generate_failed_logon(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_type: int = 2,
        source_ip: str | None = None,
        target_username: str | None = None,
        dc_system: "System | None" = None,
        exclusive_end: datetime | None = None,
    ) -> None:
        """Generate a failed logon event.

        Does NOT create a session in StateManager. Builds a OccurrenceBuilder with
        result="failure" and dispatches to matching emitters (Windows 4625,
        syslog "Failed password", eCAR LOGIN with failure_reason).

        When dc_system is provided, also emits DC-side credential validation evidence
        such as 4776 and 4771. The target host owns 4625; cloning it onto the DC would
        make two machines claim the same local failed logon.

        Args:
            user: User attempting to log on (or performing the test)
            system: Target system
            time: Attempt timestamp
            logon_type: Logon type attempted
            source_ip: Source IP for remote attempts. Local failed logons render with no
                source address in Windows Security.
            target_username: If set, the logon targets this user instead of the actor
            dc_system: Domain controller to also emit 4625/4776 on (optional)
        """
        request = FailedLogonRequest(
            user=user,
            system=system,
            time=time,
            logon_type=logon_type,
            source_ip=source_ip,
            target_username=target_username,
            dc_system=dc_system,
            exclusive_end=exclusive_end,
        )
        FailedLogonActionBundle(self, request).execute()

    def _execute_failed_logon_bundle(self, request: FailedLogonRequest) -> None:
        """Expand a failed-logon bundle through the compatibility adapter."""
        user = request.user
        system = request.system
        time = request.time
        logon_type = request.logon_type
        source_ip = request.source_ip
        target_username = request.target_username

        local_logon = logon_type in (2, 5, 7, 11)
        if source_ip == system.ip:
            source_ip = None
            local_logon = True
        if source_ip is None:
            source_ip = "-" if local_logon else system.ip
        auth_source_ip = "-" if local_logon else source_ip

        # Use target_username if provided, otherwise use the actor's username
        effective_username = target_username or user.username
        prepared_attempt = self._prepare_failed_logon_attempt_time(
            hostname=system.hostname,
            username=effective_username,
            logon_type=logon_type,
            source_ip=auth_source_ip,
            requested_time=time,
            exclusive_end=request.exclusive_end,
        )
        if prepared_attempt is None:
            logger.debug(
                "Suppressing duplicate failed logon attempt: user=%s host=%s type=%s time=%s",
                effective_username,
                system.hostname,
                logon_type,
                time,
            )
            return
        time, reservation = prepared_attempt
        if request.exclusive_end is not None:
            try:
                completion_headroom = self._failed_logon_completion_headroom(
                    request=request,
                    source_ip=source_ip,
                    auth_source_ip=auth_source_ip,
                    attempt_time=time,
                )
                if time + completion_headroom >= ensure_utc(request.exclusive_end):
                    self._cancel_failed_logon_attempt(reservation)
                    return
            except BaseException:
                self._cancel_failed_logon_attempt(reservation)
                raise
        with self._claimed_failed_logon_attempt(reservation) as prepared:
            self._execute_prepared_failed_logon_occurrence(
                request=request,
                time=time,
                source_ip=source_ip,
                auth_source_ip=auth_source_ip,
                effective_username=effective_username,
                prepared_attempt=prepared,
            )

    def _failed_logon_completion_headroom(
        self,
        *,
        request: FailedLogonRequest,
        source_ip: str,
        auth_source_ip: str,
        attempt_time: datetime | None = None,
    ) -> timedelta:
        """Return the full rendered child-lifecycle tail for failed-auth admission."""

        time = ensure_utc(attempt_time or request.time)
        os_category = _get_os_category(request.system.os)
        headroom = self._failed_logon_endpoint_projection_headroom(
            canonical_time=time,
            os_category=os_category,
        )
        if os_category == "linux":
            headroom = max(
                headroom,
                self.dispatcher.observation_policy.delay_bounds("syslog")[1],
            )
        if (
            os_category == "windows"
            and request.logon_type == 3
            and auth_source_ip not in {"", "-", request.system.ip}
        ):
            transport_headroom = timedelta(
                seconds=remote_auth_transport_max_duration_seconds(
                    source="activity_generator",
                    outcome="failure",
                )
            )
            headroom = max(
                headroom,
                transport_headroom
                + self._source_timing_planner.endpoint_clock_positive_headroom(
                    time + transport_headroom,
                    "windows",
                ),
                transport_headroom
                + self._network_sensor_close_positive_headroom(
                    canonical_time=time + transport_headroom,
                    src_ip=auth_source_ip,
                    dst_ip=request.system.ip,
                    protocol="tcp",
                    conn_states=("SF", "RSTR"),
                    payload_bytes=1,
                ),
            )
        if os_category == "linux" and source_ip not in {"", "-", request.system.ip}:
            canonical_transport_close = time + _FAILED_LINUX_SSH_CLOSE_HEADROOM
            headroom = max(
                headroom,
                _FAILED_LINUX_SSH_CLOSE_HEADROOM
                + self._network_sensor_close_positive_headroom(
                    canonical_time=canonical_transport_close,
                    src_ip=source_ip,
                    dst_ip=request.system.ip,
                    protocol="tcp",
                    conn_states=("SF", "RSTR"),
                    payload_bytes=1,
                ),
                self._failed_linux_ssh_rendered_close_headroom(time),
            )
        if request.dc_system is not None and request.dc_system.hostname != request.system.hostname:
            ntlm_canonical_tail = timedelta(milliseconds=_FAILED_LOGON_NTLM_VALIDATION_DELAY_MAX_MS)
            ntlm_rendered_tail = (
                ntlm_canonical_tail
                + self._failed_logon_endpoint_projection_headroom(
                    canonical_time=time + ntlm_canonical_tail,
                    os_category="windows",
                )
            )
            kerberos_canonical_time = time - timedelta(
                milliseconds=_FAILED_LOGON_KERBEROS_PREAUTH_LATEST_LEAD_MS,
            )
            kerberos_rendered_tail = max(
                timedelta(0),
                kerberos_canonical_time
                - time
                + self._failed_logon_endpoint_projection_headroom(
                    canonical_time=kerberos_canonical_time,
                    os_category="windows",
                ),
            )
            kerberos_network_tail = self._network_sensor_close_positive_headroom(
                canonical_time=time,
                src_ip=(source_ip if source_ip not in {"", "-"} else ""),
                dst_ip=request.dc_system.ip,
            )
            headroom = max(
                headroom,
                ntlm_rendered_tail,
                kerberos_rendered_tail,
                kerberos_network_tail,
            )
        return headroom

    def _network_sensor_close_positive_headroom(
        self,
        *,
        canonical_time: datetime,
        src_ip: str,
        dst_ip: str,
        protocol: str = "",
        conn_states: tuple[str, ...] = ("",),
        payload_bytes: int | None = None,
    ) -> timedelta:
        """Return the shared planner's allocation-free rendered sensor close tail."""

        if not conn_states:
            raise StateError("Network sensor close headroom requires at least one state")
        headrooms = tuple(
            self.dispatcher.network_observation_planner.network_sensor_close_positive_headroom(
                canonical_time,
                src_ip=src_ip,
                dst_ip=dst_ip,
                protocol=protocol,
                conn_state=conn_state,
                payload_bytes=payload_bytes,
            )
            for conn_state in conn_states
        )
        if any(
            type(headroom) is not timedelta or headroom < timedelta(0) for headroom in headrooms
        ):
            raise StateError("Network sensor close headroom returned an invalid bound")
        return max(headrooms)

    def _failed_logon_endpoint_projection_headroom(
        self,
        *,
        canonical_time: datetime,
        os_category: str,
    ) -> timedelta:
        """Return the maximum endpoint-clock and auth-provider latency tail."""

        source_keys = ["source.ecar_session"]
        if os_category == "windows":
            source_keys.append("source.windows_security_failed_logon_base")
        latency = max(
            (
                timedelta(
                    milliseconds=_activity_get_timing_window(
                        source_key,
                        default_min_ms=1,
                        default_max_ms=_FAILED_LOGON_ENDPOINT_LATENCY_DEFAULT_MAX_MS,
                        default_position="after",
                    ).max_ms,
                )
                for source_key in source_keys
            ),
            default=timedelta(0),
        )
        return (
            self._source_timing_planner.endpoint_clock_positive_headroom(
                canonical_time,
                os_category,
            )
            + latency
        )

    def _failed_linux_ssh_rendered_close_headroom(
        self,
        failure_time: datetime,
    ) -> timedelta:
        """Return the complete responder-visible and delayed syslog close tail."""

        responder_canonical_time = ensure_utc(failure_time) - timedelta(
            milliseconds=(
                _FAILED_LINUX_SSH_RESPONDER_REQUEST_LEAD_MS
                - _FAILED_LINUX_SSH_RESPONDER_CREATE_DELAY_MAX_MS
            ),
        )
        process_create_window = _activity_get_timing_window(
            "source.ecar_process_create",
            default_min_ms=0,
            default_max_ms=950,
            default_position="after",
        )
        dependent_window = _activity_get_timing_window(
            "source.ecar_dependent_after_process_create",
            default_min_ms=0,
            default_max_ms=35,
            default_position="after",
        )
        responder_visible_time = (
            responder_canonical_time
            + self._source_timing_planner.endpoint_clock_positive_headroom(
                responder_canonical_time,
                "linux",
            )
            + timedelta(milliseconds=process_create_window.max_ms)
        )
        shifted_connection_message = (
            responder_visible_time
            + self.dispatcher.observation_policy.maximum_delay_difference(
                "ecar",
                "syslog",
            )
            + timedelta(
                milliseconds=(_FAILED_LINUX_SSH_PROCESS_CAUSAL_FLOOR_MS + dependent_window.max_ms),
            )
        )
        close_after_connection_message = timedelta(
            seconds=_FAILED_LINUX_SSH_CONNECTION_DURATION_MAX_SECONDS,
            milliseconds=-_FAILED_LINUX_SSH_CONNECTION_MESSAGE_DELAY_MIN_MS,
        )
        latest_rendered_close = (
            shifted_connection_message
            + close_after_connection_message
            + self.dispatcher.observation_policy.delay_bounds("syslog")[1]
        )
        return max(timedelta(0), latest_rendered_close - ensure_utc(failure_time))

    def _execute_prepared_failed_logon_occurrence(
        self,
        *,
        request: FailedLogonRequest,
        time: datetime,
        source_ip: str,
        auth_source_ip: str,
        effective_username: str,
        prepared_attempt: _FailedLogonAttemptPreparedCommit,
    ) -> None:
        """Publish one target failed logon before its committed cadence marker."""

        user = request.user
        system = request.system
        logon_type = request.logon_type
        dc_system = request.dc_system

        # Determine failure substatus with source-native account-state semantics.
        # Ordinary known/enabled accounts should fail as bad passwords; locked
        # or disabled states require an explicit account-state model so they do
        # not contradict later successful logons.
        rng = _get_rng()
        known_account = self._is_known_failed_logon_account(effective_username, user)
        failed_profile = self._failed_logon_profile(logon_type, system, source_ip, rng)
        validation_path = self._failed_logon_validation_path(logon_type, failed_profile, rng)
        if self._is_disabled_failed_logon_account(effective_username, user):
            substatus = "0xc0000072"  # Account disabled
            user_sid = self._get_sid(effective_username)
            failure_reason = "%%2307"
        elif not known_account:
            substatus = "0xc0000064"  # User not found: NULL SID
            user_sid = "S-1-0-0"
            failure_reason = "%%2313"
        else:
            substatus = "0xc000006a"  # Wrong password
            user_sid = self._get_sid(effective_username)
            failure_reason = "%%2313"

        remote_linux_source = (
            _get_os_category(system.os) == "linux"
            and source_ip not in (None, "-")
            and source_ip != system.ip
        )
        is_windows_remote_auth = (
            _get_os_category(system.os) == "windows"
            and logon_type == 3
            and auth_source_ip not in {"", "-", system.ip}
        )
        emit_transport = False
        remote_request: WindowsRemoteAuthenticationRequest | None = None
        if is_windows_remote_auth:
            emit_probability = float(failed_profile.get("emit_network_probability", 0.0))
            emit_transport = emit_probability > 0 and rng.random() <= emit_probability
            remote_request = WindowsRemoteAuthenticationRequest(
                target_system=system,
                time=time,
                source_ip=auth_source_ip,
                source_port=int(failed_profile["source_port"]),
                logon_type=logon_type,
                auth_protocol=str(failed_profile["auth_package"]),
                outcome="failure",
                destination_port=int(failed_profile.get("network_port", 445)),
                source_system=self._ip_to_system.get(auth_source_ip),
                emit_transport=emit_transport,
            )

        self.state_manager.set_current_time(time)
        linux_ssh_source_port = None
        linux_ssh_responder_pid: int | None = None
        if remote_linux_source and source_ip is not None:
            linux_ssh_source_port = self._allocate_ephemeral_port(
                source_ip,
                system.ip,
                22,
                "tcp",
                time,
                self._os_for_ip(source_ip),
            )
            linux_ssh_responder_pid = self.ensure_linux_ssh_responder_process(
                target_system=system,
                time=time - timedelta(milliseconds=250),
                source_ip=source_ip,
                source_port=linux_ssh_source_port,
                target_user=effective_username if known_account else None,
            )

        attempt_ordinal = self.state_manager.next_semantic_peer_ordinal(
            "failed_logon",
            request.stable_id,
        )
        occurrence_key = ActionAnchor(
            family="failed_logon",
            stable_id=request.stable_id,
            source=request.source,
        ).occurrence_key(
            OccurrenceRole.PRIMARY,
            f"attempt:{attempt_ordinal}",
        )

        event = OccurrenceBuilder(
            timestamp=time,
            event_type="failed_logon",
            occurrence_key=occurrence_key,
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=effective_username,
                user_sid=user_sid,
                logon_type=logon_type,
                result="failure",
                failure_reason=failure_reason,
                failure_status="0xc000006d",
                failure_substatus=substatus,
                source_ip=(
                    source_ip if remote_linux_source and source_ip is not None else auth_source_ip
                ),
                source_port=linux_ssh_source_port or failed_profile["source_port"],
                auth_package=failed_profile["auth_package"],
                logon_process=failed_profile["logon_process"],
                lm_package=failed_profile["lm_package"],
                process_pid=failed_profile["process_pid"],
                process_name=failed_profile["process_name"],
                workstation_name=failed_profile["workstation_name"],
                subject_sid="S-1-0-0",
                subject_username="-",
                subject_domain="-",
                subject_logon_id="0x0",
            ),
            lifecycle=ActionLifecycleContext(
                group_id=request.stable_id,
                canonical_start=time,
                phase="dependent",
            ),
        )

        if is_windows_remote_auth:
            if remote_request is None:
                raise StateError("Windows failed-logon transport lost its prepared request")
            remote_planner = WindowsRemoteAuthenticationPlanner(self)
            remote_authentication_plan = (
                WindowsRemoteAuthenticationActionBundle(self, remote_request).execute()
                if emit_transport
                else remote_planner.without_transport(remote_request)
            )
            event.remote_auth = remote_authentication_plan
            primary_transport = remote_authentication_plan.primary_transport
            event.lifecycle = ActionLifecycleContext(
                group_id=remote_authentication_plan.stable_id,
                canonical_start=(
                    primary_transport.started_at if primary_transport is not None else time
                ),
                phase="dependent",
            )

        # Attach SyslogContext for Linux local auth failures. Remote SSH failures
        # emit a tuple-scoped sshd lifecycle below so "Connection from" can
        # precede authentication results and share the transport responder PID.
        if event.dst_host and event.dst_host.os_category == "linux":
            from evidenceforge.events.contexts import SyslogContext

            if remote_linux_source:
                pass
            elif source_ip and source_ip != "-":
                ssh_source_port = linux_ssh_source_port or _ephemeral_port(_get_rng(), "linux")
                event.syslog = SyslogContext(
                    app_name="sshd",
                    pid=linux_ssh_responder_pid
                    or self.state_manager.allocate_transient_linux_pid(
                        system.hostname, time, os_category=_get_os_category(system.os)
                    ),
                    facility=10,
                    severity=4,
                    message=(
                        f"Failed password for {effective_username} from {source_ip} "
                        f"port {ssh_source_port} ssh2"
                    ),
                )
            else:
                event.syslog = SyslogContext(
                    app_name="login",
                    pid=self.state_manager.allocate_transient_linux_pid(
                        system.hostname, time, os_category=_get_os_category(system.os)
                    ),
                    facility=10,
                    severity=4,
                    message=(
                        "pam_unix(login:auth): authentication failure; "
                        f"logname=LOGIN uid=0 euid=0 tty=/dev/tty1 ruser= rhost=  "
                        f"user={effective_username}"
                    ),
                )

        if remote_linux_source and source_ip is not None and linux_ssh_source_port is not None:
            connection_time, connection_duration = self._emit_failed_linux_ssh_network_connection(
                system=system,
                time=time,
                source_ip=source_ip,
                source_port=linux_ssh_source_port,
                responding_pid=linux_ssh_responder_pid,
                rng=rng,
            )
            self._emit_failed_linux_ssh_auth_syslog(
                system=system,
                connection_time=connection_time,
                failure_time=time,
                source_ip=source_ip,
                source_port=linux_ssh_source_port,
                responder_pid=linux_ssh_responder_pid,
                attempted_username=effective_username,
                known_account=known_account,
                duration=connection_duration,
            )

        self.dispatcher.dispatch_builder(event)
        prepared_attempt.commit_no_fail()

        # Domain controller side: validation evidence only. The failed local logon
        # (4625) belongs to the target workstation/server, not the DC.
        if dc_system and dc_system.hostname != system.hostname:
            # 4776 NTLM credential validation on DC
            if validation_path.get("emit_4776", True):
                ntlm_delay_ms = rng.randint(3, _FAILED_LOGON_NTLM_VALIDATION_DELAY_MAX_MS)
                self.generate_ntlm_validation(
                    username=effective_username,
                    workstation=system.hostname,
                    dc_hostname=dc_system.hostname,
                    time=time + timedelta(milliseconds=ntlm_delay_ms),
                    status=substatus,
                )

            # 4771 Kerberos pre-authentication failure on DC
            # In real AD, Kerberos is tried first; 4771 fires before 4625/4776
            # for wrong-password failures.
            if validation_path.get("emit_4771", False) and substatus == "0xc000006a":
                krb_time = time - timedelta(milliseconds=rng.randint(40, 350))
                self.generate_kerberos_preauth_failed(
                    username=effective_username,
                    source_ip=source_ip,
                    dc_hostname=dc_system.hostname,
                    time=krb_time,
                    status="0x18",  # KDC_ERR_PREAUTH_FAILED
                    emit_connection=True,
                )

        logger.debug(f"Generated failed logon: {user.username} on {system.hostname}")

    def _account_subject_fields(
        self,
        username: str,
        system: System,
        logon_id: str | None = None,
    ) -> dict[str, str]:
        """Return coherent Windows subject identity fields for an account."""
        if username in _SYSTEM_ACCOUNT_SIDS:
            return {
                "sid": _SYSTEM_ACCOUNT_SIDS[username],
                "username": username,
                "domain": "NT AUTHORITY",
                "logon_id": logon_id or _SYSTEM_ACCOUNT_LOGON_IDS[username],
            }
        return {
            "sid": self._get_sid(username),
            "username": username,
            "domain": self._build_host_context(system).netbios_domain,
            "logon_id": logon_id or self._get_user_logon_id(username, system.hostname),
        }

    def _successful_logon_subject_fields(
        self,
        *,
        user: User,
        system: System,
        logon_type: int,
        time: datetime,
        source_ip: str,
        logon_id: str,
        source_system: System | None = None,
    ) -> dict[str, str]:
        """Return source-native Windows 4624 subject fields for successful logons."""
        system_subject = self._account_subject_fields("SYSTEM", system, logon_id="0x3e7")
        if _get_os_category(system.os) != "windows":
            return system_subject

        username = user.username
        if username in _SYSTEM_ACCOUNT_LOGON_IDS or username.endswith("$") or logon_type == 5:
            return system_subject

        if logon_type == 7:
            session = self.state_manager.get_session(logon_id)
            if (
                session is not None
                and session.system == system.hostname
                and session.username == username
            ):
                return self._account_subject_fields(username, system, logon_id=session.logon_id)
            active = self._active_user_interactive_windows_session(user, system, time)
            if active is not None:
                return self._account_subject_fields(username, system, logon_id=active.logon_id)
            return system_subject

        if logon_type in {3, 10}:
            return system_subject
        return system_subject

    @staticmethod
    def _failed_logon_attempt_runtime_times(value: object) -> tuple[datetime, ...]:
        """Return one exact auth-owned failed-logon cadence window."""

        if (
            type(value) is not tuple
            or len(value) > 32
            or any(type(seen) is not datetime or seen.tzinfo is not UTC for seen in value)
            or tuple(sorted(value)) != value
        ):
            raise StateError("Failed-logon cadence cache contains malformed timestamps")
        return value

    def _prepare_failed_logon_attempt_time(
        self,
        *,
        hostname: str,
        username: str,
        logon_type: int,
        source_ip: str,
        requested_time: datetime,
        exclusive_end: datetime | None = None,
    ) -> tuple[datetime, _FailedLogonAttemptReservation] | None:
        """Prepare one bounded cadence marker for a target failed-logon occurrence."""

        current = ensure_utc(requested_time)
        key: _FailedLogonAttemptKey = (
            hostname.lower().rstrip("."),
            username.lower(),
            logon_type,
            source_ip.lower().removeprefix("::ffff:"),
        )
        duplicate_window = timedelta(milliseconds=500)
        interactive_gap = timedelta(seconds=2)
        with self._failed_logon_attempt_lock:
            watermark = self._failed_logon_attempt_times.watermark_seconds
            if watermark is not None and deadline_seconds(current) < watermark:
                raise StateError("Failed-logon cadence preparation starts behind the watermark")
            if key in self._failed_logon_attempt_pending:
                raise StateError(
                    "Failed-logon cadence key already has an active primary publication"
                )
            prior_times = self._failed_logon_attempt_runtime_times(
                self._failed_logon_attempt_times.get(key, ())
            )
            if any(
                timedelta(0) < abs(current - prior) <= duplicate_window for prior in prior_times
            ):
                return None
            normalized_time = current
            if logon_type in (2, 7, 11):
                while conflicts := [
                    prior for prior in prior_times if abs(normalized_time - prior) < interactive_gap
                ]:
                    normalized_time = max(conflicts) + interactive_gap
            if exclusive_end is not None:
                deadline = ensure_utc(exclusive_end)
                if normalized_time >= deadline:
                    return None
            retained_times = tuple(sorted((*prior_times, normalized_time))[-32:])
            reservation = _FailedLogonAttemptReservation(
                key=key,
                normalized_time=normalized_time,
                retained_times=retained_times,
                expires_at=_failed_logon_attempt_deadline(
                    retained_times,
                    self._scenario_end_time,
                ),
            )
            self._failed_logon_attempt_pending[key] = _FailedLogonAttemptPending(reservation)
            return normalized_time, reservation

    @contextmanager
    def _claimed_failed_logon_attempt(
        self,
        reservation: _FailedLogonAttemptReservation,
    ) -> Iterator[_FailedLogonAttemptPreparedCommit]:
        """Claim one exact pending cadence update and cancel it unless committed."""

        with self._failed_logon_attempt_lock:
            pending = self._failed_logon_attempt_pending.get(reservation.key)
            if pending is None or pending.reservation is not reservation:
                raise StateError("Failed-logon cadence reservation is stale or foreign")
            if pending.claimed:
                raise StateError("Failed-logon cadence reservation is already claimed")
            pending.claimed = True
        prepared = _FailedLogonAttemptPreparedCommit(self, reservation)
        try:
            yield prepared
        finally:
            if not prepared.committed:
                self._cancel_failed_logon_attempt(reservation)
            prepared._close()

    def _commit_failed_logon_attempt_no_fail(
        self,
        reservation: _FailedLogonAttemptReservation,
    ) -> None:
        """Commit one already-claimed cadence value without revisiting caller data."""

        with self._failed_logon_attempt_lock:
            pending = self._failed_logon_attempt_pending.get(reservation.key)
            if pending is None or pending.reservation is not reservation or not pending.claimed:
                raise StateError("Failed-logon cadence claim lost its exact reservation")
            self._failed_logon_attempt_times.set(
                reservation.key,
                reservation.retained_times,
                deadline=reservation.expires_at,
            )
            del self._failed_logon_attempt_pending[reservation.key]

    def _cancel_failed_logon_attempt(
        self,
        reservation: _FailedLogonAttemptReservation,
    ) -> None:
        """Release one exact uncommitted cadence reservation idempotently."""

        with self._failed_logon_attempt_lock:
            pending = self._failed_logon_attempt_pending.get(reservation.key)
            if pending is not None and pending.reservation is reservation:
                del self._failed_logon_attempt_pending[reservation.key]

    def _failed_logon_profile(
        self,
        logon_type: int,
        system: System,
        source_ip: str,
        rng: random.Random,
    ) -> dict[str, Any]:
        """Return source-native Windows 4625 field values for a failed logon."""
        config = failed_logon_config()
        if logon_type in (2, 7, 11):
            local = config.get("local_interactive", {})
            process_name = str(local.get("process_name") or r"C:\Windows\System32\winlogon.exe")
            winlogon_pid = self._get_system_pid(system.hostname, "winlogon", 0)
            return {
                "auth_package": str(local.get("authentication_package_name") or "Negotiate"),
                "logon_process": str(local.get("logon_process_name") or "User32"),
                "lm_package": "-",
                "process_pid": winlogon_pid,
                "process_name": process_name,
                "workstation_name": system.hostname,
                "source_port": 0,
                "network_port": 0,
                "emit_network_probability": 0.0,
            }

        if logon_type == 4:
            batch = config.get("batch", {})
            process_name = str(batch.get("process_name") or r"C:\Windows\System32\svchost.exe")
            return {
                "auth_package": str(batch.get("authentication_package_name") or "Negotiate"),
                "logon_process": str(batch.get("logon_process_name") or "Advapi"),
                "lm_package": "-",
                "process_pid": self._get_system_pid(system.hostname, "svchost", 0x4C0),
                "process_name": process_name,
                "workstation_name": "-",
                "source_port": 0,
                "network_port": 0,
                "emit_network_probability": 0.0,
            }

        network = config.get("network", {})
        process_profiles = [
            value
            for value in (network.get("logon_process_weights") or {}).values()
            if isinstance(value, dict) and int(value.get("weight", 0)) > 0
        ]
        if process_profiles:
            weights = [int(profile.get("weight", 1)) for profile in process_profiles]
            selected = rng.choices(process_profiles, weights=weights, k=1)[0]
        else:
            selected = {
                "authentication_package_name": "NTLM",
                "logon_process_name": "NtLmSsp",
                "lm_package_name": "NTLM V2",
            }
        ports = [
            value
            for value in (network.get("network_ports") or {}).values()
            if isinstance(value, dict) and int(value.get("weight", 0)) > 0
        ]
        if ports:
            port_weights = [int(port.get("weight", 1)) for port in ports]
            network_port = int(rng.choices(ports, weights=port_weights, k=1)[0].get("port", 445))
        else:
            network_port = 445
        return {
            "auth_package": str(selected.get("authentication_package_name") or "NTLM"),
            "logon_process": str(selected.get("logon_process_name") or "NtLmSsp"),
            "lm_package": str(selected.get("lm_package_name") or "-"),
            "process_pid": self._get_system_pid(system.hostname, "lsass", 0x2E0),
            "process_name": r"C:\Windows\System32\lsass.exe",
            "workstation_name": self._workstation_name_for_source(source_ip),
            "source_port": _ephemeral_port(rng, self._os_for_ip(source_ip)),
            "network_port": network_port,
            "emit_network_probability": float(
                network.get("emit_network_connection_probability", 1.0)
            ),
        }

    @staticmethod
    def _failed_logon_validation_path(
        logon_type: int,
        profile: dict[str, Any],
        rng: random.Random,
    ) -> dict[str, bool]:
        """Choose which DC-side failed-auth validation evidence to emit."""
        if logon_type in (2, 4, 5, 7, 11):
            return {"emit_4776": False, "emit_4771": False}
        config = failed_logon_config().get("network", {})
        paths = [
            value
            for value in (config.get("validation_path_weights") or {}).values()
            if isinstance(value, dict) and int(value.get("weight", 0)) > 0
        ]
        if paths:
            weights = [int(path.get("weight", 1)) for path in paths]
            selected = rng.choices(paths, weights=weights, k=1)[0]
            return {
                "emit_4776": bool(selected.get("emit_4776", False)),
                "emit_4771": bool(selected.get("emit_4771", False)),
            }
        auth_package = str(profile.get("auth_package") or "NTLM")
        return {
            "emit_4776": auth_package in ("NTLM", "Negotiate"),
            "emit_4771": auth_package in ("Kerberos", "Negotiate"),
        }

    def _workstation_name_for_source(self, source_ip: str) -> str:
        """Return a plausible WorkstationName for a failed network logon source."""
        if not source_ip or source_ip == "-":
            return "-"
        rdns = self._scenario_fqdn_for_ip(source_ip) or REVERSE_DNS.get(source_ip, "")
        if rdns:
            return rdns.split(".", 1)[0].upper()
        return source_ip

    def _emit_failed_linux_ssh_network_connection(
        self,
        system: System,
        time: datetime,
        source_ip: str,
        source_port: int,
        responding_pid: int | None,
        rng: random.Random,
    ) -> tuple[datetime, float]:
        """Emit source-matched Zeek SSH evidence for a failed Linux sshd logon."""
        conn_time = time - timedelta(
            milliseconds=rng.randint(
                _FAILED_LINUX_SSH_CONNECTION_LEAD_MIN_MS,
                _FAILED_LINUX_SSH_CONNECTION_LEAD_MAX_MS,
            )
        )
        duration = max(
            rng.uniform(0.9, _FAILED_LINUX_SSH_CONNECTION_DURATION_MAX_SECONDS),
            (time - conn_time).total_seconds() + rng.uniform(0.2, 0.85),
        )
        self.generate_connection(
            src_ip=source_ip,
            dst_ip=system.ip,
            time=conn_time,
            dst_port=22,
            proto="tcp",
            service="ssh",
            duration=duration,
            orig_bytes=rng.randint(260, 1800),
            resp_bytes=rng.randint(240, 2600),
            src_port=source_port,
            conn_state=rng.choices(["SF", "RSTR"], weights=[78, 22], k=1)[0],
            responding_pid=responding_pid or -1,
        )
        return conn_time, duration

    def _emit_failed_linux_ssh_auth_syslog(
        self,
        *,
        system: System,
        connection_time: datetime,
        failure_time: datetime,
        source_ip: str,
        source_port: int,
        responder_pid: int | None,
        attempted_username: str,
        known_account: bool,
        duration: float,
    ) -> None:
        """Emit source-native sshd failure rows for one remote auth tuple."""
        if not source_ip or source_ip == "-" or source_port <= 0 or responder_pid is None:
            return

        seed = _stable_seed(
            "failed_linux_ssh_auth_syslog:"
            f"{system.hostname}:{source_ip}:{source_port}:{system.ip}:"
            f"{attempted_username}:{failure_time.isoformat()}"
        )
        latest_connection_time = failure_time - timedelta(milliseconds=120 + (seed % 180))
        connection_message_time = min(
            connection_time + timedelta(milliseconds=45 + ((seed >> 8) % 120)),
            latest_connection_time,
        )
        invalid_user_time = failure_time - timedelta(milliseconds=45 + ((seed >> 16) % 110))
        close_time = max(
            failure_time + timedelta(milliseconds=70 + ((seed >> 24) % 240)),
            connection_time + timedelta(seconds=duration),
        )
        visible_connection_time = self._clamp_after_visible_linux_process_create(
            system,
            responder_pid,
            connection_message_time,
            later_source="syslog",
        )
        if visible_connection_time > connection_message_time:
            source_shift = visible_connection_time - connection_message_time
            connection_message_time += source_shift
            invalid_user_time += source_shift
            failure_time += source_shift
            close_time += source_shift

        rows: list[tuple[datetime, int, str]] = [
            (
                connection_message_time,
                6,
                f"Connection from {source_ip} port {source_port} on {system.ip} port 22",
            )
        ]
        if known_account:
            rows.append(
                (
                    failure_time,
                    4,
                    f"Failed password for {attempted_username} "
                    f"from {source_ip} port {source_port} ssh2",
                )
            )
            close_subject = f"authenticating user {attempted_username}"
        else:
            rows.extend(
                [
                    (
                        invalid_user_time,
                        5,
                        f"Invalid user {attempted_username} from {source_ip} port {source_port}",
                    ),
                    (
                        failure_time,
                        4,
                        f"Failed password for invalid user {attempted_username} "
                        f"from {source_ip} port {source_port} ssh2",
                    ),
                ]
            )
            close_subject = f"invalid user {attempted_username}"

        rows.append(
            (
                close_time,
                6,
                f"Connection closed by {close_subject} {source_ip} port {source_port} [preauth]",
            )
        )
        for row_time, severity, message in sorted(rows, key=lambda row: row[0]):
            self.generate_syslog_event(
                system,
                row_time,
                "sshd",
                message,
                pid=responder_pid,
                facility=10,
                severity=severity,
            )

    def _is_known_failed_logon_account(self, username: str, actor: User) -> bool:
        """Return whether a failed-logon target is a known account in this scenario."""
        normalized = username.split("@", 1)[0].lower()
        if normalized == actor.username.lower():
            return True
        if actor.email and username.lower() == actor.email.lower():
            return True
        if username in {"SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE"} or username.endswith("$"):
            return True
        if username in getattr(self, "sid_registry", {}):
            return True
        return False

    @staticmethod
    def _is_disabled_failed_logon_account(username: str, actor: User) -> bool:
        """Return whether this failed-logon target is explicitly disabled."""
        if actor.enabled:
            return False
        normalized = username.split("@", 1)[0].lower()
        if normalized == actor.username.lower():
            return True
        return bool(actor.email and username.lower() == actor.email.lower())

    @staticmethod
    def _validated_linux_sudo_route_owner(
        continuation: _LinuxSudoLogoffContinuation,
    ) -> _LinuxSudoValidatedRouteOwner:
        """Copy exact callback-free route leaves before using one retained owner."""

        if type(continuation) is not _LinuxSudoLogoffContinuation:
            raise StateError("Linux sudo logoff journal contains a malformed route owner")
        stable_id = continuation.stable_id
        session_identity = continuation.session_identity
        route_keys = continuation.route_keys
        reverse_bucket_present = continuation.reverse_bucket_present
        reverse_bucket = continuation.reverse_bucket
        route_preimage = continuation.route_preimage
        cleanup_ack = continuation.cleanup_ack
        active = continuation.active

        def exact_tty_key(candidate: object) -> bool:
            return bool(
                type(candidate) is tuple
                and len(candidate) == 3
                and all(type(component) is str and component for component in candidate)
            )

        if (
            type(stable_id) is not str
            or not stable_id
            or type(session_identity) is not SessionIdentity
            or type(session_identity.logon_id) is not str
            or not session_identity.logon_id
            or type(route_keys) is not tuple
            or not route_keys
            or any(not exact_tty_key(key) for key in route_keys)
            or type(reverse_bucket_present) is not bool
            or not reverse_bucket_present
            or type(reverse_bucket) is not frozenset
            or not reverse_bucket
            or any(not exact_tty_key(key) for key in reverse_bucket)
            or type(route_preimage) is not tuple
            or len(route_preimage) != len(route_keys)
            or type(active) is not bool
        ):
            raise StateError("Linux sudo logoff journal contains a malformed route owner")
        if len(frozenset(route_keys)) != len(route_keys) or not frozenset(route_keys).issubset(
            reverse_bucket
        ):
            raise StateError("Linux sudo logoff journal contains a malformed route footprint")

        for route_key, route in zip(route_keys, route_preimage, strict=True):
            if type(route) is not _LinuxSudoRouteClosePreimage:
                raise StateError("Linux sudo logoff journal contains a malformed route preimage")
            tty_key = route.tty_key
            session_logon_id = route.session_logon_id
            available_until = route.available_until
            inverse_key = route.inverse_key
            requested_tty_key = route.requested_tty_key
            assigned_tty = route.assigned_tty
            capacity_claim = route.capacity_claim
            if (
                not exact_tty_key(tty_key)
                or type(route.session_present) is not bool
                or (session_logon_id is not None and type(session_logon_id) is not str)
                or type(route.available_present) is not bool
                or (available_until is not None and type(available_until) is not datetime)
                or type(inverse_key) is not tuple
                or len(inverse_key) != 2
                or any(type(component) is not str or not component for component in inverse_key)
                or type(route.owner_present) is not bool
                or (requested_tty_key is not None and not exact_tty_key(requested_tty_key))
                or type(route.assignment_present) is not bool
                or (assigned_tty is not None and type(assigned_tty) is not str)
                or type(route.capacity_claim_present) is not bool
                or (
                    capacity_claim is not None
                    and (
                        type(capacity_claim) is not tuple
                        or len(capacity_claim) != 5
                        or type(capacity_claim[0]) is not object
                        or type(capacity_claim[1]) is not str
                        or any(type(flag) is not bool for flag in capacity_claim[2:])
                    )
                )
            ):
                raise StateError("Linux sudo logoff journal contains a malformed route preimage")
            if (
                tty_key != route_key
                or inverse_key != (tty_key[0], tty_key[2])
                or (requested_tty_key is not None and requested_tty_key[:2] != tty_key[:2])
            ):
                raise StateError("Linux sudo logoff journal contains a crossed route preimage")

        if cleanup_ack is not None:
            if type(cleanup_ack) is not _LinuxSudoRouteCleanupAck:
                raise StateError("Linux sudo logoff journal has a malformed cleanup receipt")
            ack_stable_id = cleanup_ack.continuation_stable_id
            ack_logon_id = cleanup_ack.logon_id
            ack_route_keys = cleanup_ack.route_keys
            ack_reverse_bucket = cleanup_ack.reverse_bucket
            if (
                type(ack_stable_id) is not str
                or type(ack_logon_id) is not str
                or type(ack_route_keys) is not tuple
                or any(not exact_tty_key(key) for key in ack_route_keys)
                or type(cleanup_ack.reverse_bucket_present) is not bool
                or type(ack_reverse_bucket) is not frozenset
                or any(not exact_tty_key(key) for key in ack_reverse_bucket)
                or type(cleanup_ack.sudo_tty_rows) is not int
                or cleanup_ack.sudo_tty_rows < 1
            ):
                raise StateError("Linux sudo logoff journal has a malformed cleanup receipt")
            if (
                ack_stable_id != stable_id
                or ack_logon_id != session_identity.logon_id
                or ack_route_keys != route_keys
            ):
                raise StateError("Linux sudo logoff journal has a crossed cleanup receipt")

        return _LinuxSudoValidatedRouteOwner(
            stable_id=stable_id,
            logon_id=session_identity.logon_id,
            route_keys=route_keys,
            reverse_bucket_present=reverse_bucket_present,
            reverse_bucket=reverse_bucket,
            route_preimage=route_preimage,
            cleanup_ack=cleanup_ack,
            active=active,
        )

    def _require_linux_sudo_logoff_projection_owner(
        self,
        continuation: _LinuxSudoLogoffContinuation,
    ) -> _LinuxSudoLogoffProjectionOwner:
        """Reauthenticate one retained local actor/session/host projection."""

        if type(continuation) is not _LinuxSudoLogoffContinuation:
            raise StateError("Linux sudo logoff continuation lost its projection owner")
        owner = continuation.projection_owner
        request = continuation.request
        user = continuation.user
        system = continuation.system
        session = continuation.session
        session_identity = continuation.session_identity
        if (
            type(owner) is not _LinuxSudoLogoffProjectionOwner
            or type(request) is not LogoffRequest
            or type(user) is not User
            or type(system) is not System
            or type(session) is not ActiveSession
            or type(session_identity) is not SessionIdentity
            or request.user is not user
            or request.system is not system
        ):
            raise StateError("Linux sudo logoff continuation lost its projection owner")
        if (
            any(
                type(value) is not str
                for value in (
                    owner.username,
                    owner.hostname,
                    owner.host_ip,
                    owner.host_os,
                    owner.host_os_category,
                    owner.host_system_type,
                    owner.host_domain,
                    owner.host_fqdn,
                    owner.host_netbios_domain,
                    owner.logon_id,
                    owner.source_ip,
                    owner.session_kind,
                    owner.auth_protocol,
                    owner.smb_principal,
                    owner.account_scope,
                    owner.auth_session_ref,
                    owner.session_object_id,
                    owner.lifecycle_group_id,
                    owner.parent_lifecycle_group_id,
                )
            )
            or type(owner.host_roles) is not tuple
            or any(type(role) is not str for role in owner.host_roles)
            or type(owner.session_id) is not int
            or type(owner.logon_type) is not int
            or type(owner.source_port) is not int
            or (owner.effective_uid is not None and type(owner.effective_uid) is not int)
            or (owner.effective_gid is not None and type(owner.effective_gid) is not int)
            or type(owner.session_started_at) is not datetime
        ):
            raise StateError("Linux sudo logoff continuation has a malformed projection owner")
        if (
            type(user.username) is not str
            or type(system.hostname) is not str
            or type(system.ip) is not str
            or type(system.os) is not str
            or type(system.type) is not str
            or type(system.roles) is not list
            or any(type(role) is not str for role in system.roles)
            or type(session.logon_id) is not str
            or type(session.username) is not str
            or type(session.system) is not str
            or type(session.logon_type) is not int
            or type(session.start_time) is not datetime
            or type(session.source_ip) is not str
            or type(session.source_port) is not int
            or type(session.session_id) is not int
            or type(session.session_kind) is not str
            or type(session.auth_protocol) is not str
            or type(session.smb_principal) is not str
            or type(session.account_scope) is not str
            or type(session.auth_session_ref) is not str
            or (session.effective_uid is not None and type(session.effective_uid) is not int)
            or (session.effective_gid is not None and type(session.effective_gid) is not int)
            or type(session.ecar_object_id) is not str
            or type(session.lifecycle_group_id) is not str
            or type(session.parent_lifecycle_group_id) is not str
        ):
            raise StateError("Linux sudo logoff continuation has a malformed live projection")
        if (
            user.username != owner.username
            or system.hostname != owner.hostname
            or system.ip != owner.host_ip
            or system.os != owner.host_os
            or _get_os_category(system.os) != owner.host_os_category
            or system.type != owner.host_system_type
            or tuple(system.roles) != owner.host_roles
            or session.logon_id != owner.logon_id
            or session.username != owner.username
            or session.system != owner.hostname
            or session.logon_type != owner.logon_type
            or ensure_utc(session.start_time) != owner.session_started_at
            or session.source_ip != owner.source_ip
            or session.source_port != owner.source_port
            or session.session_id != owner.session_id
            or session.session_kind != owner.session_kind
            or session.auth_protocol != owner.auth_protocol
            or session.smb_principal != owner.smb_principal
            or session.account_scope != owner.account_scope
            or session.auth_session_ref != owner.auth_session_ref
            or session.effective_uid != owner.effective_uid
            or session.effective_gid != owner.effective_gid
            or session.ecar_object_id != owner.session_object_id
            or session.lifecycle_group_id != owner.lifecycle_group_id
            or session.parent_lifecycle_group_id != owner.parent_lifecycle_group_id
            or session_identity.object_id != owner.session_object_id
            or session_identity.logon_id != owner.logon_id
            or session_identity.hostname != owner.hostname
            or session_identity.principal != owner.username
            or session_identity.session_id != owner.session_id
            or session_identity.started_at != owner.session_started_at
            or session_identity.lifecycle_group_id != owner.lifecycle_group_id
            or session_identity.parent_lifecycle_group_id != owner.parent_lifecycle_group_id
        ):
            raise StateError("Linux sudo logoff continuation projection owner drifted")
        return owner

    @staticmethod
    def _linux_sudo_logoff_host_context(
        owner: _LinuxSudoLogoffProjectionOwner,
    ) -> HostContext:
        """Materialize one event-local host context from an authenticated snapshot."""

        return HostContext(
            hostname=owner.hostname,
            ip=owner.host_ip,
            os=owner.host_os,
            os_category=owner.host_os_category,
            system_type=owner.host_system_type,
            domain=owner.host_domain,
            fqdn=owner.host_fqdn,
            netbios_domain=owner.host_netbios_domain,
            roles=list(owner.host_roles),
        )

    def _claim_pending_linux_sudo_logoff(
        self,
        request: LogoffRequest,
    ) -> _LinuxSudoLogoffContinuation | None:
        """Claim a retained exact close before consulting already-consumed State."""

        if (
            type(request) is not LogoffRequest
            or type(request.user) is not User
            or type(request.system) is not System
            or type(request.time) is not datetime
            or type(request.logon_id) is not str
            or not request.logon_id
            or type(request.logon_type) is not int
            or type(request.from_storyline) is not bool
            or (
                request.session_end_plan is not None
                and type(request.session_end_plan) is not SessionEndPlan
            )
            or type(request.source) is not str
        ):
            raise StateError("Linux sudo logoff retry request has a malformed exact shape")
        stable_id = request.stable_id
        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            if type(journals) is not dict:
                raise StateError("Linux sudo logoff journals must be an exact dictionary")
            continuation = dict.get(journals, stable_id)
            if continuation is None:
                for retained in dict.values(journals):
                    if (
                        type(retained) is not _LinuxSudoLogoffContinuation
                        or type(retained.session_identity) is not SessionIdentity
                        or type(retained.session_identity.logon_id) is not str
                    ):
                        raise StateError("Linux sudo logoff journal contains a malformed owner")
                    if retained.session_identity.logon_id == request.logon_id:
                        raise StateError(
                            "Linux sudo logoff retry changed its retained request owner"
                        )
                return None
            retained_request = continuation.request
            if (
                type(continuation) is not _LinuxSudoLogoffContinuation
                or type(continuation.stable_id) is not str
                or type(retained_request) is not LogoffRequest
                or type(retained_request.time) is not datetime
                or type(retained_request.logon_id) is not str
                or type(retained_request.logon_type) is not int
                or type(retained_request.from_storyline) is not bool
                or (
                    retained_request.session_end_plan is not None
                    and type(retained_request.session_end_plan) is not SessionEndPlan
                )
                or type(retained_request.source) is not str
                or type(continuation.session_identity) is not SessionIdentity
                or type(continuation.session_identity.logon_id) is not str
                or continuation.stable_id != stable_id
                or type(continuation.active) is not bool
                or retained_request.user is not request.user
                or retained_request.system is not request.system
                or retained_request.time != request.time
                or retained_request.logon_type != request.logon_type
                or retained_request.from_storyline is not request.from_storyline
                or retained_request.session_end_plan is not request.session_end_plan
                or retained_request.source != request.source
                or continuation.session_identity.logon_id != request.logon_id
                or continuation.dispatcher_owner is not self.dispatcher
                or continuation.state_owner is not self.state_manager
                or continuation.lifecycle_owner is not self._lifecycle_authority
            ):
                raise StateError("Linux sudo logoff retry crossed its exact retained owner")
            if continuation.active is True:
                raise StateError("Linux sudo logoff continuation is already active")
            continuation.active = True
            return continuation

    def _release_linux_sudo_logoff_claim(
        self,
        continuation: _LinuxSudoLogoffContinuation,
    ) -> None:
        """Release a journal execution claim without invoking callbacks under its mutex."""

        if (
            type(continuation) is not _LinuxSudoLogoffContinuation
            or type(continuation.stable_id) is not str
        ):
            raise StateError("Linux sudo logoff claim release has a malformed owner")
        stable_id = continuation.stable_id
        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            if type(journals) is not dict or type(continuation.active) is not bool:
                raise StateError("Linux sudo logoff claim release lost its exact journal")
            retained = dict.get(journals, stable_id)
            if retained is continuation:
                continuation.active = False

    def _install_linux_sudo_logoff_continuation(
        self,
        *,
        request: LogoffRequest,
        session: ActiveSession,
        session_identity: SessionIdentity,
        base_logoff_time: datetime,
        effective_end_plan: SessionEndPlan | None,
        process_closes: tuple[_LinuxSudoProcessClosePlan, ...],
        timing_deltas: tuple[_FrozenActivityTimingDelta, ...],
        rendered_dependents_delta: _FrozenActivityTimingDelta | None,
        ecar_logout_delta: _FrozenActivityTimingDelta | None,
        windows_logout_delta: _FrozenActivityTimingDelta | None,
    ) -> _LinuxSudoLogoffContinuation:
        """Install the exact route/session continuation before its first mutation."""

        if (
            type(request) is not LogoffRequest
            or type(request.user) is not User
            or type(request.system) is not System
            or type(request.user.username) is not str
            or type(request.system.hostname) is not str
            or type(request.system.ip) is not str
            or type(request.system.os) is not str
            or type(request.system.type) is not str
            or type(request.system.roles) is not list
            or any(type(role) is not str for role in request.system.roles)
            or type(session) is not ActiveSession
            or type(session_identity) is not SessionIdentity
            or type(session_identity.object_id) is not str
            or type(session_identity.logon_id) is not str
            or type(session_identity.hostname) is not str
            or type(session_identity.principal) is not str
            or type(session_identity.session_id) is not int
            or type(session_identity.started_at) is not datetime
            or type(session.logon_id) is not str
            or type(session.username) is not str
            or type(session.system) is not str
            or type(session.logon_type) is not int
            or type(session.start_time) is not datetime
            or type(session.source_ip) is not str
            or type(session.source_port) is not int
            or type(session.session_id) is not int
            or type(session.session_kind) is not str
            or type(session.ecar_object_id) is not str
            or type(session.auth_protocol) is not str
            or type(session.smb_principal) is not str
            or type(session.account_scope) is not str
            or type(session.auth_session_ref) is not str
            or (session.effective_uid is not None and type(session.effective_uid) is not int)
            or (session.effective_gid is not None and type(session.effective_gid) is not int)
            or (session.end_plan is not None and type(session.end_plan) is not SessionEndPlan)
            or (
                request.session_end_plan is not None
                and type(request.session_end_plan) is not SessionEndPlan
            )
            or (effective_end_plan is not None and type(effective_end_plan) is not SessionEndPlan)
            or session_identity.object_id != session.ecar_object_id
            or session_identity.logon_id != session.logon_id
            or session_identity.hostname != session.system
            or session_identity.principal != session.username
            or session_identity.session_id != session.session_id
            or session_identity.session_kind != "interactive"
            or session_identity.started_at != ensure_utc(session.start_time)
            or session_identity.lifecycle_group_id != session.lifecycle_group_id
            or session_identity.parent_lifecycle_group_id != session.parent_lifecycle_group_id
            or session.logon_type != 2
            or session.session_kind != "interactive"
            or session.source_ip not in {"", "-"}
            or session.source_port != 0
            or request.user.username != session.username
            or request.system.hostname != session.system
            or request.logon_id != session.logon_id
            or request.logon_type != 2
            or not self._lifecycle_authority.is_strict(
                LifecycleEntityRef("session", session_identity.object_id),
                session_identity.hostname,
            )
        ):
            raise StateError("Linux sudo logoff requires one exact strict local session owner")
        if request.session_end_plan is not None and (
            session.end_plan is not None
            and session.end_plan.is_hard_deadline
            and session.end_plan != request.session_end_plan
        ):
            raise StateError("Linux sudo logoff conflicts with its retained hard end plan")
        if (
            request.session_end_plan is not None
            and not request.session_end_plan.is_authoritative
            and session.end_plan != request.session_end_plan
        ):
            raise StateError("Linux sudo logoff lacks its requested retained end-plan owner")
        retained_effective_end_plan = request.session_end_plan
        if (
            retained_effective_end_plan is None
            and session.end_plan is not None
            and session.end_plan.is_hard_deadline
        ):
            retained_effective_end_plan = session.end_plan
        if effective_end_plan != retained_effective_end_plan:
            raise StateError("Linux sudo logoff changed its effective retained end plan")
        if (
            effective_end_plan is not None
            and effective_end_plan.is_authoritative
            and ensure_utc(base_logoff_time) != ensure_utc(effective_end_plan.canonical_end)
        ):
            raise StateError("Linux sudo logoff drifted from its authoritative exact end")
        if (
            effective_end_plan is not None
            and effective_end_plan.is_hard_deadline
            and ensure_utc(base_logoff_time) > ensure_utc(effective_end_plan.canonical_end)
        ):
            raise StateError("Linux sudo logoff exceeds its retained hard end plan")
        if ensure_utc(base_logoff_time) <= session_identity.started_at or (
            session.last_activity_time is not None
            and ensure_utc(base_logoff_time) < ensure_utc(session.last_activity_time)
        ):
            raise StateError("Linux sudo logoff cannot fit its exact session terminalization")
        lifecycle_session = self._lifecycle_authority.registry.get_session(
            session_identity.object_id
        )
        if (
            lifecycle_session is None
            or lifecycle_session.closed_at is not None
            or lifecycle_session.identity != LifecycleShadow.project_session_start(session_identity)
        ):
            raise StateError("Linux sudo logoff session lifecycle prestate drifted")
        for process_close in process_closes:
            if (
                type(process_close) is not _LinuxSudoProcessClosePlan
                or type(process_close.identity) is not ProcessIdentity
                or self.state_manager.get_process_identity(
                    process_close.identity.hostname,
                    process_close.identity.pid,
                )
                != process_close.identity
            ):
                raise StateError("Linux sudo logoff process State prestate drifted")
            lifecycle_process = self._lifecycle_authority.registry.get_process(
                process_close.identity.object_id
            )
            if lifecycle_process is None or lifecycle_process.closed_at is not None:
                raise StateError("Linux sudo logoff process lifecycle prestate drifted")
            self._lifecycle_authority._action_cohort_registered_process(process_close.identity)
        latest_member_close = self._lifecycle_authority.session_latest_closed_member_at_for_object(
            session_identity.object_id
        )
        if (
            effective_end_plan is not None
            and effective_end_plan.is_hard_deadline
            and latest_member_close is not None
            and ensure_utc(latest_member_close) >= ensure_utc(effective_end_plan.canonical_end)
        ):
            raise StateError(
                "Authoritative Linux sudo close cannot follow its retained session-member graph"
            )
        host_context = self._build_host_context(request.system)
        if (
            type(host_context) is not HostContext
            or type(host_context.hostname) is not str
            or type(host_context.ip) is not str
            or type(host_context.os) is not str
            or type(host_context.os_category) is not str
            or type(host_context.system_type) is not str
            or type(host_context.domain) is not str
            or type(host_context.fqdn) is not str
            or type(host_context.netbios_domain) is not str
            or type(host_context.roles) is not list
            or any(type(role) is not str for role in host_context.roles)
        ):
            raise StateError("Linux sudo logoff host projection is malformed")
        projection_owner = _LinuxSudoLogoffProjectionOwner(
            username=request.user.username,
            hostname=request.system.hostname,
            host_ip=host_context.ip,
            host_os=host_context.os,
            host_os_category=host_context.os_category,
            host_system_type=host_context.system_type,
            host_domain=host_context.domain,
            host_fqdn=host_context.fqdn,
            host_netbios_domain=host_context.netbios_domain,
            host_roles=tuple(host_context.roles),
            logon_id=session.logon_id,
            session_id=session.session_id,
            logon_type=session.logon_type,
            source_ip=session.source_ip,
            source_port=session.source_port,
            session_kind=session.session_kind,
            auth_protocol=session.auth_protocol,
            smb_principal=session.smb_principal,
            account_scope=session.account_scope,
            auth_session_ref=session.auth_session_ref,
            effective_uid=session.effective_uid,
            effective_gid=session.effective_gid,
            session_object_id=session.ecar_object_id,
            session_started_at=ensure_utc(session.start_time),
            lifecycle_group_id=session.lifecycle_group_id,
            parent_lifecycle_group_id=session.parent_lifecycle_group_id,
        )
        stable_id = request.stable_id
        missing = object()
        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            reverse = self._linux_sudo_tty_keys_by_logon_id
            sessions = self._linux_sudo_tty_sessions
            available = self._linux_sudo_tty_available
            owners = self._linux_sudo_tty_owners
            assignments = self._linux_sudo_tty_assignments
            claims = self._linux_sudo_tty_capacity_claims
            if any(
                type(mapping) is not dict
                for mapping in (
                    journals,
                    reverse,
                    sessions,
                    available,
                    owners,
                    assignments,
                    claims,
                )
            ):
                raise StateError("Linux sudo logoff owner maps must be exact dictionaries")
            if any(
                dict.__len__(mapping) > _LINUX_SUDO_TTY_MAP_CENSUS_LIMIT
                for mapping in (
                    journals,
                    reverse,
                    sessions,
                    available,
                    owners,
                    assignments,
                    claims,
                )
            ):
                raise StateError("Linux sudo logoff owner maps exceed their bounded census")
            for key, value in dict.items(assignments):
                if (
                    type(key) is not tuple
                    or len(key) != 3
                    or any(type(component) is not str for component in key)
                    or type(value) is not str
                ):
                    raise StateError("Linux sudo logoff assignment map is malformed")
            for key, value in dict.items(owners):
                if (
                    type(key) is not tuple
                    or len(key) != 2
                    or any(type(component) is not str for component in key)
                    or type(value) is not tuple
                    or len(value) != 3
                    or any(type(component) is not str for component in value)
                ):
                    raise StateError("Linux sudo logoff inverse map is malformed")
            for key, value in dict.items(claims):
                if (
                    type(key) is not tuple
                    or len(key) != 3
                    or any(type(component) is not str for component in key)
                    or type(value) is not tuple
                    or len(value) != 5
                    or type(value[0]) is not object
                    or type(value[1]) is not str
                    or any(type(flag) is not bool for flag in value[2:])
                ):
                    raise StateError("Linux sudo logoff capacity map is malformed")
            for key, value in dict.items(sessions):
                if (
                    type(key) is not tuple
                    or len(key) != 3
                    or any(type(component) is not str for component in key)
                    or type(value) is not str
                ):
                    raise StateError("Linux sudo logoff session map is malformed")
            for key, value in dict.items(available):
                if (
                    type(key) is not tuple
                    or len(key) != 3
                    or any(type(component) is not str for component in key)
                    or type(value) is not datetime
                ):
                    raise StateError("Linux sudo logoff availability map is malformed")
            for key, value in dict.items(reverse):
                if (
                    type(key) is not str
                    or type(value) is not set
                    or not value
                    or any(
                        type(route_key) is not tuple
                        or len(route_key) != 3
                        or any(type(component) is not str for component in route_key)
                        for route_key in value
                    )
                ):
                    raise StateError("Linux sudo logoff reverse map is malformed")
            if dict.get(journals, stable_id) is not None:
                raise StateError("Linux sudo logoff stable owner is already retained")
            if dict.__len__(journals) >= _LINUX_SUDO_TTY_MAP_CENSUS_LIMIT:
                raise StateError("Linux sudo logoff journal exhausted its bounded census")
            raw_reverse_bucket = dict.get(reverse, session_identity.logon_id, missing)
            if raw_reverse_bucket is missing:
                raise StateError("Linux sudo logoff lost its selected exact reverse route")
            if type(raw_reverse_bucket) is not set or not raw_reverse_bucket:
                raise StateError("Linux sudo logoff lost its exact reverse-route bucket")
            reverse_bucket = frozenset(
                self._validate_linux_sudo_tty_key(key) for key in raw_reverse_bucket
            )
            if len(reverse_bucket) != set.__len__(raw_reverse_bucket):
                raise StateError("Linux sudo logoff reverse route changed during validation")
            for reverse_key in reverse_bucket:
                routed_logon_id = dict.get(sessions, reverse_key, missing)
                if type(routed_logon_id) is not str or routed_logon_id != session_identity.logon_id:
                    raise StateError("Linux sudo logoff reverse routes crossed their forward owner")
            route_keys = tuple(
                sorted(
                    key
                    for key in reverse_bucket
                    if key[:2] == (session_identity.hostname, session_identity.principal)
                )
            )
            if not route_keys:
                raise StateError("Linux sudo logoff reverse route has no exact session key")
            retained_route_owners = tuple(
                self._validated_linux_sudo_route_owner(retained)
                for retained in dict.values(journals)
            )
            for retained_owner in retained_route_owners:
                if retained_owner.logon_id == session_identity.logon_id:
                    raise StateError("Linux sudo logoff reverse route is already retained")
            route_preimage: list[_LinuxSudoRouteClosePreimage] = []
            for tty_key in route_keys:
                routed_logon_id = dict.get(sessions, tty_key, missing)
                deadline = dict.get(available, tty_key, missing)
                if deadline is not missing and type(deadline) is not datetime:
                    raise StateError("Linux sudo logoff availability preimage is malformed")
                inverse_key = (tty_key[0], tty_key[2])
                requested_tty_key = dict.get(owners, inverse_key, missing)
                if requested_tty_key is missing:
                    raise StateError("Linux sudo logoff inverse preimage is incomplete")
                requested_tty_key = self._validate_linux_sudo_tty_key(requested_tty_key)
                assigned_tty = dict.get(assignments, requested_tty_key, missing)
                if type(assigned_tty) is not str or assigned_tty != tty_key[2]:
                    raise StateError("Linux sudo logoff assignment preimage is incomplete")
                capacity_claim = dict.get(claims, requested_tty_key, missing)
                if capacity_claim is not missing:
                    raise StateError("Linux sudo logoff route has an active capacity claim")
                if (
                    sum(
                        int(
                            type(candidate_key) is tuple
                            and len(candidate_key) == 3
                            and candidate_key[0] == tty_key[0]
                            and type(candidate_tty) is str
                            and candidate_tty == tty_key[2]
                        )
                        for candidate_key, candidate_tty in dict.items(assignments)
                    )
                    != 1
                ):
                    raise StateError("Linux sudo logoff assignment preimage is not one-to-one")
                if (
                    sum(
                        int(
                            type(candidate_key) is tuple
                            and len(candidate_key) == 2
                            and type(candidate_owner) is tuple
                            and len(candidate_owner) == 3
                            and all(type(component) is str for component in candidate_owner)
                            and candidate_owner[0] == requested_tty_key[0]
                            and candidate_owner[1] == requested_tty_key[1]
                            and candidate_owner[2] == requested_tty_key[2]
                        )
                        for candidate_key, candidate_owner in dict.items(owners)
                    )
                    != 1
                ):
                    raise StateError("Linux sudo logoff inverse preimage is not one-to-one")
                route_preimage.append(
                    _LinuxSudoRouteClosePreimage(
                        tty_key=tty_key,
                        session_present=True,
                        session_logon_id=routed_logon_id,
                        available_present=deadline is not missing,
                        available_until=None if deadline is missing else deadline,
                        inverse_key=inverse_key,
                        owner_present=True,
                        requested_tty_key=requested_tty_key,
                        assignment_present=True,
                        assigned_tty=assigned_tty,
                        capacity_claim_present=False,
                        capacity_claim=None,
                    )
                )
            protected_route_keys = set(route_keys)
            protected_inverse_keys = {route.inverse_key for route in route_preimage}
            protected_requested_keys = {
                route.requested_tty_key
                for route in route_preimage
                if route.requested_tty_key is not None
            }
            for retained_owner in retained_route_owners:
                retained_route_keys = set(retained_owner.route_keys)
                retained_inverse_keys = {
                    route.inverse_key for route in retained_owner.route_preimage
                }
                retained_requested_keys = {
                    route.requested_tty_key
                    for route in retained_owner.route_preimage
                    if route.requested_tty_key is not None
                }
                if (
                    protected_route_keys & retained_route_keys
                    or protected_inverse_keys & retained_inverse_keys
                    or protected_requested_keys & retained_requested_keys
                ):
                    raise StateError("Linux sudo logoff route overlaps a retained close")
            continuation = _LinuxSudoLogoffContinuation(
                stable_id=stable_id,
                request=request,
                user=request.user,
                system=request.system,
                session=session,
                session_identity=session_identity,
                projection_owner=projection_owner,
                base_logoff_time=ensure_utc(base_logoff_time),
                effective_end_plan=effective_end_plan,
                process_closes=process_closes,
                route_keys=route_keys,
                reverse_bucket_present=True,
                reverse_bucket=reverse_bucket,
                route_preimage=tuple(route_preimage),
                timing_deltas=timing_deltas,
                rendered_dependents_delta=rendered_dependents_delta,
                ecar_logout_delta=ecar_logout_delta,
                windows_logout_delta=windows_logout_delta,
                dispatcher_owner=self.dispatcher,
                state_owner=self.state_manager,
                lifecycle_owner=self._lifecycle_authority,
                active=True,
            )
            high_water = self._linux_sudo_logoff_high_water_pending
            if type(high_water) is not int or high_water < 0:
                raise StateError("Linux sudo logoff high-water census is malformed")
            next_high_water = max(
                high_water,
                dict.__len__(journals) + 1,
            )
            if next_high_water > _LINUX_SUDO_TTY_MAP_CENSUS_LIMIT:
                raise StateError("Linux sudo logoff high-water census exceeded capacity")
            dict.__setitem__(journals, stable_id, continuation)
            self._linux_sudo_logoff_high_water_pending = next_high_water
            return continuation

    def _plan_linux_sudo_logoff_process_closes(
        self,
        *,
        system: System,
        session: ActiveSession,
        processes: list[RunningProcess],
        base_logoff_time: datetime,
        authoritative_end_plan: SessionEndPlan | None,
    ) -> tuple[_LinuxSudoProcessClosePlan, ...]:
        """Freeze one children-first local process schedule without mutating State."""

        termination_span = (
            timedelta(milliseconds=min(3000, max(250, 100 * (len(processes) + 1))))
            if authoritative_end_plan is not None
            else timedelta(
                milliseconds=max(
                    500,
                    sum(
                        40
                        + (
                            _stable_seed(
                                "windows_session_process_termination_gap:"
                                f"{session.system}:{session.logon_id}:{process.pid}:"
                                f"{base_logoff_time.isoformat()}"
                            )
                            % 361
                        )
                        for process in processes
                    )
                    + 150,
                )
            )
        )
        termination_start = ensure_utc(base_logoff_time) - termination_span
        cumulative_gap_ms = 0
        plans: list[_LinuxSudoProcessClosePlan] = []
        for ordinal, process in enumerate(processes):
            if authoritative_end_plan is not None:
                slot_ms = termination_span.total_seconds() * 1000 / max(1, len(processes) + 1)
                terminate_at = termination_start + timedelta(milliseconds=slot_ms * ordinal)
            else:
                terminate_at = termination_start + timedelta(milliseconds=cumulative_gap_ms)
                cumulative_gap_ms += 40 + (
                    _stable_seed(
                        "windows_session_process_termination_gap:"
                        f"{session.system}:{session.logon_id}:{process.pid}:"
                        f"{base_logoff_time.isoformat()}"
                    )
                    % 361
                )
            if (
                process.last_activity_time is not None
                and terminate_at <= process.last_activity_time
            ):
                if authoritative_end_plan is not None:
                    terminate_at = ensure_utc(process.last_activity_time) + timedelta(
                        milliseconds=25
                    )
                else:
                    delay_rng = random.Random(
                        _stable_seed(
                            "process_terminate_after_activity:"
                            f"{session.system}:{process.pid}:"
                            f"{process.last_activity_time.isoformat()}"
                        )
                    )
                    terminate_at = ensure_utc(process.last_activity_time) + timedelta(
                        seconds=delay_rng.uniform(2.0, 30.0)
                    )
            terminate_at = self._held_process_termination_time(
                system=system,
                pid=process.pid,
                requested_time=terminate_at,
            )
            retained_child_close = (
                self._lifecycle_authority.process_latest_closed_child_at_for_object(
                    process.ecar_object_id
                )
            )
            if retained_child_close is not None:
                terminate_at = max(
                    terminate_at,
                    ensure_utc(retained_child_close) + timedelta(microseconds=1),
                )
            terminate_at = self._clamp_after_visible_process_create(
                system,
                process.pid,
                terminate_at,
                "windows.process_exit_after_visible_create",
            )
            if plans:
                terminate_at = max(
                    ensure_utc(terminate_at),
                    plans[-1].end_time + timedelta(microseconds=1),
                )
            identity = self.state_manager.get_process_identity(session.system, process.pid)
            if identity is None or identity.object_id != process.ecar_object_id:
                raise StateError("Linux sudo logoff process identity drifted before preparation")
            if identity.logon_id != session.logon_id:
                raise StateError("Linux sudo logoff process crossed its exact session owner")
            terminate_at = max(
                ensure_utc(terminate_at),
                identity.started_at + timedelta(microseconds=1),
            )
            if authoritative_end_plan is not None and ensure_utc(terminate_at) >= ensure_utc(
                authoritative_end_plan.canonical_end
            ):
                raise StateError(
                    "Authoritative Linux sudo close cannot fit its process graph before "
                    "the exact session end"
                )
            plans.append(
                _LinuxSudoProcessClosePlan(
                    identity=identity,
                    end_time=ensure_utc(terminate_at),
                    auth_session_id=(
                        process.auth_session_id
                        if process.auth_session_id is not None
                        else session.session_id
                    ),
                    auth_logon_type=(
                        process.auth_logon_type
                        if process.auth_logon_type is not None
                        else session.logon_type
                    ),
                    concurrency_group_id=process.concurrency_group_id,
                )
            )
        return tuple(plans)

    def _linux_sudo_terminal_result_authenticates(
        self,
        result: object,
        *,
        root_action_id: str,
        state_semantic_id: str,
        occurrence_id: str,
        expected_identity: ProcessIdentity | SessionIdentity,
        require_succeeded: bool,
    ) -> bool:
        """Totally validate one retained sudo-close action-cohort result."""

        try:
            if type(result) is not ActionCohortPublicationResult:
                return False
            receipt = result.receipt
            if (
                type(receipt) is not ActionCohortPublicationReceipt
                or not self.dispatcher.authenticates_action_cohort_publication_receipt(receipt)
                or receipt.root_action_id != root_action_id
                or receipt.state_semantic_id != state_semantic_id
                or receipt.occurrence_ids != (occurrence_id,)
                or result.state.semantic_id != state_semantic_id
                or result.state.started_sessions
                or result.state.started_processes
                or len(result.projections) != 1
                or result.projections[0].occurrence_id != occurrence_id
            ):
                return False
            if require_succeeded and (
                result.projections[0].status != "succeeded"
                or result.projections[0].error is not None
            ):
                return False
            if type(expected_identity) is ProcessIdentity:
                return bool(
                    result.state.terminated_processes == (expected_identity,)
                    and not result.state.terminalized_sessions
                )
            return bool(
                type(expected_identity) is SessionIdentity
                and not result.state.terminated_processes
                and result.state.terminalized_sessions == (expected_identity,)
            )
        except BaseException:
            return False

    def _publish_linux_sudo_terminal_phase(
        self,
        *,
        continuation: _LinuxSudoLogoffContinuation,
        phase: str,
        state_plan: object,
        event: OccurrenceBuilder,
        expected_identity: ProcessIdentity | SessionIdentity,
        stage_terminal_timing: bool = False,
    ) -> _LinuxSudoClosePhaseProgress:
        """Publish or resume one exact singleton close through its retained receipt."""

        from evidenceforge.generation.actions.command_effects import (
            ExecutionEffectAuditCohortEntry,
        )
        from evidenceforge.generation.state_manager import ActionCohortMaterializationPlan

        retained = continuation.phases.get(phase)
        if retained is not None:
            if (
                type(retained) is not _LinuxSudoClosePhaseProgress
                or retained.expected_identity != expected_identity
                or retained.receipt is None
                or retained.result is None
                or not self._linux_sudo_terminal_result_authenticates(
                    retained.result,
                    root_action_id=retained.root_action_id,
                    state_semantic_id=retained.state_semantic_id,
                    occurrence_id=retained.occurrence_id,
                    expected_identity=expected_identity,
                    require_succeeded=False,
                )
            ):
                raise StateError("Linux sudo close recovery crossed its exact phase binding")
            if not retained.projection_complete:
                outcome = retained.result.projections[0]
                result = (
                    retained.result
                    if outcome.status == "succeeded" and outcome.error is None
                    else self.dispatcher.resume_action_cohort_projection(retained.receipt)
                )
                if (
                    result is not retained.result
                    or not self._linux_sudo_terminal_result_authenticates(
                        result,
                        root_action_id=retained.root_action_id,
                        state_semantic_id=retained.state_semantic_id,
                        occurrence_id=retained.occurrence_id,
                        expected_identity=expected_identity,
                        require_succeeded=True,
                    )
                ):
                    raise StateError("Linux sudo close recovery returned a forged result")
                retained.projection_complete = True
            return retained

        if type(state_plan) is not ActionCohortMaterializationPlan:
            raise TypeError("Linux sudo close requires one exact State action-cohort plan")
        root_action_id = f"linux-sudo-close:{continuation.stable_id}:{phase}"
        audit_plan = ExecutionEffectPlan(
            ActionAnchor(
                family="linux_sudo_logoff",
                stable_id=root_action_id,
                source="activity_generator",
            ),
            (),
        )
        audit_entry = ExecutionEffectAuditCohortEntry(
            audit_plan,
            audit_plan.reconcile(()),
        )
        carrier: PreparedActionCohortProjection | None = None
        timing_preparation: SourceTimingPreparation | None = None
        try:
            with self.dispatcher.source_timing_planner.prepared_planning() as timing_preparation:
                if type(expected_identity) is ProcessIdentity:
                    self._plan_process_source_terminate_times(event)
                elif stage_terminal_timing:
                    if continuation.ecar_logout_delta is not None:
                        self._source_timing_planner.record_session_closure_source_time(
                            event,
                            "ecar",
                            event.timestamp + continuation.ecar_logout_delta.value,
                        )
                    if continuation.windows_logout_delta is not None:
                        self._source_timing_planner.record_session_closure_source_time(
                            event,
                            "windows_event_security",
                            event.timestamp + continuation.windows_logout_delta.value,
                        )
                    terminal_timing_deltas = tuple(
                        delta
                        for delta in (
                            *continuation.timing_deltas,
                            continuation.ecar_logout_delta,
                            continuation.windows_logout_delta,
                        )
                        if delta is not None
                    )
                    if len({delta.relationship_key for delta in terminal_timing_deltas}) != len(
                        terminal_timing_deltas
                    ):
                        raise StateError("Linux sudo logoff repeated a frozen timing audit key")
                    for timing_delta in terminal_timing_deltas:
                        timing_preparation.planning_runtime.sampler.record_logical_sample(
                            timing_delta.distribution,
                            relationship_key=timing_delta.relationship_key,
                        )
                carrier = self.dispatcher.prepare_action_cohort_projection(
                    event,
                    source_timing_preparation=timing_preparation,
                )
            occurrence_id = self.dispatcher.action_cohort_projection_occurrence(
                carrier
            ).occurrence_id
            prepared = self.dispatcher.bind_action_cohort_projection(
                carrier,
                state_plan=state_plan,
            )
            batch = self.dispatcher.prepare_action_cohort_batch(
                root_action_id,
                state_plan,
                (prepared,),
                (audit_entry,),
                (),
                (),
                exact_projection=True,
            )
        except BaseException as primary:
            if carrier is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    f"Linux sudo {phase} projection",
                    lambda: self.dispatcher.cancel_prepared_action_cohort_projection(carrier),
                )
            self._reconcile_generator_cleanup(
                primary,
                f"Linux sudo {phase} orphan projection",
                self.dispatcher.prune_prepared_action_cohort_projections,
            )
            self._reconcile_generator_cleanup(
                primary,
                f"Linux sudo {phase} orphan batch",
                self.dispatcher.prune_prepared_action_cohort_batches,
            )
            if timing_preparation is not None and not timing_preparation.committed:
                self._reconcile_generator_cleanup(
                    primary,
                    f"Linux sudo {phase} source timing",
                    timing_preparation.cancel,
                )
            raise

        progress = _LinuxSudoClosePhaseProgress(
            root_action_id=root_action_id,
            state_semantic_id=state_plan.semantic_id,
            occurrence_id=occurrence_id,
            expected_identity=expected_identity,
            event=event,
        )
        continuation.phases[phase] = progress
        capability = None
        try:
            with self.dispatcher.claimed_action_cohort(batch) as capability:
                result = capability.commit_no_fail()
                if (
                    result is not capability.result
                    or not self._linux_sudo_terminal_result_authenticates(
                        result,
                        root_action_id=root_action_id,
                        state_semantic_id=state_plan.semantic_id,
                        occurrence_id=occurrence_id,
                        expected_identity=expected_identity,
                        require_succeeded=True,
                    )
                ):
                    raise StateError("Linux sudo close publisher returned a forged result")
        except BaseException:
            committed_result = capability.result if capability is not None else None
            committed_receipt = capability.receipt if capability is not None else None
            if (
                capability is not None
                and capability.committed
                and type(committed_receipt) is ActionCohortPublicationReceipt
                and type(committed_result) is ActionCohortPublicationResult
                and self._linux_sudo_terminal_result_authenticates(
                    committed_result,
                    root_action_id=root_action_id,
                    state_semantic_id=state_plan.semantic_id,
                    occurrence_id=occurrence_id,
                    expected_identity=expected_identity,
                    require_succeeded=False,
                )
            ):
                progress.receipt = committed_receipt
                progress.result = committed_result
            else:
                continuation.phases.pop(phase, None)
            raise
        progress.receipt = result.receipt
        progress.result = result
        progress.projection_complete = True
        return progress

    def _execute_linux_sudo_logoff_continuation(
        self,
        continuation: _LinuxSudoLogoffContinuation,
    ) -> None:
        """Resume one exact route-bearing close through cleanup acknowledgement."""

        if (
            type(continuation) is not _LinuxSudoLogoffContinuation
            or continuation.dispatcher_owner is not self.dispatcher
            or continuation.state_owner is not self.state_manager
            or continuation.lifecycle_owner is not self._lifecycle_authority
        ):
            raise StateError("Linux sudo logoff continuation lost its runtime owner")
        projection_owner = self._require_linux_sudo_logoff_projection_owner(continuation)
        route_owner = self._validated_linux_sudo_route_owner(continuation)
        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            if (
                type(journals) is not dict
                or dict.get(journals, route_owner.stable_id) is not continuation
                or type(continuation.active) is not bool
                or not continuation.active
            ):
                raise StateError("Linux sudo logoff continuation is not its active journal owner")
        session = continuation.session
        session_identity = continuation.session_identity

        for process_close in continuation.process_closes:
            identity = process_close.identity
            phase = f"process-terminate:{identity.object_id}"
            progress = continuation.phases.get(phase)
            if progress is not None and not progress.projection_complete:
                progress = self._publish_linux_sudo_terminal_phase(
                    continuation=continuation,
                    phase=phase,
                    state_plan=None,
                    event=progress.event,
                    expected_identity=identity,
                )
            elif progress is None:
                state_builder = self.state_manager.begin_action_cohort_materialization()
                state_builder.patch_session_activity(session_identity, process_close.end_time)
                state_builder.terminate_process(identity, end_time=process_close.end_time)
                state_plan = state_builder.seal()
                event = OccurrenceBuilder(
                    timestamp=process_close.end_time,
                    event_type="process_terminate",
                    src_host=self._linux_sudo_logoff_host_context(projection_owner),
                    auth=AuthContext(
                        username=identity.principal,
                        user_sid=self._get_sid(identity.principal),
                        logon_id=identity.logon_id,
                        session_id=process_close.auth_session_id,
                        logon_type=process_close.auth_logon_type,
                    ),
                    process=ProcessContext(
                        pid=identity.pid,
                        parent_pid=identity.parent_pid,
                        image=identity.image,
                        command_line="",
                        username=identity.principal,
                        logon_id=identity.logon_id,
                        start_time=identity.started_at,
                        concurrency_group_id=process_close.concurrency_group_id,
                    ),
                    storyline_origin=continuation.request.from_storyline,
                    identity_plan=EventIdentityPlan(
                        subject=identity,
                        session=session_identity,
                    ),
                    lifecycle=ActionLifecycleContext(
                        group_id=identity.lifecycle_group_id,
                        canonical_start=identity.started_at,
                        phase="closure",
                        parent_group_id=identity.parent_lifecycle_group_id or None,
                    ),
                )
                progress = self._publish_linux_sudo_terminal_phase(
                    continuation=continuation,
                    phase=phase,
                    state_plan=state_plan,
                    event=event,
                    expected_identity=identity,
                )
            if not progress.compatibility_adopted:
                self._commit_exact_ssh_source_process_termination(progress.event)
                progress.compatibility_adopted = True

        if continuation.final_logoff_time is None:
            final_time = continuation.base_logoff_time
            visible_terminations = [
                visible
                for process_close in continuation.process_closes
                for visible in (
                    self.process_source_terminate_time(
                        process_close.identity.hostname,
                        process_close.identity.pid,
                    ),
                )
                if visible is not None
            ]
            if visible_terminations and continuation.rendered_dependents_delta is not None:
                observation_gap = self.dispatcher.observation_policy.maximum_delay_difference(
                    "ecar",
                    "ecar",
                )
                final_time = max(
                    final_time,
                    max(visible_terminations)
                    + continuation.rendered_dependents_delta.value
                    + observation_gap,
                )
                if continuation.rendered_dependents_delta not in continuation.timing_deltas:
                    continuation.timing_deltas = (
                        *continuation.timing_deltas,
                        continuation.rendered_dependents_delta,
                    )
            latest_member_close = (
                self._lifecycle_authority.session_latest_closed_member_at_for_object(
                    session_identity.object_id
                )
            )
            if latest_member_close is not None:
                final_time = max(
                    final_time,
                    ensure_utc(latest_member_close) + timedelta(microseconds=1),
                )
            if continuation.process_closes:
                final_time = max(
                    final_time,
                    max(close.end_time for close in continuation.process_closes)
                    + timedelta(microseconds=1),
                )
            continuation.final_logoff_time = ensure_utc(final_time)

            authoritative_end_plan = continuation.effective_end_plan
            if (
                authoritative_end_plan is not None
                and authoritative_end_plan.is_authoritative
                and continuation.final_logoff_time
                != ensure_utc(authoritative_end_plan.canonical_end)
            ):
                raise StateError("Linux sudo logoff drifted past its authoritative exact end")

        final_time = continuation.final_logoff_time
        if final_time is None:  # pragma: no cover - assigned immediately above
            raise StateError("Linux sudo logoff lost its frozen terminal time")
        phase = "logout"
        logout_progress = continuation.phases.get(phase)
        if logout_progress is not None and not logout_progress.projection_complete:
            logout_progress = self._publish_linux_sudo_terminal_phase(
                continuation=continuation,
                phase=phase,
                state_plan=None,
                event=logout_progress.event,
                expected_identity=session_identity,
                stage_terminal_timing=True,
            )
        elif logout_progress is None:
            state_builder = self.state_manager.begin_action_cohort_materialization()
            authoritative_end_plan = continuation.effective_end_plan
            if authoritative_end_plan is not None and authoritative_end_plan.is_authoritative:
                current_metadata = state_builder.session_metadata(session_identity)
                if type(current_metadata) is not ActionCohortSessionMetadataState:
                    raise StateError("Linux sudo logoff lost its exact session metadata")
                if current_metadata.end_plan != authoritative_end_plan:
                    state_builder.transition_session_metadata(
                        session_identity,
                        replace(current_metadata, end_plan=authoritative_end_plan),
                    )
            state_builder.terminalize_session(session_identity, end_time=final_time)
            state_plan = state_builder.seal()
            event = OccurrenceBuilder(
                timestamp=final_time,
                event_type="logoff",
                dst_host=self._linux_sudo_logoff_host_context(projection_owner),
                auth=AuthContext(
                    username=projection_owner.username,
                    user_sid=self._get_sid(projection_owner.username),
                    logon_id=projection_owner.logon_id,
                    session_id=projection_owner.session_id,
                    logon_type=projection_owner.logon_type,
                    source_ip=projection_owner.source_ip,
                    source_port=projection_owner.source_port,
                    session_kind=projection_owner.session_kind,
                    auth_protocol=projection_owner.auth_protocol,
                    smb_principal=projection_owner.smb_principal,
                    account_scope=projection_owner.account_scope,
                    auth_session_ref=projection_owner.auth_session_ref,
                    effective_uid=projection_owner.effective_uid,
                    effective_gid=projection_owner.effective_gid,
                ),
                storyline_origin=continuation.request.from_storyline,
                identity_plan=EventIdentityPlan(
                    subject=session_identity,
                    session=session_identity,
                ),
                lifecycle=ActionLifecycleContext(
                    group_id=session_identity.lifecycle_group_id,
                    canonical_start=session_identity.started_at,
                    phase="closure",
                    parent_group_id=session_identity.parent_lifecycle_group_id or None,
                ),
            )
            logout_progress = self._publish_linux_sudo_terminal_phase(
                continuation=continuation,
                phase=phase,
                state_plan=state_plan,
                event=event,
                expected_identity=session_identity,
                stage_terminal_timing=True,
            )
        if not logout_progress.compatibility_adopted:
            self._linux_shell_last_session_close[
                (projection_owner.hostname, projection_owner.username)
            ] = final_time
            logout_progress.compatibility_adopted = True

        self._require_linux_sudo_logoff_projection_owner(continuation)
        self._require_accepted_linux_sudo_session_close_owner(session)
        self._release_exact_linux_sudo_route(continuation)
        if continuation.cleanup_ack is None:
            raise StateError("Linux sudo logoff cleanup returned without exact acknowledgement")
        logger.debug(
            "Generated exact Linux sudo logoff: %s on %s (LogonID: %s)",
            projection_owner.username,
            projection_owner.hostname,
            projection_owner.logon_id,
        )
        with self._linux_sudo_tty_lock:
            retained = dict.get(self._pending_linux_sudo_logoffs, route_owner.stable_id)
            if retained is not continuation:
                raise StateError("Linux sudo logoff cleanup changed its retained journal owner")
            continuation.active = False
            self._pending_linux_sudo_logoffs.pop(route_owner.stable_id)

    def generate_logoff(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
        logon_type: int = 2,
        from_storyline: bool = False,
        session_end_plan: SessionEndPlan | None = None,
    ) -> None:
        """Generate logoff event across all applicable log formats.

        Ends session in StateManager, builds a OccurrenceBuilder, and dispatches
        to matching emitters (Windows 4634, syslog session closed, eCAR LOGOUT).

        Args:
            user: User logging off
            system: System being logged off from
            time: Logoff timestamp
            logon_id: LogonID from the logon event
            logon_type: Logon type for the session being ended
            from_storyline: When True, skip min_logoff_time clamping so the
                storyline-scheduled time is preserved unless an SSH transport
                close bounds the session lifecycle.
        """
        request = LogoffRequest(
            user=user,
            system=system,
            time=time,
            logon_id=logon_id,
            logon_type=logon_type,
            from_storyline=from_storyline,
            session_end_plan=session_end_plan,
        )
        LogoffActionBundle(self, request).execute()

    def _plan_generic_logoff_process_closes(
        self,
        *,
        system: System,
        session: ActiveSession,
        processes: list[RunningProcess],
        base_logoff_time: datetime,
        authoritative_end_plan: SessionEndPlan | None,
        uses_ssh_transport_close_margin: bool,
        suppresses_linux_foreground_lifetime_clamp: bool,
    ) -> tuple[tuple[_GenericLogoffProcessClosePlan, ...], datetime | None]:
        """Freeze and validate generic session process closes without mutation."""

        authoritative = authoritative_end_plan is not None
        termination_gaps_ms = (
            []
            if authoritative
            else [
                40
                + (
                    _stable_seed(
                        "windows_session_process_termination_gap:"
                        f"{session.system}:{session.logon_id}:{process.pid}:"
                        f"{base_logoff_time.isoformat()}"
                    )
                    % 361
                )
                for process in processes
            ]
        )
        if authoritative:
            termination_span = timedelta(
                milliseconds=min(3000, max(250, 100 * (len(processes) + 1)))
            )
        else:
            final_margin_ms = 1000 if uses_ssh_transport_close_margin else 150
            termination_span = timedelta(
                milliseconds=max(500, sum(termination_gaps_ms) + final_margin_ms)
            )
        termination_start = ensure_utc(base_logoff_time) - termination_span
        direct_session_role_pids = frozenset(
            pid
            for pid in (
                session.process_tree_root,
                session.transport_pid,
                session.session_shell_pid,
                session.session_user_manager_pid,
                session.session_winlogon_pid,
                session.explorer_pid,
                session.initial_explorer_pid,
            )
            if pid is not None
        )
        latest_planned_child_close: dict[str, datetime] = {}
        plans: list[_GenericLogoffProcessClosePlan] = []
        cumulative_gap_ms = 0
        os_category = _get_os_category(system.os)
        deadline = (
            ensure_utc(authoritative_end_plan.canonical_end)
            if authoritative_end_plan is not None
            else None
        )
        for ordinal, process in enumerate(processes):
            authoritative_latest_allowed: datetime | None = None
            ssh_network_close: datetime | None = None
            ssh_clamp_latest_allowed: datetime | None = None
            identity = self.state_manager.get_process_identity(session.system, process.pid)
            if identity is None or identity.object_id != process.ecar_object_id:
                raise StateError("Generic logoff process identity drifted before preparation")
            lifecycle_process = self._lifecycle_authority.registry.get_process(identity.object_id)
            if lifecycle_process is not None and (
                lifecycle_process.closed_at is not None
                or lifecycle_process.identity.object_id != identity.object_id
                or lifecycle_process.identity.hostname != identity.hostname
                or lifecycle_process.identity.pid != identity.pid
                or lifecycle_process.identity.started_at != identity.started_at
                or lifecycle_process.identity.image != identity.image
            ):
                raise StateError("Generic logoff process lifecycle prestate drifted")

            if authoritative:
                slot_ms = termination_span.total_seconds() * 1000 / max(1, len(processes) + 1)
                terminate_at = termination_start + timedelta(milliseconds=slot_ms * ordinal)
            else:
                terminate_at = termination_start + timedelta(milliseconds=cumulative_gap_ms)
                cumulative_gap_ms += termination_gaps_ms[ordinal]

            is_session_bootstrap = bool(
                identity.lifecycle_group_id == session.lifecycle_group_id
                or identity.pid in direct_session_role_pids
            )
            process_lifetime = (
                None
                if (
                    is_session_bootstrap
                    or (os_category == "linux" and suppresses_linux_foreground_lifetime_clamp)
                )
                else _windows_foreground_lifetime(identity.image, identity.command_line)
                if os_category == "windows"
                else _linux_foreground_lifetime(identity.image, identity.command_line)
            )
            if process_lifetime is not None:
                lifetime_rng = random.Random(
                    _stable_seed(
                        "orphan_foreground_process_lifetime:"
                        f"{session.system}:{identity.pid}:{identity.started_at.isoformat()}:"
                        f"{identity.command_line}"
                    )
                )
                bounded_termination_time = identity.started_at + timedelta(
                    seconds=lifetime_rng.uniform(*process_lifetime)
                )
                connection_hold = self._process_connection_hold_until.get(
                    self._process_instance_key(
                        session.system,
                        identity.pid,
                        identity.started_at,
                    )
                )
                if connection_hold is not None:
                    bounded_termination_time = max(
                        bounded_termination_time,
                        ensure_utc(connection_hold) + timedelta(milliseconds=25),
                    )
                terminate_at = min(terminate_at, bounded_termination_time)

            if (
                process.last_activity_time is not None
                and terminate_at <= process.last_activity_time
            ):
                if authoritative:
                    terminate_at = ensure_utc(process.last_activity_time) + timedelta(
                        milliseconds=25
                    )
                else:
                    delay_rng = random.Random(
                        _stable_seed(
                            "process_terminate_after_activity:"
                            f"{session.system}:{identity.pid}:"
                            f"{process.last_activity_time.isoformat()}"
                        )
                    )
                    terminate_at = ensure_utc(process.last_activity_time) + timedelta(
                        seconds=delay_rng.uniform(2.0, 30.0)
                    )

            if (
                session.session_kind == "ssh"
                and session.network_close_time is not None
                and session.transport_pid != identity.pid
            ):
                ssh_network_close = ensure_utc(session.network_close_time)
                process_logon_id = process.token_logon_id or identity.logon_id
                end_margin_ms = 150 + (
                    _stable_seed(
                        "process_terminate_before_logoff:"
                        f"{session.system}:{identity.pid}:{process_logon_id}"
                    )
                    % 850
                )
                latest_allowed = ssh_network_close - timedelta(milliseconds=end_margin_ms)
                if identity.started_at >= latest_allowed:
                    latest_allowed = identity.started_at + timedelta(milliseconds=100)
                if latest_allowed < ssh_network_close:
                    ssh_clamp_latest_allowed = latest_allowed
                if terminate_at >= ssh_network_close and ssh_clamp_latest_allowed is not None:
                    terminate_at = min(ensure_utc(terminate_at), latest_allowed)

            if authoritative:
                if deadline is None:  # pragma: no cover - narrowed by authoritative above
                    raise StateError("Generic authoritative logoff lost its exact deadline")
                hold_until = self._process_connection_hold_until.get(
                    self._process_instance_key(session.system, identity.pid, identity.started_at)
                )
                if hold_until is not None and ensure_utc(hold_until) >= deadline:
                    raise StateError(
                        "Process connection hold extends beyond authoritative session end: "
                        f"{session.system} pid={identity.pid} "
                        f"hold={ensure_utc(hold_until).isoformat()} "
                        f"end={deadline.isoformat()}"
                    )
                end_margin_ms = 25 + (
                    _stable_seed(
                        "process_terminate_before_authoritative_logoff:"
                        f"{session.system}:{identity.pid}:"
                        f"{process.token_logon_id or identity.logon_id}:"
                        f"{deadline.isoformat()}"
                    )
                    % 176
                )
                authoritative_latest_allowed = deadline - timedelta(milliseconds=end_margin_ms)
                terminate_at = min(ensure_utc(terminate_at), authoritative_latest_allowed)
            else:
                terminate_at = self._held_process_termination_time(
                    system=system,
                    pid=identity.pid,
                    requested_time=terminate_at,
                )

            typed_hold_until = (
                lifecycle_process.latest_hold_until if lifecycle_process is not None else None
            )
            resource_lease_deadline = self._lifecycle_authority.process_resource_lease_deadline(
                session.system,
                identity.pid,
            )
            dependency_frontier = max(
                (
                    deadline_at
                    for deadline_at in (
                        typed_hold_until,
                        resource_lease_deadline,
                    )
                    if deadline_at is not None
                ),
                default=None,
            )
            if dependency_frontier is not None:
                terminate_at = max(
                    ensure_utc(terminate_at),
                    ensure_utc(dependency_frontier),
                )

            if lifecycle_process is not None and lifecycle_process.latest_dependent_at is not None:
                terminate_at = max(
                    ensure_utc(terminate_at),
                    ensure_utc(lifecycle_process.latest_dependent_at) + timedelta(microseconds=1),
                )

            retained_child_close = (
                self._lifecycle_authority.process_latest_closed_child_at_for_object(
                    identity.object_id
                )
            )
            child_close_frontier = max(
                (
                    close_at
                    for close_at in (
                        retained_child_close,
                        latest_planned_child_close.get(identity.object_id),
                    )
                    if close_at is not None
                ),
                default=None,
            )
            if child_close_frontier is not None:
                terminate_at = max(
                    ensure_utc(terminate_at),
                    ensure_utc(child_close_frontier) + timedelta(microseconds=1),
                )

            visible_create_delta: _FrozenActivityTimingDelta | None = None
            if os_category == "windows":
                visible_create_time = self.process_source_create_time(session.system, identity.pid)
                if visible_create_time is not None and terminate_at <= visible_create_time:
                    relationship_key = "windows.process_exit_after_visible_create"
                    visible_create_delta = self._freeze_profile_activity_gap(
                        relationship_key,
                        stable_id=_activity_timing_stable_id(
                            "windows-visible-process-dependent",
                            session.system,
                            identity.pid,
                            visible_create_time,
                            terminate_at,
                        ),
                        host=session.system,
                        source="endpoint_process",
                        lifecycle_id=str(identity.pid),
                        sample_key="visible_create_gap",
                    )
                    terminate_at = visible_create_time + visible_create_delta.value

            terminate_at = max(
                ensure_utc(terminate_at),
                identity.started_at + timedelta(microseconds=1),
            )
            if (
                ssh_network_close is not None
                and ssh_clamp_latest_allowed is not None
                and terminate_at >= ssh_network_close
            ):
                raise StateError(
                    "Generic logoff cannot preserve a frozen process close across its "
                    f"SSH transport clamp: process={identity.object_id}"
                )
            if deadline is not None and terminate_at >= deadline:
                raise StateError(
                    "Authoritative generic logoff cannot fit its process graph before "
                    f"the exact session end: process={identity.object_id}"
                )
            if (
                authoritative_latest_allowed is not None
                and terminate_at > authoritative_latest_allowed
            ):
                raise StateError(
                    "Authoritative generic logoff cannot preserve its frozen process "
                    f"close before the exact deadline clamp: process={identity.object_id}"
                )
            plan = _GenericLogoffProcessClosePlan(
                identity=identity,
                end_time=ensure_utc(terminate_at),
                visible_create_delta=visible_create_delta,
            )
            plans.append(plan)
            parent_object_id = (
                lifecycle_process.identity.parent_object_id
                if lifecycle_process is not None
                else (
                    parent_identity.object_id
                    if (
                        parent_identity := self.state_manager.get_process_identity(
                            session.system,
                            identity.parent_pid,
                        )
                    )
                    is not None
                    else None
                )
            )
            if parent_object_id:
                prior_child_close = latest_planned_child_close.get(parent_object_id)
                latest_planned_child_close[parent_object_id] = (
                    plan.end_time
                    if prior_child_close is None
                    else max(prior_child_close, plan.end_time)
                )

        lifecycle_session = self._lifecycle_authority.registry.get_session(session.ecar_object_id)
        if lifecycle_session is not None and lifecycle_session.closed_at is not None:
            raise StateError("Generic logoff session lifecycle prestate drifted")
        latest_session_hold = (
            lifecycle_session.latest_hold_until if lifecycle_session is not None else None
        )
        retained_member_close = (
            self._lifecycle_authority.session_latest_closed_member_at_for_object(
                session.ecar_object_id
            )
        )
        strict_session_frontier = max(
            (
                close_at
                for close_at in (
                    retained_member_close,
                    (
                        lifecycle_session.latest_dependent_at
                        if lifecycle_session is not None
                        else None
                    ),
                    *(plan.end_time for plan in plans),
                )
                if close_at is not None
            ),
            default=None,
        )
        if deadline is not None:
            if (
                strict_session_frontier is not None
                and ensure_utc(strict_session_frontier) >= deadline
            ):
                raise StateError(
                    "Authoritative generic logoff cannot follow its retained session graph"
                )
            if latest_session_hold is not None and ensure_utc(latest_session_hold) > deadline:
                raise StateError(
                    "Authoritative generic logoff cannot follow its retained session hold"
                )
            projected_session_frontier = strict_session_frontier
        else:
            projected_session_frontier = max(
                (
                    close_at
                    for close_at in (
                        strict_session_frontier,
                        latest_session_hold,
                    )
                    if close_at is not None
                ),
                default=None,
            )
        return tuple(plans), projected_session_frontier

    def _execute_logoff_bundle(self, request: LogoffRequest) -> None:
        """Expand a logoff bundle through the compatibility adapter."""
        pending_linux_sudo = self._claim_pending_linux_sudo_logoff(request)
        if pending_linux_sudo is not None:
            try:
                self._execute_linux_sudo_logoff_continuation(pending_linux_sudo)
            finally:
                self._release_linux_sudo_logoff_claim(pending_linux_sudo)
            return
        user = request.user
        system = request.system
        time = request.time
        logon_id = request.logon_id
        logon_type = request.logon_type
        from_storyline = request.from_storyline
        session_end_plan = request.session_end_plan
        authoritative_end_plan = (
            session_end_plan
            if session_end_plan is not None and session_end_plan.is_authoritative
            else None
        )
        session = self.state_manager.get_session(logon_id)
        if session is not None:
            logon_type = session.logon_type
        has_linux_sudo_route = bool(
            session is not None
            and _get_os_category(system.os) == "linux"
            and self._has_linux_sudo_tty_route(logon_id)
        )
        has_strict_linux_sudo_owner = bool(
            has_linux_sudo_route
            and session is not None
            and self._lifecycle_authority.is_strict(
                LifecycleEntityRef("session", session.ecar_object_id),
                session.system,
            )
        )
        if has_linux_sudo_route and not has_strict_linux_sudo_owner:
            raise StateError("Linux sudo logoff lacks its exact strict lifecycle owner")
        closes_linux_sudo_route = has_linux_sudo_route
        session_transport_pid = session.transport_pid if session is not None else None
        is_ssh_session = bool(
            session
            and (
                session.session_kind == "ssh"
                or (_get_os_category(system.os) == "linux" and logon_type == 10)
            )
        )
        if (
            has_linux_sudo_route
            and not is_ssh_session
            and (
                session is None or session.session_kind != "interactive" or session.logon_type != 2
            )
        ):
            raise StateError("Linux sudo logoff has no exact terminal owner for its session kind")
        uses_exact_linux_sudo_close = bool(
            closes_linux_sudo_route
            and not is_ssh_session
            and session is not None
            and session.session_kind == "interactive"
            and session.logon_type == 2
        )
        effective_linux_sudo_end_plan = session_end_plan
        if (
            uses_exact_linux_sudo_close
            and effective_linux_sudo_end_plan is None
            and session is not None
            and session.end_plan is not None
            and session.end_plan.is_hard_deadline
        ):
            effective_linux_sudo_end_plan = session.end_plan
        if (
            uses_exact_linux_sudo_close
            and effective_linux_sudo_end_plan is not None
            and effective_linux_sudo_end_plan.is_authoritative
        ):
            authoritative_end_plan = effective_linux_sudo_end_plan
        ssh_transport_close_time = (
            ensure_utc(session.network_close_time)
            if session is not None and is_ssh_session and session.network_close_time is not None
            else None
        )
        frozen_session_processes = (
            self.state_manager.get_processes_for_session(logon_id, session.system)
            if session is not None
            else []
        )
        raw_session_end_markers = (
            (session.last_activity_time, session.network_close_time) if session is not None else ()
        )
        session_end_markers = [
            marker
            for marker in raw_session_end_markers
            if marker is not None
            and (ssh_transport_close_time is None or ensure_utc(marker) <= ssh_transport_close_time)
        ]
        session_end_markers.extend(
            marker
            for proc in frozen_session_processes
            for marker in (proc.last_activity_time or proc.start_time,)
            if marker is not None
            and (ssh_transport_close_time is None or ensure_utc(marker) <= ssh_transport_close_time)
        )
        latest_session_marker = max(session_end_markers) if session_end_markers else None
        transport_close_delta = (
            self._freeze_profile_activity_gap(
                "windows.logoff_after_last_activity",
                stable_id=_activity_timing_stable_id(
                    "ssh-transport-logoff",
                    request.stable_id,
                    ssh_transport_close_time,
                ),
                host=system.hostname,
                source="session",
                lifecycle_id=logon_id,
                sample_key="ssh_transport_close_gap",
            )
            if ssh_transport_close_time is not None and authoritative_end_plan is None
            else None
        )
        last_activity_delta = (
            self._freeze_profile_activity_gap(
                "windows.logoff_after_last_activity",
                stable_id=_activity_timing_stable_id(
                    "session-last-activity-logoff",
                    request.stable_id,
                    latest_session_marker,
                ),
                host=system.hostname,
                source="session",
                lifecycle_id=logon_id,
                sample_key="last_activity_gap",
            )
            if (
                latest_session_marker is not None
                and not from_storyline
                and authoritative_end_plan is None
            )
            else None
        )
        rendered_dependents_delta = (
            self._freeze_profile_activity_gap(
                "windows.logoff_after_rendered_dependents",
                stable_id=_activity_timing_stable_id(
                    "session-rendered-dependent-logoff",
                    request.stable_id,
                    session.ecar_object_id if session is not None else "",
                ),
                host=system.hostname,
                source="session",
                lifecycle_id=logon_id,
                sample_key="rendered_dependents_gap",
            )
            if (
                session is not None
                and authoritative_end_plan is None
                and (not uses_exact_linux_sudo_close or effective_linux_sudo_end_plan is None)
            )
            else None
        )
        ecar_logout_delta = (
            self._freeze_profile_activity_gap(
                "source.ecar_session_logout",
                stable_id=request.stable_id,
                host=system.hostname,
                source="ecar",
                lifecycle_id=logon_id,
                sample_key="ecar_logout_gap",
            )
            if authoritative_end_plan is not None
            else None
        )
        windows_logout_delta = (
            self._freeze_profile_activity_gap(
                "source.windows_security_session_logout",
                stable_id=request.stable_id,
                host=system.hostname,
                source="windows_event_security",
                lifecycle_id=logon_id,
                sample_key="windows_security_logout_gap",
            )
            if authoritative_end_plan is not None
            else None
        )
        used_timing_deltas: list[_FrozenActivityTimingDelta] = []

        if authoritative_end_plan is not None:
            time = ensure_utc(authoritative_end_plan.canonical_end)

        # Terminate session-specific processes before ending session
        deferred_ssh_transport_process = None
        remember_linux_session_close = False
        generic_process_closes: tuple[_GenericLogoffProcessClosePlan, ...] = ()
        if session:
            if ssh_transport_close_time is not None and authoritative_end_plan is None:
                if transport_close_delta is None:
                    raise StateError("SSH logoff lost its frozen transport-close delta")
                transport_logoff_time = ssh_transport_close_time + transport_close_delta.value
                used_timing_deltas.append(transport_close_delta)
                time = transport_logoff_time
            if (
                latest_session_marker is not None
                and not from_storyline
                and authoritative_end_plan is None
            ):
                # Source emitters add small native delays (for example Sysmon
                # Event 1 after canonical process creation). Leave enough room
                # that final logoff/logout records do not render before those
                # same-session dependents in another source.
                if last_activity_delta is None:
                    raise StateError("Logoff lost its frozen last-activity delta")
                min_logoff_time = latest_session_marker + last_activity_delta.value
                used_timing_deltas.append(last_activity_delta)
                if time <= min_logoff_time:
                    time = min_logoff_time
            if (
                _get_os_category(system.os) == "linux"
                and session.session_kind not in {"network", "service"}
                and session.logon_type not in {3, 5}
                and not uses_exact_linux_sudo_close
            ):
                remember_linux_session_close = True
            session_processes = list(frozen_session_processes)
            # Per-session winlogon is a SYSTEM-token process, so its immutable
            # process LogonID is 0x3e7 rather than the human session LUID.  The
            # explicit session pointer owns teardown membership across that
            # authentication-context boundary.
            if session.session_winlogon_pid is not None:
                session_winlogon = self.state_manager.get_process(
                    session.system,
                    session.session_winlogon_pid,
                )
                if session_winlogon is not None and all(
                    process.pid != session_winlogon.pid for process in session_processes
                ):
                    session_processes.append(session_winlogon)
            deferred_ssh_transport_process = (
                next(
                    (
                        process
                        for process in session_processes
                        if process.pid == session_transport_pid
                    ),
                    None,
                )
                if is_ssh_session and session_transport_pid is not None
                else None
            )
            if deferred_ssh_transport_process is not None:
                session_processes = [
                    process
                    for process in session_processes
                    if process.pid != deferred_ssh_transport_process.pid
                ]
            session_process_by_pid = {proc.pid: proc for proc in session_processes}

            def _session_process_depth(pid: int) -> int:
                depth = 0
                seen: set[int] = set()
                current = session_process_by_pid.get(pid)
                while current is not None and current.parent_pid not in seen:
                    seen.add(current.pid)
                    parent = session_process_by_pid.get(current.parent_pid)
                    if parent is None:
                        break
                    depth += 1
                    current = parent
                return depth

            session_processes.sort(
                key=lambda proc: (_session_process_depth(proc.pid), proc.start_time, proc.pid),
                reverse=True,
            )
            if uses_exact_linux_sudo_close:
                session_identity = self.state_manager.get_session_identity(session.logon_id)
                if session_identity is None:
                    raise StateError("Linux sudo logoff lost its exact live session identity")
                process_closes = self._plan_linux_sudo_logoff_process_closes(
                    system=system,
                    session=session,
                    processes=session_processes,
                    base_logoff_time=ensure_utc(time),
                    authoritative_end_plan=effective_linux_sudo_end_plan,
                )
                continuation = self._install_linux_sudo_logoff_continuation(
                    request=request,
                    session=session,
                    session_identity=session_identity,
                    base_logoff_time=ensure_utc(time),
                    effective_end_plan=effective_linux_sudo_end_plan,
                    process_closes=process_closes,
                    timing_deltas=tuple(used_timing_deltas),
                    rendered_dependents_delta=rendered_dependents_delta,
                    ecar_logout_delta=ecar_logout_delta,
                    windows_logout_delta=windows_logout_delta,
                )
                try:
                    self._execute_linux_sudo_logoff_continuation(continuation)
                finally:
                    self._release_linux_sudo_logoff_claim(continuation)
                return
            generic_process_closes, projected_session_frontier = (
                self._plan_generic_logoff_process_closes(
                    system=system,
                    session=session,
                    processes=session_processes,
                    base_logoff_time=ensure_utc(time),
                    authoritative_end_plan=authoritative_end_plan,
                    uses_ssh_transport_close_margin=ssh_transport_close_time is not None,
                    suppresses_linux_foreground_lifetime_clamp=closes_linux_sudo_route,
                )
            )
            if ssh_transport_close_time is not None and authoritative_end_plan is not None:
                if ssh_transport_close_time >= ensure_utc(authoritative_end_plan.canonical_end):
                    raise StateError(
                        "SSH transport extends beyond authoritative session end: "
                        f"{system.hostname} logon_id={logon_id}"
                    )
            if authoritative_end_plan is not None:
                self.state_manager.plan_session_end(logon_id, authoritative_end_plan)
            prior_visible_termination = self._session_process_source_terminate_times.get(
                (session.system, logon_id)
            )
            visible_termination_times = (
                [prior_visible_termination] if prior_visible_termination is not None else []
            )
            frozen_process_object_ids = frozenset(
                process_close.identity.object_id for process_close in generic_process_closes
            )
            frozen_process_token = _GENERIC_LOGOFF_FROZEN_PROCESS_OBJECT_IDS.set(
                frozen_process_object_ids
            )
            try:
                for process_close in generic_process_closes:
                    self.generate_process_termination(
                        user=user,
                        system=system,
                        time=process_close.end_time,
                        pid=process_close.identity.pid,
                        process_name=process_close.identity.image,
                        logon_id=logon_id,
                        from_storyline=from_storyline,
                        session_end_plan=authoritative_end_plan,
                    )
                    lifecycle_process = self._lifecycle_authority.registry.get_process(
                        process_close.identity.object_id
                    )
                    if (
                        lifecycle_process is None
                        or lifecycle_process.closed_at != process_close.end_time
                    ):
                        raise StateError(
                            "Generic logoff process close drifted from its frozen schedule: "
                            f"process={process_close.identity.object_id}"
                        )
                    if process_close.visible_create_delta is not None:
                        process_close.visible_create_delta.publish()
                    visible_termination_time = self.process_source_terminate_time(
                        session.system,
                        process_close.identity.pid,
                    )
                    if visible_termination_time is not None:
                        visible_termination_times.append(visible_termination_time)
            finally:
                _GENERIC_LOGOFF_FROZEN_PROCESS_OBJECT_IDS.reset(frozen_process_token)
            if visible_termination_times and authoritative_end_plan is None:
                latest_visible_termination = max(visible_termination_times)
                observation_gap = self.dispatcher.observation_policy.maximum_delay_difference(
                    "ecar",
                    "ecar",
                )
                if rendered_dependents_delta is None:
                    raise StateError("Logoff lost its frozen rendered-dependent delta")
                minimum_logoff_time = (
                    latest_visible_termination + rendered_dependents_delta.value + observation_gap
                )
                used_timing_deltas.append(rendered_dependents_delta)
                time = max(time, minimum_logoff_time)

            latest_session_member_close = (
                self._lifecycle_authority.session_latest_closed_member_at_for_object(
                    session.ecar_object_id
                )
            )
            generic_close_frontier = max(
                (
                    close_at
                    for close_at in (
                        projected_session_frontier,
                        latest_session_member_close,
                        *(close.end_time for close in generic_process_closes),
                    )
                    if close_at is not None
                ),
                default=None,
            )
            if generic_close_frontier is not None:
                minimum_session_close = ensure_utc(generic_close_frontier) + timedelta(
                    microseconds=1
                )
                if authoritative_end_plan is not None:
                    if minimum_session_close > ensure_utc(authoritative_end_plan.canonical_end):
                        raise StateError(
                            "Authoritative generic logoff cannot follow its exact "
                            "session-member close frontier"
                        )
                else:
                    time = max(ensure_utc(time), minimum_session_close)

            if authoritative_end_plan is not None:
                remaining_processes = self.state_manager.get_processes_for_session(
                    logon_id,
                    session.system,
                )
                if deferred_ssh_transport_process is not None:
                    remaining_processes = [
                        process
                        for process in remaining_processes
                        if process.pid != deferred_ssh_transport_process.pid
                    ]
                if remaining_processes:
                    raise StateError(
                        "Authoritative session closure left running processes: "
                        f"{system.hostname} logon_id={logon_id} "
                        f"pids={[proc.pid for proc in remaining_processes]}"
                    )

        # Build OccurrenceBuilder (StateManager.apply() handles end_session)
        self.state_manager.get_session_object_id(logon_id)
        session_source_ip = session.source_ip if session is not None else ""
        session_source_port = session.source_port if session is not None else 0
        session_id = (
            session.session_id if session is not None else self._session_id_for_logon(logon_id)
        )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="logoff",
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=(
                    session.smb_principal
                    if session is not None and session.session_kind == "smb"
                    else user.username
                ),
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session_id,
                logon_type=logon_type,
                source_ip=session_source_ip,
                source_port=session_source_port,
                session_kind=session.session_kind if session is not None else "",
                auth_protocol=session.auth_protocol if session is not None else "",
                smb_principal=session.smb_principal if session is not None else "",
                account_scope=session.account_scope if session is not None else "",
                auth_session_ref=session.auth_session_ref if session is not None else "",
                effective_uid=session.effective_uid if session is not None else None,
                effective_gid=session.effective_gid if session is not None else None,
            ),
            storyline_origin=from_storyline,
            lifecycle=(
                ActionLifecycleContext(
                    group_id=session.lifecycle_group_id,
                    canonical_start=session.start_time,
                    phase="closure",
                    parent_group_id=session.parent_lifecycle_group_id or None,
                )
                if session is not None
                else None
            ),
        )

        # Attach SyslogContext for Linux SSH sessions only (sshd session closed).
        # Non-SSH sessions (interactive, network) don't produce sshd evidence.
        if event.dst_host and event.dst_host.os_category == "linux" and is_ssh_session:
            from evidenceforge.events.contexts import SyslogContext

            transport_close_consistent = True
            if session is not None and session.network_close_time is not None:
                network_close_time = ensure_utc(session.network_close_time)
                logoff_time = ensure_utc(time)
                transport_close_consistent = logoff_time <= network_close_time + timedelta(
                    seconds=90
                )
            sshd_pid = (
                session_transport_pid
                if session_transport_pid is not None
                else self.state_manager.allocate_transient_linux_pid(
                    system.hostname, time, os_category=_get_os_category(system.os)
                )
            )
            source_port = session.source_port if session else 0
            if (
                not source_port
                or not session
                or session.source_ip == system.ip
                or not transport_close_consistent
            ):
                event.syslog = None
            else:
                event.syslog = SyslogContext(
                    app_name="sshd",
                    pid=sshd_pid,
                    facility=10,
                    severity=6,
                    message=f"pam_unix(sshd:session): session closed for user {user.username}",
                )

        pam_close_time: datetime | None = None
        if authoritative_end_plan is not None:
            if ecar_logout_delta is None or windows_logout_delta is None:
                raise StateError("Authoritative logoff lost its frozen source timing deltas")
            ecar_close_time = time + ecar_logout_delta.value
            windows_close_time = time + windows_logout_delta.value
            used_timing_deltas.extend((ecar_logout_delta, windows_logout_delta))
            self._source_timing_planner.record_session_closure_source_time(
                event,
                "ecar",
                ecar_close_time,
            )
            self._source_timing_planner.record_session_closure_source_time(
                event,
                "windows_event_security",
                windows_close_time,
            )
            if is_ssh_session and ssh_transport_close_time is not None and event.syslog is not None:
                pam_delay_ms = 120 + (
                    _stable_seed(
                        "ssh_pam_close_after_transport:"
                        f"{system.hostname}:{logon_id}:{ssh_transport_close_time.isoformat()}"
                    )
                    % 2381
                )
                pam_close_time = min(
                    ssh_transport_close_time + timedelta(milliseconds=pam_delay_ms),
                    ensure_utc(authoritative_end_plan.canonical_end) + timedelta(seconds=4),
                )
                self._source_timing_planner.record_session_closure_source_time(
                    event,
                    "syslog",
                    pam_close_time,
                )

        if session is not None and deferred_ssh_transport_process is not None:
            if event.syslog is not None:
                pam_close_time = self._source_timing_planner.session_closure_source_time(
                    event,
                    "syslog",
                )
            responder_close_anchor = pam_close_time or ensure_utc(time)
            responder_close_seed = _stable_seed(
                "generic_ssh_responder_terminate_after_pam:"
                f"{system.hostname}:{logon_id}:{deferred_ssh_transport_process.pid}:"
                f"{responder_close_anchor.isoformat()}"
            )
            self.generate_process_termination(
                user=user,
                system=system,
                time=responder_close_anchor
                + timedelta(
                    milliseconds=3200 + (responder_close_seed % 2000),
                    microseconds=307 + (responder_close_seed % 491),
                ),
                pid=deferred_ssh_transport_process.pid,
                process_name=deferred_ssh_transport_process.image,
                logon_id=deferred_ssh_transport_process.logon_id,
                from_storyline=from_storyline,
            )

        # Phase 3: Dispatch to matching emitters
        self.dispatcher.dispatch_builder(event)
        if event.syslog is not None and event.dst_host and event.dst_host.os_category == "linux":
            if is_ssh_session and session_id:
                remove_seed = _stable_seed(
                    "linux_ssh_logoff_logind_removed:"
                    f"{system.hostname}:{user.username}:{logon_id}:{session_id}:"
                    f"{time.isoformat()}"
                )
                syslog_close_time = self._source_timing_planner.session_closure_source_time(
                    event,
                    "syslog",
                )
                self.dispatcher.dispatch_builder(
                    OccurrenceBuilder(
                        timestamp=min(
                            syslog_close_time
                            + timedelta(
                                milliseconds=120 + (remove_seed % 880),
                                microseconds=701 + (remove_seed % 173),
                            ),
                            ensure_utc(time) + timedelta(seconds=4),
                        ),
                        event_type="syslog",
                        src_host=event.dst_host,
                        auth=AuthContext(
                            username=user.username,
                            user_sid=self._get_sid(user.username),
                            logon_id=logon_id,
                            session_id=session_id,
                            logon_type=logon_type,
                            source_ip=session_source_ip,
                            source_port=session_source_port,
                        ),
                        syslog=SyslogContext(
                            app_name="systemd-logind",
                            pid=self._get_system_pid(system.hostname, "logind", 456),
                            facility=10,
                            severity=6,
                            message=f"Removed session {session_id}.",
                        ),
                    )
                )

        if remember_linux_session_close:
            self._linux_shell_last_session_close[(system.hostname, user.username)] = ensure_utc(
                time
            )
        for timing_delta in used_timing_deltas:
            timing_delta.publish()
        if session is not None and (
            closes_linux_sudo_route or self._has_linux_sudo_tty_route(logon_id)
        ):
            self._require_accepted_linux_sudo_session_close_owner(session)
            self._release_session_retention_state(
                hostname=session.system,
                username=session.username,
                logon_id=logon_id,
            )
        logger.debug(
            f"Generated logoff: {user.username} on {system.hostname} (LogonID: {logon_id})"
        )

    @staticmethod
    def _user_profile_directory(username: str) -> str:
        """Return the Windows profile directory for a process owner."""
        account = username.split("\\")[-1]
        if account in _SYSTEM_ACCOUNTS or account.endswith("$"):
            return r"C:\Windows\System32"
        return rf"C:\Users\{account}"

    def _derive_current_directory(
        self,
        system: System,
        username: str,
        process_name: str,
        command_line: str,
        parent_pid: int,
        logon_type: int = 2,
    ) -> str:
        """Derive a source-native process working directory for Sysmon Event 1."""
        if _get_os_category(system.os) != "windows":
            account = username.split("\\")[-1]
            return (
                "/root" if account in _SYSTEM_ACCOUNTS or account == "root" else f"/home/{account}"
            )

        image = process_name.replace("/", "\\")
        image_lower = image.lower()
        exe = image_lower.rsplit("\\", 1)[-1]
        profile_dir = self._user_profile_directory(username)
        system_dir = r"C:\Windows\System32"

        if username in _SYSTEM_ACCOUNTS or username.endswith("$"):
            return system_dir + "\\"
        if logon_type == 5:
            return system_dir + "\\"

        parent_image = (
            self._lookup_process_name(system.hostname, parent_pid, _get_os_category(system.os))
            or ""
        ).lower()
        parent_dir = parent_image.rsplit("\\", 1)[0] if "\\" in parent_image else ""

        if exe in {"winword.exe", "excel.exe", "powerpnt.exe", "acrord32.exe", "acrobat.exe"}:
            if '"' in command_line:
                for candidate in command_line.split('"')[1::2]:
                    if "\\" in candidate:
                        return candidate.rsplit("\\", 1)[0] + "\\"
            return profile_dir + "\\Documents\\"

        if exe in {"onedrive.exe", "teams.exe", "outlook.exe"}:
            return profile_dir + "\\"

        if exe in {
            "cargo.exe",
            "docker.exe",
            "git.exe",
            "kubectl.exe",
            "node.exe",
            "npm.cmd",
            "npm.exe",
            "ssh.exe",
        }:
            if exe == "ssh.exe":
                return profile_dir + "\\"
            repo_names = (
                "clinical-portal",
                "integration-api",
                "ops-automation",
                "platform-services",
                "security-tools",
            )
            repo = repo_names[
                _stable_seed(
                    f"windows_project_cwd:{system.hostname}:{username}:{process_name}:"
                    f"{command_line}"
                )
                % len(repo_names)
            ]
            return profile_dir + f"\\source\\repos\\{repo}\\"

        if exe in {"chrome.exe", "msedge.exe", "firefox.exe"}:
            install_dir = image.rsplit("\\", 1)[0] if "\\" in image else ""
            if parent_dir and parent_dir == install_dir.lower():
                return install_dir + "\\"
            return profile_dir + "\\"

        if exe in {"cmd.exe", "powershell.exe", "pwsh.exe"}:
            if parent_dir and "windows\\system32" not in parent_dir:
                return parent_dir + "\\"
            return profile_dir + "\\"

        if "\\windows\\system32\\" in image_lower or "\\windows\\syswow64\\" in image_lower:
            return system_dir + "\\"

        if "\\" in image:
            return image.rsplit("\\", 1)[0] + "\\"

        return profile_dir + "\\"

    def _space_one_shot_cli_launch(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
    ) -> datetime:
        """Avoid machine-impossible bursts of repeated one-shot admin commands."""
        if _get_os_category(system.os) != "windows":
            return time

        exe_name = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name not in _WINDOWS_ONE_SHOT_CLI_EXES:
            return time

        normalized_command = " ".join(command_line.lower().split())
        exe_key = (system.hostname, username, logon_id, exe_name)
        command_key = (*exe_key, normalized_command)
        adjusted_time = time

        command_last = self._last_one_shot_cli_launch_by_command.get(command_key)
        if command_last is not None:
            min_gap = timedelta(
                seconds=random.Random(
                    _stable_seed(
                        f"one_shot_cli_same_command:{system.hostname}:{username}:"
                        f"{exe_name}:{normalized_command}:{command_last.isoformat()}"
                    )
                ).uniform(18.0, 75.0)
            )
            if adjusted_time < command_last + min_gap:
                adjusted_time = command_last + min_gap

        exe_last = self._last_one_shot_cli_launch_by_exe.get(exe_key)
        if exe_last is not None:
            min_gap = timedelta(
                seconds=random.Random(
                    _stable_seed(
                        f"one_shot_cli_same_exe:{system.hostname}:{username}:"
                        f"{exe_name}:{exe_last.isoformat()}"
                    )
                ).uniform(2.5, 9.0)
            )
            if adjusted_time < exe_last + min_gap:
                adjusted_time = exe_last + min_gap

        self._last_one_shot_cli_launch_by_exe[exe_key] = adjusted_time
        self._last_one_shot_cli_launch_by_command[command_key] = adjusted_time
        return adjusted_time

    def _remember_one_shot_cli_launch(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
    ) -> None:
        """Record the final launch timestamp for later one-shot CLI spacing."""
        if _get_os_category(system.os) != "windows":
            return
        exe_name = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name not in _WINDOWS_ONE_SHOT_CLI_EXES:
            return
        normalized_command = " ".join(command_line.lower().split())
        exe_key = (system.hostname, username, logon_id, exe_name)
        command_key = (*exe_key, normalized_command)
        self._last_one_shot_cli_launch_by_exe[exe_key] = time
        self._last_one_shot_cli_launch_by_command[command_key] = time

    @staticmethod
    def _is_top_level_browser_launch(process_name: str, command_line: str) -> bool:
        """Return whether a Windows browser command represents a user-facing process."""
        exe_name = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name not in _WINDOWS_BROWSER_EXES:
            return False
        command = f" {command_line.lower()} "
        return not any(marker in command for marker in _WINDOWS_BROWSER_CHILD_MARKERS)

    def _existing_user_browser_pid(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
        source_visible_by: datetime | None = None,
    ) -> int | None:
        """Reuse an open browser instead of emitting repeated top-level launches."""
        if _get_os_category(system.os) != "windows":
            return None
        if not self._is_top_level_browser_launch(process_name, command_line):
            return None

        requested_exe = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        preferred_key = (system.hostname, username, "")
        preferred_exe = self._preferred_browser_by_session.get(preferred_key)
        candidates: list[RunningProcess] = []
        for proc in self.state_manager.get_processes_on_system(system.hostname):
            if proc.username != username:
                continue
            if not self._is_pid_active_at(system, proc.pid, time):
                continue
            proc_exe = proc.image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
            if proc_exe not in _WINDOWS_BROWSER_EXES:
                continue
            if not self._is_top_level_browser_launch(proc.image, proc.command_line):
                continue
            candidates.append(proc)

        if not candidates:
            self._preferred_browser_by_session[preferred_key] = requested_exe
            return None

        if preferred_exe:
            preferred = [proc for proc in candidates if proc.image.lower().endswith(preferred_exe)]
            if preferred:
                proc = max(preferred, key=lambda candidate: candidate.start_time)
                if not self._process_source_visible_by(
                    hostname=system.hostname,
                    pid=proc.pid,
                    deadline=source_visible_by,
                ):
                    return None
                self.state_manager.update_process_activity_time(system.hostname, proc.pid, time)
                return proc.pid

        same_exe = [
            proc
            for proc in candidates
            if proc.image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower() == requested_exe
        ]
        chosen = max(same_exe or candidates, key=lambda candidate: candidate.start_time)
        if not self._process_source_visible_by(
            hostname=system.hostname,
            pid=chosen.pid,
            deadline=source_visible_by,
        ):
            return None
        self._preferred_browser_by_session[preferred_key] = (
            chosen.image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        )
        self.state_manager.update_process_activity_time(system.hostname, chosen.pid, time)
        return chosen.pid

    def _existing_persistent_user_app_pid(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
        source_visible_by: datetime | None = None,
        update_activity: bool = True,
    ) -> int | None:
        """Reuse already-open desktop apps that normally stay resident."""
        requested_exe = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        from evidenceforge.generation.activity.application_catalog import (
            is_singleton_application_image,
        )

        if requested_exe not in _PERSISTENT_USER_APP_EXES and not is_singleton_application_image(
            process_name, _get_os_category(system.os)
        ):
            return None
        command = f" {command_line.lower()} "
        if any(marker in command for marker in _WINDOWS_ELECTRON_CHILD_MARKERS):
            return None

        candidates: list[RunningProcess] = []
        for proc in self.state_manager.get_processes_on_system(system.hostname):
            if proc.username != username:
                continue
            if proc.logon_id and logon_id and proc.logon_id != logon_id:
                continue
            if not self._is_pid_active_at(system, proc.pid, time):
                continue
            if self._foreground_process_expired_for_attribution(system, proc, time):
                continue
            proc_exe = proc.image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
            if proc_exe == requested_exe:
                candidates.append(proc)

        if not candidates:
            return None
        chosen = max(
            candidates,
            key=lambda candidate: candidate.last_activity_time or candidate.start_time,
        )
        if not self._process_source_visible_by(
            hostname=system.hostname,
            pid=chosen.pid,
            deadline=source_visible_by,
        ):
            # ``0`` is the bounded caller's explicit reject sentinel. Returning
            # ``None`` would make it fabricate a duplicate singleton process.
            return 0
        if update_activity:
            self.state_manager.update_process_activity_time(system.hostname, chosen.pid, time)
        return chosen.pid

    def _process_effect_context(
        self,
        system: System,
        pid: int,
        process_name: str,
        command_line: str,
    ) -> tuple[str, str]:
        """Return the process identity that downstream effects should use."""
        proc = self.state_manager.get_process(system.hostname, pid)
        if proc is None:
            return process_name, command_line
        return proc.image, proc.command_line

    def _foreground_process_expired_for_attribution(
        self,
        system: System,
        proc: Any,
        time: datetime,
    ) -> bool:
        """Return whether a foreground process is not active for new effects."""
        if proc is None or proc.start_time is None:
            return False
        if time < proc.start_time:
            return True
        lifetime = self._foreground_process_lifetime_for_attribution(system, proc)
        if lifetime is None:
            return False
        max_process_time = proc.start_time + timedelta(seconds=lifetime[1] + 5.0)
        return time > max_process_time

    def _foreground_process_lifetime_for_attribution(
        self,
        system: System,
        proc: Any,
    ) -> tuple[float, float] | None:
        """Return bounded foreground lifetime for process-owned network attribution."""
        os_category = _get_os_category(system.os)
        if os_category == "windows":
            return _windows_foreground_lifetime(proc.image, proc.command_line)
        if os_category == "linux":
            exe_name = proc.image.rsplit("/", 1)[-1].lower()
            if "/usr/lib/apt/methods/" in str(proc.image).lower():
                return _linux_foreground_lifetime(proc.image, proc.command_line)
            if exe_name not in _LINUX_ONE_SHOT_NETWORK_EXES:
                return None
            return _linux_foreground_lifetime(proc.image, proc.command_line)
        return None

    def _space_browser_launch(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
    ) -> datetime:
        """Avoid rendered bursts of repeated top-level browser process creates."""
        if _get_os_category(system.os) != "windows":
            return time
        if not self._is_top_level_browser_launch(process_name, command_line):
            return time

        key = (system.hostname, username, logon_id)
        previous = self._last_browser_launch_by_session.get(key)
        adjusted_time = time
        if previous is not None:
            rng = random.Random(
                _stable_seed(
                    f"browser_launch_gap:{system.hostname}:{username}:{logon_id}:"
                    f"{previous.isoformat()}"
                )
            )
            min_gap = timedelta(seconds=rng.uniform(4.0, 18.0))
            if adjusted_time < previous + min_gap:
                adjusted_time = previous + min_gap
        self._last_browser_launch_by_session[key] = adjusted_time
        return adjusted_time

    @staticmethod
    def _singleton_application_key(
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
    ) -> tuple[str, str, str, str]:
        """Return the durable identity for one session-scoped singleton app."""
        return (
            system.hostname,
            username.lower(),
            logon_id,
            process_name.replace("/", "\\").lower(),
        )

    def claim_singleton_application_interval(
        self,
        key: tuple[str, str, str, str],
        start: datetime,
        provisional_end: datetime,
    ) -> bool:
        """Atomically reserve a singleton interval unless it overlaps an owner."""
        with self._singleton_application_lock:
            intervals = self._singleton_application_intervals.setdefault(key, [])
            if any(
                start < existing_end and existing_start < provisional_end
                for existing_start, existing_end in intervals
            ):
                return False
            intervals.append((start, provisional_end))
            return True

    def _cancel_singleton_application_interval(
        self,
        key: tuple[str, str, str, str],
        start: datetime,
        provisional_end: datetime,
    ) -> None:
        """Remove one exact provisional singleton claim after rejected creation."""

        with self._singleton_application_lock:
            intervals = self._singleton_application_intervals.get(key)
            if intervals is None:
                return
            try:
                intervals.remove((start, provisional_end))
            except ValueError:
                return
            if not intervals:
                self._singleton_application_intervals.pop(key, None)

    def update_singleton_application_end(
        self,
        key: tuple[str, str, str, str],
        start: datetime,
        end: datetime,
    ) -> None:
        """Replace a provisional singleton end after lifecycle planning."""
        with self._singleton_application_lock:
            intervals = self._singleton_application_intervals.get(key, [])
            for index, (existing_start, _existing_end) in enumerate(intervals):
                if existing_start == start:
                    intervals[index] = (start, end)
                    return

    @staticmethod
    def _linux_process_is_system_background_helper(process_name: str, command_line: str) -> bool:
        """Return whether a Linux helper should be modeled as daemon/timer-owned."""
        image_lower = process_name.lower()
        command_lower = command_line.lower()
        exe_name = image_lower.rsplit("/", 1)[-1]
        if image_lower.startswith("/usr/lib/apt/methods/"):
            return True
        if exe_name in {"dnf", "yum"} and any(
            token in command_lower for token in ("makecache", "check-update", "update")
        ):
            return True
        if exe_name == "service-healthcheck":
            return True
        return exe_name == "java" and "integration-worker" in command_lower

    @staticmethod
    def _linux_background_helper_username(process_name: str, command_line: str) -> str:
        """Return the service principal for a Linux background helper process."""
        exe_name = process_name.lower().rsplit("/", 1)[-1]
        if exe_name == "java" and "integration-worker" in command_line.lower():
            return "www-data"
        return "root"

    def generate_process(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
        process_name: str,
        command_line: str,
        parent_pid: int = 4,
        ensure_file_event: bool = False,
        from_storyline: bool = False,
        suppress_command_file_effect: bool = False,
        allow_existing_browser_reuse: bool = True,
        allow_browser_launch_spacing: bool = True,
        concurrency_group_id: str = "",
        lifecycle_group_id: str = "",
        source_visible_by: datetime | None = None,
    ) -> int:
        """Generate process creation event across all applicable log formats.

        Creates process in StateManager, builds a OccurrenceBuilder, and dispatches
        to matching emitters (Windows 4688, eCAR PROCESS/CREATE). Also emits
        probabilistic EDR file/module/registry events.

        When ensure_file_event=True, always emits at least one FILE/CREATE for
        the process image (useful for storyline processes where FILE visibility
        is important for hunting).

        Args:
            user: User creating the process
            system: System where process is created
            time: Process creation timestamp
            logon_id: LogonID of the user's session
            process_name: Full path to executable
            command_line: Command line string
            parent_pid: Parent process PID (default 4 = System)
            suppress_command_file_effect: Caller already owns command output file artifacts.
            allow_existing_browser_reuse: Reuse an already-open browser for repeated
                navigation requests. Parent-repair paths disable this when they need
                a concrete same-family browser parent for renderer/utility children.
            allow_browser_launch_spacing: Apply anti-burst spacing to top-level browser
                launches. Causal connection-owner processes disable this so process
                creation stays before the socket evidence they own.
            concurrency_group_id: Explicit same-shell concurrency group for true pipelines.
            lifecycle_group_id: Optional owning lifecycle for session-bootstrap helpers.

        Returns:
            PID of the new process
        """
        request = ProcessExecutionRequest(
            user=user,
            system=system,
            time=time,
            logon_id=logon_id,
            process_name=process_name,
            command_line=command_line,
            parent_pid=parent_pid,
            ensure_file_event=ensure_file_event,
            from_storyline=from_storyline,
            suppress_command_file_effect=suppress_command_file_effect,
            allow_existing_browser_reuse=allow_existing_browser_reuse,
            allow_browser_launch_spacing=allow_browser_launch_spacing,
            concurrency_group_id=concurrency_group_id,
            lifecycle_group_id=lifecycle_group_id,
            source_visible_by=source_visible_by,
        )
        bounded_request = self._preflight_bounded_process_source_deadline(request)
        if bounded_request is None:
            return 0
        return ProcessExecutionActionBundle(self, bounded_request).execute()

    def _preflight_bounded_process_source_deadline(
        self,
        request: ProcessExecutionRequest,
    ) -> ProcessExecutionRequest | None:
        """Reject an impossible process-create source deadline before bundle planning."""

        if request.source_visible_by is None:
            return request
        source_deadline = ensure_utc(request.source_visible_by)
        request = replace(request, source_visible_by=source_deadline)
        actor = self._prepare_process_effect_actor(request)
        if (
            matching_service_worker(
                os_category=_get_os_category(request.system.os),
                image=actor.image,
                command_line=actor.command_line,
                username=actor.username,
            )
            is not None
        ):
            # Profiled service workers own their manager/worker composite admission.
            return request
        parent_pid = self._resolve_existing_prepared_process_parent(
            system=request.system,
            user=request.user,
            time=actor.started_at,
            logon_id=actor.logon_id,
            parent_pid=request.parent_pid,
            process_username=actor.username,
        )
        if parent_pid != request.parent_pid:
            request = replace(request, parent_pid=parent_pid)
            actor = self._prepare_process_effect_actor(request)
        reuse_found, reuse_intent = self._bounded_process_reuse_intent(
            request=request,
            actor=actor,
        )
        if reuse_found:
            return replace(request, reuse_intent=reuse_intent) if reuse_intent is not None else None
        parent_source_time = (
            self._process_source_frontier_or_bound(
                system=request.system,
                pid=parent_pid,
            )
            if parent_pid > 0
            else None
        )
        session = self.state_manager.get_session(actor.logon_id) if actor.logon_id else None
        source_bound = self._process_create_source_bound(
            system=request.system,
            canonical_time=actor.started_at,
            parent_source_time=parent_source_time,
            session_source_time=(
                _session_source_ready_time(session) if session is not None else None
            ),
        )
        return request if source_bound <= source_deadline else None

    def _bounded_process_reuse_intent(
        self,
        *,
        request: ProcessExecutionRequest,
        actor: PreparedProcessEffectActor,
    ) -> tuple[bool, ProcessExecutionReuseIntent | None]:
        """Find and authenticate an exact bounded reuse without mutating its process."""

        if request.source_visible_by is None:
            return False, None
        if request.ensure_file_event or any(
            effect.spec.requirement != EffectRequirement.OPTIONAL
            for effect in request.requested_endpoint_effects
        ):
            return False, None
        if not request.suppress_command_file_effect:
            from evidenceforge.generation.activity.edr_pools import (
                select_command_file_side_effect,
            )

            if select_command_file_side_effect(actor.image, actor.command_line) is not None:
                return False, None
        if self._runtime_content_manager is not None:
            resolved_binary = self.dispatcher.resolve_process_binary_identity(
                request.system.hostname,
                actor.username,
                actor.image,
                cast(Platform, _get_os_category(request.system.os)),
            )
            if isinstance(resolved_binary, UnresolvedBinaryIdentity):
                return False, None

        candidate_pid = self._existing_windows_singleton_pid(
            request.system,
            actor.image,
            actor.started_at,
        )
        parent = self.state_manager.get_process(request.system.hostname, request.parent_pid)
        if (
            candidate_pid is None
            and _get_os_category(request.system.os) == "windows"
            and parent is not None
            and ntpath.basename(parent.image).lower() == "services.exe"
        ):
            candidate_pid = self._existing_windows_singleton_service_pid(
                system=request.system,
                process_name=actor.image,
                time=actor.started_at,
                username=actor.username,
                command_line=actor.command_line,
            )
        if candidate_pid is None and not request.from_storyline:
            candidate_pid = self._existing_persistent_user_app_pid(
                system=request.system,
                username=actor.username,
                logon_id=actor.logon_id,
                process_name=actor.image,
                command_line=actor.command_line,
                time=actor.started_at,
                source_visible_by=request.source_visible_by,
                update_activity=False,
            )
        if candidate_pid is None:
            return False, None
        if candidate_pid <= 0:
            return True, None

        running = self.state_manager.get_process(request.system.hostname, candidate_pid)
        identity = self.state_manager.get_process_identity(
            request.system.hostname,
            candidate_pid,
        )
        source_frontier = self.process_source_create_time(
            request.system.hostname,
            candidate_pid,
        )
        if running is None or identity is None or source_frontier is None:
            return True, None
        if source_frontier > ensure_utc(request.source_visible_by):
            return True, None
        return True, ProcessExecutionReuseIntent(
            hostname=request.system.hostname,
            process_object_id=identity.object_id,
            pid=candidate_pid,
            parent_pid=running.parent_pid,
            image=running.image,
            command_line=running.command_line,
            username=running.username,
            logon_id=running.logon_id,
            started_at=running.start_time,
            source_frontier=source_frontier,
        )

    def _finalize_due_process_lifetimes(
        self,
        cutoff: datetime,
        *,
        exhaust: bool,
    ) -> None:
        """Render bounded due-close pages outside lifecycle-authority locks.

        Hot allocation boundaries drain one fixed page and apply backpressure if
        more work is already due.  Engine watermarks and finalization explicitly
        repeat pages before sealing the canonical frontier.
        """

        known_users = getattr(self, "_users_by_username", {})
        normalized_cutoff = ensure_utc(cutoff)
        while True:
            due = self._lifecycle_authority.pop_due_process_closes(normalized_cutoff)
            if not due:
                return
            for intent in due:
                system = intent.system
                running = self.state_manager.get_process(system.hostname, intent.pid)
                if running is None:
                    continue
                if running.start_time != intent.started_at:
                    continue
                if self._process_termination_recorded(
                    system.hostname,
                    intent.pid,
                    running.start_time,
                ):
                    continue
                process_user = known_users.get(intent.username) or User(
                    username=intent.username,
                    full_name=intent.username,
                    email=f"{intent.username}@example.local",
                )
                self.generate_process_termination(
                    user=process_user,
                    system=system,
                    time=intent.close_at,
                    pid=intent.pid,
                    process_name=running.image or intent.process_name,
                    logon_id=running.logon_id or intent.logon_id,
                )
            if not exhaust:
                if self._lifecycle_authority.has_due_process_closes(normalized_cutoff):
                    raise StateError(
                        "Process allocation cannot proceed while more than one bounded "
                        "lifecycle close page is already due; advance the engine watermark"
                    )
                return

    def _sample_process_spacing_gap(
        self,
        *,
        relationship_key: str,
        stable_id: str,
        system: System,
        logon_id: str,
        minimum_seconds: float,
        mode_seconds: float,
        maximum_seconds: float,
    ) -> timedelta:
        """Sample one order-independent process spacing gap through the shared runtime."""

        return self.timing_runtime.sampler.sample_timedelta(
            TriangularDistribution(
                minimum=minimum_seconds * 1_000_000,
                mode=mode_seconds * 1_000_000,
                maximum=maximum_seconds * 1_000_000,
            ),
            relationship_key=relationship_key,
            scope=TimingScope(
                stable_id=stable_id,
                host=system.hostname,
                source="endpoint_process",
                lifecycle_id=logon_id,
            ),
            sample_key="gap",
        )

    def record_owned_effect_occurrence_plan(self, plan: OwnedEffectOccurrencePlan) -> None:
        """Register one exact non-process family-owned endpoint-effect root."""

        self._execution_effect_audit.record_owned_effect_plan(plan)

    def _plan_nmap_command_probes(
        self,
        request: NmapCommandProbeRequest,
        planning_profile: NmapCommandProbePlanningProfile,
    ) -> NmapCommandProbePlan | None:
        """Compile recognized nmap commands without allocating process state."""

        command_lower = request.command_line.lower()
        image_lower = request.process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if image_lower not in {"nmap", "nmap.exe"} and " nmap " not in f" {command_lower} ":
            return None
        return NmapCommandProbePlanner(planning_profile).plan(
            request,
            getattr(self, "_ip_to_system", {}),
        )

    @staticmethod
    def _nmap_command_probe_count(plan: NmapCommandProbePlan) -> int:
        """Return exact canonical connection cardinality for one bounded plan."""

        return len(plan.targets) if plan.discovery else len(plan.targets) * len(plan.ports)

    def _plan_process_execution_effects(
        self,
        request: ProcessExecutionRequest,
        anchor: ActionAnchor,
    ) -> ExecutionEffectPlan:
        """Plan bounded command effects before allocating the root process."""

        planning_request = NmapCommandProbeRequest(
            user=request.user,
            system=request.system,
            time=request.time,
            pid=-1,
            process_name=request.process_name,
            command_line=request.command_line,
        )
        scanner_plan = self._plan_nmap_command_probes(
            planning_request,
            nmap_command_probe_config(),
        )
        if scanner_plan is None:
            return ExecutionEffectPlan(anchor=anchor)
        probe_count = self._nmap_command_probe_count(scanner_plan)
        scanner_node = ExecutionEffectNode.create(
            anchor,
            ScannerEffectIntent(
                tool="nmap",
                target=request.command_line,
                probe_count=probe_count,
            ),
        )
        return ExecutionEffectPlan(anchor=anchor, nodes=(scanner_node,))

    def _process_endpoint_uses_action_cohort(
        self,
        *,
        actor: PreparedProcessEffectActor,
        admitted_effects: tuple[PreparedEndpointEffect, ...],
        effect_plan: ExecutionEffectPlan | None,
    ) -> bool:
        """Select the exact endpoint publication boundary without mutating an owner."""

        from evidenceforge.generation.actions.command_effects import (
            FileEffectIntent,
            RegistryEffectIntent,
        )

        has_scanner_effect_intent = effect_plan is not None and any(
            isinstance(node.intent, ScannerEffectIntent) for node in effect_plan.nodes
        )
        has_non_single_endpoint_effect = any(
            isinstance(effect.spec.intent, (FileEffectIntent, RegistryEffectIntent))
            and effect.spec.intent.occurrence_cardinality != 1
            for effect in admitted_effects
        )
        state_session = self.state_manager.get_session(actor.logon_id) if actor.logon_id else None
        state_session_identity = (
            self.state_manager.get_session_identity(actor.logon_id)
            if state_session is not None
            else None
        )
        lifecycle_session_snapshot = (
            self._lifecycle_authority.registry.get_session(state_session_identity.object_id)
            if state_session_identity is not None
            else None
        )
        session_requires_legacy_endpoint_path = state_session is not None and (
            state_session_identity is None
            or lifecycle_session_snapshot is None
            or lifecycle_session_snapshot.identity
            != LifecycleShadow.project_session_start(state_session_identity)
        )
        if has_scanner_effect_intent and has_non_single_endpoint_effect:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "scanner process endpoint effects require exactly one occurrence on the "
                "legacy publication path",
            )
        if session_requires_legacy_endpoint_path and has_non_single_endpoint_effect:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "process endpoint effects require exactly one occurrence when the owning "
                "State session lacks exact lifecycle-registry identity",
            )
        return not has_scanner_effect_intent and not session_requires_legacy_endpoint_path

    def _plan_process_execution_side_effects(
        self,
        request: ProcessExecutionRequest,
        anchor: ActionAnchor,
    ) -> ProcessExecutionPreparedEffects | None:
        """Freeze endpoint/module intent before any PID, lifecycle, or event mutation."""

        if request.reuse_intent is not None:
            return ProcessExecutionPreparedEffects(
                root_anchor=anchor,
                actor=self._prepare_process_effect_actor(request),
            )

        from evidenceforge.generation.actions.command_effects import (
            EffectRequirement,
            FileEffectAction,
            FileEffectIntent,
            RegistryEffectAction,
            RegistryEffectIntent,
        )
        from evidenceforge.generation.actions.endpoint_effects import (
            EndpointEffectSpec,
            EndpointStateDisposition,
            PreparedEndpointEffect,
            PreparedFileEffectPayload,
            PreparedProcessEndpointEffectPlan,
            PreparedRegistryEffectPayload,
        )

        if (
            matching_service_worker(
                os_category=_get_os_category(request.system.os),
                image=request.process_name,
                command_line=request.command_line,
                username=request.user.username,
            )
            is not None
        ):
            return None

        actor = self._prepare_process_effect_actor(request)
        rng = self._process_endpoint_effect_rng(request, actor)
        endpoint_window_candidates = [actor.started_at + timedelta(days=1)]
        scenario_end = getattr(self, "_scenario_end_time", None)
        if isinstance(scenario_end, datetime):
            endpoint_window_candidates.append(ensure_utc(scenario_end))
        dispatcher_end = getattr(self.dispatcher, "output_end_time", None)
        if isinstance(dispatcher_end, datetime):
            endpoint_window_candidates.append(ensure_utc(dispatcher_end))
        endpoint_window_end = min(endpoint_window_candidates)
        source_ready_floor = actor.started_at + timedelta(seconds=4)
        planned: list[PreparedEndpointEffect] = list(request.requested_endpoint_effects)

        process_name = actor.image
        command_line = actor.command_line
        process_username = actor.username
        os_category = _get_os_category(request.system.os)
        exe_lower = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        bundle_owned_service_payload = exe_lower in {
            "psexesvc.exe",
            "healthmonitorsvc.exe",
        }
        if request.ensure_file_event and not bundle_owned_service_payload:
            lower_path = process_name.lower()
            windows_path = lower_path.replace("/", "\\")
            is_system_binary = (
                windows_path.startswith("c:\\windows\\system32\\")
                or windows_path.startswith("c:\\windows\\syswow64\\")
                or windows_path.startswith("c:\\program files\\")
                or windows_path.startswith("c:\\program files (x86)\\")
                or lower_path.startswith(
                    (
                        "/bin/",
                        "/sbin/",
                        "/usr/bin/",
                        "/usr/sbin/",
                        "/usr/local/bin/",
                        "/usr/local/sbin/",
                    )
                )
            )
            if not is_system_binary:
                occurrence_time = max(
                    actor.started_at + timedelta(milliseconds=120),
                    source_ready_floor,
                )
                planned.append(
                    PreparedEndpointEffect(
                        spec=EndpointEffectSpec(
                            intent=FileEffectIntent(
                                action=FileEffectAction.CREATE,
                                path=process_name,
                            ),
                            occurrence_times=(occurrence_time,),
                            instance_key="guaranteed-process-image-create",
                            state_disposition=EndpointStateDisposition.DURABLE_FINAL,
                            retention_deadline=max(
                                endpoint_window_end,
                                occurrence_time + timedelta(microseconds=1),
                            ),
                        ),
                        event_type="file_create",
                        payload=PreparedFileEffectPayload(
                            path=process_name,
                            action=FileEffectAction.CREATE,
                        ),
                    )
                )

        semantic_file_effect = None
        if not request.suppress_command_file_effect:
            from evidenceforge.generation.activity.edr_pools import select_command_file_side_effect

            semantic_file_effect = select_command_file_side_effect(process_name, command_line)
            if semantic_file_effect is not None:
                action, path = semantic_file_effect
                file_action = FileEffectAction(action)
                occurrence_time = max(
                    actor.started_at + timedelta(milliseconds=180),
                    source_ready_floor + timedelta(milliseconds=1),
                )
                mutates = file_action in {FileEffectAction.CREATE, FileEffectAction.MODIFY}
                planned.append(
                    PreparedEndpointEffect(
                        spec=EndpointEffectSpec(
                            intent=FileEffectIntent(action=file_action, path=path),
                            occurrence_times=(occurrence_time,),
                            instance_key="semantic-command-file",
                            state_disposition=(
                                EndpointStateDisposition.DURABLE_FINAL
                                if mutates
                                else EndpointStateDisposition.NONE
                            ),
                            retention_deadline=(
                                max(
                                    endpoint_window_end,
                                    occurrence_time + timedelta(microseconds=1),
                                )
                                if mutates
                                else None
                            ),
                        ),
                        event_type=_FILE_ACTION_EVENT_TYPES[action],
                        payload=PreparedFileEffectPayload(path=path, action=file_action),
                    )
                )
        if (
            not request.suppress_command_file_effect
            and semantic_file_effect is None
            and rng.random() < 0.40
        ):
            from evidenceforge.generation.activity.edr_pools import select_file_side_effect

            side_effect = select_file_side_effect(
                process_name=process_name,
                command_line=command_line,
                os_category=os_category,
                rng=rng,
                user=process_username,
            )
            if side_effect is not None:
                action, path = side_effect
                file_action = FileEffectAction(action)
                occurrence_time = max(
                    actor.started_at + timedelta(milliseconds=rng.randint(110, 650)),
                    source_ready_floor + timedelta(milliseconds=2),
                )
                mutates = file_action in {FileEffectAction.CREATE, FileEffectAction.MODIFY}
                planned.append(
                    PreparedEndpointEffect(
                        spec=EndpointEffectSpec(
                            intent=FileEffectIntent(action=file_action, path=path),
                            occurrence_times=(occurrence_time,),
                            instance_key="ambient-process-file",
                            requirement=EffectRequirement.OPTIONAL,
                            state_disposition=(
                                EndpointStateDisposition.DURABLE_FINAL
                                if mutates
                                else EndpointStateDisposition.NONE
                            ),
                            retention_deadline=(
                                max(
                                    endpoint_window_end,
                                    occurrence_time + timedelta(microseconds=1),
                                )
                                if mutates
                                else None
                            ),
                        ),
                        event_type=_FILE_ACTION_EVENT_TYPES[action],
                        payload=PreparedFileEffectPayload(path=path, action=file_action),
                    )
                )

        runtime_image_load: ProcessRuntimeImageLoadPlan | None = None
        if os_category == "windows" and rng.random() < 0.30:
            from evidenceforge.generation.activity.dll_load_profiles import (
                get_runtime_dlls_for_process,
            )

            dll_profiles = get_runtime_dlls_for_process(exe_lower)
            dll_profile = rng.choice(dll_profiles) if dll_profiles else {}
            dll_path = str(dll_profile.get("path", ""))
            module_time = max(
                actor.started_at + timedelta(milliseconds=rng.randint(120, 1500)),
                source_ready_floor + timedelta(milliseconds=2),
            )
            if dll_path and module_time < endpoint_window_end:
                runtime_image_load = ProcessRuntimeImageLoadPlan(
                    timestamp=module_time,
                    path=dll_path,
                    signed=bool(dll_profile.get("signed", True)),
                    signature=str(dll_profile.get("signature", "Microsoft Windows")),
                    signature_status=str(dll_profile.get("signature_status", "Valid")),
                )

        registry_writers = {
            "svchost.exe",
            "services.exe",
            "explorer.exe",
            "powershell.exe",
            "rundll32.exe",
            "msiexec.exe",
            "reg.exe",
            "regedit.exe",
            "taskhostw.exe",
            "usoclient.exe",
            "dllhost.exe",
            "tiworker.exe",
            "trustedinstaller.exe",
            "mpcmdrun.exe",
            "msmpeng.exe",
            "winword.exe",
            "excel.exe",
            "powerpnt.exe",
            "outlook.exe",
        }
        storyline_registry_writers = {"reg.exe", "regedit.exe", "msiexec.exe"}
        if (
            os_category == "windows"
            and exe_lower in registry_writers
            and (not request.from_storyline or exe_lower in storyline_registry_writers)
            and rng.random() < 0.50
        ):
            from evidenceforge.generation.activity.edr_pools import (
                get_registry_keys_hkcu,
                get_registry_keys_hklm,
                materialize_registry_effect,
                registry_entries_for_process,
            )

            hklm_writers = {
                "svchost.exe",
                "services.exe",
                "reg.exe",
                "regedit.exe",
                "msiexec.exe",
            }
            count = rng.choices([1, 2, 3], weights=[50, 35, 15], k=1)[0]
            pool_hkcu = registry_entries_for_process(get_registry_keys_hkcu(), process_name)
            pool_hklm = registry_entries_for_process(get_registry_keys_hklm(), process_name)
            for registry_index in range(count):
                if process_username in _SYSTEM_ACCOUNTS:
                    eligible_registry = pool_hklm
                elif exe_lower in hklm_writers:
                    eligible_registry = pool_hklm + pool_hkcu
                else:
                    eligible_registry = pool_hkcu
                if not eligible_registry:
                    continue
                key, value_name, details = rng.choice(eligible_registry)
                registry_time = max(
                    actor.started_at + timedelta(milliseconds=rng.randint(120, 950)),
                    source_ready_floor + timedelta(milliseconds=3 + registry_index),
                )
                key, value_name, details, value_type = materialize_registry_effect(
                    (key, value_name, details),
                    rng,
                    request.user.username if request.user else "SYSTEM",
                    registry_time,
                    host_key=request.system.hostname,
                    host_ip=request.system.ip,
                    host_os=request.system.os,
                    deployment_registry=getattr(self.dispatcher, "deployment_registry", None),
                )
                planned.append(
                    PreparedEndpointEffect(
                        spec=EndpointEffectSpec(
                            intent=RegistryEffectIntent(
                                action=RegistryEffectAction.MODIFY,
                                key=key,
                                value_name=value_name,
                            ),
                            occurrence_times=(registry_time,),
                            instance_key=f"ambient-registry-{registry_index}",
                            requirement=EffectRequirement.OPTIONAL,
                            state_disposition=EndpointStateDisposition.DURABLE_FINAL,
                            retention_deadline=max(
                                endpoint_window_end,
                                registry_time + timedelta(microseconds=1),
                            ),
                        ),
                        event_type="registry_modify",
                        payload=PreparedRegistryEffectPayload(
                            key=key,
                            value_name=value_name,
                            value=details,
                            value_type=value_type,
                            action=RegistryEffectAction.MODIFY,
                        ),
                    )
                )

        allocation_free_endpoint = (
            PreparedProcessEndpointEffectPlan(
                root_anchor=anchor,
                actor=actor,
                window_end=endpoint_window_end,
                retention_horizon_end=endpoint_window_end,
                effects=tuple(planned),
            )
            if planned
            else None
        )
        if allocation_free_endpoint is not None:
            root_effect_plan = request.effect_plan or self._plan_process_execution_effects(
                request,
                anchor,
            )
            self._process_endpoint_uses_action_cohort(
                actor=actor,
                admitted_effects=allocation_free_endpoint.admitted_effects,
                effect_plan=root_effect_plan,
            )

        runtime_content_manager = self._runtime_content_manager
        deployment_registry = getattr(self.dispatcher, "deployment_registry", None)
        host_deployment = (
            deployment_registry.host_deployment(request.system.hostname)
            if isinstance(deployment_registry, DeploymentContentRegistry)
            else None
        )
        effective_architecture: Architecture | None = request.system.architecture or (
            host_deployment.architecture if host_deployment is not None else None
        )
        newly_reserved: list[LocalArtifactPublishToken] = []
        if runtime_content_manager is not None:
            platform = cast(Platform, os_category)
            prepared_file_effects: list[PreparedEndpointEffect] = []
            try:
                for effect in planned:
                    payload = effect.payload
                    if (
                        not isinstance(payload, PreparedFileEffectPayload)
                        or payload.artifact_publication is not None
                    ):
                        prepared_file_effects.append(effect)
                        continue
                    same_as_actor_image = canonical_native_path(
                        payload.path,
                        platform,
                    ) == canonical_native_path(actor.image, platform)
                    executable = same_as_actor_image and effective_architecture is not None
                    publication = runtime_content_manager.prepare_effect_publication(
                        root_action_id=anchor.action_id,
                        stable_source_id=(
                            f"{anchor.action_id}:{effect.spec.instance_key}:"
                            f"{effect.spec.intent.semantic_key}"
                        ),
                        hostname=request.system.hostname,
                        principal=actor.username,
                        platform=platform,
                        architecture=effective_architecture,
                        native_path=payload.path,
                        action=payload.action.value,
                        observed_at=effect.spec.occurrence_times[0],
                        owner_kind=_runtime_artifact_owner_kind(
                            platform,
                            actor.username,
                            actor.logon_id,
                        ),
                        deployment_registry=deployment_registry,
                        actor_image=actor.image,
                        executable=executable,
                    )
                    if publication is not None:
                        newly_reserved.append(publication)
                    prepared_file_effects.append(
                        replace(
                            effect,
                            payload=replace(payload, artifact_publication=publication),
                        )
                    )
            except RuntimeContentOwnerError as exc:
                for publication in newly_reserved:
                    runtime_content_manager.registry.cancel_prepared(publication)
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                    "prepared process runtime-content owner is inadmissible: "
                    f"host={request.system.hostname!r} principal={actor.username!r} "
                    f"image={actor.image!r}: {exc}",
                ) from exc
            except (ExecutionEffectPlanError, StateError, ValueError):
                for publication in newly_reserved:
                    runtime_content_manager.registry.cancel_prepared(publication)
                raise
            planned = prepared_file_effects

        try:
            endpoint = (
                replace(
                    allocation_free_endpoint,
                    effects=tuple(planned),
                )
                if allocation_free_endpoint is not None
                else None
            )
            provisional_termination = self._plan_process_provisional_termination(
                request,
                actor,
            )
            endpoint_close_floor: datetime | None = None
            if (
                provisional_termination is not None
                and endpoint is not None
                and endpoint.latest_admitted_occurrence is not None
            ):
                endpoint_close_floor = endpoint.latest_admitted_occurrence + timedelta(
                    milliseconds=25
                )
                provisional_termination = max(provisional_termination, endpoint_close_floor)
            if actor.session_deadline is not None and provisional_termination is not None:
                close_ceiling = actor.session_deadline - timedelta(milliseconds=25)
                if endpoint_close_floor is not None and endpoint_close_floor > close_ceiling:
                    raise ExecutionEffectPlanError(
                        ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                        "prepared endpoint effects leave no interval for the process lifecycle close",
                    )
                if provisional_termination > close_ceiling:
                    provisional_termination = close_ceiling
                if provisional_termination <= actor.started_at:
                    raise ExecutionEffectPlanError(
                        ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                        "prepared process actor leaves no interval for its lifecycle close",
                    )

            root_binary_publication: LocalArtifactPublishToken | None = None
            if runtime_content_manager is not None:
                platform = cast(Platform, os_category)
                endpoint_has_binary = bool(
                    endpoint is not None
                    and any(
                        isinstance(effect.payload, PreparedFileEffectPayload)
                        and effect.payload.artifact_publication is not None
                        and effect.payload.artifact_publication.record.binary is not None
                        and canonical_native_path(
                            effect.payload.artifact_publication.record.artifact.native_path,
                            platform,
                        )
                        == canonical_native_path(actor.image, platform)
                        for effect in endpoint.admitted_effects
                    )
                )
                resolved_binary = self.dispatcher.resolve_process_binary_identity(
                    request.system.hostname,
                    actor.username,
                    actor.image,
                    platform,
                )
                if not endpoint_has_binary and isinstance(
                    resolved_binary,
                    UnresolvedBinaryIdentity,
                ):
                    if effective_architecture is None:
                        raise ExecutionEffectPlanError(
                            ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                            "unresolved process executable requires exact host architecture",
                        )
                    root_binary_publication = runtime_content_manager.prepare_effect_publication(
                        root_action_id=anchor.action_id,
                        stable_source_id=f"{anchor.action_id}:root-process-image",
                        hostname=request.system.hostname,
                        principal=actor.username,
                        platform=platform,
                        architecture=effective_architecture,
                        native_path=actor.image,
                        action="create",
                        observed_at=actor.started_at,
                        owner_kind=_runtime_artifact_owner_kind(
                            platform,
                            actor.username,
                            actor.logon_id,
                        ),
                        deployment_registry=deployment_registry,
                        actor_image=actor.image,
                        executable=True,
                    )
                    if root_binary_publication is None:
                        raise ExecutionEffectPlanError(
                            ExecutionEffectPlanErrorCode.INVALID_PLAN,
                            "unresolved process executable did not prepare a binary publication",
                        )
                    newly_reserved.append(root_binary_publication)

            return ProcessExecutionPreparedEffects(
                root_anchor=anchor,
                actor=actor,
                endpoint=endpoint,
                runtime_image_load=runtime_image_load,
                provisional_termination=provisional_termination,
                root_binary_publication=root_binary_publication,
            )
        except RuntimeContentOwnerError as exc:
            if runtime_content_manager is not None:
                for publication in newly_reserved:
                    runtime_content_manager.registry.cancel_prepared(publication)
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "prepared process runtime-content owner is inadmissible: "
                f"host={request.system.hostname!r} principal={actor.username!r} "
                f"image={actor.image!r}: {exc}",
            ) from exc
        except (ExecutionEffectPlanError, StateError, ValueError):
            if runtime_content_manager is not None:
                for publication in newly_reserved:
                    runtime_content_manager.registry.cancel_prepared(publication)
            raise

    @staticmethod
    def _process_endpoint_effect_rng(
        request: ProcessExecutionRequest,
        actor: PreparedProcessEffectActor,
    ) -> random.Random:
        """Return the worker/order-stable RNG for one process endpoint preflight."""

        return random.Random(
            _stable_seed(f"process_endpoint_preflight:{request.stable_id}:{actor.stable_id}")
        )

    def _plan_process_provisional_termination(
        self,
        request: ProcessExecutionRequest,
        actor: "PreparedProcessEffectActor",
    ) -> datetime | None:
        """Freeze a Linux foreground close time before allocating its PID or state."""

        if _get_os_category(
            request.system.os
        ) != "linux" or not _linux_shell_process_reserves_foreground(
            actor.image, actor.command_line
        ):
            return None
        actor_exe = actor.image.rsplit("/", 1)[-1].lower()
        if actor_exe in {"bash", "sh", "zsh"} and actor.command_line.strip() == f"-{actor_exe}":
            return None
        parent_owns_foreground = (
            self._foreground_shell_key(
                system=request.system,
                username=actor.username,
                logon_id=actor.logon_id,
                parent_pid=request.parent_pid,
            )
            is not None
        )
        if not parent_owns_foreground:
            session = self.state_manager.get_session(actor.logon_id)
            if (
                request.lifecycle_group_id
                and session is not None
                and request.lifecycle_group_id == session.lifecycle_group_id
            ):
                # Explicit session-bootstrap members are closed by their exact
                # session owner, which preserves the descendant-first graph.
                return None
            parent_owns_foreground = bool(
                actor.logon_id
                and session is not None
                and session.system.casefold() == request.system.hostname.casefold()
            )
        if not parent_owns_foreground:
            return None
        lifetime = _linux_foreground_lifetime(actor.image, actor.command_line)
        if lifetime is None:
            return None
        minimum_seconds, maximum_seconds = lifetime
        median_seconds = minimum_seconds + (maximum_seconds - minimum_seconds) * 0.34
        return self.timing_runtime.sampler.after(
            actor.started_at,
            TruncatedLognormalDistribution(
                median=median_seconds * 1_000_000,
                sigma=0.78,
                minimum=minimum_seconds * 1_000_000,
                maximum=maximum_seconds * 1_000_000,
            ),
            relationship_key="activity.process.linux_foreground_lifetime",
            scope=TimingScope(
                stable_id=request.stable_id,
                host=request.system.hostname,
                source="endpoint_process",
                lifecycle_id=actor.lifecycle_id,
            ),
            sample_key="provisional_close",
        )

    def _prepare_process_effect_actor(
        self,
        request: ProcessExecutionRequest,
    ) -> "PreparedProcessEffectActor":
        """Resolve the root actor and start fence without mutating runtime state."""

        system = request.system
        process_name = request.process_name
        command_line = request.command_line
        if _get_os_category(system.os) == "windows":
            process_name, command_line = _windows_script_host_process(
                process_name,
                command_line,
            )
        exe_lower = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if _get_os_category(system.os) == "windows" and exe_lower == "psexesvc.exe":
            process_name = r"C:\Windows\PSEXESVC.exe"
            if "accepteula" in command_line.lower():
                command_line = r"C:\Windows\PSEXESVC.exe"
        process_name = normalize_defender_platform_path(process_name, system.hostname)

        started_at = ensure_utc(request.time)
        process_username, process_logon_id = self._resolve_process_identity(
            system=system,
            username=request.user.username,
            logon_id=request.logon_id,
            process_name=process_name,
            time=started_at,
        )
        service_account = _windows_service_process_account(process_name, command_line)
        if _get_os_category(system.os) == "windows" and service_account is not None:
            process_username = service_account
            process_logon_id = _SYSTEM_ACCOUNT_LOGON_IDS[service_account]
        if (
            _get_os_category(system.os) == "linux"
            and process_logon_id
            and (session_end := self.state_manager.get_session_end_time(process_logon_id))
            is not None
            and started_at >= ensure_utc(session_end)
            and self._linux_process_is_system_background_helper(process_name, command_line)
        ):
            process_username = self._linux_background_helper_username(process_name, command_line)
            process_logon_id = "0x3e7"

        session = self.state_manager.get_session(process_logon_id)
        session_end_plan = self.state_manager.get_session_end_plan(process_logon_id)
        session_deadline = self.state_manager.get_session_end_time(process_logon_id)
        if (
            session is not None
            and session.session_kind.casefold() == "ssh"
            and session.network_close_time is not None
        ):
            network_close_deadline = ensure_utc(session.network_close_time)
            session_deadline = (
                network_close_deadline
                if session_deadline is None
                else min(ensure_utc(session_deadline), network_close_deadline)
            )
        if session_end_plan is not None and session_end_plan.is_hard_deadline:
            planned_deadline = ensure_utc(session_end_plan.canonical_end)
            session_deadline = (
                planned_deadline
                if session_deadline is None
                else min(ensure_utc(session_deadline), planned_deadline)
            )
        if (
            session_end_plan is not None
            and session_end_plan.is_hard_deadline
            and started_at >= ensure_utc(session_end_plan.canonical_end)
        ):
            deadline = ensure_utc(session_end_plan.canonical_end)
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "prepared process actor begins at or after its authoritative session end: "
                f"host={system.hostname} logon_id={process_logon_id} image={process_name!r} "
                f"started_at={started_at.isoformat()} deadline={deadline.isoformat()}",
            )
        if session_deadline is not None and started_at >= ensure_utc(session_deadline):
            deadline = ensure_utc(session_deadline)
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "prepared process actor begins at or after its session deadline: "
                f"host={system.hostname} logon_id={process_logon_id} image={process_name!r} "
                f"started_at={started_at.isoformat()} deadline={deadline.isoformat()}",
            )
        if session is not None and started_at <= ensure_utc(session.start_time):
            offset_ms = 100 + (
                _stable_seed(
                    f"process_after_logon:{system.hostname}:{process_logon_id}:{process_name}"
                )
                % 1400
            )
            started_at = ensure_utc(session.start_time) + timedelta(milliseconds=offset_ms)
        parent = self.state_manager.get_process(system.hostname, request.parent_pid)
        if parent is not None and started_at <= ensure_utc(parent.start_time):
            offset_ms = 50 + (
                _stable_seed(
                    f"process_after_parent:{system.hostname}:{request.parent_pid}:{process_name}:"
                    f"{command_line}"
                )
                % 450
            )
            started_at = ensure_utc(parent.start_time) + timedelta(milliseconds=offset_ms)

        if not request.from_storyline and request.source_visible_by is None:
            started_at = self._preview_one_shot_cli_launch(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                time=started_at,
            )
            if request.allow_browser_launch_spacing:
                started_at = self._preview_browser_launch(
                    system=system,
                    username=process_username,
                    logon_id=process_logon_id,
                    process_name=process_name,
                    command_line=command_line,
                    time=started_at,
                )
        if (
            _get_os_category(system.os) == "linux"
            and request.source_visible_by is None
            and _linux_shell_process_reserves_foreground(process_name, command_line)
            and _linux_foreground_lifetime(process_name, command_line) is not None
        ):
            started_at = self._reserve_foreground_shell_time(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                parent_pid=request.parent_pid,
                requested_time=started_at,
                seed_text=command_line,
                concurrency_group_id=request.concurrency_group_id,
            )
        if not request.from_storyline and request.source_visible_by is None:
            started_at = self._space_interactive_shell_child_launch(
                system=system,
                process_name=process_name,
                parent_pid=request.parent_pid,
                time=started_at,
            )
        effective_deadline = ensure_utc(session_deadline) if session_deadline is not None else None
        if effective_deadline is not None and started_at >= effective_deadline:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "prepared process actor leaves no session interval after launch spacing: "
                f"host={system.hostname} logon_id={process_logon_id} image={process_name!r} "
                f"started_at={started_at.isoformat()} deadline={effective_deadline.isoformat()}",
            )
        return PreparedProcessEffectActor(
            hostname=system.hostname,
            image=process_name,
            command_line=command_line,
            username=process_username,
            logon_id=process_logon_id,
            lifecycle_id=request.lifecycle_group_id or request.stable_id,
            started_at=started_at,
            session_deadline=effective_deadline,
        )

    def _preview_one_shot_cli_launch(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
    ) -> datetime:
        """Return one-shot spacing without updating compatibility caches."""

        if _get_os_category(system.os) != "windows":
            return time
        exe_name = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name not in _WINDOWS_ONE_SHOT_CLI_EXES:
            return time
        normalized_command = " ".join(command_line.lower().split())
        exe_key = (system.hostname, username, logon_id, exe_name)
        command_key = (*exe_key, normalized_command)
        adjusted = time
        command_last = self._last_one_shot_cli_launch_by_command.get(command_key)
        if command_last is not None:
            gap = self._sample_process_spacing_gap(
                relationship_key="activity.process.one_shot_same_command_gap",
                stable_id=(
                    f"{system.hostname}:{username}:{logon_id}:{exe_name}:"
                    f"{normalized_command}:{command_last.isoformat()}"
                ),
                system=system,
                logon_id=logon_id,
                minimum_seconds=18.0,
                mode_seconds=32.0,
                maximum_seconds=75.0,
            )
            adjusted = max(adjusted, command_last + gap)
        exe_last = self._last_one_shot_cli_launch_by_exe.get(exe_key)
        if exe_last is not None:
            gap = self._sample_process_spacing_gap(
                relationship_key="activity.process.one_shot_same_exe_gap",
                stable_id=(
                    f"{system.hostname}:{username}:{logon_id}:{exe_name}:{exe_last.isoformat()}"
                ),
                system=system,
                logon_id=logon_id,
                minimum_seconds=2.5,
                mode_seconds=4.2,
                maximum_seconds=9.0,
            )
            adjusted = max(adjusted, exe_last + gap)
        return adjusted

    def _preview_browser_launch(
        self,
        *,
        system: System,
        username: str,
        logon_id: str,
        process_name: str,
        command_line: str,
        time: datetime,
    ) -> datetime:
        """Return top-level browser spacing without updating compatibility caches."""

        if _get_os_category(system.os) != "windows" or not self._is_top_level_browser_launch(
            process_name,
            command_line,
        ):
            return time
        previous = self._last_browser_launch_by_session.get((system.hostname, username, logon_id))
        if previous is None:
            return time
        gap = self._sample_process_spacing_gap(
            relationship_key="activity.process.browser_launch_gap",
            stable_id=f"{system.hostname}:{username}:{logon_id}:{previous.isoformat()}",
            system=system,
            logon_id=logon_id,
            minimum_seconds=4.0,
            mode_seconds=7.5,
            maximum_seconds=18.0,
        )
        return max(time, previous + gap)

    def _resolve_existing_prepared_process_parent(
        self,
        *,
        system: System,
        user: User,
        time: datetime,
        logon_id: str,
        parent_pid: int,
        process_username: str,
    ) -> int:
        """Resolve an existing parent for a required bundle without materializing helpers."""

        os_category = _get_os_category(system.os)
        if parent_pid not in {0, 4}:
            if (
                os_category == "windows"
                and self._is_valid_process_parent_at(
                    system=system,
                    parent_pid=parent_pid,
                    time=time,
                )
                and self._parent_process_matches_logon(
                    hostname=system.hostname,
                    parent_pid=parent_pid,
                    logon_id=logon_id,
                    os_category=os_category,
                )
            ):
                return parent_pid
            if os_category == "linux" and self._linux_parent_usable_for_child_at(
                system=system,
                parent_pid=parent_pid,
                time=time,
                logon_id=logon_id,
            ):
                return parent_pid

        system_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        if os_category == "windows":
            user_context = (
                process_username not in _SYSTEM_ACCOUNTS and not process_username.endswith("$")
            )
            if user_context:
                explorer_pid = self._get_session_explorer_pid(
                    system,
                    user,
                    time=time,
                    logon_id=logon_id,
                )
                if explorer_pid is not None:
                    return explorer_pid
            for role in ("explorer", "winlogon", "services", "svchost_dcom", "wininit"):
                candidate = system_pids.get(role)
                if (
                    candidate is not None
                    and self._is_valid_process_parent_at(
                        system=system,
                        parent_pid=candidate,
                        time=time,
                    )
                    and self._parent_process_matches_logon(
                        hostname=system.hostname,
                        parent_pid=candidate,
                        logon_id=logon_id,
                        os_category=os_category,
                    )
                ):
                    return candidate
            return 4

        session_shell = self._active_session_shell_pid(system, user, time, logon_id)
        if session_shell is not None:
            return session_shell
        for role in ("bash", "sshd", "systemd", "init"):
            candidate = system_pids.get(role)
            if candidate is not None and self._linux_parent_usable_for_child_at(
                system=system,
                parent_pid=candidate,
                time=time,
                logon_id=logon_id,
            ):
                return candidate
        return 0

    def _execute_bounded_process_reuse(
        self,
        *,
        request: ProcessExecutionRequest,
        actor: PreparedProcessEffectActor,
    ) -> int:
        """Revalidate one immutable bounded reuse token before activity mutation."""

        intent = request.reuse_intent
        deadline = request.source_visible_by
        if intent is None or deadline is None:
            return 0
        identity = self.state_manager.get_process_identity(intent.hostname, intent.pid)
        running = self.state_manager.get_process(intent.hostname, intent.pid)
        source_frontier = self.process_source_create_time(intent.hostname, intent.pid)
        if (
            identity is None
            or running is None
            or identity.object_id != intent.process_object_id
            or running.parent_pid != intent.parent_pid
            or running.image != intent.image
            or running.command_line != intent.command_line
            or running.username != intent.username
            or running.logon_id != intent.logon_id
            or ensure_utc(running.start_time) != intent.started_at
            or source_frontier != intent.source_frontier
            or source_frontier > ensure_utc(deadline)
            or actor.hostname != intent.hostname
            or actor.image != intent.image
            or actor.username != intent.username
            or actor.logon_id != intent.logon_id
            or not self._is_pid_active_at(request.system, intent.pid, actor.started_at)
        ):
            return 0
        reuse_found, authenticated = self._bounded_process_reuse_intent(
            request=replace(request, reuse_intent=None),
            actor=actor,
        )
        if not reuse_found or authenticated != intent:
            return 0
        self._record_reused_process_optional_effects(request.prepared_effects)
        self.state_manager.update_process_activity_time(
            intent.hostname,
            intent.pid,
            actor.started_at,
        )
        return intent.pid

    def _execute_process_create_bundle(self, request: ProcessExecutionRequest) -> int:
        """Expand a process-execution bundle through the compatibility adapter."""
        from evidenceforge.events.contexts import ProcessContext

        prepared_effects = request.prepared_effects
        prepared_endpoint = prepared_effects.endpoint if prepared_effects is not None else None
        prepared_actor = prepared_effects.actor if prepared_effects is not None else None
        # Scanner transports still publish through the established post-process network path.
        # Keep their process/dependent rows on that same legacy boundary until one bounded
        # scanner transport collector can admit the complete probe group atomically.
        if prepared_endpoint is not None and prepared_actor is None:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "prepared process endpoint effects lost their allocation-free actor",
            )
        uses_action_cohort = bool(
            prepared_endpoint is not None
            and prepared_actor is not None
            and self._process_endpoint_uses_action_cohort(
                actor=prepared_actor,
                admitted_effects=prepared_endpoint.admitted_effects,
                effect_plan=request.effect_plan,
            )
        )
        if uses_action_cohort:
            admitted_occurrence_count = sum(
                len(effect.spec.occurrence_times) for effect in prepared_endpoint.admitted_effects
            )
            if 1 + admitted_occurrence_count > _PROCESS_ENDPOINT_ACTION_COHORT_MEMBER_LIMIT:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "process endpoint action cohort exceeds its root/occurrence member limit",
                )
        prepared_requires_new_root = bool(
            prepared_effects is not None
            and (
                prepared_effects.process_binary_publication is not None
                or (
                    prepared_effects.endpoint is not None
                    and any(
                        spec.requirement != EffectRequirement.OPTIONAL
                        for spec in prepared_effects.endpoint.specs
                    )
                )
            )
        )
        if prepared_actor is not None:
            expected_actor = self._prepare_process_effect_actor(
                replace(request, prepared_effects=None)
            )
            if expected_actor != prepared_actor:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                    "prepared process actor drifted before root allocation",
                )

        user = request.user
        system = request.system
        time = prepared_actor.started_at if prepared_actor is not None else request.time
        logon_id = prepared_actor.logon_id if prepared_actor is not None else request.logon_id
        process_name = prepared_actor.image if prepared_actor is not None else request.process_name
        command_line = (
            prepared_actor.command_line if prepared_actor is not None else request.command_line
        )
        parent_pid = request.parent_pid
        from_storyline = request.from_storyline
        allow_existing_browser_reuse = request.allow_existing_browser_reuse
        allow_browser_launch_spacing = request.allow_browser_launch_spacing
        concurrency_group_id = request.concurrency_group_id
        source_visible_by = request.source_visible_by

        if request.reuse_intent is not None:
            return self._execute_bounded_process_reuse(
                request=request,
                actor=(
                    prepared_actor
                    if prepared_actor is not None
                    else self._prepare_process_effect_actor(request)
                ),
            )

        profiled_worker = matching_service_worker(
            os_category=_get_os_category(system.os),
            image=process_name,
            command_line=command_line,
            username=user.username,
        )
        if profiled_worker is not None:
            family_name, worker_name, _family = profiled_worker
            return self._ensure_profiled_service_worker(
                system=system,
                worker_time=time,
                activity_time=time,
                family_name=family_name,
                worker_name=worker_name,
                source_visible_by=source_visible_by,
            )

        session_end_plan = self.state_manager.get_session_end_plan(logon_id)
        if (
            session_end_plan is not None
            and session_end_plan.is_hard_deadline
            and ensure_utc(time) >= ensure_utc(session_end_plan.canonical_end)
        ):
            raise StateError(
                "Process activity cannot begin at or after its authoritative session end: "
                f"{system.hostname} logon_id={logon_id} time={ensure_utc(time).isoformat()}"
            )
        if _get_os_category(system.os) == "windows":
            process_name, command_line = _windows_script_host_process(
                process_name,
                command_line,
            )

        # Determine integrity level per UAC model:
        # - SYSTEM processes: "System" (handled in generate_system_process)
        # - Explicitly elevated (admin tools, installers): "High"
        # - Everything else (including admin users under UAC): "Medium"
        _HIGH_INTEGRITY_EXES = {
            "msiexec.exe",
            "regedit.exe",
            "mmc.exe",
            "dism.exe",
            "pkgmgr.exe",
            "setup.exe",
            "install.exe",
            "procdump64.exe",
            "procdump.exe",
            "mimikatz.exe",
            "psexec.exe",
            "psexesvc.exe",
        }
        _exe_lower = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if _get_os_category(system.os) == "windows" and _exe_lower == "psexesvc.exe":
            process_name = r"C:\Windows\PSEXESVC.exe"
            command_line = (
                r"C:\Windows\PSEXESVC.exe" if "accepteula" in command_line.lower() else command_line
            )
        process_name = normalize_defender_platform_path(process_name, system.hostname)
        if _exe_lower in _HIGH_INTEGRITY_EXES:
            _integrity = "High"
        elif _get_os_category(system.os) == "windows" and any(
            marker in command_line.lower()
            for marker in ("sekurlsa::", "privilege::debug", "lsadump::", "token::elevate")
        ):
            _integrity = "High"
        else:
            _integrity = "Medium"
            # Browser child processes (renderers) run at Low integrity.
            # ~65% of browser children are sandboxed renderers (Low),
            # ~35% are GPU/utility processes (Medium).
            _BROWSER_EXES = {"chrome.exe", "msedge.exe", "firefox.exe"}
            if _exe_lower in _BROWSER_EXES:
                _parent_image = (
                    self._lookup_process_name(
                        system.hostname, parent_pid, _get_os_category(system.os)
                    )
                    or ""
                )
                _parent_exe = _parent_image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
                if _parent_exe in _BROWSER_EXES:
                    rng = _get_rng()
                    _integrity = "Low" if rng.random() < 0.65 else "Medium"

        if prepared_actor is not None:
            process_username = prepared_actor.username
            process_logon_id = prepared_actor.logon_id
        else:
            process_username, process_logon_id = self._resolve_process_identity(
                system=system,
                username=user.username,
                logon_id=logon_id,
                process_name=process_name,
                time=time,
            )
        service_process_account = _windows_service_process_account(process_name, command_line)
        if (
            prepared_actor is None
            and _get_os_category(system.os) == "windows"
            and service_process_account is not None
        ):
            process_username = service_process_account
            process_logon_id = _SYSTEM_ACCOUNT_LOGON_IDS[service_process_account]
            _integrity = "System"
        if (
            prepared_actor is not None
            and _get_os_category(system.os) == "linux"
            and process_logon_id == "0x3e7"
            and request.logon_id != "0x3e7"
            and self._linux_process_is_system_background_helper(process_name, command_line)
        ):
            _integrity = "System"
            parent_pid = self._linux_system_parent_fallback(system, time)
        linux_session_end_time = (
            self.state_manager.get_session_end_time(process_logon_id)
            if _get_os_category(system.os) == "linux" and process_logon_id
            else None
        )
        if (
            prepared_actor is None
            and linux_session_end_time is not None
            and ensure_utc(time) >= ensure_utc(linux_session_end_time)
            and self._linux_process_is_system_background_helper(process_name, command_line)
        ):
            process_username = self._linux_background_helper_username(
                process_name,
                command_line,
            )
            process_logon_id = "0x3e7"
            _integrity = "System"
            parent_pid = self._linux_system_parent_fallback(system, time)
        if prepared_actor is not None and (
            process_name != prepared_actor.image
            or command_line != prepared_actor.command_line
            or process_username != prepared_actor.username
            or process_logon_id != prepared_actor.logon_id
        ):
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "resolved process identity drifted from its allocation-free prepared actor",
            )
        session_end_time = self.state_manager.get_session_end_time(process_logon_id)
        if (
            prepared_actor is None
            and session_end_time is not None
            and time >= session_end_time
            and process_logon_id not in _SYSTEM_ACCOUNT_LOGON_IDS.values()
        ):
            time = session_end_time - self._sample_profile_activity_gap(
                "windows.process_create_before_logoff",
                stable_id=request.stable_id,
                host=system.hostname,
                source="endpoint_process",
                lifecycle_id=process_logon_id,
                sample_key="before_logoff_gap",
            )
        session = self.state_manager.get_session(process_logon_id)
        process_logon_type = session.logon_type if session is not None else 2
        if prepared_actor is None and session is not None and time <= session.start_time:
            logon_gap = self._sample_activity_gap(
                relationship_key="activity.process.start_after_logon",
                stable_id=request.stable_id,
                minimum_ms=100,
                maximum_ms=1499,
                host=system.hostname,
                source="endpoint_process",
                lifecycle_id=process_logon_id,
                sample_key="after_logon_gap",
            )
            time = session.start_time + logon_gap
        explicit_parent = self.state_manager.get_process(system.hostname, parent_pid)
        if (
            prepared_actor is None
            and explicit_parent is not None
            and time <= explicit_parent.start_time
        ):
            parent_gap = self._sample_activity_gap(
                relationship_key="activity.process.start_after_parent",
                stable_id=request.stable_id,
                minimum_ms=50,
                maximum_ms=499,
                host=system.hostname,
                source="endpoint_process",
                lifecycle_id=process_logon_id,
                sample_key="after_parent_gap",
            )
            time = explicit_parent.start_time + parent_gap
        # A caller-supplied source deadline means this process owns an already
        # anchored causal occurrence (for example an SSH socket). Optional
        # human-spacing must not move the canonical start beyond that anchor.
        if prepared_actor is None and not from_storyline and source_visible_by is None:
            spaced_time = self._space_one_shot_cli_launch(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                time=time,
                source_visible_by=source_visible_by,
            )
            if spaced_time != time:
                time = spaced_time
            if allow_browser_launch_spacing:
                spaced_time = self._space_browser_launch(
                    system=system,
                    username=process_username,
                    logon_id=process_logon_id,
                    process_name=process_name,
                    command_line=command_line,
                    time=time,
                )
                if spaced_time != time:
                    time = spaced_time
        if (
            process_username != user.username
            and process_username not in _SYSTEM_ACCOUNTS
            and not (
                _get_os_category(system.os) == "linux"
                and process_logon_id == "0x3e7"
                and process_username in {"root", "www-data", "proxy", "postfix"}
            )
        ):
            _integrity = "Medium"
        if _get_os_category(system.os) == "windows" and process_logon_type == 5:
            _integrity = "High" if _integrity == "Medium" else _integrity
        if _get_os_category(system.os) == "windows":
            _integrity, _token_elevation, _mandatory_label = _windows_token_profile(
                process_username,
                _integrity,
            )
        else:
            _token_elevation = "%%1938"
            _mandatory_label = "S-1-16-8192"

        if (
            not prepared_requires_new_root
            and not from_storyline
            and source_visible_by is None
            and _get_os_category(system.os) == "windows"
            and _exe_lower == "explorer.exe"
            and process_logon_id not in _SYSTEM_ACCOUNT_LOGON_IDS.values()
        ):
            explorer_pid = self._ensure_session_explorer_pid(
                system,
                self._user_model_for_username(process_username),
                time,
                process_logon_id,
            )
            if explorer_pid is not None:
                self._record_reused_process_optional_effects(prepared_effects)
                self.state_manager.update_process_activity_time(
                    system.hostname,
                    explorer_pid,
                    time,
                )
                return explorer_pid

        singleton_pid = (
            self._existing_windows_singleton_pid(system, process_name, time)
            if not prepared_requires_new_root
            else None
        )
        if singleton_pid is not None:
            if not self._process_source_visible_by(
                hostname=system.hostname,
                pid=singleton_pid,
                deadline=source_visible_by,
            ):
                return 0
            self._record_reused_process_optional_effects(prepared_effects)
            self.state_manager.update_process_activity_time(
                system.hostname,
                singleton_pid,
                time,
            )
            return singleton_pid

        if (
            not prepared_requires_new_root
            and _get_os_category(system.os) == "windows"
            and explicit_parent is not None
            and ntpath.basename(explicit_parent.image).lower() == "services.exe"
        ):
            singleton_service_pid = self._existing_windows_singleton_service_pid(
                system=system,
                process_name=process_name,
                time=time,
                username=process_username,
                command_line=command_line,
            )
            if singleton_service_pid is not None:
                if not self._process_source_visible_by(
                    hostname=system.hostname,
                    pid=singleton_service_pid,
                    deadline=source_visible_by,
                ):
                    return 0
                self._record_reused_process_optional_effects(prepared_effects)
                running_proc = self.state_manager.get_process(
                    system.hostname, singleton_service_pid
                )
                if running_proc is not None:
                    self.state_manager.update_process_activity_time(
                        system.hostname,
                        singleton_service_pid,
                        time,
                    )
                return singleton_service_pid

        if not prepared_requires_new_root and not from_storyline:
            persistent_app_pid = self._existing_persistent_user_app_pid(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                time=time,
                source_visible_by=source_visible_by,
            )
            if persistent_app_pid is not None:
                if not self._process_source_visible_by(
                    hostname=system.hostname,
                    pid=persistent_app_pid,
                    deadline=source_visible_by,
                ):
                    return 0
                self._record_reused_process_optional_effects(prepared_effects)
                return persistent_app_pid

        if (
            not prepared_requires_new_root
            and not from_storyline
            and allow_existing_browser_reuse
            and source_visible_by is None
        ):
            browser_pid = self._existing_user_browser_pid(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                time=time,
                source_visible_by=source_visible_by,
            )
            if browser_pid is not None:
                if not self._process_source_visible_by(
                    hostname=system.hostname,
                    pid=browser_pid,
                    deadline=source_visible_by,
                ):
                    return 0
                self._record_reused_process_optional_effects(prepared_effects)
                return browser_pid

        if prepared_requires_new_root:
            parent_pid = self._resolve_existing_prepared_process_parent(
                system=system,
                user=user,
                time=time,
                logon_id=process_logon_id,
                parent_pid=parent_pid,
                process_username=process_username,
            )
        else:
            parent_pid = self._sanitize_user_parent_pid(
                system=system,
                user=user,
                time=time,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                parent_pid=parent_pid,
                process_username=process_username,
            )
            parent_pid = self._materialize_visible_linux_shell_parent_for_child(
                system=system,
                time=time,
                logon_id=process_logon_id,
                parent_pid=parent_pid,
                process_username=process_username,
            )
            parent_pid = self._repair_process_parent_pid(
                system=system,
                time=time,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                parent_pid=parent_pid,
                process_username=process_username,
            )
        repaired_parent = self.state_manager.get_process(system.hostname, parent_pid)
        if (
            prepared_actor is None
            and repaired_parent is not None
            and time <= repaired_parent.start_time
        ):
            time = repaired_parent.start_time + timedelta(milliseconds=50)
        if (
            prepared_actor is None
            and _get_os_category(system.os) == "linux"
            and source_visible_by is None
            and _linux_shell_process_reserves_foreground(process_name, command_line)
            and _linux_foreground_lifetime(process_name, command_line) is not None
        ):
            time = self._reserve_foreground_shell_time(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                parent_pid=parent_pid,
                requested_time=ensure_utc(time),
                seed_text=command_line,
                concurrency_group_id=concurrency_group_id,
            )
            if (
                session_end_plan is not None
                and session_end_plan.is_hard_deadline
                and time >= ensure_utc(session_end_plan.canonical_end)
            ):
                raise StateError(
                    "Foreground process cannot begin after its owning shell session ends: "
                    f"{system.hostname} logon_id={process_logon_id} "
                    f"time={time.isoformat()}"
                )
        if not from_storyline:
            if source_visible_by is None:
                if prepared_actor is None:
                    spaced_time = self._space_interactive_shell_child_launch(
                        system=system,
                        process_name=process_name,
                        parent_pid=parent_pid,
                        time=time,
                    )
                    if spaced_time != time:
                        time = spaced_time

        # Drain independently committed due closes before freezing the root State and
        # source-timing fences. Running this after a timing overlay is sealed or claimed
        # would either stale that overlay or re-enter its locked canonical indexes.
        self._finalize_due_process_lifetimes(time, exhaust=False)

        # Phase 1: Freeze the exact PID/thread identity without consuming any allocator.
        process_name = normalize_defender_platform_path(process_name, system.hostname)
        process_session_id = self._session_id_for_logon(process_logon_id)
        process_session_identity = self.state_manager.get_session_identity(process_logon_id)
        action_cohort_builder = (
            self.state_manager.begin_action_cohort_materialization() if uses_action_cohort else None
        )
        if action_cohort_builder is not None:
            process_plan = action_cohort_builder.plan_process(
                system=system.hostname,
                parent_pid=parent_pid,
                image=process_name,
                command_line=command_line,
                username=process_username,
                integrity_level=_integrity,
                logon_id=process_logon_id,
                lifecycle_group_id=request.lifecycle_group_id or request.stable_id,
                concurrency_group_id=concurrency_group_id,
                os_category=_get_os_category(system.os),
                start_time=ensure_utc(time),
                parent_activity_time=(ensure_utc(time) if parent_pid not in {0, 4} else None),
                auth_session_id=process_session_id,
                auth_logon_type=process_logon_type,
            )
            endpoint_activity_frontier = max(
                ensure_utc(time),
                prepared_endpoint.latest_admitted_occurrence or ensure_utc(time),
            )
            action_cohort_builder.patch_process_activity(
                process_plan,
                endpoint_activity_frontier,
            )
            live_session = self.state_manager.get_session(process_logon_id)
            if live_session is not None and process_session_identity is not None:
                action_cohort_builder.patch_session_activity(
                    process_session_identity,
                    endpoint_activity_frontier,
                )
            action_cohort_state_plan = action_cohort_builder.seal()
        else:
            process_plan = self.state_manager.plan_process_materialization(
                system=system.hostname,
                parent_pid=parent_pid,
                image=process_name,
                command_line=command_line,
                username=process_username,
                integrity_level=_integrity,
                logon_id=process_logon_id,
                lifecycle_group_id=request.lifecycle_group_id or request.stable_id,
                concurrency_group_id=concurrency_group_id,
                os_category=_get_os_category(system.os),
                start_time=ensure_utc(time),
                parent_activity_time=ensure_utc(time),
            )
            action_cohort_state_plan = None
        process_identity = process_plan.identity
        pid = process_identity.pid
        parent_identity = self.state_manager.get_process_identity(
            system.hostname,
            process_identity.parent_pid,
        )

        # Phase 2: Build and validate the complete root/dependent publication batch.
        provisional_process_termination = (
            prepared_effects.provisional_termination if prepared_effects is not None else None
        )
        if (
            not uses_action_cohort
            and provisional_process_termination is None
            and _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(process_name, command_line)
            and self._foreground_shell_key(
                system=system,
                username=process_identity.principal,
                logon_id=process_identity.logon_id,
                parent_pid=process_identity.parent_pid,
            )
            is not None
        ):
            provisional_lifetime = _linux_foreground_lifetime(process_name, command_line)
            if provisional_lifetime is not None:
                provisional_rng = random.Random(
                    _stable_seed(
                        "canonical-linux-foreground-lifetime:"
                        f"{system.hostname}:{pid}:{process_identity.started_at.isoformat()}:"
                        f"{command_line}"
                    )
                )
                provisional_process_termination = ensure_utc(
                    process_identity.started_at
                ) + timedelta(seconds=provisional_rng.uniform(*provisional_lifetime))
                session_deadline = self.state_manager.get_session_end_time(
                    process_identity.logon_id
                )
                if session_deadline is not None:
                    provisional_process_termination = min(
                        provisional_process_termination,
                        ensure_utc(session_deadline) - timedelta(milliseconds=25),
                    )
                provisional_process_termination = max(
                    provisional_process_termination,
                    ensure_utc(process_identity.started_at) + timedelta(milliseconds=25),
                )
        if (
            uses_action_cohort
            and provisional_process_termination is None
            and _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(process_name, command_line)
            and self._foreground_shell_key(
                system=system,
                username=process_identity.principal,
                logon_id=process_identity.logon_id,
                parent_pid=process_identity.parent_pid,
            )
            is not None
        ):
            provisional_lifetime = _linux_foreground_lifetime(process_name, command_line)
            if provisional_lifetime is not None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "Linux foreground process reached allocation without a frozen close time",
                )
        process_binary_publication = (
            prepared_effects.process_binary_publication if prepared_effects is not None else None
        )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="process_create",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=process_username,
                user_sid=self._get_sid(process_username),
                logon_id=process_logon_id,
                session_id=process_session_id,
                logon_type=process_logon_type,
                elevated=_integrity in {"High", "System"},
            ),
            process=ProcessContext(
                pid=pid,
                parent_pid=parent_pid,
                image=process_name,
                command_line=command_line,
                username=process_username,
                integrity_level=_integrity,
                logon_id=process_logon_id,
                parent_image=self._lookup_process_name(
                    system.hostname, parent_pid, _get_os_category(system.os)
                ),
                parent_command_line=self._lookup_parent_command_line(system.hostname, parent_pid),
                parent_start_time=self._lookup_parent_start_time(system.hostname, parent_pid),
                token_elevation=_token_elevation,
                mandatory_label=_mandatory_label,
                start_time=process_identity.started_at,
                current_directory=self._derive_current_directory(
                    system=system,
                    username=process_username,
                    process_name=process_name,
                    command_line=command_line,
                    parent_pid=parent_pid,
                    logon_type=process_logon_type,
                ),
                concurrency_group_id=concurrency_group_id,
                binary_identity=(
                    process_binary_publication.record.binary
                    if process_binary_publication is not None
                    else None
                ),
            ),
            storyline_origin=from_storyline,
            identity_plan=EventIdentityPlan(
                subject=process_identity,
                actor=parent_identity,
                session=(
                    process_session_identity if action_cohort_state_plan is not None else None
                ),
            ),
            lifecycle=ActionLifecycleContext(
                group_id=process_identity.lifecycle_group_id,
                canonical_start=process_identity.started_at,
                phase="start",
                parent_group_id=process_identity.parent_lifecycle_group_id or None,
            ),
        )

        endpoint_source_deadline = (
            prepared_endpoint.earliest_admitted_occurrence - timedelta(microseconds=1)
            if prepared_endpoint is not None
            and prepared_endpoint.earliest_admitted_occurrence is not None
            else None
        )
        effective_source_visible_by = (
            min(
                value
                for value in (source_visible_by, endpoint_source_deadline)
                if value is not None
            )
            if source_visible_by is not None or endpoint_source_deadline is not None
            else None
        )
        if (
            provisional_process_termination is not None
            and prepared_endpoint is not None
            and prepared_endpoint.latest_admitted_occurrence is not None
        ):
            provisional_process_termination = max(
                provisional_process_termination,
                prepared_endpoint.latest_admitted_occurrence + timedelta(milliseconds=25),
            )

        def dependent_artifact_publications(
            publication: LocalArtifactPublishToken | None,
        ) -> tuple[LocalArtifactPublishToken, ...]:
            """Bind the root binary plus a distinct dependent file publication."""

            publications: list[LocalArtifactPublishToken] = []
            if process_binary_publication is not None:
                publications.append(process_binary_publication)
            if publication is not None and publication is not process_binary_publication:
                publications.append(publication)
            return tuple(publications)

        with self.dispatcher.source_timing_planner.prepared_planning() as timing_preparation:
            self._plan_process_source_create_times(
                event,
                not_after=effective_source_visible_by,
            )

            endpoint_reconciliation = None
            endpoint_builders: tuple[
                tuple[OccurrenceBuilder, LocalArtifactPublishToken | None], ...
            ] = ()
            if prepared_endpoint is not None:
                endpoint_reconciliation, endpoint_builders = (
                    self._prepare_process_owned_endpoint_effects_for_publication(
                        system=system,
                        process_identity=process_identity,
                        process_closes_at=provisional_process_termination,
                        prepared=prepared_endpoint,
                        storyline_origin=from_storyline,
                        action_cohort_owned=action_cohort_state_plan is not None,
                    )
                )

            root_dispatch = self.dispatcher.prepare_builder(
                event,
                state_intent=(
                    PreparedDispatchStateIntent.EXTERNAL_ACTION_COHORT
                    if action_cohort_state_plan is not None
                    else PreparedDispatchStateIntent.EXTERNAL_MATERIALIZED_START
                ),
                lifecycle_ticket=(
                    action_cohort_state_plan
                    if action_cohort_state_plan is not None
                    else process_plan
                ),
                artifact_publications=(
                    (process_binary_publication,) if process_binary_publication is not None else ()
                ),
                source_timing_preparation=timing_preparation,
            )
            dependent_dispatches = tuple(
                self.dispatcher.prepare_builder(
                    builder,
                    state_intent=(
                        PreparedDispatchStateIntent.EXTERNAL_ACTION_COHORT
                        if action_cohort_state_plan is not None
                        else PreparedDispatchStateIntent.EXTERNAL_DEPENDENT
                    ),
                    lifecycle_ticket=(
                        action_cohort_state_plan
                        if action_cohort_state_plan is not None
                        else process_plan
                    ),
                    artifact_publications=dependent_artifact_publications(publication),
                    source_timing_preparation=timing_preparation,
                )
                for builder, publication in endpoint_builders
            )
        self.dispatcher.validate_prepared(root_dispatch)
        for dependent_dispatch in dependent_dispatches:
            self.dispatcher.validate_prepared(dependent_dispatch)

        artifact_publications = (
            prepared_effects.artifact_publications if prepared_effects is not None else ()
        )
        if artifact_publications and self._runtime_content_manager is None:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "prepared process artifacts require the engine-owned runtime content manager",
            )
        reservation_ids = tuple(
            getattr(publication, "_reservation_id", 0) for publication in artifact_publications
        )
        if len(reservation_ids) != len(set(reservation_ids)):
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "prepared process artifacts contain a duplicate publication token",
            )

        if action_cohort_state_plan is not None:
            from evidenceforge.generation.actions.command_effects import (
                ExecutionEffectAuditCohortEntry,
            )

            if endpoint_reconciliation is None or prepared_endpoint is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "process endpoint action cohort lost its exact reconciliation",
                )
            endpoint_effect_plan = prepared_endpoint.execution_plan
            if endpoint_effect_plan is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "process endpoint action cohort lost its execution-effect plan",
                )
            effect_member_bindings = tuple(
                ActionCohortEffectMemberBinding(
                    entry_ordinal=0,
                    node_id=builder.effect_provenance.node_id,
                    occurrence_ordinal=builder.effect_provenance.occurrence_ordinal,
                    member=dependent_dispatch,
                )
                for (builder, _publication), dependent_dispatch in zip(
                    endpoint_builders,
                    dependent_dispatches,
                    strict=True,
                )
                if builder.effect_provenance is not None
            )
            action_cohort_batch = self.dispatcher.prepare_action_cohort_batch(
                prepared_endpoint.root_anchor.action_id,
                action_cohort_state_plan,
                (root_dispatch, *dependent_dispatches),
                (
                    ExecutionEffectAuditCohortEntry(
                        endpoint_effect_plan,
                        endpoint_reconciliation,
                    ),
                ),
                effect_member_bindings,
                (),
            )
            self.dispatcher.publish_prepared_action_cohort_batch(action_cohort_batch)
            running_proc = self.state_manager.get_process(system.hostname, pid)
            if running_proc is None:  # pragma: no cover - authenticated State result invariant
                raise StateError("Committed process action cohort did not publish its root")
        else:
            with timing_preparation.claimed_commit():
                with ExitStack() as artifact_stack:
                    artifact_commits = tuple(
                        artifact_stack.enter_context(
                            self._runtime_content_manager.registry.prepared_publication(publication)
                        )
                        for publication in artifact_publications
                    )

                    def finalize_prepared_capabilities() -> None:
                        for artifact_commit in artifact_commits:
                            artifact_commit.commit()
                        timing_preparation.commit_no_fail()

                    running_proc, materialization_receipt = (
                        self._lifecycle_authority.materialize_process(
                            process_plan,
                            finalize_external_no_fail=finalize_prepared_capabilities,
                        )
                    )

            self.dispatcher.publish_prepared(
                root_dispatch,
                materialization_receipt=materialization_receipt,
            )
            for dependent_dispatch in dependent_dispatches:
                self.dispatcher.publish_prepared(
                    dependent_dispatch,
                    materialization_receipt=materialization_receipt,
                )
            if endpoint_reconciliation is not None:
                self._execution_effect_audit.record(endpoint_reconciliation)

        if not from_storyline:
            self._remember_one_shot_cli_launch(
                system=system,
                username=process_username,
                logon_id=process_logon_id,
                process_name=process_name,
                command_line=command_line,
                time=time,
            )
        if running_proc.logon_id and action_cohort_state_plan is None:
            session = self.state_manager.get_session(running_proc.logon_id)
            if session is not None:
                session.last_activity_time = time
        self._record_process_source_create_time(
            system.hostname,
            pid,
            event,
            not_after=effective_source_visible_by,
        )
        if provisional_process_termination is not None:
            self._remember_foreground_process_finalizer(
                system=system,
                user=user,
                pid=pid,
                process_name=process_name,
                logon_id=running_proc.logon_id,
                termination_time=provisional_process_termination,
            )
        if (
            _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(process_name, command_line)
            and _linux_foreground_lifetime(process_name, command_line) is None
            and self._foreground_shell_key(
                system=system,
                username=running_proc.username,
                logon_id=running_proc.logon_id,
                parent_pid=running_proc.parent_pid,
            )
            is not None
        ):
            owning_session = self.state_manager.get_session(running_proc.logon_id)
            shell_deadline = (
                self.state_manager.get_session_end_time(running_proc.logon_id)
                if running_proc.logon_id
                else None
            )
            if shell_deadline is None and owning_session is not None:
                shell_deadline = owning_session.network_close_time
            if shell_deadline is None:
                shell_deadline = getattr(self, "_scenario_end_time", None)
            if shell_deadline is not None:
                self._remember_foreground_shell_available(
                    system=system,
                    username=running_proc.username,
                    logon_id=running_proc.logon_id,
                    parent_pid=running_proc.parent_pid,
                    termination_time=ensure_utc(shell_deadline),
                    seed_text=running_proc.command_line,
                    concurrency_group_id=running_proc.concurrency_group_id,
                )
        if _get_os_category(system.os) == "windows":
            self._emit_windows_process_startup_modules(
                user=user,
                system=system,
                time=time,
                pid=pid,
                process_name=process_name,
                from_storyline=from_storyline,
            )
        self._emit_process_command_network_effects(
            user=user,
            system=system,
            time=time,
            pid=pid,
            process_name=process_name,
            command_line=command_line,
            effect_plan=request.effect_plan,
        )

        runtime_image_load = (
            prepared_effects.runtime_image_load if prepared_effects is not None else None
        )
        if runtime_image_load is not None:
            self.generate_image_load(
                user=user,
                system=system,
                time=runtime_image_load.timestamp,
                pid=pid,
                image=process_name,
                dll_path=runtime_image_load.path,
                signed=runtime_image_load.signed,
                signature=runtime_image_load.signature,
                signature_status=runtime_image_load.signature_status,
                load_phase="runtime",
                from_storyline=from_storyline,
            )
        logger.debug(f"Generated process: {process_name} (PID: {pid}) on {system.hostname}")
        return pid

    def _cancel_uncommitted_process_artifact_publications(
        self,
        prepared_effects: ProcessExecutionPreparedEffects | None,
    ) -> None:
        """Release every prepared artifact reservation not consumed by a successful bundle."""

        manager = self._runtime_content_manager
        if manager is None or prepared_effects is None:
            return
        for publication in prepared_effects.artifact_publications:
            manager.registry.cancel_prepared(publication)

    def _record_reused_process_optional_effects(
        self,
        prepared_effects: ProcessExecutionPreparedEffects | None,
    ) -> None:
        """Reconcile planned optionals explicitly when an existing root is reused."""

        endpoint = prepared_effects.endpoint if prepared_effects is not None else None
        if endpoint is None:
            return
        plan = endpoint.execution_plan
        if plan is None or any(
            node.requirement != EffectRequirement.OPTIONAL for node in plan.nodes
        ):
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "a reused process root may suppress only explicitly optional endpoint effects",
            )
        reconciliation = plan.reconcile(
            tuple(
                EffectExecutionOutcome(
                    node_id=node.node_id,
                    status=EffectOutcomeStatus.SUPPRESSED,
                    completed_at=endpoint.actor.started_at,
                    reason="optional endpoint effect omitted because an exact live root was reused",
                    canonical_occurrence_count=0,
                )
                for node in plan.ordered_nodes
            )
        )
        reconciliation.require_complete()
        self._execution_effect_audit.record(reconciliation)

    def _prepare_process_owned_endpoint_effects_for_publication(
        self,
        *,
        system: System,
        prepared: PreparedProcessEndpointEffectPlan,
        storyline_origin: bool,
        action_cohort_owned: bool = False,
        process_identity: ProcessIdentity | None = None,
        process_closes_at: datetime | None = None,
        pid: int | None = None,
        parent_pid: int | None = None,
    ) -> tuple[
        ExecutionEffectReconciliation,
        tuple[tuple[OccurrenceBuilder, LocalArtifactPublishToken | None], ...],
    ]:
        """Bind and stage an endpoint DAG against an allocation-free process identity."""

        from types import SimpleNamespace

        from evidenceforge.events.contracts import (
            EffectOccurrenceProvenance,
        )
        from evidenceforge.generation.actions.command_effects import (
            EffectExecutionOutcome,
            EffectOutcomeStatus,
            FileEffectIntent,
            RegistryEffectIntent,
        )
        from evidenceforge.generation.actions.endpoint_effects import (
            EndpointEffectExecutionPlan,
            EndpointEffectPreparedCommit,
            ExactProcessEffectActor,
            PreparedFileEffectPayload,
            PreparedRegistryEffectPayload,
            ProcessOwnedEndpointEffectActionBundle,
            ProcessOwnedEndpointEffectRequest,
            bind_prepared_process_endpoint_effect_plan,
        )

        if process_identity is None:
            if pid is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                    "endpoint effects require an exact process identity or PID",
                )
            process_identity = self.state_manager.get_process_identity(system.hostname, pid)
            running_process = self.state_manager.get_process(system.hostname, pid)
            if process_identity is None or running_process is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                    f"endpoint effects require live exact process {system.hostname}:{pid}",
                )
            process_closes_at = running_process.end_time
        if parent_pid is not None and parent_pid != process_identity.parent_pid:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                "endpoint effect parent PID drifted from its exact process identity",
            )

        actor = ExactProcessEffectActor(
            hostname=process_identity.hostname,
            pid=process_identity.pid,
            process_object_id=process_identity.object_id,
            lifecycle_id=process_identity.lifecycle_group_id,
            image=process_identity.image,
            command_line=process_identity.command_line,
            username=process_identity.principal,
            logon_id=process_identity.logon_id,
            started_at=process_identity.started_at,
            closes_at=process_closes_at,
        )
        request = bind_prepared_process_endpoint_effect_plan(prepared, actor)
        host_context = self._build_host_context(system)
        auth_context = AuthContext(
            username=actor.username,
            user_sid=self._get_sid(actor.username),
            logon_id=actor.logon_id,
        )
        process_context = ProcessContext(
            pid=process_identity.pid,
            parent_pid=process_identity.parent_pid,
            image=actor.image,
            command_line=actor.command_line,
            username=actor.username,
            logon_id=actor.logon_id,
            start_time=actor.started_at,
        )
        effect_graph = prepared.execution_plan
        if effect_graph is None:
            raise ExecutionEffectPlanError(
                ExecutionEffectPlanErrorCode.INVALID_PLAN,
                "prepared endpoint publication requires its frozen execution-effect graph",
            )
        nodes_by_instance_key = {node.instance_key: node for node in effect_graph.ordered_nodes}
        builders_by_key: dict[
            str,
            tuple[tuple[OccurrenceBuilder, LocalArtifactPublishToken | None], ...],
        ] = {}
        for effect in prepared.admitted_effects:
            spec = effect.spec
            payload = effect.payload
            intent = spec.intent
            if isinstance(intent, FileEffectIntent):
                if not isinstance(payload, PreparedFileEffectPayload):
                    raise ExecutionEffectPlanError(
                        ExecutionEffectPlanErrorCode.INVALID_PLAN,
                        "prepared file effect lost its source-native payload",
                    )
                semantic_key = f"{system.hostname}:{payload.path.casefold()}"
                subject = EntityIdentity(
                    object_id=stable_uuid("file-identity", semantic_key),
                    kind="file",
                    hostname=system.hostname,
                    semantic_key=semantic_key,
                )
                builder_template = OccurrenceBuilder(
                    timestamp=actor.started_at,
                    event_type=effect.event_type,
                    src_host=host_context,
                    auth=auth_context,
                    process=process_context,
                    file=FileContext(
                        path=payload.path,
                        action=payload.action.value,
                        pid=process_identity.pid,
                        artifact_identity=(
                            payload.artifact_publication.record.artifact
                            if payload.artifact_publication is not None
                            else None
                        ),
                        content_identity=(
                            payload.artifact_publication.record.content
                            if payload.artifact_publication is not None
                            else None
                        ),
                    ),
                    storyline_origin=storyline_origin,
                )
            elif isinstance(intent, RegistryEffectIntent):
                if not isinstance(payload, PreparedRegistryEffectPayload):
                    raise ExecutionEffectPlanError(
                        ExecutionEffectPlanErrorCode.INVALID_PLAN,
                        "prepared registry effect lost its source-native payload",
                    )
                target = f"{payload.key}\\{payload.value_name}"
                semantic_key = f"{system.hostname}:{target.casefold()}:{payload.value}"
                subject = EntityIdentity(
                    object_id=stable_uuid("registry-identity", semantic_key),
                    kind="registry",
                    hostname=system.hostname,
                    semantic_key=semantic_key,
                )
                builder_template = OccurrenceBuilder(
                    timestamp=actor.started_at,
                    event_type=effect.event_type,
                    src_host=host_context,
                    auth=auth_context,
                    process=process_context,
                    registry=RegistryContext(
                        key=target,
                        value=payload.value,
                        value_type=payload.value_type,
                        action=payload.action.value,
                        pid=process_identity.pid,
                    ),
                    storyline_origin=storyline_origin,
                )
            else:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_INTENT,
                    "prepared process endpoint adapters accept only file and registry effects",
                )
            node = nodes_by_instance_key.get(spec.instance_key)
            if node is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.MISSING_DEPENDENCY,
                    "prepared process endpoint payload has no matching effect node",
                )
            artifact_publication = (
                payload.artifact_publication
                if isinstance(payload, PreparedFileEffectPayload)
                else None
            )
            publication_occurrences = (
                tuple(enumerate(spec.occurrence_times))
                if action_cohort_owned
                else ((0, spec.occurrence_times[0]),)
            )
            builders_by_key[spec.instance_key] = tuple(
                (
                    replace(
                        builder_template,
                        timestamp=occurrence_time,
                        occurrence_key=(
                            SemanticOccurrenceKey(
                                action_id=stable_uuid(
                                    "canonical-action",
                                    process_identity.lifecycle_group_id,
                                ),
                                role=node.role,
                                instance_key=stable_uuid(
                                    "endpoint-effect-occurrence",
                                    effect_graph.action_id,
                                    node.node_id,
                                    occurrence_ordinal,
                                    occurrence_time.isoformat(),
                                ),
                            )
                            if action_cohort_owned
                            else None
                        ),
                        identity_plan=EventIdentityPlan(
                            subject=subject,
                            actor=process_identity,
                        ),
                        lifecycle=(
                            ActionLifecycleContext(
                                group_id=process_identity.lifecycle_group_id,
                                canonical_start=process_identity.started_at,
                                phase="dependent",
                                parent_group_id=(
                                    process_identity.parent_lifecycle_group_id or None
                                ),
                            )
                            if action_cohort_owned
                            else None
                        ),
                        effect_provenance=EffectOccurrenceProvenance.planned(
                            kind=(
                                EffectOccurrenceKind.FILE
                                if isinstance(intent, FileEffectIntent)
                                else EffectOccurrenceKind.REGISTRY
                            ),
                            root_action_id=prepared.root_anchor.action_id,
                            plan_action_id=effect_graph.action_id,
                            node_id=node.node_id,
                            occurrence_ordinal=occurrence_ordinal,
                        ),
                    ),
                    artifact_publication,
                )
                for occurrence_ordinal, occurrence_time in publication_occurrences
            )

        staged_builders: tuple[tuple[OccurrenceBuilder, LocalArtifactPublishToken | None], ...] = ()

        def preflight(
            candidate_request: ProcessOwnedEndpointEffectRequest,
            _anchor: ActionAnchor,
        ) -> EndpointEffectExecutionPlan:
            expected = candidate_request.execution_plan
            if expected is None or candidate_request.actor != actor:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                    "process endpoint actor drifted from its allocation-free identity",
                )
            for occurrence in expected.occurrences():
                if occurrence.timestamp < process_identity.started_at or (
                    process_closes_at is not None and occurrence.timestamp >= process_closes_at
                ):
                    raise ExecutionEffectPlanError(
                        ExecutionEffectPlanErrorCode.INVALID_ACTOR,
                        "process endpoint occurrence falls outside its prepared actor lifetime",
                    )
            return expected

        def prepare(
            candidate_request: ProcessOwnedEndpointEffectRequest,
        ) -> EndpointEffectPreparedCommit:
            nonlocal staged_builders
            plan = candidate_request.execution_plan
            if plan is None:
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "process endpoint staging requires its exact frozen plan",
                )
            suppressed = frozenset(plan.suppressed_instance_keys)
            admitted_keys = tuple(
                spec.instance_key for spec in plan.specs if spec.instance_key not in suppressed
            )
            if set(admitted_keys) != builders_by_key.keys():
                raise ExecutionEffectPlanError(
                    ExecutionEffectPlanErrorCode.INVALID_PLAN,
                    "process endpoint builders drifted from admitted planned instances",
                )
            staged_builders = tuple(
                builder for key in admitted_keys for builder in builders_by_key[key]
            )
            specs_by_key = {spec.instance_key: spec for spec in plan.specs}
            outcomes = []
            for node in plan.effects.ordered_nodes:
                spec = specs_by_key[node.instance_key]
                if node.instance_key in suppressed:
                    outcomes.append(
                        EffectExecutionOutcome(
                            node_id=node.node_id,
                            status=EffectOutcomeStatus.SUPPRESSED,
                            completed_at=actor.started_at,
                            reason="optional endpoint effect omitted outside its prepared interval",
                            canonical_occurrence_count=0,
                        )
                    )
                    continue
                outcomes.append(
                    EffectExecutionOutcome(
                        node_id=node.node_id,
                        status=EffectOutcomeStatus.REALIZED,
                        completed_at=spec.occurrence_times[-1],
                        child_action_id=(actor.lifecycle_id if action_cohort_owned else ""),
                        canonical_occurrence_count=node.intent.occurrence_cardinality,
                    )
                )
            return EndpointEffectPreparedCommit.create(plan, tuple(outcomes))

        def commit(
            _candidate_request: ProcessOwnedEndpointEffectRequest,
            _prepared_commit: EndpointEffectPreparedCommit,
        ) -> None:
            return None

        adapter = SimpleNamespace(
            _preflight_process_owned_endpoint_effects=preflight,
            _prepare_process_owned_endpoint_effects=prepare,
            _commit_process_owned_endpoint_effects=commit,
        )
        reconciliation = ProcessOwnedEndpointEffectActionBundle(adapter, request).execute()
        return reconciliation, staged_builders

    def _record_process_source_create_time(
        self,
        hostname: str,
        pid: int,
        event: OccurrenceBuilder,
        *,
        not_after: datetime | None = None,
        publish_finalized: bool = True,
    ) -> None:
        """Remember the latest rendered source timestamp for a process create."""
        if event.process is not None and event.auth is not None:
            self.state_manager.publish_process_auth_identity(
                hostname,
                pid,
                logon_id=event.auth.logon_id,
                session_id=event.auth.session_id,
                logon_type=event.auth.logon_type,
            )
        self._plan_process_source_create_times(event, not_after=not_after)
        if not publish_finalized:
            return
        start_time = event.process.start_time if event.process is not None else None
        if start_time is None:
            return
        visible_create_time = self._source_timing_planner.admitted_process_create_frontier(
            hostname=hostname,
            pid=pid,
            started_at=start_time,
        )
        if visible_create_time is not None:
            self._process_source_create_times[(hostname, pid, start_time)] = visible_create_time
            latest = getattr(self, "_process_source_create_latest", None)
            if latest is None:
                latest = {}
                self._process_source_create_latest = latest
            latest[(hostname, pid)] = (
                start_time,
                visible_create_time,
            )

    def process_source_create_time(self, hostname: str, pid: int) -> datetime | None:
        """Return the latest rendered source-create timestamp for a process."""
        return self._process_cached_time(
            self._process_source_create_times,
            getattr(self, "_process_source_create_latest", {}),
            hostname,
            pid,
        )

    def process_source_terminate_time(self, hostname: str, pid: int) -> datetime | None:
        """Return the rendered source-terminate timestamp for a process."""
        return self._process_cached_time(
            self._process_source_terminate_times,
            getattr(self, "_process_source_terminate_latest", {}),
            hostname,
            pid,
        )

    def _clamp_after_visible_process_create(
        self,
        system: System,
        pid: int,
        time: datetime,
        relationship_key: str,
        *,
        timing_runtime: TimingRuntime | SourceTimingPlanningRuntime | None = None,
    ) -> datetime:
        """Keep fast same-process dependents after visible Windows process creation."""
        if pid <= 0 or _get_os_category(system.os) != "windows":
            return time
        visible_create_time = self.process_source_create_time(system.hostname, pid)
        if visible_create_time is None or time > visible_create_time:
            return time
        return visible_create_time + self._sample_profile_activity_gap(
            relationship_key,
            stable_id=_activity_timing_stable_id(
                "windows-visible-process-dependent",
                system.hostname,
                pid,
                visible_create_time,
                time,
            ),
            host=system.hostname,
            source="endpoint_process",
            lifecycle_id=str(pid),
            sample_key="visible_create_gap",
            timing_runtime=timing_runtime,
        )

    def _clamp_after_visible_linux_process_create(
        self,
        system: System,
        pid: int,
        time: datetime,
        relationship_key: str = "source.ecar_dependent_after_process_create",
        *,
        later_source: str | None = None,
    ) -> datetime:
        """Keep Linux same-process observations after visible eCAR creation."""
        visibility = self._visible_linux_process_create_floor(
            system,
            pid,
            later_source=later_source,
        )
        if visibility is None:
            return time
        visible_create_time, required_floor = visibility
        if time > required_floor:
            return time
        runtime = getattr(self, "timing_runtime", None)
        if type(runtime) not in {TimingRuntime, SourceTimingPlanningRuntime}:
            raise StateError("Linux visibility clamping requires the engine timing runtime")
        stable_id = _activity_timing_stable_id(
            "linux-visible-process-dependent",
            system.hostname,
            pid,
            visible_create_time,
            time,
        )
        timing_delta = self._freeze_profile_activity_gap(
            relationship_key,
            stable_id=stable_id,
            host=system.hostname,
            source="endpoint_process",
            lifecycle_id=str(pid),
            sample_key="visible_create_gap",
            timing_runtime=(runtime if type(runtime) is SourceTimingPlanningRuntime else None),
        )
        result = required_floor + timing_delta.value
        timing_delta.publish()
        return result

    def _clamp_after_visible_linux_process_create_with_runtime(
        self,
        system: System,
        pid: int,
        time: datetime,
        relationship_key: str = "source.ecar_dependent_after_process_create",
        *,
        later_source: str | None = None,
        timing_runtime: TimingRuntime | SourceTimingPlanningRuntime,
        timing_scope: TimingScope,
    ) -> datetime:
        """Keep Linux observations visible using one exact injected timing runtime."""
        if type(timing_runtime) not in {TimingRuntime, SourceTimingPlanningRuntime}:
            raise StateError("Linux visibility clamping requires the exact timing runtime")
        if type(timing_scope) is not TimingScope:
            raise StateError("Linux visibility clamping requires an exact TimingScope")
        visibility = self._visible_linux_process_create_floor(
            system,
            pid,
            later_source=later_source,
        )
        if visibility is None:
            return time
        _visible_create_time, required_floor = visibility
        if time > required_floor:
            return time
        return required_floor + self._sample_profile_activity_gap(
            relationship_key,
            stable_id=timing_scope.stable_id,
            timing_runtime=timing_runtime,
            timing_scope=timing_scope,
            sample_key="visible_process_create_gap",
        )

    def _visible_linux_process_create_floor(
        self,
        system: System,
        pid: int,
        *,
        later_source: str | None,
    ) -> tuple[datetime, datetime] | None:
        """Return Linux process creation and source-visible dependent floors."""
        if pid <= 0 or _get_os_category(system.os) != "linux":
            return None
        visible_create_time = self.process_source_create_time(system.hostname, pid)
        if visible_create_time is None:
            return None
        required_floor = visible_create_time
        if later_source is not None:
            required_floor += self.dispatcher.observation_policy.maximum_delay_difference(
                "ecar",
                later_source,
            ) + timedelta(milliseconds=25)
        return visible_create_time, required_floor

    def _plan_process_source_create_times(
        self,
        event: OccurrenceBuilder,
        *,
        not_after: datetime | None = None,
    ) -> None:
        """Precompute source-create timestamps before threaded emitters render."""
        host = event.src_host
        proc = event.process
        if host is None or proc is None:
            return

        process_start_time = proc.start_time or event.timestamp
        session_ready_floor = self._process_session_source_ready_floor(host.hostname, proc)

        if host.os_category == "windows":
            sysmon_not_before = event.timestamp
            ecar_not_before = process_start_time
            if session_ready_floor is not None:
                sysmon_not_before = max(sysmon_not_before, session_ready_floor)
                ecar_not_before = max(ecar_not_before, session_ready_floor)
            if proc.parent_pid > 0:
                parent_visible_time = self.process_source_create_time(
                    host.hostname, proc.parent_pid
                )
                if parent_visible_time is not None:
                    sysmon_not_before = max(
                        sysmon_not_before,
                        parent_visible_time + timedelta(milliseconds=1),
                    )
            self._source_timing_planner.source_time(
                event,
                "source.sysmon_process_create",
                seed_parts=(host.hostname, proc.pid, process_start_time),
                not_before=sysmon_not_before,
                not_after=not_after,
            )
            self._source_timing_planner.source_time(
                event,
                "source.windows_security_process_create",
                seed_parts=(host.hostname, proc.pid, process_start_time),
                not_before=sysmon_not_before,
                not_after=not_after,
            )
            self._source_timing_planner.source_time(
                event,
                "source.ecar_process_create",
                seed_parts=(host.hostname, proc.pid, process_start_time),
                not_before=ecar_not_before,
                not_after=not_after,
            )
            return
        else:
            ecar_not_before = process_start_time

        self._source_timing_planner.source_time(
            event,
            "source.ecar_process_create",
            seed_parts=(host.hostname, proc.pid, process_start_time),
            not_before=ecar_not_before,
            not_after=not_after,
        )

    def _process_session_source_ready_floor(
        self,
        hostname: str,
        proc: ProcessContext,
    ) -> datetime | None:
        """Return the session-visible floor for process-owned source evidence."""
        logon_id = str(getattr(proc, "logon_id", "") or "")
        if not logon_id or logon_id in {"0x3e7", "0x3e4", "0x3e5", "-"}:
            return None
        session = self.state_manager.get_session(logon_id)
        if session is None or session.system != hostname:
            return None
        ready_time = _session_source_ready_time(session)
        if ready_time is None:
            return None
        return ready_time + timedelta(milliseconds=1)

    def _record_process_source_terminate_time(
        self,
        hostname: str,
        pid: int,
        event: OccurrenceBuilder,
    ) -> None:
        """Remember the rendered eCAR source timestamp for process termination."""
        self._plan_process_source_terminate_times(event)
        self._remember_process_source_terminate_time(hostname, pid, event)

    def _remember_process_source_terminate_time(
        self,
        hostname: str,
        pid: int,
        event: OccurrenceBuilder,
    ) -> None:
        """Adopt already-planned source timing without advancing its canonical owner."""

        source_timing = event.source_timing
        if source_timing is None:
            return
        source_terminate_times = [
            timestamp
            for key, timestamp in source_timing.source_times.items()
            if key.startswith("source.ecar_process_terminate|")
        ]
        if source_terminate_times:
            visible_terminate_time = max(source_terminate_times)
            start_time = event.process.start_time if event.process is not None else None
            self._process_source_terminate_times[(hostname, pid, start_time)] = (
                visible_terminate_time
            )
            latest = getattr(self, "_process_source_terminate_latest", None)
            if latest is None:
                latest = {}
                self._process_source_terminate_latest = latest
            latest[(hostname, pid)] = (
                start_time,
                visible_terminate_time,
            )
            logon_id = str(getattr(event.process, "logon_id", "") or "")
            if logon_id:
                key = (hostname, logon_id)
                previous = self._session_process_source_terminate_times.get(key)
                if previous is None or visible_terminate_time > previous:
                    self._session_process_source_terminate_times[key] = visible_terminate_time

    def _commit_exact_ssh_source_process_termination(
        self,
        event: OccurrenceBuilder,
    ) -> None:
        """Adopt one committed exact SSH client termination into compatibility caches."""

        host = event.src_host
        process = event.process
        if (
            type(event) is not OccurrenceBuilder
            or event.event_type != "process_terminate"
            or host is None
            or process is None
            or process.pid <= 0
            or process.start_time is None
        ):
            raise StateError("Exact SSH process termination cache facts are malformed")
        key = (host.hostname, process.pid, ensure_utc(process.start_time))
        self._remember_process_source_terminate_time(host.hostname, process.pid, event)
        self._terminated_process_keys.add(key)
        self._terminated_process_times[key] = ensure_utc(event.timestamp)

    def _plan_process_source_terminate_times(self, event: OccurrenceBuilder) -> None:
        """Precompute eCAR terminate timestamps for source-visible shell ordering."""
        host = event.src_host
        proc = event.process
        if host is None or proc is None or proc.start_time is None:
            return
        process_create_ts = self.process_source_create_time(host.hostname, proc.pid)
        if process_create_ts is None:
            create_anchor_event = OccurrenceBuilder(
                timestamp=proc.start_time,
                event_type="process_create",
                src_host=host,
                process=proc,
            )
            self._plan_process_source_create_times(create_anchor_event)
            source_timing = create_anchor_event.source_timing
            if source_timing is not None:
                ecar_create_times = [
                    timestamp
                    for key, timestamp in source_timing.source_times.items()
                    if key.startswith("source.ecar_process_create|")
                ]
                if ecar_create_times:
                    process_create_ts = max(ecar_create_times)
        if process_create_ts is None:
            process_create_ts = proc.start_time
        canonical_lifetime = max(timedelta(milliseconds=100), event.timestamp - proc.start_time)
        self._source_timing_planner.source_time(
            event,
            "source.ecar_process_terminate",
            seed_parts=(
                host.hostname,
                proc.pid,
                proc.start_time,
                event.timestamp,
            ),
            not_before=max(event.timestamp, process_create_ts + canonical_lifetime),
        )

    def _emit_process_command_network_effects(
        self,
        *,
        user: User,
        system: System,
        time: datetime,
        pid: int,
        process_name: str,
        command_line: str,
        effect_plan: ExecutionEffectPlan | None = None,
    ) -> None:
        """Emit direct network effects for well-known network-scanning commands."""
        probe_request = NmapCommandProbeRequest(
            user=user,
            system=system,
            time=time,
            pid=pid,
            process_name=process_name,
            command_line=command_line,
        )
        bundle = NmapCommandProbeActionBundle(
            executor=self,
            request=probe_request,
        )
        if effect_plan is None:
            bundle.execute()
            return

        probe_count = self._execute_nmap_command_probe_bundle(probe_request)
        scanner_nodes = tuple(
            node for node in effect_plan.nodes if isinstance(node.intent, ScannerEffectIntent)
        )
        if scanner_nodes:
            outcomes = (
                EffectExecutionOutcome(
                    node_id=scanner_nodes[0].node_id,
                    status=EffectOutcomeStatus.REALIZED,
                    canonical_occurrence_count=probe_count,
                ),
            )
            unplanned_failures = ()
        elif probe_count:
            outcomes = ()
            unplanned_failures = (
                UnplannedEffectFailure(
                    effect_kind=EffectKind.SCANNER,
                    canonical_occurrence_count=probe_count,
                    reason="nmap emitted canonical probes for an explicit no-effect plan",
                ),
            )
        else:
            outcomes = ()
            unplanned_failures = ()
        reconciliation = effect_plan.reconcile(
            outcomes,
            unplanned_failures=unplanned_failures,
        )
        self._execution_effect_audit.record(reconciliation)
        reconciliation.require_complete()

    def _execute_nmap_command_probe_bundle(self, request: NmapCommandProbeRequest) -> int:
        """Expand nmap-like process commands into scanner probe connections."""

        system = request.system
        time = request.time
        pid = request.pid
        process_name = request.process_name
        command_line = request.command_line
        command_lower = command_line.lower()
        image_lower = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if image_lower not in {"nmap", "nmap.exe"} and " nmap " not in f" {command_lower} ":
            return 0
        planning_profile = nmap_command_probe_config()
        plan = NmapCommandProbePlanner(planning_profile).plan(
            request,
            getattr(self, "_ip_to_system", {}),
        )
        if plan is None:
            return 0

        # The process and its connections are separate canonical occurrences, while eCAR
        # independently delays their source observations. Anchor the entire scanner family after
        # the exact process instance's visible CREATE once, then retain the plan's dense relative
        # offsets for discovery and connect siblings. Without this action-owned bridge, short
        # failed probes have no admissible FLOW interval after CREATE and render as actorless rows
        # that still reveal the owning scan by tuple and adjacency.
        probe_anchor_plan = self._nmap_probe_anchor_after_visible_process_create(request)
        probe_anchor = probe_anchor_plan.time

        rng = random.Random(
            _stable_seed(f"nmap_effects:{system.hostname}:{pid}:{command_line}:{time.isoformat()}")
        )
        if plan.discovery:
            self._emit_nmap_discovery_probes(
                request=request,
                targets=plan.targets,
                rng=rng,
                probe_anchor=probe_anchor,
                window_seconds=(
                    planning_profile.discovery_window_seconds_min,
                    planning_profile.discovery_window_seconds_max,
                ),
            )
            if probe_anchor_plan.timing_delta is not None and plan.targets:
                probe_anchor_plan.timing_delta.publish()
            return len(plan.targets)

        probe_pairs = [(target, port) for target in plan.targets for port in plan.ports]
        rng.shuffle(probe_pairs)
        offsets = self._nmap_concurrent_probe_offsets(
            count=len(probe_pairs),
            minimum_window_seconds=planning_profile.connect_window_seconds_min,
            maximum_window_seconds=planning_profile.connect_window_seconds_max,
            rng=rng,
        )
        for (target, port), offset in zip(probe_pairs, offsets, strict=True):
            target_system = self._ip_to_system.get(target.ip) if target.modeled else None
            if target.modeled:
                conn_state, service, duration, orig_bytes, resp_bytes = _nmap_probe_profile(
                    port,
                    target_system,
                    rng,
                )
            else:
                conn_state = "S0"
                service = ""
                duration = rng.uniform(1.5, 6.0)
                orig_bytes = rng.randint(0, 64)
                resp_bytes = 0
            self.generate_connection(
                src_ip=system.ip,
                dst_ip=target.ip,
                time=probe_anchor + offset,
                dst_port=port,
                proto="tcp",
                service=service,
                duration=duration,
                orig_bytes=orig_bytes,
                resp_bytes=resp_bytes,
                emit_dns=False,
                pid=pid,
                source_system=system,
                conn_state=conn_state,
                proxy_bypass=True,
                process_image=process_name,
                suppress_application_side_effects=True,
            )
        if probe_anchor_plan.timing_delta is not None and probe_pairs:
            probe_anchor_plan.timing_delta.publish()
        return len(probe_pairs)

    def _nmap_probe_anchor_after_visible_process_create(
        self,
        request: NmapCommandProbeRequest,
    ) -> _NmapProbeAnchorPlan:
        """Freeze one source-ready anchor shared by all probes from an nmap process."""

        visible_create_time = self.process_source_create_time(
            request.system.hostname,
            request.pid,
        )
        if visible_create_time is None:
            return _NmapProbeAnchorPlan(request.time, None)
        timing_delta = self._freeze_profile_activity_gap(
            "source.ecar_dependent_after_process_create",
            stable_id=request.stable_id,
            host=request.system.hostname,
            source="ecar",
            lifecycle_id=str(request.pid),
            sample_key="probe_readiness_gap",
        )
        return _NmapProbeAnchorPlan(
            max(request.time, visible_create_time + timing_delta.value),
            timing_delta,
        )

    def _emit_nmap_discovery_probes(
        self,
        *,
        request: NmapCommandProbeRequest,
        targets: tuple[NmapCommandProbeTarget, ...],
        rng: random.Random,
        probe_anchor: datetime,
        window_seconds: tuple[float, float],
    ) -> None:
        """Emit bounded process-owned ICMP discovery attempts."""

        offsets = self._nmap_concurrent_probe_offsets(
            count=len(targets),
            minimum_window_seconds=window_seconds[0],
            maximum_window_seconds=window_seconds[1],
            rng=rng,
        )
        for target, offset in zip(targets, offsets, strict=True):
            payload_bytes = rng.choice((56, 64, 84))
            responded = bool(target.modeled)
            self.generate_connection(
                src_ip=request.system.ip,
                dst_ip=target.ip,
                time=probe_anchor + offset,
                dst_port=0,
                proto="icmp",
                service="icmp",
                duration=(rng.uniform(0.001, 0.08) if responded else rng.uniform(0.8, 2.5)),
                orig_bytes=payload_bytes,
                resp_bytes=payload_bytes if responded else 0,
                emit_dns=False,
                pid=request.pid,
                source_system=request.system,
                proxy_bypass=True,
                process_image=request.process_name,
                suppress_application_side_effects=True,
            )

    @staticmethod
    def _nmap_concurrent_probe_offsets(
        *,
        count: int,
        minimum_window_seconds: float,
        maximum_window_seconds: float,
        rng: random.Random,
    ) -> list[timedelta]:
        """Return dense monotonic offsets for a concurrent scanner workload."""

        if count <= 0:
            return []
        window_us = max(
            count + 1,
            int(rng.uniform(minimum_window_seconds, maximum_window_seconds) * 1_000_000),
        )
        sampled = sorted(
            max(80_000, int(rng.betavariate(1.35, 1.8) * window_us)) for _ in range(count)
        )
        offsets: list[timedelta] = []
        previous = 79_999
        for value in sampled:
            current = max(previous + 1, value)
            offsets.append(timedelta(microseconds=current))
            previous = current
        return offsets

    def _clamp_time_after_process_start(
        self, system: System, pid: int, time: datetime, *, offset_ms: int = 100
    ) -> datetime:
        """Ensure dependent process telemetry is not timestamped before process start."""
        process = self.state_manager.get_process(system.hostname, pid)
        if process and process.start_time and time <= process.start_time:
            return process.start_time + timedelta(milliseconds=offset_ms)
        return time

    @staticmethod
    def _ssh_responder_tuple_key(source_ip: str, source_port: int, target_ip: str) -> str:
        return f"{source_ip}:{source_port}->{target_ip}:22/tcp"

    @staticmethod
    def _smb_responder_tuple_key(source_ip: str, source_port: int, target_ip: str) -> str:
        return f"{source_ip}:{source_port}->{target_ip}:445/tcp"

    @staticmethod
    def _network_responder_runtime_key(
        kind: str,
        source_ip: str,
        source_port: int,
        target_ip: str,
    ) -> tuple[str, str, int, str]:
        """Return the exact canonical runtime key for one responder tuple."""

        return (
            kind,
            source_ip.removeprefix("::ffff:"),
            source_port,
            target_ip.removeprefix("::ffff:"),
        )

    def _runtime_responder_pid(
        self,
        kind: str,
        source_ip: str,
        source_port: int,
        target_ip: str,
    ) -> int | None:
        """Return a committed network-runtime responder PID when one exists."""

        value = self._network_transaction_runtime.get_point(
            NetworkRuntimePointFamily.RESPONDER_BINDING,
            self._network_responder_runtime_key(
                kind,
                source_ip,
                source_port,
                target_ip,
            ),
            None,
        )
        if type(value) is not tuple or len(value) != 3 or type(value[1]) is not int:
            return None
        return value[1] if value[1] > 0 else None

    def _remember_smb_responder_pid(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
        pid: int,
    ) -> None:
        """Associate one Samba worker with the accepted SMB transport tuple."""

        if pid <= 0:
            return
        if not hasattr(self, "_smb_responder_pids"):
            self._smb_responder_pids: dict[str, int] = {}
        self._smb_responder_pids[
            self._smb_responder_tuple_key(source_ip, source_port, target_ip)
        ] = pid

    def smb_responder_pid_for_tuple(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
    ) -> int | None:
        """Return the tuple-scoped Samba worker, when one has been resolved."""

        runtime_pid = self._runtime_responder_pid(
            "smb",
            source_ip,
            source_port,
            target_ip,
        )
        if runtime_pid is not None:
            return runtime_pid
        if not hasattr(self, "_smb_responder_pids"):
            return None
        return self._smb_responder_pids.get(
            self._smb_responder_tuple_key(source_ip, source_port, target_ip)
        )

    def _remember_ssh_responder_pid(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
        pid: int,
    ) -> None:
        if pid <= 0:
            return
        if not hasattr(self, "_ssh_responder_pids"):
            self._ssh_responder_pids: dict[str, int] = {}
        self._ssh_responder_pids[
            self._ssh_responder_tuple_key(source_ip, source_port, target_ip)
        ] = pid

    def _remember_ssh_pid_alias(self, hostname: str, observed_pid: int | None, pid: int) -> None:
        if observed_pid is None or observed_pid <= 0 or pid <= 0 or observed_pid == pid:
            return
        if not hasattr(self, "_ssh_pid_aliases"):
            self._ssh_pid_aliases: dict[tuple[str, int], int] = {}
        self._ssh_pid_aliases[(hostname, observed_pid)] = pid

    def _ssh_pid_alias(self, hostname: str, pid: int | None) -> int | None:
        if pid is None or pid <= 0 or not hasattr(self, "_ssh_pid_aliases"):
            return None
        return self._ssh_pid_aliases.get((hostname, pid))

    def ssh_responder_pid_for_tuple(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
    ) -> int | None:
        runtime_pid = self._runtime_responder_pid(
            "ssh",
            source_ip,
            source_port,
            target_ip,
        )
        if runtime_pid is not None:
            return runtime_pid
        if not hasattr(self, "_ssh_responder_pids"):
            return None
        return self._ssh_responder_pids.get(
            self._ssh_responder_tuple_key(source_ip, source_port, target_ip)
        )

    def _prepare_network_responder_process_publication(
        self,
        *,
        plan: ProcessMaterializationPlan,
        system: System,
        source_timing_preparation: SourceTimingPreparation,
    ) -> _PreparedSessionBootstrapProcess:
        """Freeze one root-batch system-process occurrence without publishing it."""

        username = plan.identity.principal
        sid = self.sid_registry.get(username, "S-1-5-18") if self.sid_registry else "S-1-5-18"
        parent_pid = plan.identity.parent_pid
        event = OccurrenceBuilder(
            timestamp=plan.identity.started_at,
            event_type="system_process_create",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=username,
                user_sid=sid,
                logon_id=plan.identity.logon_id,
                subject_sid=sid,
                subject_username=username,
                subject_domain="NT AUTHORITY",
                subject_logon_id=plan.identity.logon_id,
            ),
            process=ProcessContext(
                pid=plan.identity.pid,
                parent_pid=parent_pid,
                image=plan.identity.image,
                command_line=plan.identity.command_line,
                username=username,
                integrity_level="System",
                logon_id=plan.identity.logon_id,
                parent_image=self._lookup_parent_image(system.hostname, parent_pid),
                parent_command_line=self._lookup_parent_command_line(system.hostname, parent_pid),
                parent_start_time=self._lookup_parent_start_time(system.hostname, parent_pid),
                token_elevation="%%1936",
                mandatory_label="S-1-16-16384",
                start_time=plan.identity.started_at,
                current_directory=self._derive_current_directory(
                    system=system,
                    username=username,
                    process_name=plan.identity.image,
                    command_line=plan.identity.command_line,
                    parent_pid=parent_pid,
                ),
            ),
            identity_plan=EventIdentityPlan(subject=plan.identity),
            lifecycle=ActionLifecycleContext(
                group_id=plan.identity.lifecycle_group_id,
                canonical_start=plan.identity.started_at,
                phase="start",
                parent_group_id=plan.identity.parent_lifecycle_group_id or None,
            ),
        )
        prepared = self.dispatcher.prepare_builder(
            event,
            state_intent=PreparedDispatchStateIntent.EXTERNAL_MATERIALIZED_START,
            lifecycle_ticket=plan,
            source_timing_preparation=source_timing_preparation,
        )
        return _PreparedSessionBootstrapProcess(
            plan=plan,
            event=event,
            publication=prepared,
        )

    def prepare_network_responder(
        self,
        *,
        kind: Literal["ssh", "smb"],
        target_system: System,
        time: datetime,
        close_time: datetime | None,
        source_ip: str,
        source_port: int,
        target_user: str | None,
        responding_pid: int,
        network_preparation: Any,
        source_timing_preparation: SourceTimingPreparation,
        runtime_expires_at: datetime,
    ) -> _PreparedNetworkResponder:
        """Plan a tuple-owned Linux responder inside the network root transaction."""

        if kind not in {"ssh", "smb"}:
            raise ValueError(f"Unsupported network responder kind {kind!r}")
        if source_port <= 0:
            raise StateError("Prepared network responder requires a resolved source port")
        tuple_key = self._network_responder_runtime_key(
            kind,
            source_ip,
            source_port,
            target_system.ip,
        )
        staged = network_preparation.read_point(
            NetworkRuntimePointFamily.RESPONDER_BINDING,
            tuple_key,
            None,
            at=ensure_utc(time),
        )
        staged_pid = (
            staged[1]
            if type(staged) is tuple
            and len(staged) == 3
            and type(staged[1]) is int
            and staged[1] > 0
            else None
        )
        candidate_pid = responding_pid if responding_pid > 0 else staged_pid
        if candidate_pid is None:
            candidate_pid = (
                self.ssh_responder_pid_for_tuple(source_ip, source_port, target_system.ip)
                if kind == "ssh"
                else self.smb_responder_pid_for_tuple(source_ip, source_port, target_system.ip)
            )
        if candidate_pid is not None:
            identity = self.state_manager.get_process_identity(
                target_system.hostname,
                candidate_pid,
            )
            if identity is not None:
                network_preparation.stage_point(
                    NetworkRuntimePointFamily.RESPONDER_BINDING,
                    tuple_key,
                    (target_system.hostname, identity.pid, identity.object_id),
                    expires_at=runtime_expires_at,
                )
                return _PreparedNetworkResponder(
                    kind=kind,
                    batch=None,
                    processes=(),
                    responding_pid=identity.pid,
                )

        builder = self.state_manager.begin_materialization_batch()
        planned: list[ProcessMaterializationPlan] = []
        close_bound = ensure_utc(close_time) if close_time is not None else None

        def _bounded_start(requested: datetime) -> datetime:
            requested = ensure_utc(requested)
            if close_bound is None or requested <= close_bound:
                return requested
            return max(ensure_utc(time), close_bound)

        if kind == "ssh":
            sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
            global_sshd = int(sys_pids.get("sshd", 0) or 0)
            parent_pid = (
                global_sshd
                if global_sshd > 0
                and self.state_manager.get_process(target_system.hostname, global_sshd) is not None
                else 0
            )
            sshd_seed = _stable_seed(
                "ssh_responder_pid:"
                f"{target_system.hostname}:{source_ip}:{source_port}:"
                f"{target_system.ip}:{time.isoformat()}"
            )
            start_time = _bounded_start(time + timedelta(milliseconds=8 + (sshd_seed % 72)))
            process_user = target_user or "unknown"
            responder_plan = builder.plan_process(
                system=target_system.hostname,
                parent_pid=parent_pid,
                image="/usr/sbin/sshd",
                command_line=f"sshd: {process_user} [priv]",
                username="root",
                integrity_level="System",
                os_category="linux",
                logon_id="0x3e7",
                lifecycle_group_id=stable_uuid(
                    "network-ssh-responder-process",
                    target_system.hostname,
                    source_ip,
                    source_port,
                    ensure_utc(time).isoformat(),
                ),
                start_time=start_time,
                parent_activity_time=start_time,
                auth_session_id=0,
                auth_logon_type=2,
            )
            planned.append(responder_plan)
            terminate_pid = None
        else:
            services = tuple(
                getattr(self, "_system_service_defaults", {}).get(
                    target_system.hostname,
                    target_system.services or (),
                )
            )
            profile = select_server_profile("linux", services)
            sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
            staged_listener = network_preparation.read_point(
                NetworkRuntimePointFamily.RESPONDER_BINDING,
                ("smb_listener", target_system.hostname),
                None,
                at=ensure_utc(time),
            )
            staged_listener_pid = (
                staged_listener[1]
                if type(staged_listener) is tuple
                and len(staged_listener) == 3
                and type(staged_listener[1]) is int
                else 0
            )
            master_pid = int(
                staged_listener_pid
                or sys_pids.get("smbd", 0)
                or sys_pids.get("smbd_master", 0)
                or 0
            )
            master_plan: ProcessMaterializationPlan | None = None
            if (
                master_pid <= 0
                or self.state_manager.get_process(
                    target_system.hostname,
                    master_pid,
                )
                is None
            ):
                listener = render_smb_process(profile.listener)
                listener_seed = _stable_seed(
                    f"smbd-listener:{target_system.hostname}:{time.isoformat()}"
                )
                listener_time = time - timedelta(seconds=30 + (listener_seed % 271))
                scenario_start = getattr(self, "_scenario_start_time", None)
                if scenario_start is not None:
                    listener_time = max(
                        listener_time,
                        ensure_utc(scenario_start) + timedelta(milliseconds=100),
                    )
                if listener_time >= time:
                    listener_time = time - timedelta(milliseconds=100)
                systemd_pid = int(sys_pids.get("systemd", 0) or 0)
                if self.state_manager.get_process(target_system.hostname, systemd_pid) is None:
                    systemd_pid = 0
                master_plan = builder.plan_process(
                    system=target_system.hostname,
                    parent_pid=systemd_pid,
                    image=listener.image,
                    command_line=listener.command_line,
                    username=listener.username,
                    integrity_level="System",
                    os_category="linux",
                    logon_id="0x3e7",
                    lifecycle_group_id=stable_uuid(
                        "network-smb-listener-process",
                        target_system.hostname,
                        ensure_utc(listener_time).isoformat(),
                    ),
                    start_time=ensure_utc(listener_time),
                    parent_activity_time=ensure_utc(listener_time),
                    auth_session_id=0,
                    auth_logon_type=2,
                )
                planned.append(master_plan)
                master_pid = master_plan.identity.pid
                network_preparation.stage_point(
                    NetworkRuntimePointFamily.RESPONDER_BINDING,
                    ("smb_listener", target_system.hostname),
                    (
                        target_system.hostname,
                        master_plan.identity.pid,
                        master_plan.identity.object_id,
                    ),
                    expires_at=runtime_expires_at,
                )
            if profile.worker is None:
                responder_plan = master_plan
                if responder_plan is None:
                    identity = self.state_manager.get_process_identity(
                        target_system.hostname,
                        master_pid,
                    )
                    if identity is None:
                        raise StateError("Prepared SMB responder lost its listener identity")
                    network_preparation.stage_point(
                        NetworkRuntimePointFamily.RESPONDER_BINDING,
                        tuple_key,
                        (target_system.hostname, identity.pid, identity.object_id),
                        expires_at=runtime_expires_at,
                    )
                    return _PreparedNetworkResponder(
                        kind="smb",
                        batch=None,
                        processes=(),
                        responding_pid=identity.pid,
                    )
                terminate_pid = None
            else:
                worker = render_smb_process(
                    profile.worker,
                    server=target_system.hostname,
                    share="",
                    path="",
                    client_path="",
                    username="root",
                    operation="transport",
                    client_ip=source_ip,
                )
                worker_seed = _stable_seed(
                    "smbd-worker:"
                    f"{target_system.hostname}:{source_ip}:{source_port}:"
                    f"{target_system.ip}:{time.isoformat()}"
                )
                worker_time = _bounded_start(time + timedelta(milliseconds=8 + (worker_seed % 72)))
                responder_plan = builder.plan_process(
                    system=target_system.hostname,
                    parent_pid=master_pid,
                    parent_plan=master_plan,
                    image=worker.image,
                    command_line=worker.command_line,
                    username=worker.username,
                    integrity_level="System",
                    os_category="linux",
                    logon_id="0x3e7",
                    lifecycle_group_id=stable_uuid(
                        "network-smb-worker-process",
                        target_system.hostname,
                        source_ip,
                        source_port,
                        ensure_utc(time).isoformat(),
                    ),
                    start_time=worker_time,
                    parent_activity_time=worker_time,
                    auth_session_id=0,
                    auth_logon_type=2,
                )
                planned.append(responder_plan)
                terminate_pid = responder_plan.identity.pid

        if responder_plan is None:
            raise StateError("Prepared network responder produced no process owner")
        batch = builder.seal()
        publications = tuple(
            self._prepare_network_responder_process_publication(
                plan=plan,
                system=target_system,
                source_timing_preparation=source_timing_preparation,
            )
            for plan in planned
        )
        network_preparation.stage_point(
            NetworkRuntimePointFamily.RESPONDER_BINDING,
            tuple_key,
            (
                target_system.hostname,
                responder_plan.identity.pid,
                responder_plan.identity.object_id,
            ),
            expires_at=runtime_expires_at,
        )
        return _PreparedNetworkResponder(
            kind=kind,
            batch=batch,
            processes=publications,
            responding_pid=responder_plan.identity.pid,
            terminate_pid_after_close=terminate_pid,
        )

    def publish_prepared_network_responder(
        self,
        prepared: _PreparedNetworkResponder,
        *,
        materialization_receipt: object,
        target_system: System,
        close_time: datetime | None,
    ) -> None:
        """Publish responder observations after the root authority commit succeeds."""

        for process in prepared.processes:
            self.dispatcher.publish_prepared(
                process.publication,
                materialization_receipt=materialization_receipt,
            )
            self._record_process_source_create_time(
                target_system.hostname,
                process.plan.identity.pid,
                process.event,
            )
        terminate_pid = prepared.terminate_pid_after_close
        if terminate_pid is None or close_time is None:
            return
        running = self.state_manager.get_process(target_system.hostname, terminate_pid)
        if running is not None:
            self._plan_linux_smb_worker_end(target_system, running, close_time)

    def _remember_ssh_session_ready_time(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
        ready_time: datetime,
    ) -> None:
        """Remember when tuple-scoped receiver-side SSH child evidence may appear."""

        self._ssh_session_ready_times[
            self._ssh_responder_tuple_key(source_ip, source_port, target_ip)
        ] = ensure_utc(ready_time)

    def ssh_session_ready_time_for_tuple(
        self,
        source_ip: str,
        source_port: int,
        target_ip: str,
    ) -> datetime | None:
        """Return the receiver-side SSH child-evidence readiness time for a tuple."""

        return self._ssh_session_ready_times.get(
            self._ssh_responder_tuple_key(source_ip, source_port, target_ip)
        )

    def ensure_linux_ssh_responder_process(
        self,
        *,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_port: int,
        target_user: str | None = None,
    ) -> int:
        """Return the destination-side sshd process that owns one SSH 5-tuple."""
        remembered = self.ssh_responder_pid_for_tuple(source_ip, source_port, target_system.ip)
        if remembered is not None:
            running = self.state_manager.get_process(target_system.hostname, remembered)
            if running is not None:
                return remembered

        sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
        global_sshd = sys_pids.get("sshd")
        parent_pid = (
            global_sshd
            if global_sshd
            and self.state_manager.get_process(target_system.hostname, global_sshd) is not None
            else 0
        )
        sshd_seed = _stable_seed(
            "ssh_responder_pid:"
            f"{target_system.hostname}:{source_ip}:{source_port}:"
            f"{target_system.ip}:{time.isoformat()}"
        )
        process_user = target_user or "unknown"
        sshd_pid = self.generate_system_process(
            system=target_system,
            time=time + timedelta(milliseconds=8 + (sshd_seed % 72)),
            process_name="/usr/sbin/sshd",
            command_line=f"sshd: {process_user} [priv]",
            parent_pid=parent_pid,
            username="root",
            emit_linux_syslog=False,
        )
        self._remember_ssh_responder_pid(source_ip, source_port, target_system.ip, sshd_pid)
        return sshd_pid

    def ensure_linux_smb_responder_process(
        self,
        *,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_port: int,
        close_time: datetime | None = None,
    ) -> int:
        """Return the destination-side smbd worker that owns one SMB tuple."""

        remembered = self.smb_responder_pid_for_tuple(
            source_ip,
            source_port,
            target_system.ip,
        )
        if remembered is not None:
            running = self.state_manager.get_process(target_system.hostname, remembered)
            if running is not None:
                self._plan_linux_smb_worker_end(
                    target_system,
                    running,
                    close_time,
                )
                return remembered

        services = tuple(
            getattr(self, "_system_service_defaults", {}).get(
                target_system.hostname,
                target_system.services or (),
            )
        )
        profile = select_server_profile("linux", services)
        sys_pids = getattr(self, "_system_pids", {}).setdefault(
            target_system.hostname,
            {},
        )
        master_pid = sys_pids.get("smbd") or sys_pids.get("smbd_master")
        if (
            master_pid is None
            or self.state_manager.get_process(
                target_system.hostname,
                master_pid,
            )
            is None
        ):
            listener = render_smb_process(profile.listener)
            listener_seed = _stable_seed(
                f"smbd-listener:{target_system.hostname}:{time.isoformat()}"
            )
            listener_time = time - timedelta(
                seconds=30 + (listener_seed % 271),
            )
            scenario_start = getattr(self, "_scenario_start_time", None)
            if scenario_start is not None:
                listener_time = max(
                    listener_time,
                    ensure_utc(scenario_start) + timedelta(milliseconds=100),
                )
            if listener_time >= time:
                listener_time = time - timedelta(milliseconds=100)
            master_pid = self.generate_system_process(
                system=target_system,
                time=listener_time,
                process_name=listener.image,
                command_line=listener.command_line,
                parent_pid=sys_pids.get("systemd", 1),
                username=listener.username,
                emit_linux_syslog=False,
            )
            sys_pids["smbd"] = master_pid
            sys_pids["smbd_master"] = master_pid

        if profile.worker is None:
            return master_pid
        worker = render_smb_process(
            profile.worker,
            server=target_system.hostname,
            share="",
            path="",
            client_path="",
            username="root",
            operation="transport",
            client_ip=source_ip,
        )
        worker_seed = _stable_seed(
            "smbd-worker:"
            f"{target_system.hostname}:{source_ip}:{source_port}:"
            f"{target_system.ip}:{time.isoformat()}"
        )
        worker_pid = self.generate_system_process(
            system=target_system,
            time=time + timedelta(milliseconds=8 + (worker_seed % 72)),
            process_name=worker.image,
            command_line=worker.command_line,
            parent_pid=master_pid,
            username=worker.username,
            emit_linux_syslog=False,
        )
        self._remember_smb_responder_pid(
            source_ip,
            source_port,
            target_system.ip,
            worker_pid,
        )
        running_worker = self.state_manager.get_process(target_system.hostname, worker_pid)
        if running_worker is not None:
            self._plan_linux_smb_worker_end(
                target_system,
                running_worker,
                close_time,
            )
        return worker_pid

    def _plan_linux_smb_worker_end(
        self,
        target_system: System,
        worker: RunningProcess,
        close_time: datetime | None,
    ) -> None:
        """Keep a transport-lived smbd worker through close, then terminate it."""

        if close_time is None:
            return
        close_time = ensure_utc(close_time)
        self._remember_process_connection_hold(
            system=target_system,
            pid=worker.pid,
            close_time=close_time,
        )
        end_seed = _stable_seed(
            f"smbd-worker-end:{target_system.hostname}:{worker.pid}:{close_time.isoformat()}"
        )
        termination_time = close_time + timedelta(milliseconds=80 + (end_seed % 1921))
        self._remember_foreground_process_finalizer(
            system=target_system,
            user=self._user_model_for_username(worker.username),
            pid=worker.pid,
            process_name=worker.image,
            logon_id=worker.logon_id or "0x3e7",
            termination_time=termination_time,
        )

    def _emit_generic_ssh_preauth_failure_syslog(
        self,
        *,
        target_system: System,
        target_host: HostContext | None,
        time: datetime,
        source_ip: str,
        source_port: int,
        sshd_pid: int,
        attempted_username: str | None,
        duration: float | None,
    ) -> None:
        """Emit source-native sshd auth companions for generic preauth transport."""
        if target_host is None or not source_ip or source_ip == "-" or source_port <= 0:
            return

        seed = _stable_seed(
            "generic_ssh_preauth_failure:"
            f"{target_system.hostname}:{source_ip}:{source_port}:{target_system.ip}:"
            f"{sshd_pid}:{time.isoformat()}"
        )
        connection_delta_ms = 5 + (seed % 10)
        invalid_delta_ms = connection_delta_ms + 40 + ((seed >> 8) % 180)
        failed_delta_ms = invalid_delta_ms + 120 + ((seed >> 16) % 600)
        close_delta_ms = max(
            failed_delta_ms + 40 + ((seed >> 24) % 180),
            int((duration or 0.0) * 1000) + 20,
        )
        process_visible_connection_time = self._clamp_after_visible_linux_process_create(
            target_system,
            sshd_pid,
            time + timedelta(milliseconds=connection_delta_ms),
            later_source="syslog",
        )
        process_floor_shift_ms = max(
            0,
            math.ceil(
                (
                    process_visible_connection_time
                    - (time + timedelta(milliseconds=connection_delta_ms))
                ).total_seconds()
                * 1000
            ),
        )
        rows = [
            (
                connection_delta_ms + process_floor_shift_ms,
                6,
                f"Connection from {source_ip} port {source_port} on {target_system.ip} port 22",
            )
        ]
        attempted_username = (attempted_username or "").strip()
        if attempted_username:
            known_account = (
                attempted_username in getattr(self, "sid_registry", {})
                or attempted_username in getattr(self, "_users_by_username", {})
                or attempted_username in {"root", "admin", "apache"}
            )
            if known_account:
                rows.append(
                    (
                        failed_delta_ms + process_floor_shift_ms,
                        4,
                        f"Failed password for {attempted_username} "
                        f"from {source_ip} port {source_port} ssh2",
                    )
                )
                close_subject = f"authenticating user {attempted_username}"
            else:
                rows.extend(
                    [
                        (
                            invalid_delta_ms + process_floor_shift_ms,
                            5,
                            f"Invalid user {attempted_username} from {source_ip} port {source_port}",
                        ),
                        (
                            failed_delta_ms + process_floor_shift_ms,
                            4,
                            f"Failed password for invalid user {attempted_username} "
                            f"from {source_ip} port {source_port} ssh2",
                        ),
                    ]
                )
                close_subject = f"invalid user {attempted_username}"
        else:
            rows.extend(
                [
                    (
                        invalid_delta_ms + process_floor_shift_ms,
                        5,
                        f"Invalid user unknown from {source_ip} port {source_port}",
                    ),
                    (
                        failed_delta_ms + process_floor_shift_ms,
                        4,
                        f"Failed password for invalid user unknown "
                        f"from {source_ip} port {source_port} ssh2",
                    ),
                ]
            )
            close_subject = "invalid user unknown"
        rows.append(
            (
                close_delta_ms + process_floor_shift_ms,
                6,
                f"Connection closed by {close_subject} {source_ip} port {source_port} [preauth]",
            )
        )
        for delta_ms, severity, message in rows:
            self.generate_syslog_event(
                target_system,
                time + timedelta(milliseconds=delta_ms),
                "sshd",
                message,
                pid=sshd_pid,
                facility=10,
                severity=severity,
            )

    def ensure_linux_ssh_client_process(
        self,
        *,
        user: User,
        source_system: System,
        target_system: System,
        time: datetime,
        process_image: str,
        source_port: int,
        required_until: datetime | None = None,
    ) -> tuple[int, str] | None:
        """Return the source-side SSH client process that owns an outbound session."""
        if _get_os_category(source_system.os) != "linux":
            return None

        requested_time = ensure_utc(time)
        image = process_image or "/usr/bin/ssh"
        exe_name = image.rsplit("/", 1)[-1].lower()
        if exe_name == "sshd":
            image = "/usr/bin/ssh"
            exe_name = "ssh"
        if exe_name not in {"ssh", "scp"}:
            image = "/usr/bin/ssh"
            exe_name = "ssh"

        target_host = self._build_host_context(target_system).fqdn or target_system.hostname
        command_line = _linux_ssh_client_command_line(
            exe_name=exe_name,
            username=user.username,
            target_host=target_host,
            target_ip=target_system.ip,
            source_hostname=source_system.hostname,
            source_port=source_port,
            requested_time=requested_time,
        )

        seed = _stable_seed(
            "linux_ssh_client_process:"
            f"{source_system.hostname}:{user.username}:{target_system.hostname}:"
            f"{source_port}:{requested_time.isoformat()}:{image}"
        )
        process_time = requested_time - timedelta(milliseconds=6500 + (seed % 11500))
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        if scenario_start is not None and requested_time >= scenario_start:
            latest_with_visible_headroom = requested_time - timedelta(seconds=5)
            if process_time < scenario_start and latest_with_visible_headroom > scenario_start:
                process_time = min(
                    latest_with_visible_headroom,
                    scenario_start + timedelta(milliseconds=400 + (seed % 1800)),
                )

        # Reject a clock/profile combination that cannot render even the root client
        # before opening a fallback session or materializing its shell chain.
        if (
            self._process_create_source_bound(
                system=source_system,
                canonical_time=process_time,
            )
            > requested_time
        ):
            return None

        session = self._active_source_linux_session(
            user,
            source_system,
            requested_time,
            required_until=required_until,
        )
        if session is None:
            # A bounded network owner cannot safely publish a fallback local session
            # before its session-shell and client source frontiers are known.  Require
            # an already-admitted source session instead of leaving a partial logon.
            return None

        logon_time = ensure_utc(session.start_time)
        parent_pid = self.ensure_linux_session_shell(
            user,
            source_system,
            session.logon_id,
            logon_time,
            process_time,
            source_visible_by=process_time,
        )
        if parent_pid is None:
            parent_pid = self.ensure_linux_visible_shell_parent(
                user,
                source_system,
                process_time,
                session.logon_id,
                logon_time,
                source_visible_by=process_time,
            )
        if parent_pid is None:
            return None

        prepared_owner = self._prepare_linux_foreground_connection_owner(
            system=source_system,
            user=user,
            session=session,
            process_time=process_time,
            activity_time=requested_time,
            process_name=image,
            command_line=command_line,
            source_visible_by=requested_time,
        )
        if prepared_owner is None:
            return None
        parent_pid, process_time = prepared_owner
        if not _session_active_for_activity(session, process_time, margin_seconds=0.5):
            return None

        pid = self.generate_process(
            user=user,
            system=source_system,
            time=process_time,
            logon_id=session.logon_id,
            process_name=image,
            command_line=command_line,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            concurrency_group_id=self._bash_history_process_group_id(
                user,
                source_system,
                process_time,
                command_line,
            ),
            source_visible_by=requested_time,
        )
        if pid <= 0:
            return None
        self._record_user_process(source_system, user, pid, image)
        self._emit_bash_command_event(user, source_system, process_time, command_line)
        self._remember_linux_bash_session_activity(
            user,
            source_system,
            process_time,
            requested_time,
        )
        self.state_manager.update_process_activity_time(source_system.hostname, pid, requested_time)
        self.state_manager.set_current_time(requested_time)
        return pid, image

    def ensure_ssh_client_process(
        self,
        *,
        user: User,
        source_system: System,
        target_system: System,
        time: datetime,
        process_image: str,
        source_port: int,
        required_until: datetime | None = None,
    ) -> tuple[int, str] | None:
        """Materialize the source-side SSH client before opening its transport."""

        if _get_os_category(source_system.os) == "linux":
            return self.ensure_linux_ssh_client_process(
                user=user,
                source_system=source_system,
                target_system=target_system,
                time=time,
                process_image=process_image,
                source_port=source_port,
                required_until=required_until,
            )
        if _get_os_category(source_system.os) != "windows":
            return None
        target_host = self._build_host_context(target_system).fqdn or target_system.hostname
        pid, image = self._ensure_user_connection_owner_process(
            source_system=source_system,
            time=time,
            service="ssh",
            dst_port=22,
            os_category="windows",
            hostname=target_host,
            ssh_attempted_username=user.username,
            source_visible_by=ensure_utc(time),
        )
        if pid <= 0 or not image:
            return None
        if required_until is not None:
            self._remember_process_connection_hold(
                system=source_system,
                pid=pid,
                close_time=required_until,
            )
        return pid, image

    def _active_source_linux_session(
        self,
        user: User,
        system: System,
        time: datetime,
        *,
        required_until: datetime | None = None,
    ) -> ActiveSession | None:
        """Return the newest Linux session that can own the full SSH client lifetime."""
        strict_server_session = (system.type or "workstation").lower() == "server" and getattr(
            self, "_scenario_start_time", None
        ) is not None
        candidates = [
            session
            for session in self.state_manager.get_sessions_for_user_at(user.username, time)
            if session.system == system.hostname
            and _session_active_for_activity(session, time, margin_seconds=1.5)
            and (
                required_until is None
                or _session_active_for_activity(session, required_until, margin_seconds=1.5)
            )
            and (not strict_server_session or session.session_kind == "ssh")
        ]
        if not candidates:
            return None
        return max(candidates, key=lambda session: ensure_utc(session.start_time))

    def _normalize_sshd_syslog_pid(
        self,
        *,
        system: System,
        time: datetime,
        message: str,
        pid: int | None,
    ) -> int | None:
        alias = self._ssh_pid_alias(system.hostname, pid)
        if alias is not None:
            return alias

        source_ip = ""
        source_port = 0
        target_user = None
        conn_match = re.match(
            r"^Connection from (?P<src_ip>\S+) port (?P<src_port>\d+) "
            r"on (?P<dst_ip>\S+) port 22$",
            message,
        )
        if conn_match:
            source_ip = conn_match.group("src_ip")
            source_port = int(conn_match.group("src_port"))
        else:
            accepted_match = re.match(
                r"^Accepted \S+ for (?:invalid user )?(?P<target_user>\S+) "
                r"from (?P<src_ip>\S+) port (?P<src_port>\d+) ",
                message,
            )
            if accepted_match:
                source_ip = accepted_match.group("src_ip")
                source_port = int(accepted_match.group("src_port"))
                target_user = accepted_match.group("target_user")

        if not source_ip or source_port <= 0:
            return pid

        responder_pid = self.ensure_linux_ssh_responder_process(
            target_system=system,
            time=time,
            source_ip=source_ip,
            source_port=source_port,
            target_user=target_user,
        )
        self._remember_ssh_pid_alias(system.hostname, pid, responder_pid)
        return responder_pid

    def reserve_ssh_source_port(
        self,
        source_ip: str,
        target_ip: str,
        source_port: int | None,
        rng: random.Random,
        source_os: str,
        time: datetime | None = None,
    ) -> int:
        """Reserve a per-source/destination SSH source port for unambiguous correlation."""
        reservation_time = ensure_utc(
            time or self.state_manager.state.current_time or self._proxy_channel_watermark
        )
        candidate = source_port or _ephemeral_port(rng, source_os)
        ts_epoch = time.timestamp() if time is not None else None
        reservation_cutoff = reservation_time - timedelta(
            seconds=_RECENT_CONNECTION_REUSE_WINDOW_SECONDS
        )
        network_runtime = getattr(self, "_network_transaction_runtime", None)
        if ts_epoch is not None:
            self._prune_recent_connection_tuples(ts_epoch)
        for _ in range(100):
            key = (source_ip, target_ip, candidate)
            reserved_at = self._ssh_source_ports.get(key)
            if reserved_at is not None and reserved_at < reservation_cutoff:
                self._ssh_source_ports.pop(key)
                reserved_at = None
            recent_key = (source_ip, candidate, target_ip, 22, "tcp")
            recent_seen = self._recent_connection_tuples.get(recent_key)
            if network_runtime is not None:
                runtime_seen = network_runtime.get_point(
                    NetworkRuntimePointFamily.RECENT_TUPLE,
                    recent_key,
                    None,
                    at=reservation_time,
                )
                if runtime_seen is not None:
                    if type(runtime_seen) is not float:
                        raise StateError(
                            "Network runtime SSH source-port tuple contains a malformed timestamp"
                        )
                    recent_seen = max(
                        recent_seen if recent_seen is not None else float("-inf"),
                        runtime_seen,
                    )
            recent_is_active = (
                ts_epoch is not None
                and recent_seen is not None
                and ts_epoch - recent_seen <= _RECENT_CONNECTION_REUSE_WINDOW_SECONDS
            )
            if (
                source_port is not None
                and reserved_at is not None
                and ts_epoch is not None
                and recent_seen is not None
                and abs(ts_epoch - recent_seen) <= 1.0
            ):
                return candidate
            if reserved_at is None and not recent_is_active:
                self._ssh_source_ports.set(
                    key,
                    reservation_time,
                    deadline=reservation_time,
                )
                if time is not None:
                    self._remember_connection_tuple(
                        source_ip,
                        candidate,
                        target_ip,
                        22,
                        "tcp",
                        reservation_time,
                    )
                    if network_runtime is not None:
                        tuple_expiry = min(
                            network_runtime.window_end,
                            reservation_time
                            + timedelta(seconds=_RECENT_CONNECTION_REUSE_WINDOW_SECONDS),
                        )
                        for tuple_key in self._connection_tuple_key_variants(
                            source_ip,
                            candidate,
                            target_ip,
                            22,
                            "tcp",
                        ):
                            network_runtime.set_point(
                                NetworkRuntimePointFamily.RECENT_TUPLE,
                                tuple_key,
                                reservation_time.timestamp(),
                                expires_at=tuple_expiry,
                            )
                return candidate
            candidate = _ephemeral_port(rng, source_os)
        raise StateError(
            "Unable to reserve a unique SSH source port after 100 exact-key attempts for "
            f"{source_ip} -> {target_ip}:22 inside the 24-hour tuple-reuse window"
        )

    def preview_ssh_source_port(
        self,
        source_ip: str,
        target_ip: str,
        source_port: int | None,
        rng: random.Random,
        source_os: str,
        time: datetime,
    ) -> int:
        """Select an SSH source port without publishing compatibility-cache state."""

        reservation_time = ensure_utc(time)
        reservation_cutoff = reservation_time - timedelta(
            seconds=_RECENT_CONNECTION_REUSE_WINDOW_SECONDS
        )
        candidate = source_port or _ephemeral_port(rng, source_os)
        network_runtime = self._network_transaction_runtime
        for _ in range(100):
            key = (source_ip, target_ip, candidate)
            reserved_at = self._ssh_source_ports.get(key)
            if reserved_at is not None and reserved_at < reservation_cutoff:
                reserved_at = None
            recent_key = (source_ip, candidate, target_ip, 22, "tcp")
            recent_seen = self._recent_connection_tuples.get(recent_key)
            runtime_seen = network_runtime.get_point(
                NetworkRuntimePointFamily.RECENT_TUPLE,
                recent_key,
                None,
                at=reservation_time,
            )
            if runtime_seen is not None:
                if type(runtime_seen) is not float:
                    raise StateError(
                        "Network runtime SSH source-port tuple contains a malformed timestamp"
                    )
                recent_seen = max(
                    recent_seen if recent_seen is not None else float("-inf"),
                    runtime_seen,
                )
            recent_is_active = bool(
                recent_seen is not None
                and reservation_time.timestamp() - recent_seen
                <= _RECENT_CONNECTION_REUSE_WINDOW_SECONDS
            )
            if reserved_at is None and not recent_is_active:
                return candidate
            candidate = _ephemeral_port(rng, source_os)
        raise StateError(
            "Unable to preview a unique SSH source port after 100 exact-key attempts for "
            f"{source_ip} -> {target_ip}:22 inside the 24-hour tuple-reuse window"
        )

    def generate_process_termination(
        self,
        user: User,
        system: System,
        time: datetime,
        pid: int,
        process_name: str,
        logon_id: str,
        from_storyline: bool = False,
        session_end_plan: SessionEndPlan | None = None,
    ) -> None:
        """Generate process termination event across all applicable log formats.

        Builds a OccurrenceBuilder and dispatches to matching emitters (Windows 4689,
        eCAR PROCESS/TERMINATE). StateManager.apply() handles end_process.

        Args:
            user: User who owned the process
            system: System where process ran
            time: Termination timestamp
            pid: PID of the terminated process
            process_name: Full path of the terminated process
            logon_id: LogonID of the owning session
        """
        request = ProcessTerminationRequest(
            user=user,
            system=system,
            time=time,
            pid=pid,
            process_name=process_name,
            logon_id=logon_id,
            from_storyline=from_storyline,
            session_end_plan=session_end_plan,
        )
        ProcessTerminationActionBundle(self, request).execute()

    def _execute_process_termination_bundle(self, request: ProcessTerminationRequest) -> None:
        """Expand a process-termination bundle through the compatibility adapter."""
        from evidenceforge.events.contexts import ProcessContext

        user = request.user
        system = request.system
        time = request.time
        pid = request.pid
        process_name = request.process_name
        logon_id = request.logon_id
        from_storyline = request.from_storyline
        authoritative_end_plan = request.session_end_plan

        running_proc = self.state_manager.get_process(system.hostname, pid)
        if self._process_termination_recorded(
            system.hostname,
            pid,
            running_proc.start_time if running_proc is not None else None,
        ):
            return

        if (
            running_proc is not None
            and running_proc.last_activity_time is not None
            and time <= running_proc.last_activity_time
        ):
            if authoritative_end_plan is not None and authoritative_end_plan.is_authoritative:
                time = ensure_utc(running_proc.last_activity_time) + timedelta(milliseconds=25)
            else:
                delay_rng = random.Random(
                    _stable_seed(
                        "process_terminate_after_activity:"
                        f"{system.hostname}:{pid}:{running_proc.last_activity_time.isoformat()}"
                    )
                )
                time = running_proc.last_activity_time + timedelta(
                    seconds=delay_rng.uniform(2.0, 30.0)
                )
        if running_proc is not None:
            process_name = running_proc.image
        process_username = running_proc.username if running_proc is not None else user.username
        process_membership_logon_id = (
            running_proc.logon_id if running_proc is not None else logon_id
        )
        process_logon_id = (
            running_proc.token_logon_id or process_membership_logon_id
            if running_proc is not None
            else logon_id
        )
        owning_session = self.state_manager.get_session(process_membership_logon_id)
        lifecycle_session = self.state_manager.get_session(logon_id)
        if (
            lifecycle_session is not None
            and lifecycle_session.system == system.hostname
            and lifecycle_session.session_winlogon_pid == pid
        ):
            # winlogon keeps its SYSTEM token/LUID while remaining a member of
            # the interactive terminal session it bootstraps.  Use that
            # explicit relationship only for terminal-session metadata and
            # teardown timing, never to rewrite the process authentication ID.
            owning_session = lifecycle_session
        token_session = self.state_manager.get_session(process_logon_id)
        session_logon_type = (
            running_proc.auth_logon_type
            if running_proc is not None and running_proc.auth_logon_type is not None
            else token_session.logon_type
            if token_session is not None
            else 0
        )
        session_end_time = (
            self.state_manager.get_session_end_time(owning_session.logon_id)
            if owning_session is not None
            else None
        )
        if (
            owning_session is not None
            and owning_session.session_kind == "ssh"
            and owning_session.network_close_time is not None
            and owning_session.transport_pid != pid
        ):
            ssh_transport_end = ensure_utc(owning_session.network_close_time)
            session_end_time = (
                ssh_transport_end
                if session_end_time is None
                else min(ensure_utc(session_end_time), ssh_transport_end)
            )
        if session_end_time is not None and time >= session_end_time:
            end_margin_ms = 150 + (
                _stable_seed(
                    f"process_terminate_before_logoff:{system.hostname}:{pid}:{process_logon_id}"
                )
                % 850
            )
            latest_allowed = session_end_time - timedelta(milliseconds=end_margin_ms)
            if running_proc is not None and running_proc.start_time >= latest_allowed:
                latest_allowed = running_proc.start_time + timedelta(milliseconds=100)
            if latest_allowed < session_end_time:
                time = min(time, latest_allowed)
        if authoritative_end_plan is not None and authoritative_end_plan.is_authoritative:
            deadline = ensure_utc(authoritative_end_plan.canonical_end)
            hold_until = self._process_connection_hold_until.get(
                self._process_instance_key(system.hostname, pid)
            )
            if hold_until is not None and ensure_utc(hold_until) >= deadline:
                raise StateError(
                    "Process connection hold extends beyond authoritative session end: "
                    f"{system.hostname} pid={pid} hold={ensure_utc(hold_until).isoformat()} "
                    f"end={deadline.isoformat()}"
                )
            end_margin_ms = 25 + (
                _stable_seed(
                    "process_terminate_before_authoritative_logoff:"
                    f"{system.hostname}:{pid}:{process_logon_id}:{deadline.isoformat()}"
                )
                % 176
            )
            time = min(ensure_utc(time), deadline - timedelta(milliseconds=end_margin_ms))
        else:
            time = self._held_process_termination_time(
                system=system,
                pid=pid,
                requested_time=time,
            )
        if not process_logon_id:
            if process_username in _SYSTEM_ACCOUNTS:
                process_logon_id = "0x3e7"
            else:
                resolved_username, resolved_logon_id = self._resolve_process_identity(
                    system=system,
                    username=process_username,
                    logon_id=logon_id,
                    process_name=process_name,
                    time=time,
                )
                process_username = resolved_username
                process_logon_id = resolved_logon_id or logon_id
        time = self._clamp_after_visible_process_create(
            system,
            pid,
            time,
            "windows.process_exit_after_visible_create",
        )
        self.state_manager.get_process_object_id(system.hostname, pid)
        process_session_id = (
            running_proc.auth_session_id
            if running_proc is not None and running_proc.auth_session_id is not None
            else token_session.session_id
            if token_session is not None
            else 0
        )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="process_terminate",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=process_username,
                user_sid=self._get_sid(process_username),
                logon_id=process_logon_id,
                session_id=process_session_id,
                logon_type=session_logon_type or 0,
            ),
            process=ProcessContext(
                pid=pid,
                parent_pid=0,
                image=process_name,
                command_line="",
                username=process_username,
                logon_id=process_logon_id,
                start_time=running_proc.start_time if running_proc is not None else None,
                concurrency_group_id=(
                    running_proc.concurrency_group_id if running_proc is not None else ""
                ),
            ),
            storyline_origin=from_storyline,
        )

        self._record_process_source_terminate_time(system.hostname, pid, event)
        if (
            running_proc is not None
            and _get_os_category(system.os) == "linux"
            and _linux_shell_process_reserves_foreground(
                running_proc.image,
                running_proc.command_line,
            )
            and self._foreground_shell_key(
                system=system,
                username=running_proc.username,
                logon_id=running_proc.logon_id,
                parent_pid=running_proc.parent_pid,
            )
            is not None
        ):
            visible_termination = self.process_source_terminate_time(system.hostname, pid)
            self._remember_foreground_shell_available(
                system=system,
                username=running_proc.username,
                logon_id=running_proc.logon_id,
                parent_pid=running_proc.parent_pid,
                termination_time=max(
                    ensure_utc(event.timestamp),
                    ensure_utc(visible_termination)
                    if visible_termination is not None
                    else ensure_utc(event.timestamp),
                ),
                seed_text=running_proc.command_line,
                concurrency_group_id=running_proc.concurrency_group_id,
            )
        self.dispatcher.dispatch_builder(event)
        termination_start_time = event.process.start_time if event.process is not None else None
        termination_key = (system.hostname, pid, termination_start_time)
        self._terminated_process_keys.add(termination_key)
        self._terminated_process_times[termination_key] = ensure_utc(event.timestamp)
        self._terminate_completed_one_shot_shell_parent(
            user=user,
            system=system,
            child=running_proc,
            child_termination_time=event.timestamp,
            from_storyline=from_storyline,
            session_end_plan=authoritative_end_plan,
        )

        logger.debug(
            f"Generated process termination: {process_name} (PID: {pid}) on {system.hostname}"
        )

    def _terminate_completed_one_shot_shell_parent(
        self,
        *,
        user: User,
        system: System,
        child: RunningProcess | None,
        child_termination_time: datetime,
        from_storyline: bool,
        session_end_plan: SessionEndPlan | None,
    ) -> None:
        """Close a one-shot Windows wrapper just after its final foreground child."""

        if child is None or _get_os_category(system.os) != "windows" or child.parent_pid <= 0:
            return
        parent = self.state_manager.get_process(system.hostname, child.parent_pid)
        if (
            parent is not None
            and parent.ecar_object_id in _GENERIC_LOGOFF_FROZEN_PROCESS_OBJECT_IDS.get()
        ):
            return
        if parent is None or not self._is_one_shot_shell_command(parent.image, parent.command_line):
            return
        if not self._windows_shell_parent_invokes_child(
            system=system,
            parent_pid=parent.pid,
            process_name=child.image,
            command_line=child.command_line,
        ):
            return
        if any(
            process.pid != child.pid and process.parent_pid == parent.pid
            for process in self.state_manager.get_processes_on_system(system.hostname)
        ):
            return
        child_lifecycle = self._lifecycle_authority.registry.get_process(child.ecar_object_id)
        if child_lifecycle is None or child_lifecycle.closed_at != ensure_utc(
            child_termination_time
        ):
            # Compatibility dispatch may record a non-strict lifecycle close
            # failure after ending the child in State.  Do not cascade that
            # split-brain state into the shell parent; the owning session will
            # close it after the exact child graph drains.
            return
        seed = _stable_seed(
            "one_shot_shell_after_final_child:"
            f"{system.hostname}:{parent.pid}:{child.pid}:{child_termination_time.isoformat()}"
        )
        parent_termination_time = child_termination_time + timedelta(
            milliseconds=80 + (seed % 920),
            microseconds=137 + (seed % 719),
        )
        resolved_parent_termination_time = self.resolve_process_lifecycle_close_candidate(
            system.hostname,
            parent.pid,
            parent_termination_time,
        )
        if resolved_parent_termination_time is None:
            return
        parent_session = self.state_manager.get_session(parent.logon_id)
        parent_deadlines = [
            ensure_utc(deadline)
            for deadline in (
                (
                    session_end_plan.canonical_end
                    if session_end_plan is not None and session_end_plan.is_authoritative
                    else None
                ),
                (
                    parent_session.end_plan.canonical_end
                    if parent_session is not None
                    and parent_session.end_plan is not None
                    and parent_session.end_plan.is_authoritative
                    else None
                ),
                parent_session.network_close_time if parent_session is not None else None,
            )
            if deadline is not None
        ]
        if (
            parent_deadlines and resolved_parent_termination_time >= min(parent_deadlines)
        ) or not self._is_within_scenario_window(resolved_parent_termination_time):
            return
        parent_termination_time = resolved_parent_termination_time
        parent_user = (
            user
            if parent.username == user.username
            else self._user_model_for_username(parent.username)
        )
        self.generate_process_termination(
            user=parent_user,
            system=system,
            time=parent_termination_time,
            pid=parent.pid,
            process_name=parent.image,
            logon_id=parent.logon_id,
            from_storyline=from_storyline,
            session_end_plan=session_end_plan,
        )

    @staticmethod
    def _kerberos_audit_runtime_times(value: object) -> tuple[datetime, ...]:
        """Return one exact runtime-owned Kerberos audit window."""

        if type(value) is not tuple or any(
            type(seen) is not datetime or seen.tzinfo is not UTC for seen in value
        ):
            raise StateError("Kerberos audit runtime point contains malformed timestamps")
        return value

    def _prepare_kerberos_audit_publication(
        self,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        *,
        stable_id: str,
        source_port: int | None = None,
    ) -> NetworkPointBatchToken | None:
        """Prepare pair and tuple audit windows for one primary DC occurrence."""

        if not source_ip or source_ip == "-" or not dc_hostname:
            return None
        current = ensure_utc(time)
        normalized_source_ip = source_ip.removeprefix("::ffff:")
        pair_key = (normalized_source_ip, dc_hostname.lower())
        runtime = self._network_transaction_runtime
        batch = runtime.begin_point_batch(
            stable_id=f"{stable_id}:audit-runtime",
            linearization_time=current,
        )
        try:
            pair_times = self._kerberos_audit_runtime_times(
                batch.read_point(
                    NetworkRuntimePointFamily.KERBEROS_AUDIT_PAIR,
                    pair_key,
                    (),
                )
            )
            pair_recent = tuple(
                seen for seen in pair_times if abs((current - seen).total_seconds()) <= 30.0
            )
            pair_recent = (*pair_recent, current)[-12:]
            pair_expiry = min(max(pair_recent) + timedelta(seconds=30), runtime.window_end)
            batch.stage_point(
                NetworkRuntimePointFamily.KERBEROS_AUDIT_PAIR,
                pair_key,
                pair_recent,
                expires_at=pair_expiry,
            )
            if source_port is not None and source_port > 0:
                tuple_key = (
                    normalized_source_ip,
                    dc_hostname.lower().rstrip("."),
                    source_port,
                )
                tuple_times = self._kerberos_audit_runtime_times(
                    batch.read_point(
                        NetworkRuntimePointFamily.KERBEROS_AUDIT_TUPLE,
                        tuple_key,
                        (),
                    )
                )
                tuple_recent = tuple(
                    seen for seen in tuple_times if abs((current - seen).total_seconds()) <= 30.0
                )
                tuple_recent = (*tuple_recent, current)[-16:]
                tuple_expiry = min(
                    max(tuple_recent) + timedelta(seconds=30),
                    runtime.window_end,
                )
                batch.stage_point(
                    NetworkRuntimePointFamily.KERBEROS_AUDIT_TUPLE,
                    tuple_key,
                    tuple_recent,
                    expires_at=tuple_expiry,
                )
            return batch.seal()
        except BaseException:
            try:
                batch.cancel()
            except StateError:
                pass
            raise

    def _dispatch_prepared_kerberos_audit(
        self,
        event: OccurrenceBuilder,
        *,
        stable_id: str,
        source_ip: str,
        dc_hostname: str,
        source_port: int | None,
    ) -> None:
        """Publish one primary DC audit and its point windows as one occurrence."""

        token = self._prepare_kerberos_audit_publication(
            source_ip,
            dc_hostname,
            event.timestamp,
            stable_id=stable_id,
            source_port=source_port,
        )
        if token is None:
            self.dispatcher.dispatch_builder(event)
            return
        with self._network_transaction_runtime.claimed_point_batch(token) as prepared:
            self.dispatcher.dispatch_builder(event)
            prepared.commit_no_fail()

    def _kerberos_audit_count_for_connection(
        self,
        source_ip: str,
        dc_hostname: str,
        source_port: int,
        time: datetime,
        *,
        window_seconds: float = 3.0,
    ) -> int:
        """Count nearby DC audit events sharing the visible Kerberos transport tuple."""
        if not source_ip or source_ip == "-" or not dc_hostname or source_port <= 0:
            return 0
        key = (source_ip.removeprefix("::ffff:"), dc_hostname.lower().rstrip("."), source_port)
        current = ensure_utc(time)
        times = self._kerberos_audit_runtime_times(
            self._network_transaction_runtime.get_point(
                NetworkRuntimePointFamily.KERBEROS_AUDIT_TUPLE,
                key,
                (),
                at=current,
            )
        )
        return sum(1 for seen in times if abs((current - seen).total_seconds()) <= window_seconds)

    def _has_recent_kerberos_audit(
        self,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        *,
        window_seconds: float = 10.0,
    ) -> bool:
        if not source_ip or source_ip == "-" or not dc_hostname:
            return False
        key = (source_ip.removeprefix("::ffff:"), dc_hostname.lower())
        current = ensure_utc(time)
        times = self._kerberos_audit_runtime_times(
            self._network_transaction_runtime.get_point(
                NetworkRuntimePointFamily.KERBEROS_AUDIT_PAIR,
                key,
                (),
                at=current,
            )
        )
        return any(abs((current - seen).total_seconds()) <= window_seconds for seen in times)

    def _emit_dc_audit_for_kerberos_connection(
        self,
        *,
        src_ip: str,
        src_port: int,
        dst_ip: str,
        time: datetime,
        dst_port: int,
        proto: str,
        conn_state: str,
        service: str,
        source_system: System | None,
    ) -> None:
        """Emit DC-side Kerberos audit companions via an action bundle."""
        request = KerberosConnectionAuditRequest(
            src_ip=src_ip,
            src_port=src_port,
            dst_ip=dst_ip,
            time=time,
            dst_port=dst_port,
            proto=proto,
            conn_state=conn_state,
            service=service,
            source_system=source_system,
        )
        KerberosConnectionAuditActionBundle(self, request).execute()

    def _execute_kerberos_connection_audit_bundle(
        self,
        request: KerberosConnectionAuditRequest,
    ) -> None:
        """Ensure visible internal-to-DC Kerberos flows have nearby DC audit evidence."""
        src_ip = request.src_ip
        src_port = request.src_port
        dst_ip = request.dst_ip
        time = request.time
        dst_port = request.dst_port
        proto = request.proto
        conn_state = request.conn_state
        service = request.service
        source_system = request.source_system

        if proto not in {"tcp", "udp"} or dst_port != 88 or service != "kerberos":
            return
        if proto == "tcp" and conn_state in {"S0", "S1", "SH", "SHR", "REJ", "OTH"}:
            return
        if source_system is None:
            return

        dc_system = self._dc_system_for_ip(dst_ip)
        if dc_system is None:
            return

        dc_hostname = dc_system.hostname
        reserved_port = self._find_reserved_kerberos_source_port(
            src_ip,
            dc_hostname,
            time,
            dst_ip=dst_ip,
            proto=proto,
            exclude_active_tuple=False,
        )
        if self._has_recent_kerberos_audit(src_ip, dc_hostname, time) and reserved_port == src_port:
            return

        rng = random.Random(
            _stable_seed(
                "kerberos_connection_audit:"
                f"{src_ip}:{dst_ip}:{source_system.hostname}:{time.timestamp()}"
            )
        )
        tgt_time, tgs_time = self._kerberos_ticket_times(
            time,
            rng,
            tgs_before_ms=(12, 75),
            tgt_before_tgs_ms=(35, 260),
        )
        machine_principal = f"{source_system.hostname}$"
        self._maybe_generate_kerberos_tgt(
            username=machine_principal,
            source_ip=src_ip,
            dc_hostname=dc_hostname,
            time=tgt_time,
            rng=rng,
            source_port=src_port,
        )
        service_name = rng.choices(
            [
                f"host/{dc_hostname}",
                f"ldap/{dc_hostname}",
                f"cifs/{dc_hostname}",
                f"DNS/{dc_hostname}",
            ],
            weights=[34, 36, 20, 10],
            k=1,
        )[0]
        machine_service_principal = (
            f"{machine_principal}@{getattr(self, '_ad_domain', 'corp.local').upper()}"
        )
        self.generate_kerberos_service_ticket(
            username=machine_service_principal,
            service_name=service_name,
            source_ip=src_ip,
            dc_hostname=dc_hostname,
            time=tgs_time,
            source_port=src_port,
        )

    def generate_connection(
        self,
        src_ip: str,
        dst_ip: str,
        time: datetime,
        dst_port: int = 443,
        proto: str = "tcp",
        service: str | None = None,
        duration: float | None = None,
        orig_bytes: int | None = None,
        resp_bytes: int | None = None,
        src_port: int | None = None,
        emit_dns: bool = False,
        pid: int = -1,
        source_system: Optional["System"] = None,
        conn_state: str | None = None,
        dns: Optional["DnsContext"] = None,
        email: Optional["EmailContext"] = None,
        smtp: Optional["SmtpContext"] = None,
        ssl: SslContext | None = None,
        x509: X509Context | None = None,
        x509_chain: list[X509Context] | None = None,
        tls_presentation: TlsCertificatePresentationPlan | None = None,
        ids_alerts: list["IdsAlertPlan"] | None = None,
        http: Optional["HttpContext"] = None,
        file_transfer: FileTransferContext | None = None,
        file_transfers: list[FileTransferContext] | None = None,
        pe: PeContext | None = None,
        pe_analyses: list[PeContext] | None = None,
        ocsp: OcspContext | None = None,
        ocsp_transaction: OcspTransactionPlan | None = None,
        proxy: Optional["ProxyContext"] = None,
        firewall: FirewallContext | None = None,
        hostname: str | None = None,
        proxy_bypass: bool = False,
        suppress_direct_http_channel: bool = False,
        process_image: str | None = None,
        preserve_dst_ip: bool = False,
        preserve_http_outcome: bool = False,
        suppress_application_side_effects: bool = False,
        suppress_source_pid_inference: bool = False,
        preserve_explicit_payload: bool = False,
        suppress_prereq_dns: bool = False,
        packet_overhead_bytes: int | None = None,
        responding_pid: int = -1,
        ssh_attempted_username: str | None = None,
        parent_action_group_id: str | None = None,
        preserve_start_time: bool = False,
        transport_lifecycle_mode: Literal["network", "deferred_session"] = "network",
        deferred_session_authority: DeferredSessionNetworkAuthority | None = None,
        identity_capture: NetworkConnectionIdentityCapture | None = None,
        persistent_smb_root_intent: PersistentSmbRootIntent | None = None,
        defer_source_publication: bool = False,
    ) -> str:
        """Generate network connection across all applicable log formats.

        Opens connection in StateManager, builds a OccurrenceBuilder with
        NetworkTransactionPlan, and dispatches to matching emitters (Zeek conn,
        Snort, eCAR FLOW). Dispatcher handles network visibility filtering.

        Optional context overrides (ids, http) are attached to the
        OccurrenceBuilder, enabling correlated rendering by format-specific
        emitters (e.g., Snort from IdsAlertPlan, web_access from HttpContext).

        Args:
            src_ip: Source IP address
            dst_ip: Destination IP address
            time: Connection start timestamp
            dst_port: Destination port
            proto: Protocol (tcp/udp/icmp)
            service: Application protocol (http, https, ssh, dns, etc.)
            duration: Connection duration in seconds
            orig_bytes: Bytes sent by originator
            resp_bytes: Bytes sent by responder
            src_port: Source port (auto-assigned ephemeral if None)
            emit_dns: If True, emit a DNS lookup for dst_ip before the connection
            ids_alerts: Optional IDS contexts for correlated multi-signature rendering
            http: Optional HttpContext override (skips auto-generation)
            preserve_dst_ip: Preserve caller-supplied dst_ip when the scenario or caller
                intentionally pairs an authored hostname with a specific address. This keeps
                static-NAT VIPs and explicit egress destinations from being re-resolved.
            suppress_direct_http_channel: Keep a higher-level protocol manager, such as the
                explicit-proxy bundle, as the sole application-channel owner for this leg.
            transport_lifecycle_mode: Publish an ordinary physical transport at the network root,
                or defer an SSH/RDP transport until its exact session binding is available.
            packet_overhead_bytes: Optional IP packet overhead to preserve source-native
                packet accounting for canonical firewall/syslog companion events.

        Returns:
            Zeek UID (18-character string)
        """
        request = NetworkConnectionRequest(
            src_ip=src_ip,
            dst_ip=dst_ip,
            time=time,
            dst_port=dst_port,
            proto=proto,
            service=service,
            duration=duration,
            orig_bytes=orig_bytes,
            resp_bytes=resp_bytes,
            src_port=src_port,
            emit_dns=emit_dns,
            pid=pid,
            source_system=source_system,
            conn_state=conn_state,
            dns=dns,
            email=email,
            smtp=smtp,
            ssl=ssl,
            x509=x509,
            x509_chain=tuple(x509_chain or ()),
            tls_presentation=tls_presentation,
            ids_alerts=tuple(ids_alerts or ()),
            http=http,
            file_transfer=file_transfer,
            file_transfers=tuple(file_transfers or ()),
            pe=pe,
            pe_analyses=tuple(pe_analyses or ()),
            ocsp=ocsp,
            ocsp_transaction=ocsp_transaction,
            proxy=proxy,
            firewall=firewall,
            hostname=hostname,
            proxy_bypass=proxy_bypass,
            suppress_direct_http_channel=suppress_direct_http_channel,
            process_image=process_image,
            preserve_dst_ip=preserve_dst_ip,
            preserve_http_outcome=preserve_http_outcome,
            suppress_application_side_effects=suppress_application_side_effects,
            suppress_source_pid_inference=suppress_source_pid_inference,
            preserve_explicit_payload=preserve_explicit_payload,
            suppress_prereq_dns=suppress_prereq_dns,
            packet_overhead_bytes=packet_overhead_bytes,
            responding_pid=responding_pid,
            ssh_attempted_username=ssh_attempted_username,
            parent_action_group_id=parent_action_group_id,
            preserve_start_time=preserve_start_time,
            transport_lifecycle_mode=transport_lifecycle_mode,
            deferred_session_authority=deferred_session_authority,
            identity_capture=identity_capture,
            persistent_smb_root_intent=(
                None
                if persistent_smb_root_intent is None
                else persistent_smb_root_intent.identity_snapshot()
            ),
            defer_source_publication=defer_source_publication,
        )
        return NetworkConnectionActionBundle(
            executor=self,
            request=request,
        ).execute()

    def generate_smb_activity(
        self,
        *,
        spec: SmbActivityEventSpec,
        actor: User,
        parent_system: System,
        time: datetime,
        process_pid: int = -1,
        process_image: str = "",
        activity_source: Literal["storyline", "baseline"] = "storyline",
        files_override: tuple[Any, ...] = (),
    ) -> SmbActivityResult:
        """Generate one bounded canonical SMB2/3 disk-share activity burst."""

        return SmbActivityActionBundle(
            self,
            SmbActivityRequest(
                spec=spec,
                actor=actor,
                parent_system=parent_system,
                time=time,
                process_pid=process_pid,
                process_image=process_image,
                activity_source=activity_source,
                files_override=files_override,
            ),
        ).execute()

    def persistent_smb_terminal_continuation_census(
        self,
    ) -> PersistentSmbTerminalContinuationCensus:
        """Return bounded retained terminal work for persistent SMB production."""

        return self._persistent_smb_terminal_continuations.census()

    @staticmethod
    def _terminal_census_fields(
        prefix: str,
        census: object,
        fields: tuple[str, ...],
    ) -> tuple[tuple[str, int], ...]:
        """Project exact integer owner fields into one named terminal census."""

        counts: list[tuple[str, int]] = []
        for field_name in fields:
            value = getattr(census, field_name)
            if type(value) is not int or value < 0:
                raise StateError(
                    f"Terminal census {prefix}.{field_name} is not a non-negative exact int"
                )
            counts.append((f"{prefix}.{field_name}", value))
        return tuple(counts)

    def _persistent_smb_projection_terminal_counts(self) -> tuple[tuple[str, int], ...]:
        """Return dispatcher-owned persistent-SMB group and source residue."""

        dispatcher = self.dispatcher
        group_census = getattr(dispatcher, "persistent_smb_projection_group_census", None)
        source_census = getattr(dispatcher, "persistent_smb_source_publication_census", None)
        if not callable(group_census) or not callable(source_census):
            raise StateError("Dispatcher has no persistent-SMB terminal census")
        group = group_census()
        source = source_census()
        return (
            *self._terminal_census_fields(
                "persistent_smb_group",
                group,
                (
                    "retained_groups",
                    "inactive_members",
                    "certified_members",
                    "committed_unacknowledged_members",
                    "retained_commit_receipts",
                    "retained_bytes",
                    "reserved_member_capacity",
                    "reserved_receipt_capacity",
                    "reserved_byte_capacity",
                    "retained_target_generations",
                ),
            ),
            *self._terminal_census_fields(
                "persistent_smb_source",
                source,
                (
                    "active_publications",
                    "prepared_publications",
                    "published_unacknowledged",
                    "acknowledged_terminal_proofs",
                    "retained_rows",
                    "retained_bytes",
                ),
            ),
        )

    def persistent_smb_terminal_state_census(self) -> TerminalTransientOwnerCensus:
        """Return all synchronous persistent-SMB action and projection residue."""

        state = self.state_manager.get_state_summary()
        state_fields = (
            "smb_file_mutation_journals",
            "smb_file_mutation_capabilities",
            "smb_file_mutation_operation_indexes",
            "smb_file_mutation_file_owners",
            "smb_file_mutation_path_owners",
            "smb_file_mutation_journal_entries",
            "smb_file_mutation_commit_results",
            "smb_file_mutation_commit_receipts",
            "smb_file_mutation_acknowledging",
            "smb_file_mutation_cancelling",
            "smb_file_mutation_journal_locators",
            "smb_file_mutation_result_locators",
            "smb_file_mutation_retained_bytes",
            "smb_connection_pins_active",
            "smb_connection_pins_terminal",
            "smb_connection_pin_install_receipts",
            "smb_connection_finalization_results",
            "smb_connection_finalization_receipts",
            "smb_connection_pin_acknowledging",
            "smb_connection_pin_session_owners",
            "smb_connection_pin_protected_sessions",
            "smb_connection_pin_reserved_bytes",
            "smb_connection_pin_retained_bytes",
        )
        state_counts = tuple((f"state.{name}", int(state[name])) for name in state_fields)
        continuation = self.persistent_smb_terminal_continuation_census()
        smb = self._smb_channel_manager.census()
        return TerminalTransientOwnerCensus(
            counts=(
                *state_counts,
                *self._terminal_census_fields(
                    "persistent_smb_continuation",
                    continuation,
                    ("retained_continuations", "active_claims", "retained_bytes"),
                ),
                *self._terminal_census_fields(
                    "smb_channel",
                    smb,
                    ("open_sessions", "open_trees", "open_handles"),
                ),
                *self._persistent_smb_projection_terminal_counts(),
            )
        )

    def assert_persistent_smb_terminal_state_drained(self) -> None:
        """Reject terminal progression while synchronous SMB action residue remains."""

        census = self.persistent_smb_terminal_state_census()
        if census.nonzero:
            raise StateError(f"Persistent SMB terminal state is not drained: {census.nonzero!r}")

    def assert_persistent_smb_projection_state_drained(self) -> None:
        """Reassert SMB group/source ownership after exact dispatcher recovery."""

        nonzero = tuple(
            (name, count)
            for name, count in self._persistent_smb_projection_terminal_counts()
            if count
        )
        if nonzero:
            raise StateError(f"Persistent SMB projection state is not drained: {nonzero!r}")

    def linux_sudo_logoff_journal_census(self) -> LinuxSudoLogoffJournalCensus:
        """Return a callback-free count of pending exact sudo-logoff owners."""

        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            if type(journals) is not dict:
                raise StateError("Linux sudo logoff journals must be an exact dictionary")
            values = tuple(dict.values(journals))
            if any(type(value) is not _LinuxSudoLogoffContinuation for value in values):
                raise StateError("Linux sudo logoff journal contains a malformed owner")
            if any(type(value.active) is not bool for value in values):
                raise StateError("Linux sudo logoff journal has a malformed execution claim")
            high_water = self._linux_sudo_logoff_high_water_pending
            if (
                type(high_water) is not int
                or high_water < len(values)
                or high_water > _LINUX_SUDO_TTY_MAP_CENSUS_LIMIT
            ):
                raise StateError("Linux sudo logoff high-water census is malformed")
            return LinuxSudoLogoffJournalCensus(
                pending=len(values),
                active=sum(value.active is True for value in values),
                capacity=_LINUX_SUDO_TTY_MAP_CENSUS_LIMIT,
                high_water_pending=high_water,
            )

    def finalize_linux_sudo_logoffs(self) -> None:
        """Drain retained route-bearing local logoffs while exact sinks remain open."""

        with self._linux_sudo_tty_lock:
            journals = self._pending_linux_sudo_logoffs
            if type(journals) is not dict:
                raise StateError("Linux sudo logoff journals must be an exact dictionary")
            values = tuple(dict.values(journals))
            if any(
                type(continuation) is not _LinuxSudoLogoffContinuation
                or type(continuation.base_logoff_time) is not datetime
                or type(continuation.stable_id) is not str
                or type(continuation.active) is not bool
                for continuation in values
            ):
                raise StateError("Linux sudo logoff journal contains a malformed owner")
            continuations = tuple(
                sorted(
                    values,
                    key=lambda continuation: (
                        continuation.base_logoff_time,
                        continuation.stable_id,
                    ),
                )
            )
        for continuation in continuations:
            if type(continuation) is not _LinuxSudoLogoffContinuation:
                raise StateError("Linux sudo logoff journal contains a malformed owner")
            claimed = self._claim_pending_linux_sudo_logoff(continuation.request)
            if claimed is not continuation:
                raise StateError("Linux sudo logoff finalizer changed its retained owner")
            try:
                self._execute_linux_sudo_logoff_continuation(continuation)
            finally:
                self._release_linux_sudo_logoff_claim(continuation)

    def assert_linux_sudo_logoffs_drained(self) -> None:
        """Reject emitter shutdown while a route-bearing close remains retained."""

        census = self.linux_sudo_logoff_journal_census()
        if census.pending or census.active:
            raise StateError(f"Linux sudo logoff journal is not drained: {census!r}")

    def terminal_transient_owner_census(self) -> TerminalTransientOwnerCensus:
        """Return the composite terminal census of transient public owners."""

        application = self._application_channel_registry.census()
        proxy = self._proxy_channel_manager.census()
        http = self._http_channel_manager.census()
        ssh = self._ssh_channel_manager.census()
        rdp = self._rdp_session_manager.census()
        smb = self._smb_channel_manager.census()
        network = self._network_transaction_runtime.census()
        lifecycle = self._lifecycle_authority.census()
        lifecycle_registry = self._lifecycle_authority.registry
        action_cohort = lifecycle_registry.action_cohort_preparation_census()
        closed_transport = lifecycle_registry.closed_transport_preparation_census()
        service = lifecycle_registry.service_preparation_census()
        timing = self._source_timing_planner.preparation_authority_census()
        detached_timing = self._source_timing_planner.detached_binding_census()
        dispatcher = self.dispatcher
        exact_census = getattr(dispatcher, "exact_projection_recovery_census", None)
        cohort_census = getattr(dispatcher, "action_cohort_publication_census", None)
        if not callable(exact_census) or not callable(cohort_census):
            raise StateError("Dispatcher has no composite terminal projection census")
        exact = exact_census()
        cohort = cohort_census()
        linux_sudo_logoff = self.linux_sudo_logoff_journal_census()
        return TerminalTransientOwnerCensus(
            counts=(
                *self._terminal_census_fields(
                    "linux_sudo_logoff",
                    linux_sudo_logoff,
                    ("pending", "active"),
                ),
                *self.persistent_smb_terminal_state_census().counts,
                *self._terminal_census_fields(
                    "application",
                    application,
                    (
                        "open_channels",
                        "active_operations",
                        "prepared_admissions",
                        "claimed_admissions",
                        "reserved_channel_ids",
                        "reserved_transport_ids",
                        "reserved_operation_ids",
                        "recoverable_admission_slots",
                        "recoverable_admission_results",
                        "prepared_admission_tokens",
                        "prepared_admission_capabilities",
                        "prepared_close_tokens",
                        "prepared_close_capabilities",
                        "prepared_close_projections",
                        "prepared_commit_journals",
                        "prepared_close_commit_journals",
                        "releasing_admissions",
                        "acknowledging_admission_results",
                        "acknowledging_close_results",
                        "recoverable_admission_receipts",
                        "recoverable_close_results",
                        "recoverable_close_receipts",
                    ),
                ),
                *self._terminal_census_fields(
                    "proxy",
                    proxy,
                    (
                        "open_tunnel_views",
                        "prepared_admissions",
                        "claimed_admissions",
                        "reserved_channel_ids",
                        "reserved_affinities",
                        "reserved_origin_transport_ids",
                    ),
                ),
                *self._terminal_census_fields(
                    "http",
                    http,
                    ("open_transport_views",),
                ),
                *self._terminal_census_fields(
                    "ssh",
                    ssh,
                    ("open_sessions", "active_operations"),
                ),
                *self._terminal_census_fields(
                    "rdp",
                    rdp,
                    (
                        "connected_sessions",
                        "disconnected_sessions",
                        "active_operations",
                        "active_leases",
                    ),
                ),
                *self._terminal_census_fields(
                    "smb",
                    smb,
                    ("open_sessions", "open_trees", "open_handles"),
                ),
                *self._terminal_census_fields(
                    "network",
                    network,
                    (
                        "open_preparations",
                        "prepared_transactions",
                        "claimed_transactions",
                        "reserved_points",
                        "preparation_fences",
                        "reserved_deadlines",
                    ),
                ),
                *self._terminal_census_fields(
                    "lifecycle",
                    lifecycle,
                    (
                        "materialization_batch_transactions_pending",
                        "materialization_batch_transactions_unacknowledged",
                    ),
                ),
                *self._terminal_census_fields(
                    "lifecycle_action_cohort",
                    action_cohort,
                    (
                        "reservations",
                        "unclaimed_reservations",
                        "claimed_reservations",
                        "committing_reservations",
                        "reserved_keys",
                        "capability_locators",
                        "claimed_capability_locators",
                        "certified_authorization_locators",
                        "expected_receipt_authorities",
                        "pending_provenance_insertions",
                        "pending_provenance_evictions",
                    ),
                ),
                *self._terminal_census_fields(
                    "lifecycle_closed_transport",
                    closed_transport,
                    (
                        "reservations",
                        "claimed_reservations",
                        "reserved_keys",
                        "capability_locators",
                    ),
                ),
                *self._terminal_census_fields(
                    "lifecycle_service",
                    service,
                    (
                        "publication_reservations",
                        "closure_reservations",
                        "claimed_publications",
                        "claimed_closures",
                        "reserved_keys",
                        "capability_locators",
                    ),
                ),
                *self._terminal_census_fields(
                    "source_timing",
                    timing,
                    (
                        "active_claims",
                        "retained_plan_operations",
                    ),
                ),
                *self._terminal_census_fields(
                    "source_timing_detached",
                    detached_timing,
                    ("retained_bindings",),
                ),
                *self._terminal_census_fields(
                    "dispatcher_exact",
                    exact,
                    (
                        "unresolved_recoveries",
                        "reserved_recoveries",
                        "active_recoveries",
                    ),
                ),
                *self._terminal_census_fields(
                    "dispatcher_exact_authority",
                    exact.authority,
                    ("active_batches", "prepared_batches", "retained_rows", "retained_bytes"),
                ),
                *self._terminal_census_fields(
                    "dispatcher_cohort",
                    cohort,
                    (
                        "prepared_batches",
                        "claimed_batches",
                        "retained_members",
                        "retained_bytes",
                        "capability_locators",
                        "prepared_projections",
                        "projection_groups",
                        "projection_retained_bytes",
                    ),
                ),
            )
        )

    def assert_terminal_transient_state_drained(self) -> None:
        """Reject source finalization while any transient owner remains."""

        census = self.terminal_transient_owner_census()
        if census.nonzero:
            raise StateError(f"Terminal transient state is not drained: {census.nonzero!r}")

    def generate_email_message(
        self,
        *,
        spec: EmailMessageEventSpec,
        actor: "User",
        system: "System",
        time: datetime,
        activity: str = "",
        storyline_id: str = "",
    ) -> EmailDeliveryResult:
        """Generate SMTP delivery evidence for one modeled email message."""
        request = EmailDeliveryRequest(
            spec=spec,
            actor=actor,
            system=system,
            time=time,
            activity=activity,
            storyline_id=storyline_id,
        )
        return EmailDeliveryActionBundle(executor=self, request=request).execute()

    def generate_email_read(
        self,
        *,
        spec: Any,
        actor: "User",
        system: "System",
        time: datetime,
        activity: str = "",
        storyline_id: str = "",
    ) -> dict[str, Any]:
        """Generate opaque TLS mailbox access evidence for an email_read event."""
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("email_read requires environment.email to be configured")
        mailbox = (spec.mailbox or actor.email).lower()
        server_name = spec.server or self._email_server_for_user_address(mailbox)
        server_system = self._email_system_for_server_name(server_name)
        server_cfg = self._email_servers_by_name()[server_name]
        protocol = spec.protocol or ("owa" if server_cfg.platform == "exchange" else "imaps")
        uid = self.generate_email_access(
            user=actor,
            system=system,
            server=server_system,
            time=time,
            platform=server_cfg.platform,
            protocol=protocol,
            duration=spec.duration,
            user_agent=spec.user_agent or "",
            message_ids=tuple(spec.message_ids),
        )
        return {
            "mailbox": mailbox,
            "server": server_name,
            "protocol": protocol,
            "message_ids": list(spec.message_ids),
            "count": spec.count,
            "uid": uid,
        }

    def generate_email_access(
        self,
        *,
        user: "User",
        system: "System",
        server: "System",
        time: datetime,
        platform: str = "generic_smtp",
        protocol: str = "",
        duration: float | None = None,
        user_agent: str = "",
        message_ids: tuple[str, ...] = (),
    ) -> str:
        """Generate an opaque TLS mailbox access session."""
        request = EmailAccessRequest(
            user=user,
            system=system,
            server=server,
            time=time,
            platform=platform,
            protocol=protocol,
            duration=duration,
            user_agent=user_agent,
            message_ids=message_ids,
        )
        return EmailAccessActionBundle(executor=self, request=request).execute()

    def _execute_email_access_bundle(self, request: EmailAccessRequest) -> str:
        """Expand one lightweight mailbox read/access session into network evidence."""
        rng = random.Random(
            _stable_seed(
                "email_access:"
                f"{request.user.username}:{request.system.hostname}:"
                f"{request.server.hostname}:{request.time.isoformat()}"
            )
        )
        protocol = request.protocol or ("owa" if request.platform == "exchange" else "imaps")
        port = 443 if protocol == "owa" else 993
        service = "ssl"
        hostname = self._email_server_fqdn(request.server.hostname)
        process_image = self._email_access_process_image(
            request.system,
            protocol,
            request.user_agent,
            rng,
        )
        process_pid, resolved_process_image = self._ensure_email_client_process(
            user=request.user,
            system=request.system,
            time=request.time,
            image=process_image,
            command_line=self._email_access_process_command_line(
                process_image,
                protocol=protocol,
                server_hostname=hostname,
            ),
        )
        duration = request.duration or rng.uniform(12.0, 180.0)
        orig_bytes = rng.randint(1200, 9000)
        resp_bytes = rng.randint(15_000, 450_000)
        responding_pid = self._email_responding_process_pid(
            request.server,
            time=request.time,
            port=port,
        )
        uid = self.generate_connection(
            src_ip=request.system.ip,
            dst_ip=request.server.ip,
            time=request.time,
            dst_port=port,
            proto="tcp",
            service=service,
            duration=duration,
            orig_bytes=orig_bytes,
            resp_bytes=resp_bytes,
            conn_state="SF",
            emit_dns=True,
            source_system=request.system,
            pid=process_pid,
            hostname=hostname,
            process_image=resolved_process_image or process_image,
            suppress_source_pid_inference=process_pid <= 0,
            responding_pid=responding_pid,
        )
        if protocol == "imaps" and self._is_linux_mail_server(request.server):
            self._emit_dovecot_imap_syslog(
                user=request.user,
                client_system=request.system,
                server=request.server,
                time=request.time,
                duration=duration,
                orig_bytes=orig_bytes,
                resp_bytes=resp_bytes,
                message_ids=request.message_ids,
                master_pid=responding_pid,
            )
        return uid

    def _emit_dovecot_imap_syslog(
        self,
        *,
        user: "User",
        client_system: "System",
        server: "System",
        time: datetime,
        duration: float,
        orig_bytes: int,
        resp_bytes: int,
        message_ids: tuple[str, ...],
        master_pid: int,
    ) -> None:
        """Emit Dovecot auth/session companions for an observed IMAPS read."""
        seed = _stable_seed(
            "dovecot_imap:"
            f"{server.hostname}:{client_system.hostname}:{user.username}:{time.isoformat()}"
        )
        rng = random.Random(seed)
        worker_pid = self.state_manager.allocate_transient_linux_pid(
            server.hostname,
            time + timedelta(milliseconds=rng.randint(35, 140)),
            release_time=time + timedelta(seconds=duration + 1.0),
        )
        session_token = self._dovecot_session_token(seed)
        message_count = max(1, len(message_ids) or rng.randint(1, 6))
        hdr_count = max(message_count, rng.randint(message_count, message_count + 4))
        body_count = rng.randint(0, message_count)
        hdr_bytes = min(resp_bytes, hdr_count * rng.randint(650, 2200))
        body_bytes = max(0, resp_bytes - hdr_bytes - rng.randint(1200, 9000))
        login_time = self._smtp_lifecycle_time(time, duration, rng.uniform(0.03, 0.12))
        logout_time = self._smtp_lifecycle_time(time, duration, rng.uniform(0.84, 0.98))
        login_pid = master_pid if master_pid > 0 else None

        self.generate_syslog_event(
            server,
            login_time,
            "dovecot",
            (
                f"imap-login: Login: user=<{user.username}>, method=PLAIN, "
                f"rip={client_system.ip}, lip={server.ip}, mpid={worker_pid}, TLS, "
                f"session=<{session_token}>"
            ),
            pid=login_pid,
        )
        self.generate_syslog_event(
            server,
            logout_time,
            "dovecot",
            (
                f"imap({user.username})<{worker_pid}><{session_token}>: "
                f"Disconnected: Logged out in={orig_bytes} out={resp_bytes} "
                "deleted=0 expunged=0 trashed=0 "
                f"hdr_count={hdr_count} hdr_bytes={hdr_bytes} "
                f"body_count={body_count} body_bytes={body_bytes}"
            ),
            pid=worker_pid,
        )

    def _dovecot_session_token(self, seed: int) -> str:
        """Return a compact deterministic Dovecot-style session token."""
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        value = seed
        chars: list[str] = []
        while value and len(chars) < 11:
            value, remainder = divmod(value, len(alphabet))
            chars.append(alphabet[remainder])
        token = "".join(reversed(chars)).rjust(10, "A")
        return token[-11:]

    def _email_access_process_image(
        self,
        system: "System",
        protocol: str,
        user_agent: str,
        rng: random.Random,
    ) -> str:
        """Return lightweight client process attribution for mailbox reads."""
        os_category = _get_os_category(system.os)
        ua = user_agent.lower()
        if protocol == "owa":
            if os_category == "windows":
                return rng.choice(
                    [
                        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
                        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
                    ]
                )
            return rng.choice(["/usr/bin/firefox", "/usr/bin/chromium"])
        if "thunderbird" in ua:
            return (
                "/usr/bin/thunderbird"
                if os_category == "linux"
                else r"C:\Program Files\Mozilla Thunderbird\thunderbird.exe"
            )
        if os_category == "windows":
            return r"C:\Program Files\Microsoft Office\root\Office16\OUTLOOK.EXE"
        return "/usr/bin/thunderbird"

    def _email_access_process_command_line(
        self,
        image: str,
        *,
        protocol: str,
        server_hostname: str,
    ) -> str:
        """Return a source-plausible command line for mailbox access ownership."""
        exe_name = image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name in {"chrome.exe", "msedge.exe", "firefox", "firefox.exe", "chromium"}:
            scheme = "https"
            path = "/owa/" if protocol == "owa" else "/mail/"
            return (
                f'"{image}" {scheme}://{server_hostname}{path}'
                if "\\" in image
                else (f"{image} {scheme}://{server_hostname}{path}")
            )
        if "thunderbird" in exe_name:
            return f'"{image}" -mail' if "\\" in image else f"{image} -mail"
        if exe_name == "outlook.exe":
            return f'"{image}" /recycle'
        return image

    def _ensure_email_client_process(
        self,
        *,
        user: "User",
        system: "System",
        time: datetime,
        image: str,
        command_line: str,
    ) -> tuple[int, str | None]:
        """Create or reuse a user mail client process for endpoint flow attribution."""
        os_category = _get_os_category(system.os)
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user_at(user.username, time)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and _session_started_by(session, time)
        ]
        if os_category == "windows":
            sessions = [
                session
                for session in sessions
                if session.logon_type in _WINDOWS_INTERACTIVE_SESSION_LOGON_TYPES
            ]
        if not sessions:
            return -1, None
        session = max(sessions, key=lambda candidate: candidate.start_time)
        image_lower = image.lower()
        image_exe = image_lower.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]
        resident_mail_client = image_exe in {"outlook.exe", "thunderbird", "thunderbird.exe"}
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(system.hostname)
            if proc.username == user.username
            and proc.logon_id == session.logon_id
            and proc.image.lower() == image_lower
            and proc.start_time is not None
            and proc.start_time <= time
            and not self._foreground_process_expired_for_attribution(system, proc, time)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            self.state_manager.update_process_activity_time(system.hostname, proc.pid, time)
            return proc.pid, proc.image

        if resident_mail_client:
            singleton_key = self._singleton_application_key(
                system,
                user.username,
                session.logon_id,
                image,
            )
            provisional_end = (
                self.state_manager.get_session_end_time(session.logon_id) or self._scenario_end_time
            )
            if not self.claim_singleton_application_interval(
                singleton_key,
                ensure_utc(session.start_time),
                provisional_end,
            ):
                return -1, None

        rng = random.Random(
            _stable_seed(
                f"email_client_process:{system.hostname}:{user.username}:{image}:{time.isoformat()}"
            )
        )
        if resident_mail_client:
            process_time = ensure_utc(session.start_time) + timedelta(
                milliseconds=500
                + _stable_seed(
                    f"resident_mail_bootstrap:{system.hostname}:{user.username}:"
                    f"{session.logon_id}:{image}"
                )
                % 2500
            )
        else:
            lead_seconds = rng.uniform(3.0, 180.0)
            process_time = time - timedelta(seconds=lead_seconds)
        min_process_time = session.start_time + timedelta(milliseconds=500)
        if process_time < min_process_time:
            process_time = min_process_time
        if process_time >= time:
            process_time = time - timedelta(milliseconds=100)
        parent_pid = self._select_parent_pid(
            system,
            user,
            image,
            time=process_time,
            logon_id=session.logon_id,
        )
        pid = self.generate_process(
            user=user,
            system=system,
            time=process_time,
            logon_id=session.logon_id,
            process_name=image,
            command_line=command_line,
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            allow_existing_browser_reuse=False,
            allow_browser_launch_spacing=False,
        )
        self._record_user_process(system, user, pid, image)
        self.state_manager.update_process_activity_time(system.hostname, pid, time)
        self.state_manager.set_current_time(time)
        running = self.state_manager.get_process(system.hostname, pid)
        if running is not None:
            return pid, running.image
        return pid, image

    def _ensure_email_submission_session(
        self,
        *,
        actor: "User",
        system: "System",
        time: datetime,
    ) -> None:
        """Ensure a sender has an interactive session before SMTP client activity."""
        planner = getattr(self, "_world_planner", None)
        if planner is None:
            return
        rng = random.Random(
            _stable_seed(
                f"email_submission_session:{system.hostname}:{actor.username}:{time.isoformat()}"
            )
        )
        try:
            planner.ensure_user_session(
                actor,
                system,
                time,
                rng,
                session_kind="interactive",
                allow_existing=True,
                storyline_protected=True,
                required_until=time + timedelta(seconds=30),
            )
        except (KeyError, RuntimeError, ValueError) as exc:
            logger.debug(
                "Unable to bootstrap email submission session for %s@%s: %s",
                actor.username,
                system.hostname,
                exc,
            )

    def _email_source_process_attribution(
        self,
        *,
        actor: "User",
        src_system: "System",
        hop: dict[str, Any],
        time: datetime,
        user_agent: str,
    ) -> tuple[int, str | None]:
        """Return source PID/image ownership for SMTP submission or relay hops."""
        if "external_mail_server" in (src_system.roles or []):
            return -1, None
        if hop.get("submission"):
            self._ensure_email_submission_session(actor=actor, system=src_system, time=time)
            image = self._email_access_process_image(src_system, "smtp", user_agent, _get_rng())
            command_line = self._email_access_process_command_line(
                image,
                protocol="smtp",
                server_hostname=self._email_server_fqdn(hop["dst_system"].hostname),
            )
            return self._ensure_email_client_process(
                user=actor,
                system=src_system,
                time=time,
                image=image,
                command_line=command_line,
            )
        if hop.get("server_to_server"):
            if _get_os_category(src_system.os) == "linux":
                pid = self._ensure_email_mta_outbound_process(src_system, time=time)
                image = self._email_mta_outbound_process_image(src_system)
                return pid, image if pid > 0 else None
            pid = self._ensure_email_server_process(src_system, time=time, port=25)
            image = self._email_server_process_image(src_system, port=25)
            return pid, image if pid > 0 else None
        return -1, None

    def _email_responding_process_pid(
        self,
        system: "System",
        *,
        time: datetime,
        port: int,
    ) -> int:
        """Return destination-side mail service ownership for endpoint evidence."""
        if "external_mail_server" in (system.roles or []):
            return -1
        return self._ensure_email_server_process(system, time=time, port=port)

    def _email_server_process_image(self, system: "System", *, port: int) -> str:
        """Return platform-specific mail service process image for a local server."""
        os_category = _get_os_category(system.os)
        if os_category == "windows":
            if port == 443:
                return r"C:\Windows\System32\inetsrv\w3wp.exe"
            if port == 993:
                return r"C:\Program Files\Microsoft\Exchange Server\V15\Bin\Microsoft.Exchange.Imap4.exe"
            return r"C:\Program Files\Microsoft\Exchange Server\V15\Bin\EdgeTransport.exe"
        if port == 993:
            return "/usr/sbin/dovecot"
        if port == 443:
            return "/usr/sbin/nginx"
        return "/usr/lib/postfix/sbin/smtpd"

    def _email_server_command_line(self, image: str, *, port: int) -> str:
        """Return a stable service command line for a mail daemon process."""
        exe_name = image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
        if exe_name == "edgetransport.exe":
            return f'"{image}" -service'
        if exe_name == "microsoft.exchange.imap4.exe":
            return f'"{image}"'
        if exe_name == "w3wp.exe":
            return f'{image} -ap "MSExchangeOWAAppPool"'
        if exe_name == "smtp" and "postfix" in image:
            return f"{image} -t unix -u -c"
        if "postfix" in image:
            return f"{image} -n smtpd"
        if exe_name == "dovecot":
            return f"{image} -F"
        return image

    def _ensure_email_server_process(
        self,
        system: "System",
        *,
        time: datetime,
        port: int,
    ) -> int:
        """Create or reuse a local mail service process for flow ownership."""
        image = self._email_server_process_image(system, port=port)
        os_category = _get_os_category(system.os)
        profiled_worker: tuple[str, str] | None = None
        if os_category == "linux" and port not in {443, 993}:
            profiled_worker = ("postfix", "smtpd")
        elif os_category == "windows" and port == 443:
            profiled_worker = ("iis", "owa")
        if profiled_worker is not None:
            process_time = time - timedelta(
                seconds=random.Random(
                    _stable_seed(
                        f"email_server_process:{system.hostname}:{image}:{time.isoformat()}"
                    )
                ).uniform(30.0, 900.0)
            )
            if process_time >= time:
                process_time = time - timedelta(milliseconds=100)
            pid = self._ensure_profiled_service_worker(
                system=system,
                worker_time=process_time,
                activity_time=time,
                family_name=profiled_worker[0],
                worker_name=profiled_worker[1],
            )
            if pid > 0:
                self.state_manager.update_process_activity_time(system.hostname, pid, time)
                self.state_manager.set_current_time(time)
            return pid

        image_lower = image.lower()
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(system.hostname)
            if proc.image.lower() == image_lower
            and proc.start_time is not None
            and proc.start_time <= time
            and self._is_pid_active_at(system, proc.pid, time)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            self.state_manager.update_process_activity_time(system.hostname, proc.pid, time)
            return proc.pid

        sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        if os_category == "windows":
            username = "SYSTEM"
            parent_pid = sys_pids.get("services", sys_pids.get("wininit", 4))
        else:
            username = "dovecot" if port == 993 else "postfix"
            parent_pid = sys_pids.get("systemd", sys_pids.get("init", 1))
        process_time = time - timedelta(
            seconds=random.Random(
                _stable_seed(f"email_server_process:{system.hostname}:{image}:{time.isoformat()}")
            ).uniform(30.0, 900.0)
        )
        if process_time >= time:
            process_time = time - timedelta(milliseconds=100)
        pid = self.generate_system_process(
            system=system,
            time=process_time,
            process_name=image,
            command_line=self._email_server_command_line(image, port=port),
            parent_pid=parent_pid,
            username=username,
            emit_linux_syslog=False,
        )
        if pid > 0:
            self.state_manager.update_process_activity_time(system.hostname, pid, time)
            self.state_manager.set_current_time(time)
        return pid

    def _email_mta_outbound_process_image(self, system: "System") -> str:
        """Return the process image that owns outbound SMTP relay connections."""
        if _get_os_category(system.os) == "windows":
            return self._email_server_process_image(system, port=25)
        return "/usr/lib/postfix/sbin/smtp"

    def _sample_email_mta_outbound_process_lead_milliseconds(
        self,
        *,
        hostname: str,
        image: str,
        activity_time: datetime,
    ) -> int:
        """Sample one outbound-MTA process lead through the exact engine runtime."""

        runtime = self.timing_runtime
        if type(runtime) not in {TimingRuntime, SourceTimingPlanningRuntime}:
            raise StateError("Email MTA timing requires the exact engine-owned runtime")
        if (
            type(hostname) is not str
            or not hostname
            or type(image) is not str
            or not image
            or type(activity_time) is not datetime
        ):
            raise StateError("Email MTA timing scope must use exact built-in values")
        normalized_time = ensure_utc(activity_time)
        lifecycle_id = f"email-mta-outbound:{hostname}:{normalized_time.isoformat()}"
        sampled = runtime.sampler.sample_value(
            _email_mta_outbound_process_lead_distribution(),
            relationship_key="activity.email.mta_outbound_process_lead",
            scope=TimingScope(
                stable_id=f"{lifecycle_id}:{image}",
                host=hostname,
                source="email_mta",
                lifecycle_id=lifecycle_id,
            ),
            sample_key="process_lead_ms",
        )
        return int(sampled + 0.5)

    def _active_email_mta_outbound_process(
        self,
        *,
        system: "System",
        time: datetime,
    ) -> int | None:
        """Return the exact active Postfix SMTP worker without sampling timing."""

        family = service_process_family("postfix")
        manager_parent = self._profiled_service_manager_parent_pid(
            system=system,
            time=time,
            family=family,
        )
        manager_pid = self._active_profiled_service_process(
            system=system,
            time=time,
            spec=family.manager,
            parent_pid=manager_parent,
        )
        if manager_pid is None:
            return None
        return self._active_profiled_service_process(
            system=system,
            time=time,
            spec=family.workers["smtp"],
            parent_pid=manager_pid,
        )

    def _ensure_email_mta_outbound_process(
        self,
        system: "System",
        *,
        time: datetime,
    ) -> int:
        """Create or reuse the local MTA delivery process for outbound flow ownership."""
        image = self._email_mta_outbound_process_image(system)
        if image == self._email_server_process_image(system, port=25):
            return self._ensure_email_server_process(system, time=time, port=25)

        if _get_os_category(system.os) == "linux":
            active_pid = self._active_email_mta_outbound_process(system=system, time=time)
            if active_pid is not None:
                self.state_manager.update_process_activity_time(system.hostname, active_pid, time)
                self.state_manager.set_current_time(time)
                return active_pid
            process_time = time - timedelta(
                milliseconds=self._sample_email_mta_outbound_process_lead_milliseconds(
                    hostname=system.hostname,
                    image=image,
                    activity_time=time,
                )
            )
            if process_time >= time:
                process_time = time - timedelta(milliseconds=50)
            pid = self._ensure_profiled_service_worker(
                system=system,
                worker_time=process_time,
                activity_time=time,
                family_name="postfix",
                worker_name="smtp",
            )
            if pid > 0:
                self.state_manager.update_process_activity_time(system.hostname, pid, time)
                self.state_manager.set_current_time(time)
            return pid

        image_lower = image.lower()
        running_candidates = [
            proc
            for proc in self.state_manager.get_processes_on_system(system.hostname)
            if proc.image.lower() == image_lower
            and proc.start_time is not None
            and proc.start_time <= time
            and self._is_pid_active_at(system, proc.pid, time)
        ]
        if running_candidates:
            proc = max(running_candidates, key=lambda candidate: candidate.start_time)
            self.state_manager.update_process_activity_time(system.hostname, proc.pid, time)
            return proc.pid

        sys_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        parent_pid = sys_pids.get("systemd", sys_pids.get("init", 1))
        process_time = time - timedelta(
            milliseconds=self._sample_email_mta_outbound_process_lead_milliseconds(
                hostname=system.hostname,
                image=image,
                activity_time=time,
            )
        )
        if process_time >= time:
            process_time = time - timedelta(milliseconds=50)
        pid = self.generate_system_process(
            system=system,
            time=process_time,
            process_name=image,
            command_line=self._email_server_command_line(image, port=25),
            parent_pid=parent_pid,
            username="postfix",
            emit_linux_syslog=False,
        )
        if pid > 0:
            self.state_manager.update_process_activity_time(system.hostname, pid, time)
            self.state_manager.set_current_time(time)
        return pid

    def _load_email_corpus(self) -> dict[str, EmailCorpusEntry]:
        """Load and cache the optional scenario-created email corpus."""
        cached = getattr(self, "_email_corpus_cache", None)
        if cached is not None:
            return cached
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None or not email_config.corpus:
            self._email_corpus_cache = {}
            return {}
        from evidenceforge.utils.assets import load_email_corpus_yaml

        raw = (
            load_email_corpus_yaml(
                Path(getattr(self, "_scenario_root", Path.cwd())),
                email_config.corpus,
            )
            or {}
        )
        messages = raw.get("messages", raw if isinstance(raw, list) else [])
        if not isinstance(messages, list):
            raise ValueError("email_corpus.yaml must contain a top-level messages list")
        entries: dict[str, EmailCorpusEntry] = {}
        for idx, item in enumerate(messages):
            if not isinstance(item, dict):
                raise ValueError(f"email_corpus.yaml messages.{idx} must be a mapping")
            entry_id = str(item.get("id") or "").strip()
            if not entry_id:
                raise ValueError(f"email_corpus.yaml messages.{idx}.id is required")
            if entry_id in entries:
                raise ValueError(f"email_corpus.yaml duplicate message id: {entry_id}")
            subject = str(item.get("subject") or "").strip()
            body = str(item.get("body") or "")
            if not subject:
                raise ValueError(f"email_corpus.yaml message {entry_id!r} requires subject")
            if not body:
                raise ValueError(f"email_corpus.yaml message {entry_id!r} requires body")
            attachments = tuple(
                self._normalize_email_attachment(att, entry_id, index)
                for index, att in enumerate(item.get("attachments") or [])
            )
            headers_raw = item.get("headers") or {}
            if not isinstance(headers_raw, dict):
                raise ValueError(
                    f"email_corpus.yaml message {entry_id!r} headers must be a mapping"
                )
            entries[entry_id] = EmailCorpusEntry(
                entry_id=entry_id,
                subject=subject,
                body=body,
                user_agent=str(item.get("user_agent") or ""),
                headers={str(key): str(value) for key, value in headers_raw.items()},
                attachments=attachments,
                tags=tuple(str(tag) for tag in item.get("tags") or []),
                background=bool(item.get("background", False)),
                storyline=bool(item.get("storyline", True)),
            )
        self._email_corpus_cache = entries
        return entries

    def _email_corpus_entry(self, corpus_id: str | None) -> EmailCorpusEntry | None:
        """Return one corpus entry or fail clearly if the scenario references an unknown ID."""
        if not corpus_id:
            return None
        corpus = self._load_email_corpus()
        entry = corpus.get(corpus_id)
        if entry is None:
            raise ValueError(f"email_message corpus_id {corpus_id!r} was not found")
        return entry

    def _email_background_corpus_entries(self) -> list[EmailCorpusEntry]:
        """Return corpus entries eligible for deterministic background email."""
        return [entry for entry in self._load_email_corpus().values() if entry.background]

    @staticmethod
    def _normalize_email_attachment(
        attachment: Any,
        entry_id: str,
        index: int,
    ) -> dict[str, Any]:
        """Normalize one corpus attachment into EmailAttachmentSpec-compatible metadata."""
        if not isinstance(attachment, dict):
            raise ValueError(
                f"email_corpus.yaml message {entry_id!r} attachments.{index} must be a mapping"
            )
        filename = str(attachment.get("filename") or "").strip()
        if not filename:
            raise ValueError(
                f"email_corpus.yaml message {entry_id!r} attachments.{index}.filename is required"
            )
        content = attachment.get("content")
        size = attachment.get("size")
        if size is None:
            size = len(str(content or "").encode("utf-8"))
        return {
            "filename": filename,
            "content_type": str(attachment.get("content_type") or "application/octet-stream"),
            "size": int(size),
            "content": None if content is None else str(content),
        }

    def _execute_email_delivery_bundle(self, request: EmailDeliveryRequest) -> EmailDeliveryResult:
        """Expand one email message into DNS, SMTP, artifact, and manifest evidence."""
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("email_message requires environment.email to be configured")

        spec = request.spec
        rng = random.Random(
            _stable_seed(
                "email_message:"
                f"{request.storyline_id}:{request.actor.username}:"
                f"{request.system.hostname}:{request.time.isoformat()}:{spec.subject or ''}"
            )
        )
        corpus_entry = self._email_corpus_entry(spec.corpus_id)
        sender = (spec.sender or request.actor.email).lower()
        recipients_all = list(dict.fromkeys([*spec.to, *spec.cc, *spec.bcc]))
        envelope_recipients = [recipient.lower() for recipient in recipients_all]
        expanded_recipients = self._expand_email_recipients(recipients_all)
        subject = (
            spec.subject
            or (corpus_entry.subject if corpus_entry is not None else "")
            or self._deterministic_email_subject(sender, expanded_recipients, rng)
        )
        if corpus_entry is not None and not request.storyline_id and spec.subject is None:
            subject = self._contextualize_background_email_subject(
                subject,
                sender=sender,
                recipients=expanded_recipients,
                event_time=request.time,
            )
        if spec.body is not None:
            body = spec.body
        elif corpus_entry is not None:
            body = corpus_entry.body
            if not request.storyline_id:
                body = self._contextualize_background_email_body(
                    body,
                    subject=subject,
                    sender=sender,
                    recipients=expanded_recipients,
                )
        else:
            body = self._deterministic_email_body(
                subject,
                rng,
                sender=sender,
                recipients=expanded_recipients,
            )
        attachments = (
            [dict(attachment) for attachment in corpus_entry.attachments]
            if corpus_entry is not None
            else [att.model_dump() for att in spec.attachments]
        )
        artifact_id = spec.artifact_id or self._email_artifact_id(
            request.storyline_id,
            sender,
            expanded_recipients,
            request.time,
        )
        body = self._email_body_with_transport_footer(
            body,
            artifact_id=artifact_id,
            sender=sender,
            recipients=expanded_recipients,
        )
        corpus_user_agent = (
            corpus_entry.user_agent if corpus_entry is not None and request.storyline_id else ""
        )
        raw_user_agent = (
            spec.user_agent or corpus_user_agent or self._email_user_agent(request.system, rng)
        )
        user_agent = self._email_effective_user_agent(
            sender,
            raw_user_agent,
            system=request.system,
        )
        message_id = self._email_message_id(artifact_id, sender, user_agent)
        route = self._plan_email_route(sender, expanded_recipients, request.system)
        delivery_succeeded = spec.outcome == "delivered"
        if route and not delivery_succeeded:
            route = route[:1]
        if route and route[0].get("submission"):
            route[0]["recipients"] = envelope_recipients
        transport_body = body if delivery_succeeded else ""
        transport_attachments = attachments if delivery_succeeded else []
        transfer_sizes = self._smtp_transfer_sizes(
            message_id=message_id,
            body=transport_body,
            attachments=transport_attachments,
            route=route,
        )
        hop_times = self._email_smtp_hop_times(
            route=route,
            message_id=message_id,
            time=request.time,
            transfer_sizes=transfer_sizes,
        )
        date_header = self._email_date_header_for_route(
            route=route,
            sender=sender,
            message_id=message_id,
            time=request.time,
        )
        received_headers = self._received_headers_for_route(
            route=route,
            sender=sender,
            message_id=message_id,
            recipients=expanded_recipients,
            time=request.time,
            user_agent=user_agent,
            transfer_sizes=transfer_sizes,
            hop_times=hop_times,
        )
        email_ctx = EmailContext(
            message_id=message_id,
            artifact_id=artifact_id,
            envelope_from=sender,
            header_from=self._email_header_address(sender),
            to=[self._email_header_address(addr) for addr in spec.to],
            cc=[self._email_header_address(addr) for addr in spec.cc],
            bcc=list(spec.bcc),
            expanded_rcptto=expanded_recipients,
            subject=subject,
            date_header=date_header,
            user_agent=user_agent,
            body=body,
            body_size=len(body.encode("utf-8")),
            custom_headers=dict(corpus_entry.headers or {}) if corpus_entry is not None else {},
            attachments=attachments,
            verdict=spec.verdict,
            mail_action=spec.mail_action,
            outcome=spec.outcome,
            received_headers=received_headers,
            storyline_id=request.storyline_id,
        )
        smtp_uids: list[str] = []
        route_summary: list[dict[str, str]] = []
        sender_client_pid = -1

        self._emit_email_route_dns(route, request.time)

        for index, hop in enumerate(route):
            hop_time = hop_times[index]
            src_system = hop["src_system"]
            dst_system = hop["dst_system"]
            tls = self._smtp_hop_uses_starttls(
                hop=hop,
                src_system=src_system,
                dst_system=dst_system,
                message_id=message_id,
                hop_index=index,
                user_agent=user_agent,
            )
            delivery_reply = self._smtp_last_reply(
                outcome=spec.outcome,
                message_id=message_id,
                hop_index=index,
                src_system=src_system,
                dst_system=dst_system,
                submission=bool(hop["submission"]),
                queue_id=self._postfix_queue_id(message_id, dst_system)
                if self._is_linux_mail_server(dst_system)
                else "",
            )
            last_reply = delivery_reply
            if tls:
                last_reply = self._smtp_starttls_reply(
                    message_id=message_id,
                    hop_index=index,
                    src_system=src_system,
                    dst_system=dst_system,
                )
            mime_file_transfers = (
                self._email_mime_file_transfers(
                    artifact_id=artifact_id,
                    hop_index=index,
                    body=body,
                    attachments=attachments,
                    duration=rng.uniform(0.04, 0.4),
                )
                if delivery_succeeded and not tls
                else []
            )
            smtp_ctx = SmtpContext(
                helo=self._email_server_fqdn(src_system.hostname),
                mailfrom=sender,
                rcptto=hop.get("recipients")
                or (envelope_recipients if index == 0 else expanded_recipients),
                date=date_header,
                from_header=email_ctx.header_from,
                to_header=email_ctx.to,
                cc_header=email_ctx.cc,
                msg_id=message_id,
                subject=subject,
                last_reply=last_reply,
                path=self._smtp_observed_path(
                    route,
                    index,
                    sender=sender,
                    message_id=message_id,
                ),
                user_agent=user_agent,
                tls=tls,
                encrypted_message=tls,
                fuids=[file_transfer.fuid for file_transfer in mime_file_transfers],
            )
            ssl_ctx = (
                self._smtp_starttls_ssl_context(
                    src_system=src_system,
                    dst_system=dst_system,
                    message_id=message_id,
                    hop_index=index,
                    event_time=hop_time,
                    submission=bool(hop.get("submission")),
                    server_to_server=bool(hop.get("server_to_server")),
                )
                if tls
                else None
            )
            tls_presentation = (
                self._smtp_starttls_certificate_presentation(
                    ssl=ssl_ctx,
                    dst_system=dst_system,
                    message_id=message_id,
                    hop_index=index,
                    event_time=hop_time,
                )
                if ssl_ctx is not None
                else None
            )
            x509_chain = (
                self._tls_certificate_planner.x509_contexts(tls_presentation)
                if tls_presentation is not None
                else []
            )
            if ssl_ctx is not None and x509_chain:
                ssl_ctx = replace(
                    ssl_ctx,
                    cert_chain_fuids=tuple(cert.fuid for cert in x509_chain),
                )
            source_pid, source_process_image = self._email_source_process_attribution(
                actor=request.actor,
                src_system=src_system,
                hop=hop,
                time=hop_time,
                user_agent=user_agent,
            )
            if hop.get("submission") and source_pid > 0:
                sender_client_pid = source_pid
            responding_pid = self._email_responding_process_pid(
                dst_system,
                time=hop_time,
                port=587 if hop["submission"] else 25,
            )
            uid = self.generate_connection(
                src_ip=src_system.ip,
                dst_ip=dst_system.ip,
                time=hop_time,
                dst_port=587 if hop["submission"] else 25,
                proto="tcp",
                service="smtp",
                duration=transfer_sizes[index]["duration"],
                orig_bytes=transfer_sizes[index]["orig_bytes"],
                resp_bytes=transfer_sizes[index]["resp_bytes"],
                conn_state="SF",
                emit_dns=True,
                source_system=(
                    None if "external_mail_server" in (src_system.roles or []) else src_system
                ),
                pid=source_pid,
                hostname=self._email_server_fqdn(dst_system.hostname),
                process_image=source_process_image,
                email=email_ctx,
                smtp=smtp_ctx,
                ssl=ssl_ctx,
                x509=x509_chain[0] if x509_chain else None,
                x509_chain=x509_chain,
                tls_presentation=tls_presentation,
                file_transfers=mime_file_transfers,
                suppress_application_side_effects=True,
                responding_pid=responding_pid,
            )
            visible_uid = self._visible_network_uid_for_format(
                uid,
                src_ip=src_system.ip,
                dst_ip=dst_system.ip,
                format_name="zeek_smtp",
            )
            if uid:
                smtp_uids.append(visible_uid or uid)
            if delivery_succeeded:
                self._emit_email_mta_syslog(
                    route=route,
                    hop_index=index,
                    hop=hop,
                    time=hop_time,
                    duration=float(transfer_sizes[index]["duration"]),
                    message_id=message_id,
                    sender=sender,
                    actor=request.actor,
                    smtp=smtp_ctx,
                    delivery_reply=delivery_reply,
                    size=int(transfer_sizes[index]["message_size"]),
                    source_pid=source_pid,
                )
            else:
                self._emit_email_mta_reject_syslog(
                    hop=hop,
                    time=hop_time,
                    duration=float(transfer_sizes[index]["duration"]),
                    sender=sender,
                    smtp=smtp_ctx,
                )
            recipient_domains = sorted(
                {self._email_domain(address) for address in hop.get("recipients", [])}
            )
            route_summary.append(
                {
                    "src": src_system.hostname,
                    "dst": dst_system.hostname,
                    "src_fqdn": self._email_server_fqdn(src_system.hostname),
                    "dst_fqdn": self._email_server_fqdn(dst_system.hostname),
                    "port": str(587 if hop["submission"] else 25),
                    "tls": str(tls).lower(),
                    "routing_mode": str(hop.get("external_routing_mode") or "internal"),
                    "recipient_domains": ",".join(recipient_domains),
                    "uid": visible_uid,
                }
            )

        artifact_path = ""
        if delivery_succeeded and self._should_materialize_email_artifact(
            artifact_id, request.storyline_id
        ):
            artifact_path = self._write_email_artifact(email_ctx)
            email_ctx.artifact_path = artifact_path
        self._record_email_artifact_manifest(email_ctx, artifact_path)
        self._emit_sender_email_endpoint_artifacts(
            email_ctx=email_ctx,
            user=request.actor,
            system=request.system,
            time=request.time,
            pid=sender_client_pid,
        )
        self._maybe_generate_email_recipient_reads(
            email_ctx=email_ctx,
            delivery_time=request.time,
            rng=rng,
        )
        return EmailDeliveryResult(
            artifact_id=artifact_id,
            message_id=message_id,
            sender=sender,
            recipients=expanded_recipients,
            subject=subject,
            outcome=spec.outcome,
            artifact_path=artifact_path,
            smtp_uids=smtp_uids,
            route=route_summary,
        )

    def _email_server_fqdn(self, hostname: str) -> str:
        """Return a stable mail host FQDN for DNS/SMTP headers."""
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is not None:
            for server in email_config.mail_servers:
                if (
                    server.system == hostname
                    or server.name == hostname
                    or server.hostname == hostname
                ):
                    return server.hostname
        ad_domain = getattr(self, "_ad_domain", "")
        if ad_domain and "." not in hostname:
            return f"{hostname}.{ad_domain}"
        return hostname

    def _visible_network_uid_for_format(
        self,
        uid: str,
        *,
        src_ip: str,
        dst_ip: str,
        format_name: str,
    ) -> str:
        """Return the sensor-visible network UID for a rendered network format."""
        if not uid:
            return ""
        dispatcher = getattr(self, "dispatcher", None)
        identifier_lookup = getattr(dispatcher, "network_identifier_for_format", None)
        if callable(identifier_lookup):
            observed_uid = identifier_lookup(uid, format_name)
            if observed_uid is not None:
                return observed_uid
        visibility = getattr(dispatcher, "visibility_engine", None)
        if visibility is None:
            return uid
        visible_formats = visibility.get_log_formats_for_connection(src_ip, dst_ip)
        if format_name not in visible_formats:
            return ""
        sensors = visibility.get_observing_sensors(src_ip, dst_ip)
        for sensor in sensors:
            if format_name not in expand_formats(sensor.log_formats):
                continue
            return uid
        return uid

    @staticmethod
    def _email_domain(address: str) -> str:
        return address.rsplit("@", 1)[-1].lower().rstrip(".")

    @staticmethod
    def _email_header_address(address: str) -> str:
        return f"<{address.lower()}>"

    def _email_artifact_id(
        self,
        storyline_id: str,
        sender: str,
        recipients: list[str],
        time: datetime,
    ) -> str:
        seed = _stable_seed(
            f"email_artifact:{storyline_id}:{sender}:{','.join(recipients)}:{time.isoformat()}"
        )
        prefix = re.sub(r"[^a-zA-Z0-9_-]+", "-", storyline_id or "email").strip("-")[:40]
        return f"{prefix or 'email'}-{seed:012x}"

    def _email_message_id(self, artifact_id: str, sender: str, user_agent: str = "") -> str:
        domain = self._email_domain(sender)
        seed_hi = _stable_seed(f"email_message_id_hi:{artifact_id}:{sender}:{user_agent}")
        seed_lo = _stable_seed(f"email_message_id_lo:{artifact_id}:{sender}:{user_agent}")
        profile = self._email_mailer_profile(sender, user_agent)
        if profile == "thunderbird":
            return f"<{seed_hi}.{seed_lo % 1_000_000}.{seed_lo:08x}@{domain}>"
        if profile == "apple_mail":
            uuid_like = uuid.UUID(
                bytes=hashlib.sha256(
                    f"email-message-id:{artifact_id}:{sender}:{user_agent}:apple".encode()
                ).digest()[:16]
            )
            return f"<{str(uuid_like).upper()}@{domain}>"
        if profile == "service":
            token = re.sub(r"[^a-z0-9]+", "-", sender.split("@", 1)[0].lower()).strip("-")
            token = token or "notice"
            queue_fragment = seed_hi & 0xFFFFFFFF
            sequence_fragment = seed_lo % 10_000_000
            return f"<{token}-{queue_fragment:08x}-{sequence_fragment:07d}@{domain}>"
        rng = random.Random(_stable_seed(f"email_message_id_profile:{artifact_id}:{sender}"))
        local_label = re.sub(r"[^a-z0-9-]+", "-", sender.split("@", 1)[0].lower()).strip("-")
        local_label = (local_label or "mail")[:16]
        style = rng.randrange(3)
        if style == 0:
            uuid_like = uuid.UUID(
                bytes=hashlib.sha256(
                    f"email-message-id:{artifact_id}:{sender}:{user_agent}:outlook".encode()
                ).digest()[:16]
            )
            return f"<{str(uuid_like).upper()}@{domain}>"
        if style == 1:
            mailbox_id = 1000 + (seed_lo % 9000)
            left = self._base36_nonzero(seed_hi, 10)
            right = self._base36_nonzero(seed_lo >> 8, 7)
            return f"<{left}.{right}.{mailbox_id}@{local_label}.{domain}>"
        return f"<{self._base36_nonzero(seed_hi, 12)}.{self._base36_nonzero(seed_lo, 10)}@{domain}>"

    def _smtp_last_reply(
        self,
        *,
        outcome: str,
        message_id: str,
        hop_index: int,
        src_system: Any,
        dst_system: Any,
        submission: bool,
        queue_id: str = "",
    ) -> str:
        """Return a deterministic source-native SMTP DATA completion reply."""
        seed = _stable_seed(
            "smtp_last_reply:"
            f"{outcome}:{message_id}:{hop_index}:"
            f"{getattr(src_system, 'hostname', '')}:{getattr(dst_system, 'hostname', '')}:"
            f"{submission}"
        )
        rng = random.Random(seed)
        dst_hostname = getattr(dst_system, "hostname", "mail")
        dst_roles = set(getattr(dst_system, "roles", None) or [])
        dst_os = str(getattr(dst_system, "os", "")).lower()
        queue_hex = f"{seed & 0xFFFFFFFFFFFF:012X}"
        queue_short = f"{seed & 0xFFFFFFFFFF:010X}"
        internal_id = 100000000 + (seed % 800000000)
        if outcome != "delivered":
            replies = [
                "550 5.7.1 Message rejected",
                "550 5.7.1 Delivery not authorized",
                "554 5.7.1 Service unavailable; message refused",
                "550 5.1.1 Recipient address rejected",
            ]
            return replies[rng.randrange(len(replies))]

        if "external_mail_server" in dst_roles:
            exim_id = (
                f"{1 + seed % 2}"
                f"{self._base36(seed >> 8, 5)}-"
                f"{self._base36(seed >> 24, 6)}-"
                f"{self._base36(seed >> 40, 2)}"
            )
            replies = [
                f"250 OK id={exim_id}",
                f"250 2.0.0 Ok: queued as {queue_short}",
                f"250 2.0.0 {queue_hex[:8]} Message accepted for delivery",
            ]
            return replies[rng.randrange(len(replies))]

        if "windows" in dst_os or "server 20" in dst_os:
            replies = [
                f"250 2.6.0 {message_id} [InternalId={internal_id}] Queued mail for delivery",
                f"250 2.0.0 {queue_hex[:10]} Message accepted for delivery",
                f"250 2.1.5 {queue_short} queued for delivery",
            ]
            return replies[rng.randrange(len(replies))]

        if queue_id:
            replies = [
                f"250 2.0.0 Ok: queued as {queue_id}",
                f"250 2.0.0 {queue_id} Message accepted for delivery",
                f"250 2.0.0 queued as {queue_id} on {dst_hostname}",
            ]
            return replies[rng.randrange(len(replies))]

        replies = [
            f"250 2.0.0 Ok: queued as {queue_short}",
            f"250 2.0.0 {queue_hex[:8]} Message accepted for delivery",
            f"250 2.0.0 queued as {queue_short.lower()} on {dst_hostname}",
        ]
        return replies[rng.randrange(len(replies))]

    def _smtp_starttls_reply(
        self,
        *,
        message_id: str,
        hop_index: int,
        src_system: Any,
        dst_system: Any,
    ) -> str:
        """Return a deterministic pre-encryption STARTTLS server reply."""
        dst_hostname = getattr(dst_system, "hostname", "")
        dst_fqdn = self._email_server_fqdn(dst_hostname) if dst_hostname else "mail.local"
        dst_os = _get_os_category(getattr(dst_system, "os", ""))
        dst_roles = set(getattr(dst_system, "roles", ()) or ())
        server_seed = _stable_seed(
            f"smtp_starttls_server_profile:{dst_hostname}:{dst_os}:{','.join(sorted(dst_roles))}"
        )
        message_seed = _stable_seed(
            "smtp_starttls_reply:"
            f"{message_id}:{hop_index}:"
            f"{getattr(src_system, 'hostname', '')}:{dst_hostname}"
        )
        if "external_mail_server" in dst_roles:
            replies = [
                f"220 2.0.0 {dst_fqdn} ready for TLS",
                "220 2.0.0 TLS go ahead",
                "220 Go ahead with TLS",
                "220 2.0.0 Begin TLS negotiation",
                "220 2.0.0 STARTTLS command accepted",
                "220 Ready to negotiate TLS",
            ]
        elif dst_os == "linux":
            replies = [
                "220 2.0.0 Ready to start TLS",
                "220 2.0.0 TLS go ahead",
                f"220 2.0.0 {dst_fqdn} ready for TLS",
                "220 2.0.0 Begin TLS negotiation now",
                "220 2.0.0 STARTTLS accepted",
                "220 Ready to start TLS",
            ]
        elif dst_os == "windows":
            replies = [
                f"220 2.0.0 {dst_fqdn} Microsoft ESMTP MAIL Service ready for TLS",
                f"220 2.0.0 {dst_fqdn} Ready to start TLS",
                "220 2.0.0 STARTTLS accepted; continue",
                "220 2.0.0 TLS negotiation accepted",
                "220 2.0.0 Begin TLS negotiation",
                "220 2.0.0 Ready for TLS",
            ]
        else:
            replies = [
                "220 2.0.0 Ready to start TLS",
                "220 2.0.0 TLS go ahead",
                "220 2.0.0 STARTTLS accepted",
                "220 Ready to negotiate TLS",
            ]

        primary_index = server_seed % len(replies)
        if message_seed % 100 < 70:
            return replies[primary_index]
        alternate_offset = 1 + ((message_seed >> 8) % (len(replies) - 1))
        return replies[(primary_index + alternate_offset) % len(replies)]

    def _smtp_observed_path(
        self,
        route: list[dict[str, Any]],
        hop_index: int,
        *,
        sender: str = "",
        message_id: str = "",
    ) -> list[str]:
        """Return a Received-chain-like path visible before the current SMTP hop."""
        if hop_index <= 0:
            external_path = self._external_sender_observed_path(
                route=route,
                sender=sender,
                message_id=message_id,
            )
            if external_path:
                return external_path
            return []
        prior_hops = route[:hop_index]
        path = [hop["dst_system"].ip for hop in reversed(prior_hops)]
        first_source_ip = prior_hops[0]["src_system"].ip
        if first_source_ip not in path:
            path.append(first_source_ip)
        return path

    @staticmethod
    def _base36(value: int, width: int) -> str:
        """Return an uppercase base36 token padded to width characters."""
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        if value <= 0:
            token = "0"
        else:
            chars: list[str] = []
            while value:
                value, remainder = divmod(value, 36)
                chars.append(alphabet[remainder])
            token = "".join(reversed(chars))
        return token[-width:].rjust(width, "0")

    @staticmethod
    def _base36_nonzero(value: int, width: int) -> str:
        """Return a fixed-width base36 token that does not start with zero."""
        if width <= 1:
            return ActivityGenerator._base36(value or 1, max(width, 1))
        floor = 36 ** (width - 1)
        span = (36**width) - floor
        return ActivityGenerator._base36(floor + (value % span), width)

    @staticmethod
    def _email_mailer_profile(sender: str, user_agent: str) -> str:
        """Return a coarse source-native mailer profile for headers and IDs."""
        agent = user_agent.lower()
        local_part = sender.split("@", 1)[0].lower()
        domain = ActivityGenerator._email_domain(sender)
        if "thunderbird" in agent:
            return "thunderbird"
        if "apple mail" in agent:
            return "apple_mail"
        if any(marker in agent for marker in ("docflow", "mailer", "notification", "service")):
            return "service"
        if any(
            marker in local_part
            for marker in ("alert", "notice", "notification", "workspace", "billing", "support")
        ):
            return "service"
        if any(marker in domain for marker in ("service", "notify", "news", "vendor")):
            return "service"
        return "outlook"

    def _deterministic_email_subject(
        self,
        sender: str,
        recipients: list[str],
        rng: random.Random,
    ) -> str:
        verbs = [
            "Follow up",
            "Question",
            "Update",
            "Review",
            "Schedule",
            "Notes",
            "Revised",
            "Confirming",
            "Reminder",
            "Draft",
            "Closeout",
            "Heads up",
        ]
        nouns = [
            "request",
            "timeline",
            "access",
            "report",
            "meeting",
            "invoice",
            "renewal",
            "change window",
            "vendor packet",
            "forecast",
            "approval",
            "field note",
            "shipping date",
            "badge update",
            "service ticket",
            "training roster",
        ]
        qualifiers = [
            "today",
            "this week",
            "before review",
            "for closeout",
            "from yesterday",
            "for next steps",
            "after the call",
            "for the shared folder",
            "before noon",
        ]
        if recipients:
            domain = self._email_domain(recipients[0])
        else:
            domain = self._email_domain(sender)
        style = rng.randrange(4)
        if style == 0:
            return f"{rng.choice(verbs)}: {rng.choice(nouns)} for {domain.split('.')[0]}"
        if style == 1:
            return f"{rng.choice(nouns).title()} {rng.randint(1040, 9980)} {rng.choice(qualifiers)}"
        if style == 2:
            return f"{rng.choice(verbs)} {rng.choice(nouns)} - {rng.choice(qualifiers)}"
        return f"{domain.split('.')[0].title()} {rng.choice(nouns)} notes"

    def _deterministic_email_body(
        self,
        subject: str,
        rng: random.Random,
        *,
        sender: str = "",
        recipients: list[str] | None = None,
    ) -> str:
        openings = ["Hi,", "Hello,", "Good morning,", "Team,", "Good afternoon,", "All,"]
        closings = ["Thanks,", "Regards,", "Best,", "Thank you,", "Appreciate it,"]
        details = [
            "I added the latest notes to the shared folder.",
            "The owner list changed after this morning's sync.",
            "Please use the attached dates when you update your tracker.",
            "The vendor asked for confirmation before they close the item.",
            "I am waiting on one more answer, but the current version is usable.",
            "No action is needed if the numbers still match your copy.",
            "Please reply only if you see a mismatch in the current draft.",
            "This is mostly a reminder so the handoff does not get lost.",
        ]
        followups = [
            "I will check back after the next status call.",
            "The next update should be ready later today.",
            "We can fold any corrections into the Friday packet.",
            "I will leave the ticket open until everyone has confirmed.",
            "Please send changes directly to the group thread.",
            "I will archive the old copy once the update is approved.",
        ]
        recipient_domains = sorted({self._email_domain(address) for address in recipients or []})
        sender_domain = self._email_domain(sender) if sender else ""
        context_seed = _stable_seed(
            "email_body_context:"
            f"{sender}:{','.join(recipients or [])}:{subject}:{rng.random():.12f}"
        )
        context_rng = random.Random(context_seed)
        reference_terms = [
            "tracker",
            "handoff",
            "thread",
            "packet",
            "review",
            "queue",
            "folder",
            "ticket",
        ]
        reference = context_rng.choice(reference_terms)
        context_line = ""
        if sender_domain or recipient_domains:
            domain_hint = recipient_domains[0] if recipient_domains else sender_domain
            context_line = (
                f"I marked the {reference} with ref "
                f"{context_seed & 0xFFFF:04X}-{(context_seed >> 16) & 0xFFF:03X} "
                f"for the {domain_hint.split('.')[0]} follow-up."
            )
        return (
            f"{rng.choice(openings)}\n\n"
            f"Please see the note below regarding {subject.lower()}. "
            f"{rng.choice(details)} {context_line} {rng.choice(followups)}\n\n"
            f"{rng.choice(closings)}\n"
        )

    def _contextualize_background_email_body(
        self,
        body: str,
        *,
        subject: str,
        sender: str,
        recipients: list[str],
    ) -> str:
        """Add deterministic per-message context to reused background corpus bodies."""
        seed = _stable_seed(
            f"background_email_corpus_body:{sender}:{','.join(recipients)}:{subject}:{len(body)}"
        )
        recipient_domain = (
            self._email_domain(recipients[0]) if recipients else self._email_domain(sender)
        )
        context_line = (
            f"\nReference: {recipient_domain.split('.')[0].upper()}-"
            f"{seed & 0xFFFF:04X}-{(seed >> 16) & 0xFFF:03X}\n"
        )
        return body.rstrip() + context_line

    def _contextualize_background_email_subject(
        self,
        subject: str,
        *,
        sender: str,
        recipients: list[str],
        event_time: datetime,
    ) -> str:
        """Return a deterministic per-message subject variant for reused background corpus."""
        seed = _stable_seed(
            "background_email_corpus_subject:"
            f"{sender}:{','.join(recipients)}:{subject}:{event_time.isoformat()}"
        )
        rng = random.Random(seed)
        recipient_domain = (
            self._email_domain(recipients[0]) if recipients else self._email_domain(sender)
        )
        domain_label = recipient_domain.split(".", 1)[0].replace("-", " ").title()
        month_day = f"{event_time:%b} {event_time.day}"
        reference = f"{seed & 0xFFFF:04X}"
        variants = [
            f"{subject} - {domain_label} {reference}",
            f"{subject} ({month_day}, ref {reference})",
            f"Re: {subject} [{reference}]",
            f"{subject} / ref {reference}",
            f"{domain_label}: {subject} #{reference}",
        ]
        return variants[rng.randrange(len(variants))]

    def _email_body_with_transport_footer(
        self,
        body: str,
        *,
        artifact_id: str,
        sender: str,
        recipients: list[str],
    ) -> str:
        """Add deterministic mail-client/gateway footer text to rendered messages."""
        seed = _stable_seed(
            "email_transport_footer:"
            f"{artifact_id}:{sender}:{','.join(recipients)}:{len(body.encode('utf-8'))}"
        )
        rng = random.Random(seed)
        ref = f"{seed & 0xFFFF:04X}-{(seed >> 16) & 0xFFFFFF:06X}"
        org_label = self._email_domain(sender).split(".", 1)[0].upper() or "MAIL"
        confidentiality = rng.choice(
            [
                "This message may contain confidential business information intended only for the listed recipients.",
                "This email and any attachments are intended for the addressed recipients and may contain privileged information.",
                "If you received this message in error, please notify the sender and delete it from your mailbox.",
            ]
        )
        handling = rng.choice(
            [
                "Please do not forward externally without the document owner's approval.",
                "Use the current shared-folder copy as the record of authority for follow-up changes.",
                "Attachments are scanned by the company mail gateway before delivery.",
                "Reply in the existing thread so the mail archive keeps the approval trail together.",
            ]
        )
        classification = rng.choice(
            ["Internal", "Internal Use", "Business Confidential", "Company Restricted"]
        )
        footer_lines = [
            "-- ",
            f"{org_label} Mail Gateway ref {ref}",
            f"Classification: {classification}",
            confidentiality,
            handling,
        ]
        return body.rstrip() + "\n\n" + "\n".join(footer_lines) + "\n"

    def _email_user_agent(self, system: "System", rng: random.Random) -> str:
        os_category = _get_os_category(system.os)
        client_rng = random.Random(
            _stable_seed(
                "email_user_agent:"
                f"{system.hostname}:{getattr(system, 'assigned_user', '')}:{os_category}"
            )
        )
        if os_category == "windows":
            return client_rng.choice(
                [
                    "Microsoft Outlook 16.0",
                    "Microsoft Office Outlook 12.0",
                    "Microsoft Outlook 15.0",
                ]
            )
        return client_rng.choice(
            ["Thunderbird 115.0", "Evolution 3.44", "Apple Mail (2.3608.120.23.2.7)"]
        )

    def _email_effective_user_agent(
        self,
        sender: str,
        user_agent: str,
        *,
        system: Any | None = None,
    ) -> str:
        """Return a profile-compatible mailer fingerprint for generated/corpus mail."""
        profile = self._email_mailer_profile(sender, user_agent)
        if system is not None and profile in {"outlook", "apple_mail"}:
            os_category = _get_os_category(system.os)
            if os_category == "windows":
                return "Microsoft Outlook 16.0"
            if os_category == "linux":
                return "Thunderbird 115.0"
        if profile != "service":
            return user_agent
        agent = user_agent.lower()
        if not any(marker in agent for marker in ("outlook", "thunderbird", "apple mail")):
            return user_agent
        local_part = sender.split("@", 1)[0].lower()
        domain_label = self._email_domain(sender).split(".", 1)[0]
        label = re.sub(r"[^A-Za-z0-9]+", " ", local_part or domain_label).strip().title()
        label = label or "Notification"
        seed = _stable_seed(f"email_service_user_agent:{sender}")
        return f"{label} Mailer {2 + seed % 4}.{seed % 10}"

    def _smtp_hop_uses_starttls(
        self,
        *,
        hop: dict[str, Any],
        src_system: "System",
        dst_system: "System",
        message_id: str,
        hop_index: int,
        user_agent: str,
    ) -> bool:
        """Return whether a modeled SMTP hop upgrades to STARTTLS."""
        if hop["submission"]:
            return self._smtp_submission_uses_starttls(
                src_system=src_system,
                dst_system=dst_system,
                message_id=message_id,
                hop_index=hop_index,
                user_agent=user_agent,
            )
        return bool(
            hop["server_to_server"]
            and hop["src_server_attempts_starttls"]
            and hop["dst_server_allows_starttls"]
        )

    def _smtp_submission_uses_starttls(
        self,
        *,
        src_system: "System",
        dst_system: "System",
        message_id: str,
        hop_index: int,
        user_agent: str,
    ) -> bool:
        """Return realistic client-submission STARTTLS behavior."""
        if "external_mail_server" in (src_system.roles or []):
            return False
        os_category = _get_os_category(src_system.os)
        if os_category not in {"windows", "linux"}:
            return False
        agent = user_agent.lower()
        if any(marker in agent for marker in ("outlook", "thunderbird", "apple mail")):
            return True
        rng = random.Random(
            _stable_seed(
                "smtp_submission_starttls:"
                f"{src_system.hostname}:{dst_system.hostname}:{message_id}:{hop_index}"
            )
        )
        return rng.random() >= 0.08

    def _smtp_starttls_ssl_context(
        self,
        *,
        src_system: "System",
        dst_system: "System",
        message_id: str,
        hop_index: int,
        event_time: datetime,
        submission: bool = False,
        server_to_server: bool = True,
    ) -> SslContext:
        """Return Zeek SSL metadata for a successful SMTP STARTTLS upgrade."""
        rng = random.Random(
            _stable_seed(
                "smtp_starttls:"
                f"{src_system.hostname}:{dst_system.hostname}:{message_id}:{hop_index}"
            )
        )
        ssl_server_name = self._smtp_starttls_server_name(
            src_system=src_system,
            dst_system=dst_system,
            message_id=message_id,
            hop_index=hop_index,
            submission=submission,
            server_to_server=server_to_server,
        )
        cert_server_name = self._email_server_fqdn(dst_system.hostname)
        version = rng.choices(_TLS_VERSION_VALUES, weights=(70, 30), k=1)[0]
        if version == "TLSv13":
            cipher = rng.choices(_TLS13_CIPHER_VALUES, weights=_TLS13_CIPHER_WEIGHTS, k=1)[0]
        else:
            cert_profile = self._smtp_starttls_certificate_profile(
                ssl_server_name=cert_server_name,
                dst_system=dst_system,
                event_time=event_time,
            )
            cipher_values, cipher_weights = self._tls12_cipher_pool_for_key_type(
                str(cert_profile["key_type"])
            )
            cipher = rng.choices(cipher_values, weights=cipher_weights, k=1)[0]
        resumed = rng.random() < 0.12
        return SslContext(
            version=version,
            cipher=cipher,
            server_name=ssl_server_name,
            resumed=resumed,
            established=True,
            ssl_history=_choose_ssl_history(
                rng,
                tls_version=version,
                established=True,
                resumed=resumed,
            ),
        )

    def _smtp_starttls_server_name(
        self,
        *,
        src_system: "System",
        dst_system: "System",
        message_id: str,
        hop_index: int,
        submission: bool,
        server_to_server: bool,
    ) -> str:
        """Return the client-advertised SNI for SMTP STARTTLS, if any."""
        server_name = self._email_server_fqdn(dst_system.hostname)
        if submission:
            return server_name
        if not server_to_server:
            return server_name

        seed = _stable_seed(
            "smtp_starttls_sni:"
            f"{src_system.hostname}:{dst_system.hostname}:{message_id}:{hop_index}"
        )
        rng = random.Random(seed)
        src_roles = set(getattr(src_system, "roles", ()) or ())
        dst_roles = set(getattr(dst_system, "roles", ()) or ())
        if "external_mail_server" in src_roles or "external_mail_server" in dst_roles:
            include_probability = 0.46
        else:
            include_probability = 0.72
        return server_name if rng.random() < include_probability else ""

    def _smtp_starttls_certificate_chain(
        self,
        *,
        ssl: SslContext,
        dst_system: "System",
        message_id: str,
        hop_index: int,
        event_time: datetime,
    ) -> list[X509Context]:
        """Return X.509 projections for an SMTP TLS presentation."""

        presentation = self._smtp_starttls_certificate_presentation(
            ssl=ssl,
            dst_system=dst_system,
            message_id=message_id,
            hop_index=hop_index,
            event_time=event_time,
        )
        return (
            self._tls_certificate_planner.x509_contexts(presentation)
            if presentation is not None
            else []
        )

    def _smtp_starttls_certificate_presentation(
        self,
        *,
        ssl: SslContext,
        dst_system: "System",
        message_id: str,
        hop_index: int,
        event_time: datetime,
    ) -> TlsCertificatePresentationPlan | None:
        """Plan SMTP STARTTLS certificate evidence through the shared TLS owner."""

        if ssl.version == "TLSv13" or ssl.resumed:
            return None
        cert_profile = self._smtp_starttls_certificate_profile(
            ssl_server_name=ssl.server_name,
            dst_system=dst_system,
            event_time=event_time,
        )
        cert_name = str(cert_profile["cert_name"])
        issuer_cfg = cert_profile["issuer_cfg"]
        key_type = str(cert_profile["key_type"])
        key_length = int(cert_profile["key_length"])
        internal_cert_name = str(cert_profile["internal_cert_name"])
        san_dns = (
            tuple(dict.fromkeys([cert_name, cert_name.split(".", 1)[0]]))
            if internal_cert_name
            else tuple(_tls_san_dns_names(cert_name))
        )
        return self._tls_certificate_planner.plan(
            backend_identity=cert_name.rstrip(".").lower(),
            cert_name=cert_name,
            issuer_config=issuer_cfg,
            event_time=event_time,
            connection_identity=f"smtp-starttls:{message_id}:{hop_index}",
            key_type=key_type,
            key_size=key_length,
            san_dns=san_dns,
        )

    def _smtp_starttls_certificate_profile(
        self,
        *,
        ssl_server_name: str,
        dst_system: "System",
        event_time: datetime,
    ) -> dict[str, Any]:
        """Return the stable SMTP certificate profile used by SSL and X.509 evidence."""
        from evidenceforge.generation.activity.tls_issuers import pick_issuer, pick_key_type

        server_name = ssl_server_name or self._email_server_fqdn(dst_system.hostname)
        internal_cert_name = server_name if _is_private_ip(dst_system.ip) else ""
        cert_name = server_name or internal_cert_name or dst_system.ip
        cert_rng = random.Random(_stable_seed(f"tls_cert_profile:{cert_name}"))
        if internal_cert_name:
            issuer_cfg = _enterprise_tls_issuer(getattr(self, "_ad_domain", ""))
        elif _is_ip_literal(cert_name):
            issuer_cfg = _raw_ip_tls_issuer(cert_name)
        else:
            issuer_cfg = pick_issuer(cert_rng, server_name=cert_name, event_time=event_time)
        key_type, key_length = pick_key_type(cert_rng, issuer_cfg)
        key_type, key_length = _tls_key_for_certificate_name(cert_name, key_type, key_length)
        return {
            "cert_name": cert_name,
            "internal_cert_name": internal_cert_name,
            "issuer_cfg": issuer_cfg,
            "key_type": key_type,
            "key_length": key_length,
        }

    @staticmethod
    def _tls12_cipher_pool_for_key_type(key_type: str) -> tuple[tuple[str, ...], tuple[int, ...]]:
        """Return TLS 1.2 ciphers whose authentication algorithm matches the cert key."""
        needs_ecdsa = key_type == "ecdsa"
        matching = [
            (cipher, weight)
            for cipher, weight in _TLS12_CIPHER_DIST
            if ("_ECDSA_" in cipher) == needs_ecdsa
        ]
        if not matching:
            matching = list(_TLS12_CIPHER_DIST)
        return (
            tuple(cipher for cipher, _weight in matching),
            tuple(weight for _cipher, weight in matching),
        )

    def _emit_email_mta_syslog(
        self,
        *,
        route: list[dict[str, Any]],
        hop_index: int,
        hop: dict[str, Any],
        time: datetime,
        duration: float,
        message_id: str,
        sender: str,
        actor: "User",
        smtp: SmtpContext,
        delivery_reply: str,
        size: int,
        source_pid: int,
    ) -> None:
        """Emit source-native MTA lifecycle syslog companions for Linux mail hops."""
        src_system = hop["src_system"]
        dst_system = hop["dst_system"]
        if self._is_linux_mail_server(dst_system):
            downstream_recipients = self._email_route_future_recipients_from_system(
                route,
                hop_index,
                dst_system,
            )
            downstream_set = set(downstream_recipients)
            hop_recipients = self._postfix_recipient_list(hop.get("recipients") or smtp.rcptto)
            local_recipients = [
                recipient for recipient in hop_recipients if recipient not in downstream_set
            ]
            if not downstream_recipients and not local_recipients:
                local_recipients = hop_recipients
            queue_recipients = list(dict.fromkeys([*local_recipients, *downstream_recipients]))
            if not queue_recipients:
                queue_recipients = hop_recipients
            self._emit_postfix_receive_syslog(
                system=dst_system,
                peer_system=src_system,
                time=time,
                duration=duration,
                message_id=message_id,
                sender=sender,
                actor=actor,
                smtp=smtp,
                size=size,
                submission=bool(hop["submission"]),
                queue_recipients=queue_recipients,
                local_recipients=local_recipients,
                remove_after_local=not downstream_recipients,
            )
        if hop["server_to_server"] and self._is_linux_mail_server(src_system):
            self._emit_postfix_delivery_syslog(
                system=src_system,
                peer_system=dst_system,
                time=time,
                duration=duration,
                message_id=message_id,
                smtp=smtp,
                delivery_reply=delivery_reply,
                port=25,
                delivery_pid=source_pid if source_pid > 0 else None,
            )

    def _emit_email_mta_reject_syslog(
        self,
        *,
        hop: dict[str, Any],
        time: datetime,
        duration: float,
        sender: str,
        smtp: SmtpContext,
    ) -> None:
        """Emit receive-side MTA evidence for an SMTP transaction rejected before DATA."""
        dst_system = hop["dst_system"]
        if not self._is_linux_mail_server(dst_system):
            return
        src_system = hop["src_system"]
        smtpd_pid = self._email_responding_process_pid(
            dst_system,
            time=time,
            port=587 if hop["submission"] else 25,
        )
        peer_name = self._postfix_peer_name(src_system)
        connect_time = self._smtp_lifecycle_time(time, duration, 0.08)
        reject_time = self._smtp_lifecycle_time(time, duration, 0.42)
        recipient = self._postfix_recipient_list(smtp.rcptto)[:1]
        to_address = recipient[0] if recipient else "undisclosed-recipients"
        reply = self._postfix_reject_reply(
            smtp=smtp,
            src_system=src_system,
            dst_system=dst_system,
            time=reject_time,
        )
        self.generate_syslog_event(
            dst_system,
            connect_time,
            "postfix/smtpd",
            f"connect from {peer_name}[{src_system.ip}]",
            pid=smtpd_pid,
        )
        self.generate_syslog_event(
            dst_system,
            reject_time,
            "postfix/smtpd",
            (
                f"NOQUEUE: reject: RCPT from {peer_name}[{src_system.ip}]: {reply}; "
                f"from=<{sender}> to=<{to_address}> proto=ESMTP helo=<{smtp.helo}>"
            ),
            pid=smtpd_pid,
        )

    def _emit_postfix_receive_syslog(
        self,
        *,
        system: "System",
        peer_system: "System",
        time: datetime,
        duration: float,
        message_id: str,
        sender: str,
        actor: "User",
        smtp: SmtpContext,
        size: int,
        submission: bool,
        queue_recipients: list[str],
        local_recipients: list[str],
        remove_after_local: bool,
    ) -> None:
        """Emit Postfix receive-side syslog rows for one accepted SMTP hop."""
        queue_id = self._postfix_queue_id(message_id, system)
        smtpd_pid = self._email_responding_process_pid(
            system, time=time, port=587 if submission else 25
        )
        cleanup_pid = self._postfix_component_pid(system, "cleanup", time)
        qmgr_pid = self._postfix_component_pid(system, "qmgr", time)
        peer_name = self._postfix_peer_name(peer_system)
        recipients = self._postfix_recipient_list(queue_recipients or smtp.rcptto)
        connect_time = self._smtp_lifecycle_time(time, duration, 0.06)
        client_time = self._smtp_lifecycle_time(time, duration, 0.20)
        cleanup_time = max(
            self._smtp_lifecycle_time(time, duration, 0.38),
            client_time + timedelta(milliseconds=160),
        )
        active_time = max(
            self._smtp_lifecycle_time(time, duration, 0.64),
            cleanup_time + timedelta(milliseconds=220),
        )
        queue_state = self._postfix_queue_state(system, queue_id)
        queue_state["client_time"] = client_time
        queue_state["active_time"] = active_time
        queue_state["recipients"] = recipients
        queue_state.setdefault("delivered_recipients", set())
        queue_state["qmgr_pid"] = qmgr_pid

        self.generate_syslog_event(
            system,
            connect_time,
            "postfix/smtpd",
            f"connect from {peer_name}[{peer_system.ip}]",
            pid=smtpd_pid,
        )
        client_suffix = f", sasl_method=LOGIN, sasl_username={actor.username}" if submission else ""
        self.generate_syslog_event(
            system,
            client_time,
            "postfix/smtpd",
            f"{queue_id}: client={peer_name}[{peer_system.ip}]{client_suffix}",
            pid=smtpd_pid,
        )
        self.generate_syslog_event(
            system,
            cleanup_time,
            "postfix/cleanup",
            f"{queue_id}: message-id={message_id}",
            pid=cleanup_pid,
        )
        self.generate_syslog_event(
            system,
            active_time,
            "postfix/qmgr",
            (
                f"{queue_id}: from=<{sender}>, size={max(size, smtp.trans_depth)}, "
                f"nrcpt={len(recipients)} (queue active)"
            ),
            pid=qmgr_pid,
        )
        if local_recipients:
            local_pid = self._postfix_component_pid(system, "local", time)
            latest_delivery_time = active_time
            for offset, recipient in enumerate(local_recipients):
                delivery_time = max(
                    self._smtp_lifecycle_time(time, duration, 0.78 + 0.05 * offset),
                    active_time + timedelta(milliseconds=180 + (offset * 110)),
                )
                delay = self._postfix_delay_between(client_time, delivery_time)
                self.generate_syslog_event(
                    system,
                    delivery_time,
                    "postfix/local",
                    (
                        f"{queue_id}: to=<{recipient}>, relay=local, delay={delay}, "
                        f"delays={self._postfix_delays(delay, queue_id=queue_id, recipient=recipient, component='local')}, "
                        "dsn=2.0.0, "
                        "status=sent (delivered to maildir)"
                    ),
                    pid=local_pid,
                )
                self._postfix_mark_queue_recipient_delivered(queue_state, recipient)
                latest_delivery_time = delivery_time
            if remove_after_local:
                self._emit_postfix_removed(
                    system=system,
                    queue_id=queue_id,
                    qmgr_pid=qmgr_pid,
                    time=max(
                        self._smtp_lifecycle_time(time, duration, 0.88),
                        latest_delivery_time + timedelta(milliseconds=12),
                    ),
                    queue_state=queue_state,
                )
        elif remove_after_local:
            self.generate_syslog_event(
                system,
                self._smtp_lifecycle_time(time, duration, 0.88),
                "postfix/qmgr",
                f"{queue_id}: removed",
                pid=qmgr_pid,
            )
            queue_state["removed"] = True

    def _emit_postfix_delivery_syslog(
        self,
        *,
        system: "System",
        peer_system: "System",
        time: datetime,
        duration: float,
        message_id: str,
        smtp: SmtpContext,
        delivery_reply: str,
        port: int,
        delivery_pid: int | None = None,
    ) -> None:
        """Emit Postfix outbound delivery rows for one Linux relay hop."""
        queue_id = self._postfix_queue_id(message_id, system)
        smtp_pid = delivery_pid or self._postfix_component_pid(system, "smtp", time)
        qmgr_pid = self._postfix_component_pid(system, "qmgr", time)
        peer_name = self._email_server_fqdn(peer_system.hostname)
        recipients = self._postfix_recipient_list(smtp.rcptto)
        remote_reply = delivery_reply or smtp.last_reply or "250 2.0.0 Ok: queued for delivery"
        queue_state = self._postfix_queue_state(system, queue_id)
        queue_state.setdefault("recipients", recipients)
        queue_state.setdefault("delivered_recipients", set())
        start_time = queue_state.get("client_time")
        if not isinstance(start_time, datetime):
            start_time = time
        active_time = queue_state.get("active_time")
        if not isinstance(active_time, datetime):
            active_time = time
        latest_delivery_time = time
        for offset, recipient in enumerate(recipients):
            delivery_time = max(
                self._smtp_lifecycle_time(time, duration, 0.82 + 0.05 * offset),
                active_time + timedelta(milliseconds=240 + (offset * 140)),
            )
            delay = self._postfix_delay_between(start_time, delivery_time)
            self.generate_syslog_event(
                system,
                delivery_time,
                "postfix/smtp",
                (
                    f"{queue_id}: to=<{recipient}>, relay={peer_name}[{peer_system.ip}]:{port}, "
                    f"delay={delay}, "
                    f"delays={self._postfix_delays(delay, queue_id=queue_id, recipient=recipient, component='smtp')}, "
                    "dsn=2.0.0, "
                    f"status=sent ({remote_reply})"
                ),
                pid=smtp_pid,
            )
            self._postfix_mark_queue_recipient_delivered(queue_state, recipient)
            latest_delivery_time = delivery_time
        expected_recipients = set(queue_state.get("recipients") or recipients)
        delivered_recipients = set(queue_state.get("delivered_recipients") or set())
        if expected_recipients <= delivered_recipients:
            self._emit_postfix_removed(
                system=system,
                queue_id=queue_id,
                qmgr_pid=qmgr_pid,
                time=max(
                    self._smtp_lifecycle_time(time, duration, 0.92),
                    latest_delivery_time + timedelta(milliseconds=12),
                ),
                queue_state=queue_state,
            )

    @staticmethod
    def _email_route_future_recipients_from_system(
        route: list[dict[str, Any]],
        hop_index: int,
        system: "System",
    ) -> list[str]:
        """Return later recipients relayed by the same mail server queue."""
        hostname = str(system.hostname).lower()
        recipients: list[str] = []
        for future_hop in route[hop_index + 1 :]:
            future_src = future_hop.get("src_system")
            if str(getattr(future_src, "hostname", "")).lower() != hostname:
                continue
            recipients.extend(
                str(recipient).lower() for recipient in future_hop.get("recipients", [])
            )
        return list(dict.fromkeys(recipients))

    @staticmethod
    def _postfix_recipient_list(recipients: list[str] | tuple[str, ...] | None) -> list[str]:
        """Return a non-empty, source-normalized recipient list for queue accounting."""
        normalized = [
            str(recipient).lower() for recipient in (recipients or []) if str(recipient).strip()
        ]
        return list(dict.fromkeys(normalized)) or ["unknown"]

    def _postfix_queue_state(self, system: "System", queue_id: str) -> dict[str, Any]:
        """Return mutable lifecycle state for one Postfix queue on one host."""
        states: dict[tuple[str, str], dict[str, Any]] | None = getattr(
            self,
            "_postfix_queue_states",
            None,
        )
        if states is None:
            states = {}
            self._postfix_queue_states = states
        return states.setdefault((system.hostname, queue_id), {})

    @staticmethod
    def _postfix_mark_queue_recipient_delivered(
        queue_state: dict[str, Any],
        recipient: str,
    ) -> None:
        """Record that a queue recipient has a visible delivery row."""
        delivered = queue_state.setdefault("delivered_recipients", set())
        if not isinstance(delivered, set):
            delivered = set(delivered)
            queue_state["delivered_recipients"] = delivered
        delivered.add(recipient.lower())

    def _emit_postfix_removed(
        self,
        *,
        system: "System",
        queue_id: str,
        qmgr_pid: int,
        time: datetime,
        queue_state: dict[str, Any],
    ) -> None:
        """Emit a queue removal once all visible recipient deliveries have landed."""
        if queue_state.get("removed"):
            return
        self.generate_syslog_event(
            system,
            time,
            "postfix/qmgr",
            f"{queue_id}: removed",
            pid=qmgr_pid,
        )
        queue_state["removed"] = True

    @staticmethod
    def _is_linux_mail_server(system: "System") -> bool:
        """Return whether a system should produce Linux MTA syslog evidence."""
        return _get_os_category(system.os) == "linux" and (
            "mail_server" in (system.roles or []) or "smtp" in (system.services or [])
        )

    def _postfix_component_pid(self, system: "System", component: str, time: datetime) -> int:
        """Return a transient source-native PID for a Postfix helper process."""
        if component == "qmgr":
            cache = getattr(self, "_postfix_qmgr_pid_cache", None)
            if cache is None:
                cache = {}
                self._postfix_qmgr_pid_cache = cache
            cached_pid = cache.get(system.hostname)
            if cached_pid is not None:
                return cached_pid
            event_time = time + timedelta(
                milliseconds=_stable_seed(f"postfix_qmgr_pid:{system.hostname}") % 40
            )
            pid = self.state_manager.allocate_transient_linux_pid(
                system.hostname,
                event_time,
                release_time=self._scenario_end_time,
            )
            cache[system.hostname] = pid
            return pid
        seed = _stable_seed(f"postfix_component_pid:{system.hostname}:{component}:{time.date()}")
        event_time = time + timedelta(milliseconds=seed % 40)
        return self.state_manager.allocate_transient_linux_pid(
            system.hostname,
            event_time,
            release_time=event_time + timedelta(minutes=10),
        )

    def _postfix_queue_id(self, message_id: str, system: "System") -> str:
        """Return a stable Postfix-like queue identifier for a message on one server."""
        seed = _stable_seed(f"postfix_queue:{system.hostname}:{message_id}")
        width = 9 + (seed % 3)
        token = f"{seed:X}"
        if len(token) < width:
            token = token.rjust(width, "0")
        return token[-width:]

    def _postfix_peer_name(self, system: "System") -> str:
        """Return the peer label Postfix would show for an SMTP client/server."""
        return self._email_server_fqdn(system.hostname)

    def _postfix_reject_reply(
        self,
        *,
        smtp: SmtpContext,
        src_system: "System",
        dst_system: "System",
        time: datetime,
    ) -> str:
        """Return a source-native SMTP reject reply for Postfix RCPT rejections."""
        reply = str(smtp.last_reply or "").strip()
        if len(reply) >= 3 and reply[:3].isdigit() and reply[0] in {"4", "5"}:
            return reply

        recipients = ",".join(self._postfix_recipient_list(smtp.rcptto))
        seed = _stable_seed(
            "postfix_reject_reply:"
            f"{src_system.hostname}:{dst_system.hostname}:{smtp.mailfrom}:"
            f"{recipients}:{time.isoformat()}"
        )
        replies = [
            "550 5.7.1 Message rejected",
            "550 5.7.1 Delivery not authorized",
            "554 5.7.1 Service unavailable; message refused",
            "550 5.1.1 Recipient address rejected",
            "450 4.7.1 Client host rejected: try again later",
        ]
        return replies[seed % len(replies)]

    @staticmethod
    def _smtp_lifecycle_time(time: datetime, duration: float, fraction: float) -> datetime:
        """Return a syslog timestamp bounded inside the SMTP hop interval."""
        bounded_duration = max(0.25, duration)
        offset = max(0.015, min(bounded_duration - 0.015, bounded_duration * fraction))
        return time + timedelta(seconds=offset)

    @staticmethod
    def _postfix_delay(duration: float, offset: int = 0) -> str:
        """Return a compact Postfix delay value."""
        value = max(0.08, duration * 0.72 + offset * 0.04)
        return f"{value:.2f}".rstrip("0").rstrip(".")

    @staticmethod
    def _postfix_delay_between(start_time: datetime, end_time: datetime) -> str:
        """Return a Postfix delay value derived from visible queue lifecycle time."""
        value = max(0.01, (end_time - start_time).total_seconds())
        return f"{value:.2f}".rstrip("0").rstrip(".")

    @staticmethod
    def _postfix_delays(
        delay: str,
        *,
        queue_id: str = "",
        recipient: str = "",
        component: str = "",
    ) -> str:
        """Return a plausible Postfix delays tuple that sums near delay."""
        total = float(delay)
        floor = min(0.01, total / 8)
        seed = _stable_seed(f"postfix_delays:{queue_id}:{recipient}:{component}:{delay}")
        rng = random.Random(seed)
        weights = [
            rng.uniform(0.08, 0.35),
            rng.uniform(0.01, 0.18),
            rng.uniform(0.06, 0.45),
            rng.uniform(0.18, 0.70),
        ]
        remaining = max(0.0, total - floor * 4)
        weight_total = sum(weights)
        before_qmgr = floor + remaining * weights[0] / weight_total
        qmgr = floor + remaining * weights[1] / weight_total
        connection = floor + remaining * weights[2] / weight_total
        delivery = max(floor, total - before_qmgr - qmgr - connection)
        return f"{before_qmgr:.2f}/{qmgr:.2f}/{connection:.2f}/{delivery:.2f}"

    def _email_smtp_hop_times(
        self,
        *,
        route: list[dict[str, Any]],
        message_id: str,
        time: datetime,
        transfer_sizes: list[dict[str, float | int]],
    ) -> list[datetime]:
        """Return canonical SMTP hop start times shared by transport and headers."""
        if not route:
            return []
        schedule_rng = random.Random(_stable_seed(f"email_smtp_hop_schedule:{message_id}"))
        current = time + timedelta(seconds=schedule_rng.uniform(1.05, 1.75))
        hop_times: list[datetime] = []
        for index, _hop in enumerate(route):
            hop_times.append(current)
            duration = (
                float(transfer_sizes[index]["duration"])
                if index < len(transfer_sizes)
                else schedule_rng.uniform(0.8, 3.5)
            )
            gap_rng = random.Random(_stable_seed(f"email_smtp_hop_gap:{message_id}:{index}"))
            current = current + timedelta(seconds=max(0.15, duration) + gap_rng.uniform(0.65, 4.8))
        return hop_times

    def _smtp_transfer_sizes(
        self,
        *,
        message_id: str,
        body: str,
        attachments: list[dict[str, Any]],
        route: list[dict[str, Any]],
    ) -> list[dict[str, float | int]]:
        """Return deterministic SMTP transfer byte and duration estimates per route hop."""
        body_size = len(body.encode("utf-8"))
        attachment_size = sum(
            len(self._email_attachment_payload_bytes(attachment, message_id))
            for attachment in attachments
        )
        unique_recipients = list(
            dict.fromkeys(address for hop in route for address in hop["recipients"])
        )
        queued_message_base = max(
            600,
            body_size
            + attachment_size
            + sum(len(address) + 12 for address in unique_recipients)
            + 520,
        )
        sizes: list[dict[str, float | int]] = []
        for index, hop in enumerate(route):
            rng = random.Random(_stable_seed(f"smtp_transfer_size:{message_id}:{index}"))
            is_submission = bool(hop["submission"])
            is_external = bool(hop.get("external_hostname"))
            control_overhead = rng.randint(360, 920) + 70 * len(hop["recipients"])
            message_size = queued_message_base + rng.randint(80, 420) + index * rng.randint(18, 95)
            if is_submission:
                smtp_tls_overhead = rng.randint(700, 2600)
                orig_bytes = message_size + control_overhead + smtp_tls_overhead
                resp_bytes = rng.randint(260, 1300)
                duration = rng.uniform(0.45, 4.2)
            else:
                relay_overhead = rng.randint(900, 2600) if is_external else rng.randint(650, 1800)
                orig_bytes = message_size + control_overhead + relay_overhead
                resp_bytes = rng.randint(420, 2400)
                duration = rng.uniform(1.2, 8.5 if is_external else 5.5)
            sizes.append(
                {
                    "message_size": int(message_size),
                    "orig_bytes": int(orig_bytes),
                    "resp_bytes": int(resp_bytes),
                    "duration": round(float(duration), 6),
                }
            )
        return sizes

    def _email_servers_by_name(self) -> dict[str, Any]:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            return {}
        return {server.name: server for server in email_config.mail_servers}

    def _email_system_for_server_name(self, server_name: str) -> "System":
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        servers = self._email_servers_by_name()
        if server_name == "default" and email_config is not None:
            server_name = email_config.default_mailbox_servers[0]
        server = servers[server_name]
        for system in self._scenario_environment.systems:
            if system.hostname == server.system:
                return system
        raise ValueError(
            f"Email server {server_name!r} references unknown system {server.system!r}"
        )

    def _email_dns_system_for_hostname(self, hostname: str | None) -> "System | None":
        """Return the configured mail server system that owns an email DNS hostname."""
        if not hostname:
            return None
        wanted = hostname.lower().rstrip(".")
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            return None
        ad_domain = str(getattr(self, "_ad_domain", "") or "").lower().rstrip(".")
        generic_mail_aliases = {
            f"mail.{domain.lower().rstrip('.')}"
            for domain in getattr(email_config, "accepted_domains", [])
            if str(domain).strip()
        }
        if ad_domain:
            generic_mail_aliases.add(f"mail.{ad_domain}")
        if wanted in generic_mail_aliases:
            route_server_names = list(getattr(email_config, "inbound_route", []) or [])
            route_server_names.extend(
                name
                for name in getattr(email_config, "default_mailbox_servers", []) or []
                if name not in route_server_names
            )
            if not route_server_names and email_config.mail_servers:
                route_server_names.append(email_config.mail_servers[0].name)
            if route_server_names:
                return self._email_system_for_server_name(route_server_names[0])
        for server in email_config.mail_servers:
            candidates = {
                str(server.hostname).lower().rstrip("."),
                str(server.name).lower().rstrip("."),
                str(server.system).lower().rstrip("."),
            }
            if wanted in candidates:
                return self._email_system_for_server_name(server.name)
        return None

    def _email_server_for_user_address(self, address: str) -> str:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("environment.email is not configured")
        user = next(
            (
                candidate
                for candidate in self._scenario_environment.users
                if candidate.email.lower() == address.lower()
            ),
            None,
        )
        if user is not None:
            user_groups = set(user.groups or [])
            for override in email_config.mailbox_overrides:
                if override.group in user_groups:
                    return override.server
        seed = _stable_seed(f"email_mailbox_server:{address}")
        return email_config.default_mailbox_servers[
            seed % len(email_config.default_mailbox_servers)
        ]

    def _expand_email_recipients(self, recipients: list[str]) -> list[str]:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            return recipients
        groups = {group.address.lower(): group for group in email_config.distribution_groups}
        expanded: list[str] = []
        for recipient in recipients:
            group = groups.get(recipient.lower())
            if group is None:
                expanded.append(recipient.lower())
            else:
                expanded.extend(member.lower() for member in group.members)
        return list(dict.fromkeys(expanded))

    def _plan_email_route(
        self,
        sender: str,
        recipients: list[str],
        client_system: "System",
    ) -> list[dict[str, Any]]:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("environment.email is not configured")
        accepted_domains = set(email_config.accepted_domains)
        internal_recipients = [
            address for address in recipients if self._email_domain(address) in accepted_domains
        ]
        external_recipients = [
            address for address in recipients if self._email_domain(address) not in accepted_domains
        ]
        sender_is_internal = self._email_domain(sender) in accepted_domains
        if not sender_is_internal:
            inbound_server_name = (
                email_config.inbound_route[0]
                if email_config.inbound_route
                else self._email_server_for_user_address(internal_recipients[0])
            )
            inbound_system = self._email_system_for_server_name(inbound_server_name)
            external_mx = self._external_source_mail_system(sender)
            inbound_hop = self._email_hop(
                external_mx,
                inbound_system,
                submission=False,
                server_to_server=True,
                src_server_name="",
                dst_server_name=inbound_server_name,
                recipients=internal_recipients,
            )
            inbound_hop["external_routing_mode"] = "inbound"
            inbound_hop["src_server_attempts_starttls"] = self._external_sender_attempts_starttls(
                sender=sender,
                src_system=external_mx,
                dst_system=inbound_system,
            )
            route = [inbound_hop]
            sender_server_name = inbound_server_name
            sender_server_system = inbound_system
        else:
            sender_server_name = self._email_server_for_user_address(sender)
            sender_server_system = self._email_system_for_server_name(sender_server_name)
            route: list[dict[str, Any]] = [
                self._email_hop(
                    client_system,
                    sender_server_system,
                    submission=True,
                    server_to_server=False,
                    src_server_name="",
                    dst_server_name=sender_server_name,
                    recipients=recipients,
                )
            ]
        for server_name in sorted(
            {self._email_server_for_user_address(addr) for addr in internal_recipients}
        ):
            dst_system = self._email_system_for_server_name(server_name)
            if dst_system.ip != sender_server_system.ip:
                route.append(
                    self._email_hop(
                        sender_server_system,
                        dst_system,
                        submission=False,
                        server_to_server=True,
                        src_server_name=sender_server_name,
                        dst_server_name=server_name,
                        recipients=[
                            address
                            for address in internal_recipients
                            if self._email_server_for_user_address(address) == server_name
                        ],
                    )
                )
        if external_recipients:
            outbound_route = self._select_outbound_email_route(sender)
            outbound_server_name = self._select_outbound_email_server_from_route(
                sender,
                outbound_route,
                email_config,
            )
            outbound_system = self._email_system_for_server_name(outbound_server_name)
            if outbound_system.ip != sender_server_system.ip:
                merged = self._merge_email_route_hop_recipients(
                    route,
                    src_system=sender_server_system,
                    dst_system=outbound_system,
                    recipients=external_recipients,
                )
                if not merged:
                    route.append(
                        self._email_hop(
                            sender_server_system,
                            outbound_system,
                            submission=False,
                            server_to_server=True,
                            src_server_name=sender_server_name,
                            dst_server_name=outbound_server_name,
                            recipients=external_recipients,
                        )
                    )
            external_by_domain: dict[str, list[str]] = {}
            for recipient in external_recipients:
                external_by_domain.setdefault(self._email_domain(recipient), []).append(recipient)
            relay_hosts = list(outbound_route.isp_relays or email_config.isp_relays)
            for domain, domain_recipients in sorted(external_by_domain.items()):
                if relay_hosts:
                    relay_host = relay_hosts[
                        _stable_seed(f"email_isp_relay:{sender}:{domain}") % len(relay_hosts)
                    ]
                    route.append(
                        self._external_email_hop(
                            outbound_system,
                            relay_host,
                            outbound_server_name,
                            domain_recipients,
                            routing_mode="smart_host",
                        )
                    )
                    continue
                mx_host = self._external_mx_for_domain(domain)
                route.append(
                    self._external_email_hop(
                        outbound_system,
                        mx_host,
                        outbound_server_name,
                        domain_recipients,
                        routing_mode="mx",
                    )
                )
        return route

    @staticmethod
    def _merge_email_route_hop_recipients(
        route: list[dict[str, Any]],
        *,
        src_system: "System",
        dst_system: "System",
        recipients: list[str],
    ) -> bool:
        """Merge recipients into an existing same-hop SMTP transaction when possible."""
        for hop in route:
            if bool(hop.get("submission")):
                continue
            if not bool(hop.get("server_to_server")):
                continue
            hop_src = hop.get("src_system")
            hop_dst = hop.get("dst_system")
            if getattr(hop_src, "ip", None) != src_system.ip:
                continue
            if getattr(hop_dst, "ip", None) != dst_system.ip:
                continue
            hop["recipients"] = list(
                dict.fromkeys(
                    [
                        *(str(recipient).lower() for recipient in hop.get("recipients", [])),
                        *(str(recipient).lower() for recipient in recipients),
                    ]
                )
            )
            return True
        return False

    def _email_hop(
        self,
        src_system: "System",
        dst_system: "System",
        *,
        submission: bool,
        server_to_server: bool,
        src_server_name: str,
        dst_server_name: str,
        recipients: list[str],
    ) -> dict[str, Any]:
        servers = self._email_servers_by_name()
        src_cfg = servers.get(src_server_name)
        dst_cfg = servers.get(dst_server_name)
        return {
            "src_system": src_system,
            "dst_system": dst_system,
            "submission": submission,
            "server_to_server": server_to_server,
            "src_server_attempts_starttls": bool(
                src_cfg is not None and src_cfg.attempt_outbound_starttls
            ),
            "dst_server_allows_starttls": bool(
                dst_cfg is not None and dst_cfg.allow_inbound_starttls
            ),
            "external_hostname": "",
            "recipients": list(dict.fromkeys(address.lower() for address in recipients)),
        }

    def _external_email_hop(
        self,
        src_system: "System",
        dst_hostname: str,
        src_server_name: str,
        recipients: list[str],
        *,
        routing_mode: str,
    ) -> dict[str, Any]:
        servers = self._email_servers_by_name()
        src_cfg = servers.get(src_server_name)
        dst_hostname = public_safe_mail_hostname(dst_hostname)
        dst_ip = generate_public_mail_ip(f"email_external_mx:{dst_hostname}", dst_hostname)
        dst_system = type(src_system)(
            hostname=dst_hostname,
            ip=dst_ip,
            os="Internet SMTP Server",
            type="server",
            services=["smtp"],
            roles=["external_mail_server"],
        )
        return {
            "src_system": src_system,
            "dst_system": dst_system,
            "submission": False,
            "server_to_server": True,
            "src_server_attempts_starttls": bool(
                src_cfg is not None and src_cfg.attempt_outbound_starttls
            ),
            "dst_server_allows_starttls": True,
            "external_hostname": dst_hostname,
            "external_recipient_domain": self._email_domain(recipients[0]) if recipients else "",
            "external_routing_mode": routing_mode,
            "recipients": list(dict.fromkeys(address.lower() for address in recipients)),
        }

    def _external_sender_attempts_starttls(
        self,
        *,
        sender: str,
        src_system: "System",
        dst_system: "System",
    ) -> bool:
        """Return realistic inbound STARTTLS policy for an external sender MTA."""
        seed = _stable_seed(
            "external_sender_starttls:"
            f"{sender}:{getattr(src_system, 'hostname', '')}:{getattr(dst_system, 'hostname', '')}"
        )
        rng = random.Random(seed)
        domain = self._email_domain(sender)
        local_part = sender.split("@", 1)[0].lower()
        if any(marker in local_part for marker in ("notice", "workspace", "support", "alert")):
            return rng.random() < 0.48
        if any(marker in domain for marker in ("serviceportal", "docflow", "vendorpost")):
            return rng.random() < 0.46
        if any(marker in domain for marker in ("partner", "benefits", "customermail")):
            return rng.random() < 0.38
        return rng.random() < 0.32

    def _external_source_mail_system(self, sender: str) -> "System":
        domain = self._email_domain(sender)
        hostname = self._external_mx_for_domain(domain)
        return type(next(iter(self._scenario_environment.systems)))(
            hostname=hostname,
            ip=generate_public_mail_ip(f"email_external_sender:{sender}", hostname),
            os="Internet SMTP Server",
            type="server",
            services=["smtp"],
            roles=["external_mail_server"],
        )

    def _select_outbound_email_route(self, sender: str) -> Any:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("environment.email is not configured")
        user = next(
            (
                candidate
                for candidate in self._scenario_environment.users
                if candidate.email.lower() == sender.lower()
            ),
            None,
        )
        user_groups = set(user.groups if user is not None else [])
        selected = email_config.outbound_routes[0]
        for route in email_config.outbound_routes:
            if route.sender_groups and user_groups.intersection(route.sender_groups):
                selected = route
                break
            if route.name == "default" and not selected.sender_groups:
                selected = route
        return selected

    def _select_outbound_email_server_from_route(
        self,
        sender: str,
        route: Any,
        email_config: Any,
    ) -> str:
        servers = route.servers
        if servers == ["default"]:
            servers = email_config.default_mailbox_servers
        return servers[_stable_seed(f"email_outbound:{sender}") % len(servers)]

    def _select_outbound_email_server(self, sender: str) -> str:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            raise ValueError("environment.email is not configured")
        return self._select_outbound_email_server_from_route(
            sender,
            self._select_outbound_email_route(sender),
            email_config,
        )

    def _email_date_header_for_route(
        self,
        *,
        route: list[dict[str, Any]],
        sender: str,
        message_id: str,
        time: datetime,
    ) -> str:
        """Return a source-plausible Date header for the modeled sender."""
        if route and "external_mail_server" in (route[0]["src_system"].roles or []):
            sender_domain = public_safe_mail_hostname(self._email_domain(sender))
            rng = random.Random(_stable_seed(f"email_external_date:{sender_domain}:{message_id}"))
            date_time = time - timedelta(seconds=rng.uniform(95.0, 210.0))
            return date_time.strftime("%a, %d %b %Y %H:%M:%S +0000")
        return time.strftime("%a, %d %b %Y %H:%M:%S +0000")

    @staticmethod
    def _external_mx_for_domain(domain: str) -> str:
        safe = re.sub(r"[^a-z0-9.-]+", "", domain.lower()).strip(".")
        safe = public_safe_mail_hostname(safe)
        mx_answers = _public_dns_mx_answers(safe)
        if mx_answers:
            parts = mx_answers[0].split(maxsplit=1)
            if len(parts) == 2:
                return public_safe_mail_hostname(parts[1].rstrip("."))
        return f"mail.{safe}"

    def _received_headers_for_route(
        self,
        *,
        route: list[dict[str, Any]],
        sender: str,
        message_id: str,
        recipients: list[str],
        time: datetime,
        user_agent: str,
        transfer_sizes: list[dict[str, float | int]],
        hop_times: list[datetime],
    ) -> list[str]:
        headers: list[str] = []
        recipient_clause = f" for <{recipients[0]}>" if len(recipients) == 1 else ""
        for index, hop in enumerate(route):
            src_system = hop["src_system"]
            dst_system = hop["dst_system"]
            by_host = self._email_server_fqdn(hop["dst_system"].hostname)
            from_host = self._email_server_fqdn(hop["src_system"].hostname)
            from_ip = self._received_header_peer_ip(
                hop,
                src_system=src_system,
                dst_system=dst_system,
            )
            duration = (
                float(transfer_sizes[index]["duration"]) if index < len(transfer_sizes) else 1.0
            )
            hop_time = hop_times[index] if index < len(hop_times) else time
            received_time = self._smtp_lifecycle_time(hop_time, duration, 0.86)
            tls = self._smtp_hop_uses_starttls(
                hop=hop,
                src_system=src_system,
                dst_system=dst_system,
                message_id=message_id,
                hop_index=index,
                user_agent=user_agent,
            )
            transport_clause = self._received_header_transport_clause(
                hop,
                tls=tls,
                message_id=message_id,
                hop_index=index,
                dst_system=dst_system,
            )
            headers.insert(
                0,
                (
                    f"from {from_host} ({from_ip}) by {by_host} "
                    f"{transport_clause}{recipient_clause}; "
                    f"{received_time.strftime('%a, %d %b %Y %H:%M:%S +0000')}"
                ),
            )
        headers.extend(
            self._external_sender_received_headers(
                route=route,
                sender=sender,
                message_id=message_id,
                time=time,
            )
        )
        return headers

    def _received_header_peer_ip(
        self,
        hop: dict[str, Any],
        *,
        src_system: "System",
        dst_system: "System",
    ) -> str:
        """Return the source IP seen by the receiving MTA for a Received hop."""
        src_ip = str(src_system.ip)
        dst_roles = set(getattr(dst_system, "roles", ()) or ())
        if not bool(hop.get("server_to_server")):
            return src_ip
        if "external_mail_server" not in dst_roles and not hop.get("external_hostname"):
            return src_ip
        if not _is_modeled_local_ip(self, src_ip):
            return src_ip
        mapped_ip = self._outbound_nat_mapped_source_ip(src_ip, str(dst_system.ip))
        return mapped_ip or src_ip

    def _outbound_nat_mapped_source_ip(self, src_ip: str, dst_ip: str) -> str:
        """Return the first rule-selected outbound NAT source IP without consuming PAT state."""
        src_segments = self._network_segments_for_ip(src_ip)
        dst_segments = self._network_segments_for_ip(dst_ip)
        if dst_segments:
            return ""
        network = getattr(getattr(self, "_scenario_environment", None), "network", None)
        if network is None:
            return ""
        for sensor in getattr(network, "sensors", []) or []:
            if getattr(sensor, "type", "") != "firewall" or not getattr(sensor, "nat_rules", []):
                continue
            sensor_segments = set(getattr(sensor, "monitoring_segments", []) or [])
            if src_segments and not (sensor_segments & src_segments):
                continue
            for rule in sensor.nat_rules:
                mapped_ip = str(getattr(rule, "mapped_ip", "") or "")
                if not mapped_ip:
                    continue
                if getattr(rule, "type", "") == "dynamic_pat" and self._nat_rule_matches_source(
                    src_ip,
                    rule,
                    src_segments,
                ):
                    return mapped_ip
                if (
                    getattr(rule, "type", "") == "static"
                    and str(getattr(rule, "real_ip", "") or "") == src_ip
                ):
                    return mapped_ip
        return ""

    def _network_segments_for_ip(self, ip: str) -> set[str]:
        """Return scenario segment names containing an IP address."""
        visibility = getattr(getattr(self, "dispatcher", None), "visibility_engine", None)
        resolve_segments = getattr(visibility, "_resolve_ip_segments", None)
        if callable(resolve_segments):
            return set(resolve_segments(ip))

        network = getattr(getattr(self, "_scenario_environment", None), "network", None)
        if network is None:
            return set()
        try:
            address = ipaddress.ip_address(ip)
        except ValueError:
            return set()
        segments: set[str] = set()
        for segment in getattr(network, "segments", []) or []:
            try:
                if address in ipaddress.ip_network(segment.cidr, strict=False):
                    segments.add(str(segment.name))
            except ValueError:
                continue
        return segments

    @staticmethod
    def _nat_rule_matches_source(src_ip: str, rule: Any, src_segments: set[str]) -> bool:
        """Return whether a NAT rule source selector matches an IP."""
        try:
            address = ipaddress.ip_address(src_ip)
        except ValueError:
            return False
        for src_entry in getattr(rule, "src", []) or []:
            entry = str(src_entry)
            if entry in src_segments or entry == src_ip:
                return True
            try:
                if address in ipaddress.ip_network(entry, strict=False):
                    return True
            except ValueError:
                continue
        return False

    @staticmethod
    def _received_header_protocol(hop: dict[str, Any], *, tls: bool) -> str:
        """Return the source-native SMTP protocol label for a Received hop."""
        if hop.get("submission"):
            return "ESMTPSA" if tls else "ESMTPA"
        return "ESMTPS" if tls else "ESMTP"

    def _received_header_transport_clause(
        self,
        hop: dict[str, Any],
        *,
        tls: bool,
        message_id: str,
        hop_index: int,
        dst_system: "System",
    ) -> str:
        """Return the MTA-native transport clause for a Received header."""
        relay_id = self._received_header_relay_id(
            message_id=message_id,
            hop_index=hop_index,
            dst_system=dst_system,
        )
        if _get_os_category(dst_system.os) == "windows":
            return f"with Microsoft SMTP Server id {relay_id}"
        protocol = self._received_header_protocol(hop, tls=tls)
        return f"with {protocol} id {relay_id}"

    def _received_header_relay_id(
        self,
        *,
        message_id: str,
        hop_index: int,
        dst_system: "System",
    ) -> str:
        """Return a relay token shaped by the receiving MTA family."""
        os_category = _get_os_category(dst_system.os)
        if os_category == "linux":
            return self._postfix_queue_id(message_id, dst_system)
        seed = _stable_seed(f"received:{message_id}:{hop_index}:{dst_system.hostname}")
        if os_category == "windows":
            exchange_builds = (
                (15, 2, 1118, 7),
                (15, 2, 1258, 12),
                (15, 2, 1544, 4),
                (15, 2, 1748, 10),
                (15, 2, 2214, 13),
                (15, 1, 2507, 6),
                (15, 1, 2686, 8),
            )
            major, minor, build, revision_base = exchange_builds[seed % len(exchange_builds)]
            revision = revision_base + ((seed >> 24) % 12)
            return f"{major}.{minor}.{build}.{revision}"
        return self._base36(seed, 10)

    def _external_sender_received_headers(
        self,
        *,
        route: list[dict[str, Any]],
        sender: str,
        message_id: str,
        time: datetime,
    ) -> list[str]:
        """Return stable pre-recipient Received headers for inbound public mail."""
        if not route:
            return []
        first_hop = route[0]
        src_system = first_hop["src_system"]
        if "external_mail_server" not in (src_system.roles or []):
            return []

        edge_host = self._email_server_fqdn(src_system.hostname)
        edge_ip = src_system.ip
        sender_domain = public_safe_mail_hostname(self._email_domain(sender))
        rng = random.Random(_stable_seed(f"email_external_received:{sender_domain}:{message_id}"))
        upstream_hops = self._external_sender_public_hops(
            sender=sender,
            message_id=message_id,
        )

        edge_time = time - timedelta(seconds=rng.uniform(14.0, 55.0))
        headers: list[str] = []
        receiver_host = edge_host
        receiver_ip = edge_ip
        received_time = edge_time
        for index, hop in enumerate(upstream_hops):
            relay_id = _stable_seed(f"received-external-hop:{message_id}:{index}") & 0xFFFFFFFF
            protocol = (
                "ESMTPSA" if index == len(upstream_hops) - 1 and rng.random() < 0.18 else "ESMTPS"
            )
            headers.append(
                f"from {hop['host']} ({hop['ip']}) by {receiver_host} ({receiver_ip}) "
                f"with {protocol} id {relay_id:08x}; "
                f"{received_time.strftime('%a, %d %b %Y %H:%M:%S +0000')}"
            )
            receiver_host = str(hop["host"])
            receiver_ip = str(hop["ip"])
            received_time -= timedelta(seconds=rng.uniform(4.0, 26.0))
        return headers

    def _external_sender_observed_path(
        self,
        *,
        route: list[dict[str, Any]],
        sender: str,
        message_id: str,
    ) -> list[str]:
        """Return the visible upstream public relay path for an inbound SMTP hop."""
        if not route:
            return []
        first_hop = route[0]
        src_system = first_hop["src_system"]
        if "external_mail_server" not in (src_system.roles or []):
            return []
        return [
            str(hop["ip"])
            for hop in self._external_sender_public_hops(sender=sender, message_id=message_id)
        ]

    def _external_sender_public_hops(
        self,
        *,
        sender: str,
        message_id: str,
    ) -> list[dict[str, str]]:
        """Return upstream public SMTP hops ordered newest to oldest."""
        sender_domain = public_safe_mail_hostname(self._email_domain(sender))
        local_part = sender.split("@", 1)[0].lower()
        preserve_app_host = self._email_mailer_profile(sender, "") == "service"
        rng = random.Random(_stable_seed(f"email_external_received:{sender_domain}:{message_id}"))
        app_prefixes = (
            ["notify", "worker", "app", "mailer"]
            if any(marker in local_part for marker in ("notice", "workspace", "alert", "support"))
            else ["smtp", "mail", "relay", "outbound"]
        )
        app_label = re.sub(r"[^a-z0-9-]+", "-", local_part).strip("-")[:18] or "mailer"
        app_host = rng.choice(
            [
                f"{rng.choice(app_prefixes)}-{1 + rng.randrange(6):02d}.{sender_domain}",
                f"{app_label}-app-{1 + rng.randrange(8):02d}.{sender_domain}",
                f"worker{1 + rng.randrange(8)}.{sender_domain}",
            ]
        )
        mta_host = rng.choice(
            [
                f"mailout-{1 + rng.randrange(4):02d}.{sender_domain}",
                f"smtp-out-{1 + rng.randrange(4):02d}.{sender_domain}",
                f"mta{1 + rng.randrange(4)}.{sender_domain}",
                f"mx-relay-{1 + rng.randrange(6):02d}.{sender_domain}",
            ]
        )
        hops = [
            {
                "host": mta_host,
                "ip": generate_public_mail_ip(
                    f"email_external_received_mta:{sender_domain}:{message_id}",
                    mta_host,
                ),
            },
            {
                "host": app_host,
                "ip": generate_public_mail_ip(
                    f"email_external_received_app:{sender_domain}:{message_id}",
                    app_host,
                ),
            },
        ]
        if rng.random() < 0.42:
            transit_host = rng.choice(
                [
                    f"inbound-{1 + rng.randrange(6):02d}.{sender_domain}",
                    f"edge-mta-{1 + rng.randrange(5):02d}.{sender_domain}",
                    f"relaypool-{1 + rng.randrange(7):02d}.{sender_domain}",
                ]
            )
            hops.insert(
                0,
                {
                    "host": transit_host,
                    "ip": generate_public_mail_ip(
                        f"email_external_received_transit:{sender_domain}:{message_id}",
                        transit_host,
                    ),
                },
            )
        for hop in hops:
            ptr_name = public_mail_ptr_name(hop["ip"], hop["host"])
            if (
                ptr_name
                and not (preserve_app_host and hop["host"] == app_host)
                and rng.random() < 0.62
            ):
                hop["host"] = ptr_name
        return hops

    def _emit_email_route_dns(
        self,
        route: list[dict[str, Any]],
        time: datetime,
    ) -> None:
        for index, hop in enumerate(route):
            source_system = hop["src_system"]
            if not _is_modeled_local_ip(self, source_system.ip):
                continue
            resolver_ips = self._dns_resolver_ips_for_source(source_system.ip)
            if not resolver_ips:
                continue
            resolver_ip = resolver_ips[0]
            dst_host = hop.get("external_hostname") or self._email_server_fqdn(
                hop["dst_system"].hostname
            )
            qtype = (
                "MX"
                if hop.get("external_hostname") and hop.get("external_routing_mode") != "smart_host"
                else "A"
            )
            answer = dst_host if qtype == "MX" else hop["dst_system"].ip
            dns_rng = random.Random(
                _stable_seed(
                    "email_route_dns:"
                    f"{source_system.ip}:{resolver_ip}:{dst_host}:{qtype}:{time.isoformat()}"
                )
            )
            query = (
                str(hop.get("external_recipient_domain") or self._email_domain(dst_host))
                if qtype == "MX"
                else dst_host
            )
            dns_ctx = DnsContext(
                query=query,
                trans_id=dns_rng.randint(1, 65535),
                query_type=qtype,
                qtype=15 if qtype == "MX" else 1,
                rcode="NOERROR",
                rcode_num=0,
                answers=[f"10 {answer}" if qtype == "MX" else answer],
                TTLs=[float(dns_rng.choice([300, 450, 600, 900, 1200]))],
                rtt=round(dns_rng.uniform(0.0022, 0.012), 6),
            )
            self.generate_connection(
                src_ip=source_system.ip,
                dst_ip=resolver_ip,
                time=time - timedelta(seconds=max(0.1, 2.0 - index * 0.1)),
                dst_port=53,
                proto="udp",
                service="dns",
                duration=dns_ctx.rtt,
                orig_bytes=60,
                resp_bytes=120,
                conn_state="SF",
                dns=dns_ctx,
                source_system=source_system,
                suppress_application_side_effects=True,
            )
            if qtype == "MX":
                a_ctx = DnsContext(
                    query=answer,
                    trans_id=dns_rng.randint(1, 65535),
                    query_type="A",
                    qtype=1,
                    rcode="NOERROR",
                    rcode_num=0,
                    answers=[hop["dst_system"].ip],
                    TTLs=[float(dns_rng.choice([300, 450, 600, 900, 1200]))],
                    rtt=round(dns_rng.uniform(0.0025, 0.014), 6),
                )
                self.generate_connection(
                    src_ip=source_system.ip,
                    dst_ip=resolver_ip,
                    time=time - timedelta(seconds=max(0.05, 1.0 - index * 0.1)),
                    dst_port=53,
                    proto="udp",
                    service="dns",
                    duration=a_ctx.rtt,
                    orig_bytes=60,
                    resp_bytes=120,
                    conn_state="SF",
                    dns=a_ctx,
                    source_system=source_system,
                    suppress_application_side_effects=True,
                )

    def _email_mime_file_transfers(
        self,
        *,
        artifact_id: str,
        hop_index: int,
        body: str,
        attachments: list[dict[str, Any]],
        duration: float,
    ) -> list[FileTransferContext]:
        """Return Zeek files.log metadata for all visible SMTP MIME parts."""
        parts: list[dict[str, Any]] = [
            {
                "name": "",
                "mime_type": "text/plain",
                "content": body,
                "size": len(body.encode("utf-8")),
            }
        ]
        for attachment in attachments:
            payload = self._email_attachment_payload_bytes(attachment, artifact_id)
            parts.append(
                {
                    "name": str(attachment.get("filename") or "attachment.bin"),
                    "mime_type": str(attachment.get("content_type") or "application/octet-stream"),
                    "payload": payload,
                    "size": len(payload),
                }
            )
        transfers: list[FileTransferContext] = []
        for depth, part in enumerate(parts):
            content_seed = f"email-mime:{artifact_id}:{depth}:{part['name']}:{part['mime_type']}"
            observation_seed = f"{content_seed}:hop:{hop_index}"
            payload = part.get("payload")
            if payload is None:
                payload = str(part.get("content") or "").encode("utf-8")
            size = max(0, int(part["size"]))
            analyzers = ["MD5", "SHA1", "SHA256"]
            transfers.append(
                FileTransferContext(
                    fuid=f"F{_stable_seed(observation_seed):017x}"[:18],
                    source="SMTP",
                    depth=depth,
                    filename=str(part["name"]),
                    analyzers=analyzers,
                    mime_type=str(part["mime_type"]),
                    duration=max(0.001, duration * (1.0 + depth * 0.15)),
                    local_orig=True,
                    is_orig=True,
                    seen_bytes=size,
                    total_bytes=size,
                    missing_bytes=0,
                    overflow_bytes=0,
                    timedout=False,
                    md5=hashlib.md5(payload, usedforsecurity=False).hexdigest(),
                    sha1=hashlib.sha1(payload, usedforsecurity=False).hexdigest(),
                    sha256=hashlib.sha256(payload).hexdigest(),
                )
            )
        return transfers

    @staticmethod
    def _email_attachment_payload_bytes(
        attachment: dict[str, Any],
        artifact_id: str,
    ) -> bytes:
        """Return the canonical bytes for an email attachment payload."""
        content = attachment.get("content")
        if content is not None:
            return str(content).encode("utf-8")
        size = max(0, int(attachment.get("size") or 0))
        if size == 0:
            return b""
        if ActivityGenerator._email_attachment_is_openxml_office(attachment):
            return ActivityGenerator._openxml_office_attachment_bytes(attachment, artifact_id, size)
        seed = (
            f"email-attachment:{artifact_id}:"
            f"{attachment.get('filename') or 'attachment.bin'}:"
            f"{attachment.get('content_type') or 'application/octet-stream'}"
        ).encode()
        repeats = (size // len(seed)) + 1
        return (seed * repeats)[:size]

    @staticmethod
    def _email_attachment_is_openxml_office(attachment: dict[str, Any]) -> bool:
        """Return whether attachment metadata claims an OpenXML Office container."""
        filename = str(attachment.get("filename") or "").lower()
        content_type = str(attachment.get("content_type") or "").lower()
        return filename.endswith((".docx", ".pptx", ".xlsx", ".xlsm")) or any(
            marker in content_type
            for marker in (
                "openxmlformats-officedocument",
                "application/vnd.ms-excel.sheet.macroenabled",
            )
        )

    @staticmethod
    def _openxml_office_attachment_bytes(
        attachment: dict[str, Any],
        artifact_id: str,
        requested_size: int,
    ) -> bytes:
        """Return deterministic Office-like OOXML bytes for generated binary attachments."""
        filename = str(attachment.get("filename") or "attachment.xlsx").lower()
        is_macro_workbook = (
            filename.endswith(".xlsm")
            or "macroenabled" in str(attachment.get("content_type") or "").lower()
        )
        payload_seed = (
            f"office-attachment:{artifact_id}:{filename}:"
            f"{attachment.get('content_type') or 'application/octet-stream'}"
        )
        binary_size = max(1024, requested_size - 2200)
        if not is_macro_workbook:
            binary_size = max(256, min(binary_size, 8192))

        buffer = io.BytesIO()
        with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_STORED) as archive:
            ActivityGenerator._write_deterministic_zip_member(
                archive,
                "[Content_Types].xml",
                (
                    b'<?xml version="1.0" encoding="UTF-8"?>'
                    b'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                    b'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                    b'<Default Extension="xml" ContentType="application/xml"/>'
                    b'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.ms-excel.sheet.macroEnabled.main+xml"/>'
                    b'<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                    b"</Types>"
                ),
            )
            ActivityGenerator._write_deterministic_zip_member(
                archive,
                "_rels/.rels",
                (
                    b'<?xml version="1.0" encoding="UTF-8"?>'
                    b'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                    b'<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                    b"</Relationships>"
                ),
            )
            ActivityGenerator._write_deterministic_zip_member(
                archive,
                "xl/workbook.xml",
                (
                    b'<?xml version="1.0" encoding="UTF-8"?>'
                    b'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
                    b'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                    b'<sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets>'
                    b"</workbook>"
                ),
            )
            ActivityGenerator._write_deterministic_zip_member(
                archive,
                "xl/_rels/workbook.xml.rels",
                (
                    b'<?xml version="1.0" encoding="UTF-8"?>'
                    b'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                    b'<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
                    b"</Relationships>"
                ),
            )
            ActivityGenerator._write_deterministic_zip_member(
                archive,
                "xl/worksheets/sheet1.xml",
                (
                    b'<?xml version="1.0" encoding="UTF-8"?>'
                    b'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                    b'<sheetData><row r="1"><c r="A1" t="str"><v>Invoice reference</v></c></row></sheetData>'
                    b"</worksheet>"
                ),
            )
            if is_macro_workbook:
                ActivityGenerator._write_deterministic_zip_member(
                    archive,
                    "xl/vbaProject.bin",
                    ActivityGenerator._deterministic_binary_bytes(payload_seed, binary_size),
                )
        return buffer.getvalue()

    @staticmethod
    def _write_deterministic_zip_member(
        archive: zipfile.ZipFile,
        name: str,
        payload: bytes,
    ) -> None:
        """Write a ZIP member with stable metadata."""
        info = zipfile.ZipInfo(name, (2024, 1, 1, 0, 0, 0))
        info.compress_type = zipfile.ZIP_STORED
        info.external_attr = 0o600 << 16
        archive.writestr(info, payload)

    @staticmethod
    def _deterministic_binary_bytes(seed: str, size: int) -> bytes:
        """Return deterministic binary-looking bytes for source-native container members."""
        payload = bytearray()
        counter = 0
        while len(payload) < size:
            payload.extend(hashlib.sha256(f"{seed}:{counter}".encode()).digest())
            counter += 1
        return bytes(payload[:size])

    def _maybe_generate_email_recipient_reads(
        self,
        *,
        email_ctx: EmailContext,
        delivery_time: datetime,
        rng: random.Random,
    ) -> None:
        """Generate low-rate opaque mailbox reads after delivered internal mail."""
        if email_ctx.outcome != "delivered":
            return
        users_by_email = {
            user.email.lower(): user for user in self._scenario_environment.users if user.email
        }
        for recipient in email_ctx.expanded_rcptto[:8]:
            user = users_by_email.get(recipient.lower())
            if user is None:
                continue
            read_probability = 0.92 if email_ctx.attachments else 0.72
            if rng.random() > read_probability:
                continue
            system = self._system_for_email_user(user)
            if system is None:
                continue
            server_name = self._email_server_for_user_address(recipient)
            server_system = self._email_system_for_server_name(server_name)
            server_cfg = self._email_servers_by_name()[server_name]
            read_delay = timedelta(seconds=rng.uniform(90.0, 2700.0))
            read_time = delivery_time + read_delay
            if not self._is_within_scenario_window(read_time):
                continue
            protocol = "owa" if server_cfg.platform == "exchange" else "imaps"
            # Recipient reads are optional children of a committed delivery.
            # Bound their complete canonical network lifecycle before creating
            # or reusing the client process: OWA can own a 180-second access
            # plus an eight-second TLS tail; IMAPS can own 180 seconds plus the
            # Dovecot worker's one-second release horizon.
            access_headroom = timedelta(seconds=188 if protocol == "owa" else 181)
            scenario_end = getattr(self, "_scenario_end_time", None)
            if scenario_end is not None and ensure_utc(read_time) + access_headroom > ensure_utc(
                scenario_end
            ):
                continue
            self.generate_email_access(
                user=user,
                system=system,
                server=server_system,
                time=read_time,
                platform=server_cfg.platform,
                protocol=protocol,
                user_agent=email_ctx.user_agent,
                message_ids=(email_ctx.message_id, email_ctx.artifact_id),
            )
            self._emit_recipient_email_endpoint_artifacts(
                email_ctx=email_ctx,
                user=user,
                system=system,
                server_system=server_system,
                protocol=protocol,
                time=read_time,
                rng=rng,
            )

    def _emit_sender_email_endpoint_artifacts(
        self,
        *,
        email_ctx: EmailContext,
        user: "User",
        system: "System",
        time: datetime,
        pid: int,
    ) -> None:
        """Emit sender-side attachment reads owned by the mail client process."""
        if pid <= 0 or not email_ctx.attachments:
            return
        rng = random.Random(_stable_seed(f"email_sender_files:{email_ctx.message_id}"))
        proc = self.state_manager.get_process(system.hostname, pid)
        min_file_time = proc.start_time + timedelta(milliseconds=250) if proc else None
        for index, attachment in enumerate(email_ctx.attachments[:4]):
            filename = self._safe_email_attachment_filename(attachment)
            file_time = time - timedelta(seconds=rng.uniform(1.5, 18.0))
            if min_file_time is not None and file_time < min_file_time:
                file_time = min_file_time + timedelta(milliseconds=index * 120)
            if file_time >= time:
                file_time = time - timedelta(milliseconds=max(100, 300 - index * 50))
            self._emit_email_endpoint_file_event(
                email_ctx=email_ctx,
                user=user,
                system=system,
                time=file_time,
                pid=pid,
                path=self._email_sender_attachment_path(user, system, filename),
                action="read",
                sequence=f"sender:{index}",
            )

    def _emit_recipient_email_endpoint_artifacts(
        self,
        *,
        email_ctx: EmailContext,
        user: "User",
        system: "System",
        server_system: "System",
        protocol: str,
        time: datetime,
        rng: random.Random,
    ) -> None:
        """Emit recipient-side mail cache and attachment file traces."""
        access_rng = random.Random(
            _stable_seed(
                "email_access:"
                f"{user.username}:{system.hostname}:{server_system.hostname}:{time.isoformat()}"
            )
        )
        process_image = self._email_access_process_image(
            system,
            protocol,
            email_ctx.user_agent,
            access_rng,
        )
        command_line = self._email_access_process_command_line(
            process_image,
            protocol=protocol,
            server_hostname=self._email_server_fqdn(server_system.hostname),
        )
        pid, _image = self._ensure_email_client_process(
            user=user,
            system=system,
            time=time + timedelta(milliseconds=350),
            image=process_image,
            command_line=command_line,
        )
        if pid <= 0:
            return
        cache_time = time + timedelta(seconds=rng.uniform(1.5, 9.0))
        self._emit_email_endpoint_file_event(
            email_ctx=email_ctx,
            user=user,
            system=system,
            time=cache_time,
            pid=pid,
            path=self._email_message_cache_path(user, system, email_ctx, process_image),
            action="create",
            sequence="message-cache",
        )
        for index, attachment in enumerate(email_ctx.attachments[:4]):
            filename = self._safe_email_attachment_filename(attachment)
            attachment_time = cache_time + timedelta(milliseconds=650 + index * 420)
            self._emit_email_endpoint_file_event(
                email_ctx=email_ctx,
                user=user,
                system=system,
                time=attachment_time,
                pid=pid,
                path=self._email_recipient_attachment_path(
                    user,
                    system,
                    filename,
                    process_image,
                    email_ctx.artifact_id,
                ),
                action="create",
                sequence=f"recipient:{index}",
            )

    def _emit_email_endpoint_file_event(
        self,
        *,
        email_ctx: EmailContext,
        user: "User",
        system: "System",
        time: datetime,
        pid: int,
        path: str,
        action: str,
        sequence: str,
    ) -> None:
        """Emit one canonical endpoint file event associated with an email message."""
        proc = self.state_manager.get_process(system.hostname, pid)
        if proc is None:
            return
        self.state_manager.get_process_object_id(system.hostname, pid)
        action_name = action if action in _FILE_ACTION_EVENT_TYPES else "create"
        self.dispatcher.dispatch_builder(
            OccurrenceBuilder(
                timestamp=time,
                event_type=_FILE_ACTION_EVENT_TYPES[action_name],
                src_host=self._build_host_context(system),
                auth=AuthContext(
                    username=user.username,
                    user_sid=self._get_sid(user.username),
                    logon_id=proc.logon_id,
                ),
                process=ProcessContext(
                    pid=proc.pid,
                    parent_pid=proc.parent_pid,
                    image=proc.image,
                    command_line=proc.command_line,
                    username=proc.username,
                    integrity_level=proc.integrity_level,
                    logon_id=proc.logon_id,
                    parent_image=self._lookup_process_name(
                        system.hostname,
                        proc.parent_pid,
                        _get_os_category(system.os),
                    ),
                    start_time=proc.start_time,
                ),
                file=FileContext(path=path, action=action_name, pid=proc.pid),
            )
        )

    @staticmethod
    def _safe_email_attachment_filename(attachment: dict[str, Any]) -> str:
        """Return a source-safe attachment filename."""
        raw = str(attachment.get("filename") or "attachment.bin")
        name = re.sub(r'[<>:"/\\|?*]+', "-", raw)
        name = re.sub(r"[\x00-\x1f]+", "-", name).strip(". ")
        return name[:96] or "attachment.bin"

    def _email_sender_attachment_path(self, user: "User", system: "System", filename: str) -> str:
        """Return a plausible sender-side attachment source path."""
        if _get_os_category(system.os) == "windows":
            return rf"{self._user_profile_directory(user.username)}\Documents\{filename}"
        return f"/home/{user.username}/Documents/{filename}"

    def _email_message_cache_path(
        self,
        user: "User",
        system: "System",
        email_ctx: EmailContext,
        process_image: str,
    ) -> str:
        """Return a source-native mail message cache path."""
        token = self._base36_nonzero(_stable_seed(f"email-cache:{email_ctx.message_id}"), 10)
        if _get_os_category(system.os) == "windows":
            profile = self._user_profile_directory(user.username)
            exe_name = process_image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
            if "thunderbird" in exe_name:
                return (
                    rf"{profile}\AppData\Roaming\Thunderbird\Profiles\{token.lower()}.default-release"
                    rf"\ImapMail\{self._email_domain(user.email)}\INBOX"
                )
            if exe_name == "outlook.exe":
                return rf"{profile}\AppData\Local\Microsoft\Outlook\RoamCache\{token}.dat"
            if exe_name in {"chrome.exe", "msedge.exe"}:
                vendor_path = r"Microsoft\Edge" if exe_name == "msedge.exe" else r"Google\Chrome"
                return (
                    rf"{profile}\AppData\Local\{vendor_path}\User Data\Default"
                    rf"\Cache\Cache_Data\f_{token.lower()}"
                )
            return (
                rf"{profile}\AppData\Local\Packages"
                rf"\microsoft.windowscommunicationsapps_8wekyb3d8bbwe\LocalState\{token}.dat"
            )
        return f"/home/{user.username}/.thunderbird/{token.lower()}.default-release/ImapMail/INBOX"

    def _email_recipient_attachment_path(
        self,
        user: "User",
        system: "System",
        filename: str,
        process_image: str,
        artifact_id: str,
    ) -> str:
        """Return a recipient-side attachment/cache path with the original filename."""
        token = self._base36_nonzero(_stable_seed(f"email-attachment-cache:{artifact_id}"), 8)
        if _get_os_category(system.os) == "windows":
            profile = self._user_profile_directory(user.username)
            exe_name = process_image.rsplit("\\", 1)[-1].rsplit("/", 1)[-1].lower()
            if "thunderbird" in exe_name:
                return (
                    rf"{profile}\AppData\Local\Thunderbird\Profiles\{token.lower()}.default-release"
                    rf"\cache2\entries\{filename}"
                )
            if exe_name in {"chrome.exe", "msedge.exe"}:
                return rf"{profile}\Downloads\{filename}"
            if exe_name != "outlook.exe":
                return (
                    rf"{profile}\AppData\Local\Packages"
                    rf"\microsoft.windowscommunicationsapps_8wekyb3d8bbwe"
                    rf"\LocalState\Attachments\{token}\{filename}"
                )
            return (
                rf"{profile}\AppData\Local\Microsoft\Windows\INetCache"
                rf"\Content.Outlook\{token}\{filename}"
            )
        return f"/home/{user.username}/.cache/thunderbird/{token.lower()}/{filename}"

    def _system_for_email_user(self, user: "User") -> "System | None":
        """Return a user's likely mailbox client system."""
        if user.primary_system:
            system = next(
                (
                    candidate
                    for candidate in self._scenario_environment.systems
                    if candidate.hostname == user.primary_system
                ),
                None,
            )
            if system is not None:
                return system
        return next(
            (
                candidate
                for candidate in self._scenario_environment.systems
                if candidate.assigned_user == user.username
            ),
            None,
        )

    def _should_materialize_email_artifact(self, artifact_id: str, storyline_id: str) -> bool:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None:
            return False
        mode = email_config.artifacts.mode
        if mode == "none":
            return False
        if mode in {"storyline", "all"}:
            return bool(storyline_id) or mode == "all"
        return artifact_id in set(email_config.artifacts.selected_ids) or storyline_id in set(
            email_config.artifacts.selected_ids
        )

    def _write_email_artifact(self, email_ctx: EmailContext) -> str:
        artifact_dir = getattr(self, "_email_artifact_dir", None)
        if artifact_dir is None:
            return ""
        try:
            path = write_exclusive_child_stream(
                artifact_dir,
                f"{email_ctx.artifact_id}.eml",
                self._iter_email_artifact_bytes(email_ctx),
                label="email artifact filename",
            )
        except PathSafetyError as exc:
            raise GenerationError(str(exc)) from exc
        return path.relative_to(artifact_dir.parent.parent.absolute()).as_posix()

    def _render_email_artifact(self, email_ctx: EmailContext) -> str:
        """Render a deterministic MIME message with profile-specific header texture."""
        return b"".join(self._iter_email_artifact_bytes(email_ctx)).decode("utf-8")

    def _iter_email_artifact_bytes(self, email_ctx: EmailContext) -> Iterator[bytes]:
        """Yield MIME bytes incrementally so base64 expansion never duplicates the message."""

        profile = self._email_mailer_profile(email_ctx.envelope_from, email_ctx.user_agent)
        has_attachments = bool(email_ctx.attachments)
        boundary = self._email_mime_boundary(email_ctx.artifact_id, profile)
        header_lines = self._email_artifact_header_lines(
            email_ctx,
            profile=profile,
            boundary=boundary,
            has_attachments=has_attachments,
        )
        if not has_attachments:
            body = self._quoted_printable_text(email_ctx.body or "")
            yield from self._iter_crlf_email_lines([*header_lines, "", body, ""])
            return

        yield from self._iter_crlf_email_lines(
            [
                *header_lines,
                "",
                f"--{boundary}",
                'Content-Type: text/plain; charset="utf-8"',
                "Content-Transfer-Encoding: quoted-printable",
                "",
                self._quoted_printable_text(email_ctx.body or ""),
                "",
            ],
            trailing_separator=True,
        )
        for attachment in email_ctx.attachments:
            payload = self._email_attachment_payload_bytes(attachment, email_ctx.artifact_id)
            content_type = str(attachment.get("content_type") or "application/octet-stream")
            filename = self._sanitize_email_header_value(
                str(attachment.get("filename") or "attachment.bin")
            )
            yield from self._iter_crlf_email_lines(
                [
                    f"--{boundary}",
                    f'Content-Type: {content_type}; name="{filename}"',
                    "Content-Transfer-Encoding: base64",
                    f'Content-Disposition: attachment; filename="{filename}"',
                    "",
                ],
                trailing_separator=True,
            )
            if payload:
                for index in range(0, len(payload), 57):
                    yield base64.b64encode(payload[index : index + 57])
                    yield b"\r\n"
            else:
                yield b"\r\n"
            yield b"\r\n"
        yield from self._iter_crlf_email_lines([f"--{boundary}--", ""])

    @staticmethod
    def _iter_crlf_email_lines(
        lines: Iterable[str],
        *,
        trailing_separator: bool = False,
    ) -> Iterator[bytes]:
        """Yield the exact byte representation of CRLF-joined text lines."""

        first = True
        for line in lines:
            if not first:
                yield b"\r\n"
            yield line.encode("utf-8")
            first = False
        if trailing_separator:
            yield b"\r\n"

    def _email_artifact_header_lines(
        self,
        email_ctx: EmailContext,
        *,
        profile: str,
        boundary: str,
        has_attachments: bool,
    ) -> list[str]:
        """Return source-native-ish ordered message headers for one mailer profile."""
        header_values = {
            "Return-Path": email_ctx.header_from,
            "Date": email_ctx.date_header,
            "From": email_ctx.header_from,
            "To": ", ".join(email_ctx.to),
            "Cc": ", ".join(email_ctx.cc),
            "Subject": email_ctx.subject,
            "Message-ID": email_ctx.message_id,
            "MIME-Version": "1.0",
            "Content-Type": (
                f'multipart/mixed; boundary="{boundary}"'
                if has_attachments
                else 'text/plain; charset="utf-8"'
            ),
            "Content-Transfer-Encoding": "" if has_attachments else "quoted-printable",
        }
        generated_mailer_header = self._email_profile_mailer_header(
            profile,
            email_ctx.user_agent,
        )
        if generated_mailer_header is not None:
            header_values[generated_mailer_header[0]] = generated_mailer_header[1]
        if profile == "outlook":
            header_values["Thread-Topic"] = email_ctx.subject
            if has_attachments:
                header_values["X-MS-Has-Attach"] = "yes"
        if profile == "service":
            header_values["Auto-Submitted"] = "auto-generated"
            header_values["X-Auto-Response-Suppress"] = "All"

        owned_headers = {
            "return-path",
            "received",
            "date",
            "from",
            "to",
            "cc",
            "bcc",
            "subject",
            "message-id",
            "mime-version",
            "content-type",
            "content-transfer-encoding",
            "thread-topic",
            "x-ms-has-attach",
            "user-agent",
            "x-mailer",
            "auto-submitted",
            "x-auto-response-suppress",
        }
        custom_headers = [
            (str(header), str(value))
            for header, value in email_ctx.custom_headers.items()
            if str(header).lower() not in owned_headers
        ]
        custom_header_names = {header.lower() for header, _ in custom_headers}

        lines = [
            self._format_email_header("Received", received)
            for received in email_ctx.received_headers
        ]
        order = self._email_profile_header_order(profile, has_attachments)
        custom_inserted = False
        for header in order:
            if header == "_CUSTOM":
                lines.extend(
                    self._format_email_header(custom_header, custom_value)
                    for custom_header, custom_value in custom_headers
                )
                custom_inserted = True
                continue
            if header in {"X-Mailer", "User-Agent"} and header.lower() in custom_header_names:
                continue
            value = header_values.get(header, "")
            if value:
                lines.append(self._format_email_header(header, value))
        if not custom_inserted:
            for header, value in custom_headers:
                lines.append(self._format_email_header(header, value))
        return lines

    @staticmethod
    def _email_profile_header_order(profile: str, has_attachments: bool) -> list[str]:
        """Return the deterministic header order for a coarse mailer profile."""
        if profile == "thunderbird":
            return [
                "Return-Path",
                "Date",
                "From",
                "To",
                "Cc",
                "Subject",
                "_CUSTOM",
                "Message-ID",
                "User-Agent",
                "MIME-Version",
                "Content-Type",
                "Content-Transfer-Encoding",
            ]
        if profile == "apple_mail":
            return [
                "Return-Path",
                "Date",
                "From",
                "To",
                "Cc",
                "Subject",
                "X-Mailer",
                "_CUSTOM",
                "Message-ID",
                "MIME-Version",
                "Content-Type",
                "Content-Transfer-Encoding",
            ]
        if profile == "service":
            return [
                "Return-Path",
                "Date",
                "From",
                "To",
                "Cc",
                "Subject",
                "Auto-Submitted",
                "X-Auto-Response-Suppress",
                "X-Mailer",
                "_CUSTOM",
                "Message-ID",
                "MIME-Version",
                "Content-Type",
                "Content-Transfer-Encoding",
            ]
        return [
            "Return-Path",
            "Date",
            "From",
            "To",
            "Cc",
            "Subject",
            "Thread-Topic",
            "X-MS-Has-Attach",
            "X-Mailer",
            "_CUSTOM",
            "Message-ID",
            "MIME-Version",
            "Content-Type",
            "Content-Transfer-Encoding",
        ]

    @staticmethod
    def _email_profile_mailer_header(
        profile: str,
        user_agent: str,
    ) -> tuple[str, str] | None:
        """Return the profile-appropriate visible mailer header."""
        if not user_agent:
            return None
        if profile == "thunderbird":
            return "User-Agent", user_agent
        return "X-Mailer", user_agent

    @staticmethod
    def _email_mime_boundary(artifact_id: str, profile: str) -> str:
        seed_hi = _stable_seed(f"email_mime_boundary:{profile}:{artifact_id}:hi")
        seed_lo = _stable_seed(f"email_mime_boundary:{profile}:{artifact_id}:lo")
        if profile == "outlook":
            return f"_004_{seed_hi:016X}{seed_lo:016X}_"
        if profile == "thunderbird":
            return f"------------{seed_hi:012x}{seed_lo & 0xFFFFFF:06x}"
        if profile == "apple_mail":
            return f"Apple-Mail=_${seed_hi:08X}-{seed_lo:08X}"
        return f"----=_Part_{seed_hi % 1000000}_{seed_lo}"

    @staticmethod
    def _sanitize_email_header_value(value: str) -> str:
        return " ".join(value.replace("\r", " ").replace("\n", " ").split())

    def _format_email_header(self, header: str, value: str) -> str:
        safe_header = re.sub(r"[^A-Za-z0-9-]+", "-", header).strip("-") or "X-Header"
        return f"{safe_header}: {self._sanitize_email_header_value(str(value))}"

    @staticmethod
    def _quoted_printable_text(text: str) -> str:
        encoded = quopri.encodestring(text.encode("utf-8"), quotetabs=False).decode("ascii")
        return encoded.replace("\n", "\r\n").rstrip("\r\n")

    def _record_email_artifact_manifest(
        self,
        email_ctx: EmailContext,
        artifact_path: str,
    ) -> None:
        email_config = getattr(getattr(self, "_scenario_environment", None), "email", None)
        if email_config is None or email_config.artifacts.mode == "none":
            return
        manifest = getattr(self, "_email_artifact_manifest", None)
        if manifest is None:
            self._email_artifact_manifest = []
            manifest = self._email_artifact_manifest
        eml_path = Path(artifact_path).name if artifact_path else ""
        export_status, export_reason = self._email_artifact_export_state(
            email_ctx,
            artifact_path,
        )
        manifest.append(
            {
                "message_id": email_ctx.message_id,
                "sender": email_ctx.envelope_from,
                "to": email_ctx.to,
                "cc": email_ctx.cc,
                "bcc": email_ctx.bcc,
                "subject": email_ctx.subject,
                "date": email_ctx.date_header,
                "eml_path": eml_path,
                "artifact_export_status": export_status,
                "artifact_export_reason": export_reason,
            }
        )

    @staticmethod
    def _email_artifact_export_state(
        email_ctx: EmailContext,
        artifact_path: str,
    ) -> tuple[str, str]:
        """Return blind-facing artifact export state for one manifest row."""
        if artifact_path:
            return "materialized", "selected_by_artifact_policy"
        if email_ctx.outcome != "delivered":
            return "metadata_only", "transport_not_completed"
        return "metadata_only", "not_selected_by_artifact_policy"

    def write_artifacts_manifest(self) -> None:
        """Write the top-level artifact manifest when email artifact metadata exists."""
        manifest = getattr(self, "_email_artifact_manifest", None)
        manifest_path = getattr(self, "_artifacts_manifest_path", None)
        if manifest_path is None or manifest is None:
            return
        import json

        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "schema_version": ARTIFACTS_MANIFEST_SCHEMA_VERSION,
            "email": {
                "messages": sorted(
                    manifest,
                    key=lambda item: (
                        item.get("date") or "",
                        item.get("message_id") or "",
                        item.get("sender") or "",
                    ),
                ),
            },
        }
        manifest_path.write_text(
            json.dumps(payload, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )

    def generate_ssh_session(
        self,
        user: User,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_system: Optional["System"] = None,
        source_port: int | None = None,
        source_pid: int = -1,
        source_process_image: str = "",
        sshd_pid: int | None = None,
        logon_id: str = "",
        session_obj_id: str = "",
        min_duration: float | None = None,
        duration: float | None = None,
        orig_bytes: int | None = None,
        resp_bytes: int | None = None,
        auth_method: str = "password",
        public_key_type: str = "",
        public_key_hash: str = "",
        emit_session_close: bool = False,
        defer_session_close: bool = False,
        session_end_plan: SessionEndPlan | None = None,
        ids_alerts: list[IdsAlertPlan] | None = None,
        source: str = "activity_generator",
    ) -> str:
        """Generate an SSH session through the SSH action-bundle adapter.

        Args:
            user: User initiating the SSH connection
            target_system: Target Linux system
            time: Connection timestamp
            source_ip: Source IP of the SSH client

        Returns:
            Zeek UID for the connection
        """
        request = SshSessionRequest(
            user=user,
            target_system=target_system,
            time=time,
            source_ip=source_ip,
            source_system=source_system,
            source_port=source_port,
            source_pid=source_pid,
            source_process_image=source_process_image,
            sshd_pid=sshd_pid,
            logon_id=logon_id,
            session_obj_id=session_obj_id,
            min_duration=min_duration,
            duration=duration,
            orig_bytes=orig_bytes,
            resp_bytes=resp_bytes,
            auth_method=auth_method,
            public_key_type=public_key_type,
            public_key_hash=public_key_hash,
            emit_session_close=emit_session_close,
            defer_session_close=defer_session_close,
            session_end_plan=session_end_plan,
            ids_alerts=list(ids_alerts or []),
            source=source,
        )
        return SshSessionActionBundle(request=request, executor=self).execute()

    def _execute_ssh_session_bundle(
        self,
        user: User,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_system: Optional["System"] = None,
        source_port: int | None = None,
        source_pid: int = -1,
        source_process_image: str = "",
        sshd_pid: int | None = None,
        logon_id: str = "",
        session_obj_id: str = "",
        min_duration: float | None = None,
        duration: float | None = None,
        orig_bytes: int | None = None,
        resp_bytes: int | None = None,
        auth_method: str = "password",
        public_key_type: str = "",
        public_key_hash: str = "",
        emit_session_close: bool = False,
        defer_session_close: bool = False,
        session_end_plan: SessionEndPlan | None = None,
        ids_alerts: list[IdsAlertPlan] | None = None,
        source: str = "activity_generator",
    ) -> tuple[str, str]:
        """Execute the canonical SSH bundle and return transport and session IDs."""

        request = SshSessionRequest(
            user=user,
            target_system=target_system,
            time=time,
            source_ip=source_ip,
            source_system=source_system,
            source_port=source_port,
            source_pid=source_pid,
            source_process_image=source_process_image,
            sshd_pid=sshd_pid,
            logon_id=logon_id,
            session_obj_id=session_obj_id,
            min_duration=min_duration,
            duration=duration,
            orig_bytes=orig_bytes,
            resp_bytes=resp_bytes,
            auth_method=auth_method,
            public_key_type=public_key_type,
            public_key_hash=public_key_hash,
            emit_session_close=emit_session_close,
            defer_session_close=defer_session_close,
            session_end_plan=session_end_plan,
            ids_alerts=list(ids_alerts or []),
            source=source,
        )
        return SshSessionActionBundle(request=request, executor=self).execute_with_identity()

    @staticmethod
    def _ssh_tcp_success_history(rng: random.Random) -> str:
        """Choose a plausible Zeek TCP history string for SSH bundle expansion."""
        return _tcp_success_history(rng)

    @staticmethod
    def _ssh_tcp_packet_counts_from_payload_and_history(
        orig_bytes: int | None,
        resp_bytes: int | None,
        history: str | None,
        rng: random.Random,
    ) -> tuple[int, int]:
        """Return TCP packet counts for SSH bundle expansion."""
        return _tcp_packet_counts_from_payload_and_history(orig_bytes, resp_bytes, history, rng)

    @staticmethod
    def _ssh_tcp_ip_byte_count(
        payload_bytes: int | None,
        packet_count: int,
        rng: random.Random,
    ) -> int:
        """Return TCP IP byte accounting for SSH bundle expansion."""
        return _tcp_ip_byte_count(payload_bytes, packet_count, rng)

    def ensure_linux_ssh_session_shell(
        self,
        user: User,
        target_system: System,
        logon_id: str,
        logon_time: datetime,
        activity_time: datetime,
        source_visible_by: datetime | None = None,
    ) -> int | None:
        """Create visible per-session sshd and login shell process state for SSH."""
        session = self.state_manager.get_session(logon_id)
        if session is None or session.system != target_system.hostname:
            return None
        logon_time = ensure_utc(logon_time)
        activity_time = ensure_utc(activity_time)
        if not _session_active_for_activity(session, activity_time, margin_seconds=1.5):
            return None
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        if session.session_shell_pid is not None:
            shell_proc = self.state_manager.get_process(
                target_system.hostname,
                session.session_shell_pid,
            )
            if shell_proc is not None:
                shell_start = ensure_utc(shell_proc.start_time)
                source_ready_time = _session_source_ready_time(session)
                if (
                    (
                        scenario_start is None
                        or activity_time < scenario_start
                        or shell_start >= scenario_start
                    )
                    and (source_ready_time is None or shell_start >= source_ready_time)
                    and shell_proc.logon_id == logon_id
                ):
                    # Parent selection and parent sanitization can both request
                    # the SSH shell while its canonical start is being fitted
                    # just after the requested activity anchor. The caller will
                    # clamp dependent process evidence after that start; retain
                    # the one session-owned shell instead of materializing a
                    # second identical bash process at the same source time.
                    return (
                        session.session_shell_pid
                        if self._process_source_bound_visible_by(
                            system=target_system,
                            pid=session.session_shell_pid,
                            deadline=source_visible_by,
                        )
                        else None
                    )

        sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
        global_sshd = sys_pids.get("sshd")
        if (
            not global_sshd
            or self.state_manager.get_process(target_system.hostname, global_sshd) is None
        ):
            return None

        shell_seed = _stable_seed(
            "linux_ssh_session_shell:"
            f"{target_system.hostname}:{user.username}:{logon_id}:{logon_time.isoformat()}"
        )
        source_ready_time = _session_source_ready_time(session)
        source_floor = logon_time + timedelta(milliseconds=150)
        if source_ready_time is not None:
            source_floor = max(source_floor, source_ready_time + timedelta(milliseconds=50))
        sshd_delay_ms = 900 + (shell_seed % 1400)
        sshd_time = max(logon_time + timedelta(milliseconds=sshd_delay_ms), source_floor)
        if (
            scenario_start is not None
            and activity_time >= scenario_start
            and sshd_time < scenario_start
        ):
            pre_command_gap = timedelta(seconds=5 + (shell_seed % 95))
            scenario_floor = scenario_start + timedelta(milliseconds=500 + (shell_seed % 3000))
            sshd_time = max(scenario_floor, activity_time - pre_command_gap)
        effective_activity_time = max(activity_time, sshd_time + timedelta(milliseconds=700))
        latest_parent_time = effective_activity_time - timedelta(milliseconds=500)
        if sshd_time > latest_parent_time and latest_parent_time >= source_floor:
            sshd_time = max(logon_time + timedelta(milliseconds=150), latest_parent_time)

        session_sshd_pid = self._ssh_session_transport_process_parent(
            session,
            target_system,
            user,
        )
        session_sshd_source = (
            self._process_source_frontier_or_bound(
                system=target_system,
                pid=session_sshd_pid,
            )
            if session_sshd_pid is not None
            else self._process_create_source_bound(
                system=target_system,
                canonical_time=sshd_time,
                parent_source_time=self._process_source_frontier_or_bound(
                    system=target_system,
                    pid=global_sshd,
                ),
            )
        )
        bash_time = sshd_time + timedelta(milliseconds=120 + (shell_seed % 180))
        effective_activity_time = max(activity_time, bash_time + timedelta(milliseconds=260))
        latest_bash_time = effective_activity_time - timedelta(milliseconds=120)
        if bash_time > latest_bash_time and latest_bash_time >= sshd_time + timedelta(
            milliseconds=20
        ):
            bash_time = max(sshd_time + timedelta(milliseconds=20), latest_bash_time)
        if source_visible_by is not None:
            if session_sshd_source is None:
                return None
            bash_source = self._process_create_source_bound(
                system=target_system,
                canonical_time=bash_time,
                parent_source_time=session_sshd_source,
                session_source_time=_session_source_ready_time(session),
            )
            if bash_source > ensure_utc(source_visible_by):
                return None
        if session_sshd_pid is None:
            session_sshd_pid = self.generate_system_process(
                system=target_system,
                time=sshd_time,
                process_name="/usr/sbin/sshd",
                command_line=f"sshd: {user.username} [priv]",
                parent_pid=global_sshd,
                username="root",
                emit_linux_syslog=False,
                source_visible_by=source_visible_by,
            )
            if session_sshd_pid <= 0:
                return None

        bash_pid = self.generate_process(
            user=user,
            system=target_system,
            time=bash_time,
            logon_id=logon_id,
            process_name="/bin/bash",
            command_line="-bash",
            parent_pid=session_sshd_pid,
            suppress_command_file_effect=True,
            source_visible_by=source_visible_by,
        )
        if bash_pid <= 0:
            return None
        session.session_shell_pid = bash_pid
        session.process_tree_root = session_sshd_pid
        return bash_pid

    def _ssh_session_transport_process_parent(
        self,
        session: ActiveSession,
        target_system: System,
        user: User,
    ) -> int | None:
        """Return the tuple-scoped sshd child when it can parent a login shell."""

        transport_pid = session.transport_pid
        if transport_pid is None or transport_pid <= 0:
            return None
        running = self.state_manager.get_process(target_system.hostname, transport_pid)
        if running is None:
            return None
        if running.image != "/usr/sbin/sshd":
            return None
        if running.command_line != f"sshd: {user.username} [priv]":
            return None
        return transport_pid

    def _active_linux_session_user_manager_pid(
        self,
        *,
        user: User,
        target_system: System,
        logon_id: str,
        at_time: datetime,
        update_session: bool = True,
    ) -> int | None:
        """Return the durable `systemd --user` process for a local Linux session."""

        at_time = ensure_utc(at_time)
        session = self.state_manager.get_session(logon_id)
        candidate_pids: list[int] = []
        if session is not None and session.session_user_manager_pid:
            candidate_pids.append(session.session_user_manager_pid)

        for proc in self.state_manager.get_processes_on_system(target_system.hostname):
            if proc.username != user.username:
                continue
            if proc.logon_id != logon_id:
                continue
            if proc.image != "/usr/lib/systemd/systemd":
                continue
            if proc.command_line != "/usr/lib/systemd/systemd --user":
                continue
            candidate_pids.append(proc.pid)

        valid_candidates = []
        for pid in dict.fromkeys(candidate_pids):
            proc = self.state_manager.get_process(target_system.hostname, pid)
            if proc is None or proc.start_time is None:
                continue
            if ensure_utc(proc.start_time) > at_time:
                continue
            if not self._is_pid_active_at(target_system, pid, at_time):
                continue
            valid_candidates.append(proc)

        if not valid_candidates:
            return None

        valid_candidates.sort(key=lambda proc: ensure_utc(proc.start_time))
        user_manager = valid_candidates[0]
        if session is not None and update_session:
            session.session_user_manager_pid = user_manager.pid
        return user_manager.pid

    def _active_linux_local_session_parent_pid(
        self,
        *,
        user: User,
        target_system: System,
        logon_id: str,
        at_time: datetime,
        update_session: bool = True,
    ) -> int | None:
        """Return an active terminal/login parent for a local Linux session shell."""

        at_time = ensure_utc(at_time)
        session = self.state_manager.get_session(logon_id)
        candidate_pids: list[int] = []
        if session is not None and session.process_tree_root:
            candidate_pids.append(session.process_tree_root)

        parent_images = {
            "/usr/libexec/gnome-terminal-server",
            "/bin/login",
        }
        for proc in self.state_manager.get_processes_on_system(target_system.hostname):
            if proc.username != user.username:
                continue
            if proc.logon_id != logon_id:
                continue
            if proc.image not in parent_images:
                continue
            candidate_pids.append(proc.pid)

        valid_candidates = []
        for pid in dict.fromkeys(candidate_pids):
            proc = self.state_manager.get_process(target_system.hostname, pid)
            if proc is None or proc.start_time is None:
                continue
            if proc.image not in parent_images:
                continue
            if ensure_utc(proc.start_time) > at_time:
                continue
            if not self._linux_parent_usable_for_child_at(
                system=target_system,
                parent_pid=pid,
                time=at_time,
                logon_id=logon_id,
            ):
                continue
            valid_candidates.append(proc)

        if not valid_candidates:
            return None

        valid_candidates.sort(key=lambda proc: ensure_utc(proc.start_time), reverse=True)
        parent = valid_candidates[0]
        if session is not None and update_session:
            session.process_tree_root = parent.pid
        return parent.pid

    def _ensure_linux_local_session_shell_parent(
        self,
        *,
        user: User,
        target_system: System,
        logon_id: str,
        logon_time: datetime,
        bash_time: datetime,
        root_parent_pid: int,
        shell_seed: int,
        source_visible_by: datetime | None = None,
    ) -> tuple[int, datetime] | None:
        """Create a visible local-session parent chain before a login shell."""

        system_type = (getattr(target_system, "type", "") or "").lower()
        workstation_like = system_type in {
            "workstation",
            "laptop",
        } or target_system.hostname.upper().startswith(("WS-", "LT-"))
        session = self.state_manager.get_session(logon_id)
        bootstrap_lifecycle_group_id = session.lifecycle_group_id if session is not None else ""
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        pre_window_session = (
            scenario_start is not None
            and ensure_utc(logon_time) < scenario_start
            and ensure_utc(bash_time) >= scenario_start
        )
        user_systemd_time = logon_time
        user_systemd_pid: int | None = None
        if workstation_like:
            user_systemd_time = logon_time + timedelta(milliseconds=90)
            if not pre_window_session:
                user_systemd_time = max(
                    user_systemd_time,
                    bash_time - timedelta(milliseconds=900 + (shell_seed % 320)),
                )
            if user_systemd_time >= bash_time:
                user_systemd_time = logon_time + timedelta(milliseconds=90)
            user_systemd_pid = self._active_linux_session_user_manager_pid(
                user=user,
                target_system=target_system,
                logon_id=logon_id,
                at_time=bash_time,
            )
            if user_systemd_pid is None:
                user_systemd_pid = self.generate_process(
                    user=user,
                    system=target_system,
                    time=user_systemd_time,
                    logon_id=logon_id,
                    process_name="/usr/lib/systemd/systemd",
                    command_line="/usr/lib/systemd/systemd --user",
                    parent_pid=root_parent_pid,
                    suppress_command_file_effect=True,
                    lifecycle_group_id=bootstrap_lifecycle_group_id,
                    source_visible_by=source_visible_by,
                )
                if user_systemd_pid <= 0:
                    return None
                if session is not None:
                    session.session_user_manager_pid = user_systemd_pid

            user_systemd_proc = self.state_manager.get_process(
                target_system.hostname,
                user_systemd_pid,
            )
            if user_systemd_proc is not None and user_systemd_proc.start_time is not None:
                user_systemd_time = ensure_utc(user_systemd_proc.start_time)

        if workstation_like:
            parent_image = "/usr/libexec/gnome-terminal-server"
            parent_command = "/usr/libexec/gnome-terminal-server"
        else:
            parent_image = "/bin/login"
            parent_command = f"login -- {user.username}"

        existing_parent_pid = self._active_linux_local_session_parent_pid(
            user=user,
            target_system=target_system,
            logon_id=logon_id,
            at_time=bash_time,
        )
        if existing_parent_pid is not None:
            existing_parent = self.state_manager.get_process(
                target_system.hostname,
                existing_parent_pid,
            )
            if existing_parent is not None and existing_parent.start_time is not None:
                return existing_parent_pid, ensure_utc(existing_parent.start_time)
            return existing_parent_pid, user_systemd_time

        terminal_time = user_systemd_time + timedelta(milliseconds=120)
        if not pre_window_session:
            terminal_time = max(
                terminal_time,
                bash_time - timedelta(milliseconds=260 + (shell_seed % 170)),
            )
        terminal_pid = self.generate_process(
            user=user,
            system=target_system,
            time=terminal_time,
            logon_id=logon_id,
            process_name=parent_image,
            command_line=parent_command,
            parent_pid=user_systemd_pid if user_systemd_pid is not None else root_parent_pid,
            suppress_command_file_effect=True,
            lifecycle_group_id=bootstrap_lifecycle_group_id,
            source_visible_by=source_visible_by,
        )
        if terminal_pid <= 0:
            return None
        terminal_proc = self.state_manager.get_process(target_system.hostname, terminal_pid)
        if terminal_proc is not None:
            terminal_time = ensure_utc(terminal_proc.start_time)
        return terminal_pid, terminal_time

    def ensure_linux_session_shell(
        self,
        user: User,
        target_system: System,
        logon_id: str,
        logon_time: datetime,
        activity_time: datetime,
        source_visible_by: datetime | None = None,
    ) -> int | None:
        """Create or return a visible Linux shell that owns session child processes."""
        session = self.state_manager.get_session_at(logon_id, activity_time)
        if session is None or session.system != target_system.hostname:
            return None
        if not _session_active_for_activity(session, activity_time, margin_seconds=1.5):
            return None
        if session.session_kind == "ssh":
            return self.ensure_linux_ssh_session_shell(
                user=user,
                target_system=target_system,
                logon_id=logon_id,
                logon_time=logon_time,
                activity_time=activity_time,
                source_visible_by=source_visible_by,
            )

        logon_time = ensure_utc(logon_time)
        activity_time = ensure_utc(activity_time)
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        if session.session_shell_pid is not None:
            shell_proc = self.state_manager.get_process(
                target_system.hostname,
                session.session_shell_pid,
            )
            if shell_proc is not None and self._is_pid_active_at(
                target_system,
                session.session_shell_pid,
                activity_time,
            ):
                shell_start = ensure_utc(shell_proc.start_time)
                if (
                    scenario_start is None
                    or activity_time < scenario_start
                    or shell_start >= scenario_start
                ):
                    return (
                        session.session_shell_pid
                        if self._process_source_bound_visible_by(
                            system=target_system,
                            pid=session.session_shell_pid,
                            deadline=source_visible_by,
                        )
                        else None
                    )

        sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
        parent_pid = sys_pids.get("systemd") or sys_pids.get("init")
        if (
            not parent_pid
            or self.state_manager.get_process(target_system.hostname, parent_pid) is None
        ):
            if source_visible_by is not None:
                return None
            anchor_time = activity_time
            if scenario_start is not None and logon_time < scenario_start:
                anchor_time = logon_time
            parent_pid = self._linux_anchor_pid(target_system, anchor_time)

        shell_seed = _stable_seed(
            "linux_session_shell:"
            f"{target_system.hostname}:{user.username}:{logon_id}:{logon_time.isoformat()}"
        )
        bash_time = logon_time + timedelta(milliseconds=180 + (shell_seed % 1200))
        if (
            scenario_start is not None
            and activity_time >= scenario_start
            and bash_time < scenario_start
        ):
            scenario_floor = scenario_start + timedelta(milliseconds=400 + (shell_seed % 2500))
            pre_command_gap = timedelta(seconds=4 + (shell_seed % 75))
            bash_time = max(scenario_floor, activity_time - pre_command_gap)
        session_root = (
            self.state_manager.get_process(target_system.hostname, session.process_tree_root)
            if session.process_tree_root
            else None
        )
        if (
            session_root is not None
            and session_root.image
            in {
                "/bin/login",
                "/usr/libexec/gnome-terminal-server",
            }
            and ensure_utc(session_root.start_time) >= bash_time
            and ensure_utc(session_root.start_time) < activity_time
        ):
            bash_time = ensure_utc(session_root.start_time) + timedelta(milliseconds=120)
        readiness_gap = timedelta(milliseconds=2200 + (shell_seed % 5200))
        latest_bash_time = activity_time - readiness_gap
        if bash_time > latest_bash_time and latest_bash_time > logon_time:
            bash_time = latest_bash_time

        if source_visible_by is not None:
            source_bound = self._linux_local_session_shell_source_bound(
                user=user,
                target_system=target_system,
                session=session,
                logon_time=logon_time,
                activity_time=activity_time,
                root_parent_pid=parent_pid,
                shell_seed=shell_seed,
                bash_time=bash_time,
            )
            if source_bound is None or source_bound > ensure_utc(source_visible_by):
                return None

        parent_plan = self._ensure_linux_local_session_shell_parent(
            user=user,
            target_system=target_system,
            logon_id=logon_id,
            logon_time=logon_time,
            bash_time=bash_time,
            root_parent_pid=parent_pid,
            shell_seed=shell_seed,
            source_visible_by=source_visible_by,
        )
        if parent_plan is None:
            return None
        parent_pid, parent_time = parent_plan
        if parent_time >= bash_time:
            bash_time = parent_time + timedelta(milliseconds=120)

        bash_pid = self.generate_process(
            user=user,
            system=target_system,
            time=bash_time,
            logon_id=logon_id,
            process_name="/bin/bash",
            command_line="-bash",
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            lifecycle_group_id=session.lifecycle_group_id,
            source_visible_by=source_visible_by,
        )
        if bash_pid <= 0:
            return None
        session.session_shell_pid = bash_pid
        session.process_tree_root = parent_pid
        return bash_pid

    def _linux_local_session_shell_source_bound(
        self,
        *,
        user: User,
        target_system: System,
        session: ActiveSession,
        logon_time: datetime,
        activity_time: datetime,
        root_parent_pid: int,
        shell_seed: int,
        bash_time: datetime,
    ) -> datetime | None:
        """Return the allocation-free source frontier for a local login-shell chain."""

        system_type = (getattr(target_system, "type", "") or "").lower()
        workstation_like = system_type in {"workstation", "laptop"} or (
            target_system.hostname.upper().startswith(("WS-", "LT-"))
        )
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        pre_window_session = (
            scenario_start is not None
            and logon_time < scenario_start
            and bash_time >= scenario_start
        )
        root_source = self._process_source_frontier_or_bound(
            system=target_system,
            pid=root_parent_pid,
        )
        if root_source is None:
            return None

        user_systemd_time = logon_time
        user_systemd_source = root_source
        user_systemd_pid: int | None = None
        if workstation_like:
            user_systemd_time = logon_time + timedelta(milliseconds=90)
            if not pre_window_session:
                user_systemd_time = max(
                    user_systemd_time,
                    bash_time - timedelta(milliseconds=900 + (shell_seed % 320)),
                )
            if user_systemd_time >= bash_time:
                user_systemd_time = logon_time + timedelta(milliseconds=90)
            user_systemd_pid = self._active_linux_session_user_manager_pid(
                user=user,
                target_system=target_system,
                logon_id=session.logon_id,
                at_time=bash_time,
                update_session=False,
            )
            if user_systemd_pid is not None:
                manager = self.state_manager.get_process(target_system.hostname, user_systemd_pid)
                if manager is None:
                    return None
                user_systemd_time = ensure_utc(manager.start_time)
                user_systemd_source = self._process_source_frontier_or_bound(
                    system=target_system,
                    pid=user_systemd_pid,
                )
            else:
                user_systemd_source = self._process_create_source_bound(
                    system=target_system,
                    canonical_time=user_systemd_time,
                    parent_source_time=root_source,
                    session_source_time=_session_source_ready_time(session),
                )
            if user_systemd_source is None:
                return None

        parent_pid = self._active_linux_local_session_parent_pid(
            user=user,
            target_system=target_system,
            logon_id=session.logon_id,
            at_time=bash_time,
            update_session=False,
        )
        if parent_pid is not None:
            parent = self.state_manager.get_process(target_system.hostname, parent_pid)
            if parent is None:
                return None
            parent_time = ensure_utc(parent.start_time)
            parent_source = self._process_source_frontier_or_bound(
                system=target_system,
                pid=parent_pid,
            )
        else:
            parent_time = user_systemd_time + timedelta(milliseconds=120)
            if not pre_window_session:
                parent_time = max(
                    parent_time,
                    bash_time - timedelta(milliseconds=260 + (shell_seed % 170)),
                )
            parent_source = self._process_create_source_bound(
                system=target_system,
                canonical_time=parent_time,
                parent_source_time=user_systemd_source,
                session_source_time=_session_source_ready_time(session),
            )
        if parent_source is None:
            return None
        if parent_time >= bash_time:
            bash_time = parent_time + timedelta(milliseconds=120)
        return self._process_create_source_bound(
            system=target_system,
            canonical_time=bash_time,
            parent_source_time=parent_source,
            session_source_time=_session_source_ready_time(session),
        )

    def _active_visible_linux_shell_pid(
        self,
        system: System,
        username: str,
        time: datetime,
        logon_id: str = "",
    ) -> int | None:
        """Return a visible user shell that can own Linux child process telemetry."""
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        activity_time = ensure_utc(time)
        candidates = []
        for proc in self.state_manager.get_processes_on_system(system.hostname):
            proc_exe = proc.image.rsplit("/", 1)[-1].lower()
            if proc_exe not in {"bash", "sh", "zsh"}:
                continue
            if proc.username != username:
                continue
            if logon_id and proc.logon_id and proc.logon_id != logon_id:
                continue
            if proc.logon_id:
                session = self.state_manager.get_session(proc.logon_id)
                session_end = self.state_manager.get_session_end_time(proc.logon_id)
                if session_end is not None and activity_time >= ensure_utc(session_end):
                    continue
                if session is not None and not _session_active_for_activity(
                    session,
                    activity_time,
                    margin_seconds=1.5,
                ):
                    continue
            if not self._is_pid_active_at(system, proc.pid, activity_time):
                continue
            shell_start = ensure_utc(proc.start_time)
            if (
                scenario_start is not None
                and activity_time >= scenario_start
                and shell_start < scenario_start
            ):
                continue
            candidates.append(proc)
        if not candidates:
            return None
        candidates.sort(key=lambda proc: ensure_utc(proc.start_time), reverse=True)
        return candidates[0].pid

    def ensure_linux_visible_shell_parent(
        self,
        user: User,
        target_system: System,
        activity_time: datetime,
        logon_id: str = "",
        logon_time: datetime | None = None,
        source_visible_by: datetime | None = None,
        existing_only: bool = False,
    ) -> int | None:
        """Create or return a source-visible Linux shell parent for loose user work."""
        activity_time = ensure_utc(activity_time)
        if logon_id and not existing_only:
            session = self.state_manager.get_session(logon_id)
            if session is not None and not _session_active_for_activity(
                session,
                activity_time,
                margin_seconds=1.5,
            ):
                return None
            if session is not None and session.system == target_system.hostname:
                session_shell = self.ensure_linux_session_shell(
                    user=user,
                    target_system=target_system,
                    logon_id=logon_id,
                    logon_time=logon_time or session.start_time,
                    activity_time=activity_time,
                    source_visible_by=source_visible_by,
                )
                if session_shell is not None:
                    return session_shell
        existing = self._active_visible_linux_shell_pid(
            target_system,
            user.username,
            activity_time,
            logon_id,
        )
        if existing is not None:
            return (
                existing
                if self._process_source_bound_visible_by(
                    system=target_system,
                    pid=existing,
                    deadline=source_visible_by,
                )
                else None
            )
        if existing_only:
            return None

        sys_pids = getattr(self, "_system_pids", {}).get(target_system.hostname, {})
        parent_pid = sys_pids.get("systemd") or sys_pids.get("init")
        if (
            not parent_pid
            or self.state_manager.get_process(target_system.hostname, parent_pid) is None
        ):
            if source_visible_by is not None:
                return None
            parent_pid = self._linux_anchor_pid(target_system, activity_time)

        shell_seed = _stable_seed(
            "linux_visible_shell_parent:"
            f"{target_system.hostname}:{user.username}:{logon_id}:{activity_time.isoformat()}"
        )
        readiness_gap = timedelta(milliseconds=2000 + (shell_seed % 5000))
        base_time = ensure_utc(logon_time) if logon_time is not None else None
        shell_time = (
            base_time + timedelta(milliseconds=160 + (shell_seed % 1100))
            if base_time is not None
            else activity_time - readiness_gap
        )
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
        if (
            scenario_start is not None
            and activity_time >= scenario_start
            and shell_time < scenario_start
        ):
            scenario_floor = scenario_start + timedelta(milliseconds=350 + (shell_seed % 2200))
            pre_command_gap = timedelta(seconds=3 + (shell_seed % 60))
            shell_time = max(scenario_floor, activity_time - pre_command_gap)
        latest_shell_time = activity_time - readiness_gap
        if shell_time > latest_shell_time and (base_time is None or latest_shell_time > base_time):
            shell_time = latest_shell_time

        shell_pid = self.generate_process(
            user=user,
            system=target_system,
            time=shell_time,
            logon_id=logon_id,
            process_name="/bin/bash",
            command_line="-bash",
            parent_pid=parent_pid,
            suppress_command_file_effect=True,
            source_visible_by=source_visible_by,
        )
        return shell_pid if shell_pid > 0 else None

    def generate_bash_command(
        self,
        user: User,
        system: System,
        time: datetime,
        activity_type_or_command: str = "default",
        *,
        emit_process_telemetry: bool = True,
    ) -> datetime | None:
        """Generate bash command history entry via dispatch.

        Builds a OccurrenceBuilder with ShellContext and dispatches.
        BashHistoryEmitter.can_handle() filters for Linux-only.

        Args:
            user: User executing command
            system: Linux system
            time: Command execution time
            activity_type_or_command: Either an activity type key (process_code, etc.)
                or a direct command string (if it contains spaces or '/')
            emit_process_telemetry: Whether direct shell commands may emit correlated
                process lifecycle telemetry. Storyline process events set this to False
                because the typed process event already owns the canonical process.
        """
        return LinuxShellCommandActionBundle(
            self,
            LinuxShellCommandRequest(
                user=user,
                system=system,
                time=time,
                activity_type_or_command=activity_type_or_command,
                emit_process_telemetry=emit_process_telemetry,
            ),
        ).execute()

    def _resolve_bash_command(
        self,
        user: User,
        system: System,
        activity_type_or_command: str,
    ) -> str:
        """Return the concrete bash command for an activity key or literal command."""

        _activity_type_commands = {
            "process_code": [
                "vim script.py",
                "nano config.conf",
                "code .",
                "git status",
                "git diff",
                "python3 -m pytest",
                "cat README.md",
            ],
            "process_build": [
                "make",
                "gcc -o output source.c",
                "npm run build",
                "docker build -t app .",
                "cargo build --release",
            ],
            "connection_web": [
                "curl https://example.com",
                "wget https://github.com/repo/file.tar.gz",
                "curl -I https://api.example.com/health",
            ],
            "process_query": [
                "mysql --defaults-extra-file=~/.my.cnf -e 'SHOW DATABASES'",
                "psql -c '\\l'",
                "redis-cli info",
                "mysql --defaults-extra-file=~/.my.cnf -e 'SHOW PROCESSLIST'",
                "psql -c 'SELECT pg_size_pretty(pg_database_size(current_database()))'",
                "sqlite3 /var/lib/app/data.db '.tables'",
            ],
            "process_system": [
                "systemctl status sshd",
                "journalctl -u cron --since '1 hour ago'",
                "top -bn1 | head -20",
                "ss -tulnp",
                "df -h",
                "free -m",
                "dmesg | tail -20",
                "last -10",
            ],
            "process_user_apps": [
                "ls -la",
                "cd /var/www/html",
                "tail -f /var/log/syslog",
                'grep -r "error" /var/log/',
                "systemctl status apache2",
                "free -m",
                "uptime",
                "cat /etc/hostname",
                "netstat -tlnp",
                "du -sh /var/log/*",
                "w",
                'journalctl -u apache2 --since "1 hour ago"',
                "htop",
                "ss -tulnp",
                "ip -o addr show scope global",
            ],
            "default": [
                "ls -la",
                "ps aux",
                "top",
                "df -h",
                "whoami",
                "pwd",
                "cat /etc/os-release",
                "uptime",
                "free -m",
                "w",
                "tail -20 /var/log/syslog",
                "history | tail -20",
                "date",
                "ls /tmp",
                "mount | grep -v tmpfs",
            ],
        }

        if activity_type_or_command in _activity_type_commands:
            command_list = _activity_type_commands[activity_type_or_command]
            if activity_type_or_command == "process_user_apps":
                from evidenceforge.generation.activity.bash_commands import _resolve_server_role

                server_role = _resolve_server_role(
                    system.hostname,
                    list(getattr(system, "services", []) or []),
                )
                if server_role == "db":
                    command_list = [
                        "ls -la",
                        "tail -f /var/log/mysql/error.log",
                        "mysql --defaults-extra-file=~/.my.cnf -e 'SHOW PROCESSLIST'",
                        "pg_isready",
                        "du -sh /var/lib/mysql/*",
                        "systemctl status mysql",
                        "free -m",
                        "uptime",
                        "cat /etc/hostname",
                        "ss -tulnp",
                        "w",
                        "htop",
                        "ip -4 addr show scope global",
                    ]
                elif server_role != "web":
                    web_markers = (
                        "apache",
                        "nginx",
                        "certbot",
                        "/var/www",
                        "ab -n",
                    )
                    command_list = [
                        command
                        for command in command_list
                        if not any(marker in command for marker in web_markers)
                    ]
            from evidenceforge.generation.activity.bash_commands import (
                _choose_template_with_memory,
            )

            command = _choose_template_with_memory(
                _get_rng(),
                command_list,
                {},
                list(getattr(system, "services", []) or []),
                system.hostname,
                user.username,
            )
        else:
            command = activity_type_or_command
        return command

    @staticmethod
    def _should_skip_bash_history(user: User, system: System) -> bool:
        """Return true when bash-history evidence should be suppressed."""

        _ = system
        return _is_noninteractive_bash_user(user)

    @staticmethod
    def _prepare_bash_history_command(system: System, command: str) -> str:
        """Return a source-native command suitable for bash history."""

        if _get_os_category(system.os) == "linux":
            return _background_linux_shell_command_if_needed(command)
        return command

    @staticmethod
    def _bash_history_process_group_id(
        user: User,
        system: System,
        time: datetime,
        command: str,
    ) -> str:
        """Return the internal eCAR marker for bash-history-synchronized processes."""
        seed = _stable_seed(
            "bash_history_process_sync:"
            f"{system.hostname}:{user.username}:{ensure_utc(time).isoformat()}:{command}"
        )
        return f"bash-history:{seed:016x}"

    def _emit_bash_command_event(
        self,
        user: User,
        system: System,
        time: datetime,
        command: str,
    ) -> None:
        """Dispatch a bash-history event at an already scheduled command time."""
        if _is_noninteractive_bash_user(user):
            logger.debug(
                "Skipping bash_history for noninteractive web service user %s on %s",
                user.username,
                system.hostname,
            )
            return

        from evidenceforge.events.contexts import ShellContext

        event = OccurrenceBuilder(
            timestamp=time,
            event_type="bash_command",
            src_host=self._build_host_context(system),
            auth=AuthContext(username=user.username),
            shell=ShellContext(command=command),
        )

        self.dispatcher.dispatch_builder(event)

    def _maybe_emit_bash_process_telemetry(
        self,
        user: User,
        system: System,
        time: datetime,
        command: str,
    ) -> None:
        """Emit process telemetry for interactive Linux shell commands when state supports it."""
        if _get_os_category(system.os) != "linux":
            return
        process_groups = _linux_command_process_groups_from_shell(
            command,
            max_processes=_LINUX_SHELL_MAX_INFERRED_PROCESSES,
            username=user.username,
        )
        if not process_groups:
            return

        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and _session_active_for_activity(session, time, margin_seconds=1.5)
        ]
        if not sessions:
            return
        session = max(sessions, key=lambda candidate: candidate.start_time)
        parent_pid = session.session_shell_pid
        if parent_pid is None or not self._is_pid_active_at(system, parent_pid, time):
            parent_pid = self.ensure_linux_session_shell(
                user=user,
                target_system=system,
                logon_id=session.logon_id,
                logon_time=session.start_time,
                activity_time=time,
            )
        if parent_pid is None:
            return

        rng = random.Random(
            _stable_seed(
                f"bash_process_telemetry:{system.hostname}:{user.username}:{time}:{command}"
            )
        )

        action_group_id = self._bash_history_process_group_id(
            user,
            system,
            time,
            command,
        )
        requested_group_time = time + timedelta(milliseconds=rng.randint(20, 180))
        for group_index, process_group in enumerate(process_groups):
            group_release_times: list[tuple[datetime, str]] = []
            concurrency_group_id = (
                action_group_id
                if len(process_groups) == 1
                else f"{action_group_id}:command:{group_index}"
            )
            base_process_time = self._reserve_foreground_shell_time(
                system=system,
                username=user.username,
                logon_id=session.logon_id,
                parent_pid=parent_pid,
                requested_time=requested_group_time,
                seed_text=f"{command}:command:{group_index}",
                concurrency_group_id=concurrency_group_id,
            )
            stage_times = plan_linux_pipeline_stage_times(
                base_process_time,
                stage_count=len(process_group),
                scope_parts=(
                    system.hostname,
                    user.username,
                    session.logon_id,
                    concurrency_group_id,
                ),
                active_process_count=len(
                    self.state_manager.get_processes_on_system(system.hostname)
                ),
                timing_runtime=self.timing_runtime,
            )
            for (image, process_command_line), process_time in zip(
                process_group, stage_times, strict=True
            ):
                if not self._is_within_scenario_window(process_time):
                    continue
                network_close_time = getattr(session, "network_close_time", None)
                if network_close_time is not None:
                    if network_close_time.tzinfo is None:
                        network_close_time = network_close_time.replace(tzinfo=UTC)
                    else:
                        network_close_time = network_close_time.astimezone(UTC)
                    if process_time >= network_close_time - timedelta(milliseconds=750):
                        continue
                pid = self.generate_process(
                    user=user,
                    system=system,
                    time=process_time,
                    logon_id=session.logon_id,
                    process_name=image,
                    command_line=process_command_line,
                    parent_pid=parent_pid,
                    suppress_command_file_effect=True,
                    concurrency_group_id=concurrency_group_id,
                )
                running_proc = self.state_manager.get_process(system.hostname, pid)
                actual_process_start = (
                    running_proc.start_time if running_proc is not None else process_time
                )
                self._record_user_process(system, user, pid, image)
                lifetime = _linux_foreground_lifetime(image, process_command_line)
                if lifetime is not None:
                    termination_time = self._generate_bounded_foreground_process_termination(
                        user=user,
                        system=system,
                        start_time=actual_process_start,
                        pid=pid,
                        process_name=image,
                        logon_id=session.logon_id,
                        lifetime=lifetime,
                        rng=rng,
                    )
                    group_release_times.append((termination_time, process_command_line))
            for termination_time, process_command_line in group_release_times:
                self._remember_foreground_shell_available(
                    system=system,
                    username=user.username,
                    logon_id=session.logon_id,
                    parent_pid=parent_pid,
                    termination_time=termination_time,
                    seed_text=process_command_line,
                    concurrency_group_id=concurrency_group_id,
                )
            requested_group_time = base_process_time

    def _prepare_bash_process_session(
        self,
        user: User,
        system: System,
        requested_time: datetime,
        command: str,
    ) -> None:
        """Ensure assigned Linux workstation shell commands have session ownership."""
        if _get_os_category(system.os) != "linux":
            return
        if (system.type or "workstation").lower() != "workstation":
            return
        if system.assigned_user != user.username:
            return
        if not _linux_command_processes_from_shell(
            command,
            max_processes=_LINUX_SHELL_MAX_INFERRED_PROCESSES,
            username=user.username,
        ):
            return

        requested_time = ensure_utc(requested_time)
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and session.logon_type not in {3, 5}
            and _session_active_for_activity(session, requested_time, margin_seconds=1.5)
        ]
        if sessions:
            return

        seed = _stable_seed(
            "linux_workstation_bash_session:"
            f"{system.hostname}:{user.username}:{requested_time.isoformat()}:{command}"
        )
        logon_time = requested_time - timedelta(minutes=5 + (seed % 11), seconds=seed % 47)
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
            if requested_time >= scenario_start and logon_time < scenario_start:
                logon_time = scenario_start + timedelta(milliseconds=350 + (seed % 3200))
        if logon_time >= requested_time:
            logon_time = requested_time - timedelta(seconds=2, milliseconds=seed % 500)
        if not self._is_within_scenario_window(logon_time):
            return

        self.generate_logon(
            user=user,
            system=system,
            time=logon_time,
            logon_type=2,
            source_ip="-",
            emit_network_evidence=False,
        )

    def _schedule_bash_history_time(
        self,
        user: User,
        system: System,
        requested_time: datetime,
        command: str,
    ) -> datetime | None:
        """Preserve foreground command dwell time for one user's shell history."""
        requested_time = self._align_linux_bash_after_session_ready(
            user,
            system,
            requested_time,
            command,
        )
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and session.logon_type not in {3, 5}
            and _session_active_for_activity(session, requested_time)
        ]
        logon_id = (
            max(sessions, key=lambda session: ensure_utc(session.start_time)).logon_id
            if sessions
            else ""
        )
        key = (system.hostname, user.username, logon_id)
        scheduled_time = max(
            requested_time,
            self._bash_history_next_time.get(key, requested_time),
            self._bash_history_next_time.get(
                (system.hostname, user.username, ""),
                requested_time,
            ),
        )
        scheduled_time = self._fit_bash_history_time_to_linux_session(
            user,
            system,
            scheduled_time,
        )
        if scheduled_time is None:
            return None
        second_reservation = self._prepare_bash_history_second(
            user,
            system,
            scheduled_time,
            command,
        )
        scheduled_time = second_reservation.scheduled_time
        scheduled_time = self._fit_bash_history_time_to_linux_session(
            user,
            system,
            scheduled_time,
        )
        if scheduled_time is None:
            return None
        scheduled_time = self._align_bash_history_with_foreground_process(
            user,
            system,
            scheduled_time,
            command,
        )
        scheduled_time = self._fit_bash_history_time_to_linux_session(
            user,
            system,
            scheduled_time,
        )
        if scheduled_time is None:
            return None
        self._commit_bash_history_second_no_fail(second_reservation)
        dwell_seconds = _bash_command_dwell_seconds(command)
        jitter_rng = random.Random(
            _stable_seed(
                f"bash_dwell:{system.hostname}:{user.username}:{scheduled_time.timestamp()}:{command}"
            )
        )
        if dwell_seconds <= 2.0:
            command_count = self._bash_history_command_counts.get(key, 0)
            quick_streak = self._bash_history_quick_streaks.get(key, 0)
            roll = jitter_rng.random()
            if command_count == 0:
                extra_delay = jitter_rng.uniform(4.0, 18.0)
            elif roll < 0.16 and quick_streak == 0:
                extra_delay = jitter_rng.uniform(4.0, 12.0)
            elif roll < 0.68:
                extra_delay = jitter_rng.uniform(18.0, 95.0)
            elif roll < 0.93:
                extra_delay = jitter_rng.uniform(95.0, 420.0)
            else:
                extra_delay = jitter_rng.uniform(420.0, 1500.0)
            dwell_seconds += extra_delay
            self._bash_history_quick_streaks[key] = quick_streak + 1 if extra_delay < 14.0 else 0
        elif dwell_seconds < 45.0:
            dwell_seconds = dwell_seconds * jitter_rng.uniform(1.0, 2.2) + jitter_rng.uniform(
                4.0, 18.0
            )
        else:
            dwell_seconds = max(dwell_seconds, dwell_seconds * jitter_rng.uniform(0.95, 1.35))
            self._bash_history_quick_streaks[key] = 0
        completion_time = scheduled_time + timedelta(seconds=dwell_seconds)
        self._bash_history_command_counts[key] = self._bash_history_command_counts.get(key, 0) + 1
        self._bash_history_next_time[key] = completion_time
        self._remember_linux_bash_session_activity(
            user,
            system,
            scheduled_time,
            completion_time,
        )
        return scheduled_time

    def _align_bash_history_with_foreground_process(
        self,
        user: User,
        system: System,
        scheduled_time: datetime,
        command: str,
    ) -> datetime:
        """Move bash history to the same foreground-shell slot as process telemetry."""
        if _get_os_category(system.os) != "linux":
            return scheduled_time
        if not _linux_command_processes_from_shell(
            command,
            max_processes=_LINUX_SHELL_MAX_INFERRED_PROCESSES,
            username=user.username,
        ):
            return scheduled_time

        activity_time = ensure_utc(scheduled_time)
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and session.logon_type not in {3, 5}
            and _session_active_for_activity(session, activity_time, margin_seconds=1.5)
        ]
        if not sessions:
            return scheduled_time
        session = max(sessions, key=lambda candidate: ensure_utc(candidate.start_time))

        parent_pid = session.session_shell_pid
        if parent_pid is None or not self._is_pid_active_at(system, parent_pid, activity_time):
            parent_pid = self._active_session_shell_pid(
                system,
                user,
                activity_time,
                session.logon_id,
            )
        if parent_pid is None:
            return scheduled_time

        return self._reserve_foreground_shell_time(
            system=system,
            username=user.username,
            logon_id=session.logon_id,
            parent_pid=parent_pid,
            requested_time=activity_time,
            seed_text=command,
        )

    def _remember_linux_bash_session_activity(
        self,
        user: User,
        system: System,
        scheduled_time: datetime,
        completion_time: datetime,
    ) -> None:
        """Record shell-history activity on the concrete session that owns it."""
        if _get_os_category(system.os) != "linux":
            return
        activity_time = ensure_utc(scheduled_time)
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and session.logon_type not in {3, 5}
            and _session_active_for_activity(session, activity_time)
        ]
        if not sessions:
            return
        session = max(sessions, key=lambda candidate: ensure_utc(candidate.start_time))
        marker = ensure_utc(completion_time)
        activity_end = _session_activity_end_time(session)
        if activity_end is not None:
            marker = min(marker, activity_end - timedelta(milliseconds=900))
        if session.last_activity_time is None or marker > ensure_utc(session.last_activity_time):
            session.last_activity_time = marker

    def _fit_bash_history_time_to_linux_session(
        self,
        user: User,
        system: System,
        scheduled_time: datetime,
    ) -> datetime | None:
        """Return a concrete session-owned bash timestamp for Linux shell history."""
        if _get_os_category(system.os) != "linux":
            return scheduled_time
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind not in {"network", "service"}
            and session.logon_type not in {3, 5}
        ]
        strict_server_session = (system.type or "workstation").lower() == "server" and getattr(
            self, "_scenario_start_time", None
        ) is not None
        if not sessions:
            if strict_server_session:
                return None
            last_close = self._linux_shell_last_session_close.get((system.hostname, user.username))
            if last_close is not None and ensure_utc(scheduled_time) >= ensure_utc(last_close):
                return None
            return scheduled_time

        activity_time = ensure_utc(scheduled_time)
        sessions.sort(key=lambda session: ensure_utc(session.start_time))
        for session in sessions:
            window_start = _session_source_ready_time(session) or ensure_utc(session.start_time)
            candidate_time = max(activity_time, window_start)
            if _session_active_for_activity(
                session,
                candidate_time,
                margin_seconds=0.9,
            ):
                return candidate_time
        return None

    def _align_linux_bash_after_session_ready(
        self,
        user: User,
        system: System,
        requested_time: datetime,
        command: str,
    ) -> datetime:
        """Shift visible Linux shell commands after SSH auth/PAM/eCAR session readiness."""
        if _get_os_category(system.os) != "linux":
            return requested_time
        activity_time = ensure_utc(requested_time)
        sessions = [
            session
            for session in self.state_manager.get_sessions_for_user(user.username)
            if session.system == system.hostname
            and session.session_kind == "ssh"
            and _session_active_for_activity(session, activity_time)
        ]
        if not sessions:
            return requested_time
        session = max(sessions, key=lambda candidate: ensure_utc(candidate.start_time))
        ready_time = _session_source_ready_time(session)
        if ready_time is None or activity_time >= ready_time:
            return requested_time
        ready_seed = _stable_seed(
            "linux_bash_after_ssh_ready:"
            f"{system.hostname}:{user.username}:{session.logon_id}:{command}:{activity_time}"
        )
        return ready_time + timedelta(milliseconds=180 + (ready_seed % 420))

    def _prepare_bash_history_second(
        self,
        user: User,
        system: System,
        scheduled_time: datetime,
        command: str,
    ) -> _BashHistorySecondReservation:
        """Prepare exact same-user collision updates without allocating them."""
        username_key = user.username.lower()
        candidate = scheduled_time
        updated_counts: dict[_BashHistorySecondKey, int] = {}
        for attempt in range(8):
            second_key = (username_key, int(candidate.timestamp()))
            if second_key in updated_counts:
                collision_count = updated_counts[second_key]
            elif second_key in self._bash_history_user_seconds:
                collision_count = self._bash_history_user_seconds[second_key]
            else:
                updated_counts[second_key] = 1
                return _BashHistorySecondReservation(
                    scheduled_time=candidate,
                    updated_counts=tuple(updated_counts.items()),
                )
            updated_counts[second_key] = collision_count + 1
            delay_rng = random.Random(
                _stable_seed(
                    "bash_user_second_collision:"
                    f"{username_key}:{system.hostname}:{command}:"
                    f"{candidate.timestamp()}:{attempt}:{collision_count}"
                )
            )
            candidate += timedelta(seconds=delay_rng.randint(1, 23))

        second_key = (username_key, int(candidate.timestamp()))
        updated_counts[second_key] = (
            updated_counts.get(
                second_key,
                self._bash_history_user_seconds.get(second_key, 0),
            )
            + 1
        )
        return _BashHistorySecondReservation(
            scheduled_time=candidate,
            updated_counts=tuple(updated_counts.items()),
        )

    def _commit_bash_history_second_no_fail(
        self,
        reservation: _BashHistorySecondReservation,
    ) -> None:
        """Publish one already-fitted Bash user-second reservation."""
        self._bash_history_user_seconds.update(reservation.updated_counts)

    def generate_bash_command_with_noise(
        self,
        user: User,
        system: System,
        time: datetime,
        command: str,
    ) -> None:
        """Generate a bash command with organic noise commands around it.

        Emits the primary command plus 0-3 organic noise commands at
        slight time offsets, simulating an attacker or admin who types
        ls, pwd, id etc. between deliberate actions.
        """
        # Emit the primary command
        self.generate_bash_command(user, system, time, command)

        # Probabilistically emit 0-3 noise commands (role-aware)
        from evidenceforge.generation.activity.bash_commands import pick_bash_command_entry

        rng = _get_rng()
        n_noise = rng.choices([0, 1, 1, 2, 2, 3], k=1)[0]
        typo_count = 0
        # Complexity-aware inter-command delays
        _COMPLEX_PREFIXES = ("nmap", "find ", "tar ", "rsync", "make", "docker", "ansible")
        _MEDIUM_PREFIXES = ("curl", "wget", "scp", "ssh ", "mysql", "psql", "pip", "apt", "yum")
        cumulative_delay = 0.0
        prev_cmd = command
        for _ in range(n_noise):
            # Delay based on complexity of previous command
            if any(prev_cmd.startswith(p) for p in _COMPLEX_PREFIXES):
                delay = rng.uniform(20.0, 120.0)
            elif any(prev_cmd.startswith(p) for p in _MEDIUM_PREFIXES):
                delay = rng.uniform(8.0, 45.0)
            else:
                delay = rng.choice(
                    [
                        rng.uniform(4.0, 14.0),
                        rng.uniform(18.0, 90.0),
                        rng.uniform(90.0, 240.0),
                    ]
                )
            cumulative_delay += delay
            noise_time = time + timedelta(seconds=cumulative_delay)
            noise_cmd, is_typo = pick_bash_command_entry(
                rng,
                user.persona or "",
                system.hostname,
                system.services,
                username=user.username,
                session_command_count=n_noise + 1,
                prior_typo_count=typo_count,
                system_os=system.os,
            )
            if is_typo:
                typo_count += 1
            self.generate_bash_command(user, system, noise_time, noise_cmd)
            prev_cmd = noise_cmd

    def generate_system_process(
        self,
        system: System,
        time: datetime,
        process_name: str,
        command_line: str,
        parent_pid: int = 4,
        username: str = "SYSTEM",
        syslog_message: str | None = None,
        *,
        emit_linux_syslog: bool = True,
        concurrency_group_id: str = "",
        _profiled_service_bypass: bool = False,
        _skip_singleton_reuse: bool = False,
        source_visible_by: datetime | None = None,
    ) -> int:
        """Generate a system process creation event (no user session required).

        Used for scheduled tasks, service spawns, and other system-initiated
        processes that don't have an associated user logon session.

        Args:
            system: System where process is created
            time: Process creation timestamp
            process_name: Full path to executable
            command_line: Command line string
            parent_pid: Parent process PID
            username: System account name (SYSTEM, root, etc.)
            syslog_message: Custom syslog message (overrides auto-generated message)
            emit_linux_syslog: Whether to attach a Linux syslog record to this process event.
            concurrency_group_id: Optional source-local process group for related
                foreground children such as cron shell/workload pairs.
            source_visible_by: Optional deadline for every process-create source view.

        Returns:
            PID of the new process
        """
        from evidenceforge.events.contexts import ProcessContext

        source_deadline = ensure_utc(source_visible_by) if source_visible_by is not None else None
        if source_deadline is not None and ensure_utc(time) > source_deadline:
            return 0
        if source_deadline is None:
            self.state_manager.set_current_time(time)
        if _get_os_category(system.os) == "windows":
            process_name, command_line = _windows_script_host_process(
                process_name,
                command_line,
            )

        if not _profiled_service_bypass:
            profiled_worker = matching_service_worker(
                os_category=_get_os_category(system.os),
                image=process_name,
                command_line=command_line,
                username=username,
            )
            if profiled_worker is not None:
                family_name, worker_name, _family = profiled_worker
                return self._ensure_profiled_service_worker(
                    system=system,
                    worker_time=time,
                    activity_time=time,
                    family_name=family_name,
                    worker_name=worker_name,
                    source_visible_by=source_visible_by,
                )

        exe_name = ntpath.basename(process_name).lower()
        if (
            _get_os_category(system.os) == "windows"
            and exe_name in _WINDOWS_SHELL_UWP_USER_PROCESS_EXES
        ):
            session = self._active_interactive_windows_session(system, time)
            if session is None:
                return 0
            session_user = self._user_model_for_username(session.username)
            if self.state_manager.get_process(system.hostname, parent_pid) is None:
                parent_pid = (
                    self._resolve_existing_prepared_process_parent(
                        system=system,
                        user=session_user,
                        time=time,
                        logon_id=session.logon_id,
                        parent_pid=parent_pid,
                        process_username=session_user.username,
                    )
                    if source_deadline is not None
                    else self._resolve_parent(
                        system,
                        session_user,
                        time,
                        session.logon_id,
                        process_name,
                    )
                )
            if source_deadline is not None:
                source_floor = ensure_utc(time)
                session_ready = _session_source_ready_time(session)
                if session_ready is not None:
                    source_floor = max(
                        source_floor,
                        session_ready + timedelta(milliseconds=1),
                    )
                parent_visible_time = self._process_source_frontier_or_bound(
                    system=system,
                    pid=parent_pid,
                )
                persistent_app_pid = self._existing_persistent_user_app_pid(
                    system=system,
                    username=session_user.username,
                    logon_id=session.logon_id,
                    process_name=process_name,
                    command_line=command_line,
                    time=time,
                    source_visible_by=source_deadline,
                )
                if persistent_app_pid is not None:
                    return persistent_app_pid
                if parent_visible_time is not None:
                    source_floor = max(
                        source_floor,
                        ensure_utc(parent_visible_time) + timedelta(milliseconds=1),
                    )
                prepared_actor = self._prepare_process_effect_actor(
                    ProcessExecutionRequest(
                        user=session_user,
                        system=system,
                        time=time,
                        logon_id=session.logon_id,
                        process_name=process_name,
                        command_line=command_line,
                        parent_pid=parent_pid,
                        allow_existing_browser_reuse=False,
                        source_visible_by=source_visible_by,
                    )
                )
                source_floor = max(
                    source_floor,
                    self._process_create_source_bound(
                        system=system,
                        canonical_time=prepared_actor.started_at,
                        parent_source_time=parent_visible_time,
                        session_source_time=session_ready,
                    ),
                )
                if source_floor > source_deadline:
                    return 0
            return self.generate_process(
                user=session_user,
                system=system,
                time=time,
                logon_id=session.logon_id,
                process_name=process_name,
                command_line=command_line,
                parent_pid=parent_pid,
                allow_existing_browser_reuse=False,
                source_visible_by=source_visible_by,
            )

        singleton_service_pid = None
        if not _skip_singleton_reuse:
            singleton_service_pid = self._existing_windows_singleton_service_pid(
                system=system,
                process_name=process_name,
                time=time,
                username=username,
                command_line=command_line,
            )
        if singleton_service_pid is not None:
            if not self._process_source_visible_by(
                hostname=system.hostname,
                pid=singleton_service_pid,
                deadline=source_deadline,
            ):
                return 0
            return singleton_service_pid

        system_logon_ids = {"SYSTEM": "0x3e7", "LOCAL SERVICE": "0x3e5", "NETWORK SERVICE": "0x3e4"}
        logon_id = system_logon_ids.get(username, "0x3e7")
        if source_deadline is not None:
            parent_pid = self._resolve_existing_prepared_process_parent(
                system=system,
                user=self._user_model_for_username(username),
                time=time,
                logon_id=logon_id,
                parent_pid=parent_pid,
                process_username=username,
            )
        else:
            parent_pid = self._repair_process_parent_pid(
                system=system,
                time=time,
                logon_id=logon_id,
                process_name=process_name,
                command_line=command_line,
                parent_pid=parent_pid,
                process_username=username,
            )
        repaired_parent = self.state_manager.get_process(system.hostname, parent_pid)
        if repaired_parent is not None and time <= repaired_parent.start_time:
            time = repaired_parent.start_time + timedelta(milliseconds=50)
        source_floor = ensure_utc(time)
        parent_visible_time = None
        if parent_pid > 0:
            parent_visible_time = self._process_source_frontier_or_bound(
                system=system,
                pid=parent_pid,
            )
            if parent_visible_time is not None:
                source_floor = max(
                    source_floor,
                    ensure_utc(parent_visible_time) + timedelta(milliseconds=1),
                )
        if source_deadline is not None:
            source_floor = max(
                source_floor,
                self._process_create_source_bound(
                    system=system,
                    canonical_time=time,
                    parent_source_time=parent_visible_time,
                ),
            )
            if source_floor > source_deadline:
                return 0
        self.state_manager.set_current_time(time)
        self.state_manager.update_process_activity_time(system.hostname, parent_pid, time)
        pid = self.state_manager.create_process(
            system=system.hostname,
            parent_pid=parent_pid,
            image=process_name,
            command_line=command_line,
            username=username,
            integrity_level="System",
            logon_id=logon_id,
        )

        # Determine system-level SID and logon ID
        sid = self.sid_registry.get(username, "S-1-5-18") if self.sid_registry else "S-1-5-18"

        self.state_manager.get_process_object_id(system.hostname, pid)
        self.state_manager.get_process_object_id(system.hostname, parent_pid)
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="system_process_create",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=username,
                user_sid=sid,
                logon_id=logon_id,
                subject_sid=sid,
                subject_username=username,
                subject_domain="NT AUTHORITY",
                subject_logon_id=logon_id,
            ),
            process=ProcessContext(
                pid=pid,
                parent_pid=parent_pid,
                image=process_name,
                command_line=command_line,
                username=username,
                integrity_level="System",
                logon_id=logon_id,
                parent_image=self._lookup_parent_image(system.hostname, parent_pid),
                parent_command_line=self._lookup_parent_command_line(system.hostname, parent_pid),
                parent_start_time=self._lookup_parent_start_time(system.hostname, parent_pid),
                token_elevation="%%1936",
                mandatory_label="S-1-16-16384",
                start_time=self._lookup_parent_start_time(system.hostname, pid),
                current_directory=self._derive_current_directory(
                    system=system,
                    username=username,
                    process_name=process_name,
                    command_line=command_line,
                    parent_pid=parent_pid,
                ),
                concurrency_group_id=concurrency_group_id,
            ),
        )

        self._record_process_source_create_time(
            system.hostname,
            pid,
            event,
            not_after=source_visible_by,
            publish_finalized=False,
        )
        # Attach SyslogContext for Linux hosts
        if emit_linux_syslog and event.src_host and event.src_host.os_category == "linux":
            from evidenceforge.events.contexts import SyslogContext

            if syslog_message:
                event.syslog = SyslogContext(
                    app_name="systemd",
                    pid=1,
                    facility=3,
                    severity=6,
                    message=syslog_message,
                )
            elif "cron" in (process_name or "").lower():
                event.syslog = SyslogContext(
                    app_name="CRON",
                    pid=pid,
                    facility=9,
                    severity=6,
                    message=f"({username}) CMD ({command_line})",
                )
            else:
                app_name = process_name.split("/")[-1]
                event.syslog = SyslogContext(
                    app_name=app_name,
                    pid=pid,
                    facility=3,
                    severity=6,
                    message=f"started: {command_line}",
                )

        self.dispatcher.dispatch_builder(event)
        self._record_process_source_create_time(
            system.hostname,
            pid,
            event,
            not_after=source_visible_by,
        )

        return pid

    def generate_system_process_termination(
        self,
        system: System,
        time: datetime,
        pid: int,
        process_name: str,
        parent_pid: int = 0,
        username: str = "root",
        syslog_message: str | None = None,
        *,
        concurrency_group_id: str = "",
    ) -> None:
        """Terminate a system process, emitting eCAR PROCESS/TERMINATE + optional syslog.

        Unlike generate_process_termination(), this doesn't require a user session.
        Used for short-lived system service processes (systemd units, etc.).
        """
        from evidenceforge.events.contexts import ProcessContext

        if self._is_protected_windows_system_pid(system, pid):
            self.state_manager.update_process_activity_time(system.hostname, pid, time)
            return

        running_proc = self.state_manager.get_process(system.hostname, pid)
        if running_proc is not None:
            process_name = running_proc.image
            username = running_proc.username or username
            if (
                running_proc.last_activity_time is not None
                and time <= running_proc.last_activity_time
            ):
                delay_ms = 20 + (
                    _stable_seed(
                        "system_process_terminate_after_activity:"
                        f"{system.hostname}:{pid}:{running_proc.last_activity_time.isoformat()}"
                    )
                    % 480
                )
                time = running_proc.last_activity_time + timedelta(milliseconds=delay_ms)
        process_logon_id = (
            running_proc.logon_id
            if running_proc is not None and running_proc.logon_id
            else {"SYSTEM": "0x3e7", "LOCAL SERVICE": "0x3e5", "NETWORK SERVICE": "0x3e4"}.get(
                username, "0x3e7"
            )
        )
        if parent_pid not in (0, pid):
            self.state_manager.update_process_activity_time(system.hostname, parent_pid, time)
        time = self._clamp_after_visible_process_create(
            system,
            pid,
            time,
            "windows.process_exit_after_visible_create",
        )
        sid = self.sid_registry.get(username, "S-1-5-18") if self.sid_registry else "S-1-5-18"
        self.state_manager.get_process_object_id(system.hostname, pid)
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="process_terminate",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=username,
                user_sid=sid,
                logon_id=process_logon_id,
                subject_sid=sid,
                subject_username=username,
                subject_domain="NT AUTHORITY",
                subject_logon_id=process_logon_id,
            ),
            process=ProcessContext(
                pid=pid,
                parent_pid=parent_pid,
                image=process_name,
                command_line="",
                username=username,
                logon_id=process_logon_id,
                start_time=running_proc.start_time if running_proc is not None else None,
                concurrency_group_id=concurrency_group_id,
            ),
        )

        if syslog_message and event.src_host and event.src_host.os_category == "linux":
            from evidenceforge.events.contexts import SyslogContext

            event.syslog = SyslogContext(
                app_name="systemd",
                pid=1,
                facility=3,
                severity=6,
                message=syslog_message,
            )

        self.dispatcher.dispatch_builder(event)

    def _is_protected_windows_system_pid(self, system: System, pid: int) -> bool:
        """Return whether a PID belongs to the durable seeded Windows process tree."""
        if _get_os_category(system.os) != "windows":
            return False
        system_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        return pid in set(system_pids.values())

    def _dns_observed_ttls(
        self,
        *,
        resolver_ip: str,
        query: str,
        qtype_name: str,
        answers: list[str],
        is_internal: bool,
        base_ttl: int,
        time: datetime,
    ) -> list[float]:
        """Return resolver-consistent TTLs for a DNS RRset observation."""
        if not answers:
            return []
        bounded_ttl = max(1, int(base_ttl))
        if is_internal:
            return [float(bounded_ttl)] * len(answers)

        ts_epoch = time.timestamp()
        normalized_query = query.rstrip(".").lower()
        normalized_answers = tuple(sorted(str(answer) for answer in answers))
        cache_key = (resolver_ip, normalized_query, qtype_name.upper(), normalized_answers)
        offset = _stable_seed(f"dns_rrset_cache_cycle:{cache_key}") % bounded_ttl
        cycle_start = math.floor((ts_epoch - offset) / bounded_ttl) * bounded_ttl + offset
        age = max(0.0, ts_epoch - cycle_start)
        remaining = max(1, int(bounded_ttl - age))
        return [float(remaining)] * len(answers)

    def _normalize_dns_context_for_resolver(
        self,
        dns: DnsContext,
        *,
        resolver_ip: str,
        time: datetime,
    ) -> None:
        """Normalize caller-provided DNS context through shared resolver semantics."""
        ad_domain = getattr(self, "_ad_domain", "corp.local")
        qtype_name = (dns.query_type or "").upper()
        if qtype_name in {"A", "AAAA", "PTR", "MX", "NS", "SOA"}:
            dns.query = self._dns_canonical_internal_hostname(dns.query) or dns.query
        reverse_ip = _dns_reverse_ipv4(dns.query) if qtype_name == "PTR" else None
        reverse_name = self._scenario_fqdn_for_ip(reverse_ip) if reverse_ip else None
        if reverse_name and dns.rcode == "NOERROR" and dns.answers:
            dns.answers = [reverse_name]
        email_dns_system = self._email_dns_system_for_hostname(dns.query)
        email_dns_ip = str(getattr(email_dns_system, "ip", "") or "") if email_dns_system else ""
        if email_dns_ip and qtype_name == "A":
            dns.answers = [email_dns_ip]
        elif email_dns_ip and qtype_name == "AAAA":
            dns.answers = _public_dns_aaaa_answers(
                dns.query,
                email_dns_ip,
                is_internal=True,
            )
        is_internal = (
            qtype_name == "SRV"
            or _dns_is_internal_name(dns.query, ad_domain)
            or bool(reverse_ip and _is_private_ip(reverse_ip))
            or email_dns_system is not None
        )
        if is_internal:
            dns.AA = True
        elif qtype_name != "TXT":
            dns.AA = False

        if dns.rcode != "NOERROR" or not dns.answers:
            return
        if dns.preserve_ttls and len(dns.TTLs) == len(dns.answers):
            return
        if not is_internal and qtype_name == "TXT" and len(dns.TTLs) == len(dns.answers):
            base_ttl = max(1, int(min(dns.TTLs)))
        else:
            base_ttl = _dns_base_ttl(dns.query, is_internal)
        dns.TTLs = self._dns_observed_ttls(
            resolver_ip=resolver_ip,
            query=dns.query,
            qtype_name=qtype_name or str(dns.qtype),
            answers=dns.answers,
            is_internal=is_internal,
            base_ttl=base_ttl,
            time=time,
        )

    def _dns_observation_time_is_visible(self, time: datetime) -> bool:
        """Return whether DNS evidence at time can reach source emitters."""
        dispatcher = getattr(self, "dispatcher", None)
        gate = getattr(dispatcher, "output_start_time", None)
        if gate is None:
            return True
        ts = time
        if ts.tzinfo is not None and gate.tzinfo is None:
            ts = ts.replace(tzinfo=None)
        elif ts.tzinfo is None and gate.tzinfo is not None:
            gate = gate.replace(tzinfo=None)
        return ts >= gate

    def _dns_observation_epoch_is_visible(self, epoch: float) -> bool:
        """Return whether a cached DNS observation epoch was inside the output window."""
        dispatcher = getattr(self, "dispatcher", None)
        gate = getattr(dispatcher, "output_start_time", None)
        if gate is None:
            return True
        if gate.tzinfo is None:
            return datetime.fromtimestamp(epoch) >= gate
        return datetime.fromtimestamp(epoch, tz=gate.tzinfo) >= gate

    def _emit_dns_lookup(
        self,
        src_ip: str,
        dst_ip: str,
        time: datetime,
        hostname: str | None = None,
        force_address: bool = False,
        bypass_cache: bool = False,
        source_system: System | None = None,
        source_pid: int = -1,
        source_process_image: str = "",
        planned_query_time: datetime | None = None,
        planned_rtt_seconds: float | None = None,
        parent_action_group_id: str | None = None,
    ) -> None:
        """Emit a DNS lookup preceding a TCP connection.

        Generates both a Zeek conn.log UDP/53 record and a Zeek dns.log record
        with consistent fields. The dns.log answers field contains the dst_ip
        that the subsequent TCP connection will use.

        Args:
            src_ip: IP of the system making the query
            dst_ip: IP that will be resolved (the "answer")
            time: Timestamp of the DNS query (should precede TCP connection)
            hostname: Explicit domain name to use (bypasses REVERSE_DNS lookup)
            force_address: Force an A/AAAA lookup for connection prerequisites.
            bypass_cache: Emit a lookup even when the generator cache has a valid entry.
        """
        request = DnsLookupRequest(
            src_ip=src_ip,
            dst_ip=dst_ip,
            time=time,
            hostname=hostname,
            force_address=force_address,
            bypass_cache=bypass_cache,
            source_system=source_system,
            source_pid=source_pid,
            source_process_image=source_process_image,
            planned_query_time=planned_query_time,
            planned_rtt_seconds=planned_rtt_seconds,
            parent_action_group_id=parent_action_group_id,
        )
        DnsLookupActionBundle(executor=self, request=request).execute()

    def _dns_query_process_context(
        self,
        request: DnsLookupRequest,
        source_system: System | None,
        query_time: datetime,
    ) -> ProcessContext | None:
        """Return a query process only when it existed at the DNS occurrence time."""
        if source_system is None or request.source_pid <= 0:
            return None
        running = self.state_manager.get_process(source_system.hostname, request.source_pid)
        if running is None or ensure_utc(running.start_time) > ensure_utc(query_time):
            return None
        if self._process_termination_recorded(
            source_system.hostname,
            request.source_pid,
            running.start_time,
        ):
            return None
        return ProcessContext(
            pid=running.pid,
            parent_pid=running.parent_pid,
            image=running.image or request.source_process_image,
            command_line=running.command_line,
            username=running.username,
            logon_id=running.logon_id,
            start_time=running.start_time,
        )

    def _sample_dns_timing_milliseconds(
        self,
        *,
        relationship_key: str,
        stable_id: str,
        host: str,
        lifecycle_id: str,
        sample_key: str,
        minimum_ms: int,
        maximum_ms: int,
        ordinal: int = 0,
    ) -> int:
        """Sample one integer-millisecond DNS gap through the engine-owned runtime."""

        runtime = self.timing_runtime
        if type(runtime) not in {TimingRuntime, SourceTimingPlanningRuntime}:
            raise StateError("DNS timing requires the exact engine-owned runtime")
        if (
            type(relationship_key) is not str
            or not relationship_key
            or type(stable_id) is not str
            or not stable_id
            or type(host) is not str
            or not host
            or type(lifecycle_id) is not str
            or not lifecycle_id
            or type(sample_key) is not str
            or not sample_key
            or type(minimum_ms) is not int
            or type(maximum_ms) is not int
            or type(ordinal) is not int
        ):
            raise StateError("DNS timing scope and support must use exact built-in values")
        sampled = runtime.sampler.sample_value(
            _dns_inclusive_millisecond_distribution(minimum_ms, maximum_ms),
            relationship_key=relationship_key,
            scope=TimingScope(
                stable_id=stable_id,
                host=host,
                source="dns_lookup",
                lifecycle_id=lifecycle_id,
                ordinal=ordinal,
            ),
            sample_key=sample_key,
        )
        return int(sampled + 0.5)

    def _execute_dns_lookup_bundle(self, request: DnsLookupRequest) -> None:
        """Expand one DNS lookup request into canonical evidence."""
        src_ip = request.src_ip
        dst_ip = request.dst_ip
        time = request.time
        hostname = request.hostname
        force_address = request.force_address

        rng = _get_rng()

        # Use explicit hostname if provided (domain-first selection), then the
        # current scenario's owned systems, and only then packaged DNS data.
        if not hostname:
            hostname = self._scenario_fqdn_for_ip(dst_ip) or REVERSE_DNS.get(dst_ip)
        if not hostname:
            if _is_private_ip(dst_ip):
                hostname = _generate_internal_hostname(
                    rng, dst_ip, getattr(self, "_ad_domain", "corp.local")
                )
            else:
                hostname = _generate_random_hostname(rng, dst_ip)
        hostname = self._dns_canonical_internal_hostname(hostname) or hostname
        email_dns_system = self._email_dns_system_for_hostname(hostname)
        email_dns_ip = str(getattr(email_dns_system, "ip", "") or "") if email_dns_system else ""

        # DNS caching: skip re-emission if this source/resolver/hostname tuple
        # still has a client-visible address answer. Values are expiration
        # epochs derived from the TTL actually returned in dns.log, not the
        # authoritative TTL, so later TCP evidence does not depend on visibly
        # expired DNS answers.
        if not hasattr(self, "_dns_cache"):
            self._dns_cache = ExpiringIndex(deadline=lambda window: _dns_cache_window(window)[1])
        elif not isinstance(self._dns_cache, ExpiringIndex):
            existing_dns_cache = self._dns_cache
            self._dns_cache = ExpiringIndex(deadline=lambda window: _dns_cache_window(window)[1])
            self._dns_cache.update(existing_dns_cache)
        if not hasattr(self, "_dns_cache_last_prune"):
            self._dns_cache_last_prune = 0.0

        ts_epoch = time.timestamp()

        # Keep the cache bounded: drop entries older than the max TTL horizon,
        # and enforce a hard cap under high-cardinality/adversarial inputs.
        if ts_epoch - self._dns_cache_last_prune >= 60 or len(self._dns_cache) > 50_000:
            cutoff = ts_epoch
            self._dns_cache.expire_before(cutoff)
            if len(self._dns_cache) > 50_000:
                self._dns_cache.trim(
                    50_000,
                    rank=lambda _key, cached_window: cached_window,
                    reverse=True,
                )
            self._dns_cache_last_prune = ts_epoch

        ad_domain = getattr(self, "_ad_domain", "corp.local")
        is_email_internal_name = email_dns_system is not None
        is_internal = _dns_is_internal_name(hostname, ad_domain) or is_email_internal_name

        # Determine DNS server IP from network visibility or use default. Forward
        # proxies use a sticky configured resolver policy instead of rotating
        # evenly across unrelated public DNS providers.
        src_system = request.source_system or getattr(self, "_ip_to_system", {}).get(src_ip)
        dns_ips = self._dns_resolver_ips_for_source(src_ip)
        if is_internal and getattr(self, "_dns_server_ips_are_public_fallback", False):
            return
        if src_system and "forward_proxy" in (src_system.roles or []) and not is_internal:
            resolver_pool = [ip for ip in dns_ips if _is_private_ip(ip)] or dns_ips
            resolver_rng = random.Random(_stable_seed(f"proxy_dns_policy:{src_ip}"))
            primary_index = resolver_rng.randrange(len(resolver_pool))
            secondary_index = (
                primary_index + 1 + resolver_rng.randrange(max(1, len(resolver_pool) - 1))
            ) % len(resolver_pool)
            primary_resolver = resolver_pool[primary_index]
            secondary_resolver = resolver_pool[secondary_index]
            resolver_roll = random.Random(
                _stable_seed(f"proxy_dns_roll:{src_ip}:{hostname}:{int(ts_epoch // 300)}")
            ).random()
            dns_server_ip = primary_resolver if resolver_roll < 0.92 else secondary_resolver
        else:
            dns_server_ip = _get_rng().choice(dns_ips)

        cache_key = (src_ip, dns_server_ip, hostname, "ADDR")
        cached_at, cached_until = _dns_cache_window(self._dns_cache.get(cache_key))
        if force_address and not request.bypass_cache and cached_at <= ts_epoch < cached_until:
            if not self._dns_observation_time_is_visible(
                time
            ) or self._dns_observation_epoch_is_visible(cached_at):
                return  # Cache hit — skip DNS emission

        _src_os = "windows"
        if src_system is not None:
            _src_os = _get_os_category(src_system.os)
        dns_timing_host = src_system.hostname if src_system is not None else src_ip
        dns_timing_lifecycle = request.parent_action_group_id or request.stable_id
        if request.planned_query_time is not None:
            dns_time = request.planned_query_time
        else:
            query_lead_ms = self._sample_dns_timing_milliseconds(
                relationship_key="activity.dns.query_before_request",
                stable_id=request.stable_id,
                host=dns_timing_host,
                lifecycle_id=dns_timing_lifecycle,
                sample_key="query_lead_ms",
                minimum_ms=900,
                maximum_ms=1400,
            )
            dns_time = time - timedelta(milliseconds=query_lead_ms)
        query_process = self._dns_query_process_context(request, src_system, dns_time)
        src_port = self._allocate_ephemeral_port(
            src_ip, dns_server_ip, 53, "udp", dns_time, _src_os
        )

        from evidenceforge.events.contexts import DnsContext

        # Phase 6.3: 0.2% chance of SERVFAIL (transient failures).
        # Known internal names are served by authoritative internal DNS and
        # should not randomly fail unless a scenario explicitly models DNS trouble.
        if not force_address and not is_internal and rng.random() < 0.002:
            dns_ctx = DnsContext(
                query=hostname,
                trans_id=rng.randint(1, 65535),
                qtype=1,
                query_type="A",
                rcode="SERVFAIL",
                rcode_num=2,
                query_process=query_process,
            )
            self.generate_connection(
                src_ip=src_ip,
                dst_ip=dns_server_ip,
                time=dns_time,
                dst_port=53,
                proto="udp",
                service="dns",
                duration=rng.uniform(0.001, 0.03),
                orig_bytes=rng.randint(40, 100),
                resp_bytes=rng.randint(80, 400),
                src_port=src_port,
                dns=dns_ctx,
                parent_action_group_id=request.parent_action_group_id,
                preserve_start_time=request.planned_query_time is not None,
            )
            return

        # Determine query type, query string, and answer
        qtype_roll = 0.0 if force_address else rng.random()
        txt_ttl: int | None = None

        if ":" in dst_ip and force_address:
            qtype, qtype_name = 28, "AAAA"
            query = hostname
            answers = [_IPV6_MAP.get(email_dns_ip, dst_ip) if email_dns_ip else dst_ip]
        elif qtype_roll < 0.65:
            # A record: hostname → IPv4
            qtype, qtype_name = 1, "A"
            query = hostname
            answers = (
                [email_dns_ip]
                if email_dns_ip
                else _dns_address_rrset(
                    hostname,
                    dst_ip,
                    is_internal=is_internal,
                )
            )
        elif qtype_roll < 0.85:
            # AAAA record: hostname → IPv6
            qtype, qtype_name = 28, "AAAA"
            query = hostname
            answers = _public_dns_aaaa_answers(
                hostname,
                email_dns_ip or dst_ip,
                is_internal=is_internal,
            )
        elif qtype_roll < 0.93:
            # PTR record: reversed IP → rDNS name
            qtype, qtype_name = 12, "PTR"
            query = _dns_reverse_query(dst_ip)
            if _is_private_ip(dst_ip):
                answers = [self._scenario_fqdn_for_ip(dst_ip) or hostname]
            else:
                answers = [_generate_rdns_name(rng, dst_ip, hostname)]
        elif qtype_roll < 0.98:
            # SRV record: AD service discovery — only when the world owns a DC.
            dc_systems = getattr(self, "_dc_systems", [])
            if dc_systems:
                qtype, qtype_name = 33, "SRV"
                domain = ad_domain
                query = rng.choice(_AD_SRV_QUERIES).format(domain=domain)
                dc_sys = _get_rng().choice(dc_systems)
                dc_hostname = self._scenario_fqdn_for_ip(dc_sys.ip) or dc_sys.hostname
                svc_prefix = query.split(".")[0]
                port = _SRV_PORT_MAP.get(svc_prefix, 389)
                answers = [f"0 100 {port} {dc_hostname}"]
                is_internal = True
            else:
                qtype, qtype_name = 6, "SOA"
                query = _dns_registrable_domain(hostname)
                answers = _public_dns_soa_answers(query)
        elif qtype_roll < 0.995:
            # TXT record: SPF/DKIM/DMARC-style mail/authentication lookups.
            qtype, qtype_name = 16, "TXT"
            query, txt_answer, txt_ttl = _dns_txt_query_and_answer(rng, hostname)
            answers = [txt_answer]
        else:
            # MX record: domain → mail server
            if _dns_hostname_allows_mx(hostname):
                qtype, qtype_name = 15, "MX"
                query = _dns_registrable_domain(hostname)
                if _dns_is_internal_name(query, ad_domain):
                    answers = [f"10 mail.{query}"]
                else:
                    answers = _public_dns_mx_answers(query)
            else:
                qtype, qtype_name = 16, "TXT"
                query, txt_answer, txt_ttl = _dns_txt_query_and_answer(rng, hostname)
                answers = [txt_answer]

        query_email_system = self._email_dns_system_for_hostname(query)
        query_is_internal = (
            qtype_name == "SRV"
            or _dns_is_internal_name(query, ad_domain)
            or (qtype_name == "PTR" and _is_private_ip(dst_ip))
            or query_email_system is not None
        )
        if query_is_internal and not _is_private_ip(dns_server_ip):
            dns_server_ip = _get_rng().choice(dns_ips)
            src_port = self._allocate_ephemeral_port(
                src_ip, dns_server_ip, 53, "udp", dns_time, _src_os
            )
        is_internal = query_is_internal

        if force_address and qtype in (1, 28) and query_is_internal and _is_private_ip(src_ip):
            srv_discovery_lead_ms = self._sample_dns_timing_milliseconds(
                relationship_key="activity.dns.ad_srv_discovery_before_address",
                stable_id=request.stable_id,
                host=dns_timing_host,
                lifecycle_id=dns_timing_lifecycle,
                sample_key="srv_discovery_lead_ms",
                minimum_ms=180,
                maximum_ms=420,
            )
            self._emit_ad_srv_discovery(
                src_ip=src_ip,
                dns_server_ip=dns_server_ip,
                time=dns_time - timedelta(seconds=2, milliseconds=srv_discovery_lead_ms),
                src_os=_src_os,
                domain=ad_domain,
                rng=rng,
                query_process=query_process,
            )

        # Internal authoritative names use stable TTLs. External answers may be
        # observed through a resolver cache, so expose realistic countdown TTLs.
        base_ttl = txt_ttl if txt_ttl is not None else _dns_base_ttl(query, is_internal)
        ttls = self._dns_observed_ttls(
            resolver_ip=dns_server_ip,
            query=query,
            qtype_name=qtype_name,
            answers=answers,
            is_internal=is_internal,
            base_ttl=base_ttl,
            time=dns_time,
        )
        if force_address and qtype in (1, 28) and not is_internal and ttls:
            min_client_ttl = max(30, math.ceil((time - dns_time).total_seconds()) + 1)
            ttls = [max(float(min_client_ttl), ttl) for ttl in ttls]

        # Only address lookups for the requested hostname populate the client
        # DNS cache. PTR/SRV/MX companions should not hide future A/AAAA
        # evidence for high-volume proxy or browser destinations.
        pending_cache_window: tuple[float, float] | None = None
        if query == hostname and qtype in (1, 28):
            client_ttl = max(1.0, min(ttls) if ttls else float(base_ttl))
            cached_at = dns_time.timestamp()
            pending_cache_window = (cached_at, cached_at + client_ttl)

        # Build DnsContext and emit connection + dns.log via fan-out
        dns_ctx = DnsContext(
            query=query,
            trans_id=rng.randint(1, 65535),
            qtype=qtype,
            query_type=qtype_name,
            rcode="NOERROR",
            rcode_num=0,
            answers=answers,
            TTLs=ttls,
            rtt=(
                request.planned_rtt_seconds
                if request.planned_rtt_seconds is not None
                else _dns_rtt(rng, dns_server_ip)
            ),
            AA=is_internal,
            RD=True,
            RA=True,
            preserve_ttls=True,
            query_process=query_process,
        )
        dns_uid = self.generate_connection(
            src_ip=src_ip,
            dst_ip=dns_server_ip,
            time=dns_time,
            dst_port=53,
            proto="udp",
            service="dns",
            duration=rng.uniform(0.001, 0.03),
            orig_bytes=rng.randint(40, 100),
            resp_bytes=rng.randint(80, 400),
            src_port=src_port,
            dns=dns_ctx,
            parent_action_group_id=request.parent_action_group_id,
            preserve_start_time=request.planned_query_time is not None,
        )
        if not dns_uid:
            return
        if pending_cache_window is not None:
            self._dns_cache[cache_key] = pending_cache_window

        # Address lookups that are prerequisites for TCP still occur in a
        # resolver ecosystem. Add low-volume companion questions so Zeek DNS
        # does not collapse to only A/TXT/SRV in generated enterprise slices.
        if force_address and rng.random() < 0.25:
            companion_choices, companion_weights = _dns_companion_kind_distribution_for_source(
                src_system
            )
            companion_delay_ms = self._sample_dns_timing_milliseconds(
                relationship_key="activity.dns.companion_after_query",
                stable_id=request.stable_id,
                host=dns_timing_host,
                lifecycle_id=dns_timing_lifecycle,
                sample_key="companion_delay_ms",
                minimum_ms=1,
                maximum_ms=30,
            )
            companion_time = dns_time + timedelta(milliseconds=companion_delay_ms)
            companion_src_port = self._allocate_ephemeral_port(
                src_ip, dns_server_ip, 53, "udp", companion_time, _src_os
            )
            companion_kind = rng.choices(
                companion_choices,
                weights=companion_weights,
                k=1,
            )[0]
            companion_query = hostname
            companion_answers: list[str] = []
            companion_rcode = "NOERROR"
            companion_rcode_num = 0
            companion_qtype = 28
            if companion_kind == "AAAA":
                companion_qtype = 28
                companion_answers = _public_dns_aaaa_answers(
                    hostname,
                    dst_ip,
                    is_internal=is_internal,
                )
            elif companion_kind == "PTR":
                companion_qtype = 12
                companion_query = _dns_reverse_query(dst_ip)
                if _is_private_ip(dst_ip):
                    companion_answers = [self._scenario_fqdn_for_ip(dst_ip) or hostname]
                else:
                    (
                        companion_rcode,
                        companion_rcode_num,
                        companion_answers,
                    ) = _public_dns_ptr_response(dst_ip, hostname)
            elif companion_kind == "NS":
                companion_qtype = 2
                companion_query = _dns_registrable_domain(hostname)
                if _dns_is_internal_name(companion_query, ad_domain):
                    companion_answers = [f"ns1.{companion_query}", f"ns2.{companion_query}"]
                else:
                    companion_answers = _public_dns_ns_answers(companion_query)
            elif companion_kind == "MX" and _dns_hostname_allows_mx(hostname):
                companion_qtype = 15
                companion_query = _dns_registrable_domain(hostname)
                if _dns_is_internal_name(companion_query, ad_domain):
                    companion_answers = [f"10 mail.{companion_query}"]
                else:
                    companion_answers = _public_dns_mx_answers(companion_query)
            else:
                companion_kind = "SOA"
                companion_qtype = 6
                companion_query = _dns_registrable_domain(hostname)
                if _dns_is_internal_name(companion_query, ad_domain):
                    companion_answers = [
                        _dns_soa_answer(
                            companion_query,
                            f"ns1.{companion_query}",
                            f"hostmaster.{companion_query}",
                            "internal",
                        )
                    ]
                else:
                    companion_answers = _public_dns_soa_answers(companion_query)
            companion_email_system = self._email_dns_system_for_hostname(companion_query)
            companion_is_internal = (
                _dns_is_internal_name(companion_query, ad_domain)
                or (companion_kind == "PTR" and _is_private_ip(dst_ip))
                or companion_email_system is not None
            )
            companion_ttls = self._dns_observed_ttls(
                resolver_ip=dns_server_ip,
                query=companion_query,
                qtype_name=companion_kind,
                answers=companion_answers,
                is_internal=companion_is_internal,
                base_ttl=_dns_base_ttl(companion_query, companion_is_internal),
                time=companion_time,
            )
            companion_ctx = DnsContext(
                query=companion_query,
                trans_id=rng.randint(1, 65535),
                qtype=companion_qtype,
                query_type=companion_kind,
                rcode=companion_rcode,
                rcode_num=companion_rcode_num,
                answers=companion_answers,
                TTLs=companion_ttls,
                rtt=_dns_rtt(rng, dns_server_ip),
                AA=companion_is_internal,
                RD=True,
                RA=True,
                preserve_ttls=True,
                query_process=query_process,
            )
            self.generate_connection(
                src_ip=src_ip,
                dst_ip=dns_server_ip,
                time=companion_time,
                dst_port=53,
                proto="udp",
                service="dns",
                duration=rng.uniform(0.001, 0.02),
                orig_bytes=rng.randint(40, 100),
                resp_bytes=rng.randint(80, 500),
                src_port=companion_src_port,
                dns=companion_ctx,
                parent_action_group_id=request.parent_action_group_id,
            )
            if companion_kind == "MX" and companion_answers:
                mx_hosts = [
                    str(answer).split()[-1].rstrip(".")
                    for answer in companion_answers
                    if str(answer).split()[-1].rstrip(".") not in {"", "."}
                ]
                if mx_hosts:
                    mx_host = mx_hosts[0]
                    mx_a_delay_ms = self._sample_dns_timing_milliseconds(
                        relationship_key="activity.dns.mx_address_after_mx",
                        stable_id=request.stable_id,
                        host=dns_timing_host,
                        lifecycle_id=dns_timing_lifecycle,
                        sample_key=f"mx_a_delay_ms:{mx_host.lower()}",
                        minimum_ms=2,
                        maximum_ms=45,
                    )
                    mx_a_time = companion_time + timedelta(milliseconds=mx_a_delay_ms)
                    mx_a_src_port = self._allocate_ephemeral_port(
                        src_ip,
                        dns_server_ip,
                        53,
                        "udp",
                        mx_a_time,
                        _src_os,
                    )
                    mx_a_ip = (
                        dst_ip
                        if _dns_is_internal_name(mx_host, ad_domain)
                        else _generate_random_external_ip(
                            random.Random(_stable_seed(f"dns_mx_companion_a:{mx_host}"))
                        )
                    )
                    mx_a_email_system = self._email_dns_system_for_hostname(mx_host)
                    mx_a_email_ip = (
                        str(getattr(mx_a_email_system, "ip", "") or "") if mx_a_email_system else ""
                    )
                    mx_a_is_internal = (
                        _dns_is_internal_name(mx_host, ad_domain) or mx_a_email_system is not None
                    )
                    mx_a_answers = _dns_address_rrset(
                        mx_host,
                        mx_a_email_ip or mx_a_ip,
                        is_internal=mx_a_is_internal,
                    )
                    mx_a_ctx = DnsContext(
                        query=mx_host,
                        trans_id=rng.randint(1, 65535),
                        qtype=1,
                        query_type="A",
                        rcode="NOERROR",
                        rcode_num=0,
                        answers=mx_a_answers,
                        TTLs=self._dns_observed_ttls(
                            resolver_ip=dns_server_ip,
                            query=mx_host,
                            qtype_name="A",
                            answers=mx_a_answers,
                            is_internal=mx_a_is_internal,
                            base_ttl=_dns_base_ttl(mx_host, mx_a_is_internal),
                            time=mx_a_time,
                        ),
                        rtt=_dns_rtt(rng, dns_server_ip),
                        AA=mx_a_is_internal,
                        RD=True,
                        RA=True,
                        preserve_ttls=True,
                        query_process=query_process,
                    )
                    self.generate_connection(
                        src_ip=src_ip,
                        dst_ip=dns_server_ip,
                        time=mx_a_time,
                        dst_port=53,
                        proto="udp",
                        service="dns",
                        duration=rng.uniform(0.001, 0.02),
                        orig_bytes=rng.randint(40, 100),
                        resp_bytes=rng.randint(80, 500),
                        src_port=mx_a_src_port,
                        dns=mx_a_ctx,
                        parent_action_group_id=request.parent_action_group_id,
                    )

        # Occasional resolver search-suffix mistakes/background discovery probes.
        # Keep this low-volume and avoid doubling an already-qualified internal name.
        if rng.random() < 0.05:
            nxdomain_queries = _dns_nxdomain_companion_queries(hostname, ad_domain)
            nx_query = rng.choice(nxdomain_queries)
            nx_lead_ms = self._sample_dns_timing_milliseconds(
                relationship_key="activity.dns.nxdomain_before_query",
                stable_id=request.stable_id,
                host=dns_timing_host,
                lifecycle_id=dns_timing_lifecycle,
                sample_key=f"nxdomain_lead_ms:{nx_query.lower()}",
                minimum_ms=1,
                maximum_ms=10,
            )
            nx_time = dns_time - timedelta(milliseconds=nx_lead_ms)
            nx_is_internal = _dns_is_internal_name(nx_query, ad_domain) or nx_query in {
                "wpad",
                "wpad.local",
                "isatap",
            }
            nx_dns_server_ip = dns_server_ip
            if nx_is_internal and not _is_private_ip(nx_dns_server_ip):
                nx_dns_server_ip = _get_rng().choice(dns_ips)
            nx_src_port = self._allocate_ephemeral_port(
                src_ip, nx_dns_server_ip, 53, "udp", nx_time, _src_os
            )
            nx_qtype = 33 if nx_query.startswith("_") else 1
            nx_qtype_name = "SRV" if nx_qtype == 33 else "A"
            nx_ctx = DnsContext(
                query=nx_query,
                trans_id=rng.randint(1, 65535),
                qtype=nx_qtype,
                query_type=nx_qtype_name,
                rcode="NXDOMAIN",
                rcode_num=3,
                rtt=_dns_rtt(rng, nx_dns_server_ip),
                AA=nx_is_internal,
                RD=True,
                RA=True,
                query_process=query_process,
            )
            self.generate_connection(
                src_ip=src_ip,
                dst_ip=nx_dns_server_ip,
                time=nx_time,
                dst_port=53,
                proto="udp",
                service="dns",
                duration=rng.uniform(0.001, 0.01),
                orig_bytes=rng.randint(40, 80),
                resp_bytes=rng.randint(80, 200),
                src_port=nx_src_port,
                dns=nx_ctx,
                parent_action_group_id=request.parent_action_group_id,
            )

    @staticmethod
    def _ad_srv_discovery_runtime_identity(
        *,
        src_ip: str,
        domain: str,
        time: datetime,
        query: str,
    ) -> tuple[tuple[str, str, int, str], datetime, datetime]:
        """Return the bounded runtime point identity for one hourly SRV query."""

        current = ensure_utc(time)
        bucket_start = (current + timedelta(seconds=5)).replace(
            minute=0,
            second=0,
            microsecond=0,
        )
        bucket = (bucket_start - datetime(1970, 1, 1, tzinfo=UTC)) // timedelta(hours=1)
        key = (
            src_ip.removeprefix("::ffff:"),
            domain.lower().rstrip("."),
            bucket,
            query.lower().rstrip("."),
        )
        return key, bucket_start, bucket_start + timedelta(hours=1)

    def _prepare_ad_srv_discovery_publication(
        self,
        *,
        src_ip: str,
        domain: str,
        time: datetime,
        query: str,
    ) -> NetworkPointBatchToken | None:
        """Prepare one hourly SRV marker before publishing its network occurrence."""

        key, marker, nominal_expiry = self._ad_srv_discovery_runtime_identity(
            src_ip=src_ip,
            domain=domain,
            time=time,
            query=query,
        )
        runtime = self._network_transaction_runtime
        batch = runtime.begin_point_batch(
            stable_id=f"ad-srv-discovery:{key[0]}:{key[1]}:{key[2]}:{key[3]}",
            linearization_time=ensure_utc(time),
        )
        try:
            existing = batch.read_point(
                NetworkRuntimePointFamily.AD_SRV_DISCOVERY,
                key,
                None,
                at=ensure_utc(time),
            )
            if existing is not None:
                if type(existing) is not datetime or existing.tzinfo is not UTC:
                    raise StateError("AD SRV runtime point contains a malformed bucket marker")
                if existing != marker:
                    raise StateError("AD SRV runtime point bucket marker disagrees with its key")
                batch.cancel()
                return None
            batch.stage_point(
                NetworkRuntimePointFamily.AD_SRV_DISCOVERY,
                key,
                marker,
                expires_at=min(nominal_expiry, runtime.window_end),
            )
            return batch.seal()
        except BaseException:
            try:
                batch.cancel()
            except StateError:
                pass
            raise

    def _emit_ad_srv_discovery(
        self,
        *,
        src_ip: str,
        dns_server_ip: str,
        time: datetime,
        src_os: str,
        domain: str,
        rng: random.Random,
        query_process: ProcessContext | None,
    ) -> None:
        """Emit low-volume AD SRV service-discovery DNS for domain clients."""
        dc_systems = list(getattr(self, "_dc_systems", []) or [])
        if not dc_systems:
            return

        from evidenceforge.events.contexts import DnsContext

        query_templates = [
            "_ldap._tcp.dc._msdcs.{domain}",
            "_kerberos._tcp.{domain}",
            "_ldap._tcp.{domain}",
            "_kerberos._tcp.dc._msdcs.{domain}",
        ]
        start_index = _stable_seed(f"ad_srv_query:{src_ip}:{domain}") % len(query_templates)
        query_count = 1 + (_stable_seed(f"ad_srv_query_count:{src_ip}:{domain}") % 2)
        selected_queries = [
            query_templates[(start_index + index) % len(query_templates)]
            for index in range(query_count)
        ]
        dc_hosts = sorted(
            (
                (dc.hostname if "." in dc.hostname else f"{dc.hostname}.{domain}".rstrip("."))
                for dc in dc_systems
            ),
            key=str.lower,
        )
        for index, query_template in enumerate(selected_queries):
            query = query_template.format(domain=domain)
            token = self._prepare_ad_srv_discovery_publication(
                src_ip=src_ip,
                domain=domain,
                time=time,
                query=query,
            )
            if token is None:
                continue
            service_prefix = query.split(".", 1)[0]
            port = _SRV_PORT_MAP.get(service_prefix, 389)
            answers = [f"0 100 {port} {hostname}" for hostname in dc_hosts[:2]]
            with self._network_transaction_runtime.claimed_point_batch(token) as prepared:
                if index == 0:
                    query_spacing_ms = 0
                else:
                    runtime_key, marker, _ = self._ad_srv_discovery_runtime_identity(
                        src_ip=src_ip,
                        domain=domain,
                        time=time,
                        query=query,
                    )
                    query_spacing_ms = self._sample_dns_timing_milliseconds(
                        relationship_key="activity.dns.ad_srv_query_spacing",
                        stable_id=(
                            f"ad-srv-discovery:{runtime_key[0]}:{runtime_key[1]}:"
                            f"{runtime_key[2]}:{runtime_key[3]}"
                        ),
                        host=src_ip,
                        lifecycle_id=marker.isoformat(),
                        sample_key="query_spacing_ms",
                        minimum_ms=35,
                        maximum_ms=95,
                        ordinal=index,
                    )
                srv_time = time + timedelta(milliseconds=query_spacing_ms)
                src_port = self._allocate_ephemeral_port(
                    src_ip,
                    dns_server_ip,
                    53,
                    "udp",
                    srv_time,
                    src_os,
                )
                srv_ctx = DnsContext(
                    query=query,
                    trans_id=rng.randint(1, 65535),
                    qtype=33,
                    query_type="SRV",
                    rcode="NOERROR",
                    rcode_num=0,
                    answers=answers,
                    TTLs=[float(_dns_base_ttl(query, True))] * len(answers),
                    rtt=_dns_rtt(rng, dns_server_ip),
                    AA=True,
                    RD=True,
                    RA=True,
                    query_process=query_process,
                )
                self.generate_connection(
                    src_ip=src_ip,
                    dst_ip=dns_server_ip,
                    time=srv_time,
                    dst_port=53,
                    proto="udp",
                    service="dns",
                    duration=rng.uniform(0.001, 0.02),
                    orig_bytes=rng.randint(48, 110),
                    resp_bytes=rng.randint(140, 520),
                    src_port=src_port,
                    dns=srv_ctx,
                )
                prepared.commit_no_fail()

    def get_baseline_pattern(
        self,
        persona_name: str | None,
        persona=None,
    ) -> list[tuple[str, float]]:
        """Get baseline activity pattern for persona.

        Phase 2.6: If persona has activity_intensity overrides, builds
        dynamic pattern from those. Otherwise falls back to hardcoded patterns.

        Args:
            persona_name: Persona name string (or None for default)
            persona: Optional resolved Persona object for dynamic patterns

        Returns:
            List of (activity_type, probability) tuples
        """
        # Phase 2.6: Use activity_intensity overrides if provided
        if persona and persona.activity_intensity:
            return self._build_pattern_from_intensity(persona.activity_intensity)

        # Fall back to hardcoded patterns (Phase 1 behavior)
        if persona_name and persona_name.lower() in BASELINE_PATTERNS:
            return BASELINE_PATTERNS[persona_name.lower()]
        return BASELINE_PATTERNS["default"]

    def _build_pattern_from_intensity(self, intensity: dict[str, int]) -> list[tuple[str, float]]:
        """Convert activity_intensity dict to baseline pattern.

        Maps intensity values to probabilities. Higher intensity = higher probability.

        Args:
            intensity: Dict mapping activity_type to events/hour intensity

        Returns:
            List of (activity_type, probability) tuples
        """
        # Always include logon
        pattern: list[tuple[str, float]] = [("logon", 0.9)]

        if not intensity:
            return pattern

        # Normalize intensities to probabilities (cap at 0.95).
        # Ignore non-positive values when determining the denominator so an
        # all-zero (or all-negative) map cannot trigger divide-by-zero.
        positive_values = [
            value for activity, value in intensity.items() if activity != "logon" and value > 0
        ]
        if not positive_values:
            for activity, _ in intensity.items():
                if activity == "logon":
                    continue  # Already added
                pattern.append((activity, 0.1))
            return pattern

        max_val = max(positive_values)
        for activity, value in intensity.items():
            if activity == "logon":
                continue  # Already added
            normalized = max(value, 0) / max_val
            prob = min(0.95, normalized * 0.8 + 0.1)
            pattern.append((activity, prob))

        return pattern

    # Process→network correlation loaded from config/activity/process_network_map.yaml.
    # See generation/activity/process_network.py for the loader.

    def _emit_process_network_correlation(
        self,
        system: Any,
        process_name: str,
        command_line: str,
        time: datetime,
        pid: int,
        rng: random.Random,
    ) -> None:
        """Emit network connections correlated with a process creation.

        When a baseline process is one that normally generates network
        traffic (browsers, Office apps, dev tools, DB clients), emit
        a corresponding connection shortly after process creation.
        """
        # Extract executable basename
        exe = process_name.rsplit("\\", 1)[-1].rsplit("/", 1)[-1]
        # Strip .exe for Linux lookups
        exe_base = exe.replace(".exe", "") if exe.endswith(".exe") else exe

        from evidenceforge.generation.activity.process_network import get_exe_to_service

        _exe_map = get_exe_to_service()
        conn_info = _exe_map.get(exe) or _exe_map.get(exe_base)
        if conn_info is None:
            return

        dst_port = conn_info["dst_port"]
        service = conn_info["service"]
        command_target = _extract_network_command_target(command_line, service)
        ssh_attempted_username = (
            _extract_ssh_attempted_username(command_line) if service == "ssh" else None
        )
        command_http_url = _extract_http_url_from_command(command_line)

        # Only emit ~60% of ambient app launches. Commands that name a concrete
        # remote endpoint should leave a matching socket attempt every time.
        if not command_target and not command_http_url and rng.random() > 0.60:
            return

        conn_time = time + timedelta(milliseconds=rng.randint(50, 500))
        ext_hostname = None
        http_context = None
        resp_bytes = rng.randint(500, 50000)
        emit_dns = bool(conn_info["external"])
        failure_conn_state = None

        if conn_info["external"]:
            # External connection: domain-first selection. App-specific mappings
            # can constrain destinations via DNS registry tags (e.g., Teams →
            # Teams/M365 endpoints instead of arbitrary web/CDN domains).
            from evidenceforge.generation.activity.dns_registry import (
                _domain_to_ip as _d2ip,
            )
            from evidenceforge.generation.activity.dns_registry import (
                generate_long_tail_domain as _gen_lt_domain,
            )
            from evidenceforge.generation.activity.dns_registry import (
                pick_domain_and_ip as _pick_domain_and_ip,
            )
            from evidenceforge.generation.activity.dns_registry import resolve_domain_ip

            dns_tags = conn_info.get("dns_tags") or []
            process_http = _http_context_from_process_command(
                process_name,
                command_line,
                response_body_len=resp_bytes,
            )
            if process_http is not None:
                http_context, ext_hostname, dst_port, service = process_http
                command_target = self._system_for_hostname(ext_hostname)
                if command_target is not None:
                    dst_ip = command_target.ip
                else:
                    host_lower = ext_hostname.lower().rstrip(".")
                    ad_domain = str(getattr(self, "_ad_domain", "") or "").lower().rstrip(".")
                    if host_lower.endswith(".local") or (
                        ad_domain and host_lower.endswith(f".{ad_domain}")
                    ):
                        return
                    dst_ip = resolve_domain_ip(ext_hostname, src_host=system.hostname)
            elif service == "ssl":
                if hasattr(self, "_pick_profiled_tls_destination"):
                    ext_hostname, dst_ip = self._pick_profiled_tls_destination(
                        rng,
                        src_ip=system.ip,
                        source_system=system,
                        purpose_tags=tuple(dns_tags) if dns_tags else ("web", "saas"),
                    )
                elif dns_tags:
                    tag = rng.choice(dns_tags)
                    ext_hostname, dst_ip = _pick_domain_and_ip(
                        rng,
                        tag,
                        src_host=system.hostname,
                        include_os=_get_os_category(system.os),
                    )
                else:
                    ext_hostname = _gen_lt_domain(rng)
                    dst_ip = _d2ip(ext_hostname)
            elif dns_tags:
                tag = rng.choice(dns_tags)
                ext_hostname, dst_ip = _pick_domain_and_ip(
                    rng,
                    tag,
                    src_host=system.hostname,
                    include_os=_get_os_category(system.os),
                )
            else:
                ext_hostname = _gen_lt_domain(rng)
                dst_ip = _d2ip(ext_hostname)
        else:
            # Internal connection: use DB server or any internal server
            db_servers = getattr(self, "_db_servers", [])
            all_ips = getattr(self, "_all_system_ips", [])
            resolved_command_target = (
                self._resolve_command_network_target(command_target, service)
                if command_target
                else None
            )
            if resolved_command_target is not None:
                dst_ip, command_hostname = resolved_command_target
                if command_hostname:
                    ext_hostname = command_hostname
                    emit_dns = True
                target_system = getattr(self, "_ip_to_system", {}).get(dst_ip)
                if not self._process_network_target_supports_service(
                    target_system,
                    service,
                    dst_port,
                ):
                    failure_conn_state = "S0"
                    service = ""
                    resp_bytes = 0
            elif command_target:
                fallback_target = (
                    self._fallback_database_network_target(command_target, system)
                    if service in {"mssql", "mysql", "postgresql"}
                    else None
                )
                if fallback_target is None:
                    logger.debug(
                        "Skipping %s process network effect with unresolved command target %s",
                        service,
                        command_target,
                    )
                    return
                dst_ip, command_hostname, emit_dns = fallback_target
                if command_hostname:
                    ext_hostname = command_hostname
                failure_conn_state = "S0"
                service = ""
                resp_bytes = 0
            elif service in ("mssql", "mysql", "postgresql") and db_servers:
                # Filter to DB servers that match the requested service
                svc = service
                compatible = [
                    e
                    for e in db_servers
                    if (isinstance(e, dict) and e.get("service") == svc) or not isinstance(e, dict)
                ]
                if not compatible:
                    return  # No service-compatible DB host — skip
                db_entry = rng.choice(compatible)
                dst_ip = db_entry["ip"] if isinstance(db_entry, dict) else db_entry
            elif all_ips:
                compatible_ips = self._process_network_target_ips(system, service, dst_port)
                if compatible_ips:
                    dst_ip = rng.choice(compatible_ips)
                elif service in {"smb", "rdp", "ssh"} or dst_port in {22, 445, 3389}:
                    return
                else:
                    dst_ip = rng.choice([ip for ip in all_ips if ip != system.ip] or all_ips)
            else:
                return  # No internal targets available

        self.generate_connection(
            src_ip=system.ip,
            dst_ip=dst_ip,
            time=conn_time,
            dst_port=dst_port,
            proto="tcp",
            service=service,
            duration=rng.uniform(0.3, 15.0),
            orig_bytes=rng.randint(48, 140) if failure_conn_state else rng.randint(200, 5000),
            resp_bytes=resp_bytes,
            emit_dns=emit_dns,
            pid=pid,
            http=http_context,
            hostname=ext_hostname,
            source_system=system,
            conn_state=failure_conn_state,
            ssh_attempted_username=ssh_attempted_username,
        )

    def _baseline_type3_source_ip(
        self,
        user: User,
        system: System,
        rng: random.Random,
        *,
        is_service_account: bool,
    ) -> str | None:
        """Choose a source host for ambient baseline Type 3 logons.

        Human workstation users should not create self-sourced network logons;
        those are local-service semantics and otherwise collide with outbound
        SMB evidence whose real Type 3 record belongs on the file server.
        """
        all_ips = [str(ip) for ip in getattr(self, "_all_system_ips", []) if str(ip)]
        other_ips = [ip for ip in all_ips if ip != system.ip]

        username = user.username
        service_identity = (
            is_service_account
            or username in {"SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE"}
            or username.endswith("$")
        )
        if service_identity and rng.random() < 0.30:
            return system.ip
        if other_ips:
            return rng.choice(other_ips)
        if service_identity:
            return system.ip
        return None

    def _sample_rdp_outer_timing_milliseconds(
        self,
        *,
        relationship_key: str,
        stable_id: str,
        host: str,
        lifecycle_id: str,
        sample_key: str,
        minimum_ms: int,
        maximum_ms: int,
        ordinal: int = 0,
    ) -> int:
        """Sample one RDP outer-placement gap through the exact engine runtime."""

        runtime = self.timing_runtime
        if type(runtime) not in {TimingRuntime, SourceTimingPlanningRuntime}:
            raise StateError("RDP outer timing requires the exact engine-owned runtime")
        if (
            type(relationship_key) is not str
            or not relationship_key
            or type(stable_id) is not str
            or not stable_id
            or type(host) is not str
            or not host
            or type(lifecycle_id) is not str
            or not lifecycle_id
            or type(sample_key) is not str
            or not sample_key
            or type(minimum_ms) is not int
            or type(maximum_ms) is not int
            or minimum_ms < 0
            or maximum_ms < minimum_ms
            or type(ordinal) is not int
            or ordinal < 0
        ):
            raise StateError("RDP outer timing scope and support must use exact built-in values")
        sampled = runtime.sampler.sample_value(
            _rdp_inclusive_millisecond_distribution(minimum_ms, maximum_ms),
            relationship_key=relationship_key,
            scope=TimingScope(
                stable_id=stable_id,
                host=host,
                source="activity.rdp",
                lifecycle_id=lifecycle_id,
                ordinal=ordinal,
            ),
            sample_key=sample_key,
        )
        return int(sampled + 0.5)

    def execute_baseline_activity(
        self, user: User, system: System, time: datetime, activity_type: str
    ) -> None:
        """Execute a specific baseline activity type.

        Args:
            user: User performing the activity
            system: System where activity occurs
            time: Activity timestamp
            activity_type: Type of activity to execute
        """
        # Logon activity (10% chance of failure — bad password)
        if activity_type == "logon":
            if _get_rng().random() < 0.10:
                self.generate_failed_logon(user, system, time)
                return

            # Phase 6.2: Realistic logon type distribution by system type
            # Type 3 (network) should dominate in AD; Type 5 only for service accounts
            rng = _get_rng()
            sys_type = (system.type or "workstation").lower()
            os_category = _get_os_category(system.os)
            is_service_account = user.username.endswith("$") or user.username.lower().startswith(
                "svc"
            )

            if os_category == "linux":
                # SSH is a modeled remote-session bundle on Linux. Generic
                # baseline logon activity should not create successful
                # non-SSH "remote" endpoint sessions.
                if is_service_account:
                    logon_type = 5
                else:
                    logon_type = 2
            elif sys_type in ("server", "domain_controller"):
                # Servers/DCs: Type 3 (network) dominates
                logon_type = rng.choices([3, 5, 3, 4, 2, 8], weights=[70, 15, 8, 4, 2, 1], k=1)[0]
            elif is_service_account:
                # Service accounts on workstations: network + service logons
                logon_type = rng.choices([3, 5, 3], weights=[70, 25, 5], k=1)[0]
            else:
                # Regular users on workstations: Type 3 dominant, no Type 5
                logon_type = rng.choices([3, 2, 7, 11, 3], weights=[55, 20, 10, 10, 5], k=1)[0]

            active_interactive = None
            if (
                logon_type in (2, 7, 11)
                and not is_service_account
                and sys_type not in ("server", "domain_controller")
            ):
                active_interactive = self._active_user_workstation_windows_session(
                    user,
                    system,
                    time,
                )
            if active_interactive is not None and logon_type in (2, 7, 11):
                # A baseline "logon" activity while the same user's console
                # session is already active is continued use, not a new
                # same-user Type 2/11 session.  If the session is visibly
                # locked, render the re-authentication as a Type 7 unlock;
                # otherwise just advance activity time and keep the durable
                # workstation session.
                lock_key = (system.hostname, user.username, active_interactive.logon_id)
                if logon_type == 7 and lock_key in getattr(self, "_last_workstation_lock_time", {}):
                    self.generate_workstation_unlock(
                        user,
                        system,
                        time,
                        active_interactive.logon_id,
                    )
                else:
                    active_interactive.last_activity_time = time
                return

            if active_interactive is None and logon_type == 7:
                # Type 7 is an unlock of an existing session, not a fresh
                # session-establishing event.
                logon_type = 2

            network_source_ip = None
            if logon_type == 3:
                network_source_ip = self._baseline_type3_source_ip(
                    user,
                    system,
                    rng,
                    is_service_account=is_service_account,
                )
                if network_source_ip is None:
                    logon_type = 2

            # Type 3 (network) logons are standalone events, not interactive sessions
            if logon_type in (3, 4, 5, 8):
                # Pick a source IP from another system for network logons
                source_ip = network_source_ip
                logon_id = self.generate_logon(
                    user,
                    system,
                    time,
                    logon_type=logon_type,
                    source_ip=source_ip if source_ip else system.ip,
                )
                # Type 3/5 are short-lived — generate paired logoff after brief delay
                logoff_delay = _get_rng().uniform(1.0, 60.0)
                logoff_time = time + timedelta(seconds=logoff_delay)
                self.generate_logoff(user, system, logoff_time, logon_id, logon_type)
                return

            # Interactive logon types (2, 7, 10, 11) — create sessions
            if logon_type == 7:
                source_ip = "127.0.0.1"
            elif logon_type in (10, 11):
                # Remote interactive (RDP/VNC) — pick a realistic remote IP
                other_ips = getattr(self, "_all_system_ips", [])
                remote_ips = [ip for ip in other_ips if ip != system.ip]
                source_ip = _get_rng().choice(remote_ips) if remote_ips else system.ip
            else:
                source_ip = None  # Local console on Windows — defaults to system.ip

            # Linux remote interactive logons are SSH sessions. Let the SSH
            # compatibility path own transport, auth/PAM, endpoint session, and
            # session state so eCAR does not see a duplicate generic login.
            if (
                _get_os_category(system.os) == "linux"
                and logon_type in (2, 10)
                and source_ip
                and source_ip != system.ip
            ):
                self.generate_logon(
                    user,
                    system,
                    time,
                    logon_type=10,
                    source_ip=source_ip,
                )
                return
            elif (
                _get_os_category(system.os) == "windows"
                and logon_type == 10
                and source_ip
                and source_ip != system.ip
            ):
                rdp_source_system = self._resolve_direct_rdp_source_system(
                    user,
                    system,
                    source_ip,
                    _get_rng(),
                )
                if rdp_source_system is not None:
                    source_ip = rdp_source_system.ip
                canonical_activity_time = ensure_utc(time)
                rdp_lifecycle_id = (
                    f"baseline-rdp:{user.username}:{source_ip}:{system.hostname}:"
                    f"{canonical_activity_time.isoformat()}"
                )
                rdp_lead_ms = self._sample_rdp_outer_timing_milliseconds(
                    relationship_key="activity.rdp.session_before_baseline_logon",
                    stable_id=rdp_lifecycle_id,
                    host=system.hostname,
                    lifecycle_id=rdp_lifecycle_id,
                    sample_key="session_lead_ms",
                    minimum_ms=80,
                    maximum_ms=400,
                )
                rdp_time = time - timedelta(milliseconds=rdp_lead_ms)
                source_process_time = (
                    rdp_time
                    - timedelta(
                        milliseconds=self._sample_rdp_outer_timing_milliseconds(
                            relationship_key="activity.rdp.source_process_before_session",
                            stable_id=rdp_lifecycle_id,
                            host=rdp_source_system.hostname,
                            lifecycle_id=rdp_lifecycle_id,
                            sample_key="source_process_lead_ms",
                            minimum_ms=1800,
                            maximum_ms=3200,
                        )
                    )
                    if rdp_source_system is not None
                    else None
                )
                self.generate_rdp_session(
                    user=user,
                    target_system=system,
                    time=rdp_time,
                    source_ip=source_ip,
                    source_system=rdp_source_system,
                    source_process_time=source_process_time,
                    source_process_factory=(
                        self._direct_rdp_source_process_factory(_get_rng())
                        if rdp_source_system is not None
                        else None
                    ),
                )
                return

            self.generate_logon(
                user,
                system,
                time,
                logon_type=logon_type,
                source_ip=source_ip,
            )

        # Process activities
        elif activity_type in PROCESS_TEMPLATES:
            os_category = _get_os_category(system.os)
            if (
                os_category == "windows"
                and self._locked_user_interactive_windows_session(user, system, time) is not None
            ):
                return
            # Get or create session for this user (with login cooldown)
            if os_category == "windows":
                active_session = self._active_user_interactive_windows_session(
                    user,
                    system,
                    time,
                )
            else:
                sessions = self.state_manager.get_sessions_for_user(user.username)
                active_session = (
                    next(
                        (
                            s
                            for s in sessions
                            if s.system == system.hostname
                            and _session_active_for_activity(s, time)
                            and s.logon_type in (2, 10, 11)
                        ),
                        None,
                    )
                    if sessions
                    else None
                )

            if active_session:
                logon_id = active_session.logon_id
                active_session.last_activity_time = time
            else:
                future_session = (
                    self._near_future_user_interactive_windows_session(user, system, time)
                    if os_category == "windows"
                    else None
                )
                if future_session is not None:
                    time = ensure_utc(future_session.start_time) + timedelta(
                        seconds=_get_rng().uniform(20.0, 90.0)
                    )
                    if not self._is_within_scenario_window(time):
                        return
                    logon_id = future_session.logon_id
                    future_session.last_activity_time = time
                else:
                    # No active session on this system — create logon slightly before
                    # the process to maintain causal ordering
                    if os_category == "linux":
                        logon_time = time - timedelta(seconds=_get_rng().uniform(7.0, 15.0))
                    else:
                        logon_time = time - timedelta(seconds=_get_rng().uniform(0.5, 2.0))
                    logon_id = self.generate_logon(user, system, logon_time)

            # Phase 2.10: OS-aware process template selection
            # Map activity_type to catalog category
            _CATEGORY_MAP = {
                "process_user_apps": "user_app",
                "process_code": "code",
                "process_build": "build",
                "process_query": "query",
            }
            catalog_category = _CATEGORY_MAP.get(activity_type)

            if catalog_category in ("user_app", "browser", "office") and system.type in (
                "server",
                "domain_controller",
            ):
                return

            # Prefer compiled assignment truth; retain the catalog only for legacy callers.
            if catalog_category:
                rng = _get_rng()
                deployment_registry = getattr(self.dispatcher, "deployment_registry", None)
                result: tuple[str, str] | None = None
                singleton_per_session = False
                if deployment_registry is not None:
                    host_deployment = deployment_registry.host_deployment(system.hostname)
                    user_profile = (
                        deployment_registry.user_profile_for(
                            system.hostname,
                            user.username,
                            host_deployment.platform,
                        )
                        if host_deployment is not None
                        else None
                    )
                    selected_assignment = None
                    if user_profile is not None:
                        candidate_count = (
                            deployment_registry.count_user_application_assignments_for_category(
                                user_profile.profile_id,
                                catalog_category,
                            )
                        )
                        if candidate_count:
                            selected_assignment = (
                                deployment_registry.select_user_application_assignment_for_category(
                                    user_profile.profile_id,
                                    catalog_category,
                                    unit_interval=rng.random(),
                                )
                            )
                    if (
                        selected_assignment is not None
                        and "browser" in selected_assignment.eligible_categories
                        and user_profile is not None
                    ):
                        browser_count = (
                            deployment_registry.count_user_application_assignments_for_category(
                                user_profile.profile_id,
                                "browser",
                            )
                        )
                        if browser_count > 1:
                            preferred = deployment_registry.preferred_browser_assignment(
                                user_profile.profile_id
                            )
                            if (
                                preferred is not None
                                and catalog_category in preferred.eligible_categories
                            ):
                                if rng.random() < 0.90:
                                    selected_assignment = preferred
                                else:
                                    alternative = (
                                        deployment_registry.browser_alternative_assignment_at(
                                            user_profile.profile_id,
                                            preferred.assignment_id,
                                            rng.randrange(browser_count - 1),
                                        )
                                    )
                                    if (
                                        alternative is not None
                                        and catalog_category in alternative.eligible_categories
                                    ):
                                        selected_assignment = alternative
                    if selected_assignment is not None:
                        descriptor = deployment_registry.application_descriptor_for_assignment(
                            selected_assignment
                        )
                        if descriptor is not None:
                            result = deployment_registry.materialize_application_command(
                                rng,
                                selected_assignment,
                                username=user.username,
                                category=catalog_category,
                            )
                            singleton_per_session = descriptor.singleton_per_session
                else:
                    from evidenceforge.generation.activity.application_catalog import (
                        is_singleton_application_image,
                        pick_app_and_command,
                    )

                    result = pick_app_and_command(
                        rng,
                        user.persona or "default",
                        os_category,
                        catalog_category,
                        username=user.username,
                        system_type=system.type,
                        deployment_key=self._software_deployment_key,
                    )
                    if result is not None:
                        singleton_per_session = is_singleton_application_image(
                            result[0], os_category
                        )
                if result:
                    process_name, command_line = result

                    singleton_key: tuple[str, str, str, str] | None = None
                    if singleton_per_session:
                        normalized_image = process_name.replace("/", "\\").lower()
                        singleton_key = self._singleton_application_key(
                            system,
                            user.username,
                            logon_id,
                            normalized_image,
                        )
                        provisional_end = (
                            self.state_manager.get_session_end_time(logon_id)
                            or self._scenario_end_time
                        )
                        if not self.claim_singleton_application_interval(
                            singleton_key, time, provisional_end
                        ):
                            return
                        existing = next(
                            (
                                proc
                                for proc in self.state_manager.get_processes_on_system(
                                    system.hostname
                                )
                                if proc.username.lower() == user.username.lower()
                                and proc.logon_id == logon_id
                                and proc.image.replace("/", "\\").lower() == normalized_image
                            ),
                            None,
                        )
                        if existing is not None:
                            self.state_manager.update_process_activity_time(
                                system.hostname, existing.pid, time
                            )
                            return
                    command_line = self._parameterize_command_for_system(
                        rng,
                        command_line,
                        username=user.username,
                        system=system,
                    )
                    process_time = time
                    shell_command_line = command_line
                    source_process_groups = [[(process_name, command_line)]]
                    if os_category == "linux":
                        shell_command_line = _background_linux_shell_command_if_needed(command_line)
                        process_time = self._schedule_bash_history_time(
                            user, system, time, shell_command_line
                        )
                        if process_time is None or not self._is_within_scenario_window(
                            process_time
                        ):
                            return
                        source_process_groups = _linux_catalog_process_groups_from_shell_command(
                            process_name,
                            shell_command_line,
                            username=user.username,
                        )
                        process_name, command_line = source_process_groups[0][0]
                    parent_pid = self._resolve_parent(
                        system, user, process_time, logon_id, process_name
                    )
                    bash_history_group_id = (
                        self._bash_history_process_group_id(
                            user,
                            system,
                            process_time,
                            shell_command_line,
                        )
                        if os_category == "linux"
                        else ""
                    )
                    pid = -1
                    created_processes: list[tuple[int, str, str, datetime]] = []
                    requested_group_time = process_time
                    for group_index, source_process_group in enumerate(source_process_groups):
                        concurrency_group_id = (
                            bash_history_group_id
                            if len(source_process_groups) == 1
                            else f"{bash_history_group_id}:command:{group_index}"
                        )
                        group_process_time = requested_group_time
                        if os_category == "linux":
                            group_process_time = self._reserve_foreground_shell_time(
                                system=system,
                                username=user.username,
                                logon_id=logon_id,
                                parent_pid=parent_pid,
                                requested_time=requested_group_time,
                                seed_text=f"{shell_command_line}:command:{group_index}",
                                concurrency_group_id=concurrency_group_id,
                            )
                        stage_times = plan_linux_pipeline_stage_times(
                            group_process_time,
                            stage_count=len(source_process_group),
                            scope_parts=(
                                system.hostname,
                                user.username,
                                logon_id,
                                concurrency_group_id,
                            ),
                            active_process_count=len(
                                self.state_manager.get_processes_on_system(system.hostname)
                            ),
                            timing_runtime=self.timing_runtime,
                        )
                        for (
                            source_process_name,
                            source_command_line,
                        ), source_process_time in zip(
                            source_process_group, stage_times, strict=True
                        ):
                            if not self._is_within_scenario_window(source_process_time):
                                continue
                            source_pid = self.generate_process(
                                user,
                                system,
                                source_process_time,
                                logon_id,
                                source_process_name,
                                source_command_line,
                                parent_pid=parent_pid,
                                concurrency_group_id=concurrency_group_id,
                            )
                            if pid < 0:
                                pid = source_pid
                                process_name = source_process_name
                                command_line = source_command_line
                                process_time = source_process_time
                            created_processes.append(
                                (
                                    source_pid,
                                    source_process_name,
                                    source_command_line,
                                    source_process_time,
                                )
                            )
                            self._record_user_process(system, user, source_pid, source_process_name)
                            if os_category == "linux":
                                lifetime = _linux_foreground_lifetime(
                                    source_process_name, source_command_line
                                )
                                if lifetime is not None:
                                    self._remember_foreground_shell_available(
                                        system=system,
                                        username=user.username,
                                        logon_id=logon_id,
                                        parent_pid=parent_pid,
                                        termination_time=source_process_time
                                        + timedelta(seconds=lifetime[1]),
                                        seed_text=source_command_line,
                                        concurrency_group_id=concurrency_group_id,
                                    )
                        requested_group_time = group_process_time
                    if not created_processes:
                        return
                    if active_session:
                        active_session.last_activity_time = process_time
                    effect_process_name, effect_command_line = self._process_effect_context(
                        system,
                        pid,
                        process_name,
                        command_line,
                    )
                    network_process_name, network_command_line = (
                        _network_effect_context_for_process(
                            process_name,
                            command_line,
                            effect_process_name,
                            effect_command_line,
                        )
                    )

                    # Spawn child/utility processes for apps that have them
                    if activity_type == "process_user_apps" and deployment_registry is None:
                        from evidenceforge.generation.activity.application_catalog import (
                            get_child_processes,
                            parameterize_scoped_command,
                        )

                        exe_lower = effect_process_name.rsplit("\\", 1)[-1].lower()
                        if "/" in effect_process_name:
                            exe_lower = effect_process_name.rsplit("/", 1)[-1].lower()
                        child_entries = get_child_processes(os_category, exe_lower)
                        if child_entries:
                            num_children = rng.randint(1, min(3, len(child_entries)))
                            for entry in rng.sample(child_entries, num_children):
                                child_time = process_time + timedelta(seconds=rng.uniform(0.5, 3.0))
                                child_image = entry["image"]
                                child_cmd = parameterize_scoped_command(
                                    rng,
                                    entry["command_line"],
                                    entry,
                                )
                                if "{username}" in child_image:
                                    child_image = child_image.replace("{username}", user.username)
                                if "{username}" in child_cmd:
                                    child_cmd = child_cmd.replace("{username}", user.username)
                                self.generate_process(
                                    user,
                                    system,
                                    child_time,
                                    logon_id,
                                    child_image,
                                    child_cmd,
                                    parent_pid=pid,
                                )

                    # Emit correlated network connection for network-active apps
                    # (tight PID+timestamp coupling alongside profile-driven volume)
                    self._emit_process_network_correlation(
                        system,
                        network_process_name,
                        network_command_line,
                        process_time,
                        pid,
                        rng,
                    )

                    # Also generate bash history for Linux processes from the same
                    # canonical command so eCAR and shell artifacts do not diverge.
                    if os_category == "windows":
                        lifetime = _windows_foreground_lifetime(
                            effect_process_name,
                            effect_command_line,
                        )
                        if lifetime is not None:
                            termination_time = (
                                self._generate_bounded_foreground_process_termination(
                                    user=user,
                                    system=system,
                                    start_time=process_time,
                                    pid=pid,
                                    process_name=effect_process_name,
                                    logon_id=logon_id,
                                    lifetime=lifetime,
                                    rng=rng,
                                )
                            )
                            if (
                                singleton_key is not None
                                and self.state_manager.get_process(system.hostname, pid) is None
                            ):
                                self.update_singleton_application_end(
                                    singleton_key, process_time, termination_time
                                )
                    elif os_category == "linux":
                        self._emit_bash_command_event(
                            user,
                            system,
                            process_time,
                            shell_command_line,
                        )
                        for (
                            source_pid,
                            source_process_name,
                            source_command_line,
                            source_process_time,
                        ) in created_processes:
                            lifetime = _linux_foreground_lifetime(
                                source_process_name,
                                source_command_line,
                            )
                            if lifetime is None:
                                continue
                            running_proc = self.state_manager.get_process(
                                system.hostname, source_pid
                            )
                            actual_process_start = (
                                running_proc.start_time
                                if running_proc is not None
                                else source_process_time
                            )
                            process_group_id = (
                                running_proc.concurrency_group_id
                                if running_proc is not None
                                else bash_history_group_id
                            )
                            termination_time = (
                                self._generate_bounded_foreground_process_termination(
                                    user=user,
                                    system=system,
                                    start_time=actual_process_start,
                                    pid=source_pid,
                                    process_name=source_process_name,
                                    logon_id=logon_id,
                                    lifetime=lifetime,
                                    rng=rng,
                                )
                            )
                            self._remember_foreground_shell_available(
                                system=system,
                                username=user.username,
                                logon_id=logon_id,
                                parent_pid=parent_pid,
                                termination_time=termination_time,
                                seed_text=source_command_line,
                                concurrency_group_id=process_group_id,
                            )

            # Legacy PROCESS_TEMPLATES only for process_system (not user apps/code/build/query)
            elif activity_type == "process_system":
                if os_category == "windows" and activity_type in PROCESS_TEMPLATES:
                    rng = _get_rng()
                    process_name, command_line = rng.choice(PROCESS_TEMPLATES[activity_type])
                    process_name = process_name.replace("{username}", user.username)
                    command_line = self._parameterize_command_for_system(
                        rng,
                        command_line,
                        username=user.username,
                        system=system,
                    )
                    parent_pid = self._resolve_parent(system, user, time, logon_id, process_name)
                    pid = self.generate_process(
                        user,
                        system,
                        time,
                        logon_id,
                        process_name,
                        command_line,
                        parent_pid=parent_pid,
                    )
                    self._record_user_process(system, user, pid, process_name)
                    lifetime = _windows_foreground_lifetime(process_name, command_line)
                    if lifetime is not None:
                        self._generate_bounded_foreground_process_termination(
                            user=user,
                            system=system,
                            start_time=time,
                            pid=pid,
                            process_name=process_name,
                            logon_id=logon_id,
                            lifetime=lifetime,
                            rng=rng,
                        )
                elif os_category == "linux" and activity_type in PROCESS_TEMPLATES_LINUX:
                    rng = _get_rng()
                    process_name, command_line = rng.choice(PROCESS_TEMPLATES_LINUX[activity_type])
                    command_line = self._parameterize_command_for_system(
                        rng,
                        command_line,
                        username=user.username,
                        system=system,
                    )
                    command_line = _background_linux_shell_command_if_needed(command_line)
                    process_time = self._schedule_bash_history_time(
                        user, system, time, command_line
                    )
                    if process_time is None or not self._is_within_scenario_window(process_time):
                        return
                    parent_pid = self._resolve_parent(
                        system, user, process_time, logon_id, process_name
                    )
                    process_time = self._reserve_foreground_shell_time(
                        system=system,
                        username=user.username,
                        logon_id=logon_id,
                        parent_pid=parent_pid,
                        requested_time=process_time,
                        seed_text=command_line,
                    )
                    if not self._is_within_scenario_window(process_time):
                        return
                    pid = self.generate_process(
                        user,
                        system,
                        process_time,
                        logon_id,
                        process_name,
                        command_line,
                        parent_pid=parent_pid,
                        concurrency_group_id=self._bash_history_process_group_id(
                            user,
                            system,
                            process_time,
                            command_line,
                        ),
                    )
                    self._record_user_process(system, user, pid, process_name)
                    if active_session:
                        active_session.last_activity_time = process_time
                    self._emit_bash_command_event(user, system, process_time, command_line)
                    lifetime = _linux_foreground_lifetime(process_name, command_line)
                    if lifetime is not None:
                        running_proc = self.state_manager.get_process(system.hostname, pid)
                        actual_process_start = (
                            running_proc.start_time if running_proc is not None else process_time
                        )
                        termination_time = self._generate_bounded_foreground_process_termination(
                            user=user,
                            system=system,
                            start_time=actual_process_start,
                            pid=pid,
                            process_name=process_name,
                            logon_id=logon_id,
                            lifetime=lifetime,
                            rng=rng,
                        )
                        self._remember_foreground_shell_available(
                            system=system,
                            username=user.username,
                            logon_id=logon_id,
                            parent_pid=parent_pid,
                            termination_time=termination_time,
                            seed_text=command_line,
                        )

        # Connection activities
        elif activity_type in EXTERNAL_IPS:
            rng = _get_rng()
            conn_hostname = None  # Domain name for DNS/SNI consistency

            # Domain-first selection: pick a domain, resolve to its IP.
            # Uses pick_domain_and_ip() which maintains correct per-domain IP
            # pools and per-host deterministic selection (simulates DNS cache).
            from evidenceforge.generation.activity.dns_registry import (
                _domain_to_ip,
                generate_long_tail_domain,
                pick_domain_and_ip,
            )

            _tag_for_activity = {
                "connection_web": "web",
                "connection_saas": "saas",
                "connection_email": "email",
                "connection_git": "git",
                "connection_db": "internal",
            }
            tag = _tag_for_activity.get(activity_type, "web")

            if activity_type in ("connection_web", "connection_saas") and rng.random() < 0.30:
                # 30% chance: long-tail domain for CDN/SaaS/analytics diversity
                conn_hostname = generate_long_tail_domain(rng)
                dst_ip = _domain_to_ip(conn_hostname)
            else:
                # Known domain with correct per-domain IP pairing
                conn_hostname, dst_ip = pick_domain_and_ip(rng, tag, src_host=system.hostname)
                if dst_ip == system.ip:
                    return  # Skip self-connections

            # Set service and port based on activity type
            if activity_type in ("connection_web", "connection_saas"):
                service = rng.choice(["http", "ssl"])
                dst_port = 443 if service == "ssl" else 80
                if service == "ssl":
                    conn_hostname, dst_ip = self._pick_profiled_tls_destination(
                        rng,
                        src_ip=system.ip,
                        source_system=system,
                        purpose_tags=(tag,),
                    )
            elif activity_type == "connection_email":
                if getattr(getattr(self, "_scenario_environment", None), "email", None) is not None:
                    return
                service = "smtp"
                # Route through internal Exchange if detected (P1-15)
                exchange_ip = getattr(self, "_exchange_ip", None)
                if exchange_ip:
                    dst_ip = exchange_ip
                    dst_port = 25  # Internal SMTP relay uses port 25
                else:
                    dst_port = 587
            elif activity_type == "connection_git":
                service = "ssl"
                dst_port = 443
            elif activity_type == "connection_db":
                db_servers = getattr(self, "_db_servers", [])
                if db_servers:
                    db = _get_rng().choice(db_servers)
                    dst_ip = db["ip"]
                    service = db["service"]
                    dst_port = db["port"]
                    conn_hostname = None
                else:
                    # No DB servers detected from scenario; skip DB connection
                    return
            else:
                service = None
                dst_port = 443

            # Generate realistic traffic sizes
            orig_bytes = rng.randint(500, 5000)
            resp_bytes = rng.randint(1000, 50000)
            duration = rng.uniform(0.1, 5.0)

            self.generate_connection(
                src_ip=system.ip,
                dst_ip=dst_ip,
                time=time,
                dst_port=dst_port,
                service=service,
                emit_dns=True,
                duration=duration,
                orig_bytes=orig_bytes,
                resp_bytes=resp_bytes,
                hostname=conn_hostname,
            )

    def generate_machine_account_logon(
        self,
        hostname: str,
        machine_username: str,
        dc_hostname: str,
        source_ip: str,
        dc_ip: str,
        time: datetime,
        domain: str = "",
        exclusive_end: datetime | None = None,
    ) -> None:
        """Generate machine account logon event (4624 type 3) on the DC.

        Machine accounts (COMPUTERNAME$) authenticate to DCs constantly for
        GPO updates, Kerberos renewal, LDAP queries, etc. The event is logged
        on the DC, not on the source machine.
        """
        request = MachineAccountLogonRequest(
            hostname=hostname,
            machine_username=machine_username,
            dc_hostname=dc_hostname,
            source_ip=source_ip,
            dc_ip=dc_ip,
            time=time,
            domain=domain,
            exclusive_end=exclusive_end,
        )
        MachineAccountLogonActionBundle(self, request).execute()

    def _execute_machine_account_logon_bundle(
        self,
        request: MachineAccountLogonRequest,
    ) -> None:
        """Generate machine account logon event (4624 type 3) on the DC."""
        machine_username = request.machine_username
        dc_hostname = request.dc_hostname
        source_ip = request.source_ip
        dc_ip = request.dc_ip
        time = request.time
        domain = request.domain

        if request.exclusive_end is not None:
            latest_canonical_logoff = ensure_utc(time) + timedelta(seconds=30)
            remote_transport_headroom = timedelta(
                seconds=remote_auth_transport_max_duration_seconds(
                    source="machine_account_logon",
                    outcome="success",
                ),
            )
            endpoint_clock_headroom = self._source_timing_planner.endpoint_clock_positive_headroom(
                latest_canonical_logoff,
                "windows",
            )
            network_sensor_headroom = self._network_sensor_close_positive_headroom(
                canonical_time=ensure_utc(time) + remote_transport_headroom,
                src_ip=source_ip,
                dst_ip=dc_ip,
                protocol="tcp",
                conn_states=("SF",),
                payload_bytes=1,
            )
            completion_headroom = timedelta(
                seconds=machine_account_authentication_close_bound_seconds(
                    endpoint_clock_headroom_seconds=endpoint_clock_headroom.total_seconds(),
                    network_sensor_headroom_seconds=network_sensor_headroom.total_seconds(),
                ),
            )
            if ensure_utc(time) + completion_headroom >= ensure_utc(request.exclusive_end):
                return

        domain = domain or getattr(self, "_netbios_domain", "CORP")
        rng = _get_rng()
        logon_id = self.state_manager.preview_logon_id(dc_hostname, time)
        tgt_time, tgs_time = self._kerberos_ticket_times(
            time,
            rng,
            tgs_before_ms=(8, 65),
            tgt_before_tgs_ms=(35, 220),
        )
        kerberos_source_port = self._reserve_kerberos_source_port(
            source_ip,
            dc_hostname,
            tgt_time,
        )
        self.generate_kerberos_tgt(
            username=machine_username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=tgt_time,
            source_port=kerberos_source_port,
        )
        service, destination_port = rng.choices(
            [("ldap", 389), ("cifs", 445)],
            weights=[55, 45],
            k=1,
        )[0]
        service_name = f"{service}/{dc_hostname}"
        self.generate_kerberos_service_ticket(
            username=machine_username,
            service_name=service_name,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=tgs_time,
            source_port=kerberos_source_port,
        )
        target_system = self._ip_to_system.get(dc_ip)
        if target_system is None:
            target_system = System(
                hostname=dc_hostname,
                ip=dc_ip,
                os="Windows Server 2022",
                type="domain_controller",
            )
        service_source_port = self._allocate_ephemeral_port(
            source_ip,
            dc_ip,
            destination_port,
            "tcp",
            time,
            self._os_for_ip(source_ip),
        )
        remote_request = WindowsRemoteAuthenticationRequest(
            target_system=target_system,
            time=time,
            source_ip=source_ip,
            source_port=service_source_port,
            logon_type=3,
            auth_protocol="Kerberos",
            outcome="success",
            destination_port=destination_port,
            source_system=self._ip_to_system.get(source_ip),
            logon_id=logon_id,
            transport_role="target_service",
            source="machine_account_logon",
        )
        expected_session = self.state_manager.plan_session_materialization(
            logon_id=logon_id,
            username=machine_username,
            system=dc_hostname,
            logon_type=3,
            source_ip=source_ip,
            start_time=time,
            source_port=service_source_port,
            session_kind="network",
            logon_guid_required=False,
            lifecycle_group_id=remote_request.stable_id,
        )
        try:
            returned_session = self.state_manager.register_session(
                logon_id=logon_id,
                username=machine_username,
                system=dc_hostname,
                logon_type=3,
                source_ip=source_ip,
                start_time=time,
                source_port=service_source_port,
                session_kind="network",
                logon_guid_required=False,
                lifecycle_group_id=remote_request.stable_id,
            )
        except BaseException:
            # Registration can have committed its exact State plan before an
            # acknowledgement fault. Adopt only that already-planned identity;
            # a fail-before or foreign owner remains an error.
            returned_session = self.state_manager.get_session(logon_id)
            if (
                returned_session is None
                or self.state_manager.get_session_identity(logon_id) != expected_session.identity
            ):
                raise
        session = self.state_manager.get_session(logon_id)
        if (
            session is None
            or session is not returned_session
            or self.state_manager.get_session_identity(logon_id) != expected_session.identity
        ):
            raise StateError("Machine-account logon registered a different session identity")
        session_obj_id = session.ecar_object_id
        remote_authentication_plan = WindowsRemoteAuthenticationActionBundle(
            self,
            replace(remote_request, session_object_id=session_obj_id),
        ).execute()
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="machine_logon",
            dst_host=self._build_dc_host_context(dc_hostname),
            auth=AuthContext(
                username=machine_username,
                user_sid=self._get_sid(machine_username),
                logon_id=logon_id,
                logon_type=3,
                auth_package="Kerberos",
                source_ip=source_ip,
                source_port=service_source_port,
                logon_process="Kerberos",
                lm_package="-",
                logon_guid="{00000000-0000-0000-0000-000000000000}",
                subject_sid=self._get_sid("SYSTEM"),
                subject_username="SYSTEM",
                subject_domain="NT AUTHORITY",
                subject_logon_id="0x3e7",
            ),
            remote_auth=remote_authentication_plan,
            lifecycle=ActionLifecycleContext(
                group_id=remote_authentication_plan.stable_id,
                canonical_start=time,
                phase="start",
            ),
        )
        self.dispatcher.dispatch_builder(event)

        # Paired logoff for short-lived type 3 machine logon (1-30 seconds)
        logoff_delay = rng.uniform(1.0, 30.0)
        logoff_event = OccurrenceBuilder(
            timestamp=time + timedelta(seconds=logoff_delay),
            event_type="logoff",
            dst_host=self._build_dc_host_context(dc_hostname),
            auth=AuthContext(
                username=machine_username,
                user_sid=self._get_sid(machine_username),
                logon_id=logon_id,
                logon_type=3,
            ),
            lifecycle=ActionLifecycleContext(
                group_id=remote_authentication_plan.stable_id,
                canonical_start=time,
                phase="closure",
            ),
        )
        self.dispatcher.dispatch_builder(logoff_event)
        self.state_manager.end_session(logon_id, logoff_event.timestamp)

    def generate_kerberos_tgt(
        self,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        domain: str = "",
        source_port: int | None = None,
    ) -> None:
        """Generate Kerberos TGT request event (4768) on the DC."""
        request = KerberosTgtRequest(
            username=username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=time,
            domain=domain,
            source_port=source_port,
        )
        KerberosTgtActionBundle(self, request).execute()

    def _execute_kerberos_tgt_bundle(self, request: KerberosTgtRequest) -> None:
        """Generate Kerberos TGT request event (4768) on the DC."""
        from evidenceforge.events.contexts import KerberosContext

        username = request.username
        source_ip = request.source_ip
        dc_hostname = request.dc_hostname
        time = request.time
        domain = request.domain
        source_port = request.source_port

        # Kerberos realm is always the DNS FQDN in uppercase, never NetBIOS short name
        domain = domain or getattr(self, "_ad_domain", "corp.local").upper()
        rng = _get_rng()
        from evidenceforge.generation.activity.kerberos_realism import pick_tgt_success_fields

        tgt_fields = pick_tgt_success_fields(
            rng,
            domain.lower(),
            allow_no_preauth=self._kerberos_account_allows_no_preauth(username),
        )
        source_port = self._reserve_kerberos_source_port(
            source_ip,
            dc_hostname,
            time,
            source_port,
        )
        time = self._kerberos_source_time(
            time,
            event_type="kerberos_tgt",
            username=username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            source_port=source_port,
        )

        event = OccurrenceBuilder(
            timestamp=time,
            event_type="kerberos_tgt",
            dst_host=self._build_dc_host_context(dc_hostname),
            kerberos=KerberosContext(
                target_username=username,
                target_domain=domain,
                target_sid=self._get_sid(username),
                service_name="krbtgt",
                service_sid=self._get_sid("krbtgt"),
                ticket_options=tgt_fields["ticket_options"],
                encryption_type=tgt_fields["encryption_type"],
                pre_auth_type=tgt_fields["pre_auth_type"],
                cert_issuer_name=tgt_fields["cert_issuer_name"],
                cert_serial_number=tgt_fields["cert_serial_number"],
                cert_thumbprint=tgt_fields["cert_thumbprint"],
                source_ip=f"::ffff:{source_ip}",
                source_port=source_port,
            ),
        )

        self._dispatch_prepared_kerberos_audit(
            event,
            stable_id=request.stable_id,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            source_port=source_port,
        )
        self._remember_kerberos_tgt_cache(username, source_ip, dc_hostname, time, rng)

