    def _emit_new_credentials_logon(
        self,
        *,
        user: User,
        system: System,
        time: datetime,
        caller_logon_id: str,
        outbound_username: str,
        outbound_domain: str,
        lifecycle_group_id: str,
    ) -> str:
        """Emit a local Type 9 token clone for a modeled runas /netonly action."""

        if _get_os_category(system.os) != "windows":
            raise StateError("NewCredentials is only valid on Windows systems")
        caller_session = self.state_manager.get_session_at(caller_logon_id, time)
        if (
            caller_session is None
            or caller_session.system != system.hostname
            or caller_session.username != user.username
            or not windows_logon_can_own_desktop(caller_session.logon_type)
        ):
            raise StateError(
                "NewCredentials requires an active local interactive caller session on "
                f"{system.hostname}: caller_logon_id={caller_logon_id}"
            )

        self.state_manager.set_current_time(time)
        lifecycle_id = f"{lifecycle_group_id}:new_credentials"
        logon_id = self.state_manager.create_session(
            username=user.username,
            system=system.hostname,
            logon_type=9,
            source_ip="-",
            source_port=0,
            session_kind="new_credentials",
            lifecycle_group_id=lifecycle_id,
            parent_lifecycle_group_id=lifecycle_group_id,
        )
        session = self.state_manager.get_session(logon_id)
        session_id = session.session_id if session is not None else 0
        subject = self._account_subject_fields(user.username, system, caller_logon_id)
        outbound_account = outbound_username.split("\\")[-1].split("@", 1)[0]
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="logon",
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=user.username,
                full_name=user.full_name,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session_id,
                logon_type=9,
                auth_package="Negotiate",
                source_ip="-",
                source_port=0,
                logon_process="seclogo",
                lm_package="-",
                logon_guid="{00000000-0000-0000-0000-000000000000}",
                subject_sid=subject["sid"],
                subject_username=subject["username"],
                subject_domain=subject["domain"],
                subject_logon_id=subject["logon_id"],
                reporting_pid=self._get_system_pid(system.hostname, "lsass", 0x2E0),
                process_pid=self._get_system_pid(system.hostname, "svchost_local_system", 0x4C0),
                process_name=r"C:\Windows\System32\svchost.exe",
                outbound_username=outbound_account,
                outbound_domain=outbound_domain,
                cloned_from_logon_id=caller_logon_id,
                session_kind="new_credentials",
            ),
            lifecycle=ActionLifecycleContext(
                group_id=lifecycle_id,
                canonical_start=time,
                phase="start",
                parent_group_id=lifecycle_group_id,
            ),
        )
        self.dispatcher.dispatch_builder(event)
        return logon_id

    def _coerce_windows_explicit_credentials_subject(
        self,
        user: User,
        system: System,
        target_username: str,
    ) -> User:
        """Return a Windows-native subject for 4648 when the narrative actor is Unix-local."""
        if _get_os_category(system.os) != "windows":
            return user
        if user.username.lower() not in _LINUX_LOCAL_ACCOUNTS:
            return user

        candidate = target_username.split("\\")[-1].split("@", 1)[0]
        known_users = getattr(self, "_users_by_username", {})
        if candidate and candidate.lower() not in _LINUX_LOCAL_ACCOUNTS:
            if candidate in known_users:
                return known_users[candidate]
            if _USER_MODEL_USERNAME_RE.fullmatch(candidate):
                return User(
                    username=candidate,
                    full_name=candidate,
                    email=f"{candidate}@{self._valid_fallback_email_domain()}",
                )

        assigned_user = getattr(system, "assigned_user", "")
        if assigned_user:
            assigned = known_users.get(assigned_user)
            if assigned is not None:
                return assigned
            if _USER_MODEL_USERNAME_RE.fullmatch(assigned_user):
                return User(
                    username=assigned_user,
                    full_name=assigned_user,
                    email=f"{assigned_user}@{self._valid_fallback_email_domain()}",
                )
        return User(
            username="Administrator",
            full_name="Administrator",
            email=f"administrator@{self._valid_fallback_email_domain()}",
        )

    def _explicit_credentials_source_ip(
        self,
        system: System,
        target_server: str,
        source_ip: str = "",
    ) -> str:
        """Return source network metadata for explicit-credential use."""
        target = target_server.strip().lower()
        system_domain = getattr(system, "domain", "")
        local_names = {
            system.hostname.lower(),
            f"{system.hostname}.{system_domain}".lower() if system_domain else "",
            system.ip,
        }
        if target in {"", "-", "localhost", "127.0.0.1", "::1"}:
            return "-"
        target_host = target.split(".", 1)[0]
        if target in local_names or target_host == system.hostname.lower():
            return "-"

        explicit_source_ip = source_ip.strip()
        if explicit_source_ip in {"", "-"}:
            return system.ip

        normalized_source_ip = explicit_source_ip.removeprefix("::ffff:")
        if normalized_source_ip.lower() in local_names or explicit_source_ip.lower() in local_names:
            return "-"

        source_system = getattr(self, "_ip_to_system", {}).get(normalized_source_ip)
        if source_system is None:
            return "-"
        if (
            source_system.ip == system.ip
            or source_system.hostname.lower() == system.hostname.lower()
        ):
            return "-"
        return normalized_source_ip

    def _explicit_credentials_target_system(self, target_server: str) -> System | None:
        """Resolve a 4648 target server to a known scenario system when possible."""
        target = target_server.strip()
        if not target or target in {"-", "localhost", "127.0.0.1", "::1"}:
            return None
        normalized_target = target.removeprefix("::ffff:")
        systems_by_ip = getattr(self, "_ip_to_system", {})
        target_system = systems_by_ip.get(normalized_target)
        if target_system is not None:
            return target_system
        world_model = getattr(self, "_world_model", None)
        if world_model is None:
            return None
        hostname_key = normalized_target.split(".", 1)[0]
        return world_model.systems_by_hostname.get(normalized_target) or (
            world_model.systems_by_hostname.get(hostname_key) if hostname_key else None
        )

    def _ensure_explicit_credentials_subject_logon(
        self,
        user: User,
        system: System,
        time: datetime,
    ) -> str:
        """Return a visible subject session for a Windows 4648 event."""
        existing = self._get_user_interactive_logon_id(user.username, system.hostname, time)
        if existing != "0x0":
            return existing
        if user.username in _SYSTEM_ACCOUNT_LOGON_IDS:
            return _SYSTEM_ACCOUNT_LOGON_IDS[user.username]

        logon_time = time - timedelta(seconds=2)
        scenario_start = getattr(self, "_scenario_start_time", None)
        if scenario_start is not None:
            scenario_start = ensure_utc(scenario_start)
            if ensure_utc(logon_time) < scenario_start:
                logon_time = time - timedelta(milliseconds=500)
        return self.generate_logon(user, system, logon_time, logon_type=2, source_ip="-")

    def _explicit_credentials_target_domain(
        self,
        target_username: str,
        target_server: str,
        source_system: System,
    ) -> str:
        """Return a source-native TargetDomainName for explicit credentials."""
        if "\\" in target_username:
            return target_username.split("\\", 1)[0]
        if "@" in target_username:
            return target_username.rsplit("@", 1)[1].upper()

        netbios_domain = self._build_host_context(source_system).netbios_domain
        if target_username in _SYSTEM_ACCOUNT_LOGON_IDS:
            return "NT AUTHORITY"
        if target_username in getattr(self, "_users_by_username", {}):
            return netbios_domain
        if target_username in self.sid_registry and target_username.lower() not in {
            "root",
            "apache",
        }:
            return netbios_domain

        target_host = target_server.split(".", 1)[0].upper() if target_server else ""
        world_model = getattr(self, "_world_model", None)
        target_system = None
        if world_model is not None:
            target_system = world_model.systems_by_hostname.get(target_server) or (
                world_model.systems_by_hostname.get(target_server.split(".", 1)[0])
                if target_server
                else None
            )
        if target_system is not None and _get_os_category(target_system.os) != "windows":
            return target_host or netbios_domain
        if target_username.lower() in {"root", "apache"}:
            return target_host or "-"
        return netbios_domain

    def generate_workstation_lock(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> WorkstationLockResult:
        """Attempt a workstation lock transition and report its outcome."""
        request = WorkstationLockRequest(
            user=user,
            system=system,
            time=time,
            logon_id=logon_id,
        )
        return WorkstationLockActionBundle(self, request).execute()

    def _execute_workstation_lock_bundle(
        self,
        request: WorkstationLockRequest,
    ) -> WorkstationLockResult:
        """Generate event 4800 only when the workstation enters the locked state."""
        user = request.user
        system = request.system
        time = request.time
        logon_id = request.logon_id

        session = self.state_manager.get_session(logon_id)
        if (
            session is None
            or session.system != system.hostname
            or session.start_time > time
            or not _is_windows_workstation_session(session)
        ):
            return WorkstationLockResult(
                emitted=False,
                skipped_reason="no_eligible_interactive_session",
            )
        if not hasattr(self, "_last_workstation_lock_time"):
            self._last_workstation_lock_time = {}
        if self._locked_user_interactive_windows_session(user, system, time) is not None:
            return WorkstationLockResult(
                emitted=False,
                skipped_reason="workstation_already_locked",
            )
        lock_key = (system.hostname, user.username, logon_id)
        if lock_key in self._last_workstation_lock_time:
            return WorkstationLockResult(
                emitted=False,
                skipped_reason="workstation_already_locked",
            )
        self._last_workstation_lock_time[lock_key] = time
        session = self.state_manager.get_session(logon_id)
        if session is not None:
            session.last_activity_time = time
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="workstation_locked",
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=user.username,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session.session_id,
            ),
        )
        self.dispatcher.dispatch_builder(event)
        return WorkstationLockResult(emitted=True)

    def generate_workstation_unlock(
        self,
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> None:
        """Generate workstation unlock event (4801 + 4624 type 7)."""
        request = WorkstationUnlockRequest(
            user=user,
            system=system,
            time=time,
            logon_id=logon_id,
        )
        WorkstationUnlockActionBundle(self, request).execute()

    def _execute_workstation_unlock_bundle(self, request: WorkstationUnlockRequest) -> None:
        """Generate workstation unlock event (4801 + 4624 type 7)."""
        user = request.user
        system = request.system
        time = request.time
        logon_id = request.logon_id

        session = self.state_manager.get_session(logon_id)
        lock_times = getattr(self, "_last_workstation_lock_time", {})
        lock_key = (system.hostname, user.username, logon_id)
        lock_time = lock_times.get(lock_key)
        if lock_time is None:
            locked = self._locked_user_interactive_windows_session(user, system, time)
            if locked is not None:
                lock_time, session = locked
                logon_id = session.logon_id
                lock_key = (system.hostname, user.username, logon_id)
        if (
            session is None
            or session.system != system.hostname
            or session.start_time > time
            or not _is_windows_workstation_session(session)
        ):
            return
        reauth_gap = self._workstation_unlock_reauth_gap(user, system, time, logon_id)
        reauth_not_before = session.start_time
        if lock_time is not None:
            min_reauth_time = lock_time + timedelta(seconds=min_unlock_gap_seconds())
            reauth_not_before = max(reauth_not_before, min_reauth_time)
            self._last_workstation_lock_time.pop(lock_key, None)
        timing_graph = TemporalConstraintGraph()
        timing_graph.add_node(
            "reauth",
            time - reauth_gap,
            not_before=reauth_not_before,
        )
        timing_graph.add_node("unlock", time)
        timing_graph.constrain_after("unlock", "reauth", min_gap=reauth_gap)
        resolved_times = timing_graph.resolve()
        reauth_time = resolved_times["reauth"]
        unlock_time = resolved_times["unlock"]

        session = self.state_manager.get_session(logon_id)
        if session is not None:
            session.last_activity_time = unlock_time
        # Unlock is a re-authentication: Windows records the Type 7 4624 before
        # the workstation-unlocked audit event for the same terminal session.
        self.generate_logon(
            user=user,
            system=system,
            time=reauth_time,
            logon_type=7,
            source_ip="-",
            logon_id=logon_id,
        )
        event = OccurrenceBuilder(
            timestamp=unlock_time,
            event_type="workstation_unlocked",
            dst_host=self._build_host_context(system),
            auth=AuthContext(
                username=user.username,
                user_sid=self._get_sid(user.username),
                logon_id=logon_id,
                session_id=session.session_id,
            ),
        )
        self.dispatcher.dispatch_builder(event)

    @staticmethod
    def _workstation_unlock_reauth_gap(
        user: User,
        system: System,
        time: datetime,
        logon_id: str,
    ) -> timedelta:
        """Return source-native spacing from unlock re-auth to 4801 audit."""

        seed = _stable_seed(
            "workstation_unlock_reauth_gap:"
            f"{system.hostname}:{user.username}:{logon_id}:{time.isoformat()}"
        )
        return timedelta(milliseconds=80 + (seed % 571))

    def _resolve_windows_inbound_service_pid(
        self,
        system: System,
        dst_port: int,
        time: datetime,
    ) -> int:
        """Return a destination-local Windows service PID for inbound audit rows."""

        if _get_os_category(system.os) != "windows":
            return -1

        system_pids = getattr(self, "_system_pids", {}).get(system.hostname, {})
        for role in _WINDOWS_INBOUND_SERVICE_PID_CANDIDATES.get(dst_port, ()):
            pid = int(system_pids.get(role, -1) or -1)
            if pid > 0 and self._is_pid_active_at(system, pid, time):
                return pid
        return -1

    @staticmethod
    def _should_emit_windows_inbound_wfp(event: OccurrenceBuilder, target_system: System) -> bool:
        """Return whether a canonical connection should create target-side 5156 evidence."""

        net = event.network
        if net is None or net.responding_pid <= 0:
            return False
        if net.dst_ip == net.src_ip or net.dst_ip != target_system.ip:
            return False
        if event.firewall is not None and event.firewall.action == "deny":
            return False
        # Domain controllers collect WFP evidence selectively in ordinary baseline
        # traffic.  Explicit storyline bundles retain complete coverage so attack
        # evidence remains auditable, while baseline admission avoids one 5156 row
        # per permitted connection becoming a synthetic volume signature.
        roles = {str(role).lower() for role in (target_system.roles or [])}
        if "domain_controller" in roles and event.lifecycle is None:
            seed = _stable_seed(
                "baseline_dc_wfp:"
                f"{net.src_ip}:{net.src_port}:{net.dst_ip}:{net.dst_port}:"
                f"{net.protocol}:{event.timestamp.isoformat()}"
            )
            if seed % 100 >= 35:
                return False
        proto = net.protocol.lower()
        if proto == "tcp":
            if net.conn_state in {"S0", "REJ", "S1", "SH", "SHR", "OTH"}:
                return False
            history = net.history or ""
            if not net.conn_state and not history:
                return True
            return any(marker in history for marker in ("h", "a", "d", "r", "f"))
        if proto in {"udp", "icmp"}:
            return net.conn_state not in {"S0", "REJ", "OTH"}
        return False

    def generate_wfp_connection(
        self,
        system: System,
        time: datetime,
        network: NetworkTransactionPlan,
        pid: int = 4,
        application: str | None = None,
        parent_action_group_id: str | None = None,
    ) -> None:
        """Generate WFP connection permitted event (5156) on Windows host.

        Records the Windows Filtering Platform firewall allow decision.
        """
        from evidenceforge.events.contexts import ProcessContext

        process = None
        if pid > 0:
            running = self.state_manager.get_process(system.hostname, pid)
            if running is not None:
                process = ProcessContext(
                    pid=pid,
                    parent_pid=running.parent_pid,
                    image=running.image,
                    command_line=running.command_line,
                    username=running.username,
                    logon_id=running.logon_id,
                    start_time=running.start_time,
                    parent_start_time=self._lookup_parent_start_time(
                        system.hostname,
                        running.parent_pid,
                    ),
                )
        if process is None and application and pid <= 0:
            process = ProcessContext(
                pid=pid,
                parent_pid=0,
                image=application,
                command_line="",
                username="",
            )
        if process is None and pid > 0 and pid != 4:
            logger.debug(
                "Skipping WFP 5156 for unresolved process image: host=%s pid=%s",
                system.hostname,
                pid,
            )
            return
        if process is not None:
            time = self._clamp_after_visible_process_create(
                system,
                pid,
                time,
                "source.windows_wfp_connection",
            )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="wfp_connection",
            src_host=self._build_host_context(system),
            network=network,
            process=process,
            lifecycle=(
                ActionLifecycleContext(
                    group_id=network.stable_id,
                    canonical_start=time,
                    phase="dependent",
                    parent_group_id=parent_action_group_id,
                )
                if network.stable_id
                else None
            ),
        )
        self.dispatcher.dispatch_builder(event)

    def generate_rdp_session(
        self,
        user: User,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_system: Optional["System"] = None,
        source_pid: int = -1,
        source_port: int | None = None,
        logon_id: str | None = None,
        source_process_time: datetime | None = None,
        source_process_factory: RdpSourceProcessFactory | None = None,
        preserve_explicit_source: bool = False,
        session_end_plan: SessionEndPlan | None = None,
        ids_alerts: list[IdsAlertPlan] | None = None,
    ) -> str:
        """Generate RDP session: Zeek conn + 4624 type 10 + eCAR on target.

        Compound event ensuring network and host evidence are always paired.
        Returns Zeek UID.
        """
        uid, _ = self._execute_rdp_session_bundle(
            user=user,
            target_system=target_system,
            time=time,
            source_ip=source_ip,
            source_system=source_system,
            source_pid=source_pid,
            source_port=source_port,
            logon_id=logon_id,
            source_process_time=source_process_time,
            source_process_factory=source_process_factory,
            preserve_explicit_source=preserve_explicit_source,
            session_end_plan=session_end_plan,
            ids_alerts=ids_alerts,
        )
        return uid

    def _execute_rdp_session_bundle(
        self,
        user: User,
        target_system: System,
        time: datetime,
        source_ip: str,
        source_system: Optional["System"] = None,
        source_pid: int = -1,
        source_port: int | None = None,
        logon_id: str | None = None,
        source_process_time: datetime | None = None,
        source_process_factory: RdpSourceProcessFactory | None = None,
        preserve_explicit_source: bool = False,
        session_end_plan: SessionEndPlan | None = None,
        ids_alerts: list[IdsAlertPlan] | None = None,
    ) -> tuple[str, str]:
        """Execute the canonical RDP bundle and return transport and session IDs."""

        bundle = RdpSessionActionBundle(
            executor=self,
            request=RdpSessionRequest(
                user=user,
                target_system=target_system,
                time=time,
                source_ip=source_ip,
                source_system=source_system,
                source_pid=source_pid,
                source_port=source_port,
                source_process_time=source_process_time,
                logon_id=logon_id or "",
                preserve_explicit_source=preserve_explicit_source,
                session_end_plan=session_end_plan,
                ids_alerts=list(ids_alerts or []),
            ),
            source_process_factory=source_process_factory,
        )
        uid = bundle.execute()
        return uid, bundle.rendered_logon_id

    def _resolve_direct_rdp_source_system(
        self,
        user: User,
        target_system: System,
        source_ip: str,
        rng: random.Random,
    ) -> System | None:
        """Return a modeled Windows source host for direct Type 10 compatibility calls."""

        source_system = self._ip_to_system.get(source_ip)
        if (
            source_system is not None
            and source_system.ip != target_system.ip
            and _get_os_category(source_system.os) == "windows"
        ):
            return source_system

        candidates = sorted(
            {
                system.hostname: system
                for system in self._ip_to_system.values()
                if system.ip != target_system.ip and _get_os_category(system.os) == "windows"
            }.values(),
            key=lambda system: system.hostname,
        )
        workstations = [
            system
            for system in candidates
            if (system.type or "workstation").lower() == "workstation"
        ]
        preferred = [
            system for system in workstations or candidates if system.assigned_user == user.username
        ]
        return rng.choice(preferred or workstations or candidates) if candidates else None

    def _direct_rdp_source_process_factory(
        self,
        rng: random.Random,
    ) -> RdpSourceProcessFactory:
        """Return a source-process factory for direct RDP compatibility generation."""

        def _factory(
            *,
            user: User,
            source_system: System,
            target_system: System,
            time: datetime,
        ) -> int:
            source_session = self._active_user_interactive_windows_session(
                user,
                source_system,
                time,
            )
            if source_session is None:
                logon_time = time - timedelta(seconds=rng.uniform(30.0, 180.0))
                logon_id = self.generate_logon(
                    user,
                    source_system,
                    logon_time,
                    logon_type=2,
                    reuse_required_at=time,
                )
                source_session = self.state_manager.get_session(logon_id)
            if source_session is None:
                return -1

            parent_pid = source_session.explorer_pid or source_session.process_tree_root
            if parent_pid is None:
                sys_pids = getattr(self, "_system_pids", {}).get(source_system.hostname, {})
                parent_pid = sys_pids.get(
                    "explorer",
                    sys_pids.get("winlogon", sys_pids.get("services", 4)),
                )

            self.state_manager.set_current_time(time)
            pid = self.generate_process(
                user=user,
                system=source_system,
                time=time,
                logon_id=source_session.logon_id,
                process_name=r"C:\Windows\System32\mstsc.exe",
                command_line=f"mstsc.exe /v:{target_system.hostname}",
                parent_pid=parent_pid,
            )
            self._record_user_process(
                source_system,
                user,
                pid,
                r"C:\Windows\System32\mstsc.exe",
            )
            return pid

        return _factory

    def _coerce_windows_rdp_user_from_existing_session(
        self,
        user: User,
        target_system: System,
        source_ip: str,
    ) -> User:
        """Use a recent successful Windows credential instead of a Unix local actor."""
        if _get_os_category(target_system.os) != "windows":
            return user
        if user.username.lower() not in _LINUX_LOCAL_ACCOUNTS:
            return user
        sessions = [
            session
            for session in self.state_manager.get_sessions_on_system(target_system.hostname)
            if session.source_ip == source_ip
            and session.username.lower() not in _LINUX_LOCAL_ACCOUNTS
            and session.username not in _SYSTEM_ACCOUNT_LOGON_IDS
        ]
        if not sessions:
            return user
        selected = max(sessions, key=lambda session: session.start_time)
        known_users = getattr(self, "_users_by_username", {})
        if selected.username in known_users:
            return known_users[selected.username]
        ad_domain = self._valid_fallback_email_domain()
        return User(
            username=selected.username,
            full_name=selected.username,
            email=f"{selected.username}@{ad_domain}",
        )

    def _valid_fallback_email_domain(self) -> str:
        """Return a safe domain for synthetic fallback users."""
        ad_domain = str(getattr(self, "_ad_domain", "corp.local")).strip().lower()
        allowed = set("abcdefghijklmnopqrstuvwxyz0123456789.-")
        labels = ad_domain.split(".")
        if (
            len(labels) >= 2
            and all(labels)
            and all(
                set(label) <= allowed and not label.startswith("-") and not label.endswith("-")
                for label in labels
            )
            and labels[-1].isalpha()
            and len(labels[-1]) >= 2
        ):
            return ad_domain
        return "corp.local"

    @staticmethod
    def _reconcile_generator_cleanup(
        primary: BaseException,
        label: str,
        cleanup: Callable[[], object],
    ) -> bool:
        """Run one idempotent cleanup twice at most without masking its primary."""

        failures: list[BaseException] = []
        for _attempt in range(2):
            try:
                cleanup()
                return True
            except BaseException as failure:
                failures.append(failure)
        for failure in failures:
            try:
                primary.add_note(
                    f"Generator {label} cleanup also failed with "
                    f"{type(failure).__module__}.{type(failure).__qualname__}"
                )
            except BaseException:
                continue
        return False

    def generate_service_logon(
        self,
        system: System,
        time: datetime,
        service_account: str = "SYSTEM",
    ) -> str:
        """Generate a service logon (type 5) for system accounts.

        Unlike generate_logon(), does not require a User object.
        Emits 4624 (type 5) + 4672 (special privileges) via normal pipeline.
        Built-in service principals retain their Windows well-known authentication IDs;
        named service accounts receive ordinary allocated session IDs.
        """
        request = ServiceLogonRequest(
            system=system,
            time=time,
            service_account=service_account,
        )
        return ServiceLogonActionBundle(self, request).execute()

    def _execute_service_logon_bundle(self, request: ServiceLogonRequest) -> str:
        """Generate a service logon (type 5) for system accounts."""
        service_account = request.service_account
        normalized_account = service_account.upper()
        builtin_account = (
            normalized_account if normalized_account in _SYSTEM_ACCOUNT_LOGON_IDS else None
        )
        event_account = builtin_account or service_account
        sid = _SYSTEM_ACCOUNT_SIDS.get(event_account)
        stable_id = request.stable_id
        sid_reservation: _SidReservation | None = None
        if sid is None:
            sid_reservation, sid = self._reserve_sid(service_account)
        try:
            return self._execute_service_logon_projection(
                request,
                stable_id=stable_id,
                sid=sid,
                sid_reservation=sid_reservation,
            )
        except BaseException as primary:
            if sid_reservation is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "SID reservation",
                    lambda: self._cancel_sid_reservation(sid_reservation),
                )
            raise

    def _execute_service_logon_projection(
        self,
        request: ServiceLogonRequest,
        *,
        stable_id: str,
        sid: str,
        sid_reservation: _SidReservation | None,
    ) -> str:
        """Prepare and publish one fully frozen Type-5 projection."""

        system = request.system
        time = request.time
        service_account = request.service_account
        normalized_account = service_account.upper()
        builtin_account = (
            normalized_account if normalized_account in _SYSTEM_ACCOUNT_LOGON_IDS else None
        )
        event_account = builtin_account or service_account
        logon_id = _SYSTEM_ACCOUNT_LOGON_IDS.get(normalized_account, "")
        session_plan = None
        state_plan = None
        audit_entry = None
        if not logon_id:
            state_builder = self.state_manager.begin_action_cohort_materialization()
            session_plan = state_builder.plan_session(
                username=service_account,
                system=system.hostname,
                logon_type=5,
                source_ip="-",
                start_time=time,
                session_kind="service",
                logon_guid_required=False,
                lifecycle_group_id=stable_id,
            )
            state_plan = state_builder.seal()
            logon_id = session_plan.identity.logon_id
            from evidenceforge.generation.actions.command_effects import (
                ExecutionEffectAuditCohortEntry,
            )

            audit_plan = ExecutionEffectPlan(
                ActionAnchor(
                    family="service_logon",
                    stable_id=stable_id,
                    source=request.source,
                ),
                (),
            )
            audit_entry = ExecutionEffectAuditCohortEntry(
                audit_plan,
                audit_plan.reconcile(()),
            )
        host = self._build_host_context(system)
        reporting_pid = self._get_system_pid(system.hostname, "lsass", 0x2E0)
        subject = self._account_subject_fields("SYSTEM", system, logon_id="0x3e7")
        # The Windows built-in token LUID is durable, but each emitted Type 5
        # authentication is a distinct occurrence. Preserve the native LUID in
        # AuthContext while giving normalized session consumers an occurrence
        # identity that cannot LOGIN repeatedly as one lifecycle object.
        builtin_lifecycle_group_id = stable_uuid(
            "windows-built-in-service-authentication-occurrence",
            system.hostname,
            logon_id,
            stable_id,
        )
        builtin_authentication_identity = (
            EntityIdentity(
                hostname=system.hostname,
                object_id=stable_uuid(
                    "windows-built-in-service-authentication-object",
                    system.hostname,
                    logon_id,
                    stable_id,
                ),
                kind="authentication_occurrence",
                semantic_key=stable_id,
            )
            if normalized_account in _SYSTEM_ACCOUNT_LOGON_IDS
            else None
        )

        event = OccurrenceBuilder(
            timestamp=time,
            event_type="logon",
            dst_host=host,
            auth=AuthContext(
                username=event_account,
                user_sid=sid,
                logon_id=logon_id,
                logon_type=5,
                auth_package="Negotiate",
                source_ip="-",
                source_port=0,
                elevated=True,
                logon_process="Advapi",
                lm_package="-",
                logon_guid="{00000000-0000-0000-0000-000000000000}",
                subject_sid=subject["sid"],
                subject_username=subject["username"],
                subject_domain=subject["domain"],
                subject_logon_id=subject["logon_id"],
                reporting_pid=reporting_pid,
            ),
            lifecycle=ActionLifecycleContext(
                group_id=(
                    builtin_lifecycle_group_id
                    if builtin_authentication_identity is not None
                    else stable_id
                ),
                canonical_start=time,
                phase="start",
            ),
            identity_plan=(
                EventIdentityPlan(
                    subject=builtin_authentication_identity,
                )
                if builtin_authentication_identity is not None
                else EventIdentityPlan(
                    subject=session_plan.identity,
                    session=session_plan.identity,
                )
            ),
        )

        carrier: PreparedActionCohortProjection | None = None
        prepared: PreparedDispatch | None = None
        timing_preparation: SourceTimingPreparation | None = None
        try:
            with self.dispatcher.source_timing_planner.prepared_planning() as timing_preparation:
                carrier = self.dispatcher.prepare_action_cohort_projection(
                    event,
                    source_timing_preparation=timing_preparation,
                )
            occurrence_id = self.dispatcher.action_cohort_projection_occurrence(
                carrier
            ).occurrence_id
            if state_plan is not None:
                prepared = self.dispatcher.bind_action_cohort_projection(
                    carrier,
                    state_plan=state_plan,
                )
        except BaseException as primary:
            if carrier is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "projection carrier",
                    lambda: self.dispatcher.cancel_prepared_action_cohort_projection(carrier),
                )
            self._reconcile_generator_cleanup(
                primary,
                "orphan projection",
                self.dispatcher.prune_prepared_action_cohort_projections,
            )
            if timing_preparation is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "source timing",
                    timing_preparation.cancel,
                )
            raise

        if state_plan is None:
            try:
                result = self.dispatcher.publish_state_neutral_exact_projection(carrier)
            except BaseException as error:
                receipt = None
                attached_result = None
                try:
                    attributes = object.__getattribute__(error, "__dict__")
                    receipt = (
                        attributes.get("state_neutral_projection_receipt")
                        if type(attributes) is dict
                        else None
                    )
                    attached_result = (
                        attributes.get("state_neutral_projection_result")
                        if type(attributes) is dict
                        else None
                    )
                    result_type = getattr(
                        dispatcher_types,
                        "StateNeutralProjectionPublicationResult",
                        None,
                    )
                    authentic = (
                        receipt is not None
                        and result_type is not None
                        and type(attached_result) is result_type
                        and attached_result.receipt is receipt
                        and self.dispatcher.authenticates_state_neutral_projection_publication_receipt(
                            receipt
                        )
                        is True
                        and receipt.occurrence_ids == (occurrence_id,)
                    )
                except BaseException:
                    authentic = False
                if not authentic:
                    self._reconcile_generator_cleanup(
                        error,
                        "state-neutral carrier",
                        lambda: self.dispatcher.cancel_prepared_action_cohort_projection(carrier),
                    )
                    self._reconcile_generator_cleanup(
                        error,
                        "state-neutral orphan projection",
                        self.dispatcher.prune_prepared_action_cohort_projections,
                    )
                    if timing_preparation is not None:
                        self._reconcile_generator_cleanup(
                            error,
                            "state-neutral source timing",
                            timing_preparation.cancel,
                        )
                    raise
                result = self.dispatcher.resume_state_neutral_exact_projection(receipt)
                if result is not attached_result:
                    raise StateError(
                        "Built-in service-logon recovery returned a different publication result"
                    ) from error
                self._validate_state_neutral_service_logon_result(
                    result,
                    occurrence_id=occurrence_id,
                    expected_receipt=receipt,
                )
            else:
                self._validate_state_neutral_service_logon_result(
                    result,
                    occurrence_id=occurrence_id,
                )
            return logon_id

        if session_plan is None:  # pragma: no cover - construction invariant
            raise StateError("Named service-logon State plan lost its session member")
        if audit_entry is None:  # pragma: no cover - construction invariant
            raise StateError("Named service-logon State plan lost its audit member")
        if prepared is None:  # pragma: no cover - construction invariant
            raise StateError("Named service-logon projection lost its prepared dispatch")
        try:
            batch = self.dispatcher.prepare_action_cohort_batch(
                stable_id,
                state_plan,
                (prepared,),
                (audit_entry,),
                (),
                (),
                owned_effect_plans=(),
                exact_projection=True,
            )
        except BaseException as primary:
            self._reconcile_generator_cleanup(
                primary,
                "orphan action-cohort batch",
                self.dispatcher.prune_prepared_action_cohort_batches,
            )
            if timing_preparation is not None:
                self._reconcile_generator_cleanup(
                    primary,
                    "pre-batch source timing",
                    timing_preparation.cancel,
                )
            self._reconcile_generator_cleanup(
                primary,
                "post-batch orphan projection",
                self.dispatcher.prune_prepared_action_cohort_projections,
            )
            raise
        try:
            result = self.dispatcher.publish_prepared_action_cohort_batch(batch)
        except BaseException as error:
            receipt = None
            attached_result = None
            try:
                attributes = object.__getattribute__(error, "__dict__")
                receipt = (
                    attributes.get("action_cohort_receipt") if type(attributes) is dict else None
                )
                attached_result = (
                    attributes.get("action_cohort_result") if type(attributes) is dict else None
                )
                authentic = (
                    receipt is not None
                    and type(attached_result) is ActionCohortPublicationResult
                    and attached_result.receipt is receipt
                    and self.dispatcher.authenticates_action_cohort_publication_receipt(receipt)
                    is True
                    and receipt.occurrence_ids == (occurrence_id,)
                    and receipt.root_action_id == stable_id
                    and receipt.state_semantic_id == state_plan.semantic_id
                )
            except BaseException:
                authentic = False
            if not authentic:
                self._reconcile_generator_cleanup(
                    error,
                    "action-cohort batch",
                    lambda: self.dispatcher.cancel_prepared_action_cohort_batch(batch),
                )
                self._reconcile_generator_cleanup(
                    error,
                    "orphan action-cohort batch",
                    self.dispatcher.prune_prepared_action_cohort_batches,
                )
                raise
            try:
                result = self.dispatcher.resume_action_cohort_projection(receipt)
            except BaseException as resume_error:
                if sid_reservation is None:  # pragma: no cover - named invariant
                    raise StateError(
                        "Named service-logon recovery lost its SID reservation"
                    ) from resume_error
                # The authenticated receipt remains dispatcher-owned and drainable. Install the
                # exact reserved binding before allowing that pending canonical work to escape.
                self._commit_sid_reservation(sid_reservation)
                raise
            if result is not attached_result:
                raise StateError(
                    "Named service-logon recovery returned a different publication result"
                ) from error
            self._validate_named_service_logon_result(
                result,
                occurrence_id=occurrence_id,
                expected_receipt=receipt,
                expected_root_action_id=stable_id,
                expected_state_semantic_id=state_plan.semantic_id,
            )
        else:
            self._validate_named_service_logon_result(
                result,
                occurrence_id=occurrence_id,
                expected_root_action_id=stable_id,
                expected_state_semantic_id=state_plan.semantic_id,
            )
        if self.state_manager.get_session_identity(logon_id) != session_plan.identity:
            raise StateError("Named service-logon cohort returned an invalid session identity")
        if sid_reservation is None:  # pragma: no cover - named invariant
            raise StateError("Named service-logon projection lost its SID reservation")
        if self._commit_sid_reservation(sid_reservation) != sid:
            raise StateError("Named service-logon committed a different reserved SID")
        return logon_id

    def _validate_state_neutral_service_logon_result(
        self,
        result: object,
        *,
        occurrence_id: str,
        expected_receipt: object | None = None,
    ) -> None:
        """Validate one terminal state-neutral exact projection result."""

        result_type = getattr(
            dispatcher_types,
            "StateNeutralProjectionPublicationResult",
            None,
        )
        if result_type is None or type(result) is not result_type:
            raise StateError("Built-in service-logon projection returned the wrong result type")
        receipt = result.receipt
        projection = result.projection
        try:
            authentic = (
                expected_receipt is None or receipt is expected_receipt
            ) and self.dispatcher.authenticates_state_neutral_projection_publication_receipt(
                receipt
            ) is True
            receipt_matches = authentic and receipt.occurrence_ids == (occurrence_id,)
        except BaseException:
            receipt_matches = False
        if (
            not receipt_matches
            or type(projection) is not ActionCohortProjectionOutcome
            or projection.occurrence_id != occurrence_id
            or projection.status != "succeeded"
            or projection.error is not None
        ):
            raise StateError("Built-in service-logon projection returned invalid terminal proof")

    def _validate_named_service_logon_result(
        self,
        result: object,
        *,
        occurrence_id: str,
        expected_receipt: object | None = None,
        expected_root_action_id: str,
        expected_state_semantic_id: str,
    ) -> None:
        """Validate one terminal named Type-5 exact cohort result."""

        if type(result) is not ActionCohortPublicationResult:
            raise StateError("Named service-logon projection returned the wrong result type")
        receipt = result.receipt
        projections = result.projections
        try:
            authentic = (
                expected_receipt is None or receipt is expected_receipt
            ) and self.dispatcher.authenticates_action_cohort_publication_receipt(receipt) is True
            receipt_matches = (
                authentic
                and receipt.occurrence_ids == (occurrence_id,)
                and receipt.root_action_id == expected_root_action_id
                and receipt.state_semantic_id == expected_state_semantic_id
            )
        except BaseException:
            receipt_matches = False
        if (
            not receipt_matches
            or type(projections) is not tuple
            or len(projections) != 1
            or type(projections[0]) is not ActionCohortProjectionOutcome
            or projections[0].occurrence_id != occurrence_id
            or projections[0].status != "succeeded"
            or projections[0].error is not None
        ):
            raise StateError("Named service-logon projection returned invalid terminal proof")

    def generate_kerberos_preauth_failed(
        self,
        username: str,
        source_ip: str,
        dc_hostname: str,
        time: datetime,
        status: str = "0x18",
        source_port: int | None = None,
        emit_connection: bool = False,
    ) -> None:
        """Generate Kerberos pre-authentication failed event (4771) on DC."""
        request = KerberosPreauthFailureRequest(
            username=username,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            time=time,
            status=status,
            source_port=source_port,
            emit_connection=emit_connection,
        )
        KerberosPreauthFailureActionBundle(self, request).execute()

    def _execute_kerberos_preauth_failure_bundle(
        self,
        request: KerberosPreauthFailureRequest,
    ) -> None:
        """Generate Kerberos pre-authentication failed event (4771) on DC."""
        username = request.username
        source_ip = request.source_ip
        dc_hostname = request.dc_hostname
        time = request.time
        status = request.status
        source_port = request.source_port
        emit_connection = request.emit_connection

        rng = _get_rng()
        from evidenceforge.generation.activity.kerberos_realism import pick_tgt_failure_fields

        failure_fields = pick_tgt_failure_fields(rng, status)
        dc_host = self._build_dc_host_context(dc_hostname)
        reporting_pid = self._get_system_pid(dc_hostname, "lsass", 0x2E0)
        has_source_ip = source_ip not in {"", "-"}
        normalized_source_ip = (
            f"::ffff:{source_ip}" if has_source_ip and ":" not in source_ip else source_ip
        )
        source_port = (
            self._reserve_kerberos_source_port(source_ip, dc_hostname, time, source_port)
            if has_source_ip
            else 0
        )
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="kerberos_preauth_failed",
            dst_host=dc_host,
            kerberos=KerberosContext(
                target_username=username,
                target_domain=getattr(self, "_ad_domain", "corp.local").upper(),
                target_sid=self._get_sid(username),
                service_name="krbtgt",
                ticket_options=failure_fields["ticket_options"],
                ticket_status=status,
                pre_auth_type=failure_fields["pre_auth_type"],
                source_ip=normalized_source_ip or "-",
                source_port=source_port,
                reporting_pid=reporting_pid,
            ),
        )
        self._dispatch_prepared_kerberos_audit(
            event,
            stable_id=request.stable_id,
            source_ip=source_ip,
            dc_hostname=dc_hostname,
            source_port=source_port,
        )

        if not emit_connection or not has_source_ip:
            return
        dc_system = self._dc_system_for_hostname(dc_hostname)
        dc_ip = str(getattr(dc_system, "ip", "") or "")
        if not dc_ip:
            return
        source_system = getattr(self, "_ip_to_system", {}).get(source_ip)
        self.generate_connection(
            src_ip=source_ip,
            dst_ip=dc_ip,
            time=time,
            dst_port=88,
            proto="tcp",
            service="kerberos",
            duration=rng.uniform(0.001, 0.04),
            orig_bytes=rng.randint(180, 900),
            resp_bytes=rng.randint(80, 500),
            src_port=source_port,
            source_system=source_system,
            conn_state=rng.choices(["SF", "RSTR"], weights=[82, 18], k=1)[0],
            emit_dns=False,
        )

    def _get_user_logon_id(
        self,
        username: str,
        hostname: str,
        at_time: datetime | None = None,
    ) -> str:
        """Look up the user's active session LogonID on the given host.

        Returns the session LogonID if found. Well-known service identities use
        their canonical logon IDs. Human/domain accounts without an active
        session fall back to 0x0 rather than SYSTEM's 0x3e7.
        """
        canonical_logon_ids = {
            "SYSTEM": "0x3e7",
            "LOCAL SERVICE": "0x3e5",
            "NETWORK SERVICE": "0x3e4",
        }
        if username in canonical_logon_ids:
            return canonical_logon_ids[username]

        sessions = (
            self.state_manager.get_sessions_for_user_at(username, at_time)
            if at_time is not None
            else self.state_manager.get_sessions_for_user(username)
        )
        if sessions:
            host_sessions = [s for s in sessions if s.system == hostname]
            active = max(host_sessions, key=lambda s: s.start_time) if host_sessions else None
            if active:
                return active.logon_id
        return "0x0"

    def _get_user_interactive_logon_id(
        self,
        username: str,
        hostname: str,
        at_time: datetime,
    ) -> str:
        """Return the newest active interactive Windows session for a human caller.

        Explicit-credential tools are launched in a desktop or remote-interactive
        token. A Type 3 network authentication can authorize remote resource access,
        but it cannot own an Explorer process tree or become a 4648 caller session.
        """
        sessions = self.state_manager.get_sessions_for_user_at(username, at_time)
        candidates = [
            session
            for session in sessions
            if session.system == hostname
            and session.logon_type in {2, 10, 11}
            and session.session_kind not in {"network", "service"}
        ]
        if not candidates:
            return "0x0"
        return max(candidates, key=lambda session: ensure_utc(session.start_time)).logon_id

    def _get_subject_logon_id(
        self,
        username: str,
        hostname: str,
        at_time: datetime | None = None,
    ) -> str:
        """Look up the visible subject session, including service-account sessions."""
        sessions = (
            self.state_manager.get_sessions_for_user_at(username, at_time)
            if at_time is not None
            else self.state_manager.get_sessions_for_user(username)
        )
        if sessions:
            host_sessions = [s for s in sessions if s.system == hostname]
            active = max(host_sessions, key=lambda s: s.start_time) if host_sessions else None
            if active:
                return active.logon_id
        return self._get_user_logon_id(username, hostname, at_time)

    def _ensure_account_management_subject_logon(
        self,
        actor: User,
        system: System,
        time: datetime,
    ) -> str:
        """Return an active subject LogonID for account-management audit events."""
        existing = self._get_user_logon_id(actor.username, system.hostname, time)
        if existing != "0x0":
            return existing

        source_ip = system.ip
        world_model = getattr(self, "_world_model", None)
        primary_system_name = getattr(actor, "primary_system", None)
        if world_model is not None and primary_system_name:
            primary_system = world_model.systems_by_hostname.get(primary_system_name)
            if primary_system is not None:
                source_ip = primary_system.ip

        logon_time = time - timedelta(milliseconds=500)
        return self.generate_logon(
            actor,
            system,
            logon_time,
            logon_type=3 if source_ip != system.ip else 2,
            source_ip=source_ip,
        )

    def generate_log_cleared(
        self,
        user: User,
        system: System,
        time: datetime,
        from_storyline: bool = False,
        subject_logon_id: str | None = None,
    ) -> None:
        """Generate security log cleared event (1102) on target system."""
        request = LogClearedRequest(
            user=user,
            system=system,
            time=time,
            from_storyline=from_storyline,
            subject_logon_id=subject_logon_id,
        )
        LogClearedActionBundle(self, request).execute()

    def _execute_log_cleared_bundle(self, request: LogClearedRequest) -> None:
        """Generate security log cleared event (1102) on target system."""
        user = request.user
        system = request.system
        time = request.time
        from_storyline = request.from_storyline
        subject_logon_id = request.subject_logon_id

        if user.username in _SYSTEM_ACCOUNT_LOGON_IDS:
            subject_logon_id = _SYSTEM_ACCOUNT_LOGON_IDS[user.username]
        subject_logon_id = subject_logon_id or self._get_subject_logon_id(
            user.username, system.hostname, time
        )
        subject = self._account_subject_fields(user.username, system, logon_id=subject_logon_id)
        event = OccurrenceBuilder(
            timestamp=time,
            event_type="log_cleared",
            src_host=self._build_host_context(system),
            auth=AuthContext(
                username=user.username,
                subject_sid=subject["sid"],
                subject_username=subject["username"],
                subject_domain=subject["domain"],
                subject_logon_id=subject["logon_id"],
            ),
            storyline_origin=from_storyline,
        )
        self.dispatcher.dispatch_builder(event)

